COLLDATA("muslim","ur",[[3569,"ابن جریج نے ہمیں خبر دی ، کہا : ہمیں ابن ابی ملیکہ نے بتایا ، انہیں قاسم بن محمد بن ابی بکر نے خبر دی ، انہیں سیدہ عائشہ رضی اللہ عنہا نے بتایا کہ سہلہ بنت سہیل بن عمرو رضی اللہ عنہا نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور کہا : اللہ کے رسول! سالم ۔ ۔ ( انہوں نے ) سالم مولیٰ ابی حذیفہ رضی اللہ عنہ کے بارے میں ( کہا : ) ۔ ۔ ہمارے ساتھ ہمارے گھر میں رہتا ہے ۔ وہ مردوں کی حد بلوغٹ کو پہنچ چکا ہے اور وہ ( سب کچھ ) جاننے لگا ہے جو مرد جانتے ہیں ۔ آپ نے فرمایا : \" تم اسے دودھ پلا دو تو تم اس پر حرام ہو جاؤ گی ۔ \" ( گویا یہ حکم صرف سیدنا سہلہ کے لیے تھا ۔ ) ( ابن ابی ملیکہ نے ) کہا : میں سال بھر یا اس کے قریب ٹھہرا ، میں نے یہ حدیث بیان نہ کی ، میں اس ( کو بیان کرنے ) سے ڈرتا رہا ، پھر میں قاسم سے ملا تو میں نے انہیں کہا : آپ نے مجھے ایک حدیث سنائی تھی ، جو میں نے اس کے بعد کبھی بیان نہیں کی ، انہوں نے پوچھا : وہ کون سی حدیث ہے؟ میں نے انہیں بتائی ، انہوں نے کہا : اسے میرے حوالے سے بیان کرو کہ سیدہ عائشہ رضی اللہ عنہا نے مجھے اس کی خبر دی تھی","",{"u2":"ابن جریج نے ہمیں خبر دی، کہا: ہمیں ابن ابی ملیکہ نے بتایا، انہیں قاسم بن محمد بن ابی بکر نے خبر دی، انہیں سیدہ عائشہ رضی اللہ عنہا نے بتایا کہ سہلہ بنت سہیل بن عمرو رضی اللہ عنہا نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور کہا: اللہ کے رسول! سالم۔۔ (انہوں نے) سالم مولیٰ ابی حذیفہ رضی اللہ عنہ کے بارے میں (کہا:)۔۔ ہمارے ساتھ ہمارے گھر میں رہتا ہے۔ وہ مردوں کی حد بلوغٹ کو پہنچ چکا ہے اور وہ (سب کچھ) جاننے لگا ہے جو مرد جانتے ہیں۔ آپ نے فرمایا: \"تم اسے دودھ پلا دو تو تم اس پر حرام ہو جاؤ گی۔\" (گویا یہ حکم صرف حضرت سہلہ کے لیے تھا۔) (ابن ابی ملیکہ نے) کہا: میں سال بھر یا اس کے قریب ٹھہرا، میں نے یہ حدیث بیان نہ کی، میں اس (کو بیان کرنے) سے ڈرتا رہا، پھر میں قاسم سے ملا تو میں نے انہیں کہا: آپ نے مجھے ایک حدیث سنائی تھی، جو میں نے اس کے بعد کبھی بیان نہیں کی، انہوں نے پوچھا: وہ کون سی حدیث ہے؟ میں نے انہیں بتائی، انہوں نے کہا: اسے میرے حوالے سے بیان کرو کہ سیدہ عائشہ رضی اللہ عنہا نے مجھے اس کی خبر دی تھی"}],[3570,"شعبہ نے حُمَید بن نافع سے حدیث بیان کی ، انہوں نے زینب بنت ام سلمہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : سیدہ ام سلمہ رضی اللہ عنہا نے سیدہ عائشہ رضی اللہ عنہا سے کہا : آپ کے پاس ( گھر میں ) ایک قریب البلوغت لڑکا آتا ہے جسے میں پسند نہیں کرتی کہ وہ میرے پاس آئے ۔ سیدہ عائشہ رضی اللہ عنہا نے جواب دیا : کیا تمہارے لیے رسول اللہ صلی اللہ علیہ وسلم ( کی زندگی ) میں نمونہ نہیں ہے؟ انہوں نے ( آگے ) کہا : ابوحذیفہ رضی اللہ عنہ کی بیوی نے عرض کی تھی : اے اللہ کے رسول! سالم میرے سامنے آتا ہے اور ( اب ) وہ مرد ہے ، اور اس وجہ سے ابوحذیفہ رضی اللہ عنہ کے دل میں کچھ ناگواری ہے ، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اسے دودھ پلا دو تاکہ وہ تمہارے پاس آ سکے","",{"u2":"شعبہ نے حُمَید بن نافع سے حدیث بیان کی، انہوں نے زینب بنت ام سلمہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: سیدہ ام سلمہ رضی اللہ عنہا نے سیدہ عائشہ رضی اللہ عنہا سے کہا: آپ کے پاس (گھر میں) ایک قریب البلوغت لڑکا آتا ہے جسے میں پسند نہیں کرتی کہ وہ میرے پاس آئے۔ سیدہ عائشہ رضی اللہ عنہا نے جواب دیا: کیا تمہارے لیے رسول اللہ صلی اللہ علیہ وسلم (کی زندگی) میں نمونہ نہیں ہے؟ انہوں نے (آگے) کہا: ابوحذیفہ رضی اللہ عنہ کی بیوی نے عرض کی تھی: اے اللہ کے رسول! سالم میرے سامنے آتا ہے اور (اب) وہ مرد ہے، اور اس وجہ سے ابوحذیفہ رضی اللہ عنہ کے دل میں کچھ ناگواری ہے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے دودھ پلا دو تاکہ وہ تمہارے پاس آ سکے"}],[3571,"بُکَیر سے روایت ہے ، انہوں نے کہا : میں نے حمید بن نافع سے سنا وہ کہہ رہے تھے ، میں نے زینب بنت ابی سلمہ رضی اللہ عنہا سے سنا وہ کہہ رہی تھیں : میں نے نبی صلی اللہ علیہ وسلم کی زوجہ محترمہ ام سلمہ رضی اللہ عنہا سے سنا وہ سیدہ عائشہ رضی اللہ عنہا سے کہہ رہی تھیں : اللہ کی قسم! میرے دل کو یہ بات اچھی نہیں لگتی کہ مجھے کوئی ایسا لڑکا دیکھے جو رضاعت سے مستغنی ہو چکا ہے ۔ انہوں نے پوچھا : کیوں؟ سہلہ بنت سہیل رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی تھیں ، انہوں نے عرض کی تھی : اے اللہ کے رسول! اللہ کی قسم! میں سالم کے ( گھر میں ) داخلے کی وجہ سے ابوحذیفہ رضی اللہ عنہ کے چہرے پر ناگواری سی محسوس کرتی ہوں ، کہا : تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" اسے دودھ پلا دو ۔ \"\" اس نے کہا : وہ تو داڑھی والا ہے ۔ آپ نے فرمایا : \"\" اسے دودھ پلا دو ، اس سے وہ ناگواری ختم ہو جائے گی جو ابوحذیفہ کے چہرے پر ہے ۔ \"\" ( سہلہ رضی اللہ عنہا نے ) کہا : اللہ کی قسم! ( اس کے بعد ) میں نے ابوحذیفہ رضی اللہ عنہا کے چہرے پر ( کبھی ) ناگواری محسوس نہیں کی","",{"u2":"بُکَیر سے روایت ہے، انہوں نے کہا: میں نے حمید بن نافع سے سنا وہ کہہ رہے تھے، میں نے زینب بنت ابی سلمہ رضی اللہ عنہا سے سنا وہ کہہ رہی تھیں: میں نے نبی صلی اللہ علیہ وسلم کی زوجہ محترمہ ام سلمہ رضی اللہ عنہا سے سنا وہ سیدہ عائشہ رضی اللہ عنہا سے کہہ رہی تھیں: اللہ کی قسم! میرے دل کو یہ بات اچھی نہیں لگتی کہ مجھے کوئی ایسا لڑکا دیکھے جو رضاعت سے مستغنی ہو چکا ہے۔\nانہوں نے پوچھا: کیوں؟ سہلہ بنت سہیل رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی تھیں، انہوں نے عرض کی تھی: اے اللہ کے رسول! اللہ کی قسم! میں سالم کے (گھر میں) داخلے کی وجہ سے ابوحذیفہ رضی اللہ عنہ کے چہرے پر ناگواری سی محسوس کرتی ہوں، کہا: تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے دودھ پلا دو۔\" اس نے کہا: وہ تو داڑھی والا ہے۔ آپ نے فرمایا:\"اسے دودھ پلا دو، اس سے وہ ناگواری ختم ہو جائے گی جو ابوحذیفہ کے چہرے پر ہے۔\" (سہلہ رضی اللہ عنہا نے) کہا: اللہ کی قسم! (اس کے بعد) میں نے ابوحذیفہ رضی اللہ عنہا کے چہرے پر (کبھی) ناگواری محسوس نہیں کی"}],[3572,"ابوعبیدہ بن عبداللہ بن زمعہ نے مجھے خبر دی کہ ان کی والدہ زینب بنت ابی سلمہ رضی اللہ عنہا نے انہیں بتایا کہ ان کی والدہ نبی صلی اللہ علیہ وسلم کی زوجہ محترمہ سیدہ ام سلمہ رضی اللہ عنہا کہا کرتی تھیں : نبی صلی اللہ علیہ وسلم کی تمام ازواج نے اس بات سے انکار کیا کہ اس ( بڑی عمر کی ) رضاعت کی وجہ سے کسی کو اپنے گھر میں داخل ہونے دیں ، اور انہوں نے عائشہ رضی اللہ عنہا سے کہا : اللہ کی قسم! ہم اسے محض رخصت خیال کرتی ہیں جو رسول اللہ صلی اللہ علیہ وسلم نے خاص طور پر سالم رضی اللہ عنہ کو دی تھی ، لہٰذا اس ( طرح کی ) رضاعت کی وجہ سے نہ کوئی ہمارے پاس آنے والا بن سکے گا اور نہ ہمیں دیکھنے والا","",{"u2":"ابوعبیدہ بن عبداللہ بن زمعہ نے مجھے خبر دی کہ ان کی والدہ زینب بنت ابی سلمہ رضی اللہ عنہا نے انہیں بتایا کہ ان کی والدہ نبی صلی اللہ علیہ وسلم کی زوجہ محترمہ سیدہ ام سلمہ رضی اللہ عنہاکہا کرتی تھیں: نبی صلی اللہ علیہ وسلم کی تمام ازواج نے اس بات سے انکار کیا کہ اس (بڑی عمر کی) رضاعت کی وجہ سے کسی کو اپنے گھر میں داخل ہونے دیں، اور انہوں نے عائشہ رضی اللہ عنہا سے کہا: اللہ کی قسم! ہم اسے محض رخصت خیال کرتی ہیں جو رسول اللہ صلی اللہ علیہ وسلم نے خاص طور پر سالم رضی اللہ عنہ کو دی تھی، لہذا اس (طرح کی) رضاعت کی وجہ سے نہ کوئی ہمارے پاس آنے والا بن سکے گا اور نہ ہمیں دیکھنے والا"}],[3573,"ابواحوص نے ہمیں اشعث سے حدیث بیان کی ، انہوں نے اپنے والد سے ، اور انہوں نے مسروق سے روایت کی ، انہوں نے کہا : سیدہ عائشہ رضی اللہ عنہا نے کہا : رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے جبکہ میرے پاس ایک آدمی بیٹھا ہوا تھا ۔ یہ بات آپ پر گراں گزری ، اور میں نے آپ کے چہرے پر غصہ دیکھا ، کہا : تو میں نے عرض کی : اللہ کے رسول! یہ رضاعت ( کے رشتے سے ) میرا بھائی ہے ، کہا : تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" ( تم خواتین ) اپنے رضاعی بھائیوں ( کے معاملے ) کو دیکھ لیا کرو ( اچھی طرح غور کر لیا کرو ) کیونکہ رضاعت بھوک ہی سے ( معتبر ) ہے","",{"u2":"ابواحوص نے ہمیں اشعث سے حدیث بیان کی، انہوں نے اپنے والد سے، اور انہوں نے مسروق سے روایت کی، انہوں نے کہا: سیدہ عائشہ رضی اللہ عنہا نے کہا: رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے جبکہ میرے پاس ایک آدمی بیٹھا ہوا تھا۔ یہبات آپ پر گراں گزری، اور میں نے آپ کے چہرے پر غصہ دیکھا، کہا: تو میں نے عرض کی: اللہ کے رسول! یہ رضاعت (کے رشتے سے) میرا بھائی ہے، کہا: تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"(تم خواتین) اپنے رضاعی بھائیوں (کے معاملے) کو دیکھ لیا کرو (اچھی طرح غور کر لیا کرو) کیونکہ رضاعت بھوک ہی سے (معتبر) ہے"}],[3574,"شعبہ ، سفیان اور زائدہ سب نے اشعث بن ابو شعثاء سے ابواحوص کی سند کے ساتھ اسی کی حدیث کے ہم معنی حدیث بیان کی ، مگر انہوں نے ( بھی ) من المجاعة کے الفاظ کہے","",{"u2":"شعبہ، سفیان اور زائدہ سب نے اشعث بن ابو شعثاء سے ابواحوص کی سند کے ساتھ اسی کی حدیث کے ہم معنی حدیث بیان کی، مگر انہوں نے (بھی) من المجاعۃ کے الفاظ کہے"}],[3575,"یزید بن زُرَیع نے ہمیں حدیث بیان کی ، کہا : ہمیں سعید بن ابوعروبہ نے قتادہ سے حدیث بیان کی ، انہوں نے ابوخلیل صالح سے ، انہوں نے ابوعلقمہ ہاشمی سے اور انہوں نے ابوسعید خدری رضی اللہ عنہ سے روایت کی کہ حنین کے دن ( جنگ میں فتح حاصل کرنے کے بعد ) رسول اللہ صلی اللہ علیہ وسلم نے اوطاس کی جانب ایک لشکر بھیجا ، ان کا دشمن سے سامنا ہوا ، انہوں نے ان ( دشمنوں ) سے لڑائی کی ، پھر ان پر غالب آ گئے اور ان میں سے کنیزیں حاصل کر لیں ، تو رسول اللہ صلی اللہ علیہ وسلم کے اصحاب میں سے بعض لوگوں نے ان کے مشرک خاوندوں ( کی موجودگی ) کی بنا پر ان سے مجامعت کرنے میں حرج محسوس کیا ، اس پر اللہ عزوجل نے اس کے بارے میں ( یہ آیت ) نازل فرمائی : \" اور شادی شدہ عورتیں ( بھی حرام ہیں ) سوائے ان ( لونڈیوں ) کے جن کے مالک تمہارے دائیں ہاتھ ہوں ۔ \" یعنی جب ان کی عدت پوری ہو جائے تو ( تمہاری لونڈیاں بن جانے کی بنا پر ) وہ تمہارے لیے حلال ہیں","",{"u2":"یزید بن زُرَیع نے ہمیں حدیث بیان کی، کہا: ہمیں سعید بن ابوعروبہ نے قتادہ سے حدیث بیان کی، انہوں نے ابوخلیل صالح سے، انہوں نے ابوعلقمہ ہاشمی سے اور انہوں نے ابوسعید خدری رضی اللہ عنہ سے روایت کی کہ حنین کے دن (جنگ میں فتح حاصل کرنے کے بعد) رسول اللہ صلی اللہ علیہ وسلم نے اوطاس کی جانب ایک لشکر بھیجا، ان کا دشمن سے سامنا ہوا، انہوں نے ان (دشمنوں) سے لڑائی کی، پھر ان پر غالب آ گئے اور ان میں سے کنیزیں حاصل کر لیں، تو رسول اللہ صلی اللہ علیہ وسلم کے اصحاب میں سے بعض لوگوں نے ان کے مشرک خاوندوں (کی موجودگی) کی بنا پر ان سے مجامعت کرنے میں حرج محسوس کیا، اس پر اللہ عزوجل نے اس کے بارے میں (یہ آیت) نازل فرمائی: \"اور شادی شدہ عورتیں (بھی حرام ہیں) سوائے ان (لونڈیوں) کے جن کے مالک تمہارے دائیں ہاتھ ہوں۔\" یعنی جب ان کی عدت پوری ہو جائے تو (تمہاری لونڈیاں بن جانے کی بنا پر) وہ تمہارے لیے حلال ہیں"}],[3576,"عبدالاعلی نے ہمیں سعید سے حدیث بیان کی ، انہوں نے قتادہ سے ، انہوں نے ابوخلیل سے روایت کی کہ ابوعلقمہ ہاشمی نے حدیث بیان کی ، انہیں سیدنا ابوسعید خدری رضی اللہ عنہ نے حدیث بیان کی کہ اللہ کے نبی صلی اللہ علیہ وسلم نے حنین کے دن ایک سریہ بھیجا ۔ ۔ ۔ ( آگے ) یزید بن زریع کی حدیث کے ہم معنی ہے لیکن انہوں نے کہا : سوائے ان ( لونڈیوں ) کے جن کے مالک تمہارے دائیں ہاتھ ہوں ، وہ تمہارے لیے حلال ہیں ۔ اور انہوں نے \" جب ان کی عدت پوری ہو جائے \" کے الفاظ ذکر نہیں کیے ۔ ( اس سریہ میں جو کنیزیں ہاتھ آئیں یہ واقعہ ان کے بارے میں ہے)","",{"u2":"عبدالاعلی نے ہمیں سعید سے حدیث بیان کی، انہوں نے قتادہ سے، انہوں نے ابوخلیل سے روایت کی کہ ابوعلقمہ ہاشمی نے حدیث بیان کی، انہیں سیدنا ابوسعید خدری رضی اللہ عنہ نے حدیث بیان کی کہ اللہ کے نبی صلی اللہ علیہ وسلم نے حنین کے دن ایک سریہ بھیجا۔۔۔ (آگے) یزید بن زریع کی حدیث کے ہم معنی ہے لیکن انہوں نے کہا: سوائے ان (لونڈیوں) کے جن کے مالک تمہارے دائیں ہاتھ ہوں، وہ تمہارے لیے حلال ہیں۔ اور انہوں نے \"جب ان کی عدت پوری ہو جائے\" کے الفاظ ذکر نہیں کیے۔ (اس سریہ میں جو کنیزیں ہاتھ آئیں یہ واقعہ ان کے بارے میں ہے"}],[3577,"شعبہ نے قتادہ سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی","",{"u2":"شعبہ نے قتادہ سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی"}],[3578,"شعبہ نے ہمیں قتادہ سے حدیث بیان کی ، انہوں نے ابوخلیل سے اور انہوں نے سیدنا ابوسعید رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : اوطاس کے دن صحابہ کو لونڈیاں ملیں جن کے خاوند بھی تھے ، اس پر وہ ( ان سے تعلقات ، قائم کرتے ہوئے ) ڈرے ( کہ یہ گناہ نہ ہو ) اس پر یہ آیت نازل کی گئی : \" اور شادی شدہ عورتیں ( بھی حرام ہیں ) سوائے ان ( لونڈیوں ) کے جن کے تمہارے دائیں ہاتھ مالک ہو جائیں","",{"u2":"شعبہ نے ہمیں قتادہ سے حدیث بیان کی، انہوں نے ابوخلیل سے اور انہوں نے سیدنا ابوسعید رضی اللہ عنہ سے روایت کی، انہوں نے کہا: اوطاس کے دن صحابہ کو لونڈیاں ملیں جن کے خاوند بھی تھے، اس پر وہ (ان سے تعلقات، قائم کرتے ہوئے) ڈرے (کہ یہ گناہ نہ ہو) اس پر یہ آیت نازل کی گئی: \"اور شادی شدہ عورتیں (بھی حرام ہیں) سوائے ان (لونڈیوں) کے جن کے تمہارے دائیں ہاتھ مالک ہو جائیں"}],[3579,"سعید نے قتادہ سے اسی سند کے ساتھ اسی طرح حدیث بیان کی","",{"u2":"سعید نے قتادہ سے اسی سند کے ساتھ اسی طرح حدیث بیان کی"}],[3580,"قتیبہ بن سعید اور محمد بن رُمح نے کہا : لیث نے ہمیں ابن شہاب سے خبر دی ، انہوں نے عروہ سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : سعد بن ابی وقاص اور عبد بن زمعہ رضی اللہ عنہما نے ایک لڑکے کے بارے میں جھگڑا کیا ۔ سعد رضی اللہ عنہ نے کہا : اللہ کے رسول! یہ میرے بھائی عتبہ بن ابی وقاص کا بیٹا ہے ، اس نے مجھے وصیت کی تھی کہ یہ اس کا بیٹا ہے ، آپ اس کی مشابہت دیکھ لیں ۔ عبد بن زمعہ رضی اللہ عنہ نے کہا : یہ میرا بھائی ہے ، اللہ کے رسول! یہ میرے باپ کی لونڈی سے اسی کے بستر پر پیدا ہوا ہے ، رسول اللہ صلی اللہ علیہ وسلم نے اس کی مشابہت دیکھی تو آپ نے واضھ طور پر عتبہ کے ساتھ مشابہت ( بھی ) محسوس کی ، اس کے بعد آپ نے فرمایا : \"\" عبد! یہ تمہارا ( بھائی ) ہے ۔ ( اس کا سبب یہ ہے کہ ) بچہ صاحب فراش کا ہے ، اور زنا کرنے والے کے لیے پتھر ( ناکامی اور محرومی ) ہے ۔ اور سودہ بنت زمعہ! ( تم ) اس سے پردہ کرو ۔ \"\" اس کے بعد اس نے کبھی سیدہ سودہ رضی اللہ عنہا کو نہیں دیکھا ۔ اور محمد بن رمح نے آپ کے الفاظ \"\" يا عبد \"\" ذکر نہیں کیے","",{"u2":"قتیبہ بن سعید اور محمد بن رُمح نے کہا: لیث نے ہمیں ابن شہاب سے خبر دی، انہوں نے عروہ سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: سعد بن ابی وقاص اور عبد بن زمعہ رضی اللہ عنہما نے ایک لڑکے کے بارے میں جھگڑا کیا۔ سعد رضی اللہ عنہ نے کہا: اللہ کے رسول! یہ میرے بھائی عتبہ بن ابی وقاص کا بیٹا ہے، اس نے مجھے وصیت کی تھی کہ یہ اس کا بیٹا ہے، آپ اس کی مشابہت دیکھ لیں۔\nعبد بن زمعہ رضی اللہ عنہ نے کہا: یہ میرا بھائی ہے،اللہ کے رسول! یہ میرے باپ کی لونڈی سے اسی کے بستر پر پیدا ہوا ہے، رسول اللہ صلی اللہ علیہ وسلم نے اس کی مشابہت دیکھی تو آپ نے واضھ طور پر عتبہ کے ساتھ مشابہت (بھی) محسوس کی، اس کے بعد آپ نے فرمایا: \"عبد! یہ تمہارا (بھائی) ہے۔ (اس کا سبب یہ ہے کہ) بچہ صاحب فراش کا ہے، اور زنا کرنے والے کے لیے پتھر (ناکامی اور محرومی) ہے۔ اور سودہ بنت زمعہ! (تم) اس سے پردہ کرو۔\" اس کے بعد اس نے کبھی سیدہ سودہ رضی اللہ عنہا کو نہیں دیکھا۔ اور محمد بن رمح نے آپ کے الفاظ \"یا عبد\" ذکر نہیں کیے"}],[3581,"سفیان بن عیینہ اور معمر نے زہری سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی ۔ لیکن معمر اور ابن عیینہ کی حدیث میں ہے : \" بچہ صاحب فراش کا ہے \" اور ان دونوں نے \" زانی کے لیے پتھر ہے \" کے الفاظ ذکر نہیں کیے","",{"u2":"سفیان بن عیینہ اور معمر نے زہری سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی۔ لیکن معمر اور ابن عیینہ کی حدیث میں ہے: \"بچہ صاحب فراش کا ہے\" اور ان دونوں نے \"زانی کے لیے پتھر ہے\" کے الفاظ ذکر نہیں کیے"}],[3582,"معمر نے زہری سے خبر دی ، انہوں نے ابن مسیب اور ابوسلمہ سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" بچہ بستر والے کا ہے اور زانی کے لیے پتھر ( ناکامی اور محرومی ) ہے","",{"u2":"معمر نے زہری سے خبر دی، انہوں نے ابن مسیب اور ابوسلمہ سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بچہ بستر والے کا ہے اور زانی کے لیے پتھر (ناکامی اور محرومی) ہے"}],[3583,"سعید بن منصور ، زہیر بن حرب ، عبدالاعلیٰ بن حماد اور عمرو ناقد سب نے کہا : ہمیں سفیان نے زہری سے خبر دی ۔ ابن منصور نے کہا : سعید نے ابوہریرہ رضی اللہ عنہ سے روایت کی ۔ عبدالاعلی نے کہا : ابوسلمہ سے یا سعید سے روایت ہے ، انہوں نے ابوہریرہ رضی اللہ عنہ سے روایت کی ۔ زہیر نے کہا : سعید یا ابوسلمہ نے ان دونوں میں سے ایک نے یا دونوں نے ابوہریرہ رضی اللہ عنہ سے روایت کی ۔ اور عمرو نے ایک بار کہا : ہمیں سفیان نے زہری کے حوالے سے سعید اور ابوسلمہ سے ، اور ایک بار کہا : سعید یا ابوسلمہ سے ، اور ایک بار کہا : سعید نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ۔ ۔ ۔ ( آگے ) جس طرح معمر کی حدیث ہے","",{"u2":"سعید بن منصور، زہیر بن حرب، عبدالاعلیٰ بن حماد اور عمرو ناقد سب نے کہا: ہمیں سفیان نے زہری سے خبر دی۔ ابن منصور نے کہا: سعید نے ابوہریرہ رضی اللہ عنہ سے روایت کی۔ عبدالاعلی نے کہا: ابوسلمہ سے یا سعید سے روایت ہے، انہوں نے ابوہریرہ رضی اللہ عنہ سے روایت کی۔ زہیر نے کہا: سعید یا ابوسلمہ نے ان دونوں میں سے ایک نے یا دونوں نے ابوہریرہ رضی اللہ عنہ سے روایت کی۔ اور عمرو نے ایک بار کہا: ہمیں سفیان نے زہری کے حوالے سے سعید اور ابوسلمہ سے، اور ایک بار کہا: سعید یا ابوسلمہ سے، اور ایک بار کہا: سعید نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی۔۔۔ (آگے) جس طرح معمر کی حدیث ہے"}],[3584,"لیث نے ہمیں ابن شہاب سے حدیث بیان کی ، انہوں نے عروہ سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم خوش خوش میرے پاس تشریف لائے ، آپ کے چہرے ( پیشانی ) کے خطوط چمک رہے تھے ، آپ نے فرمایا : \" تم نے دیکھا نہیں کہ ابھی ابھی ( بنو مدلج کے قیافہ شناس ) مُجزز نے زید بن حارثہ اور اسامہ بن زید رضی اللہ عنہما کو دیکھا ہے ، اور کہا ہے : ان قدموں میں سے ایک ( قدم ) دوسرے میں سے ہے ۔ \" ( ایک بیٹے کا ہے ، دوسرا باپ کا)","",{"u2":"لیث نے ہمیں ابن شہاب سے حدیث بیان کی، انہوں نے عروہ سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم خوش خوش میرے پاس تشریف لائے، آپ کے چہرے (پیشانی) کے خطوط چمک رہے تھے، آپ نے فرمایا: \"تم نے دیکھا نہیں کہ ابھی ابھی (بنو مدلج کے قیافہ شناس) مُجزز نے زید بن حارثہ اور اسامہ بن زید رضی اللہ عنہما کو دیکھا ہے، اور کہا ہے: ان قدموں میں سے ایک (قدم) دوسرے میں سے ہے۔\" (ایک بیٹے کا ہے، دوسرا باپ کا"}],[3585,"سفیان نے ہمیں زہری سے حدیث بیان کی ، انہوں نے عروہ سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : ایک روز رسول اللہ صلی اللہ علیہ وسلم خوش خوش میرے پاس تشریف لائے ۔ اور فرمایا : \" عائشہ! کیا تم نے دیکھا نہیں کہ مجزز مدلجی میرے پاس آیا ، اس نے اسامہ اور زید کو دیکھا ، ان دونوں پر ایک چادر تھی جس نے ان کے سروں کو ڈھانپا ہوا تھا اور ان کے پاؤں ننگے تھے تو اس نے کہا : بلاشبہ یہ قدم ایک دوسرے میں سے ہیں","",{"u2":"سفیان نے ہمیں زہری سے حدیث بیان کی، انہوں نے عروہ سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: ایک روز رسول اللہ صلی اللہ علیہ وسلم خوش خوش میرے پاس تشریف لائے۔ اور فرمایا: \"عائشہ! کیا تم نے دیکھا نہیں کہ مجزز مدلجی میرے پاس آیا، اس نے اسامہ اور زید کو دیکھا، ان دونوں پر ایک چادر تھی جس نے ان کے سروں کو ڈھانپا ہوا تھا اور ان کے پاؤں ننگے تھے تو اس نے کہا: بلاشبہ یہ قدم ایک دوسرے میں سے ہیں"}],[3586,"ابراہیم بن سعد نے ہمیں زہری سے حدیث بیان کی ، انہوں نے عروہ سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : ایک قیافہ شناس آیا ، رسول اللہ صلی اللہ علیہ وسلم بھی موجود تھے ، اسامہ بن زید اور زید بن حارثہ رضی اللہ عنہم ( ایک چادر میں ) لیٹے ہوئے تھے تو اس نے کہا : بلاشبہ یہ قدم ایک دوسرے میں سے ہیں ۔ اس سے نبی صلی اللہ علیہ وسلم کو خوشی ہوئی اور آپ کو بہت اچھا لگا ، آپ نے یہ بات سیدہ عائشہ رضی اللہ عنہا کو بھی بتائی","",{"u2":"ابراہیم بن سعد نے ہمیں زہری سے حدیث بیان کی، انہوں نے عروہ سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: ایک قیافہ شناس آیا، رسول اللہ صلی اللہ علیہ وسلم بھی موجود تھے، اسامہ بن زید اور زید بن حارثہ رضی اللہ عنہم (ایک چادر میں) لیٹے ہوئے تھے تو اس نے کہا: بلاشبہ یہ قدم ایک دوسرے میں سے ہیں۔ اس سے نبی صلی اللہ علیہ وسلم کو خوشی ہوئی اور آپ کو بہت اچھا لگا، آپ نے یہ بات سیدہ عائشہ رضی اللہ عنہا کو بھی بتائی"}],[3587,"یونس ، معمر اور ابن جریج سب نے زہری سے اسی سند کے ساتھ ، ان ( لیث ، سفیان اور ابراہیم بھی سعد ) کی حدیث کے ہم معنی روایت بیان کی اور ( ابن وہب نے ) یونس کی حدیث میں یہ اضافہ کیا : اور مجزز ایک قیافہ شاس تھا","",{"u2":"یونس، معمر اور ابن جریج سب نے زہری سے اسی سند کے ساتھ، ان (لیث، سفیان اور ابراہیم بھی سعد) کی حدیث کے ہم معنی روایت بیان کی اور (ابن وہب نے) یونس کی حدیث میں یہ اضافہ کیا: اور مجزز ایک قیافہ شاس تھا"}],[3588,"محمد بن ابوبکر نے عبدالملک بن ابوبکر بن عبدالرحمٰن بن حارث بن ہشام سے ، انہوں نے اپنے والد سے ، انہوں نے ام سلمہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے جب ام سلمہ رضی اللہ عنہا سے شادی کی تو ان کے ہاں تین دن قیام کیا اور فرمایا : \" اپنے اہل ( شوہر ) کے نزدیک تمہاری قدر و منزلت میں کسی طرح کی کمی نہیں ، اگر تم چاہو تو میں تمہارے پاس ( قیام کے لیے ) سات دن رکھ لیتا ہوں اور اگر میں نے تمہارے ہاں سات دن قیام کیا تو اپنی ساری بیویوں کے ہاں سات سات دن قیام کروں گا","",{"u2":"محمد بن ابوبکر نے عبدالملک بن ابوبکر بن عبدالرحمٰن بن حارث بن ہشام سے، انہوں نے اپنے والد سے، انہوں نے ام سلمہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے جب ام سلمہ رضی اللہ عنہا سے شادی کی تو ان کے ہاں تین دن قیام کیا اور فرمایا: \"اپنے اہل (شوہر) کے نزدیک تمہاری قدر و منزلت میں کسی طرح کی کمی نہیں، اگر تم چاہو تو میں تمہارے پاس (قیام کے لیے) سات دن رکھ لیتا ہوں اور اگر میں نے تمہارے ہاں سات دن قیام کیا تو اپنی ساری بیویوں کے ہاں سات سات دن قیام کروں گا"}],[3589,"عبداللہ بن ابوبکر نے عبدالملک بن ابوبکر سے ، انہوں نے ابوبکر بن عبدالرحمٰن سے روایت کی کہ جب رسول اللہ صلی اللہ علیہ وسلم نے ام سلمہ رضی اللہ عنہا سے نکاح کیا اور وہ آپ صلی اللہ علیہ وسلم کے پاس رہائش پذیر ہو گئیں تو آپ صلی اللہ علیہ وسلم نے ان سے کہا : \" اپنے شوہر کے سامنے تمہارے مرتبے میں کوئی کمی نہیں ، اگر تم چاہو تو میں تمہارے ہاں سات دن قیام کروں گا ، اور اگر تم چاہو تو تین دن قیام کروں گا پھر ( باری باری ) سب کے ہاں جانا شروع کروں گا ۔ \" ام سلمہ رضی اللہ عنہا نے جواب دیا : آپ تین دن قیام فرمائیں","",{"u2":"عبداللہ بن ابوبکر نے عبدالملک بن ابوبکر سے، انہوں نے ابوبکر بن عبدالرحمٰن سے روایت کی کہ جب رسول اللہ صلی اللہ علیہ وسلم نے ام سلمہ رضی اللہ عنہا سے نکاح کیا اور وہ آپ صلی اللہ علیہ وسلم کے پاس رہائش پذیر ہو گئیں تو آپ صلی اللہ علیہ وسلم نے ان سے کہا: \"اپنے شوہر کے سامنے تمہارے مرتبے میں کوئی کمی نہیں، اگر تم چاہو تو میں تمہارے ہاں سات دن قیام کروں گا، اور اگر تم چاہو تو تین دن قیام کروں گا پھر (باری باری) سب کے ہاں جانا شروع کروں گا۔\" ام سلمہ رضی اللہ عنہا نے جواب دیا: آپ تین دن قیام فرمائیں"}],[3590,"سلیمان بن بلال نے ہمیں عبدالرحمٰن بن حُمَید سے حدیث بیان کی ، انہوں نے عبدالملک بن ابوبکر سے ، انہوں نے ابوبکر بن عبدالرحمٰن سے روایت کی کہ جب رسول اللہ صلی اللہ علیہ وسلم نے ام سلمہ رضی اللہ عنہا سے نکاح کیا تو آپ ان کے پاس گئے ، اس کے بعد آپ نے نکلنے کا ارادہ کیا تو انہوں نے آپ کے کپڑے کو پکڑ لیا ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اگر تم چاہو تو میں مزید تمہارے ہاں قیام کروں گا اور تمہارے ساتھ اس کا حساب رکھوں گا ، کنواری کے لیے سات راتیں ہیں اور ثیبہ ( دوہاجو ) کے لیے تین راتیں ہیں","",{"u2":"سلیمان بن بلال نے ہمیں عبدالرحمٰن بن حُمَید سے حدیث بیان کی، انہوں نے عبدالملک بن ابوبکر سے، انہوں نے ابوبکر بن عبدالرحمٰن سے روایت کی کہ جب رسول اللہ صلی اللہ علیہ وسلم نے ام سلمہ رضی اللہ عنہا سے نکاح کیا تو آپ ان کے پاس گئے، اس کے بعد آپ نے نکلنے کا ارادہ کیا تو انہوں نے آپ کے کپڑے کو پکڑ لیا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم چاہو تو میں مزید تمہارے ہاں قیام کروں گا اور تمہارے ساتھ اس کا حساب رکھوں گا، کنواری کے لیے سات راتیں ہیں اور ثیبہ (دوہاجو) کے لیے تین راتیں ہیں"}],[3591,"ابوضمرہ نے عبدالرحمٰن بن حمید سے اسی سند کے ساتھ اسی کے مانند روایت کی","",{"u2":"ابوضمرہ نے عبدالرحمٰن بن حمید سے اسی سند کے ساتھ اسی کے مانند روایت کی"}],[3592,"عبدالواحد بن ایمن نے ابوبکر بن عبدالرحمٰن سے ، انہوں نے ام سلمہ رضی اللہ عنہا سے روایت کی ، انہوں ( عبدالواحد ) نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے ان ( ام سلمہ رضی اللہ عنہا ) سے شادی کی ، اور بہت سی باتوں کا ذکر کیا ، ان میں یہ بات بھی تھی : آپ نے فرمایا : \" اگر تم چاہو کہ میں تمہارے ہاں سات سات دن قیام کروں ( تو ہو سکتا ہے ) اور اگر میں نے تمہارے ہاں سات دن قیام کیا تو اپنی ساری بیویوں کے ہاں سات سات دن قیام کروں گا","",{"u2":"عبدالواحد بن ایمن نے ابوبکر بن عبدالرحمٰن سے، انہوں نے ام سلمہ رضی اللہ عنہا سے روایت کی، انہوں (عبدالواحد) نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے ان (ام سلمہ رضی اللہ عنہا) سے شادی کی، اور بہت سی باتوں کا ذکر کیا، ان میں یہ بات بھی تھی: آپ نے فرمایا: \"اگر تم چاہو کہ میں تمہارے ہاں سات سات دن قیام کروں (تو ہو سکتا ہے) اور اگر میں نے تمہارے ہاں سات دن قیام کیا تو اپنی ساری بیویوں کے ہاں سات سات دن قیام کروں گا"}],[3593,"ہشیم نے ہمیں خالد سے خبر دی ، انہوں نے ابوقلابہ سے ، انہوں نے انس بن مالک رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : جب کوئی دوہاجو جو ( ثیبہ ) کے بعد باکرہ سے شادی کرے تو اس کے ہاں سات دن قیام کرے اور جب باکرہ کے بعد کسی ثیبہ سے شادی کرے تو اس کے ہاں تین دن قیام کرے ۔ خالد نے کہا : اگر میں کہوں کہ انہوں نے اسے مرفوعا بیان کیا ہے ، تو میں سچ کہوں گا لیکن انہوں نے کہا تھا : سنت اسی طرح ہے ۔ ( یہ حدیث کو مرفوع کرنے کے مترادف ہے)","",{"u2":"ہشیم نے ہمیں خالد سے خبر دی، انہوں نے ابوقلابہ سے، انہوں نے انس بن مالک رضی اللہ عنہ سے روایت کی، انہوں نے کہا: جب کوئی دوہاجو جو (ثیبہ) کے بعد باکرہ سے شادی کرے تو اس کے ہاں سات دن قیام کرے اور جب باکرہ کے بعد کسی ثیبہ سے شادی کرے تو اس کے ہاں تین دن قیام کرے۔ خالد نے کہا: اگر میں کہوں کہ انہوں نے اسے مرفوعا بیان کیا ہے، تو میں سچ کہوں گا لیکن انہوں نے کہا تھا: سنت اسی طرح ہے۔ (یہ حدیث کو مرفوع کرنے کے مترادف ہے"}],[3594,"سفیان نے ایوب اور خالد حذاء سے خبر دی ، انہوں نے ابوقلابہ سے ، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : سنت میں سے ہے کہ ( دلہا ) باکرہ کے ہاں سات راتیں قیام کرے ۔ خالد نے کہا : اگر میں چاہوں تو کہہ سکتا ہوں : انہوں نے اسے نبی صلی اللہ علیہ وسلم سے مرفوعا بیان کیا ہے","",{"u2":"سفیان نے ایوب اور خالد حذاء سے خبر دی، انہوں نے ابوقلابہ سے، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: سنت میں سے ہے کہ (دلہا) باکرہ کے ہاں سات راتیں قیام کرے۔\nخالد نے کہا: اگر میں چاہوں تو کہہ سکتا ہوں: انہوں نے اسے نبی صلی اللہ علیہ وسلم سے مرفوعا بیان کیا ہے"}],[3595,"سیدنا انس رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : نبی صلی اللہ علیہ وسلم کی نو بیویاں تھیں ، جب آپ ان میں باری تقسیم فرماتے تو پہلی باری والی بیوی کے پاس نویں رات ہی پہنچتے ۔ وہ سب ہر رات اس ( بیوی کے ) گھر میں جمع ہو جاتی تھیں جہاں نبی صلی اللہ علیہ وسلم تشریف فرما ہوتے ، سیدہ زینب رضی اللہ عنہا آئیں تو آپ نے اپنا ہاتھ ان کی طرف پھیلایا ۔ انہوں ( عائشہ رضی اللہ عنہا ) نے کہا : یہ زینب ہیں آپ نے اپنا ہاتھ روک لیا ، اس پر ان دونوں میں تکرار ہو گئی حتی کہ ان کی آوازیں بلند ہو گئیں ، اور ( اسی دوران میں ) نماز کی اامت ہو گئی ، سیدنا ابوبکر رضی اللہ عنہ کا وہاں سے گزر ہوا ، انہوں نے ان کی آوازیں سنیں تو کہا : اے اللہ کے رسول! آپ نماز کے لیے تشریف لائیے اور ان کے منہ میں مٹی ڈالیے ۔ نبی صلی اللہ علیہ وسلم باہر تشریف لائے تو سیدہ عائشہ رضی اللہ عنہا نے کہا : ابھی نبی صلی اللہ علیہ وسلم اپنی نماز پوری کریں گے تو ابوبکر رضی اللہ عنہ آئیں گے وہ مجھے ایسے ایسے ( ڈانٹ ڈپٹ ) کریں گے ۔ جب نبی صلی اللہ علیہ وسلم نے نماز مکمل کی ، ابوبکر رضی اللہ عنہ ان ( سیدہ عائشہ رضی اللہ عنہا ) کے پاس آئے اور انہیں سخت سرزنش کی ۔ اور کہا : کیا تم ایسا کرتی ہو؟","",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: نبی صلی اللہ علیہ وسلم کی نو بیویاں تھیں، جب آپ ان میں باری تقسیم فرماتے تو پہلی باری والی بیوی کے پاس نویں رات ہی پہنچتے۔ وہ سب ہر رات اس (بیوی کے) گھر میں جمع ہو جاتی تھیں جہاں نبی صلی اللہ علیہ وسلم تشریف فرما ہوتے، سیدہ زینب رضی اللہ عنہا آئیں تو آپ نے اپنا ہاتھ ان کی طرف پھیلایا۔ انہوں (عائشہ رضی اللہ عنہا) نے کہا: یہ زینب ہیں آپ نے اپنا ہاتھ روک لیا، اس پر ان دونوں میں تکرار ہو گئی حتی کہ ان کی آوازیں بلند ہو گئیں، اور (اسی دوران میں) نماز کی اامت ہو گئی، سیدنا ابوبکر رضی اللہ عنہ کا وہاں سے گزر ہوا، انہوں نے ان کی آوازیں سنیں تو کہا: اے اللہ کے رسول! آپ نماز کے لیے تشریف لائیے اور ان کے منہ میں مٹی ڈالیے۔ نبی صلی اللہ علیہ وسلم باہر تشریف لائے تو سیدہ عائشہ رضی اللہ عنہا نے کہا: ابھی نبی صلی اللہ علیہ وسلم اپنی نماز پوری کریں گے تو ابوبکر رضی اللہ عنہ آئیں گے وہ مجھے ایسے ایسے (ڈانٹ ڈپٹ) کریں گے۔ جب نبی صلی اللہ علیہ وسلم نے نماز مکمل کی، ابوبکر رضی اللہ عنہ ان (سیدہ عائشہ رضی اللہ عنہا) کے پاس آئے اور انہیں سخت سرزنش کی۔ اور کہا: کیا تم ایسا کرتی ہو؟"}],[3596,"جریر نے ہمیں ہشام بن عروہ سے حدیث بیان کی ، انہوں نے اپنے والد ( عروہ بن زبیر ) سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : میں نے کوئی عورت نہیں دیکھی جو مجھے سودہ بنت زمعہ رضی اللہ عنہا کی نسبت زیادہ پسندیدہ ہو کہ میں اس کے پیکر میں ہوں ( اس جیسی بن جاؤں ) ایک ایسی خاتون کی نسبت جن میں کچھ گرم مزاجی ( بھی ) تھی ، کہا : جب وہ بوڑھی ہو گئیں تو انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اپنی باری کا دن سیدہ عائشہ رضی اللہ عنہا کو دے دیا ۔ انہوں نے کہا : اے اللہ کے رسول! میں نے آپ کے ساتھ اپنی باری کا دن سیدہ عائشہ رضی اللہ عنہا کو دے دیا ہے ۔ اس کے بعد رسول اللہ صلی اللہ علیہ وسلم عائشہ رضی اللہ عنہا کو دو دن دیتے ، ایک ان کا دن اور ایک سیدہ سودہ رضی اللہ عنہا کا دن","",{"u2":"جریر نے ہمیں ہشام بن عروہ سے حدیث بیان کی، انہوں نے اپنے والد (عروہ بن زبیر) سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: میں نے کوئی عورت نہیں دیکھی جو مجھے سودہ بنت زمعہ رضی اللہ عنہا کی نسبت زیادہ پسندیدہ ہو کہ میں اس کے پیکر میں ہوں (اس جیسی بن جاؤں) ایک ایسی خاتون کی نسبت جن میں کچھ گرم مزاجی (بھی) تھی، کہا: جب وہ بوڑھی ہو گئیں تو انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اپنی باری کا دن سیدہ عائشہ رضی اللہ عنہا کو دے دیا۔ انہوں نے کہا: اے اللہ کے رسول! میں نے آپ کے ساتھ اپنی باری کا دن سیدہ عائشہ رضی اللہ عنہا کو دے دیا ہے۔ اس کے بعد رسول اللہ صلی اللہ علیہ وسلم عائشہ رضی اللہ عنہا کو دو دن دیتے، ایک ان کا دن اور ایک سیدہ سودہ رضی اللہ عنہا کا دن"}],[3597,"عقبہ بن خالد ، زہیر اور شریک ، ان سب نے ہشام سے اسی سند کے ساتھ روایت کی کہ سیدہ سودہ رضی اللہ عنہا جب بوڑھی ہو گئیں ۔ ۔ ۔ آگے جریر کی حدیث کے ہم معنی ہے اور شریک کی حدیث میں یہ اضافہ ہے : وہ پہلی خاتون تھیں جن سے آپ صلی اللہ علیہ وسلم نے میرے بعد نکاح کیا","",{"u2":"عقبہ بن خالد، زہیر اور شریک، ان سب نے ہشام سے اسی سند کے ساتھ روایت کی کہ سیدہ سودہ رضی اللہ عنہا جب بوڑھی ہو گئیں۔۔۔ آگے جریر کی حدیث کے ہم معنی ہے اور شریک کی حدیث میں یہ اضافہ ہے: وہ پہلی خاتون تھیں جن سے آپ صلی اللہ علیہ وسلم نے میرے بعد نکاح کیا"}],[3598,"ابواسامہ نے ہمیں ہشام سے حدیث بیان کی ، انہوں نے اپنے والد ( عروہ ) سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : میں ان عورتوں پر غیرت کرتی تھی جو اپنے آپ کو رسول اللہ صلی اللہ علیہ وسلم کے سامنے بطور ہبہ پیش کرتی تھیں ، میں کہتی : کیا کوئی عورت بھی خود کو ہبہ کر سکتی ہے؟ جب اللہ تعالیٰ نے نازل فرمایا : \" آپ ان عورتوں میں سے جسے چاہیں پیچھے کر دیں اور جسے چاہیں اپنے پاس جگہ دیں اور جسے آپ نے الگ کر دیا تھا ان میں سے بھی جسے آپ کا دل چاہے لائیں ۔ \" کہا : تو میں نے کہا : اللہ کی قسم! میں آپ کے رب کو نہیں دیکھتی مگر وہ آپ کے لیے آپ کی خواہش ( کو پورا کرنے ) میں جلدی کرتا ہے","",{"u2":"ابواسامہ نے ہمیں ہشام سے حدیث بیان کی، انہوں نے اپنے والد (عروہ) سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: میں ان عورتوں پر غیرت کرتی تھی جو اپنے آپ کو رسول اللہ صلی اللہ علیہ وسلم کے سامنے بطور ہبہ پیش کرتی تھیں، میں کہتی: کیا کوئی عورت بھی خود کو ہبہ کر سکتی ہے؟ جب اللہ تعالیٰ نے نازل فرمایا: \"آپ ان عورتوں میں سے جسے چاہیں پیچھے کر دیں اور جسے چاہیں اپنے پاس جگہ دیں اور جسے آپ نے الگ کر دیا تھا ان میں سے بھی جسے آپ کا دل چاہے لائیں۔\" کہا: تو میں نے کہا: اللہ کی قسم! میں آپ کے رب کو نہیں دیکھتی مگر وہ آپ کے لیے آپ کی خواہش (کو پورا کرنے) میں جلدی کرتا ہے"}],[3599,"عبدہ بن سلیمان نے ہشام سے حدیث بیان کی ، انہوں نے اپنے والد ( عروہ ) سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سےروایت کی ، وہ کہا کرتی تھیں : کیا اس عورت کو حیا محسوس نہیں ہوتی جو خود کو کسی مرد کے لیے ہبہ کرتی ہے ۔ یہاں تک کہ اللہ تعالیٰ نے یہ نازل فرمایا : \" آپ ان عورتوں میں سے جسے چاہیں پیچھے کریں اور جسے چاہیں اپنے پاس جگہ دیں ۔ \" تو میں نے کہا : بلاشبہ آپ کا رب آپ کی خواہش ( کو پورا کرنے ) میں جلدی کرتا ہے","",{"u2":"عبدہ بن سلیمان نے ہشام سے حدیث بیان کی، انہوں نے اپنے والد (عروہ) سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سےروایت کی، وہ کہاکرتی تھیں: کیا اس عورت کو حیا محسوس نہیں ہوتی جو خود کو کسی مرد کے لیے ہبہ کرتی ہے۔ یہاں تک کہ اللہ تعالیٰ نے یہ نازل فرمایا: \"آپ ان عورتوں میں سے جسے چاہیں پیچھے کریں اور جسے چاہیں اپنے پاس جگہ دیں۔\" تو میں نے کہا: بلاشبہ آپ کا رب آپ کی خواہش (کو پورا کرنے) میں جلدی کرتا ہے"}],[3600,"محمد بن بکر نے ہمیں حدیث بیان کی ، کہا : ہمیں ابن جریج نے خبر دی ، کہا : مجھے عطاء نے خبر دی ، کہا : سرف کے مقام پر ہم سیدنا ابن عباس رضی اللہ عنہ کے ساتھ نبی صلی اللہ علیہ وسلم کی اہلیہ سیدہ میمونہ رضی اللہ عنہا کے جنازے میں حاضر ہوئے تو ابن عباس رضی اللہ عنہ نے کہا : یہ نبی صلی اللہ علیہ وسلم کی اہلیہ ہیں ۔ جب تم ان کی چارپائی اٹھاؤ تو اس کو ادھر اُدھر حرکت دینا نہ ہلانا ، نرمی ( اور احترام ) سے کام لینا ، امر واقع یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی نو بیویاں تھیں ، آپ آٹھ کے لیے باری تقسیم کرتے اور ایک کے لیے تقسیم نہ کرتے تھے ۔ عطاء نے کہا : جن کو آپ باری نہیں دیتے تھے وہ سیدہ صفیہ بنت حیی بن اخطب رضی اللہ عنہا تھیں","",{"u2":"محمد بن بکر نے ہمیں حدیث بیان کی، کہا: ہمیں ابن جریج نے خبر دی، کہا: مجھے عطاء نے خبر دی، کہا: سرف کے مقام پر ہم سیدنا ابن عباس رضی اللہ عنہ کے ساتھ نبی صلی اللہ علیہ وسلم کی اہلیہ سیدہ میمونہ رضی اللہ عنہا کے جنازے میں حاضر ہوئے تو ابن عباس رضی اللہ عنہ نے کہا: یہ نبی صلی اللہ علیہ وسلم کی اہلیہ ہیں۔ جب تم ان کی چارپائی اٹھاؤ تو اس کو ادھر اُدھر حرکت دینا نہ ہلانا، نرمی (اور احترام) سے کام لینا، امر واقع یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی نو بیویاں تھیں، آپ آٹھ کے لیے باری تقسیم کرتے اور ایک کے لیے تقسیم نہ کرتے تھے۔ عطاء نے کہا: جن کو آپ باری نہیں دیتے تھے وہ سیدہ صفیہ بنت حیی بن اخطب رضی اللہ عنہا تھیں"}],[3601,"عبدالرزاق نے ابن جریج سے اسی سند کے ساتھ روایت کی اور یہ اضافہ کیا کہ عطاء نے کہا : وہ ان سب میں سے ، آخر میں فوت ہونے والی ( میمونہ رضی اللہ عنہا ) تھیں ، وہ مدینہ میں فوت ہوئیں","",{"u2":"عبدالرزاق نے ابن جریج سے اسی سند کے ساتھ روایت کی اور یہ اضافہ کیا کہ عطاء نے کہا: وہ ان سب میں سے، آخر میں فوت ہونے والی (میمونہ رضی اللہ عنہا) تھیں، وہ مدینہ میں فوت ہوئیں"}],[3602,"سیدنا ابوہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" عورت کے ساتھ چار باتوں کی بنا پر شادی کی جاتی ہے : اس کے مال کی وجہ سے ، اس کے حسب ( ونسب ) کی وجہ سے ، اس کی خوبصورتی کی وجہ سے اور اس کے دین کی وجہ سے ۔ تم دین والی کے ساتھ ( شادی کر کے ) ظفر مند بنو ( کامیابی حاصل کرو ) تمہارے ہاتھ خاک آلود ہوں ۔ \" ( یہ اس بات سے کنایہ ہے کہ تم ہمیشہ کام کرتے رہو)","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"عورت کے ساتھ چار باتوں کی بنا پر شادی کی جاتی ہے: اس کے مال کی وجہ سے، اس کے حسب (ونسب) کی وجہ سے، اس کی خوبصورتی کی وجہ سے اور اس کے دین کی وجہ سے۔ تم دین والی کے ساتھ (شادی کر کے) ظفر مند بنو (کامیابی حاصل کرو) تمہارے ہاتھ خاک آلود ہوں۔\" (یہ اس بات سے کنایہ ہے کہ تم ہمیشہ کام کرتے رہو"}],[3603,"عطاء سے روایت ہے ، کہا : مجھے جابر بن عبداللہ رضی اللہ عنہ نے خبر دی ، انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک عورت سے شادی کی ، میری ملاقات نبی صلی اللہ علیہ وسلم سے ہوئی تو آپ نے پوچھا : \" جابر! تم نے نکاح کر لیا ہے؟ \" میں نے عرض کی : جی ہاں ۔ آپ نے فرمایا : \" کنواری ہے یا دوہاجو ( شوہر دیدہ ) ؟ \" میں نے عرض کی : دوہاجو ۔ آپ نے فرمایا : \" باکرہ سے کیوں نہ کی ، تم اس سے دل لگی کرتے؟ \" میں نے عرض کی : اے اللہ کے رسول! میری بہنیں ہیں تو میں ڈرا کہ وہ میرے اور ان کے درمیان حائل ہو جائے گی ، آپ نے فرمایا : \" پھر ٹھیک ہے ، بلاشبہ کسی عورت سے شادی ( میں رغبت ) اس کے دین ، مال اور خوبصورتی کی وجہ سے کی جاتی ہے ، تم دین والی کو چنو تمہارے ہاتھ خاک آلود ہوں","",{"u2":"عطاء سے روایت ہے، کہا: مجھے جابر بن عبداللہ رضی اللہ عنہ نے خبر دی، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک عورت سے شادی کی، میری ملاقات نبی صلی اللہ علیہ وسلم سے ہوئی تو آپ نے پوچھا: \"جابر! تم نے نکاح کر لیا ہے؟\" میں نے عرض کی: جی ہاں۔ آپ نے فرمایا:\"کنواری ہے یا دوہاجو (شوہر دیدہ)؟\" میں نے عرض کی: دوہاجو۔ آپ نے فرمایا: \"باکرہ سے کیوں نہ کی، تم اس سے دل لگی کرتے؟\" میں نے عرض کی: اے اللہ کے رسول! میری بہنیں ہیں تو میں ڈرا کہ وہ میرے اور ان کے درمیان حائل ہو جائے گی، آپ نے فرمایا: \"پھر ٹھیک ہے، بلاشبہ کسی عورت سے شادی (میں رغبت) اس کے دین، مال اور خوبصورتی کی وجہ سے کی جاتی ہے، تم دین والی کو چنو تمہارے ہاتھ خاک آلود ہوں"}],[3604,"شعبہ نے ہمیں محارب سے حدیث بیان کی ، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں نے ایک عورت سے شادی کی تو رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے پوچھا : \"\" کیا تم نے نکاح کیا ہے؟ \"\" میں نے عرض کی : جی ہاں ۔ آپ نے پوچھا : \"\" کنواری سے یا دوہاجو ( ثیبہ ) سے؟ \"\" میں نے عرض کی : دوہاجو سے ۔ آپ نے فرمایا : \"\" تم کنواریوں اور ان کی ملاعبت ( باہم کھیل کود ) سے ( دور ) کہاں رہ گئے؟ \"\" شعبہ نے کہا : میں نے یہ حدیث عمرو بن دینار کے سامنے بیان کی تو انہوں نے کہا : میں نے یہ حدیث سیدنا جابر رضی اللہ عنہ سے سنی تھی اور انہوں نے کہا تھا : \"\" تم نے کنواری سے ( شادی ) کیوں نہ کی؟ تم اس کے ساتھ کھیلتے وہ تمہارے ساتھ کھیلتی","",{"u2":"شعبہ نے ہمیں محارب سے حدیث بیان کی، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں نے ایک عورت سے شادی کی تو رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے پوچھا: \"کیا تم نے نکاح کیا ہے؟\" میں نے عرض کی: جی ہاں۔ آپ نے پوچھا: \"کنواری سے یا دوہاجو (ثیبہ) سے؟\" میں نے عرض کی: دوہاجو سے۔ آپ نے فرمایا: \"تم کنواریوں اور ان کی ملاعبت (باہم کھیل کود) سے (دور) کہاں رہ گئے؟\"\nشعبہ نے کہا: میں نے یہ حدیث عمرو بن دینار کے سامنے بیان کی تو انہوں نے کہا: میں نے یہ حدیث سیدنا جابر رضی اللہ عنہ سے سنی تھی اور انہوں نے کہا تھا:\"تم نے کنواری سے (شادی) کیوں نہ کی؟ تم اس کے ساتھ کھیلتے وہ تمہارے ساتھ کھیلتی"}],[3605,"یحییٰ بن یحییٰ اور ابو ربیع زہرانی نے ہمیں حدیث بیان کی ، یحییٰ نے کہا : حماد بن زید نے ہمیں عمرو بن دینار سے خبر دی ، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ ( میرے والد ) عبداللہ رضی اللہ عنہ نے وفات پائی اور پیچھے نو بیٹیاں ۔ ۔ یا کہا : سات بیٹیاں ۔ ۔ چھوڑیں تو میں نے ایک ثیبہ ( دوہاجو ) عورت سے نکاح کر لیا ۔ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے پوچھا : \"\" جابر! نکاح کر لیا ہے؟ \"\" میں نے عرض کی : جی ہاں ۔ آپ نے پوچھا : \"\" کنواری ہے یا دوہاجو؟ \"\" میں نے عرض کی : اللہ کے رسول! دوہاجو ہے ۔ آپ نے فرمایا : \"\" کنواری کیوں نہیں ، تم اس سے دل لگی کرتے ، وہ تم سے دل لگی کرتی ۔ ۔ یا فرمایا : تم اس کے ساتھ ہنستے کھیلتے ، وہ تمہارے ساتھ ہنستی کھیلتی ۔ ۔ \"\" میں نے آپ صلی اللہ علیہ وسلم سے عرض کی : ( میرے والد ) عبداللہ رضی اللہ عنہ نے وفات پائی اور پیچھے نو ۔ ۔ یا سات ۔ ۔ بیٹیاں چھوڑیں ، تو میں نے اچھا نہ سمجھا کہ میں ان کے پاس انہی جیسی ( کم عمر ) لے آؤں ۔ میں نے چاہا کہ ایسی عورت لاؤں جو ان کی نگہداشت کرے اور ان کی اصلاح کرے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" اللہ تمہیں برکت دے! \"\" یا آپ نے میرے لیے خیر اور بھلائی کی دعا فرمائی ۔ اور ابوربیع کی روایت میں ہے : \"\" تم اس کے ساتھ دل لگی کرتے وہ تمہارے ساتھ دل لگی کرتی اور تم اس کے ساتھ ہنستے کھیلتے ، وہ تمہارے ساتھ ہنستی کھیلتی","",{"u2":"یحییٰ بن یحییٰ اور ابو ربیع زہرانی نے ہمیں حدیث بیان کی، یحییٰ نے کہا: حماد بن زید نے ہمیں عمرو بن دینار سے خبر دی، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ (میرے والد) عبداللہ رضی اللہ عنہ نے وفات پائی اور پیچھے نو بیٹیاں۔۔ یا کہا: سات بیٹیاں۔۔ چھوڑیں تو میں نے ایک ثیبہ (دوہاجو) عورت سے نکاح کر لیا۔ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے پوچھا:\"جابر! نکاح کر لیا ہے؟\"میں نے عرض کی: جی ہاں۔ آپ نے پوچھا: \"کنواری ہے یا دوہاجو؟\" میں نے عرض کی: اللہ کے رسول! دوہاجو ہے۔ آپ نے فرمایا: \"کنواری کیوں نہیں، تم اس سے دل لگی کرتے،وہ تم سے دل لگی کرتی۔۔ یا فرمایا: تم اس کے ساتھ ہنستے کھیلتے، وہ تمہارے ساتھ ہنستی کھیلتی۔۔\" میں نے آپ صلی اللہ علیہ وسلم سے عرض کی: (میرے والد) عبداللہ رضی اللہ عنہ نے وفات پائی اور پیچھے نو۔۔ یا سات۔۔ بیٹیاں چھوڑیں، تو میں نے اچھا نہ سمجھا کہ میں ان کے پاس انہی جیسی (کم عمر) لے آؤں۔ میں نے چاہا کہ ایسی عورت لاؤں جو ان کی نگہداشت کرے اور ان کی اصلاح کرے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تمہیں برکت دے!\"یا آپ نے میرے لیے خیر اور بھلائی کی دعا فرمائی۔\nاور ابوربیع کی روایت میں ہے:\"تم اس کے ساتھ دل لگی کرتے وہ تمہارے ساتھ دل لگی کرتی اور تم اس کے ساتھ ہنستے کھیلتے، وہ تمہارے ساتھ ہنستی کھیلتی"}],[3606,"سفیان نے ہمیں عمرو سے حدیث بیان کی ، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے پوچھا : \" جابر! کیا تم نے نکاح کر لیا ہے؟ \" اور آگے یہاں تک بیان کیا : ایسی عورت جو اُن کی نگہداشت کرے اور ان کی کنگھی کرے ، آپ نے فرمایا : \" تم نے ٹھیک کیا ۔ \" اور انہوں نے اس کے بعد والا حصہ بیان نہیں کیا","",{"u2":"سفیان نے ہمیں عمرو سے حدیث بیان کی، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے پوچھا: \"جابر! کیا تم نے نکاح کر لیا ہے؟\" اور آگے یہاں تک بیان کیا: ایسی عورت جو اُن کی نگہداشت کرے اور ان کی کنگھی کرے، آپ نے فرمایا: \"تم نے ٹھیک کیا۔\" اور انہوں نے اس کے بعد والا حصہ بیان نہیں کیا"}],[3607,"شعبی نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک غزوے میں شریک تھے ۔ جب ہم واپس ہوئے تو میں نے اپنے سست رفتار اونٹ کو تھوڑا سا تیز کیا ، میرے ساتھ پیچھے سے ایک سوار آ کر ملا انہوں نے لوہے کی نوک والی چھڑی سے جو ان کے ساتھ تھی ، میرے اونٹ کو کچوکا لگایا ، تو وہ اتنا تیز چلنے لگا جتنا آپ نے کسی بہترین اونٹ کو ( تیز چلتے ہوئے ) دیکھا ، آپ نے پوچھا : \"\" جابر! تمہیں کس چیز نے جلدی میں ڈال رکھا ہے؟ \"\" میں نے عرض کی : اللہ کے رسول! میں نے نئی نئی شادی کی ہے ۔ آپ نے پوچھا : \"\" باکرہ سے شادی کی ہے یا ثیبہ ( دوہاجو ) سے؟ \"\" انہوں نے عرض کی : ثیبہ سے ۔ آپ نے فرمایا : \"\" تم نے کسی ( کنواری ) لڑکی سے کیوں نہ کی ، تم اس کے ساتھ دل لگی کرتے ، وہ تمہارے ساتھ دل لگی کرتی؟ \"\" کہا : جب ہم مدینہ آئے ، ( اس میں ) داخل ہونے لگے تو آپ نے فرمایا : \"\" ٹھہر جاؤ ، ہم رات ۔ ۔ یعنی عشاء ۔ ۔ کے وقت داخل ہوں ، تاکہ پراگندہ بالوں والی بال سنوار لے اور جس جس کا شوہر غائب رہا ، وہ بال ( وغیرہ ) صاف کر لے ۔ \"\" اور فرمایا : \"\" جب گھر پہنچنا تو عقل و تحمل سے کام لینا ( حالت حیض میں جماع نہ کرنا)","",{"u2":"شعبی نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک غزوے میں شریک تھے۔ جب ہم واپس ہوئے تو میں نے اپنے سست رفتار اونٹ کو تھوڑا سا تیز کیا، میرے ساتھ پیچھے سے ایک سوار آ کر ملا انہوں نے لوہے کی نوک والی چھڑی سے جو ان کے ساتھ تھی، میرے اونٹ کو کچوکا لگایا، تو وہ اتنا تیز چلنے لگا جتنا آپ نے کسی بہترین اونٹ کو (تیز چلتے ہوئے) دیکھا، آپ نے پوچھا: \"جابر! تمہیں کس چیز نے جلدی میں ڈال رکھا ہے؟\" میں نے عرض کی: اللہ کے رسول! میں نے نئی نئی شادی کی ہے۔ آپ نے پوچھا: \"باکرہ سے شادی کی ہے یا ثیبہ (دوہاجو) سے؟\" انہوں نے عرض کی: ثیبہ سے۔ آپ نے فرمایا: \"تم نے کسی (کنواری) لڑکی سے کیوں نہ کی، تم اس کے ساتھ دل لگی کرتے، وہ تمہارے ساتھ دل لگی کرتی؟\"\nکہا: جب ہم مدینہ آئے، (اس میں) داخل ہونے لگے تو آپ نے فرمایا: \"ٹھہر جاؤ، ہم رات۔۔ یعنی عشاء۔۔ کے وقت داخل ہوں، تاکہ پراگندہ بالوں والی بال سنوار لے اور جس جس کا شوہر غائب رہا، وہ بال (وغیرہ) صاف کر لے۔\" اور فرمایا: \"جب گھر پہنچنا تو عقل و تحمل سے کام لینا (حالت حیض میں جماع نہ کرنا"}],[3608,"وہب بن کیسان نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک غزوے میں نکلا تھا ، میرے اونٹ نے میری رفتار سست کر دی تو رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لے آئے اور فرمایا : \" جابر! \" میں نے عرض کی : جی ۔ آپ نے پوچھا : \" کیا معاملہ ہے؟ \" میں نے عرض کی : میرے لیے میرا اونٹ سست پڑ چکا ہے اور تھک گیاہے ، اس لیے میں پیچھے رہ گیا ہوں ۔ آپ ( اپنی سواری سے ) اترے اور اپنی مڑے ہوئے سرے والی چھڑی سے اسے کچوکا لگایا ، پھر فرمایا : \" سوار ہو جاؤ ۔ \" میں سوار ہو گیا ۔ اس کے بعد میں نے خود کو دیکھا کہ میں اس کو رسول اللہ صلی اللہ علیہ وسلم ( کی اونٹنی ) سے ( آگے بڑھنے سے ) روک رہا ہوں ۔ پھر آپ نے پوچھا : \" کیا تم نے شادی کر لی؟ \" میں نے عرض کی : جی ہاں ۔ آپ نے پوچھا : \" کنواری سے یا دوہاجو سے؟ \" میں نے عرض کی : دوہاجو ہے ۔ آپ نے فرمایا : \" ( کنواری ) لڑکی سے کیوں نہ کی ، تم اس کے ساتھ دل لگی کرتے ، وہ تمہارے ساتھ دل لگی کرتی ۔ \" میں نے عرض کی : میری ( چھوٹی ) بہنیں ہیں ۔ میں نے چاہا کہ ایسی عورت سے شادی کروں جو ان کی ڈھارس بندھائے ، ان کی کنگھی کرے اور ان کی نگہداشت کرے ۔ آپ نے فرمایا : \" تم ( گھر ) پہنچنے والے ہو ، جب پہنچ جاؤ تو احتیاط اور عقل مندی سے کام لینا ۔ \" پھر پوچھا : \" کیا تم اپنا اونٹ بیچو گے؟ \" میں نے عرض کی : جی ہاں ، چنانچہ آپ نے وہ ( اونٹ ) مجھ سے ایک اوقیہ ( چاندی کی قیمت ) میں خرید لیا ۔ پھر رسول اللہ صلی اللہ علیہ وسلم پہنچ گئے اور میں صبح کے وقت پہنچا ، مسجد میں آیا تو آپ کو مسجد کے دروازے پر پایا ۔ آپ صلی اللہ علیہ وسلم نے پوچھا : \" ابھی پہنچے ہو؟ \" میں نے عرض کی : جی ہاں ۔ آپ نے فرمایا : \" اپنا اونٹ چھوڑو اور مسجد میں جا کر دو رکعت نماز ادا کرو ۔ \" میں مسجد میں داخل ہوا ، نماز پڑھی ، پھر ( آپ کے پاس ) واپس آیا تو آپ نے بلال رضی اللہ عنہ کو حکم دیا کہ میرے لیے ایک اوقیہ ( چاندی ) تول دیں ، چنانچہ سیدنا بلال رضی اللہ عنہ نے وزن کیا ، اورترازو کو جھکایا ( اوقیہ سے زیادہ تولا ۔ ) کہا : اس کے بعد میں چل پڑا ، جب میں نے پیٹھ پھیری تو آپ نے فرمایا : \" جابر کو میرے پاس بلاؤ ۔ \" مجھے بلایا گیا ۔ میں نے ( دل میں ) کہا : اب آپ میرا اونٹ ( بھی ) مجھے واپس کر دیں گے ۔ اور مجھے کوئی چیز اس سے زیادہ ناپسند نہ تھی ( کہ میں قیامت وصول کرنے کے بعد آپ صلی اللہ علیہ وسلم سے اپنا اونٹ بھی واپس لے لوں ۔ ) آپ نے فرمایا : \" اپنا اونٹ لے لو اور اس کی قیمت بھی تمہاری ہے","",{"u2":"وہب بن کیسان نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک غزوے میں نکلا تھا، میرے اونٹ نے میری رفتار سست کر دی تو رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لے آئے اور فرمایا: \"جابر!\" میں نے عرض کی: جی۔ آپ نے پوچھا: \"کیا معاملہ ہے؟\" میں نے عرض کی: میرے لیے میرا اونٹ سست پڑ چکا ہے اور تھک گیاہے، اس لیے میں پیچھے رہ گیا ہوں۔ آپ (اپنی سواری سے) اترے اور اپنی مڑے ہوئے سرے والی چھڑی سے اسے کچوکا لگایا، پھر فرمایا: \"سوار ہو جاؤ۔\" میں سوار ہو گیا۔ اس کے بعد میں نے خود کو دیکھا کہ میں اس کو رسول اللہ صلی اللہ علیہ وسلم (کی اونٹنی) سے (آگے بڑھنے سے) روک رہا ہوں۔ پھر آپ نے پوچھا: \"کیا تم نے شادی کر لی؟\" میں نے عرض کی: جی ہاں۔ آپ نے پوچھا: \"کنواری سے یا دوہاجو سے؟\" میں نے عرض کی: دوہاجو ہے۔ آپ نے فرمایا: \"(کنواری) لڑکی سے کیوں نہ کی، تم اس کے ساتھ دل لگی کرتے، وہ تمہارے ساتھ دل لگی کرتی۔\" میں نے عرض کی: میری (چھوٹی) بہنیں ہیں۔ میں نے چاہا کہ ایسی عورت سے شادی کروں جو ان کی ڈھارس بندھائے، ان کی کنگھی کرے اور ان کی نگہداشت کرے۔ آپ نے فرمایا: \"تم (گھر) پہنچنے والے ہو، جب پہنچ جاؤ تو احتیاط اور عقل مندی سے کام لینا۔\" پھر پوچھا: \"کیا تم اپنا اونٹ بیچو گے؟\" میں نے عرض کی: جی ہاں، چنانچہ آپ نے وہ (اونٹ) مجھ سے ایک اوقیہ (چاندی کی قیمت) میں خرید لیا۔ پھر رسول اللہ صلی اللہ علیہ وسلم پہنچ گئے اور میں صبح کے وقت پہنچا، مسجد میں آیا تو آپ کو مسجد کے دروازے پر پایا۔ آپ صلی اللہ علیہ وسلم نے پوچھا: \"ابھی پہنچے ہو؟\" میں نے عرض کی: جی ہاں۔ آپ نے فرمایا: \"اپنا اونٹ چھوڑو اور مسجد میں جا کر دو رکعت نماز ادا کرو۔\" میں مسجد میں داخل ہوا، نماز پڑھی، پھر (آپ کے پاس) واپس آیا تو آپ نے بلال رضی اللہ عنہ کو حکم دیا کہ میرے لیے ایک اوقیہ (چاندی) تول دیں، چنانچہ سیدنا بلال رضی اللہ عنہ نے وزن کیا، اورترازو کو جھکایا (اوقیہ سے زیادہ تولا۔) کہا: اس کے بعد میں چل پڑا، جب میں نے پیٹھ پھیری تو آپ نے فرمایا: \"جابر کو میرے پاس بلاؤ۔\" مجھے بلایا گیا۔ میں نے (دل میں) کہا: اب آپ میرا اونٹ (بھی) مجھے واپس کر دیں گے۔ اور مجھے کوئی چیز اس سے زیادہ ناپسند نہ تھی (کہ میں قیامت وصول کرنے کے بعد آپ صلی اللہ علیہ وسلم سے اپنا اونٹ بھی واپس لے لوں۔) آپ نے فرمایا: \"اپنا اونٹ لے لو اور اس کی قیمت بھی تمہاری ہے"}],[3609,"ابونضرہ نے ہمیں سیدنا جابر بن عبداللہ رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں تھے ، اور میں ایک پانی ڈھونے والے اونٹ پر ( سوار ) تھا ۔ اور وہ پیچھے رہ جانے والے لوگوں کے ساتھ تھا ۔ کہا : آپ نے اسے ۔ ۔ میرا خیال ہے ، انہوں نے کہا : اپنے پاس موجود کسی چیز سے ۔ ۔ مارا ، یا کہا : کچوکا لگایا ، کہا : اس کے بعد وہ لوگوں ( کے اونٹوں ) سے آگے نکلنے لگا ، وہ مجھ سے کھینچا تانی کرنے لگا حتیٰ کہ مجھے اس کو روکنا پڑتا تھا ۔ کہا : اس کے بعد رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" کیا تم مجھے یہ اتنے اتنے میں بیچو گے؟ اللہ تمہیں معاف فرمائے! \"\" کہا : میں نے عرض کی ۔ اللہ کے نبی! وہ آپ ہی کا ہے ۔ آپ نے ( دوبارہ ) پوچھا : \"\" کیا تم مجھے وہ اتنے اتنے میں بیچو گے؟ اللہ تمہارے گناہ معاف فرمائے! \"\" کہا : میں نے عرض کی : اللہ کے نبی! وہ آپ کا ہے ۔ کہا : اور آپ نے مجھ سے ( یہ بھی ) پوچھا : \"\" کیا اپنے والد ( کی وفات ) کے بعد تم نے نکاح کر لیا ہے؟ \"\" میں نے عرض کی : جی ہاں ۔ آپ نے پوچھا : \"\" دوہاجو ( شوہر دیدہ ) سے یا دوشیزہ سے؟ \"\" میں نے عرض کی : دوہاجو سے ۔ آپ نے فرمایا : \"\" تم نے کنواری سے کیوں نہ شادی کی ، وہ تمہارے ساتھ ہنستی کھیلتی اور تم اس کے ساتھ ہنستے کھیلتے اور وہ تمہارے ساتھ دل لگی کرتی ، تم اس کے ساتھ دل لگی کرتے؟ \"\" ابونضرہ نے کہا : یہ ایسا کلمہ تھا جسے مسلمان ( محاورتا ) کہتے تھے کہ ایسے ایسے کرو ، اللہ تمہارے گناہ بخش دے","",{"u2":"ابونضرہ نے ہمیں سیدنا جابر بن عبداللہ رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں تھے، اور میں ایک پانی ڈھونے والے اونٹ پر (سوار) تھا۔ اور وہ پیچھے رہ جانے والے لوگوں کے ساتھ تھا۔ کہا: آپ نے اسے۔۔ میرا خیال ہے، انہوں نے کہا: اپنے پاس موجود کسی چیز سے۔۔ مارا، یا کہا: کچوکا لگایا، کہا: اس کے بعد وہ لوگوں (کے اونٹوں) سے آگے نکلنے لگا، وہ مجھ سے کھینچا تانی کرنے لگا حتیٰ کہ مجھے اس کو روکنا پڑتا تھا۔ کہا: اس کے بعد رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم مجھے یہ اتنے اتنے میں بیچو گے؟ اللہ تمہیں معاف فرمائے!\" کہا: میں نے عرض کی۔ اللہ کے نبی! وہ آپ ہی کا ہے۔ آپ نے (دوبارہ) پوچھا: \"کیا تم مجھے وہ اتنے اتنے میں بیچو گے؟ اللہ تمہارے گناہ معاف فرمائے!\" کہا: میں نے عرض کی: اللہ کے نبی! وہ آپ کا ہے۔ کہا: اور آپ نے مجھ سے (یہ بھی) پوچھا: \"کیا اپنے والد (کی وفات) کے بعد تم نے نکاح کر لیا ہے؟\" میں نے عرض کی: جی ہاں۔ آپ نے پوچھا: \"دوہاجو (شوہر دیدہ) سے یا دوشیزہ سے؟\" میں نے عرض کی: دوہاجو سے۔ آپ نے فرمایا: \"تم نے کنواری سے کیوں نہ شادی کی، وہ تمہارے ساتھ ہنستی کھیلتی اور تم اس کے ساتھ ہنستے کھیلتے اور وہ تمہارے ساتھ دل لگی کرتی، تم اس کے ساتھ دل لگی کرتے؟\"\nابونضرہ نے کہا: یہ ایسا کلمہ تھا جسے مسلمان (محاورتا) کہتے تھے کہ ایسے ایسے کرو، اللہ تمہارے گناہ بخش دے"}],[3610,"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" عورت کو پسلی سے پیدا کیا گیا ہے ، وہ تمہارے لیے کسی ایک طریقے پر ہرگز سیدھی نہیں رہ سکتی ، اگر تم اس سے فائدہ اٹھانا چاہو تو ( اسی طرح ) فائدہ اٹھا لو گے کہ اس میں کجی رہے گی اور اگر تم اسے سیدھا کرنے چلو گے تو اسے توڑ ڈالو گے ، اور اسے توڑنا اس کی طلاق ہے"],[3611,"ابوحازم نے سیدنا ابوہریرہ رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" جو اللہ اور قیامت کے دن پر ایمان رکھتا ہے جب ( اپنی بیوی میں ) کوئی ( پسند نہ آنے والا ) معاملہ دیکھے تو اچھی طرح سے بات کہے یا خاموش رہے ۔ اور عورتوں کے ساتھ اچھے سلوک کی نصیحت قبول کرو کیونکہ عورت پسلی سے پیدا کی گئی ہے ۔ اور پسلیوں میں سب سے زیادہ ٹیڑھ اس کے اوپر والے حصے میں ہے ۔ اگر تم اسے سیدھا کرنے لگ جاؤ گے تو اسے توڑ دو گے اور اگر چھوڑ دو گے تو وہ ٹیڑھی ہی رہے گی ، عورتوں کے ساتھ اچھے سلوک کی نصیحت قبول کرو","",{"u2":"یونس نے مجھے ابن شہاب سے خبر دی، کہا: مجھے ابن مسیب نے سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بلاشبہ عورت پسلی کی طرح ہے، اگر تم اسے سیدھا کرنے لگ جاؤ گے تو اسے توڑ ڈالو گے اور اگر اسے چھوڑ دو گے تو اس سے فائدہ اٹھاؤ گے جبکہ اس میں ٹیڑھا پن (موجود) ہو گا"}],[3612,"عیسیٰ بن یونس نے ہمیں حدیث بیان کی ، کہا : ہمیں عبدالحمید بن جعفر نے عمران بن ابی انس سے حدیث سنائی ، انہوں نے عمر بن حکم سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا : \" کوئی مومن مرد کسی مومنہ عورت سے بغض نہ رکھے ۔ اگر اسے اس کی کوئی عادت ناپسند ہے تو دوسری پسند ہو گی ۔ \" یا آپ نے غيره ( اس کے سوا کوئی اور ) فرمایا","",{"u2":"زہری کے بھتیجے نے اپنے چچا (زہری) سے اسی سند کے ساتھ بالکل اسی کے مانند روایت کی"}],[3613,"ابوعاصم نے ہمیں حدیث بیان کی ، کہا : ہمیں عبدالحمید بن جعفر نے سابقہ سند کے ساتھ سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ۔ ۔ ۔ اسی کے مانند","",{"u2":"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عورت کو پسلی سے پیدا کیا گیا ہے، وہ تمہارے لیے کسی ایک طریقے پر ہرگز سیدھی نہیں رہ سکتی، اگر تم اس سے فائدہ اٹھانا چاہو تو (اسی طرح) فائدہ اٹھا لو گے کہ اس میں کجی رہے گی اور اگر تم اسے سیدھا کرنے چلو گے تو اسے توڑ ڈالو گے، اور اسے توڑنا اس کی طلاق ہے"}],[3614,"ابوہریرہ رضی اللہ عنہ کے آزاد کردہ غلام ابو یونس نے سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" اگر حواء ( علیہا السلام ) نہ ہوتیں تو کوئی عورت اپنے شوہر سے کبھی خیانت نہ کرتی","",{"u2":"ابوحازم نے سیدنا ابوہریرہ رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو اللہ اور قیامت کے دن پر ایمان رکھتا ہے جب (اپنی بیوی میں) کوئی (پسند نہ آنے والا) معاملہ دیکھے تو اچھی طرح سے بات کہے یا خاموش رہے۔ اور عورتوں کے ساتھ اچھے سلوک کی نصیحت قبول کرو کیونکہ عورت پسلی سے پیدا کی گئی ہے۔ اور پسلیوں میں سب سے زیادہ ٹیڑھ اس کے اوپر والے حصے میں ہے۔ اگر تم اسے سیدھا کرنے لگ جاؤ گے تو اسے توڑ دو گے اور اگر چھوڑ دو گے تو وہ ٹیڑھی ہی رہے گی، عورتوں کے ساتھ اچھے سلوک کی نصیحت قبول کرو"}],[3615,"ہمام بن منبہ سے روایت ہے ، انہوں نے کہا : یہ احادیث ہیں جو سیدنا ابوہریرہ رضی اللہ عنہ نے ہمیں رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں ، پھر انہوں نے متعدد احادیث بیان کیں ، ان میں ایک یہ تھی : اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اگر بنی اسرائیل نہ ہوتے تو کھانا خراب نہ ہوتا اور گوشت بدبودار نہ ہوتا اور اگر حواء علیہا السلام نہ ہوتیں تو کوئی عورت اپنے شوہر سے خیانت نہ کرتی","",{"u2":"عیسیٰ بن یونس نے ہمیں حدیث بیان کی، کہا: ہمیں عبدالحمید بن جعفر نے عمران بن ابی انس سے حدیث سنائی، انہوں نے عمر بن حکم سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا: \"کوئی مومن مرد کسی مومنہ عورت سے بغض نہ رکھے۔ اگر اسے اس کی کوئی عادت ناپسند ہے تو دوسری پسند ہو گی۔\" یا آپ نے غیرہ (اس کے سوا کوئی اور) فرمایا"}],[3616,"سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" دنیا متاع ( کچھ وقت تک کے لیے فائدہ اٹھانے کی چیز ) ہے اور دنیا کی بہترین متاع نیک عورت ہے","",{"u2":"ابوعاصم نے ہمیں حدیث بیان کی، کہا: ہمیں عبدالحمید بن جعفر نے سابقہ سند کے ساتھ سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کی، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی۔۔۔ اسی کے مانند"}],[3617,"یونس نے مجھے ابن شہاب سے خبر دی ، کہا : مجھے ابن مسیب نے سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" بلاشبہ عورت پسلی کی طرح ہے ، اگر تم اسے سیدھا کرنے لگ جاؤ گے تو اسے توڑ ڈالو گے اور اگر اسے چھوڑ دو گے تو اس سے فائدہ اٹھاؤ گے جبکہ اس میں ٹیڑھا پن ( موجود ) ہو گا","",{"u2":"ابوہریرہ رضی اللہ عنہ کے آزاد کردہ غلام ابو یونس نے سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کی، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"اگر حواء (علیہا السلام) نہ ہوتیں تو کوئی عورت اپنے شوہر سے کبھی خیانت نہ کرتی"}],[3618,"زہری کے بھتیجے نے اپنے چچا ( زہری ) سے اسی سند کے ساتھ بالکل اسی کے مانند روایت کی","",{"u2":"ہمام بن منبہ سے روایت ہے، انہوں نے کہا: یہ احادیث ہیں جو سیدنا ابوہریرہ رضی اللہ عنہ نے ہمیں رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں، پھر انہوں نے متعدد احادیث بیان کیں، ان میں ایک یہ تھی: اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر بنی اسرائیل نہ ہوتے تو کھانا خراب نہ ہوتا اور گوشت بدبودار نہ ہوتا اور اگر حواء علیہا السلام نہ ہوتیں تو کوئی عورت اپنے شوہر سے خیانت نہ کرتی"}],[3619,"امام مالک بن انس نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے عہد میں اپنی بیوی کو جبکہ وہ حائضہ تھی ، طلاق دے دی ، سیدنا عمر بن خطاب رضی اللہ عنہ نے اس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے پوچھا تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا : \" اسے حکم دو کہ وہ اس سے رجوع کرے ، پھر اسے رہنے دے حتی کہ وہ پاک ہو جائے ( طہر شروع ہو جائے ) ، پھر اسے حیض آ جائے ، پھر وہ پاک ہو جائے ۔ پھر اگر وہ چاہے تو اس کے بعد اسے اپنے پاس رکھے اور اگر چاہے تو اس سے مجامعت کرنے سے پہلے طلاق دے دے ۔ یہی وہ عدت ہے جس کا اللہ نے حکم دیا ہے کہ اس کے مطابق عورتوں کو طلاق دی جائے","",{"u2":"امام مالک بن انس نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے عہد میں اپنی بیوی کو جبکہ وہ حائضہ تھی، طلاق دے دی، سیدنا عمر بن خطاب رضی اللہ عنہ نے اس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے پوچھا تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"اسے حکم دو کہ وہ اس سے رجوع کرے، پھر اسے رہنے دے حتی کہ وہ پاک ہو جائے (طہر شروع ہو جائے)، پھر اسے حیض آ جائے، پھر وہ پاک ہو جائے۔ پھر اگر وہ چاہے تو اس کے بعد اسے اپنے پاس رکھے اور اگر چاہے تو اس سے مجامعت کرنے سے پہلے طلاق دے دے۔ یہی وہ عدت ہے جس کا اللہ نے حکم دیا ہے کہ اس کے مطابق عورتوں کو طلاق دی جائے"}],[3620,"یحییٰ بن یحییٰ ، قتیبہ بن سعید اور ابن رمح نے ہمیں حدیث بیان کی ۔ ۔ الفاظ یحییٰ کے ہیں ۔ ۔ قتیبہ نے کہا : ہمیں لیث نے حدیث سنائی اور دوسرے دونوں نے کہا : ہمیں لیث بن سعد نے نافع سے خبر دی ، انہوں نے کہا : سیدنا عبداللہ ( بن عمر رضی اللہ عنہ ) سے روایت ہے کہ انہوں نے اپنی بیوی کو جب وہ حیض کی حالت میں تھی ایک طلاق دی ، تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ وہ اس سے رجوع کریں ، پھر اسے ( اپنے پاس ) روکیں حتی کہ وہ پاک ہو جائے ، پھر ان کے ہاں اسے دوبارہ حیض آئے ، پھر اسے مہلت دیں حتی کہ وہ ( پھر سے ) اپنے حیض سے پاک ہو جائے ۔ اس کے بعد اگر اسے طلاق دینا چاہیں تو طہر کے زمانے میں ، اس کے ساتھ مجامعت کرنے سے پہلے اسے طلاق دیں ، یہی وہ عدت ہے جس کا اللہ نے حکم دیا ہے کہ اس کے مطابق عورتوں کو طلاق دی جائے ۔ ابن رمح نے اپنی روایت میں یہ اضافہ کیا : سیدنا عبداللہ رضی اللہ عنہ سے جب اس ( مسئلہ ) کے بارے میں سوال کیا جاتا تو وہ ان میں سے کسی سے کہتے : اگر تم نے اپنی بیوی کو ایک یا دو مرتبہ طلاق دی ہے ( تو رجوع کرو ) کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے اس کا حکم دیا تھا ۔ اور اگر تم اسے تین طلاقیں دے چکے ہو تو وہ تم پر حرام ہو گئی ہے یہاں تک کہ وہ تمہارے سواکسی اور شوہر سے نکاح کرے ۔ تم نے اس حکم میں ، جو اس نے تمہاری بیوی کی طلاق کے بارے میں تمہیں دیا ہے ، اللہ کی نافرمانی کی ہے ۔ امام مسلم رحمۃ اللہ علیہ نے کہا : لیث نے اپنے ( روایت کردہ ) قول \"\" ایک طلاق \"\" ( کو محفوظ رکھنے اور بیان کرنے کے معاملے ) میں بہت اچھا کام کیا ہے","",{"u2":"یحییٰ بن یحییٰ، قتیبہ بن سعید اور ابن رمح نے ہمیں حدیث بیان کی۔۔ الفاظ یحییٰ کے ہیں۔۔ قتیبہ نے کہا: ہمیں لیث نے حدیث سنائی اور دوسرے دونوں نے کہا: ہمیں لیث بن سعد نے نافع سے خبر دی، انہوں نے کہا: حضرت عبداللہ (بن عمر رضی اللہ عنہ) سے روایت ہے کہ انہوں نے اپنی بیوی کو جب وہ حیض کی حالت میں تھی ایک طلاق دی، تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ وہ اس سے رجوع کریں، پھر اسے (اپنے پاس) روکیں حتی کہ وہ پاک ہو جائے، پھر ان کے ہاں اسے دوبارہ حیض آئے، پھر اسے مہلت دیں حتی کہ وہ (پھر سے) اپنے حیض سے پاک ہو جائے۔ اس کے بعد اگر اسے طلاق دینا چاہیں تو طہر کے زمانے میں، اس کے ساتھ مجامعت کرنے سے پہلے اسے طلاق دیں، یہی وہ عدت ہے جس کا اللہ نے حکم دیا ہے کہ اس کے مطابق عورتوں کو طلاق دی جائے۔\nابن رمح نے اپنی روایت میں یہ اضافہ کیا: سیدنا عبداللہ رضی اللہ عنہ سے جب اس (مسئلہ) کے بارے میں سوال کیا جاتا تو وہ ان میں سے کسی سے کہتے: اگر تم نے اپنی بیوی کو ایک یا دو مرتبہ طلاق دی ہے (تو رجوع کرو) کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے اس کا حکم دیا تھا۔ اور اگر تم اسے تین طلاقیں دے چکے ہو تو وہ تم پر حرام ہو گئی ہے یہاں تک کہ وہ تمہارے سواکسی اور شوہر سے نکاح کرے۔ تم نے اس حکم میں، جو اس نے تمہاری بیوی کی طلاق کے بارے میں تمہیں دیا ہے،اللہ کی نافرمانی کی ہے۔\nامام مسلم رحمۃ اللہ علیہ نے کہا: لیث نے اپنے (روایت کردہ) قول \"ایک طلاق\" (کو محفوظ رکھنے اور بیان کرنے کے معاملے) میں بہت اچھا کام کیا ہے"}],[3621,"عبداللہ بن نمیر نے ہمیں حدیث بیان کی ، ( کہا : ) ہمیں عبیداللہ نے نافع سے حدیث بیان کی ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں اپنی بیوی کو جب وہ حیض کی حالت میں تھی ، طلاق دے دی ۔ سیدنا عمر رضی اللہ عنہ نے یہ بات رسول اللہ صلی اللہ علیہ وسلم کو بتائی تو آپ نے فرمایا : \"\" اسے حکم دو کہ اس سے رجوع کرے پھر اسے ( اپنے پاس رکھ ) چھوڑے حتی کہ وہ پاک ہو جائے ، پھر اسے دوسرا حیض آئے ، اس کے بعد جب وہ پاک ہو جائے تو مباشرت کرنے سے پہلے اسے طلاق دے یا اسے اپنے پاس رکھے ۔ بلاشبہ یہی وہ عدت ہے جس کا اللہ تعالیٰ نے حکم دیا ہے کہ اس کے مطابق عورتوں کو طلاق دی جائے ۔ \"\" عبیداللہ نے کہا : میں نے نافع سے پوچھا : طلاق کا کیا کیا گیا؟ انہوں نے جواب دیا : وہ ایک تھی ، اس کو شمار کیا گیا","",{"u2":"عبداللہ بن نمیر نے ہمیں حدیث بیان کی، (کہا:) ہمیں عبیداللہ نے نافع سے حدیث بیان کی، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں اپنی بیوی کو جب وہ حیض کی حالت میں تھی، طلاق دے دی۔ سیدنا عمر رضی اللہ عنہ نے یہ بات رسول اللہ صلی اللہ علیہ وسلم کو بتائی تو آپ نے فرمایا: \"اسے حکم دو کہ اس سے رجوع کرے پھر اسے (اپنے پاس رکھ) چھوڑے حتی کہ وہ پاک ہو جائے، پھر اسے دوسرا حیض آئے، اس کے بعد جب وہ پاک ہو جائے تو مباشرت کرنے سے پہلے اسے طلاق دے یا اسے اپنے پاس رکھے۔ بلاشبہ یہی وہ عدت ہے جس کا اللہ تعالیٰ نے حکم دیا ہے کہ اس کے مطابق عورتوں کو طلاق دی جائے۔\"\nعبیداللہ نے کہا: میں نے نافع سے پوچھا: طلاق کا کیا کیا گیا؟ انہوں نے جواب دیا: وہ ایک تھی، اس کو شمار کیا گیا"}],[3622,"ابوبکر بن ابی شیبہ اور ابن مثنیٰ نے بھی ہمیں یہی حدیث سنائی ، ان دونوں نے کہا : ہمیں عبداللہ بن ادریس نے عبیداللہ سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی ، تاہم انہوں نے نافع سے عبیداللہ کے سوال کا تذکرہ نہیں کیا ۔ ابن مثنیٰ نے اپنی روایت میں فليرجعها ( اسے لوٹا لے ) کہا ۔ اور ابوبکر نے : فليراجعها ( اس سے رجوع کرے ) کہا"],[3623,"ایوب نے نافع سے روایت کی کہ سیدنا ابن عمر رضی اللہ عنہ نے اپنی بیوی کو حیض کی حالت میں طلاق دے دی ۔ سیدنا عمر رضی اللہ عنہ نے ( اس کے بارے میں ) نبی صلی اللہ علیہ وسلم سے سوال کیا ، تو آپ نے انہیں حکم دیا کہ وہ ( ابن عمر رضی اللہ عنہ ) اس عورت سے رجوع کرے ، پھر اسے مہلت دے حتی کہ اسے دوسرا حیض آئے ، پھر اسے مہلت دے حتی کہ وہ پاک ہو جائے ، پھر اسے چھونے ( مجامعت کرنے ) سے پہلے طلاق دے ، یہی وہ عدت ہے جس کا اللہ تعالیٰ نے حکم دیا ہے کہ اس کے مطابق عورتوں کو طلاق دی جائے ۔ ( نافع نے ) کہا : سیدنا ابن عمر رضی اللہ عنہ سے جب اس آدمی کے بارے میں پوچھا جاتا جو اپنی بیوی کو حالت حیض میں طلاق دے دیتا ہے تو وہ کہتے : اگر تم نے ایک یا دو طلاقیں دی ہیں ( تو رجوع کر سکتے ہو کیو کہ ) رسول اللہ صلی اللہ علیہ وسلم نے انہیں حکم دیا تھا کہ اس سے رجوع کریں ، پھر اسے مہلت دیں حتی کہ اسے دوسرا حیض آئے ، ( فرمایا : ) پھر اسے مہلت دیں حتی کہ وہ پاک ہو جائے ، پھر اس سے مجامعت کرنے سے پہلے اسے طلاق دیں ۔ اور اگر تم نے تین طلاقیں دی ہیں تو تم نے اپنے رب کے حکم میں جو اس نے تمہاری بیوی کی طلاق کے حوالے سے تمہیں دیا ہے ، اس کی نافرمانی کی ہے اور ( اب ) وہ تم سے ( مستقل طور پر ) جدا ہو گئی ہے","",{"u2":"ابوبکر بن ابی شیبہ اور ابن مثنیٰ نے بھی ہمیں یہی حدیث سنائی، ان دونوں نے کہا: ہمیں عبداللہ بن ادریس نے عبیداللہ سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی، تاہم انہوں نے نافع سے عبیداللہ کے سوال کا تذکرہ نہیں کیا۔\nابن مثنیٰ نے اپنی روایت میں فلیرجعہا (اسے لوٹا لے) کہا۔اور ابوبکر نے: فلیراجعہا (اس سے رجوع کرے) کہا"}],[3624,"امام زہری کے بھتیجے محمد نے ہمیں اپنے چچا زہری سے حدیث بیان کی ، ( کہا : ) ہمیں سالم بن عبداللہ نے خبر دی کہ سیدنا عبداللہ بن عمر رضی اللہ عنہ نے کہا : میں نے اپنی بیوی کو اس حالت میں طلاق دی کہ وہ حائضہ تھی ، سیدنا عمر رضی اللہ عنہ نے یہ بات نبی صلی اللہ علیہ وسلم کو بتائی تو رسول اللہ صلی اللہ علیہ وسلم سخت غصے میں آئے ، پھر فرمایا : \" اسے حکم دو کہ اس سے رجوع کرے تا آنکہ اسے اس حیض کے سوا جس میں اس نے اسے طلاق دی ہے دوسرا حیض شروع ہو جائے ۔ اس کے بعد اگر وہ اسے طلاق دینا چاہے تو اسے ( دوسرے حیض کے بعد ) پاک ہونے کی حالت میں ، مباشرت کرنے سے پہلے طلاق دے ، یہی عدت کے مطابق طلاق ہے جس طرح اللہ نے حکم دیا ہے ۔ \" اور سیدنا عبداللہ ( بن عمر رضی اللہ عنہ ) نے اسے ایک طلاق دی تھی اور اس کی وہ طلاق شمار کی گئی اور عبداللہ رضی اللہ عنہ نے ، جس طرح رسول اللہ صلی اللہ علیہ وسلم نے انہیں حکم دیا تھا ، اس سے رجوع کیا","",{"u2":"ایوب نے نافع سے روایت کی کہ سیدنا ابن عمر رضی اللہ عنہ نے اپنی بیوی کو حیض کی حالت میں طلاق دے دی۔ سیدنا عمر رضی اللہ عنہ نے (اس کے بارے میں) نبی صلی اللہ علیہ وسلم سے سوال کیا، تو آپ نے انہیں حکم دیا کہ وہ (ابن عمر رضی اللہ عنہ) اس عورت سے رجوع کرے، پھر اسے مہلت دے حتی کہ اسے دوسرا حیض آئے، پھر اسے مہلت دے حتی کہ وہ پاک ہو جائے، پھر اسے چھونے (مجامعت کرنے) سے پہلے طلاق دے، یہی وہ عدت ہے جس کا اللہ تعالیٰ نے حکم دیا ہے کہ اس کے مطابق عورتوں کو طلاق دی جائے۔ (نافع نے) کہا: سیدنا ابن عمر رضی اللہ عنہ سے جب اس آدمی کے بارے میں پوچھا جاتا جو اپنی بیوی کو حالت حیض میں طلاق دے دیتا ہے تو وہ کہتے: اگر تم نے ایک یا دو طلاقیں دی ہیں (تو رجوع کر سکتے ہو کیو کہ) رسول اللہ صلی اللہ علیہ وسلم نے انہیں حکم دیا تھا کہ اس سے رجوع کریں، پھر اسے مہلت دیں حتی کہ اسے دوسرا حیض آئے، (فرمایا:) پھر اسے مہلت دیں حتی کہ وہ پاک ہو جائے، پھر اس سے مجامعت کرنے سے پہلے اسے طلاق دیں۔ اور اگر تم نے تین طلاقیں دی ہیں تو تم نے اپنے رب کے حکم میں جو اس نے تمہاری بیوی کی طلاق کے حوالے سے تمہیں دیا ہے، اس کی نافرمانی کی ہے اور (اب) وہ تم سے (مستقل طور پر) جدا ہو گئی ہے"}],[3625,"زبیدی نے زہری سے اسی سند کے ساتھ یہ حدیث بیان کی ، لیکن انہوں نے کہا : سیدنا ابن عمر رضی اللہ عنہ نے فرمایا : میں نے اس سے رجوع کر لیا اور اس کی وہ طلاق شمار کر لی گئی جو میں نے اسے دی تھی","",{"u2":"امام زہری کے بھتیجے محمد نے ہمیں اپنے چچا زہری سے حدیث بیان کی، (کہا:) ہمیں سالم بن عبداللہ نے خبر دی کہ سیدنا عبداللہ بن عمر رضی اللہ عنہ نے کہا: میں نے اپنی بیوی کو اس حالت میں طلاق دی کہ وہ حائضہ تھی، سیدنا عمر رضی اللہ عنہ نے یہ بات نبی صلی اللہ علیہ وسلم کو بتائی تو رسول اللہ صلی اللہ علیہ وسلم سخت غصے میں آئے، پھر فرمایا: \"اسے حکم دو کہ اس سے رجوع کرے تا آنکہ اسے اس حیض کے سوا جس میں اس نے اسے طلاق دی ہے دوسرا حیض شروع ہو جائے۔ اس کے بعد اگر وہ اسے طلاق دینا چاہے تو اسے (دوسرے حیض کے بعد) پاک ہونے کی حالت میں، مباشرت کرنے سے پہلے طلاق دے، یہی عدت کے مطابق طلاق ہے جس طرح اللہ نے حکم دیا ہے۔\" اور حضرت عبداللہ (بن عمر رضی اللہ عنہ) نے اسے ایک طلاق دی تھی اور اس کی وہ طلاق شمار کی گئی اور عبداللہ رضی اللہ عنہ نے، جس طرح رسول اللہ صلی اللہ علیہ وسلم نے انہیں حکم دیا تھا، اس سے رجوع کیا"}],[3626,"ابوطلحہ کے آزاد کردہ غلام محمد بن عبدالرحمٰن نے سالم سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ انہوں نے اپنی بیوی کو جبکہ وہ حائضہ تھی ، طلاق دے دی ۔ سیدنا عمر رضی اللہ عنہ نے یہ بات نبی صلی اللہ علیہ وسلم سے عرض کی تو آپ نے فرمایا : \" اسے حکم دو کہ وہ اس ( مطلقہ بیوی ) سے رجوع کرے ، پھر اسے حالت طہر میں یا حالت حمل میں طلاق دے ۔ \" ( حمل میں طلاق دی جائے گی تو وضع حمل تک آسانی سے عدت کا شمار ہو سکے گا)","",{"u2":"زبیدی نے زہری سے اسی سند کے ساتھ یہ حدیث بیان کی، لیکن انہوں نے کہا: سیدنا ابن عمر رضی اللہ عنہ نے فرمایا: میں نے اس سے رجوع کر لیا اور اس کی وہ طلاق شمار کر لی گئی جو میں نے اسے دی تھی\nابوطلحہ کے آزاد کردہ غلام محمد بن عبدالرحمٰن نے سالم سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ انہوں نے اپنی بیوی کو جبکہ وہ حائضہ تھی، طلاق دے دی۔ سیدنا عمر رضی اللہ عنہ نے یہ بات نبی صلی اللہ علیہ وسلم سے عرض کی تو آپ نے فرمایا: \"اسے حکم دو کہ وہ اس (مطلقہ بیوی) سے رجوع کرے، پھر اسے حالت طہر میں یا حالت حمل میں طلاق دے۔\" (حمل میں طلاق دی جائے گی تو وضع حمل تک آسانی سے عدت کا شمار ہو سکے گا"}],[3627,"عبداللہ بن دینار نے ابن عمر رضی اللہ عنہ سے حدیث بیان کی کہ انہوں نے اپنی بیوی کو جبکہ وہ حائضہ تھی طلاق دی ، سیدنا عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے بارے میں پوچھا تو آپ نے فرمایا : \" اسے حکم دو کہ اس سے رجوع کرے یہاں تک کہ وہ ( حیض سے ) پاک ہو جائے ، پھر اسے دوبارہ حیض آ جائے ، پھر پاک ہو جائے ، پھر اس کے بعد اسے طلاق دے یا ( اپنے پاس ) روک لے","",{"u2":"عبداللہ بن دینار نے ابن عمر رضی اللہ عنہ سے حدیث بیان کی کہ انہوں نے اپنی بیوی کو جبکہ وہ حائضہ تھی طلاق دی، سیدنا عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے بارے میں پوچھا تو آپ نے فرمایا: \"اسے حکم دو کہ اس سے رجوع کرے یہاں تک کہ وہ (حیض سے) پاک ہو جائے، پھر اسے دوبارہ حیض آ جائے، پھر پاک ہو جائے، پھر اس کے بعد اسے طلاق دے یا (اپنے پاس) روک لے"}],[3628,"اسماعیل بن ابراہیم نے ہمیں ایوب سے حدیث بیان کی ، انہوں نے ابن سیرین سے روایت کی ، انہوں نے کہا : میں نے بیس سال توقف کیا ، مجھے ایسے لوگ جنہیں میں مہتم نہیں سمجھتا تھا حدیث بیان کرتے رہے کہ سیدنا ابن عمر رضی اللہ عنہ نے اپنی بیوی کو جبکہ وہ حائضہ تھی تین طلاقیں دیں تو انہیں اس سے رجوع کرنے کا حکم دیا گیا ۔ میں نے یہ کیا کہ میں انہیں مہتم نہیں کرتا تھا لیکن حدیث ( کی حقیقت ) کو بھی نہیں جانتا تھا ، یہاں تک کہ میری ملاقات ابوغلاب یونس بن جبیر باہلی سے ہوئی ۔ وہ بہت ضبط والے تھے ۔ ( حدیث کو بہت اچھی طرح یاد رکھنے والے تھے ) انہوں نے مجھے حدیث بیان کی کہ انہوں نے خود ابن عمر رضی اللہ عنہ سے پوچھا تھا ، انہوں نے ان کو حدیث بیان کی کہ انہوں نے اپنی بیوی کو حیض کی حالت میں ایک طلاق دی تھی تو انہیں کم دیا گیا کہ وہ اس سے رجوع کریں ۔ کہا : میں نے عرض کی : کیا اسے طلاق شمار کیا گیا؟ انہوں نے جواب دیا : کیوں نہیں! اگر کوئی ( آدمی ) خود ہی ( صحیح طریقے پر طلاق دینے سے ) عاجز آ گیا ہو اور ( حالت حیض میں طلاق دے کر ) حماقت سے کام لیا ہو ( تو کیا طلاق نہ ہو گی)","",{"u2":"اسماعیل بن ابراہیم نے ہمیں ایوب سے حدیث بیان کی، انہوں نے ابن سیرین سے روایت کی، انہوں نے کہا: میں نے بیس سال توقف کیا، مجھے ایسے لوگ جنہیں میں مہتم نہیں سمجھتا تھا حدیث بیان کرتے رہے کہ سیدنا ابن عمر رضی اللہ عنہ نے اپنی بیوی کو جبکہ وہ حائضہ تھی تین طلاقیں دیں تو انہیں اس سے رجوع کرنے کا حکم دیا گیا۔ میں نے یہ کیا کہ میں انہیں مہتم نہیں کرتا تھا لیکن حدیث (کی حقیقت) کو بھی نہیں جانتا تھا، یہاں تک کہ میری ملاقات ابوغلاب یونس بن جبیر باہلی سے ہوئی۔ وہ بہت ضبط والے تھے۔ (حدیث کو بہت اچھی طرح یاد رکھنے والے تھے) انہوں نے مجھے حدیث بیان کی کہ انہوں نے خود ابن عمر رضی اللہ عنہ سے پوچھا تھا، انہوں نے ان کو حدیث بیان کی کہ انہوں نے اپنی بیوی کو حیض کی حالت میں ایک طلاق دی تھی تو انہیں کم دیا گیا کہ وہ اس سے رجوع کریں۔ کہا: میں نے عرض کی: کیا اسے طلاق شمار کیا گیا؟ انہوں نے جواب دیا: کیوں نہیں! اگر کوئی (آدمی) خود ہی (صحیح طریقے پر طلاق دینے سے) عاجز آ گیا ہو اور (حالت حیض میں طلاق دے کر) حماقت سے کام لیا ہو (تو کیا طلاق نہ ہو گی"}],[3629,"حماد نے ایوب سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی ، البتہ انہوں نے کہا : سیدنا عمر رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے دریافت کیا تو آپ نے انہیں حکم دیا ( کہ ابن عمر رضی اللہ عنہ یہ کریں)","",{"u2":"حماد نے ایوب سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی، البتہ انہوں نے کہا: سیدنا عمر رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے دریافت کیا تو آپ نے انہیں حکم دیا (کہ ابن عمر رضی اللہ عنہ یہ کریں"}],[3630,"عبدالوارث بن عبدالصمد کے دادا عبدالوارث بن سعید نے ایوب سے اسی سند کے ساتھ ( یہی ) روایت بیان کی اور ( اپنی ) حدیث میں کہا : سیدنا عمر رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے اس کے بارے میں سوال کیا تو آپ نے انہیں حکم دیا کہ وہ ( ابن عمر رضی اللہ عنہ ) اس سے رجوع کرے حتی کہ اسے حالت طہر میں مجامعت کیے بغیر طلاق دے ، اور کہا : \" وہ اسے عدت کے آغاز میں طلاق دے ۔ \" ( یعنی اس طہر کے آغاز میں جس سے عدت شمار ہونی ہے)","",{"u2":"عبدالوارث بن عبدالصمد کے دادا عبدالوارث بن سعید نے ایوب سے اسی سند کے ساتھ (یہی) روایت بیان کی اور (اپنی) حدیث میں کہا: سیدنا عمر رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے اس کے بارے میں سوال کیا تو آپ نے انہیں حکم دیا کہ وہ (ابن عمر رضی اللہ عنہ) اس سے رجوع کرے حتی کہ اسے حالت طہر میں مجامعت کیے بغیر طلاق دے، اور کہا: \"وہ اسے عدت کے آغاز میں طلاق دے۔\" (یعنی اس طہر کے آغاز میں جس سے عدت شمار ہونی ہے"}],[3631,"یونس نے محمد بن سیرین سے ، انہوں نے یونس بن جبیر سے روایت کی ، انہوں نے کہا : میں نے ابن عمر رضی اللہ عنہ سے عرض کی : ایک آدمی نے اپنی بیوی کو حالت حیض میں طلاق دی ہے؟ تو انہوں نے کہا : کیا تم عبداللہ بن عمر رضی اللہ عنہ کو جانتے ہو؟ اس نے اپنی بیوی کو حیض کی حالت میں طلاق دی تھی ، سیدنا عمر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے دریافت کیا تو آپ نے اسے ( ابن عمر کو ) حکم دیا کہ وہ اس سے رجوع کرے ، پھر وہ ( عورت اگر اسے دوسرے طہر میں مجامعت کیے بغیر طلاق دی جائے تو وہاں سے ) آگے عدت شمار کرے ۔ کہا : میں نے ان ( ابن عمر رضی اللہ عنہ ) سے پوچھا : اگر کوئی آدمی اپنی بیوی کو حالت حیض میں طلاق دے تو کیا اس طلاق کو شمار کیا جائے گا؟ کہا : انہوں نے کہا : تو ( اور ) کیا؟ اگر وہ خود ہی ( صحیح طریقہ اختیار کرنے سے ) عاجز رہا اور اس نے حماقت سے کام لیا ( تو کیا طلاق شمار نہ ہو گی)","",{"u2":"یونس نے محمد بن سیرین سے، انہوں نے یونس بن جبیر سے روایت کی، انہوں نے کہا: میں نے ابن عمر رضی اللہ عنہ سے عرض کی: ایک آدمی نے اپنی بیوی کو حالت حیض میں طلاق دی ہے؟ تو انہوں نے کہا: کیا تم عبداللہ بن عمر رضی اللہ عنہ کو جانتے ہو؟ اس نے اپنی بیوی کو حیض کی حالت میں طلاق دی تھی، سیدنا عمر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے دریافت کیا تو آپ نے اسے (ابن عمر کو) حکم دیا کہ وہ اس سے رجوع کرے، پھر وہ (عورت اگر اسے دوسرے طہر میں مجامعت کیے بغیر طلاق دی جائے تو وہاں سے) آگے عدت شمار کرے۔ کہا: میں نے ان (ابن عمر رضی اللہ عنہ) سے پوچھا: اگر کوئی آدمی اپنی بیوی کو حالت حیض میں طلاق دے تو کیا اس طلاق کو شمار کیا جائے گا؟ کہا: انہوں نے کہا: تو (اور) کیا؟ اگر وہ خود ہی (صحیح طریقہ اختیار کرنے سے) عاجز رہا اور اس نے حماقت سے کام لیا (تو کیا طلاق شمار نہ ہو گی"}],[3632,"قتادہ سے روایت ہے انہوں نے کہا : میں نے یونس بن جبیر سے سنا انہوں نے کہا میں نے ابن عمر رضی اللہ عنہ کو یہ کہتے ہوئے سنا : میں نے اپنی بیوی کو حالت حیض میں طلاق دی ، اس پر سیدنا عمر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ کو یہ بات بتائی تو نبی صلی اللہ علیہ وسلم نے فرمایا : وہ اس سے رجوع کرے ، اس کے بعد جب وہ پاک ہو جائے تو اگر وہ چاہے اسے طلاق دے دے ۔ ( یونس نے ) کہا : میں نے ابن عمر رضی اللہ عنہ سے پوچھا : کیا آپ اس طلاق کو شمار کریں گے؟ انہوں نے کہا : اس سے کیا چیز مانع ہے تمہاری کیا رائے ہے اگر وہ خود ( صحیح طریقہ اختیار کرنے سے ) عاجز رہا اور نادانی والا کام کیا ( تو طلاق کیوں شمار نہ ہو گی)","",{"u2":"قتادہ سے روایت ہے انہوں نے کہا: میں نے یونس بن جبیر سے سنا انہوں نے کہا میں نے ابن عمر رضی اللہ عنہ کو یہ کہتے ہوئے سنا: میں نے اپنی بیوی کو حالت حیض میں طلاق دی، اس پر سیدنا عمر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ کو یہ بات بتائی تو نبی صلی اللہ علیہ وسلم نے فرمایا: وہ اس سے رجوع کرے، اس کے بعد جب وہ پاک ہو جائے تو اگر وہ چاہے اسے طلاق دے دے۔ (یونس نے) کہا: میں نے ابن عمر رضی اللہ عنہ سے پوچھا: کیا آپ اس طلاق کو شمار کریں گے؟ انہوں نے کہا: اس سے کیا چیز مانع ہے تمہاری کیا رائے ہے اگر وہ خود (صحیح طریقہ اختیار کرنے سے) عاجز رہا اور نادانی والا کام کیا (تو طلاق کیوں شمار نہ ہو گی"}],[3633,"عبدالملک نے انس بن سیرین سے روایت کی ، انہوں نے کہا : میں نے سیدنا ابن عمر رضی اللہ عنہ سے ان کی اس بیوی کے بارے میں سوال کیا جسے انہوں نے طلاق دی تھی ۔ انہوں نے کہا : میں نے اسے حالت حیض میں طلاق دی تھی ۔ میں نے یہ بات سیدنا عمر رضی اللہ عنہ کو بتائی تو انہوں نے یہی بات نبی صلی اللہ علیہ وسلم کو بتائی ۔ اس پر آپ نے فرمایا : \" اسے حکم دو کہ وہ اس سے رجوع کرے اور جب وہ پاک ہو جائے تو اسے اس کے طہر میں طلاق دے ۔ \" کہا : میں نے اس ( بیوی ) سے رجوع کیا ، پھر اس کے طہر میں اسے طلاق دی ۔ میں نے پوچھا : آپ نے وہ طلاق شمار کی جو اسے حالت حیض میں دی تھی؟ انہوں نے جواب دیا : میں اسے کیوں شمار نہ کرتا؟ اگر میں خود ہی ( صحیح طریقہ اپنانے سے ) عاجز رہا تھا اور حماقت سے کام لیا تھا ( تو کیا طلاق شمار نہ ہو گی)","",{"u2":"عبدالملک نے انس بن سیرین سے روایت کی، انہوں نے کہا: میں نے سیدنا ابن عمر رضی اللہ عنہ سے ان کی اس بیوی کے بارے میں سوال کیا جسے انہوں نے طلاق دی تھی۔ انہوں نے کہا: میں نے اسے حالت حیض میں طلاق دی تھی۔ میں نے یہ بات سیدنا عمر رضی اللہ عنہ کو بتائی تو انہوں نے یہی بات نبی صلی اللہ علیہ وسلم کو بتائی۔ اس پر آپ نے فرمایا: \"اسے حکم دو کہ وہ اس سے رجوع کرے اور جب وہ پاک ہو جائے تو اسے اس کے طہر میں طلاق دے۔\" کہا: میں نے اس (بیوی) سے رجوع کیا، پھر اس کے طہر میں اسے طلاق دی۔ میں نے پوچھا: آپ نے وہ طلاق شمار کی جو اسے حالت حیض میں دی تھی؟ انہوں نے جواب دیا: میں اسے کیوں شمار نہ کرتا؟ اگر میں خود ہی (صحیح طریقہ اپنانے سے) عاجز رہا تھا اور حماقت سے کام لیا تھا (تو کیا طلاق شمار نہ ہو گی"}],[3634,"محمد بن جعفر نے ہمیں حدیث سنائی ، انہوں نے کہا : ہمیں شعبہ نے انس بن سیرین سے حدیث بیان کی کہ انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا ، انہوں نے کہا : میں نے اپنی بیوی کو اس حالت میں طلاق دی کہ وہ حائضہ تھی ، اس پر سیدنا عمر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ کو بتایا تو آپ نے فرمایا : \" اسے حکم دو کہ اس سے رجوع کرے ، پھر جب وہ پاک ہو جائے تو تب اسے طلاق دے ۔ \" میں نے سیدنا ابن عمر رضی اللہ عنہ سے پوچھا : کیا آپ نے اس طلاق کو شمار کیا تھا؟ انہوں نے کہا : تو ( اور ) کیا","",{"u2":"محمد بن جعفر نے ہمیں حدیث سنائی، انہوں نے کہا: ہمیں شعبہ نے انس بن سیرین سے حدیث بیان کی کہ انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا، انہوں نے کہا: میں نے اپنی بیوی کو اس حالت میں طلاق دی کہ وہ حائضہ تھی، اس پر سیدنا عمر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ کو بتایا تو آپ نے فرمایا: \"اسے حکم دو کہ اس سے رجوع کرے، پھر جب وہ پاک ہو جائے تو تب اسے طلاق دے۔\" میں نے سیدنا ابن عمر رضی اللہ عنہ سے پوچھا: کیا آپ نے اس طلاق کو شمار کیا تھا؟ انہوں نے کہا: تو (اور) کیا"}],[3635,"خالد بن حارث اور بہز دونوں نے کہا : ہمیں شعبہ نے اسی سند سے حدیث بیان کی ، لیکن ان دونوں کی حدیث میں ( فليراجعها ، یعنی اس سے رجوع کرنے کی بجائے ) فليرجعها ( وہ اس کو لوٹا لے ) ہے ۔ اور ان دونوں کی حدیث میں یہ بھی ہے ، کہا : میں نے ان سے پوچھا : کیا آپ اس طلاق کو شمار کریں گے؟ انہوں نے جواب دیا : تو ( اور ) کیا","",{"u2":"خالد بن حارث اور بہز دونوں نے کہا: ہمیں شعبہ نے اسی سند سے حدیث بیان کی، لیکن ان دونوں کی حدیث میں (فلیراجعہا،یعنی اس سے رجوع کرنے کی بجائے) فلیرجعہا (وہ اس کو لوٹا لے) ہے۔ اور ان دونوں کی حدیث میں یہ بھی ہے، کہا: میں نے ان سے پوچھا: کیا آپ اس طلاق کو شمار کریں گے؟ انہوں نے جواب دیا: تو (اور) کیا"}],[3636,"(عبداللہ ) ابن طاوس نے اپنے والد سے روایت کی کہ انہوں نے ابن عمر رضی اللہ عنہ سے سنا ، ان سے ایسے آدمی کے بارے میں سوال کیا جا رہا تھا جس نے اپنی بیوی کو حیض کی حالت میں طلاق دی ۔ انہوں نے کہا : کیا تم عبداللہ بن عمر رضی اللہ عنہ کو جانتے ہو؟ اس نے کہا : ہاں ، انہوں نے کہا : انہوں نے اپنی بیوی کو حیض میں طلاق دے دی تھی تو سیدنا عمر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کے پاس گئے اور آپ کو اس خبر سے آگاہ کیا ۔ آپ نے انہیں حکم دیا کہ وہ اس سے رجوع کرے ۔ ( ابن طاقس نے ) کہا : میں نے اپنے والد کو اس سے زیادہ بیان کرتے ہوئے نہیں سنا","",{"u2":"عبداللہ) ابن طاوس نے اپنے والد سے روایت کی کہ انہوں نے ابن عمر رضی اللہ عنہ سے سنا، ان سے ایسے آدمی کے بارے میں سوال کیا جا رہا تھا جس نے اپنی بیوی کو حیض کی حالت میں طلاق دی۔ انہوں نے کہا: کیا تم عبداللہ بن عمر رضی اللہ عنہ کو جانتے ہو؟ اس نے کہا: ہاں، انہوں نے کہا: انہوں نے اپنی بیوی کو حیض میں طلاق دے دی تھی تو سیدنا عمر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کے پاس گئے اور آپ کو اس خبر سے آگاہ کیا۔ آپ نے انہیں حکم دیا کہ وہ اس سے رجوع کرے۔(ابن طاقس نے) کہا: میں نے اپنے والد کو اس سے زیادہ بیان کرتے ہوئے نہیں سنا"}],[3637,"حجاج بن محمد نے ہمیں حدیث بیان کی ، کہا : ابن جریج نے کہا : مجھے ابوزبیر نے خبر دی کہ انہوں نے عَزہ کے مولیٰ عبدالرحمٰن بن ایمن سے سنا ، وہ سیدنا ابن عمر رضی اللہ عنہ سے پوچھ رہے تھے اور ابوزبیر بھی یہ بات سن رہے تھے کہ آپ کی اس آدمی کے بارے میں کیا رائے ہے جس نے اپنی بیوی کو حیض کی حالت میں طلاق دے دی؟ انہوں نے جواب دیا : ابن عمر رضی اللہ عنہ نے بھی رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں اپنی بیوی کو حالت حیض میں طلاق دی تھی تو سیدنا عمر رضی اللہ عنہ نے اس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا اور بتایا : عبداللہ بن عمر رضی اللہ عنہ نے اپنی بیوی کو حیض کی حالت میں طلاق دے دی ہے تو نبی صلی اللہ علیہ وسلم نے ان سے فرمایا : \"\" وہ اس سے رجوع کرے ۔ \"\" چنانچہ انہوں نے اس سے رجوع کر لیا ، اور آپ نے فرمایا : \"\" جب وہ پاک ہو جائے تو اسے طلاق دے یا ( اپنے ہاں بسائے ) رکھے ۔ \"\" سیدنا ابن عمر رضی اللہ عنہ نے کہا : اور نبی صلی اللہ علیہ وسلم نے ( یہ آیت ) تلاوت فرمائی : \"\" اے نبی! جب آپ لوگ عورتوں کو طلاق دیں تو انہیں ان کی عدت ( شروع کرنے ) کے وقت طلاق دے","",{"u2":"حجاج بن محمد نے ہمیں حدیث بیان کی، کہا: ابن جریج نے کہا: مجھے ابوزبیر نے خبر دی کہ انہوں نے عَزہ کے مولیٰ عبدالرحمٰن بن ایمن سے سنا، وہ سیدنا ابن عمر رضی اللہ عنہ سے پوچھ رہے تھے اور ابوزبیر بھی یہ بات سن رہے تھے کہ آپ کی اس آدمی کے بارے میں کیا رائے ہے جس نے اپنی بیوی کو حیض کی حالت میں طلاق دے دی؟ انہوں نے جواب دیا: ابن عمر رضی اللہ عنہ نے بھی رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں اپنی بیوی کو حالت حیض میں طلاق دی تھی تو سیدنا عمر رضی اللہ عنہ نے اس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا اور بتایا: عبداللہ بن عمر رضی اللہ عنہ نے اپنی بیوی کو حیض کی حالت میں طلاق دے دی ہے تو نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: \"وہ اس سے رجوع کرے۔\" چنانچہ انہوں نے اس سے رجوع کر لیا، اور آپ نے فرمایا: \"جب وہ پاک ہو جائے تو اسے طلاق دے یا (اپنے ہاں بسائے) رکھے۔\"\nسیدنا ابن عمر رضی اللہ عنہ نے کہا: اور نبی صلی اللہ علیہ وسلم نے (یہ آیت) تلاوت فرمائی: \"اے نبی! جب آپ لوگ عورتوں کو طلاق دیں تو انہیں ان کی عدت (شروع کرنے) کے وقت طلاق دے"}],[3638,"ابوعاصم نے ابن جریج سے ، انہوں نے ابوزبیر سے اور انہوں نے ابن عمر رضی اللہ عنہ سے اسی واقعے کے مطابق روایت کی","",{"u2":"ابوعاصم نے ابن جریج سے، انہوں نے ابوزبیر سے اور انہوں نے ابن عمر رضی اللہ عنہ سے اسی واقعے کے مطابق روایت کی"}],[3639,"عبدالرزاق نے ہمیں حدیث بیان کی ، ( کہا : ) ہمیں ابن جریج نے خبر دی ، ( کہا : ) مجھے ابوزبیر نے خبر دی کہ انہوں نے عروہ کے مولیٰ عبدالرحمٰن بن ایمن سے سنا ، وہ سیدنا ابن عمر رضی اللہ عنہ سے پوچھ رہے تھے ، اور ابوزبیر بھی سن رہے تھے ۔ ۔ ۔ جس طرح حجاج کی حدیث ہے اور اس ( حدیث ) میں کچھ اضافہ بھی ہے ۔ امام مسلم رحمۃ اللہ علیہ نے کہا : انہوں نے جو \"\" مولیٰ عروہ \"\" کہا ہے ، اس میں غلطی کی ، وہ مولیٰ عزہ تھے","",{"u2":"عبدالرزاق نے ہمیں حدیث بیان کی، (کہا:) ہمیں ابن جریج نے خبر دی، (کہا:) مجھے ابوزبیر نے خبر دی کہ انہوں نے عروہ کے مولیٰ عبدالرحمٰن بن ایمن سے سنا، وہ سیدنا ابن عمر رضی اللہ عنہ سے پوچھ رہے تھے، اور ابوزبیر بھی سن رہے تھے۔۔۔ جس طرح حجاج کی حدیث ہے اور اس (حدیث) میں کچھ اضافہ بھی ہے۔\nامام مسلم رحمۃ اللہ علیہ نے کہا: انہوں نے جو \"مولیٰ عروہ\" کہاہے، اس میں غلطی کی، وہ مولیٰ عزہ تھے"}],[3640,"معمر نے ہمیں ابن طاوس سے خبر دی ، انہوں نے اپنے والد ( طاوس بن کیسان ) سے ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ کے عہد میں اور عمر رضی اللہ عنہ کی خلافت کے ( ابتدائی ) دو سالوں تک ( اکٹھی ) تین طلاقیں ایک شمار ہوتی تھی ، پھر سیدنا عمر بن خطاب رضی اللہ عنہ نے کہا : لوگوں نے ایسے کام میں جلد بازی شروع کر دی ہے جس میں ان کے لیے تحمل اور سوچ بچار ( ضروری ) تھا ۔ اگر ہم اس ( عجلت ) کو ان پر نافذ کر دیں ( تو شاید وہ تحمل سے کام لینا شروع کر دیں ) اس کے بعد انہوں نے اسے ان پر نافذ کر دیا ۔ ( اکٹھی تین طلاقوں کو تین شمار کرنے لگے)","",{"u2":"معمر نے ہمیں ابن طاوس سے خبر دی، انہوں نے اپنے والد (طاوس بن کیسان) سے، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ کے عہد میں اور عمر رضی اللہ عنہ کی خلافت کے (ابتدائی) دو سالوں تک (اکٹھی) تین طلاقیں ایک شمار ہوتی تھی، پھر سیدنا عمر بن خطاب رضی اللہ عنہ نے کہا: لوگوں نے ایسے کام میں جلد بازی شروع کر دی ہے جس میں ان کے لیے تحمل اور سوچ بچار (ضروری) تھا۔ اگر ہم اس (عجلت) کو ان پر نافذ کر دیں (تو شاید وہ تحمل سے کام لینا شروع کر دیں) اس کے بعد انہوں نے اسے ان پر نافذ کر دیا۔ (اکٹھی تین طلاقوں کو تین شمار کرنے لگے"}],[3641,"ابن جریج نے ہمیں خبر دی ، کہا : مجھے ابن طاوس نے اپنے والد ( طاوس بن کیسان ) سے خبر دی کہ ابوصبہاء نے ابن عباس رضی اللہ عنہ سے پوچھا : کیا آپ جانتے ہیں کہ نبی صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ کے عہد میں ، اور سیدنا عمر رضی اللہ عنہ کی خلافت کے ( ابتدائی ) تین سالوں تک تین طلاقوں کو ایک شمار کیا جاتا ہے؟ تو سیدنا ابن عباس رضی اللہ عنہ نے جواب دیا : ہاں","",{"u2":"ابن جریج نے ہمیں خبر دی، کہا: مجھے ابن طاوس نے اپنے والد (طاوس بن کیسان) سے خبر دی کہ ابوصبہاء نے ابن عباس رضی اللہ عنہ سے پوچھا: کیا آپ جانتے ہیں کہ نبی صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ کے عہد میں، اور سیدنا عمر رضی اللہ عنہ کی خلافت کے (ابتدائی) تین سالوں تک تین طلاقوں کو ایک شمار کیا جاتا ہے؟ تو سیدنا ابن عباس رضی اللہ عنہ نے جواب دیا: ہاں"}],[3642,"ابراہیم بن میسرہ نے طاوس سے روایت کی کہ ابوصبہاء نے سیدنا ابن عباس رضی اللہ عنہ سے عرض کی : آپ اپنے نوادر ( جن سے اکثر لوگ بے خبر ہیں ) فتووں میں سے کوئی چیز عنایت کریں ۔ کیا رسول اللہ صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ کے عہد میں تین طلاقیں ایک نہیں تھیں؟ انہوں نے جواب دیا : یقینا ایسے ہی تھا ، اس کے بعد جب سیدنا عمر رضی اللہ عنہ کا زمانہ آیا تو لوگوں نے پے در پے ( غلط طریقے سے ایک ساتھ تین ) طلاقیں دینا شروع کر دیں ۔ تو انہوں نے اس بات کو ان پر لاگو کر دیا","",{"u2":"ابراہیم بن میسرہ نے طاوس سے روایت کی کہ ابوصبہاء نے سیدنا ابن عباس رضی اللہ عنہ سے عرض کی: آپ اپنے نوادر (جن سے اکثر لوگ بے خبر ہیں) فتووں میں سے کوئی چیز عنایت کریں۔ کیا رسول اللہ صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ کے عہد میں تین طلاقیں ایک نہیں تھیں؟ انہوں نے جواب دیا: یقینا ایسے ہی تھا، اس کے بعد جب سیدنا عمر رضی اللہ عنہ کا زمانہ آیا تو لوگوں نے پے در پے (غلط طریقے سے ایک ساتھ تین) طلاقیں دینا شروع کر دیں۔ تو انہوں نے اس بات کو ان پر لاگو کر دیا"}],[3643,"ہشام ، یعنی دستوائی ( کپڑے والے ) سے روایت ہے ، انہوں نے کہا : مجھے یحییٰ بن کثیر نے یعلیٰ بن حکیم سے حدیث بیان کرتے ہوئے لکھ بھیجا ، انہوں نے سعید بن جبیر سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، وہ ( بیوی کو اپنے اوپر ) حرام کرنے کے بارے میں کہا کرتے تھے : یہ قسم ہے جس کا وہ کفارہ دے گا ۔ اور سیدنا ابن عباس رضی اللہ عنہ نے کہا : \"\" یقینا تمہارے لیے رسول اللہ صلی اللہ علیہ وسلم ( کی زندگی ) میں بہترین نمونہ ہے","",{"u2":"ہشام، یعنی دستوائی (کپڑے والے) سے روایت ہے، انہوں نے کہا: مجھے یحییٰ بن کثیر نے یعلیٰ بن حکیم سے حدیث بیان کرتے ہوئے لکھ بھیجا، انہوں نے سعید بن جبیر سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، وہ (بیوی کو اپنے اوپر) حرام کرنے کے بارے میں کہا کرتے تھے: یہ قسم ہے جس کا وہ کفارہ دے گا۔\nاور سیدنا ابن عباس رضی اللہ عنہ نے کہا: \"یقینا تمہارے لیے رسول اللہ صلی اللہ علیہ وسلم (کی زندگی) میں بہترین نمونہ ہے"}],[3644,"معاویہ بن سلام نے ہمیں یحییٰ بن ابی کثیر سے حدیث بیان کی کہ یعلیٰ بن حکیم نے انہیں خبر دی ، انہیں سعید بن جبیر نے خبر دی ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے سنا : انہوں نے کہا : جب کوئی آدمی اپنی بیوی کو اپنے اوپر حرام ٹھہرا لے تو یہ قسم ہے جس کا وہ کفارہ دے گا ، اور کہا : \" بلاشبہ تمہارے لیے رسول اللہ صلی اللہ علیہ وسلم ( کی زندگی ) میں بہترین نمونہ ہے","",{"u2":"معاویہ بن سلام نے ہمیں یحییٰ بن ابی کثیر سے حدیث بیان کی کہ یعلیٰ بن حکیم نے انہیں خبر دی، انہیں سعید بن جبیر نے خبر دی، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے سنا: انہوں نے کہا: جب کوئی آدمی اپنی بیوی کو اپنے اوپر حرام ٹھہرا لے تو یہ قسم ہے جس کا وہ کفارہ دے گا، اور کہا: \"بلاشبہ تمہارے لیے رسول اللہ صلی اللہ علیہ وسلم (کی زندگی) میں بہترین نمونہ ہے"}],[3645,"عبید بن عمیر نے خبر دی کہ انہوں نے سیدہ عائشہ رضی اللہ عنہا سے سنا ، وہ بتا رہی تھیں کہ نبی صلی اللہ علیہ وسلم زینب بنت حجش رضی اللہ عنہا کے ہاں ٹھہرتے اور ان کے پاس سے شہد نوش فرماتے تھے : کہا : میں اور حفصہ رضی اللہ عنہا نے اتفاق کیا کہ ہم میں سے جس کے پاس بھی نبی صلی اللہ علیہ وسلم ( پہلے ) تشریف لائیں ، وہ کہے : مجھے آپ سے مغافیر کی بو محسوس ہو رہی ہے ۔ کیا آپ نے مغافیر کھائی ہے؟آپ ان میں سے ایک کے پاس تشریف لے گئے تو انہوں نے آپ کے سامنے یہی بات کی ، آپ صلی اللہ علیہ وسلم نے فرمایا : \" بلکہ میں نے زینب بنت حجش کے ہاں سے شہد پیا ہے ۔ اور آئندہ ہرگز نہیں پیوں گا ۔ \" اس پر ( قرآن ) نازل ہوا : \" آپ کیوں حرام ٹھہراتے ہیں جو اللہ نے آپ کے لیے حلال کیا ہے \" اس فرمان تک : \" اگر تم دونوں توبہ کرو ۔ \" ۔ ۔ یہ عائشہ اور حفصہ رضی اللہ عنہا کے لیے کہا گیا ۔ ۔ \" اور جب نبی صلی اللہ علیہ وسلم نے اپنی کسی بیوی سے راز کی بات کہی \" اس سے مراد ( آپ صلی اللہ علیہ وسلم کا یہ فرمان ) ہے : \" بلکہ میں نے شہد پیا ہے <انڈر لائن > </انڈر لائن >","",{"u2":"عبید بن عمیر نے خبر دی کہ انہوں نے سیدہ عائشہ رضی اللہ عنہا سے سنا، وہ بتا رہی تھیں کہ نبی صلی اللہ علیہ وسلم زینب بنت حجش رضی اللہ عنہا کے ہاں ٹھہرتے اور ان کے پاس سے شہد نوش فرماتے تھے: کہا: میں اور حفصہ رضی اللہ عنہا نے اتفاق کیا کہ ہم میں سے جس کے پاس بھی نبی صلی اللہ علیہ وسلم (پہلے) تشریف لائیں، وہ کہے: مجھے آپ سے مغافیر کی بو محسوس ہو رہی ہے۔ کیا آپ نے مغافیر کھائی ہے؟آپ ان میں سے ایک کے پاس تشریف لے گئے تو انہوں نے آپ کے سامنے یہی بات کی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"بلکہ میں نے زینب بنت حجش کے ہاں سے شہد پیا ہے۔ اور آئندہ ہرگز نہیں پیوں گا۔\" اس پر (قرآن) نازل ہوا: \"آپ کیوں حرام ٹھہراتے ہیں جو اللہ نے آپ کے لیے حلال کیا ہے\" اس فرمان تک: \"اگر تم دونوں توبہ کرو۔\"۔۔ یہ عائشہ اور حفصہ رضی اللہ عنہا کے لیے کہا گیا۔۔ \"اور جب نبی صلی اللہ علیہ وسلم نے اپنی کسی بیوی سے راز کی بات کہی\" اس سے مراد (آپ صلی اللہ علیہ وسلم کا یہ فرمان) ہے: \"بلکہ میں نے شہد پیا ہے <انڈر لائن > </انڈر لائن >"}],[3646,"ابواسامہ نے ہمیں ہشام سے حدیث بیان کی ، انہوں نے اپنے والد ( عروہ ) سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم میٹھی چیز اور شہد کو پسند فرماتے تھے ، جب آپ صلی اللہ علیہ وسلم عصر کی نماز پڑھتے تو اپنی تمام ازواج کے ہاں چکر لگاتے اور ان کے قریب ہوتے ، ( ایسا ہوا کہ ) آپ سیدہ حفصہ رضی اللہ عنہا کے ہاں گئے تو ان کے ہاں آپ اس سے زیادہ ( دیر کے لیے ) رکے جتنا آپ ( کسی بیوی کے پاس ) رکا کرتے تھے ۔ ان ( سیدہ حفصہ رضی اللہ عنہا ) کو ان کے خاندان کی کسی عورت نے شہد کا ( بھرا ہوا ) ایک برتن ہدیہ کیا تھا تو انہوں نے اس میں سے رسول اللہ صلی اللہ علیہ وسلم کو شہد پلایا ۔ میں نے ( دل میں ) کہا : اللہ کی قسم! ہم آپ ( کو زیادہ دیر قیام سے روکنے ) کے لیے ضرور کوئی حیلہ کریں گی ، چنانچہ میں نے اس بات کا ذکر سیدہ سودہ رضی اللہ عنہا سے کیا ، اور کہا : جب آپ صلی اللہ علیہ وسلم تمہارے ہاں تشریف لائیں گے تو تمہارے قریب ہوں گے ، ( اس وقت ) تم ان سے کہنا : اللہ کے رسول! کیا آپ نے مغافیر کھائی ہے؟ وہ تمہیں جواب دیں گے ، نہیں! تو تم ان سے کہنا : یہ بو کیسی ہے؟ ۔ ۔ اور رسول اللہ صلی اللہ علیہ وسلم پر یہ بات انتیائی گراں گزرتی تھی کہ آپ سے بو محسوس کی جائے ۔ ۔ اس پر وہ تمہیں جواب دیں گے : مجھے حفصہ نے شہد پلایا تھا ، تو تم ان سے کہنا ( پھر ) اس کی مکھی نے عرفط ( بوٹی ) کا رس چوسا ہو گا ۔ میں بھی آپ سے یہی بات کہوں گی اور صفیہ تم بھی آپ صلی اللہ علیہ وسلم سے یہی کہنا! جب آپ صلی اللہ علیہ وسلم سیدہ سودہ رضی اللہ عنہا کے ہاں تشریف لے گئے ، ( عائشہ رضی اللہ عنہا نے ) کہا : سودہ رضی اللہ عنہا کہتی ہیں : اس ذات کی قسم جس کے سوا کوئی حقیقی معبود نہیں! آپ ابھی دروازے پر ہی تھے کہ میں تمہاری ملامت کے ر سے آپ کو بلند آواز سے وہ بات کہنے ہی لگی تھی جو تم نے مجھ سے کہی تھی ، پھر جب رسول اللہ صلی اللہ علیہ وسلم قریب ہوئے تو سیدہ سودہ رضی اللہ عنہا نے کہا : اللہ کے رسول! کیا آپ نے مغافیر کھائی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" نہیں ۔ \"\" انہوں نے کہا : تو یہ بو کیسی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" مجھے حفصہ نے شہد پلایا تھا ۔ \"\" انہوں نے کہا : پھر اس کی مکھی نے عرفط کا رس چوسا ہو گا ۔ اس کے بعد جب آپ میرے ہاں تشریف لائے ، تو میں نے بھی آپ سے یہی بات کہی ، پھر آپ سیدہ صفیہ رضی اللہ عنہا کے ہاں گئے ، تو انہوں نے بھی یہی بات کہی ، اس کے بعد آپ سیدہ حفصہ رضی اللہ عنہا کے ہاں ( دوبارہ ) تشریف لائے تو انہوں نے عرض کی : کیا آپ کو شہد پیش نہ کروں ، تو آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" نہیں ، مجھے اس کی ضرورت نہیں ۔ \"\" ( عائشہ رضی اللہ عنہا نے ) کہا : سودہ رضی اللہ عنہا کہنے لگیں ، سبحان اللہ! اللہ کی قسم! ہم نے آپ کو اس سے محروم کر دیا ہے ۔ تو میں نے ان سے کہا : خاموش رہیں ۔ ابواسحاق ابراہیم نے کہا : ہمیں حسن بن بشر بن قاسم نے حدیث بیان کی ، ( کہا : ) ہمیں ابواسامہ نے بالکل اسی طرح حدیث بیان کی","",{"u2":"ابواسامہ نے ہمیں ہشام سے حدیث بیان کی، انہوں نے اپنے والد (عروہ) سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم میٹھی چیز اور شہد کو پسند فرماتے تھے، جب آپ صلی اللہ علیہ وسلم عصر کی نماز پڑھتے تو اپنی تمام ازواج کے ہاں چکر لگاتے اور ان کے قریب ہوتے، (ایسا ہوا کہ) آپ سیدہ حفصہ رضی اللہ عنہا کے ہاں گئے تو ان کے ہاں آپ اس سے زیادہ (دیر کے لیے) رکے جتنا آپ (کسی بیوی کے پاس) رکا کرتے تھے۔ ان (سیدہ حفصہ رضی اللہ عنہا) کو ان کے خاندان کی کسی عورت نے شہد کا (بھرا ہوا) ایک برتن ہدیہ کیا تھا تو انہوں نے اس میں سے رسول اللہ صلی اللہ علیہ وسلم کو شہد پلایا۔ میں نے (دل میں) کہا: اللہ کی قسم! ہم آپ (کو زیادہ دیر قیام سے روکنے) کے لیے ضرور کوئی حیلہ کریں گی، چنانچہ میں نے اس بات کا ذکر سیدہ سودہ رضی اللہ عنہا سے کیا، اور کہا: جب آپ صلی اللہ علیہ وسلم تمہارے ہاں تشریف لائیں گے تو تمہارے قریب ہوں گے، (اس وقت) تم ان سے کہنا: اللہ کے رسول! کیا آپ نے مغافیر کھائی ہے؟ وہ تمہیں جواب دیں گے، نہیں! تو تم ان سے کہنا: یہ بو کیسی ہے؟۔۔ اور رسول اللہ صلی اللہ علیہ وسلم پر یہ بات انتیائی گراں گزرتی تھی کہ آپ سے بو محسوس کی جائے۔۔ اس پر وہ تمہیں جواب دیں گے: مجھے حفصہ نے شہد پلایا تھا، تو تم ان سے کہنا (پھر) اس کی مکھی نے عرفط (بوٹی) کا رس چوسا ہو گا۔میں بھی آپ سے یہی بات کہوں گی اور صفیہ تم بھی آپ صلی اللہ علیہ وسلم سے یہی کہنا! جب آپ صلی اللہ علیہ وسلم سیدہ سودہ رضی اللہ عنہا کے ہاں تشریف لے گئے، (عائشہ رضی اللہ عنہا نے) کہا: سودہ رضی اللہ عنہا کہتی ہیں: اس ذات کی قسم جس کے سوا کوئی حقیقی معبود نہیں! آپ ابھی دروازے پر ہی تھے کہ میں تمہاری ملامت کے ر سے آپ کو بلند آواز سے وہبات کہنے ہی لگی تھی جو تم نے مجھ سے کہی تھی، پھر جب رسول اللہ صلی اللہ علیہ وسلم قریب ہوئے تو سیدہ سودہ رضی اللہ عنہا نے کہا: اللہ کے رسول! کیا آپ نے مغافیر کھائی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں۔\" انہوں نے کہا: تو یہ بو کیسی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے حفصہ نے شہد پلایا تھا۔\" انہوں نے کہا: پھر اس کی مکھی نے عرفط کا رس چوسا ہو گا۔ اس کے بعد جب آپ میرے ہاں تشریف لائے، تو میں نے بھی آپ سے یہی بات کہی، پھر آپ سیدہ صفیہ رضی اللہ عنہا کے ہاں گئے، تو انہوں نے بھی یہی بات کہی، اس کے بعد آپ سیدہ حفصہ رضی اللہ عنہا کے ہاں (دوبارہ) تشریف لائے تو انہوں نے عرض کی: کیا آپ کو شہد پیش نہ کروں، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں، مجھے اس کی ضرورت نہیں۔\"\n(عائشہ رضی اللہ عنہا نے) کہا: سودہ رضی اللہ عنہا کہنے لگیں، سبحان اللہ! اللہ کی قسم! ہم نے آپ کو اس سے محروم کر دیا ہے۔ تو میں نے ان سے کہا: خاموش رہیں۔\nابواسحاق ابراہیم نے کہا: ہمیں حسن بن بشر بن قاسم نے حدیث بیان کی، (کہا:) ہمیں ابواسامہ نے بالکل اسی طرح حدیث بیان کی"}],[3647,"علی بن مسہر نے ہشام بن عروہ سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی",""],[3648,"علی بن مسہر نے ہشام بن عروہ سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی","",{"u2":"علی بن مسہر نے ہشام بن عروہ سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی"}],[3649,"ابن شہاب سے روایت ہے ، کہا : مجھے ابوسلمہ بن عبدالرحمٰن نے خبر دی کہ عائشہ رضی اللہ عنہا نے کہا : جب رسول اللہ صلی اللہ علیہ وسلم کو حکم دیا گیا کہ وہ اپنی بیویوں کو اختیار دیں تو آپ نے ( اس کی ) ابتدا مجھ سے کی ، اور فرمایا : \" میں تم سے ایک بات کرنے لگا ہوں ۔ تمہارے لیے اس بات میں کوئی حرج نہیں کہ تم اپنے والدین سے مشورہ کرنے تک ( جواب دینے میں ) عجلت سے کام نہ لو ۔ \" انہوں نے کہا : آپ کو بخوبی علم تھا کہ میرے والدین مجھے کبھی آپ سے جدا ہونے کا مشورہ نہیں دیں گے ۔ اس کے بعد آپ صلی اللہ علیہ وسلم نے فرمایا : \" بلاشبہ اللہ تعالیٰ نے فرمایا ہے : \" اے نبی! اپنی بیویوں سے کہہ دیجئے کہ اگر تم دنیا کی زندگی اور اس کی زینت چاہتی ہو تو آؤ میں تمہیں ( دنیا کا ) ساز و سامان دوں اور تمہیں اچھائی کے ساتھ رخصت کر دوں ۔ اور اگر تم اللہ اور اس کا رسول اور آخرت کا گھر چاہتی ہو تو اللہ نے تم میں سے نیک کام کرنے والیوں کے لیے اجر عظیم تیار کر رکھا ہے ۔ \" ( عائشہ رضی اللہ عنہا نے ) کہا : میں نے عرض کی : ان میں سے کس بات میں اپنے والدین سے مشورہ کروں؟ میں تو اللہ ، اس کا رسول اور آخرت کا گھر چاہتی ہوں ۔ کہا : پھر اللہ کے رسول صلی اللہ علیہ وسلم کی تمام ازواج نے وہی کیا جو میں نے کیا تھا","",{"u2":"ابن شہاب سے روایت ہے، کہا: مجھے ابوسلمہ بن عبدالرحمٰن نے خبر دی کہ عائشہ رضی اللہ عنہا نے کہا: جب رسول اللہ صلی اللہ علیہ وسلم کو حکم دیا گیا کہ وہ اپنی بیویوں کو اختیار دیں تو آپ نے (اس کی) ابتدا مجھ سے کی، اور فرمایا: \" میں تم سے ایک بات کرنے لگا ہوں۔ تمہارے لیے اس بات میں کوئی حرج نہیں کہ تم اپنے والدین سے مشورہ کرنے تک (جواب دینے میں) عجلت سے کام نہ لو۔\" انہوں نے کہا: آپ کو بخوبی علم تھا کہ میرے والدین مجھے کبھی آپ سے جدا ہونے کا مشورہ نہیں دیں گے۔ اس کے بعد آپ صلی اللہ علیہ وسلم نے فرمایا: \"بلاشبہ اللہ تعالیٰ نے فرمایا ہے: \"اے نبی! اپنی بیویوں سے کہہ دیجئے کہ اگر تم دنیا کی زندگی اور اس کی زینت چاہتی ہو تو آؤ میں تمہیں (دنیا کا) ساز و سامان دوں اور تمہیں اچھائی کے ساتھ رخصت کر دوں۔ اور اگر تم اللہ اور اس کا رسول اور آخرت کا گھر چاہتی ہو تو اللہ نے تم میں سے نیک کام کرنے والیوں کے لیے اجر عظیم تیار کر رکھا ہے۔\" (عائشہ رضی اللہ عنہا نے) کہا: میں نے عرض کی: ان میں سے کس بات میں اپنے والدین سے مشورہ کروں؟ میں تو اللہ، اس کا رسول اور آخرت کا گھر چاہتی ہوں۔ کہا: پھر اللہ کے رسول صلی اللہ علیہ وسلم کی تمام ازواج نے وہی کیا جو میں نے کیا تھا"}],[3650,"عباد بن عباد نے ہمیں عاصم سے حدیث بیان کی ، انہوں نے معاذ عدویہ سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : جب ہم میں سے کسی بیوی کی باری کا دن ہوتا تو رسول اللہ صلی اللہ علیہ وسلم ( کسی اور بیوی کے ہاں جانے کے لیے ) ہم سے اجازت لیتے تھے ، حالانکہ یہ آیت نازل ہو چکی تھی : \" آپ ان میں سے جسے چاہیں ( خود سے ) الگ رکھیں اور جسے چاہیں اپنے پاس جگہ دیں ۔ \" تو معاذہ نے ان سے پوچھا : جب رسول اللہ صلی اللہ علیہ وسلم آپ سے اجازت لیتے تو آپ ان سے کیا کہتی تھیں؟ انہوں نے جواب دیا : میں کہتی تھی : اگر یہ ( اختیار ) میرے سپرد ہے تو میں اپنے آپ پر کسی کو ترجیح نہیں دیتی","",{"u2":"عباد بن عباد نے ہمیں عاصم سے حدیث بیان کی، انہوں نے معاذ عدویہ سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: جب ہم میں سے کسی بیوی کی باری کا دن ہوتا تو رسول اللہ صلی اللہ علیہ وسلم (کسی اور بیوی کے ہاں جانے کے لیے) ہم سے اجازت لیتے تھے، حالانکہ یہ آیت نازل ہو چکی تھی: \"آپ ان میں سے جسے چاہیں (خود سے) الگ رکھیں اور جسے چاہیں اپنے پاس جگہ دیں۔\" تو معاذہ نے ان سے پوچھا: جب رسول اللہ صلی اللہ علیہ وسلم آپ سے اجازت لیتے تو آپ ان سے کیا کہتی تھیں؟ انہوں نے جواب دیا: میں کہتی تھی: اگر یہ (اختیار) میرے سپرد ہے تو میں اپنے آپ پر کسی کو ترجیح نہیں دیتی"}],[3651,"(عبداللہ ) بن مبارک نے کہا : ہمیں عاصم نے اسی سند سے اسی کے ہم معنی خبر دی","",{"u2":"عبداللہ) بن مبارک نے کہا: ہمیں عاصم نے اسی سند سے اسی کے ہم معنی خبر دی"}],[3652,"عبثر نے ہمیں اسماعیل بن ابی خالد سے خبر دی ، انہوں نے شعبی سے اور انہوں نے مسروق سے روایت کی ، کہا : سیدہ عائشہ رضی اللہ عنہا نے کہا : ( جب ) رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ( علیحدہ ہو جانے کا ) اختیار دیا تھا ، تو ہم نے اسے طلاق شمار نہیں کیا","",{"u2":"عبثر نے ہمیں اسماعیل بن ابی خالد سے خبر دی، انہوں نے شعبی سے اور انہوں نے مسروق سے روایت کی، کہا: سیدہ عائشہ رضی اللہ عنہا نے کہا: (جب) رسول اللہ صلی اللہ علیہ وسلم نے ہمیں (علیحدہ ہو جانے کا) اختیار دیا تھا، تو ہم نے اسے طلاق شمار نہیں کیا"}],[3653,"علی بن مسہر نے اسی سند کے ساتھ مسروق سے روایت کی ، انہوں نے کہا : جب میری اہلیہ نے مجھے پسند کر لیا تو اس کے بعد مجھے کوئی پرواہ نہیں کہ میں اسے ایک بار ، سو بار یا ایک ہزار بااختیار دوں ۔ بلاشبہ میں نے سیدہ عائشہ رضی اللہ عنہا سے دریافت کیا تھا تو انہوں نے جواب دیا : بلاشبہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اختیار دیا تھا تو کیا وہ طلاق تھی! ( نہیں تھی)","",{"u2":"علی بن مسہر نے اسی سند کے ساتھ مسروق سے روایت کی، انہوں نے کہا: جب میری اہلیہ نے مجھے پسند کر لیا تو اس کے بعد مجھے کوئی پرواہ نہیں کہ میں اسے ایک بار، سو بار یا ایک ہزار بااختیار دوں۔ بلاشبہ میں نے سیدہ عائشہ رضی اللہ عنہا سے دریافت کیا تھا تو انہوں نے جواب دیا: بلاشبہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اختیار دیا تھا تو کیا وہ طلاق تھی! (نہیں تھی"}],[3654,"شعبہ نے ہمیں عاصم سے حدیث بیان کی ، انہوں نے شعبی سے ، انہوں نے مسروق سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی ازواج کو ( ساتھ رہنے یا علیحدہ ہو جانے کا ) اختیار دیا تھا اور وہ طلاق نہیں تھی","",{"u2":"شعبہ نے ہمیں عاصم سے حدیث بیان کی، انہوں نے شعبی سے، انہوں نے مسروق سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی ازواج کو (ساتھ رہنے یا علیحدہ ہو جانے کا) اختیار دیا تھا اور وہ طلاق نہیں تھی"}],[3655,"سفیان نے عاصم احول اور اسماعیل بن ابی خالد سے ، انہوں نے شعبی سے ، انہوں نے مسروق سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اختیار دیا تو ہم نے آپ کو اختیار کیا ( چن لیا ) اور آپ نے اسے طلاق شمار نہیں کیا","",{"u2":"سفیان نے عاصم احول اور اسماعیل بن ابی خالد سے، انہوں نے شعبی سے، انہوں نے مسروق سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اختیار دیا تو ہم نے آپ کو اختیار کیا (چن لیا) اور آپ نے اسے طلاق شمار نہیں کیا"}],[3656,"ابومعاویہ نے اعمش سے ، انہوں نے مسلم سے ، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اختیار دیا تو ہم نے آپ کو اختیار کر لیا اور آپ نے اسے ہم پر ( طلاق وغیرہ ) کچھ شمار نہیں کیا","",{"u2":"ابومعاویہ نے اعمش سے، انہوں نے مسلم سے، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اختیار دیا تو ہم نے آپ کو اختیار کر لیا اور آپ نے اسے ہم پر (طلاق وغیرہ) کچھ شمار نہیں کیا"}],[3657,"اسماعیل بن زکریا نے ہمیں حدیث بیان کی ، کہا : ہمیں اعمش نے ابراہیم سے حدیث بیان کی ، انہوں نے اسود سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، ( نیز اسماعیل نے ) اعمش سے ، انہوں نے مسلم ( ابن صبیح ) سے ، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے اسی کے مانند روایت کی","",{"u2":"اسماعیل بن زکریا نے ہمیں حدیث بیان کی، کہا: ہمیں اعمش نے ابراہیم سے حدیث بیان کی، انہوں نے اسود سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، (نیز اسماعیل نے) اعمش سے، انہوں نے مسلم (ابن صبیح) سے، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے اسی کے مانند روایت کی"}],[3658,"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : سیدنا ابوبکر رضی اللہ عنہ آئے ، وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہونے کی اجازت مانگ رہے تھے ۔ انہوں نے لوگوں کو آپ کے دروازے پر بیٹھے ہوئے پایا ۔ ان میں سے کسی کو اجازت نہیں ملی تھی ۔ کہا : ابوبکر رضی اللہ عنہ کو اجازت ملی تو وہ اندر داخل ہو گئے ، پھر عمر رضی اللہ عنہ آئے ، انہوں نے اجازت مانگی ، انہیں بھی اجازت مل گئی ، انہوں نے نبی صلی اللہ علیہ وسلم کو غمگین اور خاموش بیٹھے ہوئے پایا ، آپ کی بیویاں آپ کے ارد گرد تھیں ۔ کہا : تو انہوں ( ابوبکر رضی اللہ عنہ ) نے کہا : میں ضرور کوئی ایسی بات کروں گا جس سے میں نبی صلی اللہ علیہ وسلم کو ہنساؤں گا ۔ انہوں نے کہا : اللہ کے رسول! کاش کہ آپ بنت خارجہ کو دیکھتے جب اس نے مجھ سے نفقہ کا سوال کیا تو میں اس کی جانب بڑھا اور اس کی گردن دبا دی ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم ہنس پڑے ۔ اور فرمایا : \"\" یہ بھی میرے اردگرد بیٹھی ہیں ، جیسے تم دیکھ رہے ہو ، اور مجھ سے نفقہ مانگ رہی ہیں ۔ \"\" ابوبکر رضی اللہ عنہ عائشہ رضی اللہ عنہا کی جانب اٹھے اور ان کی گردن پر ضرب لگانا چاہتے تھے اور عمر رضی اللہ عنہ حفصہ رضی اللہ عنہا کی جانب بڑھے اور وہ ان کی گردن پر مارنا چاہتے تھے ، ( رسول اللہ صلی اللہ علیہ وسلم نے ان دونوں کو اس سے روک دیا ۔ مسند احمد : 3/328 ) اور دونوں کہہ رہے تھے : تم رسول اللہ صلی اللہ علیہ وسلم سے اس چیز کا سوال کرتی ہو جو ان کے پاس نہیں ہے ۔ وہ کہنے لگیں : اللہ کی قسم! آج کے بعد ہم کبھی رسول اللہ صلی اللہ علیہ وسلم سے ایسی چیز کا مطالبہ نہیں کریں گی جو آپ کے پاس نہ ہو گی ۔ پھر آپ صلی اللہ علیہ وسلم نے ایک ماہ یا انتیس دن تک کے لیے ان سے علیحدگی اختیار کر لی ۔ پھر آپ پر یہ آیت نازل ہوئی : \"\" اے نبی صلی اللہ علیہ وسلم! آپ اپنی بیویوں سے کہہ دو ۔ \"\" حتی کہ یہاں پہنچ گئے : \"\" تم میں سے نیکی کرنے والیوں کے لیے بڑا اجر ہے ۔ \"\" ( جابر رضی اللہ عنہ نے ) کہا : آپ نے ابتدا سیدہ عائشہ رضی اللہ عنہا سے کی اور فرمایا : \"\" اے عائشہ! میں تمہارے سامنے ایک معاملہ پیش کر رہا ہوں اور پسند کرتا ہوں کہ تم ، اپنے والدین سے مشورہ کر لینے تک اس میں جلدی نہ کرنا ۔ \"\" انہوں نے کہا : کیا میں آپ کے بارے میں ، اللہ کے رسول! اپنے والدین سے مشورہ کروں گی! بلکہ میں تو اللہ ، اس کے رسول اور آخرت کے گھر کو چنتی ہوں ، اور آپ سے یہ درخواست کرتی ہو کہ جو میں نے کہا ہے ، آپ اپنی بیویوں میں سے کسی کو اس کی خبر نہ دیں ۔ آپ نے فرمایا : \"\" مجھ سے جو بھی پوچھے گی میں اسے بتا دوں گا ، اللہ تعالیٰ نے مجھے سختی کرنے والا اور لوگوں کے لیے مشکلات ڈھونڈنے والا بنا کر نہیں بھیجا ، بلکہ اللہ نے مجھے تعلیم دینے والا اور آسانی کرنے والا بنا کر بھیجا ہے","",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: سیدنا ابوبکر رضی اللہ عنہ آئے، وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہونے کی اجازت مانگ رہے تھے۔ انہوں نے لوگوں کو آپ کے دروازے پر بیٹھے ہوئے پایا۔ ان میں سے کسی کو اجازت نہیں ملی تھی۔ کہا: ابوبکر رضی اللہ عنہ کو اجازت ملی تو وہ اندر داخل ہو گئے، پھر عمر رضی اللہ عنہ آئے، انہوں نے اجازت مانگی، انہیں بھی اجازت مل گئی، انہوں نے نبی صلی اللہ علیہ وسلم کو غمگین اور خاموش بیٹھے ہوئے پایا، آپ کی بیویاں آپ کے ارد گرد تھیں۔ کہا: تو انہوں (ابوبکر رضی اللہ عنہ) نے کہا: میں ضرور کوئی ایسی بات کروں گا جس سے میں نبی صلی اللہ علیہ وسلم کو ہنساؤں گا۔ انہوں نے کہا: اللہ کے رسول! کاش کہ آپ بنت خارجہ کو دیکھتے جب اس نے مجھ سے نفقہ کا سوال کیا تو میں اس کی جانب بڑھا اور اس کی گردن دبا دی۔\nاس پر رسول اللہ صلی اللہ علیہ وسلم ہنس پڑے۔ اور فرمایا: \"یہ بھی میرے اردگرد بیٹھی ہیں، جیسے تم دیکھ رہے ہو، اور مجھ سے نفقہ مانگ رہی ہیں۔\" ابوبکر رضی اللہ عنہ عائشہ رضی اللہ عنہا کی جانب اٹھے اور ان کی گردن پر ضرب لگانا چاہتے تھے اور عمر رضی اللہ عنہ حفصہ رضی اللہ عنہا کی جانب بڑھے اور وہ ان کی گردن پر مارنا چاہتے تھے، (رسول اللہ صلی اللہ علیہ وسلم نے ان دونوں کو اس سے روک دیا۔ مسند احمد: 3/328) اور دونوں کہہ رہے تھے: تم رسول اللہ صلی اللہ علیہ وسلم سے اس چیز کا سوال کرتی ہو جو ان کے پاس نہیں ہے۔ وہ کہنے لگیں: اللہ کی قسم! آج کے بعد ہم کبھی رسول اللہ صلی اللہ علیہ وسلم سے ایسی چیز کا مطالبہ نہیں کریں گی جو آپ کے پاس نہ ہو گی۔ پھر آپ صلی اللہ علیہ وسلم نے ایک ماہ یا انتیس دن تک کے لیے ان سے علیحدگی اختیار کر لی۔ پھر آپ پر یہ آیت نازل ہوئی: \"اے نبی صلی اللہ علیہ وسلم! آپ اپنی بیویوں سے کہہ دو۔\" حتی کہ یہاں پہنچ گئے: \"تم میں سے نیکی کرنے والیوں کے لیے بڑا اجر ہے۔\" (جابر رضی اللہ عنہ نے) کہا: آپ نے ابتدا سیدہ عائشہ رضی اللہ عنہا سے کی اور فرمایا: \"اے عائشہ! میں تمہارے سامنے ایک معاملہ پیش کر رہا ہوں اور پسند کرتا ہوں کہ تم، اپنے والدین سے مشورہ کر لینے تک اس میں جلدی نہ کرنا۔\" انہوں نے کہا: کیا میں آپ کے بارے میں، اللہ کے رسول! اپنے والدین سے مشورہ کروں گی! بلکہ میں تو اللہ، اس کے رسول اور آخرت کے گھر کو چنتی ہوں، اور آپ سے یہ درخواست کرتی ہو کہ جو میں نے کہا ہے، آپ اپنی بیویوں میں سے کسی کو اس کی خبر نہ دیں۔ آپ نے فرمایا: \"مجھ سے جو بھی پوچھے گی میں اسے بتا دوں گا، اللہ تعالیٰ نے مجھے سختی کرنے والا اور لوگوں کے لیے مشکلات ڈھونڈنے والا بنا کر نہیں بھیجا، بلکہ اللہ نے مجھے تعلیم دینے والا اور آسانی کرنے والا بنا کر بھیجا ہے"}],[3659,"سماک ابوزمیل سے روایت ہے ، ( انہوں نے کہا : ) مجھے عبداللہ بن عباس رضی اللہ عنہ نے حدیث بیان کی ، ( کہا : ) مجھے عمر بن خطاب رضی اللہ عنہ نے حدیث بیان کی ، انہوں نے کہا : جب نبی صلی اللہ علیہ وسلم نے اپنی ازواج سے علیحدگی اختیار فرمائی ، کہا : میں مسجد میں داخل ہوا تو لوگوں کو دیکھا وہ ( پریشانی اور تفکر میں ) کنکریاں زمین پر مار رہے ہیں ، اور کہہ رہے ہیں : رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیویوں کو طلاق دے دی ہے ، یہ واقعہ انہیں پردے کا حکم دیے جانے سے پہلے کا ہے ۔ عمر رضی اللہ عنہ نے کہا : میں نے ( دل میں ) کہا : آج میں اس معاملے کو جان کر رہوں گا ۔ انہوں نے کہا : میں عائشہ رضی اللہ عنہا کے پاس گیا ، اور کہا : ابوبکر رضی اللہ عنہ کی بیٹی! تم اس حد تک پہنچ چکی ہو کہ اللہ کے رسول صلی اللہ علیہ وسلم کو اذیت دو؟ انہوں نے جواب دیا : خطاب کے بیٹے! آپ کا مجھ سے کیا واسطہ؟ آپ اپنی گھٹڑی ( یا تھیلا وغیرہ جس میں قیمتی ساز و سامان سنبھال کر رکھا جاتا ہے یعنی اپنی بیٹی حفصہ رضی اللہ عنہا ) کی فکر کریں ۔ انہوں نے کہا : پھر میں ( اپنی بیٹی ) حفصہ بنت عمر رضی اللہ عنہا کے پاس آیا اور کہا : حفصہ! کیا تم اس حد تک پہنچ گئی ہو کہ اللہ کے رسول صلی اللہ علیہ وسلم کو تکلیف دو؟ اللہ کی قسم! تمہیں خوب معلوم ہے کہ اللہ کے رسول صلی اللہ علیہ وسلم تم سے محبت نہیں رکھتے ۔ اگر میں نہ ہوتا تو رسول اللہ صلی اللہ علیہ وسلم تمہیں طلاق دے دیتے ۔ ( میری یہ بات سن کر ) وہ بری طرح سے رونے لگیں ۔ میں نے ان سے پوچھا : اللہ کے رسول صلی اللہ علیہ وسلم کہاں ہیں؟ انہوں نے جواب دیا : وہ اپنے بالا خانے پر سامان رکھنے والی جگہ میں ہیں ۔ میں وہاں گیا تو دیکھا رسول اللہ صلی اللہ علیہ وسلم کا غلام رَباح چوبارے کی چوکھٹ کے نیچے والی لکڑی پر بیٹھا ہے ۔ اس نے اپنے دونوں پاؤں لکڑی کی سوراخ دار سیڑھی پر لٹکا رکھے ہیں ۔ وہ کھجور کا ایک تنا تھا ، رسول اللہ صلی اللہ علیہ وسلم اس پر ( قدم رکھ کر ) چڑھتے اور اترتے تھے ۔ میں نے آواز دی ، رباح! مجھے اپنے پاس ، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں ، حاضر ہونے کی اجازت لے دو ۔ رباح رضی اللہ عنہ نے بالا خانے کی طرف نظر کی ، پھر مجھے دیکھا اور کچھ نہ کہا ۔ میں نے پھر کہا : رباح! مجھے اپنے پاس ، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں ، حاضر ہونے کی اجازت لے دو ، رباح رضی اللہ عنہ نے ( دوبارہ ) بالا خانے کی طرف نگاہ اٹھائی ، پھر مجھے دیکھا ، اور کچھ نہ کہا ، پھر میں نے اپنی آواز کو بلند کی اور کہا : اے رباح! مجھے اپنے پاس ، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں ، حاضر ہونے کی اجازت لے دو ، میرا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سمجھا ہے کہ میں حفصہ رضی اللہ عنہا کی ( سفارش کرنے کی ) خاطر آیا ہوں ، اللہ کی قسم! اگر رسول اللہ صلی اللہ علیہ وسلم مجھے اس کی گردن اڑانے کا حکم دیں تو میں اس کی گردن اڑا دوں گا ، اور میں نے اپنی آواز کو ( خوب ) بلند کیا ، تو اس نے مجھے اشارہ کیا کہ اوپر چڑھ آؤ ۔ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا ، آپ ایک چٹائی پر لیٹے ہوئے تھے ، میں بیٹھ گیا ، آپ نے اپنا ازار درست کیا اور آپ ( کے جسم ) پر اس کے علاوہ اور کچھ نہ تھا اور چٹائی نے آپ کے جسم پر نشان ڈال دیے تھے ۔ میں نے اپنی آنکھوں سے رسول اللہ صلی اللہ علیہ وسلم کے سامان کے کمرے میں دیکھا تو صرف مٹھی بھر جو ایک صاع کے برابر ہوں گے ، جَو اور کمرے کے ایک کونے میں اتنی ہی کیکر کی چھال دیکھی ۔ اس کے علاوہ ایک غیر دباغت شدہ چمڑا لٹکا ہوا تھا ۔ کہا : تو میری آنکھیں بہ پڑیں ، آپ صلی اللہ علیہ وسلم نے پوچھا : \" ابن خطاب! تمہیں رُلا کیا چیز رہی ہے؟ \" میں نے عرض کی : اللہ کے نبی! میں کیوں نہ روؤں؟ اس چٹائی نے آپ کے جسم اطہر پر نشان ڈال دیے ہیں ، اور یہ آپ کا سامان رکھنے کا کمرہ ہے ، اس میں وہی کچھ ہے جو مجھے نظر آرہا ہے ، اور قیصر و کسری نہروں اور پھلوں کے درمیان ( شاندار زندگی بسر کر رہے ) ہیں ، جبکہ آپ تو اللہ کے رسول اور اس کی چنی ہوئی ہستی ہیں ، اور یہ آپ کا سارا سامان ہے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" ابن خطاب! کیا تمہیں پسند نہیں کہ ہمارے لیے آخرت ہو اور ان کے لیے دنیا ہو؟ \" میں نے عرض کی : کیوں نہیں! کہا : جب میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تھا تو آپکے چہرے پر غصہ دیکھ رہا تھا ، میں نے عرض کی : اللہ کے رسول! آپ کو ( اپنی ) بیویوں کی حالت کی بنا پر کیا دشواری ہے؟ اگر آپ نے انہیں طلاق دے دی ہے تو اللہ آپ کے ساتھ ہے ، اس کے فرشتے ، جبرئیل ، میکائیل ، میں ، ابوبکر اور تمام مومن آپ کے ساتھ ہیں ۔ اور میں اللہ کا شکر ادا کرتا ہوں کہ میں نے کم ہی کوئی بات کہی ، مگر میں نے امید کی کہ اللہ میری اس بات کی تصدیق فرما دے گا جو میں کہہ رہا ہوں ۔ ( چنانچہ ایسے ہی ہوا ) اور یہ تخییر کی آیت نازل ہو گئی : \" اگر وہ ( نبی ) تم سب ( بیویوں ) کو طلاق دے دیں تو قریب ہے کہ ان کا رب ، انہیں تم سے بہتر بیویاں بدلے میں دے ۔ \" اور \" اگر تم دونوں ان کے خلاف ایک دوسرے کی مدد کرو گی ، تو اللہ خود ان کا نگہبان ہے ، اور جبریل اور صالح مومن اور اس کے بعد تمام فرشتے ( ان کے ) مددگار ہیں ۔ \" عائشہ بنت ابی بکر اور حفصہ رضی اللہ عنہن دونوں نبی صلی اللہ علیہ وسلم کی تمام بیویوں کے مقابلے میں ایک دوسرے کا ساتھ دیتی تھیں ۔ میں نے عرض کی : اے اللہ کے رسول! کیا آپ نے ان کو طلاق دے دی ہے؟ آپ نے فرمایا : \" نہیں ۔ \" میں نے عرض کی : اے اللہ کے رسول! میں مسجد میں داخل ہوا تھا تو لوگ کنکریاں زمین پر مار رہے تھے ، اور کہہ رہے تھے : اللہ کے رسول صلی اللہ علیہ وسلم نے اپنی بیویوں کو چلاق دے دی ہے ۔ کیا میں اتر کر انہیں بتا دوں کہ آپ نے ان ( بیویوں ) کو طلاق نہیں دی؟ آپ نے فرمایا : \" ہاں ، اگر چاہو ۔ \" میں مسلسل آپ سے گفتگو کرتا رہا یہاں تک کہ آپ کے چہرے سے غصہ دور ہو گیا ، اور یہاں تک کہ آپ کے لب وار ہوئے اور آپ ہنسے ۔ آپ کے سامنے والے دندانِ مبارک سب انسانوں سے زیادہ خوبصورت تھے ۔ پھر اللہ کے نبی صلی اللہ علیہ وسلم ( بالا خانے سے نیچے ) اترے ۔ میں تنے کو تھامتے ہوئے اترا اور رسول اللہ صلی اللہ علیہ وسلم ایسے اترے جیسے زمین پر چل رہے ہوں ، آپ نے تنے کو ہاتھ تک نہ لگایا ۔ میں نے عرض کی : اللہ کے رسول! آپ بالا خانے میں 29 دن رہے ہیں ۔ آپ نے فرمایا : \" مہینہ 29 دن کا ہوتا ہے ۔ \" چنانچہ میں مسجد کے دروازے پر کھڑا ہوا ، اور بلند آواز سے پکار کر کہا : رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیویوں کو طلاق نہیں دی ، اور ( پھر ) یہ آیت نازل ہوئی : \" اور جب ان کے پاس امن یا خوف کی کوئی خبر آتی ہے تو اسے مشہور کر دیتے ہیں ، اور اگر وہ اسے رسول اللہ صلی اللہ علیہ وسلم کی طرف اور اپنے معاملات سنبھالنے والوں کی طرف لوٹا دیتے ، تو وہ لوگ جو ان میں اس سے اصل مطلب اخذ کرتے ہیں اسے ضرور جان لیتے ۔ \" تو میں ہی تھا جس نے اس معاملے کی اصل حقیقت کو اخذ کیا ، اور اللہ تعالیٰ نے تخییر کی آیت نازل فرمائی","",{"u2":"سماک ابوزمیل سے روایت ہے، (انہوں نے کہا:) مجھے عبداللہ بن عباس رضی اللہ عنہ نے حدیث بیان کی، (کہا:) مجھے عمر بن خطاب رضی اللہ عنہ نے حدیث بیان کی، انہوں نے کہا: جب نبی صلی اللہ علیہ وسلم نے اپنی ازواج سے علیحدگی اختیار فرمائی، کہا: میں مسجد میں داخل ہوا تو لوگوں کو دیکھا وہ (پریشانی اور تفکر میں) کنکریاں زمین پر مار رہے ہیں، اور کہہ رہے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیویوں کو طلاق دے دی ہے، یہ واقعہ انہیں پردے کا حکم دیے جانے سے پہلے کا ہے۔ عمر رضی اللہ عنہ نے کہا: میں نے (دل میں) کہا: آج میں اس معاملے کو جان کر رہوں گا۔ انہوں نے کہا: میں عائشہ رضی اللہ عنہا کے پاس گیا، اور کہا: ابوبکر رضی اللہ عنہ کی بیٹی! تم اس حد تک پہنچ چکی ہو کہ اللہ کے رسول صلی اللہ علیہ وسلم کو اذیت دو؟ انہوں نے جواب دیا: خطاب کے بیٹے! آپ کا مجھ سے کیا واسطہ؟ آپ اپنی گھٹڑی (یا تھیلا وغیرہ جس میں قیمتی ساز و سامان سنبھال کر رکھا جاتا ہے یعنی اپنی بیٹی حفصہ رضی اللہ عنہا) کی فکر کریں۔ انہوں نے کہا: پھر میں (اپنی بیٹی) حفصہ بنت عمر رضی اللہ عنہا کے پاس آیا اور کہا: حفصہ! کیا تم اس حد تک پہنچ گئی ہو کہ اللہ کے رسول صلی اللہ علیہ وسلم کو تکلیف دو؟ اللہ کی قسم! تمہیں خوب معلوم ہے کہ اللہ کے رسول صلی اللہ علیہ وسلم تم سے محبت نہیں رکھتے۔ اگر میں نہ ہوتا تو رسول اللہ صلی اللہ علیہ وسلم تمہیں طلاق دے دیتے۔ (میری یہ بات سن کر) وہ بری طرح سے رونے لگیں۔ میں نے ان سے پوچھا: اللہ کے رسول صلی اللہ علیہ وسلم کہاں ہیں؟ انہوں نے جواب دیا: وہ اپنے بالا خانے پر سامان رکھنے والی جگہ میں ہیں۔ میں وہاں گیا تو دیکھا رسول اللہ صلی اللہ علیہ وسلم کا غلام رَباح چوبارے کی چوکھٹ کے نیچے والی لکڑی پر بیٹھا ہے۔ اس نے اپنے دونوں پاؤں لکڑی کی سوراخ دار سیڑھی پر لٹکا رکھے ہیں۔ وہ کھجور کا ایک تنا تھا، رسول اللہ صلی اللہ علیہ وسلم اس پر (قدم رکھ کر) چڑھتے اور اترتے تھے۔ میں نے آواز دی، رباح! مجھے اپنے پاس، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں، حاضر ہونے کی اجازت لے دو۔ رباح رضی اللہ عنہ نے بالا خانے کی طرف نظر کی، پھر مجھے دیکھا اور کچھ نہ کہا۔ میں نے پھر کہا: رباح! مجھے اپنے پاس، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں، حاضر ہونے کی اجازت لے دو، رباح رضی اللہ عنہ نے (دوبارہ) بالا خانے کی طرف نگاہ اٹھائی، پھر مجھے دیکھا، اور کچھ نہ کہا، پھر میں نے اپنی آواز کو بلند کی اور کہا: اے رباح! مجھے اپنے پاس، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں، حاضر ہونے کی اجازت لے دو، میرا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سمجھا ہے کہ میں حفصہ رضی اللہ عنہا کی (سفارش کرنے کی) خاطر آیا ہوں، اللہ کی قسم! اگر رسول اللہ صلی اللہ علیہ وسلم مجھے اس کی گردن اڑانے کا حکم دیں تو میں اس کی گردن اڑا دوں گا، اور میں نے اپنی آواز کو (خوب) بلند کیا، تو اس نے مجھے اشارہ کیا کہ اوپر چڑھ آؤ۔ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، آپ ایک چٹائی پر لیٹے ہوئے تھے، میں بیٹھ گیا، آپ نے اپنا ازار درست کیا اور آپ (کے جسم) پر اس کے علاوہ اور کچھ نہ تھا اور چٹائی نے آپ کے جسم پر نشان ڈال دیے تھے۔ میں نے اپنی آنکھوں سے رسول اللہ صلی اللہ علیہ وسلم کے سامان کے کمرے میں دیکھا تو صرف مٹھی بھر جو ایک صاع کے برابر ہوں گے، جَو اور کمرے کے ایک کونے میں اتنی ہی کیکر کی چھال دیکھی۔ اس کے علاوہ ایک غیر دباغت شدہ چمڑا لٹکا ہوا تھا۔ کہا: تو میری آنکھیں بہ پڑیں، آپ صلی اللہ علیہ وسلم نے پوچھا: \"ابن خطاب! تمہیں رُلا کیا چیز رہی ہے؟\" میں نے عرض کی: اللہ کے نبی! میں کیوں نہ روؤں؟ اس چٹائی نے آپ کے جسم اطہر پر نشان ڈال دیے ہیں، اور یہ آپ کا سامان رکھنے کا کمرہ ہے، اس میں وہی کچھ ہے جو مجھے نظر آرہا ہے، اور قیصر و کسری نہروں اور پھلوں کے درمیان (شاندار زندگی بسر کر رہے) ہیں، جبکہ آپ تو اللہ کے رسول اور اس کی چنی ہوئی ہستی ہیں، اور یہ آپ کا سارا سامان ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ابن خطاب! کیا تمہیں پسند نہیں کہ ہمارے لیے آخرت ہو اور ان کے لیے دنیا ہو؟\" میں نے عرض کی: کیوں نہیں! کہا: جب میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تھا تو آپکے چہرے پر غصہ دیکھ رہا تھا، میں نے عرض کی: اللہ کے رسول! آپ کو (اپنی) بیویوں کی حالت کی بنا پر کیا دشواری ہے؟ اگر آپ نے انہیں طلاق دے دی ہے تو اللہ آپ کے ساتھ ہے، اس کے فرشتے، جبرئیل، میکائیل، میں، ابوبکر اور تمام مومن آپ کے ساتھ ہیں۔ اور میں اللہ کا شکر ادا کرتا ہوں کہ میں نے کم ہی کوئی بات کہی، مگر میں نے امید کی کہ اللہ میری اس بات کی تصدیق فرما دے گا جو میں کہہ رہا ہوں۔ (چنانچہ ایسے ہی ہوا) اور یہ تخییر کی آیت نازل ہو گئی: \"اگر وہ (نبی) تم سب (بیویوں) کو طلاق دے دیں تو قریب ہے کہ ان کا رب، انہیں تم سے بہتر بیویاں بدلے میں دے۔\" اور \"اگر تم دونوں ان کے خلاف ایک دوسرے کی مدد کرو گی، تو اللہ خود ان کا نگہبان ہے، اور جبریل اور صالح مومن اور اس کے بعد تمام فرشتے (ان کے) مددگار ہیں۔\"عائشہ بنت ابی بکر اور حفصہ رضی اللہ عنہن دونوں نبی صلی اللہ علیہ وسلم کی تمام بیویوں کے مقابلے میں ایک دوسرے کا ساتھ دیتی تھیں۔ میں نے عرض کی: اے اللہ کے رسول! کیا آپ نے ان کو طلاق دے دی ہے؟ آپ نے فرمایا: \"نہیں۔\"میں نے عرض کی: اے اللہ کے رسول! میں مسجد میں داخل ہوا تھا تو لوگ کنکریاں زمین پر مار رہے تھے، اور کہہ رہے تھے: اللہ کے رسول صلی اللہ علیہ وسلم نے اپنی بیویوں کو چلاق دے دی ہے۔ کیا میں اتر کر انہیں بتا دوں کہ آپ نے ان (بیویوں) کو طلاق نہیں دی؟ آپ نے فرمایا: \"ہاں، اگر چاہو۔\" میں مسلسل آپ سے گفتگو کرتا رہا یہاں تک کہ آپ کے چہرے سے غصہ دور ہو گیا، اور یہاں تک کہ آپ کے لب وار ہوئے اور آپ ہنسے۔ آپ کے سامنے والے دندانِ مبارک سب انسانوں سے زیادہ خوبصورت تھے۔ پھر اللہ کے نبی صلی اللہ علیہ وسلم (بالا خانے سے نیچے) اترے۔ میں تنے کو تھامتے ہوئے اترا اور رسول اللہ صلی اللہ علیہ وسلم ایسے اترے جیسے زمین پر چل رہے ہوں، آپ نے تنے کو ہاتھ تک نہ لگایا۔ میں نے عرض کی: اللہ کے رسول! آپ بالا خانے میں 29 دن رہے ہیں۔ آپ نے فرمایا: \"مہینہ 29 دن کا ہوتا ہے۔\"چنانچہ میں مسجد کے دروازے پر کھڑا ہوا، اور بلند آواز سے پکار کر کہا: رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیویوں کو طلاق نہیں دی، اور (پھر) یہ آیت نازل ہوئی: \"اور جب ان کے پاس امن یا خوف کی کوئی خبر آتی ہے تو اسے مشہور کر دیتے ہیں، اور اگر وہ اسے رسول اللہ صلی اللہ علیہ وسلم کی طرف اور اپنے معاملات سنبھالنے والوں کی طرف لوٹا دیتے، تو وہ لوگ جو ان میں اس سے اصل مطلب اخذ کرتے ہیں اسے ضرور جان لیتے۔\" تو میں ہی تھا جس نے اس معاملے کی اصل حقیقت کو اخذ کیا، اور اللہ تعالیٰ نے تخییر کی آیت نازل فرمائی"}],[3660,"سلیمان بن بلال نے کہا : مجھے یحییٰ نے عبید بن حنین سے خبر دی کہ انہوں نے عبداللہ بن عباس رضی اللہ عنہ سے سنا وہ حدیث بیان کر رہے تھے ، انہوں نے کہا : میں نے سال بھر کے انتظار کیا ، میں سیدنا عمر بن خطاب رضی اللہ عنہ سے ایک آیت کے بارے میں دریافت کرنا چاہتا تھا مگر ان کی ہیبت کی وجہ سے ان سے سوال کرنے کی ہمت نہ پاتا تھا ، حتی کہ وہ حج کرنے کے لیے روانہ ہوئے ، میں بھی ان کے ساتھ نکلا ، جب لوٹے تو ہم راستے میں کسی جگہ تھے کہ وہ قضائے حاجت کے لیے پیلو کے درخت کی طرف چلے گئے ، میں ان کے انتظار میں ٹھہر گیا ، حتی کہ وہ فارغ ہو گئے ، پھر میں ان کے ساتھ چل پڑا ، میں نے عرض کی : امیر المومنین! رسول اللہ صلی اللہ علیہ وسلم کی ازواج میں سے وہ کون سی دو خواتین تھیں جنہوں نے رسول اللہ صلی اللہ علیہ وسلم کے خلاف ایکا کر لیا تھا؟ انہوں نے جواب دیا : وہ حفصہ اور عائشہ رضی اللہ عنہن تھیں ۔ میں نے کہا : اللہ کی قسم! میں ایک سال سے اس کے بارے میں آپ سے پوچھنا چاہتا تھا مگر آپ کے رعب کی وجہ سے ہمت نہ پاتا تھا ۔ انہوں نے کہا : ایسا نہیں کرنا ، جو بات بھی تم سمجھو کہ مجھے علم ہے ، اس کے بارے میں مجھ سے پوچھ لیا کرو ، اگر میں جانتا ہوا تو تمہیں بتا دوں گا ۔ کہا : اور سیدنا عمر رضی اللہ عنہ نے کہا : اللہ کی قسم! جب ہم جاہلیت کے زمانے میں تھے تو عورتوں کو کسی شمار میں نہ رکھتے تھے ، حتی کہ اللہ تعالیٰ نے ان کے بارے میں جو نازل کیا ، سو نازل کیا ، اور جو ( مرتبہ ) انہیں دینا تھا سو دیا ۔ انہوں نے کہا : ایک مرتبہ میں کسی معاملے میں لگا ہوا تھا ، اس کے متعلق سوچ بچار کر رہا تھا کہ مجھے میری بیوی نے کہا : اگر آپ ایسا ایسا کر لیں ( تو بہتر ہو گا ۔ ) میں نے اسے جواب دیا : تمہیں اس سے کیا سروکار؟ اور یہاں ( اس معاملے میں ) تمہیں کیا دلچسپی ہے؟ اور ایک کام جو میں کرنا چاہتا ہوں اس میں تمہارا تکلف ( زبردستی ٹانگ اڑانا ) کیسا؟اس نے مجھے جواب دیا : ابن خطاب! آپ پر تعجب ہے! آپ یہ نہیں چاہتے کہ آپ کے بارے آگے بات کی جائے ، جبکہ آپ کی بیٹی رسول اللہ صلی اللہ علیہ وسلم کو ایسے پلٹ کر جواب دیتی ہے کہ آپ صلی اللہ علیہ وسلم دن بھر اس سے ناراض رہتے ہیں ۔ سیدنا عمر رضی اللہ عنہ نے کہا : میں ( اسی وقت ) اپنی چادر پکڑتا ہوں اور اپنی جگہ سے نکل کھڑا ہوتا ہوں ، یہاں تک کہ حفصہ کے پاس پہنچتا ہوں ۔ جا کر میں نے اس سے کہا : بٹیا! تم رسول اللہ صلی اللہ علیہ وسلم کو ایسے جواب دیتی ہو کہ وہ سارا دن ناراض رہتے ہیں ۔ حفصہ رضی اللہ عنہا نے جواب دیا : اللہ کی قسم! ہم آپ صلی اللہ علیہ وسلم کو جواب دے لیتی ہیں ۔ میں نے کہا : جان لو میں تمہیں اللہ کی سزا اور اس کے رسول صلی اللہ علیہ وسلم کی ناراضی سے ڈرا رہا ہوں ، میری بیٹی! تمہیں وہ ( عائشہ رضی اللہ عنہا اپنے رویے کی بنا پر ) دھوکے میں نہ ڈال دے جسے اپنے حسن اور رسول اللہ صلی اللہ علیہ وسلم کی اپنے سے محبت پر ناز ہے ۔ پھر میں نکلا حتی کہ ام سلمہ رضی اللہ عنہا کے ہاں آیا ، کیونکہ میری ان سے قرابت داری تھی ۔ میں نے ان سے بات کی تو ام سلمہ رضی اللہ عنہا نے مجھے جواب دیا : ابن خطاب تم پر تعجب ہے! تم ہر کام میں دخل اندازی کرتے ہو حتی کہ تم چاہتے ہو کہ رسول اللہ صلی اللہ علیہ وسلم اور ان کی ازواج کے مابین بھی دخل دو؟ انہوں نے مجھے اس طرح آڑے ہاتھوں لیا کہ جو ( عزم ) میں ( دل میں ) پا رہا تھا ( کہ میں ازواجِ مطہرات کو رسول اللہ صلی اللہ علیہ وسلم کے سامنے جواب دینے سے روک لوں گا ) مجھے توڑ کر اس سے الگ کر دیا ۔ چنانچہ میں ان کے ہاں سے نکل آیا ۔ میرا ایک انصاری ساتھی تھا ، جب میں ( آپ کی مجلس سے ) غیر حاضر ہوتا تو وہ میرے پاس ( وہاں کی ) خبر لاتا اور جب وہ غیر حاضر ہوتا تو میں اس کے پاس خبر لے آتا ۔ ہم اس زمانے میں غسان کے بادشاہوں میں سے ایک بادشاہ سے ڈر رہے تھے ۔ ہمیں بتایا گیا تھا کہ وہ ہم پر چڑھائی کرنا چاہتے ہے ۔ اس ( کی وجہ ) سے ہمارے سینے ( اندیشوں سے ) بھرے ہوئے تھے ۔ ( اچانک ایک دن ) میرا انصاری دوست آ کر دروازہ کھٹکھٹانے لگا اور کہنے لگا : کھولو ، کھولو! میں نے پوچھا : غسانی آ گیا ہے؟ اس نے کہا : اس سے بھی زیادہ سنگین معاملہ ہے ، رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیویوں سے علیحدگی اختیار کر لی ہے ۔ میں نے کہا : حفصہ اور عائشہ رضی اللہ عنھن کی ناک خاک آلود ہو! پھر میں اپنے کپرے لے کر نکل کھڑا ہوا ، حتی کہ ( رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں ) حاضر ہوا ۔ رسول اللہ صلی اللہ علیہ وسلم اپنے بالا خانے میں تھے جس پر سیڑھی کے ذریعے چڑھ کر جانا ہوتا تھا ، اور رسول اللہ صلی اللہ علیہ وسلم کا ایک سیاہ فام غلام سیڑھی کے سرے پر بیٹھا ہوا تھا ۔ میں نے کہا : یہ عمر ہے ( خدمت میں حاضری کی اجازت چاہتا ہے ) ، تو مجھے اجازت عطا ہوئی ۔ عمر رضی اللہ عنہ نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے یہ ساری بات بیان کی ، جب میں ام سلمہ رضی اللہ عنہا کی بات پر پہنچا تو رسول اللہ صلی اللہ علیہ وسلم مسکرا دیے ۔ آپ ایک چٹائی پر ( لیٹے ہوئے ) تھے ، آپ کے ( جسم مبارک ) اور اس ( چٹائی ) کے درمیان کچھ نہ تھا ۔ آپ کے سر کے نیچے چمڑے کا ایک تکیہ تھا جس میں کھجور کی چھال بھری ہوئی تھی ۔ آپ کے پاؤں کے قریب کیکر کی چھال کا چھوٹا سا گٹھا پڑا تھا اور آپ کے سر کے قریب کچھ کچے چمڑے لٹکے ہوئے تھے ۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کے پہلو پر چٹائی کے نشان دیکھے تو رو پڑا ۔ آپ نے پوچھا : \" تمہیں کیا رلا رہا ہے؟ \" عرض کی : اے اللہ کے رسول! کسریٰ اور قیصر دونوں ( کفر کے باوجود ) اُس ناز و نعمت میں ہیں جس میں ہیں اور آپ تو اللہ کے رسول ہیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کیا تمہیں پسند نہیں کہ ان کے لیے ( صرف ) دنیا ہو اور تمہارے لیے آخرت ہو","",{"u2":"سلیمان بن بلال نے کہا: مجھے یحییٰ نے عبید بن حنین سے خبر دی کہ انہوں نے عبداللہ بن عباس رضی اللہ عنہ سے سنا وہ حدیث بیان کر رہے تھے، انہوں نے کہا: میں نے سال بھر کے انتظار کیا، میں سیدنا عمر بن خطاب رضی اللہ عنہ سے ایک آیت کے بارے میں دریافت کرنا چاہتا تھا مگر ان کی ہیبت کی وجہ سے ان سے سوال کرنے کی ہمت نہ پاتا تھا، حتی کہ وہ حج کرنے کے لیے روانہ ہوئے، میں بھی ان کے ساتھ نکلا، جب لوٹے تو ہم راستے میں کسی جگہ تھے کہ وہ قضائے حاجت کے لیے پیلو کے درخت کی طرف چلے گئے، میں ان کے انتظار میں ٹھہر گیا، حتی کہ وہ فارغ ہو گئے، پھر میں ان کے ساتھ چل پڑا، میں نے عرض کی: امیر المومنین! رسول اللہ صلی اللہ علیہ وسلم کی ازواج میں سے وہ کون سی دو خواتین تھیں جنہوں نے رسول اللہ صلی اللہ علیہ وسلم کے خلاف ایکا کر لیا تھا؟ انہوں نے جواب دیا: وہ حفصہ اور عائشہ رضی اللہ عنہن تھیں۔ میں نے کہا: اللہ کی قسم! میں ایک سال سے اس کے بارے میں آپ سے پوچھنا چاہتا تھا مگر آپ کے رعب کی وجہ سے ہمت نہ پاتا تھا۔ انہوں نے کہا:ایسا نہیں کرنا، جو بات بھی تم سمجھو کہ مجھے علم ہے، اس کے بارے میں مجھ سے پوچھ لیا کرو، اگر میں جانتا ہوا تو تمہیں بتا دوں گا۔ کہا: اور سیدنا عمر رضی اللہ عنہ نے کہا: اللہ کی قسم! جب ہم جاہلیت کے زمانے میں تھے تو عورتوں کو کسی شمار میں نہ رکھتے تھے، حتی کہ اللہ تعالیٰ نے ان کے بارے میں جو نازل کیا، سو نازل کیا، اور جو (مرتبہ) انہیں دینا تھا سو دیا۔ انہوں نے کہا: ایک مرتبہ میں کسی معاملے میں لگا ہوا تھا، اس کے متعلق سوچ بچار کر رہا تھا کہ مجھے میری بیوی نے کہا: اگر آپ ایسا ایسا کر لیں (تو بہتر ہو گا۔) میں نے اسے جواب دیا: تمہیں اس سے کیا سروکار؟ اور یہاں (اس معاملے میں) تمہیں کیا دلچسپی ہے؟ اور ایک کام جو میں کرنا چاہتا ہوں اس میں تمہارا تکلف (زبردستی ٹانگ اڑانا) کیسا؟اس نے مجھے جواب دیا: ابن خطاب! آپ پر تعجب ہے! آپ یہ نہیں چاہتے کہ آپ کے بارے آگے بات کی جائے، جبکہ آپ کی بیٹی رسول اللہ صلی اللہ علیہ وسلم کو ایسے پلٹ کر جواب دیتی ہے کہ آپ صلی اللہ علیہ وسلم دن بھر اس سے ناراض رہتے ہیں۔ سیدنا عمر رضی اللہ عنہ نے کہا: میں (اسی وقت) اپنی چادر پکڑتا ہوں اور اپنی جگہ سے نکل کھڑا ہوتا ہوں، یہاں تک کہ حفصہ کے پاس پہنچتا ہوں۔ جا کر میں نے اس سے کہا: بٹیا! تم رسول اللہ صلی اللہ علیہ وسلم کو ایسے جواب دیتی ہو کہ وہ سارا دن ناراض رہتے ہیں۔ حفصہ رضی اللہ عنہا نے جواب دیا: اللہ کی قسم! ہم آپ صلی اللہ علیہ وسلم کو جواب دے لیتی ہیں۔ میں نے کہا: جان لو میں تمہیں اللہ کی سزا اور اس کے رسول صلی اللہ علیہ وسلم کی ناراضی سے ڈرا رہا ہوں، میری بیٹی! تمہیں وہ (عائشہ رضی اللہ عنہا اپنے رویے کی بنا پر)دھوکے میں نہ ڈال دے جسے اپنے حسن اور رسول اللہ صلی اللہ علیہ وسلم کی اپنے سے محبت پر ناز ہے۔ پھر میں نکلا حتی کہ ام سلمہ رضی اللہ عنہا کے ہاں آیا، کیونکہ میری ان سے قرابت داری تھی۔میں نے ان سے بات کی تو ام سلمہ رضی اللہ عنہا نے مجھے جواب دیا: ابن خطاب تم پر تعجب ہے! تم ہر کام میں دخل اندازی کرتے ہو حتی کہ تم چاہتے ہو کہ رسول اللہ صلی اللہ علیہ وسلم اور ان کی ازواج کے مابین بھی دخل دو؟ انہوں نے مجھے اس طرح آڑے ہاتھوں لیا کہ جو (عزم) میں (دل میں) پا رہا تھا (کہ میں ازواجِ مطہرات کو رسول اللہ صلی اللہ علیہ وسلم کے سامنے جواب دینے سے روک لوں گا) مجھے توڑ کر اس سے الگ کر دیا۔ چنانچہ میں ان کے ہاں سے نکل آیا۔ میرا ایک انصاری ساتھی تھا، جب میں (آپ کی مجلس سے) غیر حاضر ہوتا تو وہ میرے پاس (وہاں کی) خبر لاتا اور جب وہ غیر حاضر ہوتا تو میں اس کے پاس خبر لے آتا۔ ہم اس زمانے میں غسان کے بادشاہوں میں سے ایک بادشاہ سے ڈر رہے تھے۔ ہمیں بتایا گیا تھا کہ وہ ہم پر چڑھائی کرنا چاہتے ہے۔ اس (کی وجہ) سے ہمارے سینے (اندیشوں سے) بھرے ہوئے تھے۔ (اچانک ایک دن) میرا انصاری دوست آ کر دروازہ کھٹکھٹانے لگا اور کہنے لگا: کھولو، کھولو! میں نے پوچھا: غسانی آ گیا ہے؟ اس نے کہا: اس سے بھی زیادہ سنگین معاملہ ہے، رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیویوں سے علیحدگی اختیار کر لی ہے۔ میں نے کہا: حفصہ اور عائشہ رضی اللہ عنھن کی ناک خاک آلود ہو! پھر میں اپنے کپرے لے کر نکل کھڑا ہوا، حتی کہ (رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں) حاضر ہوا۔ رسول اللہ صلی اللہ علیہ وسلم اپنے بالا خانے میں تھے جس پر سیڑھی کے ذریعے چڑھ کر جانا ہوتا تھا، اور رسول اللہ صلی اللہ علیہ وسلم کا ایک سیاہ فام غلام سیڑھی کے سرے پر بیٹھا ہوا تھا۔ میں نے کہا: یہ عمر ہے (خدمت میں حاضری کی اجازت چاہتا ہے)، تو مجھے اجازت عطا ہوئی۔ عمر رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے یہ ساری بات بیان کی، جب میں ام سلمہ رضی اللہ عنہا کی بات پر پہنچا تو رسول اللہ صلی اللہ علیہ وسلم مسکرا دیے۔ آپ ایک چٹائی پر (لیٹے ہوئے) تھے، آپ کے (جسم مبارک) اور اس (چٹائی) کے درمیان کچھ نہ تھا۔ آپ کے سر کے نیچے چمڑے کا ایک تکیہ تھا جس میں کھجور کی چھال بھری ہوئی تھی۔ آپ کے پاؤں کے قریب کیکر کی چھال کا چھوٹا سا گٹھا پڑا تھا اور آپ کے سر کے قریب کچھ کچے چمڑے لٹکے ہوئے تھے۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کے پہلو پر چٹائی کے نشان دیکھے تو رو پڑا۔ آپ نے پوچھا: \"تمہیں کیا رلا رہا ہے؟\" عرض کی: اے اللہ کے رسول! کسریٰ اور قیصر دونوں (کفر کے باوجود) اُس ناز و نعمت میں ہیں جس میں ہیں اور آپ تو اللہ کے رسول ہیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تمہیں پسند نہیں کہ ان کے لیے (صرف) دنیا ہو اور تمہارے لیے آخرت ہو"}],[3661,"حماد بن سلمہ نے ہمیں حدیث بیان کی ، ( کہا : ) ہمیں یحییٰ بن سعید نے عبید بن حنین سے خبر دی ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، کہا : میں سیدنا عمر رضی اللہ عنہ کے ساتھ ( حج سے ) واپس آیا حتی کہ جب ہم مرالظہران میں تھے ۔ ۔ ۔ آگے سلیمان بن بلال کی حدیث کے مانند پوری لمبی حدیث بیان کی ، مگر انہوں ( ابن عباس رضی اللہ عنہ ) نے کہا : میں نے عرض کی : دو عورتوں کا معاملہ کیا تھا؟ انہوں نے جواب دیا : ( وہ ) حفصہ اور ام سلمہ رضی اللہ عنھن ( تھیں ۔ ) اور اس میں یہ اضافہ کیا : میں ( ازواج مطہرات کے ) حجروں کے پاس آیا تو ہر گھر میں رونے کی آواز تھی ، اور یہ بھی اضافہ کیا : آپ صلی اللہ علیہ وسلم نے ان سے ایک ماہ ایلاء کیا تھا ، جب 29 دن ہوئے تو آپ صلی اللہ علیہ وسلم ( بالا خانے سے ) اتر کر ان کے پاس تشریف لے آئے","",{"u2":"حماد بن سلمہ نے ہمیں حدیث بیان کی، (کہا:) ہمیں یحییٰ بن سعید نے عبید بن حنین سے خبر دی، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، کہا: میں سیدنا عمر رضی اللہ عنہ کے ساتھ (حج سے) واپس آیا حتی کہ جب ہم مرالظہران میں تھے۔۔۔ آگے سلیمان بن بلال کی حدیث کے مانند پوری لمبی حدیث بیان کی، مگر انہوں (ابن عباس رضی اللہ عنہ) نے کہا: میں نے عرض کی: دو عورتوں کا معاملہ کیا تھا؟ انہوں نے جواب دیا: (وہ) حفصہ اور ام سلمہ رضی اللہ عنھن (تھیں۔) اور اس میں یہ اضافہ کیا: میں (ازواج مطہرات کے) حجروں کے پاس آیا تو ہر گھر میں رونے کی آواز تھی، اور یہ بھی اضافہ کیا: آپ صلی اللہ علیہ وسلم نے ان سے ایک ماہ ایلاء کیا تھا، جب 29 دن ہوئے تو آپ صلی اللہ علیہ وسلم (بالا خانے سے) اتر کر ان کے پاس تشریف لے آئے"}],[3662,"سفیان بن عیینہ نے ہمیں یحییٰ بن سعید سے حدیث بیان کی ، انہوں نے عبید بن حنین سے سنا ، وہ سیدنا عباس رضی اللہ عنہ کے آزاد کردہ غلام تھے ۔ انہوں نے کہا : میں نے ابن عباس رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : میں سیدنا عمر رضی اللہ عنہ سے ان دو عورتوں کے بارے میں پوچھنا چاہتا تھا جنہوں نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایکا کیا تھا ، میں سال بھر منتظر رہا ، مجھے کوئی مناسب موقع نہ مل رہا تھا ، حتی کہ میں مکہ کے سفر میں ان کے ساتھ گیا ، جب ہم مر الظہران پہنچے تو وہ قضائے حاجت کے لیے گئے اور کہا : میرے پاس پانی کا ایک لوٹا لے آنا ، میں نے انہیں لا دیا ۔ جب وہ اپنی حاجت سے فارغ ہو کر لوٹے ، میں جا کر ان ( کے ہاتھوں ) پر پانی ڈالنے لگا ، تو مجھے ( سوال ) یاد آ گیا ، میں نے ان سے پوچھا : اے امیر المومنین! وہ کون سی دو عورتیں تھیں؟ میں نے ابھی اپنی بات ختم نہ کی تھی کہ انہوں نے جواب دیا : وہ عائشہ اور حفصہ رضی اللہ عنھن تھیں","",{"u2":"سفیان بن عیینہ نے ہمیں یحییٰ بن سعید سے حدیث بیان کی، انہوں نے عبید بن حنین سے سنا، وہ سیدنا عباس رضی اللہ عنہ کے آزاد کردہ غلام تھے۔ انہوں نے کہا: میں نے ابن عباس رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: میں سیدنا عمر رضی اللہ عنہ سے ان دو عورتوں کے بارے میں پوچھنا چاہتا تھا جنہوں نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایکا کیا تھا، میں سال بھر منتظر رہا، مجھے کوئی مناسب موقع نہ مل رہا تھا، حتی کہ میں مکہ کے سفر میں ان کے ساتھ گیا، جب ہم مر الظہران پہنچے تو وہ قضائے حاجت کے لیے گئے اور کہا: میرے پاس پانی کا ایک لوٹا لے آنا، میں نے انہیں لا دیا۔ جب وہ اپنی حاجت سے فارغ ہو کر لوٹے، میں جا کر ان (کے ہاتھوں) پر پانی ڈالنے لگا، تو مجھے (سوال) یاد آ گیا، میں نے ان سے پوچھا: اے امیر المومنین! وہ کون سی دو عورتیں تھیں؟ میں نے ابھی اپنی بات ختم نہ کی تھی کہ انہوں نے جواب دیا: وہ عائشہ اور حفصہ رضی اللہ عنھن تھیں"}],[3663,"معمر نے زہری سے ، انہوں نے عبیداللہ بن عبداللہ بن ابی ثور سے ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں شدت سے خواہش مند رہا تھا کہ سیدنا عمر رضی اللہ عنہ سے نبی صلی اللہ علیہ وسلم کی ازواج میں سے ان دو کے بارے میں سوال کروں جن کے متعلق اللہ تعالیٰ نے فرمایا : \"\" اگر تم دونوں اللہ سے توبہ کرتی ہو تو یقینا تمہارے دل آگے جھک گئے ہیں \"\" حتی کہ سیدنا عمر رضی اللہ عنہ نے حج ( کا سفر ) کیا اور میں نے بھی ان کے ساتھ حج کیا ، ( واپسی پر ) ہم راستے کے ایک حصے میں تھے کہ عمر رضی اللہ عنہ ( اپنی ضرورت کے لیے راستے سے ) ایک طرف ہٹ گئے اور میں بھی پانی کا برتن لیے ان کے ساتھ ہٹ گیا ، وہ صحرا میں چلے گئے ، پھر میرے پاس آئے تو میں نے ان کے ہاتھوں پر پانی انڈیلا ، انہوں نے وضو کیا تو میں نے کہا : اے امیر المومنین! نبی صلی اللہ علیہ وسلم کی بیویوں میں سے وہ دو کون سی تھیں جن کے بارے میں اللہ تعالیٰ نے فرمایا ہے : \"\" اگر تم دونوں اللہ سے توبہ کرو تو یقینا تمہارے دل جھک گئے ہیں؟ \"\" عمر رضی اللہ عنہ نے کہا : ابن عباس! تم پر تعجب ہے! ۔ ۔ ۔ زہری نے کہا : اللہ کی قسم! انہوں ( ابن عباس رضی اللہ عنہ ) نے جو سوال ان سے کیا ، وہ انہیں برا لگا اور انہوں نے ( اس کا جواب ) چھپایا بھی نہیں ۔ ۔ انہوں نے کہا : وہ حفصہ اور عائشہ رضی اللہ عنھن تھیں ۔ پھر سیدنا عمر رضی اللہ عنہ بات سنانے لگے اور کہا : ہم قریش کے لوگ ایسی قوم تھے جو اپنی عورتوں پر غالب تھے ، جب ہم مدینہ آئے تو ہم نے ایسے لوگ پائے جن پر ان کی عورتیں غالب تھیں ، چنانچہ ہماری عورتوں نے بھی ان کی عورتوں سے سیکھنا شروع کر دیا ۔ ( مردوں کو پلٹ کر جواب دینے لگیں ۔ ) عمر رضی اللہ عنہ نے کہا : میرا گھر بالائی علاقے بنی امیہ بن زید کے محلے میں تھا ، ایک دن میں اپنی بیوی پر ناراض ہوا ، تو وہ مجھے پلٹ کر جواب دینے لگی ، مجھے اس کا جواب دینا بڑا ناگوار گزرا تو اس نے کہا : تمہیں یہ ناگوار گزرتا ہے کہ میں تمہیں جواب دوں؟ اللہ کی قسم! نبی صلی اللہ علیہ وسلم کی ازواج بھی آپ صلی اللہ علیہ وسلم کو جواب دے دیتی ہیں ، اور ان میں سے کوئی ایک تو آپ صلی اللہ علیہ وسلم کو رات تک پورا دن چھوڑ بھی دیتی ہے ( روٹھی رہتی ہے ۔ ) میں چلا ، حفصہ رضی اللہ عنہا کے ہاں گیا اور کہا : کیا تم رسول اللہ صلی اللہ علیہ وسلم کو پلٹ کر جواب دے دیتی ہو؟ انہوں نے کہا : جی ہاں ۔ میں نے ( پھر ) پوچھا : کیا تم میں سے کوئی انہیں رات تک دن بھر کے لیے چھوڑ بھی دیتی ہے؟ انہوں نے کہا : جی ہاں! میں نے کہا : تم میں سے جس نے بھی ایسا کیا وہ ناکام ہوئی اور خسارے میں پڑی ۔ کیا تم میں سے کوئی اس بات سے بے خوف ہو جاتی ہے کہ اپنے رسول صلی اللہ علیہ وسلم کی ناراضی کی وجہ سے اللہ ( بھی ) اس پر ناراض ہو جائے گا تو وہ تباہ و برباد ہو جائے گی؟ ( آیندہ ) تم رسول اللہ صلی اللہ علیہ وسلم کو جواب دینا نہ ان سے کسی چیز کا مطالبہ کرنا ، تمہیں جو چاہئے مجھ سے مانگ لینا ۔ تمہیں یہ بات دھوکے میں نہ ڈال دے کہ تمہاری ہمسائی ( سوکن ) تم سے زیادہ خوبصورت اور رسول اللہ صلی اللہ علیہ وسلم کو زیادہ محبوب ہے ۔ ۔ ان کی مراد سیدہ عائشہ رضی اللہ عنہا سے تھی ۔ سیدنا عمر رضی اللہ عنہ نے کہا : ۔ ۔ انصار میں سے میرا ایک پڑوسی تھا ۔ ۔ ہم باری باری ( بالائی علاقے سے ) اتر کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوتے تھے ۔ ایک دن وہ اترتا اور ایک دن میں اترتا ، وہ میرے پاس وحی وغیرہ کی خبریں لاتا اور میں بھی ( اپنی باری کے دن ) اس کے پاس اسی طرح کی خبریں لاتا ۔ اور ( ان دنوں ) ہم آپس میں باتیں کر رہے تھے کہ غسانی ہمارے ساتھ لڑائی کرنے کے لیے گھوڑوں کو کھڑیاں لگا رہے تھے ، میرا ساتھی ( رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہونے کے لیے عوالی سے ) اترا ، پھر عشاء کے وقت میرے پاس آیا ، میرا دروازہ کھٹکھٹایا ، پھر مجھے آواز دی ، میں باہر نکلا تو اس نے کہا : ایک بہت بڑا واقعہ رونما ہو گیا ہے ۔ میں نے پوچھا : کیا ہوا؟ کیا غسانی آ گئے؟ اس نے کہا : نہیں ، بلکہ وہ اس سے بھی بڑا اور لمبا چوڑا ( معاملہ ) ہے ۔ نبی صلی اللہ علیہ وسلم نے اپنی بیویوں کو طلاق دے دی ہے ۔ میں نے کہا : حفصہ تو ناکام ہوئی اور خسارے میں پڑ گئی ۔ میں تو ( پہلے ہی ) سمجھتا تھا کہ ایسا ہونے والا ہے ۔ ( دوسرے دن ) جب میں صبح کی نماز پڑھ چکا تو اپنے کپڑے پہنے ، مدینہ میں آیا اور حفصہ کے پاس گیا ، وہ رو رہی تھی ۔ میں نے پوچھا : کیا رسول اللہ صلی اللہ علیہ وسلم نے تم سب کو طلاق دے دی ہے؟ اس نے کہا : میں نہیں جانتی ، البتہ آپ الگ تھلگ اس بالاخانے میں ہیں ۔ میں آپ کے سیاہ فام غلام کے پاس آیا ، اور اسے کہا ، عمر کے لیے اجازت مانگو ۔ وہ گیا ، پھر میری طرف باہر آیا اور کہا : میں نے آُ صلی اللہ علیہ وسلم کے سامنے تمہارا ذکر کیا مگر آپ خاموش رہے ۔ میں چلا آیا حتی کہ منبر کے پاس آ کر بیٹھ گیا ، تو وہاں بہت سے لوگ بیٹھے تھے ، ان میں سے بعض رو رہے تھے ، میں تھوڑی دیر بیٹھا ، پھر جو کیفیت مجھ پر طاری تھی وہ مجھ پر غالب آ گئی ۔ میں پھر غلام کے پاس آیا اور کہا : عمر کے لیے اجازت مانگو ، وہ اندر داخل ہوا ، پھر میری طرف باہر آیا اور کہا : میں نے آپ صلی اللہ علیہ وسلم کے سامنے تمہارا ذکر کیا ، مگر آپ خاموش رہے ۔ میں پیٹھ پھیر کر مڑا تو اچانک غلام مجھے بلانے لگا ، اور کہا : اندر چلے جاؤ ، آپ صلی اللہ علیہ وسلم نے تمہیں اجازت دے دی ہے ۔ میں اندر داخل ہوا ، رسول اللہ صلی اللہ علیہ وسلم کو سلام عرض کیا تو دیکھا کہ آپ بنتی کی ایک چٹائی پر سہارا لے کر بیٹھے تھے ، جس نے آپ کے پہلو پر نشان ڈال دیے تھے ، میں نے عرض کی : کیا آپ نے اللہ کے رسول! اپنی بیویوں کو طلاق دے دی ہے؟ آپ نے میری طرف ( دیکھتے ہوئے ) اپنا سر مبارک اٹھایا اور فرمایا : \"\" نہیں ۔ \"\" میں نے کہا : اللہ اکبر ۔ اللہ کے رسول! اگر آپ ہمیں دیکھتے تو ہم قریش ایسی قوم تھے جو اپنی بیویوں پر غالب رہتے تھے ۔ جب ہم مدینہ آئے تو ہم نے ایسی قوم کو پایا جن کی عورتیں ان پر غالب تھیں ، تو ہماری عورتوں نے بھی ان کی عورتوں ( کی عادت ) سے سیکھنا شروع کر دیا ، چنانچہ ایک دن میں اپنی بیوی پر برہم ہوا تو وہ مجھے پلٹ کر جواب دینے لگی ۔ مجھے اس کا جواب دینا انتہائی ناگوار گزرا ، اس نے کہا : تمہیں یہ ناگوار گزرتا ہے کہ میں تمہیں جواب دیتی ہوں؟ اللہ کی قسم! نبی صلی اللہ علیہ وسلم کی بیویاں بھی آپ کو جواب دے دیتی ہیں ، اور ان میں سے کوئی تو آپ کو رات تک چھوڑ بھی دیتی ( روٹھ بھی جاتی ) ہے ۔ تو میں نے کہا : ان میں سے جس نے ایسا کیا وہ ناکام ہوئی اور خسارے میں پڑی ۔ کیا ( یہ کام کر کے ) ان میں سے کوئی اس بات سے بے خوف ہو سکتی ہے کہ اپنے رسول کی ناراضی کی وجہ سے اللہ اس پر ناراض ہو جائے ( اگر ایسا ہوا ) تو وہ تباہ ہو گئی ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم مسکرا دیے تو میں نے کہا : اللہ کے رسول! میں حفصہ کے پاس گیا اور اس نے کہا : تمہیں یہ بات کسی دھوکے میں نہ ڈال دے کہ تمہاری ہمسائی ( سوکن ) تم سے زیادہ خوبصورت اور اللہ کے رسول صلی اللہ علیہ وسلم کو تم سے زیادہ محبوب ہے ۔ اس پر آپ دوبارہ مسکرائے تو میں نے عرض کی : اللہ کے رسول! ( کچھ دیر بیٹھ کر ) بات چیت کروں ، آپ نے فرمایا : \"\" ہاں ۔ \"\" چنانچہ میں بیٹھ گیا اور میں نے سر اوپر کر کے گھر میں نگاہ دوڑائی تو اللہ کی قسم! اس میں تین چمڑوں کے سوا کچھ نہ تھا جس پر نظر پڑتی ، میں نے عرض کی : اللہ کے رسول! دعا فرمائیے کہ اللہ آپ کی امت پر فراخی فرمائے ۔ فارسیوں اور رومیوں پر وسعت کی گئی ہے حالانکہ وہ اللہ تعالیٰ کی عبادت نہیں کرتے ۔ اس پر آپ صلی اللہ علیہ وسلم سیدھے ہو کر بیٹھ گئے ، پھر فرمایا : \"\" ابن خطاب! کیا تم کسی شک میں مبتلا ہو؟ یہ ایسے لوگ ہیں جنہیں ان ( کے حصے ) کی اچھی چیزیں جلد ہی دنیا میں دے دی گئی ہیں ۔ \"\" میں نے عرض کی : اللہ کے رسول! میرے لیے بخشش طلب کیجیے ۔ اور آپ نے ان ( ازواج ) پر سخت غصے کی وجہ سے قسم کھا لی تھی کہ ایک مہینہ ان کے پاس نہیں جائیں گے ۔ یہاں تک کہ اللہ تعالیٰ نے آپ پر عتاب فرمایا ۔ ( کہ بیویوں کی بات پر آپ کیوں غمزدہ ہوتے اور حلال چیزوں سے دور رہنے کی قسم کھاتے ہیں)","",{"u2":"معمر نے زہری سے، انہوں نے عبیداللہ بن عبداللہ بن ابی ثور سے، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں شدت سے خواہش مند رہا تھا کہ سیدنا عمر رضی اللہ عنہ سے نبی صلی اللہ علیہ وسلم کی ازواج میں سے ان دو کے بارے میں سوال کروں جن کے متعلق اللہ تعالیٰ نے فرمایا: \"اگر تم دونوں اللہ سے توبہ کرتی ہو تو یقینا تمہارے دل آگے جھک گئے ہیں\" حتی کہ سیدنا عمر رضی اللہ عنہ نے حج (کا سفر) کیا اور میں نے بھی ان کے ساتھ حج کیا، (واپسی پر) ہم راستے کے ایک حصے میں تھے کہ عمر رضی اللہ عنہ (اپنی ضرورت کے لیے راستے سے) ایک طرف ہٹ گئے اور میں بھی پانی کا برتن لیے ان کے ساتھ ہٹ گیا، وہ صحرا میں چلے گئے، پھر میرے پاس آئے تو میں نے ان کے ہاتھوں پر پانی انڈیلا، انہوں نے وضو کیا تو میں نے کہا: اے امیر المومنین! نبی صلی اللہ علیہ وسلم کی بیویوں میں سے وہ دو کون سی تھیں جن کے بارے میں اللہ تعالیٰ نے فرمایا ہے: \"اگر تم دونوں اللہ سے توبہ کرو تو یقینا تمہارے دل جھک گئے ہیں؟\" عمر رضی اللہ عنہ نے کہا: ابن عباس! تم پر تعجب ہے!۔۔۔ زہری نے کہا: اللہ کی قسم! انہوں (ابن عباس رضی اللہ عنہ) نے جو سوال ان سے کیا، وہ انہیں برا لگا اور انہوں نے (اس کا جواب) چھپایا بھی نہیں۔۔ انہوں نے کہا: وہ حفصہ اور عائشہ رضی اللہ عنھن تھیں۔ پھر سیدنا عمر رضی اللہ عنہ بات سنانے لگے اور کہا: ہم قریش کے لوگ ایسی قوم تھے جو اپنی عورتوں پر غالب تھے، جب ہم مدینہ آئے تو ہم نے ایسے لوگ پائے جن پر ان کی عورتیں غالب تھیں، چنانچہ ہماری عورتوں نے بھی ان کی عورتوں سے سیکھنا شروع کر دیا۔ (مردوں کو پلٹ کر جواب دینے لگیں۔) عمر رضی اللہ عنہ نے کہا: میرا گھر بالائی علاقے بنی امیہ بن زید کے محلے میں تھا، ایک دن میں اپنی بیوی پر ناراض ہوا، تو وہ مجھے پلٹ کر جواب دینے لگی، مجھے اس کا جواب دینا بڑا ناگوار گزرا تو اس نے کہا: تمہیں یہ ناگوار گزرتا ہے کہ میں تمہیں جواب دوں؟ اللہ کی قسم! نبی صلی اللہ علیہ وسلم کی ازواج بھی آپ صلی اللہ علیہ وسلم کو جواب دے دیتی ہیں، اور ان میں سے کوئی ایک تو آپ صلی اللہ علیہ وسلم کو رات تک پورا دن چھوڑ بھی دیتی ہے (روٹھی رہتی ہے۔) میں چلا، حفصہ رضی اللہ عنہا کے ہاں گیا اور کہا: کیا تم رسول اللہ صلی اللہ علیہ وسلم کو پلٹ کر جواب دے دیتی ہو؟ انہوں نے کہا: جی ہاں۔ میں نے (پھر) پوچھا: کیا تم میں سے کوئی انہیں رات تک دن بھر کے لیے چھوڑ بھی دیتی ہے؟ انہوں نے کہا: جی ہاں! میں نے کہا: تم میں سے جس نے بھی ایسا کیا وہ ناکام ہوئی اور خسارے میں پڑی۔ کیا تم میں سے کوئی اس بات سے بے خوف ہو جاتی ہے کہ اپنے رسول صلی اللہ علیہ وسلم کی ناراضی کی وجہ سے اللہ (بھی) اس پر ناراض ہو جائے گا تو وہ تباہ و برباد ہو جائے گی؟ (آیندہ) تم رسول اللہ صلی اللہ علیہ وسلم کو جواب دینا نہ ان سے کسی چیز کا مطالبہ کرنا، تمہیں جو چاہئے مجھ سے مانگ لینا۔ تمہیں یہ بات دھوکے میں نہ ڈال دے کہ تمہاری ہمسائی (سوکن) تم سے زیادہ خوبصورت اور رسول اللہ صلی اللہ علیہ وسلم کو زیادہ محبوب ہے۔۔ ان کی مراد سیدہ عائشہ رضی اللہ عنہا سے تھی۔\nسیدنا عمر رضی اللہ عنہ نے کہا:۔۔ انصار میں سے میرا ایک پڑوسی تھا۔۔ ہم باری باری (بالائی علاقے سے) اتر کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوتے تھے۔ ایک دن وہ اترتا اور ایک دن میں اترتا، وہ میرے پاس وحی وغیرہ کی خبریں لاتا اور میں بھی (اپنی باری کے دن) اس کے پاس اسی طرح کی خبریں لاتا۔ اور (ان دنوں) ہم آپس میں باتیں کر رہے تھے کہ غسانی ہمارے ساتھ لڑائی کرنے کے لیے گھوڑوں کو کھڑیاں لگا رہے تھے، میرا ساتھی (رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہونے کے لیے عوالی سے) اترا، پھر عشاء کے وقت میرے پاس آیا، میرا دروازہ کھٹکھٹایا، پھر مجھے آواز دی، میں باہر نکلا تو اس نے کہا: ایک بہت بڑا واقعہ رونما ہو گیا ہے۔ میں نے پوچھا: کیا ہوا؟ کیا غسانی آ گئے؟ اس نے کہا: نہیں، بلکہ وہ اس سے بھی بڑا اور لمبا چوڑا (معاملہ) ہے۔ نبی صلی اللہ علیہ وسلم نے اپنی بیویوں کو طلاق دے دی ہے۔ میں نے کہا: حفصہ تو ناکام ہوئی اور خسارے میں پڑ گئی۔ میں تو (پہلے ہی) سمجھتا تھا کہ ایسا ہونے والا ہے۔ (دوسرے دن) جب میں صبح کی نماز پڑھ چکا تو اپنے کپڑے پہنے، مدینہ میں آیا اور حفصہ کے پاس گیا، وہ رو رہی تھی۔ میں نے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم نے تم سب کو طلاق دے دی ہے؟ اس نے کہا: میں نہیں جانتی، البتہ آپ الگ تھلگ اس بالاخانے میں ہیں۔ میں آپ کے سیاہ فام غلام کے پاس آیا، اور اسے کہا، عمر کے لیے اجازت مانگو۔ وہ گیا، پھر میری طرف باہر آیا اور کہا: میں نے آُ صلی اللہ علیہ وسلم کے سامنے تمہارا ذکر کیا مگر آپ خاموش رہے۔ میں چلا آیا حتی کہ منبر کے پاس آ کر بیٹھ گیا، تو وہاں بہت سے لوگ بیٹھے تھے، ان میں سے بعض رو رہے تھے، میں تھوڑی دیر بیٹھا، پھر جو کیفیت مجھ پر طاری تھی وہ مجھ پر غالب آ گئی۔ میں پھر غلام کے پاس آیا اور کہا: عمر کے لیے اجازت مانگو، وہ اندر داخل ہوا، پھر میری طرف باہر آیا اور کہا: میں نے آپ صلی اللہ علیہ وسلم کے سامنے تمہارا ذکر کیا، مگر آپ خاموش رہے۔ میں پیٹھ پھیر کر مڑا تو اچانک غلام مجھے بلانے لگا، اور کہا: اندر چلے جاؤ، آپ صلی اللہ علیہ وسلم نے تمہیں اجازت دے دی ہے۔ میں اندر داخل ہوا، رسول اللہ صلی اللہ علیہ وسلم کو سلام عرض کیا تو دیکھا کہ آپ بنتی کی ایک چٹائی پر سہارا لے کر بیٹھے تھے، جس نے آپ کے پہلو پر نشان ڈال دیے تھے، میں نے عرض کی: کیا آپ نے اللہ کے رسول! اپنی بیویوں کو طلاق دے دی ہے؟ آپ نے میری طرف (دیکھتے ہوئے) اپنا سر مبارک اٹھایا اور فرمایا: \"نہیں۔\" میں نے کہا: اللہ اکبر۔اللہ کے رسول! اگر آپ ہمیں دیکھتے تو ہم قریش ایسی قوم تھے جو اپنی بیویوں پر غالب رہتے تھے۔ جب ہم مدینہ آئے تو ہم نے ایسی قوم کو پایا جن کی عورتیں ان پر غالب تھیں، تو ہماری عورتوں نے بھی ان کی عورتوں (کی عادت) سے سیکھنا شروع کر دیا، چنانچہ ایک دن میں اپنی بیوی پر برہم ہوا تو وہ مجھے پلٹ کر جواب دینے لگی۔ مجھے اس کا جواب دینا انتہائی ناگوار گزرا، اس نے کہا: تمہیں یہ ناگوار گزرتا ہے کہ میں تمہیں جواب دیتی ہوں؟ اللہ کی قسم! نبی صلی اللہ علیہ وسلم کی بیویاں بھی آپ کو جواب دے دیتی ہیں، اور ان میں سے کوئی تو آپ کو رات تک چھوڑ بھی دیتی (روٹھ بھی جاتی) ہے۔ تو میں نے کہا: ان میں سے جس نے ایسا کیا وہ ناکام ہوئی اور خسارے میں پڑی۔ کیا (یہ کام کر کے) ان میں سے کوئی اس بات سے بے خوف ہو سکتی ہے کہ اپنے رسول کی ناراضی کی وجہ سے اللہ اس پر ناراض ہو جائے (اگر ایسا ہوا) تو وہ تباہ ہو گئی۔ اس پر رسول اللہ صلی اللہ علیہ وسلم مسکرا دیے تو میں نے کہا: اللہ کے رسول! میں حفصہ کے پاس گیا اور اس نے کہا: تمہیں یہ بات کسی دھوکے میں نہ ڈال دے کہ تمہاری ہمسائی (سوکن) تم سے زیادہ خوبصورت اور اللہ کے رسول صلی اللہ علیہ وسلم کو تم سے زیادہ محبوب ہے۔ اس پر آپ دوبارہ مسکرائے تو میں نے عرض کی: اللہ کے رسول! (کچھ دیر بیٹھ کر) بات چیت کروں، آپ نے فرمایا: \"ہاں۔\" چنانچہ میں بیٹھ گیا اور میں نے سر اوپر کر کے گھر میں نگاہ دوڑائی تو اللہ کی قسم! اس میں تین چمڑوں کے سوا کچھ نہ تھا جس پر نظر پڑتی، میں نے عرض کی: اللہ کے رسول! دعا فرمائیے کہ اللہ آپ کی امت پر فراخی فرمائے۔ فارسیوں اور رومیوں پر وسعت کی گئی ہے حالانکہ وہ اللہ تعالیٰ کی عبادت نہیں کرتے۔ اس پر آپ صلی اللہ علیہ وسلم سیدھے ہو کر بیٹھ گئے، پھر فرمایا: \"ابن خطاب! کیا تم کسی شک میں مبتلا ہو؟ یہ ایسے لوگ ہیں جنہیں ان (کے حصے) کی اچھی چیزیں جلد ہی دنیا میں دے دی گئی ہیں۔\" میں نے عرض کی: اللہ کے رسول! میرے لیے بخشش طلب کیجیے۔ اور آپ نے ان (ازواج) پر سخت غصے کی وجہ سے قسم کھا لی تھی کہ ایک مہینہ ان کے پاس نہیں جائیں گے۔ یہاں تک کہ اللہ تعالیٰ نے آپ پر عتاب فرمایا۔ (کہ بیویوں کی بات پر آپ کیوں غمزدہ ہوتے اور حلال چیزوں سے دور رہنے کی قسم کھاتے ہیں"}],[3664,"معمر نے زہری سے ، انہوں نے عبیداللہ بن عبداللہ بن ابی ثور سے ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں شدت سے خواہش مند رہا تھا کہ سیدنا عمر رضی اللہ عنہ سے نبی صلی اللہ علیہ وسلم کی ازواج میں سے ان دو کے بارے میں سوال کروں جن کے متعلق اللہ تعالیٰ نے فرمایا : \"\" اگر تم دونوں اللہ سے توبہ کرتی ہو تو یقینا تمہارے دل آگے جھک گئے ہیں \"\" حتی کہ سیدنا عمر رضی اللہ عنہ نے حج ( کا سفر ) کیا اور میں نے بھی ان کے ساتھ حج کیا ، ( واپسی پر ) ہم راستے کے ایک حصے میں تھے کہ عمر رضی اللہ عنہ ( اپنی ضرورت کے لیے راستے سے ) ایک طرف ہٹ گئے اور میں بھی پانی کا برتن لیے ان کے ساتھ ہٹ گیا ، وہ صحرا میں چلے گئے ، پھر میرے پاس آئے تو میں نے ان کے ہاتھوں پر پانی انڈیلا ، انہوں نے وضو کیا تو میں نے کہا : اے امیر المومنین! نبی صلی اللہ علیہ وسلم کی بیویوں میں سے وہ دو کون سی تھیں جن کے بارے میں اللہ تعالیٰ نے فرمایا ہے : \"\" اگر تم دونوں اللہ سے توبہ کرو تو یقینا تمہارے دل جھک گئے ہیں؟ \"\" عمر رضی اللہ عنہ نے کہا : ابن عباس! تم پر تعجب ہے! ۔ ۔ ۔ زہری نے کہا : اللہ کی قسم! انہوں ( ابن عباس رضی اللہ عنہ ) نے جو سوال ان سے کیا ، وہ انہیں برا لگا اور انہوں نے ( اس کا جواب ) چھپایا بھی نہیں ۔ ۔ انہوں نے کہا : وہ حفصہ اور عائشہ رضی اللہ عنھن تھیں ۔ پھر سیدنا عمر رضی اللہ عنہ بات سنانے لگے اور کہا : ہم قریش کے لوگ ایسی قوم تھے جو اپنی عورتوں پر غالب تھے ، جب ہم مدینہ آئے تو ہم نے ایسے لوگ پائے جن پر ان کی عورتیں غالب تھیں ، چنانچہ ہماری عورتوں نے بھی ان کی عورتوں سے سیکھنا شروع کر دیا ۔ ( مردوں کو پلٹ کر جواب دینے لگیں ۔ ) عمر رضی اللہ عنہ نے کہا : میرا گھر بالائی علاقے بنی امیہ بن زید کے محلے میں تھا ، ایک دن میں اپنی بیوی پر ناراض ہوا ، تو وہ مجھے پلٹ کر جواب دینے لگی ، مجھے اس کا جواب دینا بڑا ناگوار گزرا تو اس نے کہا : تمہیں یہ ناگوار گزرتا ہے کہ میں تمہیں جواب دوں؟ اللہ کی قسم! نبی صلی اللہ علیہ وسلم کی ازواج بھی آپ صلی اللہ علیہ وسلم کو جواب دے دیتی ہیں ، اور ان میں سے کوئی ایک تو آپ صلی اللہ علیہ وسلم کو رات تک پورا دن چھوڑ بھی دیتی ہے ( روٹھی رہتی ہے ۔ ) میں چلا ، حفصہ رضی اللہ عنہا کے ہاں گیا اور کہا : کیا تم رسول اللہ صلی اللہ علیہ وسلم کو پلٹ کر جواب دے دیتی ہو؟ انہوں نے کہا : جی ہاں ۔ میں نے ( پھر ) پوچھا : کیا تم میں سے کوئی انہیں رات تک دن بھر کے لیے چھوڑ بھی دیتی ہے؟ انہوں نے کہا : جی ہاں! میں نے کہا : تم میں سے جس نے بھی ایسا کیا وہ ناکام ہوئی اور خسارے میں پڑی ۔ کیا تم میں سے کوئی اس بات سے بے خوف ہو جاتی ہے کہ اپنے رسول صلی اللہ علیہ وسلم کی ناراضی کی وجہ سے اللہ ( بھی ) اس پر ناراض ہو جائے گا تو وہ تباہ و برباد ہو جائے گی؟ ( آیندہ ) تم رسول اللہ صلی اللہ علیہ وسلم کو جواب دینا نہ ان سے کسی چیز کا مطالبہ کرنا ، تمہیں جو چاہئے مجھ سے مانگ لینا ۔ تمہیں یہ بات دھوکے میں نہ ڈال دے کہ تمہاری ہمسائی ( سوکن ) تم سے زیادہ خوبصورت اور رسول اللہ صلی اللہ علیہ وسلم کو زیادہ محبوب ہے ۔ ۔ ان کی مراد سیدہ عائشہ رضی اللہ عنہا سے تھی ۔ سیدنا عمر رضی اللہ عنہ نے کہا : ۔ ۔ انصار میں سے میرا ایک پڑوسی تھا ۔ ۔ ہم باری باری ( بالائی علاقے سے ) اتر کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوتے تھے ۔ ایک دن وہ اترتا اور ایک دن میں اترتا ، وہ میرے پاس وحی وغیرہ کی خبریں لاتا اور میں بھی ( اپنی باری کے دن ) اس کے پاس اسی طرح کی خبریں لاتا ۔ اور ( ان دنوں ) ہم آپس میں باتیں کر رہے تھے کہ غسانی ہمارے ساتھ لڑائی کرنے کے لیے گھوڑوں کو کھڑیاں لگا رہے تھے ، میرا ساتھی ( رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہونے کے لیے عوالی سے ) اترا ، پھر عشاء کے وقت میرے پاس آیا ، میرا دروازہ کھٹکھٹایا ، پھر مجھے آواز دی ، میں باہر نکلا تو اس نے کہا : ایک بہت بڑا واقعہ رونما ہو گیا ہے ۔ میں نے پوچھا : کیا ہوا؟ کیا غسانی آ گئے؟ اس نے کہا : نہیں ، بلکہ وہ اس سے بھی بڑا اور لمبا چوڑا ( معاملہ ) ہے ۔ نبی صلی اللہ علیہ وسلم نے اپنی بیویوں کو طلاق دے دی ہے ۔ میں نے کہا : حفصہ تو ناکام ہوئی اور خسارے میں پڑ گئی ۔ میں تو ( پہلے ہی ) سمجھتا تھا کہ ایسا ہونے والا ہے ۔ ( دوسرے دن ) جب میں صبح کی نماز پڑھ چکا تو اپنے کپڑے پہنے ، مدینہ میں آیا اور حفصہ کے پاس گیا ، وہ رو رہی تھی ۔ میں نے پوچھا : کیا رسول اللہ صلی اللہ علیہ وسلم نے تم سب کو طلاق دے دی ہے؟ اس نے کہا : میں نہیں جانتی ، البتہ آپ الگ تھلگ اس بالاخانے میں ہیں ۔ میں آپ کے سیاہ فام غلام کے پاس آیا ، اور اسے کہا ، عمر کے لیے اجازت مانگو ۔ وہ گیا ، پھر میری طرف باہر آیا اور کہا : میں نے آُ صلی اللہ علیہ وسلم کے سامنے تمہارا ذکر کیا مگر آپ خاموش رہے ۔ میں چلا آیا حتی کہ منبر کے پاس آ کر بیٹھ گیا ، تو وہاں بہت سے لوگ بیٹھے تھے ، ان میں سے بعض رو رہے تھے ، میں تھوڑی دیر بیٹھا ، پھر جو کیفیت مجھ پر طاری تھی وہ مجھ پر غالب آ گئی ۔ میں پھر غلام کے پاس آیا اور کہا : عمر کے لیے اجازت مانگو ، وہ اندر داخل ہوا ، پھر میری طرف باہر آیا اور کہا : میں نے آپ صلی اللہ علیہ وسلم کے سامنے تمہارا ذکر کیا ، مگر آپ خاموش رہے ۔ میں پیٹھ پھیر کر مڑا تو اچانک غلام مجھے بلانے لگا ، اور کہا : اندر چلے جاؤ ، آپ صلی اللہ علیہ وسلم نے تمہیں اجازت دے دی ہے ۔ میں اندر داخل ہوا ، رسول اللہ صلی اللہ علیہ وسلم کو سلام عرض کیا تو دیکھا کہ آپ بنتی کی ایک چٹائی پر سہارا لے کر بیٹھے تھے ، جس نے آپ کے پہلو پر نشان ڈال دیے تھے ، میں نے عرض کی : کیا آپ نے اللہ کے رسول! اپنی بیویوں کو طلاق دے دی ہے؟ آپ نے میری طرف ( دیکھتے ہوئے ) اپنا سر مبارک اٹھایا اور فرمایا : \"\" نہیں ۔ \"\" میں نے کہا : اللہ اکبر ۔ اللہ کے رسول! اگر آپ ہمیں دیکھتے تو ہم قریش ایسی قوم تھے جو اپنی بیویوں پر غالب رہتے تھے ۔ جب ہم مدینہ آئے تو ہم نے ایسی قوم کو پایا جن کی عورتیں ان پر غالب تھیں ، تو ہماری عورتوں نے بھی ان کی عورتوں ( کی عادت ) سے سیکھنا شروع کر دیا ، چنانچہ ایک دن میں اپنی بیوی پر برہم ہوا تو وہ مجھے پلٹ کر جواب دینے لگی ۔ مجھے اس کا جواب دینا انتہائی ناگوار گزرا ، اس نے کہا : تمہیں یہ ناگوار گزرتا ہے کہ میں تمہیں جواب دیتی ہوں؟ اللہ کی قسم! نبی صلی اللہ علیہ وسلم کی بیویاں بھی آپ کو جواب دے دیتی ہیں ، اور ان میں سے کوئی تو آپ کو رات تک چھوڑ بھی دیتی ( روٹھ بھی جاتی ) ہے ۔ تو میں نے کہا : ان میں سے جس نے ایسا کیا وہ ناکام ہوئی اور خسارے میں پڑی ۔ کیا ( یہ کام کر کے ) ان میں سے کوئی اس بات سے بے خوف ہو سکتی ہے کہ اپنے رسول کی ناراضی کی وجہ سے اللہ اس پر ناراض ہو جائے ( اگر ایسا ہوا ) تو وہ تباہ ہو گئی ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم مسکرا دیے تو میں نے کہا : اللہ کے رسول! میں حفصہ کے پاس گیا اور اس نے کہا : تمہیں یہ بات کسی دھوکے میں نہ ڈال دے کہ تمہاری ہمسائی ( سوکن ) تم سے زیادہ خوبصورت اور اللہ کے رسول صلی اللہ علیہ وسلم کو تم سے زیادہ محبوب ہے ۔ اس پر آپ دوبارہ مسکرائے تو میں نے عرض کی : اللہ کے رسول! ( کچھ دیر بیٹھ کر ) بات چیت کروں ، آپ نے فرمایا : \"\" ہاں ۔ \"\" چنانچہ میں بیٹھ گیا اور میں نے سر اوپر کر کے گھر میں نگاہ دوڑائی تو اللہ کی قسم! اس میں تین چمڑوں کے سوا کچھ نہ تھا جس پر نظر پڑتی ، میں نے عرض کی : اللہ کے رسول! دعا فرمائیے کہ اللہ آپ کی امت پر فراخی فرمائے ۔ فارسیوں اور رومیوں پر وسعت کی گئی ہے حالانکہ وہ اللہ تعالیٰ کی عبادت نہیں کرتے ۔ اس پر آپ صلی اللہ علیہ وسلم سیدھے ہو کر بیٹھ گئے ، پھر فرمایا : \"\" ابن خطاب! کیا تم کسی شک میں مبتلا ہو؟ یہ ایسے لوگ ہیں جنہیں ان ( کے حصے ) کی اچھی چیزیں جلد ہی دنیا میں دے دی گئی ہیں ۔ \"\" میں نے عرض کی : اللہ کے رسول! میرے لیے بخشش طلب کیجیے ۔ اور آپ نے ان ( ازواج ) پر سخت غصے کی وجہ سے قسم کھا لی تھی کہ ایک مہینہ ان کے پاس نہیں جائیں گے ۔ یہاں تک کہ اللہ تعالیٰ نے آپ پر عتاب فرمایا ۔ ( کہ بیویوں کی بات پر آپ کیوں غمزدہ ہوتے اور حلال چیزوں سے دور رہنے کی قسم کھاتے ہیں)","",{"u2":"زہری نے کہا: مجھے عروہ نے سیدہ عائشہ رضی اللہ عنہا سے خبر دی، انہوں نے کہا: جب انتیس راتیں گزر گئیں، رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے، آپ نے میرے (گھر) سے ابتدا کی، میں نے عرض کی: اللہ کے رسول! آپ نے قسم کھائی تھی کہ مہینہ بھر ہمارے پاس نہیں آئیں گے، اور آپ انتیسویں دن تشریف لائے ہیں، میں انہیں شمار کرتی رہی ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"بلاشبہ مہینہ انتیس دن کا ہے۔\" پھر فرمایا: \"عائشہ! میں تم سے ایک بات کرنے لگا ہوں، تمہارے لیے کوئی حرج نہیں کہ تم اپنے والدین سے بھی مشورہ کرنے تک اس میں جلدی نہ کرو۔\" پھر آپ نے میرے سامنے تلاوت فرمائی: \"اے نبی! اپنی بیویوں سے کہہ دیجیے\" سے لے کر \"بہت بڑا اجر ہے\" تک پہنچ گئے۔ عائشہ رضی اللہ عنہا نے کہا: اللہ کی قسم! آپ کو بخوبی علم تھا کہ میرے والدین مجھے کبھی آپ سے جدائی کا مشورہ نہیں دیں گے۔ کہا: تو میں نے عرض کی: کیا میں اس کے بارے میں اپنے والدین سے مشورہ کروں گی؟ میں یقینا اللہ، اس کے رسول صلی اللہ علیہ وسلم اور آخرت کے گھر کی طلب گار ہوں۔\nمعمر نے کہا: مجھے ایوب نے خبر دی کہ سیدہ عائشہ رضی اللہ عنہا نے کہا: آپ اپنی دوسری بیویوں کو نہ بتائیں کہ میں نے آپ کو چن لیا ہے۔ تو نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: \"اللہ تعالیٰ نے مجھے مبلغ (پہنچانے والا) بنا کر بھیجا ہے، کمزوریاں ڈھونڈنے والا بنا کر نہیں بھیجا۔\"\nقتادہ نے کہا: (صَغَتْ قُلُوبُکُمَا ۖ) (التحریم: 4:66) کا معنی ہے: تم دونوں کے دل مائل ہو چکے ہیں"}],[3665,"اسود بن سفیان کے مولیٰ عبداللہ بن یزید نے ابوسلمہ بن عبدالرحمٰن سے ، انہوں نے فاطمہ بنت قیس رضی اللہ عنہا سے روایت کی کہ ابو عمرو بن حفص رضی اللہ عنہ نے انہیں طلاق بتہ ( حتمی ، تیسری طلاق ) دے دی ، اور وہ خود غیر حاضر تھے ، ان کے وکیل نے ان کی طرف سے کچھ جَو ( وغیرہ ) بھیجے ، تو وہ اس پر ناراض ہوئیں ، اس ( وکیل ) نے کہا : اللہ کی قسم! تمہارا ہم پر کوئی حق نہیں ۔ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں ، اور یہ بات آپ کو بتائی ۔ آپ نے فرمایا : \" اب تمہارا خرچ اس کے ذمے نہیں ۔ \" اور آپ نے انہیں حکم دیا کہ وہ ام شریک رضی اللہ عنہا کے گھر میں عدت گزاریں ، پھر فرمایا : \" اس عورت کے پاس میرے صحابہ آتے جاتے ہیں ، تم ابن مکتوم رضی اللہ عنہ کے ہاں عدت گزر لو ، وہ نابینا آدمی ہیں ، تم اپنے ( اوڑھنے کے ) کپڑے بھی اتار سکتی ہو ۔ تم جب ( عدت کی بندش سے ) آزاد ہو جاؤ تو مجھے بتانا ۔ \" جب میں ( عدت سے ) فارغ ہوئی ، تو میں نے آپ صلی اللہ علیہ وسلم نے بتایا کہ معاویہ بن ابی سفیان اور ابوجہم رضی اللہ عنہم دونوں نے مجھے نکاح کا پیغام بھیجا ہے ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ابوجہم تو اپنے کندھے سے لاٹھی نہیں اتارتا ، اور رہا معاویہ تو وہ انتہائی فقیر ہے ، اس کے پاس کوئی مال نہیں ، تم اسامہ بن زید رضی اللہ عنہ سے نکاح کر لو ۔ \" میں نے اسے ناپسند کیا ، آپ نے پھر فرمایا : \" اسامہ سے نکاح کر لو ۔ \" تو میں نے ان سے نکاح کر لیا ، اللہ نے اس میں خیر ڈال دی اور اس کی وجہ سے مجھ پر رشک کیا جانے لگا","",{"u2":"اسود بن سفیان کے مولیٰ عبداللہ بن یزید نے ابوسلمہ بن عبدالرحمٰن سے، انہوں نے فاطمہ بنت قیس رضی اللہ عنہا سے روایت کی کہ ابو عمرو بن حفص رضی اللہ عنہ نے انہیں طلاق بتہ (حتمی، تیسری طلاق) دے دی، اور وہ خود غیر حاضر تھے، ان کے وکیل نے ان کی طرف سے کچھ جَو (وغیرہ) بھیجے، تو وہ اس پر ناراض ہوئیں، اس (وکیل) نے کہا: اللہ کی قسم! تمہارا ہم پر کوئی حق نہیں۔ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں، اور یہ بات آپ کو بتائی۔ آپ نے فرمایا: \"اب تمہارا خرچ اس کے ذمے نہیں۔\" اور آپ نے انہیں حکم دیا کہ وہ ام شریک رضی اللہ عنہا کے گھر میں عدت گزاریں، پھر فرمایا: \"اس عورت کے پاس میرے صحابہ آتے جاتے ہیں، تم ابن مکتوم رضی اللہ عنہ کے ہاں عدت گزر لو، وہ نابینا آدمی ہیں، تم اپنے (اوڑھنے کے) کپڑے بھی اتار سکتی ہو۔ تم جب (عدت کی بندش سے) آزاد ہو جاؤ تو مجھے بتانا۔\" جب میں (عدت سے) فارغ ہوئی، تو میں نے آپ صلی اللہ علیہ وسلم نے بتایا کہ معاویہ بن ابی سفیان اور ابوجہم رضی اللہ عنہم دونوں نے مجھے نکاح کا پیغام بھیجا ہے۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ابوجہم تو اپنے کندھے سے لاٹھی نہیں اتارتا، اور رہا معاویہ تو وہ انتہائی فقیر ہے، اس کے پاس کوئی مال نہیں، تم اسامہ بن زید رضی اللہ عنہ سے نکاح کر لو۔\" میں نے اسے ناپسند کیا، آپ نے پھر فرمایا: \"اسامہ سے نکاح کر لو۔\" تو میں نے ان سے نکاح کر لیا، اللہ نے اس میں خیر ڈال دی اور اس کی وجہ سے مجھ پر رشک کیا جانے لگا"}],[3666,"ابوحازم نے ابوسلمہ سے ، انہوں نے فاطمہ بنت قیس رضی اللہ عنہا سے روایت کی کہ نبی صلی اللہ علیہ وسلم کے عہد میں ان کے شوہر نے انہیں طلاق دے دی ، اور اس نے انہیں بہت حقیر سا خرچ دیا ، جب انہوں نے اسے دیکھا تو کہا : اللہ کی قسم! میں ( اس بات سے ) رسول اللہ صلی اللہ علیہ وسلم کو ضرور آگاہ کروں گی ، اگر میرے لیے خرچ ہے تو اتنا لوں گی جو میری گزران درست کر دے ، اگر میرے لیے خرچ نہیں ہے تو میں اس سے کچھ بھی نہیں لوں گی ۔ انہوں نے کہا : میں نے اس بات کا ذکر رسول اللہ صلی اللہ علیہ وسلم سے کیا تو آپ نے فرمایا : \" تمہارے لیے نہ خرچ ہے اور نہ رہائش ۔"],[3667,"عمران بن ابی انس نے ابوسلمہ سے روایت کی ، انہوں نے کہا : میں نے فاطمہ بنت قیس رضی اللہ عنہا سے دریافت کیا تو انہوں نے مجھے بتایا کہ ان کے مخزومی شوہر نے انہیں طلاق دے دی اور ان پر خرچ کرنے سے بھی انکار کر دیا ، تو وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور آپ کو اس بات کی خبر دی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تمہارے لیے خرچ نہیں ہے ۔ ( وہاں سے ) منتقل ہو کر ابن ام مکتوم رضی اللہ عنہ کے ہاں چلی جاؤ اور وہیں رہو ، وہ نابینا آدمی ہیں ، تم وہاں اپنے ( اوڑھنے کے ) کپڑے بھی اتار سکو گی","",{"u2":"ابوحازم نے ابوسلمہ سے، انہوں نے فاطمہ بنت قیس رضی اللہ عنہا سے روایت کی کہ نبی صلی اللہ علیہ وسلم کے عہد میں ان کے شوہر نے انہیں طلاق دے دی، اور اس نے انہیں بہت حقیر سا خرچ دیا، جب انہوں نے اسے دیکھا تو کہا: اللہ کی قسم! میں (اس بات سے) رسول اللہ صلی اللہ علیہ وسلم کو ضرور آگاہ کروں گی، اگر میرے لیے خرچ ہے تو اتنا لوں گی جو میری گزران درست کر دے، اگر میرے لیے خرچ نہیں ہے تو میں اس سے کچھ بھی نہیں لوں گی۔ انہوں نے کہا: میں نے اس بات کا ذکر رسول اللہ صلی اللہ علیہ وسلم سے کیا تو آپ نے فرمایا: \"تمہارے لیے نہ خرچ ہے اور نہ رہائش۔\"\nعمران بن ابی انس نے ابوسلمہ سے روایت کی، انہوں نے کہا: میں نے فاطمہ بنت قیس رضی اللہ عنہا سے دریافت کیا تو انہوں نے مجھے بتایا کہ ان کے مخزومی شوہرنے انہیں طلاق دے دی اور ان پر خرچ کرنے سے بھی انکار کر دیا، تو وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور آپ کو اس بات کی خبر دی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے لیے خرچ نہیں ہے۔ (وہاں سے) منتقل ہو کر ابن ام مکتوم رضی اللہ عنہ کے ہاں چلی جاؤ اور وہیں رہو، وہ نابینا آدمی ہیں، تم وہاں اپنے (اوڑھنے کے) کپڑے بھی اتار سکو گی"}],[3668,"یحییٰ بن ابی کثیر سے روایت ہے ، ( کہا : ) مجھے ابوسلمہ نے خبر دی کہ ضحاک بن قیس رضی اللہ عنہ کی ہمشیرہ فاطمہ بنت قیس رضی اللہ عنہا نے انہیں بتایا کہ ابوحفص بن مغیرہ مخزومی نے اسے تین طلاقیں دے دیں ، پھر یمن کی طرف طلا گیا ، تو اس کے عزیز و اقارب نے اسے کہا : تمہارا خرچ ہمارے ذمے نہیں ہے ۔ خالد بن ولید رضی اللہ عنہ چند ساتھیوں کے ہمراہ آئے ، سیدہ میمونہ رضی اللہ عنہا کے گھر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی : ابوحفص نے اپنی بیوی کو تین طلاقیں دے دی ہیں ، کیا اس ( کی سابقہ بیوی ) کے لیے خرچہ ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اس کے لیے خرچہ نہیں ہے جبکہ اس کے لیے عدت ( گزارنا ) ضروری ہے ۔ \" اور آپ نے اس کی طرف پیغام بھیجا : \" اپنے بارے میں مجھ سے ( مشورہ کرنے سے پہلے ) سبقت نہ کرنا ۔ \" اور اسے حکم دیا کہ ام شریک رضی اللہ عنہا کے ہاں منتقل ہو جائے ، پھر اسے پیغام بھیجا : \" ام شریک کے ہاں اولین مہاجرین آتے ہیں ، تم ابن مکتوم اعمیٰ کے ہاں چلی جاؤ ، جب ( کبھی ) تم اپنی اوڑھنی اتارو گی تو وہ تمہیں نہیں دیکھ سکیں گے ۔ \" وہ ان کے ہاں چلی گئیں ، جب ان کی عدت پوری ہو گئی تو رسول اللہ صلی اللہ علیہ وسلم نے ان کا نکاح اسامہ بن زید بن حارثہ رضی اللہ عنہا سے کر دیا","",{"u2":"یحییٰ بن ابی کثیر سے روایت ہے، (کہا:) مجھے ابوسلمہ نے خبر دی کہ ضحاک بن قیس رضی اللہ عنہ کی ہمشیرہ فاطمہ بنت قیس رضی اللہ عنہا نے انہیں بتایا کہ ابوحفص بن مغیرہ مخزومی نے اسے تین طلاقیں دے دیں، پھر یمن کی طرف طلا گیا، تو اس کے عزیز و اقارب نے اسے کہا: تمہارا خرچ ہمارے ذمے نہیں ہے۔ خالد بن ولید رضی اللہ عنہ چند ساتھیوں کے ہمراہ آئے، سیدہ میمونہ رضی اللہ عنہا کے گھر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی: ابوحفص نے اپنی بیوی کو تین طلاقیں دے دی ہیں، کیا اس (کی سابقہ بیوی) کے لیے خرچہ ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس کے لیے خرچہ نہیں ہے جبکہ اس کے لیے عدت (گزارنا) ضروری ہے۔\" اور آپ نے اس کی طرف پیغام بھیجا: \"اپنے بارے میں مجھ سے (مشورہ کرنے سے پہلے) سبقت نہ کرنا۔\" اور اسے حکم دیا کہ ام شریک رضی اللہ عنہا کے ہاں منتقل ہو جائے، پھر اسے پیغام بھیجا: \"ام شریک کے ہاں اولین مہاجرین آتے ہیں، تم ابن مکتوم اعمیٰ کے ہاں چلی جاؤ، جب (کبھی) تم اپنی اوڑھنی اتارو گی تو وہ تمہیں نہیں دیکھ سکیں گے۔\" وہ ان کے ہاں چلی گئیں، جب ان کی عدت پوری ہو گئی تو رسول اللہ صلی اللہ علیہ وسلم نے ان کا نکاح اسامہ بن زید بن حارثہ رضی اللہ عنہا سے کر دیا"}],[3669,"یحییٰ بن ایوب ، قتیبہ بن سعید اور ابن حجر نے ہمیں حدیث سنائی ، انہوں نے کہا : ہمیں اسماعیل ، یعنی ابن جعفر نے محمد بن عمرو سے حدیث بیان کی ، انہوں نے ہمیں ابوسلمہ سے ، انہوں نے فاطمہ بنت قیس رضی اللہ عنہا سے حدیث بیان کی ۔ اسی طرح ہمیں ابوبکر بن ابی شیبہ نے حدیث بیان کی ۔ ( کہا : ) ہم سے محمد بن بشر نے حدیث بیان کی ، ( کہا : ) ہم سے محمد بن عمرو نے باقی ماندہ سابقہ سند کے ساتھ حدیث بیان کی : ( ابوسلمہ نے ) کہا : میں نے فاطمہ بنت قیس رضی اللہ عنہا کے منہ سے سن کر یہ حدیث لکھی ، انہوں نے کہا : میں بنو مخزوم کے ایک آدمی کے ہاں تھی ۔ اس نے مجھے تین طلاقیں دے دیں تو میں نے اس کے گھر والوں کے ہاں پیغام بھیجا ، میں خرچ کا مطالبہ کر رہی تھی ۔ ۔ ۔ آگے ان سب نے ابوسلمہ سے یحییٰ بن کثیر کی حدیث کے مانند بیان کیا ، البتہ محمد بن عمرو کی حدیث میں ہے : \" اپنے ( نکاح کے ) معاملے میں ( ہمارے ساتھ مشورہ کیے بغیر ) ہمیں پیچھے نہ چھوڑ دینا"],[3670,"یحییٰ بن ایوب ، قتیبہ بن سعید اور ابن حجر نے ہمیں حدیث سنائی ، انہوں نے کہا : ہمیں اسماعیل ، یعنی ابن جعفر نے محمد بن عمرو سے حدیث بیان کی ، انہوں نے ہمیں ابوسلمہ سے ، انہوں نے فاطمہ بنت قیس رضی اللہ عنہا سے حدیث بیان کی ۔ اسی طرح ہمیں ابوبکر بن ابی شیبہ نے حدیث بیان کی ۔ ( کہا : ) ہم سے محمد بن بشر نے حدیث بیان کی ، ( کہا : ) ہم سے محمد بن عمرو نے باقی ماندہ سابقہ سند کے ساتھ حدیث بیان کی : ( ابوسلمہ نے ) کہا : میں نے فاطمہ بنت قیس رضی اللہ عنہا کے منہ سے سن کر یہ حدیث لکھی ، انہوں نے کہا : میں بنو مخزوم کے ایک آدمی کے ہاں تھی ۔ اس نے مجھے تین طلاقیں دے دیں تو میں نے اس کے گھر والوں کے ہاں پیغام بھیجا ، میں خرچ کا مطالبہ کر رہی تھی ۔ ۔ ۔ آگے ان سب نے ابوسلمہ سے یحییٰ بن کثیر کی حدیث کے مانند بیان کیا ، البتہ محمد بن عمرو کی حدیث میں ہے : \" اپنے ( نکاح کے ) معاملے میں ( ہمارے ساتھ مشورہ کیے بغیر ) ہمیں پیچھے نہ چھوڑ دینا",""],[3671,"صالح نے ابن شہاب سے روایت کی ، ابوسلمہ بن عبدالرحمٰن بن عوف نے انہیں خبر دی کہ فاطمہ بنت قیس رضی اللہ عنہا نے انہیں بتایا کہ وہ ابو عمرو بن حفص بن مغیرہ رضی اللہ عنہ کی بیوی تھیں ، انہوں نے اسے تینوں طلاقوں میں سے آخری طلاق بھی دے دی ، ان کا خیال تھا کہ وہ اپنے گھر سے باہر نکلنے کے بارے میں فتویٰ پوچھنے کے لیے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں ، تو آپ صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ نابینا ( صحابی ) ابن ام مکتوم رضی اللہ عنہ کے گھر منتقل ہو جائیں ۔ مروان نے ( جب وہ مدینے کا عامل تھا ) اس بات سے انکار کر دیا کہ وہ مطلقہ عورت کے اپنے گھر سے نکلنے کے بارے میں ان کی ( بات کی ) تصدیق کرے ۔ اور عروہ نے کہا : سیدہ عائشہ رضی اللہ عنہا نے بھی فاطمہ بنت قیس رضی اللہ عنہا کے سامنے اس بات کو قبول کرنے سے انکار کر دیا","",{"u2":"صالح نے ابن شہاب سے روایت کی، ابوسلمہ بن عبدالرحمٰن بن عوف نے انہیں خبر دی کہ فاطمہ بنت قیس رضی اللہ عنہا نے انہیں بتایا کہ وہ ابو عمرو بن حفص بن مغیرہ رضی اللہ عنہ کی بیوی تھیں، انہوں نے اسے تینوں طلاقوں میں سے آخری طلاق بھی دے دی، ان کا خیال تھا کہ وہ اپنے گھر سے باہر نکلنے کے بارے میں فتویٰ پوچھنے کے لیے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں، تو آپ صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ نابینا (صحابی) ابن ام مکتوم رضی اللہ عنہ کے گھر منتقل ہو جائیں۔ مروان نے (جب وہ مدینے کا عامل تھا) اس بات سے انکار کر دیا کہ وہ مطلقہ عورت کے اپنے گھر سے نکلنے کے بارے میں ان کی (بات کی) تصدیق کرے۔ اور عروہ نے کہا: سیدہ عائشہ رضی اللہ عنہا نے بھی فاطمہ بنت قیس رضی اللہ عنہا کے سامنے اس بات کو قبول کرنے سے انکار کر دیا"}],[3672,"عقیل نے ابن شہاب سے اسی سند کے ساتھ اسی کے مانند روایت کی ، ساتھ عروہ کا قول بھی ذکر کیا کہ سیدہ عائشہ رضی اللہ عنہا نے فاطمہ رضی اللہ عنہا کے سامنے اس بات کو ناقابل قبول قرار دیا","",{"u2":"عقیل نے ابن شہاب سے اسی سند کے ساتھ اسی کے مانند روایت کی، ساتھ عروہ کا قول بھی ذکر کیا کہ سیدہ عائشہ رضی اللہ عنہا نے فاطمہ رضی اللہ عنہا کے سامنے اس بات کو ناقابل قبول قرار دیا"}],[3673,"معمر نے ہمیں زہری سے خبر دی ، انہوں نے عبیداللہ بن عبداللہ بن عتبہ سے روایت کی کہ ابو عمرو بن حفص بن مغیرہ رضی اللہ عنہ سیدنا علی بن ابی طالب رضی اللہ عنہ کے ساتھ یمن کی جانب گئے اور اپنی بیوی فاطمہ بنت قیس رضی اللہ عنہا کو اس کی ( تین ) طلاقوں میں سے جو طلاق باقی تھی بھیج دی ، اور انہوں نے ان کے بارے میں ( اپنے عزیزوں ) حارث بن ہشام اور عیاش بن ابی ربیعہ سے کہا کہ وہ انہیں خرچ دیں ، تو ان دونوں نے ان ( فاطمہ ) سے کہا : اللہ کی قسم! تمہارے لیے کوئی خرچ نہیں الا یہ کہ تم حاملہ ہوتی ۔ وہ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور آپ کو ان دونوں کی بات بتائی تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" تمہارے لیے خرچ نہیں ( بنتا ۔ ) \" انہوں نے آپ سے نقل مکانی کی اجازت چاہی تو آپ نے انہیں اجازت دے دی ۔ انہوں نے پوچھا : اللہ کے رسول! کہاں؟ فرمایا : \" ابن ام مکتوم کے ہاں ۔ \" وہ نابینا تھے ، وہ ان کے سامنے اپنے ( اوڑھنے کے ) کپڑے اتارتیں تو وہ انہیں دیکھ نہیں سکتے تھے ۔ جب ان کی عدت پوری ہوئی تو نبی صلی اللہ علیہ وسلم نے ان کا نکاح اسامہ بن زید رضی اللہ عنہ سے کر دیا ۔ اس کے بعد مروان نے اس حدیث کے بارے میں دریافت کرنے کے لیے قبیصہ بن ذؤیب کو ان کے پاس بھیجا تو انہوں نے اسے یہ حدیث بیان کی ، اس پر مروان نے کہا : ہم نے یہ حدیث صرف ایک عورت سے سنی ہے ، ہم تو اسی مقبول طریقے کو تھامے رکھیں گے جس پر ہم نے تمام لوگوں کو پایا ہے ۔ جب فاطمہ رضی اللہ عنہا کو مروان کی یہ بات پہنچی تو انہوں نے کہا : میرے اور تمہارے درمیان قرآن فیصل ہے ۔ اللہ تعالیٰ نے فرمایا : \" تم انہیں ان کے گھروں سے مت نکالو ۔ \" آیت مکمل کی ۔ انہوں نے کہا : یہ آیت تو ( جس طرح اس کے الفاظ ( «لَعَلَّ» ٱللَّـهَ «يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا» ) ( الطلاق 1 : 65 ) سے ظاہر ہے ) اس ( شوہر ) کے لیے ہوئی جسے رجوع کا حق حاصل ہے ، اور تیسری طلاق کے بعد از سر نو کون سی بات پیدا ہو سکتی ہے؟ اور تم یہ بات کیسے کہتے ہو کہ اگر وہ حاملہ نہیں ہے تو اس کے لیے خرچ نہیں ہے؟ پھر تم اسے روکتے کس بنا پر ہو","",{"u2":"معمر نے ہمیں زہری سے خبر دی، انہوں نے عبیداللہ بن عبداللہ بن عتبہ سے روایت کی کہ ابو عمرو بن حفص بن مغیرہ رضی اللہ عنہ سیدنا علی بن ابی طالب رضی اللہ عنہ کے ساتھ یمن کی جانب گئے اور اپنی بیوی فاطمہ بنت قیس رضی اللہ عنہا کو اس کی (تین) طلاقوں میں سے جو طلاق باقی تھی بھیج دی، اور انہوں نے ان کے بارے میں (اپنے عزیزوں) حارث بن ہشام اور عیاش بن ابی ربیعہ سے کہا کہ وہ انہیں خرچ دیں، تو ان دونوں نے ان (فاطمہ) سے کہا: اللہ کی قسم! تمہارے لیے کوئی خرچ نہیں الا یہ کہ تم حاملہ ہوتی۔ وہ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور آپ کو ان دونوں کی بات بتائی تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے لیے خرچ نہیں (بنتا۔)\" انہوں نے آپ سے نقل مکانی کی اجازت چاہی تو آپ نے انہیں اجازت دے دی۔ انہوں نے پوچھا: اللہ کے رسول! کہاں؟ فرمایا: \"ابن ام مکتوم کے ہاں۔\" وہ نابینا تھے، وہ ان کے سامنے اپنے (اوڑھنے کے) کپڑے اتارتیں تو وہ انہیں دیکھ نہیں سکتے تھے۔ جب ان کی عدت پوری ہوئی تو نبی صلی اللہ علیہ وسلم نے ان کا نکاح اسامہ بن زید رضی اللہ عنہ سے کر دیا۔ اس کے بعد مروان نے اس حدیث کے بارے میں دریافت کرنے کے لیے قبیصہ بن ذؤیب کو ان کے پاس بھیجا تو انہوں نے اسے یہ حدیث بیان کی، اس پر مروان نے کہا: ہم نے یہ حدیث صرف ایک عورت سے سنی ہے، ہم تو اسی مقبول طریقے کو تھامے رکھیں گے جس پر ہم نے تمام لوگوں کو پایا ہے۔ جب فاطمہ رضی اللہ عنہا کو مروان کی یہ بات پہنچی تو انہوں نے کہا: میرے اور تمہارے درمیان قرآن فیصل ہے۔ اللہ تعالیٰ نے فرمایا: \"تم انہیں ان کے گھروں سے مت نکالو۔\" آیت مکمل کی۔ انہوں نے کہا: یہ آیت تو (جس طرح اس کے الفاظ (لَعَلَّ ٱللَّـہَ یُحْدِثُ بَعْدَ ذَٰلِکَ أَمْرًا) (الطلاق 1:65) سے ظاہر ہے) اس (شوہر) کے لیے ہوئی جسے رجوع کا حق حاصل ہے، اور تیسری طلاق کے بعد از سر نو کون سی بات پیدا ہو سکتی ہے؟ اور تم یہ بات کیسے کہتے ہو کہ اگر وہ حاملہ نہیں ہے تو اس کے لیے خرچ نہیں ہے؟ پھر تم اسے روکتے کس بنا پر ہو"}],[3674,"زہیر بن حرب نے مجھے حدیث بیان کی ، ( کہا : ) ہمیں ہشیم نے حدیث بیان کی ، ( کہا : ) ہمیں سیار ، حصین ، مغیرہ ، اشعث ، مجالد ، اسماعیل بن ابی خالد اور داود سب نے شعبی سے خبر دی ۔ ۔ البتہ داود نے کہا : ہمیں حدیث بیان کی ۔ ۔ انہوں نے کہا : میں فاطمہ بنت قیس رضی اللہ عنہا کے پاس گیا اور ان سے رسول اللہ صلی اللہ علیہ وسلم کے فیصلے کے متعلق دریافت کیا جو ان کے بارے میں تھا ۔ انہوں نے کہا : ان کے شوہر نے انہیں تین طلاقیں دے دیں ، کہا : تو میں رہائش اور خرچ کے لیے اس کے ساتھ اپنا جھگڑا لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس گئی ۔ کہا : تو آپ نے مجھے رہائش اور خرچ ( کا حق ) نہ دیا ، اور مجھے حکم دیا کہ میں اپنی عدت ابن ام مکتوم رضی اللہ عنہ کے گھر گزاروں","",{"u2":"زہیر بن حرب نے مجھے حدیث بیان کی، (کہا:) ہمیں ہشیم نے حدیث بیان کی، (کہا:) ہمیں سیار، حصین، مغیرہ، اشعث، مجالد، اسماعیل بن ابی خالد اور داود سب نے شعبی سے خبر دی۔۔ البتہ داود نے کہا: ہمیں حدیث بیان کی۔۔ انہوں نے کہا: میں فاطمہ بنت قیس رضی اللہ عنہا کے پاس گیا اور ان سے رسول اللہ صلی اللہ علیہ وسلم کے فیصلے کے متعلق دریافت کیا جو ان کے بارے میں تھا۔ انہوں نے کہا: ان کے شوہر نے انہیں تین طلاقیں دے دیں، کہا: تو میں رہائش اور خرچ کے لیے اس کے ساتھ اپنا جھگڑا لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس گئی۔ کہا: تو آپ نے مجھے رہائش اور خرچ (کا حق) نہ دیا، اور مجھے حکم دیا کہ میں اپنی عدت ابن ام مکتوم رضی اللہ عنہ کے گھر گزاروں"}],[3675,"یحییٰ بن یحییٰ نے ہمیں حدیث بیان کی ، کہا : ہمیں ہشیم نے حصین ، داود ، مغیرہ ، اسماعیل اور اشعث سے ، انہوں نے شعبی سے خبر دی کہ انہوں نے کہا : میں فاطمہ بنت قیس رضی اللہ عنہا کے پاس گیا ۔ ۔ ۔ ( آگے ) ہشیم سے زہیر کی روایت کردہ حدیث کے مانند ہے","",{"u2":"یحییٰ بن یحییٰ نے ہمیں حدیث بیان کی، کہا: ہمیں ہشیم نے حصین، داود، مغیرہ، اسماعیل اور اشعث سے، انہوں نے شعبی سے خبر دی کہ انہوں نے کہا: میں فاطمہ بنت قیس رضی اللہ عنہا کے پاس گیا۔۔۔ (آگے) ہشیم سے زہیر کی روایت کردہ حدیث کے مانند ہے"}],[3676,"قرہ نے ہمیں حدیث بیان کی ، ( کہا : ) ہمیں سیار ابوالحکم نے حدیث بیان کی ، ( کہا : ) ہمیں شعبی نے حدیث بیان کی ، انہوں نے کہا : ہم فاطمہ بنت قیس رضی اللہ عنہا کے پاس گئے ، انہوں نے ابن طاب کی تازہ کھجوروں سے ہماری ضیافت کی ، اور ہمیں عمدہ جَو کے ستو پلائے ، اس کے بعد میں نے ان سے ایسی عورت کے بارے میں پوچھا جسے تین طلاقیں دی گئی ہوں کہ وہ عدت کہاں گزارے گی؟ انہوں نے جواب دیا : مجھے میرے شوہر نے تین طلاقیں دیں تو نبی صلی اللہ علیہ وسلم نے مجھے اجازت دی کہ میں اپنے گھرانے میں عدت گزاروں ۔ ( ابن مکتوم ان کے عزیز تھے)","",{"u2":"قرہ نے ہمیں حدیث بیان کی، (کہا:) ہمیں سیار ابوالحکم نے حدیث بیان کی، (کہا:) ہمیں شعبی نے حدیث بیان کی، انہوں نے کہا: ہم فاطمہ بنت قیس رضی اللہ عنہا کے پاس گئے، انہوں نے ابن طاب کی تازہ کھجوروں سے ہماری ضیافت کی، اور ہمیں عمدہ جَو کے ستو پلائے، اس کے بعد میں نے ان سے ایسی عورت کے بارے میں پوچھا جسے تین طلاقیں دی گئی ہوں کہ وہ عدت کہاں گزارے گی؟ انہوں نے جواب دیا: مجھے میرے شوہر نے تین طلاقیں دیں تو نبی صلی اللہ علیہ وسلم نے مجھے اجازت دی کہ میں اپنے گھرانے میں عدت گزاروں۔ (ابن مکتوم ان کے عزیز تھے"}],[3677,"سلمہ بن کہیل نے شعبی سے اور انہوں نے فاطمہ بنت قیس رضی اللہ عنہا سے روایت کی ، انہوں نے ایسی عورت کے بارے میں نبی صلی اللہ علیہ وسلم سے روایت کی جسے تین طلاقیں دے دی گئی ہوں ، آپ نے فرمایا : \" اس کے لیے نہ رہائش ہے اور نہ خرچ","",{"u2":"سلمہ بن کہیل نے شعبی سے اور انہوں نے فاطمہ بنت قیس رضی اللہ عنہا سے روایت کی، انہوں نے ایسی عورت کے بارے میں نبی صلی اللہ علیہ وسلم سے روایت کی جسے تین طلاقیں دے دی گئی ہوں، آپ نے فرمایا: \"اس کے لیے نہ رہائش ہے اور نہ خرچ"}],[3678,"یحییٰ بن آدم نے ہمیں خبر دی ، ( کہا : ) عمار بن رُزیق نے ہمیں ابواسحاق سے حدیث بیان کی ، انہوں نے شعبی سے اور انہوں نے فاطمہ بنت قیس رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : میرے شوہر نے مجھے تین طلاقیں دیں تو میں نے ( وہاں سے ) نقل مکانی کا ارادہ کیا ۔ میں نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی ، تو آپ نے فرمایا : \" تم اپنے چچا زاد عمرو بن ام مکتوم کے گھر منتقل ہو جاؤ ، اور ان کے ہاں عدت گزارو","",{"u2":"یحییٰ بن آدم نے ہمیں خبر دی، (کہا:) عمار بن رُزیق نے ہمیں ابواسحاق سے حدیث بیان کی، انہوں نے شعبی سے اور انہوں نے فاطمہ بنت قیس رضی اللہ عنہا سے روایت کی، انہوں نے کہا: میرے شوہر نے مجھے تین طلاقیں دیں تو میں نے (وہاں سے) نقل مکانی کا ارادہ کیا۔ میں نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی، تو آپ نے فرمایا: \"تم اپنے چچا زاد عمرو بن ام مکتوم کے گھر منتقل ہو جاؤ، اور ان کے ہاں عدت گزارو"}],[3679,"ابواحمد نے ہمیں خبر دی ، ( کہا : ) عمار بن رزیق نے ہمیں ابواسحاق سے حدیث بیان کی ، انہوں نے کہا : میں اسود بن یزید ( نخعی ) کے ساتھ ( کوفہ کی ) بڑی مسجد میں بیٹھا ہوا تھا ، شعبی بھی ہمارے ساتھ تھے ، تو شعبی نے فاطمہ بنت قیس رضی اللہ عنہا کی حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں رہائش اور خرچ ( کا حق ) نہیں دیا ۔ پھر اسود نے مٹھی بھر کنکریاں لیں اور انہیں دے ماریں اور کہا : تم پر افسوس! تم اس طرح کی حدیث بیان کر رہے ہو؟ عمر رضی اللہ عنہ نے کہا تھا : ہم ایک عورت کے قول کی وجہ سے اللہ کی کتاب اور اس کے رسول کی سنت کو نہیں چھوڑ سکتے ، ہم نہیں جانتے کہ اس نے ( اس مسئلے کو ) یاد رکھا ہے یا بھول گئی ، اس کے لیے رہائش اور خرچ ہے ۔ ( اور یہ آیت تلاوت کی ) اللہ عزوجل نے فرمایا : \" تم انہیں ان کے گھروں سے نہ نکالو ، اور نہ وہ خود نکلیں ، مگر یہ کہ وہ کوئی کھلی بے حیائی کریں","",{"u2":"ابواحمد نے ہمیں خبر دی، (کہا:) عمار بن رزیق نے ہمیں ابواسحاق سے حدیث بیان کی، انہوں نے کہا: میں اسود بن یزید (نخعی) کے ساتھ (کوفہ کی) بڑی مسجد میں بیٹھا ہوا تھا، شعبی بھی ہمارے ساتھ تھے، تو شعبی نے فاطمہ بنت قیس رضی اللہ عنہا کی حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں رہائش اور خرچ (کا حق) نہیں دیا۔ پھر اسود نے مٹھی بھر کنکریاں لیں اور انہیں دے ماریں اور کہا: تم پر افسوس! تم اس طرح کی حدیث بیان کر رہے ہو؟ عمر رضی اللہ عنہ نے کہا تھا: ہم ایک عورت کے قول کی وجہ سے اللہ کی کتاب اور اس کے رسول کی سنت کو نہیں چھوڑ سکتے، ہم نہیں جانتے کہ اس نے (اس مسئلے کو) یاد رکھا ہے یا بھول گئی، اس کے لیے رہائش اور خرچ ہے۔ (اور یہ آیت تلاوت کی) اللہ عزوجل نے فرمایا: \"تم انہیں ان کے گھروں سے نہ نکالو، اور نہ وہ خود نکلیں، مگر یہ کہ وہ کوئی کھلی بے حیائی کریں"}],[3680,"سلیمان بن معاذ نے ابواسحاق سے اسی سند کے ساتھ عمار بن رزیق سے روایت کردہ ابواحمد کی حدیث کے ہم معنی حدیث مکمل قصے سمیت بیان کی","",{"u2":"سلیمان بن معاذ نے ابواسحاق سے اسی سند کے ساتھ عمار بن رزیق سے روایت کردہ ابواحمد کی حدیث کے ہم معنی حدیث مکمل قصے سمیت بیان کی"}],[3681,"وکیع نے ہمیں حدیث بیان کی ، کہا : ہمیں سفیان نے ابوبکر بن ابوجہم بن سخیر عدوی سے حدیث بیان کی ، انہوں نے کہا : میں فاطمہ بنت قیس رضی اللہ عنہا سے سنا وہ کہہ رہی تھیں کہ ان کے شوہر نے انہیں تین طلاقیں دیں تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں رہائش دی نہ خرچ ۔ کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا : \" جب ( عدت سے ) آزاد ہو جاؤ تو مجھے اطلاع دینا \" سو میں نے آپ کو اطلاع دی ۔ معاویہ ، ابوجہم اور اسامہ بن زید رضی اللہ عنہم نے ان کی طرف پیغام بھیجا ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" معاویہ تو فقیر ہے اس کے پاس مال نہیں ہے ، اور رہا ابوجہم تو وہ عورتوں کو بہت مارنے والا ہے ، البتہ اسامہ بن زید ہے ۔ \" انہوں نے ( ناپسندیدگی کا اظہار کرتے ہوئے ) ہاتھ سے اس طرح اشارہ کیا : اسامہ! اسامہ! رسول اللہ صلی اللہ علیہ وسلم نے انہیں فرمایا : \" اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی اطاعت تمہارے لیے بہتر ہے ۔ \" کہا : تو میں نے ان سے شادی کر لی ، اس کے بعد مجھ پر رشک کیا جانے لگا","",{"u2":"وکیع نے ہمیں حدیث بیان کی، کہا: ہمیں سفیان نے ابوبکر بن ابوجہم بن سخیر عدوی سے حدیث بیان کی، انہوں نے کہا: میں فاطمہ بنت قیس رضی اللہ عنہا سے سنا وہ کہہ رہی تھیں کہ ان کے شوہر نے انہیں تین طلاقیں دیں تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں رہائش دی نہ خرچ۔ کہا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: \"جب (عدت سے) آزاد ہو جاؤ تو مجھے اطلاع دینا\" سو میں نے آپ کو اطلاع دی۔ معاویہ، ابوجہم اور اسامہ بن زید رضی اللہ عنہم نے ان کی طرف پیغام بھیجا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معاویہ تو فقیر ہے اس کے پاس مال نہیں ہے، اور رہا ابوجہم تو وہ عورتوں کو بہت مارنے والا ہے، البتہ اسامہ بن زید ہے۔\" انہوں نے (ناپسندیدگی کا اظہار کرتے ہوئے) ہاتھ سے اس طرح اشارہ کیا: اسامہ! اسامہ! رسول اللہ صلی اللہ علیہ وسلم نے انہیں فرمایا: \"اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی اطاعت تمہارے لیے بہتر ہے۔\" کہا: تو میں نے ان سے شادی کر لی، اس کے بعد مجھ پر رشک کیا جانے لگا"}],[3682,"عبدالرحمٰن نے ہمیں سفیان سے حدیث بیان کی ، انہوں نے ابوبکر بن ابی جہم سے روایت کی ، انہوں نے کہا : میں نے فاطمہ بنت قیس رضی اللہ عنہا سے سنا وہ کہہ رہی تھیں : میرے شوہر ابوعمرو بن حفص بن مغیرہ رضی اللہ عنہ نے عیاش بن ابی ربیعہ کو میری طلاق کا پیغام دے کر بھیجا اور اس کے ساتھ پانچ صاع کھجوریں اور پانچ صاع جَو بھی بھیجے ۔ میں نے کہا : کیا میرے لیے صرف یہی خرچ ہے؟ کیا میں تم لوگوں کے گھر میں عدت نہیں گزاروں گی؟ اس نے جواب دیا : نہیں ۔ انہوں نے کہا : میں نے اپنے کپڑے سمیٹے اور رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی تو آپ نے پوچھا : \" وہ تمہیں کتنی طلاقیں دے چکے ہیں؟ \" میں نے جواب دیا : تین ۔ آپ نے فرمایا : \" اس نے سچ کہا ، تمہارے لیے خرچ نہیں ہے ۔ اپنے چچا زاد عمرو بن ام مکتوم کے گھر عدت گزارو ، وہ نابینا ہیں تم ان کے ہاں اپنا اوڑھنے کا کپڑا اتار سکو گی ۔ جب تمہاری عدت ختم ہو جائے تو مجھے اطلاع دینا ۔ \" انہوں نے ( آکر ) کہا : مجھے کئی لوگوں نے نکاح کا پیغام بھیجا ہے ، ان میں معاویہ اور ابوجہم بھی ہیں ۔ نبی صلی اللہ علیہ وسلم نے فرمایا : \" معاویہ تو فقیر اور مفلوک الحال ہے ، اور رہے ابوجہم تو وہ عورتوں پر بہت سختی کرتے ہیں ۔ ۔ یا وہ عورتوں کو مارتے ہیں ، یا اس طرح کی کوئی اور بات کہی ۔ ۔ البتہ تم اسامہ بن زید کو قبول کر لو","",{"u2":"عبدالرحمٰن نے ہمیں سفیان سے حدیث بیان کی، انہوں نے ابوبکر بن ابی جہم سے روایت کی، انہوں نے کہا: میں نے فاطمہ بنت قیس رضی اللہ عنہا سے سنا وہ کہہ رہی تھیں: میرے شوہر ابوعمرو بن حفص بن مغیرہ رضی اللہ عنہ نے عیاش بن ابی ربیعہ کو میری طلاق کا پیغام دے کر بھیجا اور اس کے ساتھ پانچ صاع کھجوریں اور پانچ صاع جَو بھی بھیجے۔ میں نے کہا: کیا میرے لیے صرف یہی خرچ ہے؟ کیا میں تم لوگوں کے گھر میں عدت نہیں گزاروں گی؟ اس نے جواب دیا: نہیں۔ انہوں نے کہا: میں نے اپنے کپڑے سمیٹے اور رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی تو آپ نے پوچھا: \"وہ تمہیں کتنی طلاقیں دے چکے ہیں؟\" میں نے جواب دیا: تین۔ آپ نے فرمایا: \"اس نے سچ کہا، تمہارے لیے خرچ نہیں ہے۔ اپنے چچا زاد عمرو بن ام مکتوم کے گھر عدت گزارو، وہ نابینا ہیں تم ان کے ہاں اپنا اوڑھنے کا کپڑا اتار سکو گی۔ جب تمہاری عدت ختم ہو جائے تو مجھے اطلاع دینا۔\" انہوں نے (آکر) کہا: مجھے کئی لوگوں نے نکاح کا پیغام بھیجا ہے، ان میں معاویہ اور ابوجہم بھی ہیں۔ نبی صلی اللہ علیہ وسلم نے فرمایا: \"معاویہ تو فقیر اور مفلوک الحال ہے، اور رہے ابوجہم تو وہ عورتوں پر بہت سختی کرتے ہیں۔۔ یا وہ عورتوں کو مارتے ہیں، یا اس طرح کی کوئی اور بات کہی۔۔ البتہ تم اسامہ بن زید کو قبول کر لو"}],[3683,"ابو عاصم نے ہمیں خبر دی ( کہا : ) ہمیں سفیان ثوری نے ابوبکر بن ابی جہم سے حدیث بیان کی ، انہوں نے کہا : میں اور ابوسلمہ بن عبدالرحمٰن فاطمہ بنت قیس رضی اللہ عنہا کے ہاں حاضر ہوئے ، ہم نے ان سے سوال کیا ، تو انہوں نے کہا : میں ابوعمرو بن حفص بن مغیرہ رضی اللہ عنہ کی بییو تھی ، وہ نجران کی لڑائی میں نکلے ، آگے انہوں نے ابن مہدی کی حدیث کے ہم معنی بیان کیا اور یہ اضافہ کیا : ( فاطمہ نے ) کہا : تو میں نے ان ( اسامہ ) سے شادی کر لی ، اللہ نے ابوزید ( اسامہ بن زید رضی اللہ عنہ ) کی وجہ سے مجھے شرف بخشا ، اللہ نے ابوزید کی وجہ سے مجھے عزت دی","",{"u2":"ابو عاصم نے ہمیں خبر دی (کہا:) ہمیں سفیان ثوری نے ابوبکر بن ابی جہم سے حدیث بیان کی، انہوں نے کہا: میں اور ابوسلمہ بن عبدالرحمٰن فاطمہ بنت قیس رضی اللہ عنہا کے ہاں حاضر ہوئے، ہم نے ان سے سوال کیا، تو انہوں نے کہا: میں ابوعمرو بن حفص بن مغیرہ رضی اللہ عنہ کی بییو تھی، وہ نجران کی لڑائی میں نکلے، آگے انہوں نے ابن مہدی کی حدیث کے ہم معنی بیان کیا اور یہ اضافہ کیا: (فاطمہ نے) کہا: تو میں نے ان (اسامہ) سے شادی کر لی، اللہ نے ابوزید (اسامہ بن زید رضی اللہ عنہ) کی وجہ سے مجھے شرف بخشا، اللہ نے ابوزید کی وجہ سے مجھے عزت دی"}],[3684,"شعبہ نے ہمیں حدیث بیان کی ، ( کہا : ) ابوبکر ( بن ابی جہم ) نے مجھے حدیث بیان کی ، انہوں نے کہا : میں اور ابوسلمہ ، ابن زبیر کے زمانہ خلافت میں ، فاطمہ بنت قیس رضی اللہ عنہا کے پاس گئے تو انہوں نے ہمیں حدیث بیان کی کہ ان کے شوہر نے انہیں تین طلاقیں دیں ، آگے سفیان کی حدیث کی طرح ہے","",{"u2":"شعبہ نے ہمیں حدیث بیان کی، (کہا:) ابوبکر (بن ابی جہم) نے مجھے حدیث بیان کی، انہوں نے کہا: میں اور ابوسلمہ، ابن زبیر کے زمانہ خلافت میں، فاطمہ بنت قیس رضی اللہ عنہا کے پاس گئے تو انہوں نے ہمیں حدیث بیان کی کہ ان کے شوہر نے انہیں تین طلاقیں دیں، آگے سفیان کی حدیث کی طرح ہے"}],[3685,"(عبداللہ بن یسار ) بہی نے فاطمہ بنت قیس رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : میرے شوہر نے مجھے تین طلاقیں دیں تو رسول اللہ صلی اللہ علیہ وسلم نے میرے لیے رہائش اور خرچ نہیں رکھا","",{"u2":"عبداللہ بن یسار) بہی نے فاطمہ بنت قیس رضی اللہ عنہا سے روایت کی، انہوں نے کہا: میرے شوہر نے مجھے تین طلاقیں دیں تو رسول اللہ صلی اللہ علیہ وسلم نے میرے لیے رہائش اور خرچ نہیں رکھا"}],[3686,"عروہ بن زبیر نے کہا : یحییٰ بن سعید بن عاص نے عبدالرحمٰن بن حکم کی بیٹی سے شادی کی ، بعد میں اسے طلاق دے دی اور اسے اپنے ہاں سے بھی نکال دیا ۔ عروہ نے اس بات کی وجہ سے ان پر سخت اعتراض کیا ، تو انہوں نے کہا : فاطمہ ( بھی اپنے خاوند کے گھر سے ) چلی گئی تھی ۔ عروہ نے کہا : اس پر میں سیدہ عائشہ رضی اللہ عنہا کی خدمت میں حاضر ہوا اور انہیں یہ بات بتائی تو انہوں نے کہا : فاطمہ بنت قیس کے لیے اس حدیث کو بیان کرنے میں کوئی خیر نہیں ہے","",{"u2":"عروہ بن زبیر نے کہا: یحییٰ بن سعید بن عاص نے عبدالرحمٰن بن حکم کی بیٹی سے شادی کی، بعد میں اسے طلاق دے دی اور اسے اپنے ہاں سے بھی نکال دیا۔ عروہ نے اس بات کی وجہ سے ان پر سخت اعتراض کیا، تو انہوں نے کہا: فاطمہ (بھی اپنے خاوند کے گھر سے) چلی گئی تھی۔ عروہ نے کہا: اس پر میں سیدہ عائشہ رضی اللہ عنہا کی خدمت میں حاضر ہوا اور انہیں یہ بات بتائی تو انہوں نے کہا: فاطمہ بنت قیس کے لیے اس حدیث کو بیان کرنے میں کوئی خیر نہیں ہے"}],[3687,"فاطمہ بنت قیس رضی اللہ عنہا سے روایت ہے ، انہوں نے کہا : میں نے عرض کی : اے اللہ کے رسول! مجھے میرے شوہر نے تین طلاقیں دے دی ہیں ، اور میں ڈرتی ہوں کہ کوئی گھس کر مجھ پر حملہ کر دے گا ، کہا : اس پر آپ صلی اللہ علیہ وسلم نے انہیں حکم دیا تو انہوں نے جگہ بدل لی","",{"u2":"فاطمہ بنت قیس رضی اللہ عنہا سے روایت ہے، انہوں نے کہا: میں نے عرض کی: اے اللہ کے رسول! مجھے میرے شوہر نے تین طلاقیں دے دی ہیں، اور میں ڈرتی ہوں کہ کوئی گھس کر مجھ پر حملہ کر دے گا، کہا: اس پر آپ صلی اللہ علیہ وسلم نے انہیں حکم دیا تو انہوں نے جگہ بدل لی"}],[3688,"شعبہ نے ہمیں عبدالرحمٰن بن قاسم سے حدیث بیان کی ، انہوں نے اپنے والد ( قاسم ) سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ انہوں نے کہا : اس بات کو بیان کرنے میں فاطمہ رضی اللہ عنہا کے لیے کوئی بھلائی نہیں ہے کہ \" نہ رہائش ہے نہ خرچ","",{"u2":"شعبہ نے ہمیں عبدالرحمٰن بن قاسم سے حدیث بیان کی، انہوں نے اپنے والد (قاسم) سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ انہوں نے کہا: اس بات کو بیان کرنے میں فاطمہ رضی اللہ عنہا کے لیے کوئی بھلائی نہیں ہے کہ \"نہ رہائش ہے نہ خرچ"}],[3689,"سفیان نے عبدالرحمٰن بن قاسم سے اور انہوں نے اپنے والد ( قاسم ) سے روایت کی ، انہوں نے کہا : عروہ بن زبیر نے سیدہ عائشہ رضی اللہ عنہا سے پوچھا : کیا آپ نے فلانہ بنت حکم کو نہیں دیکھا؟ اس کے شوہر نے اسے تین طلاقیں دیں تو وہ ( اس کے گھر سے ) چلی گئی ۔ ( عائشہ رضی اللہ عنہا نے ) کہا : اس نے برا کیا ۔ عروہ نے پوچھا : کیا آپ نے فاطمہ رضی اللہ عنہا کا قول نہیں سنا؟ تو انہوں نے جواب دیا : دیکھو! اس کو بیان کرنے میں اس کے لیے کوئی بھلائی نہیں ہے","",{"u2":"سفیان نے عبدالرحمٰن بن قاسم سے اور انہوں نے اپنے والد (قاسم) سے روایت کی، انہوں نے کہا: عروہ بن زبیر نے سیدہ عائشہ رضی اللہ عنہا سے پوچھا: کیا آپ نے فلانہ بنت حکم کو نہیں دیکھا؟ اس کے شوہر نے اسے تین طلاقیں دیں تو وہ (اس کے گھر سے) چلی گئی۔ (عائشہ رضی اللہ عنہا نے) کہا: اس نے برا کیا۔ عروہ نے پوچھا: کیا آپ نے فاطمہ رضی اللہ عنہا کا قول نہیں سنا؟ تو انہوں نے جواب دیا: دیکھو! اس کو بیان کرنے میں اس کے لیے کوئی بھلائی نہیں ہے"}],[3690,"سیدنا جابر بن عبداللہ رضی اللہ عنہ کہتے ہیں : میری خالہ کو طلاق ہو گئی ، انہوں نے ( دورانِ عدت ) اپنی کھجوروں کا پھل توڑنے کا ارادہ کیا ، تو ایک آدمی نے انہیں ( گھر سے ) باہر نکلنے پر ڈانٹا ۔ وہ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں ، تو آپ نے فرمایا : \" کیوں نہیں ، اپنی کھجوروں کا پھل توڑو ، ممکن ہے کہ تم ( اس سے ) صدقہ کرو یا کوئی اور اچھا کام کرو","",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ کہتے ہیں: میری خالہ کو طلاق ہو گئی، انہوں نے (دورانِ عدت) اپنی کھجوروں کا پھل توڑنے کا ارادہ کیا، تو ایک آدمی نے انہیں (گھر سے) باہر نکلنے پر ڈانٹا۔ وہ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں، تو آپ نے فرمایا: \"کیوں نہیں، اپنی کھجوروں کا پھل توڑو، ممکن ہے کہ تم (اس سے) صدقہ کرو یا کوئی اور اچھا کام کرو"}],[3691,"ابن شہاب سے روایت ہے ، ( انہوں نے کہا : ) مجھے عبیداللہ بن عبداللہ بن عتبہ بن مسعود نے حدیث بیان کی کہ ان کے والد نے عمر بن عبداللہ بن ارقم زہری کو حکم دیتے ہوئے لکھا کہ سبیعہ بنت حارث اسلمیہ رضی اللہ عنہا کے پاس جائیں ، اور ان سے ان کے واقعے کے بارے میں اور ان کے فتویٰ پوچھنے پر جو کچھ رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا تھا اس کے بارے میں پوچھیں ۔ چنانچہ عمر بن عبداللہ نے عبداللہ بن عتبہ کو خبر دیتے ہوئے لکھا کہ سبیعہ نے انہیں بتایا ہے کہ وہ سعد بن خولہ کی بیوی تھیں ، وہ بنی عامر بن لؤی میں سے تھے اور وہ بدر میں شریک ہونے والوں میں سے تھے ۔ وہ حجۃ الوداع کے موقع پر ، فوت ہو گئے تھے جبکہ وہ حاملہ تھیں ۔ ان کی وفات کے بعد زیادہ وقت نہ گزرا تھا کہ انہوں نے بچے کو جنم دیا ۔ جب وی اپنے نفاس سے پاک ہوئیں تو انہوں نے نکاح کا پیغام دینے والوں کے لیے ( کہ انہیں ان کی عدت سے فراغت کا پتہ چل جائے کچھ ) بناؤ سنگھار کیا ۔ بنو عبدالدار کا ایک آدمی ۔ ۔ ابوالسنابل بن بعکک ۔ ۔ ان کے ہاں آیا تو ان سے کہا : کیا بات ہے میں آپ کو بنی سنوری دیکھ رہا ہوں؟ شاید آپ کو نکاح کی امید ہے؟ اللہ کی قسم! آپ نکاح نہیں کر سکتیں حتی کہ آپ پر چار مہینے دس دن گزر جائیں ۔ سبیعہ رضی اللہ عنہا نے کہا : جب اس نے مجھے یہ بات کہی تو شام کے وقت میں نے اپنے کپڑے سمیٹے ، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی اور آپ سے اس کے بارے میں دریافت کیا ۔ آپ صلی اللہ علیہ وسلم نے مجھے فتویٰ دیا کہ میں اسی وقت حلال ہو چکی ہوں جب میں نے بچہ جنا تھا اور آپ صلی اللہ علیہ وسلم نے ، اگر میں مناسب سمجھوں تو مجھے شادی کرنے کا حکم دیا ۔ ابن شہاب نے کہا : میں کوئی حرج نہیں سمجھتا کہ وضع حمل کے ساتھ ہی ، چاہے وہ اپنے ( نفاس کے ) خون میں ہو ، عورت نکاح کر لے ، البتہ اس کا شوہر اس کے پاک ہونے تک اس کے قریب نہ جائے","",{"u2":"ابن شہاب سے روایت ہے، (انہوں نے کہا:) مجھے عبیداللہ بن عبداللہ بن عتبہ بن مسعود نے حدیث بیان کی کہ ان کے والد نے عمر بن عبداللہ بن ارقم زہری کو حکم دیتے ہوئے لکھا کہ سبیعہ بنت حارث اسلمیہ رضی اللہ عنہا کے پاس جائیں، اور ان سے ان کے واقعے کے بارے میں اور ان کے فتویٰ پوچھنے پر جو کچھ رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا تھا اس کے بارے میں پوچھیں۔ چنانچہ عمر بن عبداللہ نے عبداللہ بن عتبہ کو خبر دیتے ہوئے لکھا کہ سبیعہ نے انہیں بتایا ہے کہ وہ سعد بن خولہ کی بیوی تھیں، وہ بنی عامر بن لؤی میں سے تھے اور وہ بدر میں شریک ہونے والوں میں سے تھے۔ وہ حجۃ الوداع کے موقع پر، فوت ہو گئے تھے جبکہ وہ حاملہ تھیں۔ ان کی وفات کے بعد زیادہ وقت نہ گزرا تھا کہ انہوں نے بچے کو جنم دیا۔ جب وی اپنے نفاس سے پاک ہوئیں تو انہوں نے نکاح کا پیغام دینے والوں کے لیے (کہ انہیں ان کی عدت سے فراغت کا پتہ چل جائے کچھ) بناؤ سنگھار کیا۔ بنو عبدالدار کا ایک آدمی۔۔ ابوالسنابل بن بعکک۔۔ ان کے ہاں آیا تو ان سے کہا: کیا بات ہے میں آپ کو بنی سنوری دیکھ رہا ہوں؟ شاید آپ کو نکاح کی امید ہے؟ اللہ کی قسم! آپ نکاح نہیں کر سکتیں حتی کہ آپ پر چار مہینے دس دن گزر جائیں۔ سبیعہ رضی اللہ عنہا نے کہا: جب اس نے مجھے یہ بات کہی تو شام کے وقت میں نے اپنے کپڑے سمیٹے، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی اور آپ سے اس کے بارے میں دریافت کیا۔ آپ صلی اللہ علیہ وسلم نے مجھے فتویٰ دیا کہ میں اسی وقت حلال ہو چکی ہوں جب میں نے بچہ جنا تھا اور آپ صلی اللہ علیہ وسلم نے، اگر میں مناسب سمجھوں تو مجھے شادی کرنے کا حکم دیا۔\nابن شہاب نے کہا: میں کوئی حرج نہیں سمجھتا کہ وضع حمل کے ساتھ ہی، چاہے وہ اپنے (نفاس کے) خون میں ہو، عورت نکاح کر لے، البتہ اس کا شوہر اس کے پاک ہونے تک اس کے قریب نہ جائے"}],[3692,"عبدالوہاب نے کہا : میں نے یحییٰ بن سعید سے سنا ، ( انہوں نے کہا : ) مجھے سلیمان بن یسار نے خبر دی کہ ابوسلمہ بن عبدالرحمٰن اور ابن عباس رضی اللہ عنہم دونوں سیدنا ابوہریرہ رضی اللہ عنہ کے ہاں اکٹھے ہوئے اور وہ دونوں اس عورت کا ذکر کرنے لگے جس کا اپنے شوہر کی وفات سے چند راتوں کے بعد نفاس شروع ہو جائے ۔ ابن عباس رضی اللہ عنہ نے کہا : اس کی عدت دو وقتوں میں سے آخر والا ہے ۔ ابوسلمہ نے کہا : وہ حلال ہو چکی ہے ۔ وہ دونوں اس معاملے میں بحث کرنے لگے ، تو ابوہریرہ رضی اللہ عنہ نے کہا : میں اپنے بھتیجے ۔ ۔ یعنی ابوسلمہ ۔ ۔ کے ساتھ ہوں ۔ اس کے بعد انہوں نے اس مسئلے کے بارے میں دریافت کرنے کے لیے ابن عباس رضی اللہ عنہ کے آزاد کردہ غلام کریب کو سیدہ ام سلمہ رضی اللہ عنہا کی طرف بھیجا ۔ وہ ( واپس ) ان کے پاس آیا تو انہیں بتایا کہ ام سلمہ رضی اللہ عنہا نے کہا ہے : سبیعہ اسلمیہ رضی اللہ عنہا نے اپنے شوہر کی وفات سے چند راتوں کے بعد بچہ جنا تھا ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اس بات کا ذکر کیا تو آپ نے انہیں نکاح کرنے کا حکم دیا تھا","",{"u2":"عبدالوہاب نے کہا: میں نے یحییٰ بن سعید سے سنا، (انہوں نے کہا:) مجھے سلیمان بن یسار نے خبر دی کہ ابوسلمہ بن عبدالرحمٰن اور ابن عباس رضی اللہ عنہم دونوں سیدنا ابوہریرہ رضی اللہ عنہ کے ہاں اکٹھے ہوئے اور وہ دونوں اس عورت کا ذکر کرنے لگے جس کا اپنے شوہر کی وفات سے چند راتوں کے بعد نفاس شروع ہو جائے۔ ابن عباس رضی اللہ عنہ نے کہا: اس کی عدت دو وقتوں میں سے آخر والا ہے۔ ابوسلمہ نے کہا: وہ حلال ہو چکی ہے۔ وہ دونوں اس معاملے میں بحث کرنے لگے، تو ابوہریرہ رضی اللہ عنہ نے کہا: میں اپنے بھتیجے۔۔ یعنی ابوسلمہ۔۔ کے ساتھ ہوں۔ اس کے بعد انہوں نے اس مسئلے کے بارے میں دریافت کرنے کے لیے ابن عباس رضی اللہ عنہ کے آزاد کردہ غلام کریب کو سیدہ ام سلمہ رضی اللہ عنہا کی طرف بھیجا۔ وہ (واپس) ان کے پاس آیا تو انہیں بتایا کہ ام سلمہ رضی اللہ عنہا نے کہا ہے: سبیعہ اسلمیہ رضی اللہ عنہا نے اپنے شوہر کی وفات سے چند راتوں کے بعد بچہ جنا تھا، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اس بات کا ذکر کیا تو آپ نے انہیں نکاح کرنے کا حکم دیا تھا"}],[3693,"لیث اور یزید بن ہارون دونوں نے اسی سند کے ساتھ یحییٰ بن سعید سے روایت کی ، البتہ لیث نے اپنی حدیث میں کہا : انہوں نے ( کسی کو ) ام سلمہ رضی اللہ عنہا کی طرف بھیجا ۔ انہوں نے کریب کا نام نہیں لیا","",{"u2":"لیث اور یزید بن ہارون دونوں نے اسی سند کے ساتھ یحییٰ بن سعید سے روایت کی، البتہ لیث نے اپنی حدیث میں کہا: انہوں نے (کسی کو) ام سلمہ رضی اللہ عنہا کی طرف بھیجا۔ انہوں نے کریب کا نام نہیں لیا"}],[3694,"حمید بن نافع نے زینب بنت ابی سلمہ سے روایت کی کہ انہوں نے اِن ( حمید ) کو یہ تین حدیثیں بیان کیں ، کہا : زینب رضی اللہ عنہا نے کہا : جب نبی صلی اللہ علیہ وسلم کی زوجہ محترمہ سیدہ ام حبیبہ رضی اللہ عنہا کے والد ابوسفیان رضی اللہ عنہ فوت ہوئے تو میں ان کے ہاں گئی ، ام حبیبہ رضی اللہ عنہا نے زرد رنگ ملی مخلوط یا کوئی اور خوشبو منگوائی ، اس میں سے ( پہلے ) ایک بچی کو لگائی ( تاکہ ) ہاتھ پر اس کی مقدار بہت کم ہو جائے ) پھر اپنے رخساروں پر ہاتھ مل لیا ، پھر کہا : اللہ کی قسم! مجھے خوشبو کی ضرورت نہ تھی مگر ( بات یہ ہے کہ ) میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ منبر پر ارشاد فرما رہے تھے : \" کسی عورت کے لیے جو اللہ تعالیٰ اور آخرت کے دن پر ایمان رکھتی ہو ، حلال نہیں کہ وہ کسی بھی مرنے والے پر تین دن سے زیادہ سوگ منائے مگر خاوند پر ، چار ماہ دس دن ( سوگ منائے)","",{"u2":"حمید بن نافع نے زینب بنت ابی سلمہ سے روایت کی کہ انہوں نے اِن (حمید) کو یہ تین حدیثیں بیان کیں، کہا: زینب رضی اللہ عنہا نے کہا: جب نبی صلی اللہ علیہ وسلم کی زوجہ محترمہ سیدہ ام حبیبہ رضی اللہ عنہا کے والد ابوسفیان رضی اللہ عنہ فوت ہوئے تو میں ان کے ہاں گئی، ام حبیبہ رضی اللہ عنہا نے زرد رنگ ملی مخلوط یا کوئی اور خوشبو منگوائی، اس میں سے (پہلے) ایک بچی کو لگائی (تاکہ) ہاتھ پر اس کی مقدار بہت کم ہو جائے) پھر اپنے رخساروں پر ہاتھ مل لیا، پھر کہا: اللہ کی قسم! مجھے خوشبو کی ضرورت نہ تھی مگر (بات یہ ہے کہ) میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ منبر پر ارشاد فرما رہے تھے: \"کسی عورت کے لیے جو اللہ تعالیٰ اور آخرت کے دن پر ایمان رکھتی ہو، حلال نہیں کہ وہ کسی بھی مرنے والے پر تین دن سے زیادہ سوگ منائے مگر خاوند پر، چار ماہ دس دن (سوگ منائے"}],[3696,"حمید بن نافع نے زینب بنت ابی سلمہ سے روایت کی کہ انہوں نے اِن ( حمید ) کو یہ تین حدیثیں بیان کیں ، کہا : زینب رضی اللہ عنہا نے کہا : جب نبی صلی اللہ علیہ وسلم کی زوجہ محترمہ سیدہ ام حبیبہ رضی اللہ عنہا کے والد ابوسفیان رضی اللہ عنہ فوت ہوئے تو میں ان کے ہاں گئی ، ام حبیبہ رضی اللہ عنہا نے زرد رنگ ملی مخلوط یا کوئی اور خوشبو منگوائی ، اس میں سے ( پہلے ) ایک بچی کو لگائی ( تاکہ ) ہاتھ پر اس کی مقدار بہت کم ہو جائے ) پھر اپنے رخساروں پر ہاتھ مل لیا ، پھر کہا : اللہ کی قسم! مجھے خوشبو کی ضرورت نہ تھی مگر ( بات یہ ہے کہ ) میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ منبر پر ارشاد فرما رہے تھے : \" کسی عورت کے لیے جو اللہ تعالیٰ اور آخرت کے دن پر ایمان رکھتی ہو ، حلال نہیں کہ وہ کسی بھی مرنے والے پر تین دن سے زیادہ سوگ منائے مگر خاوند پر ، چار ماہ دس دن ( سوگ منائے)",""],[3697,"حمید بن نافع سے روایت ہے ، انہوں نے کہا : میں نے زینب بنت ام سلمہ رضی اللہ عنہا سے سنا ، انہوں نے کہا : ام حبیبہ رضی اللہ عنہا کا کوئی انتہائی قریبی عزیز فوت ہو گیا ۔ انہوں نے زرد رنگ کی خوشبو منگوائی اور اسے ہلکا سا اپنے ( رخسار اور ) بازوؤں پر لگایا ، اور کہا : میں اس لیے ایسا کر رہی ہوں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : \" کسی عورت کے لیے جو اللہ تعالیٰ اور آخرت کے دن پر ایمان رکھتی ہو ، حلال نہیں کہ وہ ( کسی مرنے والے پر ) تین دن سے زیادہ سوگ منائے ، مگر خاوند پر چار مہینے دس دن ( سوگ منائے)",""],[3698,"معاذ بن معاذ نے ہمیں حدیث بیان کی ، ( کہا : ) ہمیں شعبہ نے حمید بن نافع سے اکٹھی دو حدیثیں بیان کیں ، سرمہ لگانے کے بارے میں ام سلمہ رضی اللہ عنہا کی حدیث اور ام سلمہ رضی اللہ عنہا اور نبی صلی اللہ علیہ وسلم کی ازواج میں سے ایک اور بیوی کی حدیث ، البتہ انہوں نے ان کا نام ، زینب نہیں لیا ۔ ۔ ۔ ( باقی حدیث ) محمد بن جعفر کی ( سابقہ ) حدیث کی طرح ( بیان کی)","",{"u2":"حمید بن نافع سے روایت ہے، انہوں نے کہا: میں نے زینب بنت ام سلمہ رضی اللہ عنہا سے سنا وہ اپنی والدہ سے حدیث بیان کر رہی تھیں کہ ایک عورت کا شوہر فوت ہو گیا، انہیں اس کی آنکھ کے بارے میں (بیماری لاحق ہونے کا) خطرہ محسوس ہوا تو وہ نبی صلی اللہ علیہ وسلم کے پاس آئے، اور آپ سے سرمہ لگانے کی اجازت مانگی، اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی اپنے گھر کے بدترین حصے میں اپنے ٹاٹوں میں۔۔ یا فرمایا: اپنے بدترین ٹاٹوں میں اپنے گھر کے اندر۔۔۔ سال بھر رہتی، اس کے بعد جب کوئی کتا گزرتا تو وہ ایک لید پھینکتی اور باہر نکلتی تو کیا (اب) چار مہینے دس دن (صبر) نہیں (کر سکتی"}],[3699,"حمید بن نافع سے روایت ہے کہ انہوں نے زینب بنت ابی سلمہ رضی اللہ عنہا سے سنا ، وہ سیدہ ام سلمہ اور سیدہ ام حبیبہ رضی اللہ عنہا سے حدیث بیان کر رہی تھیں ، وہ دونوں یہ بتا رہی تھیں کہ ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوئی اور عرض کی کہ اس کی ایک بیٹی کا شوہر فوت ہو گیا ہے ، اس کی آنکھ میں تکلیف ہو گئی ہے وہ چاہتی ہے کہ اس میں سرمہ لگائے ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" بلاشبہ تم میں سے کوئی عورت ( پورا ) سال گزرنے پر لید پھینکا کرتی تھی ، اور یہ تو صرف چار مہینے دس دن ہیں","",{"u2":"معاذ بن معاذ نے ہمیں حدیث بیان کی، (کہا:) ہمیں شعبہ نے حمید بن نافع سے اکٹھی دو حدیثیں بیان کیں، سرمہ لگانے کے بارے میں ام سلمہ رضی اللہ عنہا کی حدیث اور ام سلمہ رضی اللہ عنہا اور نبی صلی اللہ علیہ وسلم کی ازواج میں سے ایک اور بیوی کی حدیث، البتہ انہوں نے ان کا نام، زینب نہیں لیا۔۔۔ (باقی حدیث) محمد بن جعفر کی (سابقہ) حدیث کی طرح (بیان کی"}],[3701,"زینب بنت ابی سلمہ رضی اللہ عنہا سے روایت ہے ، انہوں نے کہا : جب ام حبیبہ رضی اللہ عنہا کے پاس ( ان کے والد ) ابوسفیان رضی اللہ عنہ کی موت کی خبر آئی تو انہوں نے تیسرے دن زرد رنگ کی خوشبو منگوائی اور اسے اپنے بازوؤں اور رخساروں پر ہلکا سا لگایا اور کہا : مجھے اس کی ضرورت نہ تھی ، ( مگر ) میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا تھا : \" کسی عورت کے لیے جو اللہ تعالیٰ اور آخرت کے دن پر ایمان رکھتی ہو ، حلال نہیں کہ وہ ( کسی مرنے والے پر ) تین دن سے زیادہ سوگ منائے ، سوائے شوہر کے ، وہ اس پر چار مہینے دس دن سوگ منائے","",{"u2":"زینب بنت ابی سلمہ رضی اللہ عنہا سے روایت ہے، انہوں نے کہا: جب ام حبیبہ رضی اللہ عنہا کے پاس (ان کے والد) ابوسفیان رضی اللہ عنہ کی موت کی خبر آئی تو انہوں نے تیسرے دن زرد رنگ کی خوشبو منگوائی اور اسے اپنے بازوؤں اور رخساروں پر ہلکا سا لگایا اور کہا: مجھے اس کی ضرورت نہ تھی، (مگر) میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا تھا: \"کسی عورت کے لیے جو اللہ تعالیٰ اور آخرت کے دن پر ایمان رکھتی ہو، حلال نہیں کہ وہ (کسی مرنے والے پر) تین دن سے زیادہ سوگ منائے، سوائے شوہر کے، وہ اس پر چار مہینے دس دن سوگ منائے"}],[3702,"لیث بن سعد نے نافع سے روایت کی کہ صفیہ بنت ابی عبید نے انہیں سیدہ حفصہ رضی اللہ عنہا سے یا سیدہ عائشہ رضی اللہ عنہا سے یا ان دونوں سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کسی عورت کے لیے ، جو اللہ تعالیٰ اور آخرت کے دن پر ایمان رکھتی ہے ۔ ۔ یا فرمایا : اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم پر ایمان رکھتی ہے ۔ ۔ حلال نہیں کہ وہ اپنے شوہر کے سوا کسی بھی مرنے والے پر تین دن سے زیادہ سوگ منائے","",{"u2":"لیث بن سعد نے نافع سے روایت کی کہ صفیہ بنت ابی عبید نے انہیں سیدہ حفصہ رضی اللہ عنہا سے یا سیدہ عائشہ رضی اللہ عنہا سے یا ان دونوں سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی عورت کے لیے، جو اللہ تعالیٰ اور آخرت کے دن پر ایمان رکھتی ہے۔۔ یا فرمایا: اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم پر ایمان رکھتی ہے۔۔ حلال نہیں کہ وہ اپنے شوہر کے سوا کسی بھی مرنے والے پر تین دن سے زیادہ سوگ منائے"}],[3703,"عبداللہ بن دینار نے نافع سے لیث کی حدیث کی سند کے ساتھ اسی کی مانند روایت بیان کی","",{"u2":"عبداللہ بن دینار نے نافع سے لیث کی حدیث کی سند کے ساتھ اسی کی مانند روایت بیان کی"}],[3704,"یحییٰ بن سعید کہتے ہیں : میں نے نافع سے سنا ، وہ صفیہ بنت ابوعبید سے حدیث بیان کر رہے تھے کہ انہوں نے نبی صلی اللہ علیہ وسلم کی زوجہ حفصہ بنت عمر رضی اللہ عنہا سے سنا ، وہ نبی صلی اللہ علیہ وسلم سے حدیث بیان کر رہی تھیں ۔ ۔ ۔ جس طرح لیث اور ابن دینار کی حدیث ہے ۔ اور یہ اضافہ کیا : \" وہ اس پر چار مہینے دس دن سوگ منائے گی","",{"u2":"یحییٰ بن سعید کہتے ہیں: میں نے نافع سے سنا، وہ صفیہ بنت ابوعبید سے حدیث بیان کر رہے تھے کہ انہوں نے نبی صلی اللہ علیہ وسلم کی زوجہ حفصہ بنت عمر رضی اللہ عنہا سے سنا، وہ نبی صلی اللہ علیہ وسلم سے حدیث بیان کر رہی تھیں۔۔۔ جس طرح لیث اور ابن دینار کی حدیث ہے۔ اور یہ اضافہ کیا: \"وہ اس پر چار مہینے دس دن سوگ منائے گی"}],[3705,"ایوب اور عبیداللہ دونوں نے نافع سے ، انہوں نے صفیہ بنت ابی عبید سے ، انہوں نے نبی صلی اللہ علیہ وسلم کی کسی اور اہلیہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ان ( لیث بن سعد ، عبداللہ بن دینار اور یحییٰ بن سعید ) کی حدیث کے ہم معنی حدیث روایت کی","",{"u2":"ایوب اور عبیداللہ دونوں نے نافع سے، انہوں نے صفیہ بنت ابی عبید سے، انہوں نے نبی صلی اللہ علیہ وسلم کی کسی اور اہلیہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ان (لیث بن سعد، عبداللہ بن دینار اور یحییٰ بن سعید) کی حدیث کے ہم معنی حدیث روایت کی"}],[3706,"سیدہ عائشہ رضی اللہ عنہا نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" کسی عورت کے لیے ، جو اللہ تعالیٰ اور قیامت کے دن پر ایمان رکھتی ہے ، حلال نہیں کہ وہ اپنے شوہر کے سوا کسی مرنے والے پر تین دن سے زیادہ سوگ منائے","",{"u2":"سیدہ عائشہ رضی اللہ عنہا نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"کسی عورت کے لیے، جو اللہ تعالیٰ اور قیامت کے دن پر ایمان رکھتی ہے، حلال نہیں کہ وہ اپنے شوہر کے سوا کسی مرنے والے پر تین دن سے زیادہ سوگ منائے"}],[3707,"ابن ادریس نے ہمیں ہشام سے حدیث بیان کی ، انہوں نے سیدہ حفصہ رضی اللہ عنہا سے اور انہوں نے ام عطیہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی عورت کسی مرنے والے پر تین دن سے زیادہ سوگ نہ منائے ، مگر خاوند پر ، ( اس پر ) چار مہینے دس دن ( سوگ منائے ) نہ وہ عَصب کے خانہ دار کپڑے کے سوا کوئی رنگا ہوا کپڑا پہنے ، نہ سرمہ لگائے ، مگر ( اس دوران میں ) جب ( حیض سے ) پاک ہو تو معمولی سی قُسط یا اظفار ( جیسی کوئی چیز ) استعمال کر لے ۔ \" ( یہ دونوں خوشبوئیں نہیں ، صرف بدبو کو زائل کرنے والے بخور ہیں)","",{"u2":"ابن ادریس نے ہمیں ہشام سے حدیث بیان کی، انہوں نے سیدہ حفصہ رضی اللہ عنہا سے اور انہوں نے ام عطیہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی عورت کسی مرنے والے پر تین دن سے زیادہ سوگ نہ منائے، مگر خاوند پر، (اس پر) چار مہینے دس دن (سوگ منائے) نہ وہ عَصب کے خانہ دار کپڑے کے سوا کوئی رنگا ہوا کپڑا پہنے، نہ سرمہ لگائے، مگر (اس دوران میں) جب (حیض سے) پاک ہو تو معمولی سی قُسط یا اظفار (جیسی کوئی چیز) استعمال کر لے۔\" (یہ دونوں خوشبوئیں نہیں، صرف بدبو کو زائل کرنے والے بخور ہیں"}],[3708,"عبداللہ بن نمیر اور یزید بن ہارون ، دونوں نے ہشام سے اسی سند کے ساتھ روایت کی ، اور دونوں نے کہا : \" طہر کے آغاز میں تھوڑی سی قسط اور اظفار لگا لے","",{"u2":"عبداللہ بن نمیر اور یزید بن ہارون، دونوں نے ہشام سے اسی سند کے ساتھ روایت کی، اور دونوں نے کہا: \"طہر کے آغاز میں تھوڑی سی قسط اور اظفار لگا لے"}],[3709,"ایوب نے حفصہ سے ، انہوں نے ام عطیہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : ہمیں منع کیا جاتا تھا کہ ہم کسی مرنے والے پر تین دن سے زیادہ سوگ منائیں ۔ مگر خاوند پر ، ( اس پر ) چار مہینے دس دن ( سوگ ہے ۔ ) نہ سرمہ لگائیں ، نہ خوشبو استعمال کریں اور نہ رنگا ہوا کپڑا پہنیں ، اور عورت کو اس کے طہر میں ، جب ہم میں سے کوئی اپنے حیض سے غسل کر لے ، اجازت دی گئی کہ وہ تھوڑی سی قسط اور اظفار استعمال کر لے","",{"u2":"ایوب نے حفصہ سے، انہوں نے ام عطیہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: ہمیں منع کیا جاتا تھا کہ ہم کسی مرنے والے پر تین دن سے زیادہ سوگ منائیں۔ مگر خاوند پر، (اس پر) چار مہینے دس دن (سوگ ہے۔) نہ سرمہ لگائیں، نہ خوشبو استعمال کریں اور نہ رنگا ہوا کپڑا پہنیں، اور عورت کو اس کے طہر میں، جب ہم میں سے کوئی اپنے حیض سے غسل کر لے، اجازت دی گئی کہ وہ تھوڑی سی قسط اور اظفار استعمال کر لے"}],[3710,"سہل بن سعد ساعدی رضی االله عنہ سے روایت ہے عویمر عجلانی ، عاصم بن عدی انصاری کے پاس آیا اور ان سے کہا اے عاصم! بھلا اگر کوئی شخص اپنی جورو کیس اتھ کسی مرد کو دیکھے کیا اس کو مار ڈالے ، پھر تم اس کو مار ڈالو گے یا وہ کیا کرے؟ تو یہ مسئلہ پوچھو میرے واسطے رسول االله صلی اللہ علیہ وسلم سے ۔ عاصم رضی االله عنہ نے رسول االله صلی اللہ علیہ وسلم سے پوچھا آپ نے اس قسم کے سوالوں کو ناپسند کیا اور ان کی برائی بیان کی ۔ عاصمؓ نے جو رسول االله صلی اللہ علیہ وسلم سے سنا وہ ان کو شاق گزرا ۔ جب وہ اپنے لوگوں میں لوٹ کر آئے تو عویمر ان کے پاس آئے اور پوچھا اے عاصمؓ! جناب رسول االله صلی اللہ علیہ وسلم نے کیا فرمایا؟ عاصمؓ نے عویمرؓ سے کہا تو میرے اچھی چیز نہیں لایا ۔ رسول االله صلی اللہ علیہ وسلم کو تیرا مسئلہ پوچھنا ناگوار ہوا ۔ عویمرؓ نے کہا قسم خدا کی میں تو باز نہ آؤں گا جب تک یہ مسئلہ آپ سے نہ پوچھوں گا ۔ پھر عویمرؓ آیا رسول االله صلی اللہ علیہ وسلم کے پاس تمام لوگوں میں اور عرض کیا یارسول االله! آپ کیا فرماتے ہیں اگرکوئی شخص اپنی بی بی کے پاس غیر مرد کو دیکھے اس کو مار ڈالے ، پھر آپ اس کو مار ڈالیں گے ( اس کے قصاص میں ) وہ کیا کرے؟ رسول االله صلی اللہ علیہ وسلم نے فرمایا تیرے او رتیری جورو کے باب میں االله کا حکم اُترا ( یعنی آیت لعان کی ) تو جا او راپنی جورو کو لے کر آ ۔ سہلؓ نے کہا پھر دونوں میاں بیبی نے لعان کیا او رمیں لوگوں کے ساتھ رسول االله صلی اللہ علیہ وسلم کے پاس موجود تھا جب وہ فارغ ہوئے تو عویمرؓ نے کہا یا رسول االله اگر میں اس عورت کو اب رکھوں تو میں جھوٹا ہوں پھر عویمرؓ نے اس کو تین طلاق دے دیں اس سے پہلے کہ رسول االله صلی اللہ علیہ وسلم اس کو حکم کرتے ابن شہاب نے کہا پھر لعان کرنے والوں کا یہی طریقہ ٹھہر گیا ۔"],[3711,"سہل بن سعدؓ سے روایت ہے عویمر انصاریؓ جو بنی عجلان میں سے تھا عاصم بن عدیؓ کے پاس آیا پھر بیان کیا حدیث کو اخیر تک اسی طرح جیسے اوپر گزری اور حدیث میں ابن شہاب کا قول بھی شریک کردیاکہ پھر جدائی مرد کو عورت سے سنت ہوگئی لعان کرنے والوں میں اور اتنا زیادہ کیا کہ سہل نے کہا وہ عورت حاملہ تھی اس کے بیٹے کو ماں کی طرف نسبت کرکے پکارتے پھر یہ طریقہ جاری ہوا کہ ایسا لڑکا اپنی ماں کا وارث ہوگا اور وہ اس کی وارث ہوگی اپنے حصہ کے موافق ۔"],[3712,"ابن جریج سے روایت ہے کہ مجھ سے ابن شہاب نے بیان کیا متاعنین کا حال او ران کا طریقہ سہل بن سعدؓ کی حدیث سے جو بنی ساعدہ میں سے تھا اس نے کہا انصار میں سے ایک شخص رسول االله صلی اللہ علیہ وسلم کے پاس آیا اور عرض کیا یارسول االله آپ کیا سمجھتے ہیں اگر کوئی شخص اپنی جورو کے ساتھ کسی مرد کو دیکھے اور بیان کیا سارا قصہ حدیث کا اور اتنا زیادہ کیا کہ پھر دونوں نے لعان کیا مسجد کے اندر اور میں موجود تھا اور اس روایت میں یہ بھی ہے کہ اس شخص نے طلاق دی تین بار اپنی عورت کو رسول االله صلی اللہ علیہ وسلم کے حکم کرنے سے پہلے پھر وہ جدا ہوگیا اس سے آپ کے سامنے آپ نے فرمایا یہی جدائی ہے درمیان لعان کرنے والوں کے ۔"],[3713,"سعید بن جبیرؓ سے روایت ہے مجھ سے پوچھا گیا لعان کرنے والوں کا مسئلہ مصعب بن زبیر کی خلافت میں میں حیران ہوا کیا جواب دوں تو میں چلا عبداالله بن عمرؓ کے مکان کی طرف مکہ میں او ران کے غلام سے کہا میری عرض کرو اس نے کہا وہ آرام کرتے ہیں انہوں نے میری آواز سنی او رکہا کیا جبیر کا بیٹا ہے؟ میں نے کہا ہاں انہوں نے کہا اندر آ قسم خدا کی تو کسی کام سے آیا ہوگا میں اندر آگیا تو وہ ایک کمبل بچھائے بیٹھے تھے او رایک تکیے پر ٹیک لگائے تھے جو چھال سے کھجور کی بھرا ہوا تھا ۔ میں نے کہا اے ابوعبدالرحمن! لعان کرنے والوں میں جدائی کی جائے گی؟ انہوں نے کہا سبحان االله بے شک جدائی کی جائے گی اور سب سے پہلے اس باب میں فلاں نے پوچھا جو فلاں کا بیٹا تھا رسول االله صلی اللہ علیہ وسلم سے ۔ اس نے کہا یا رسول االله آپ کیا سمجھتے ہیں اگر ہم میں سے کوئی اپنی عورت کو برا کام کراتے دیکھے تو کیا کرے ، اگر منہ سے نکالے تو بری بات نکالے گا اگر چپ رہے تو ایسی بری بات سے کیونکر چپ رہے؟ رسول االله صلی اللہ علیہ وسلم یہ سن کر چپ ہورہے اور جواب نہیں دیا ۔ پھر وہ شخص آپ کے پاس آیا اور کہنے لگا یا رسول االله ۔ جو بات میں نے آپ سے پوچھی تھی میں خود اس میں پڑگیا ۔ تب االله تعالیٰ نے یہ آیتیں اتاریں سورۂ نور میں والذین یرمون ازواجھم آخر تک ۔ آپ نے یہ آیتیں مرد کو پڑھ کر سنائیں اور اس کو نصیحت کی اور سمجھایا کہ دنیا کا عذاب آخرت کے عذاب سے آسان ہے ۔ ( یعنی اگر تو جھوٹ طوفان باندھتا ہے تو اب بھی بول دے ، حد قذف کے اسی کوڑے پڑجائیں گے ، مگر یہ جہنم میں جلنے سے آسان ہے ) ۔ وہ بولا نہیں قسم اس کی جس نے آپ کو سچائی کے ساتھ بھیجا میں نے عورت پر طوفان نہیں جوڑا ۔ پھر آپ نے عوت کو بلایااوراس کو ڈرایا اور سمجھایا اور فرمایا دنیا کا عذاب سہل ہے آخرت کے عذاب سے ۔ وہ بولی نہیں قسم اس کی جس نے آپ کو سچائی کیس اتھ بھیجا ہے میرا خاوند جھوٹ بولتا ہے ۔ تب آپ نے شروع کیا مرد سے اور اس نے چار گواہیاں دیں االله تعالیٰ کے نام کی مقرر وہ سچا ہے اور پانچویں بار میں یہ کہا کہ خدا کی پھٹکار ہو اس پر اگر وہ جھوٹا ہو ۔ پھر عورت کو بلایا اس نے چار گواہیاں دیں االله تعالیٰ کے نام کی مقرر مرد جھوٹا ہے اور پانچویں بار میں یہ کہا االله کا غضب اترے اس پر اگر مرد سچا ہے ۔ اس کے بعد آپ نے جدائی کرادی ان دونوں میں ۔"],[3714,"اس سند سے ہی مندرجہ بالا روایت نقل کی گئی ہے ۔"],[3715,"عبداالله بن عمرؓ سے روایت ہے کہ رسول االله صلی اللہ علیہ وسلم نے فرمایا لعان کرنے والوں کو تم دونوں کا حساب االله تعالیٰ پر ہے ، تم میں سے ایک جھوٹا ہے ۔ آپ نے خاوند سے فرمایا اب تیرا کوئی بس عورت پر نہں ہے کیونکہ وہ تجھ سے ہمیشہ کے لیے جدا ہوگئی ۔ مرد بولا میرا مال یا رسول االله! جو اس نے لیا ہے ۔ آپ نے فرمایا مال تجھ کو نہیں ملے گا ، کیونکہ اگر تو سچا ہے تو مال کا بدلہ ہے جو اس کی فرج تجھ پر حلال ہوگئی اور اگر تو جھوٹا ہے تو مال اور دور ہوگیا ( بلکہ تیرے اوپر اور وبال ہوا جھوٹ کا ) ۔"],[3716,"عبداالله بن عمرؓ سے روایت ہے رسول االله صلی اللہ علیہ وسلم نے جدائی کردی بنی عجلان کی جورو اور مرد میں اور فرمایا االله تعالیٰ جانتا ہے تم میں سے کوئی جھوٹا ہے ۔ پھر کیا تم میں سے کوئی توبہ کرتا ہے؟"],[3717,"سعید بن جبیر سے روایت ہے کہ میں نے ابن عمرؓ سے لعان کو پوچھا تو انہوں نے نقل کیا جناب رسول االله صلی اللہ علیہ وسلم سے ایسا ہی جیسے اوپر گزرا ۔"],[3718,"سعید بن جبیر سے روایت ہے مصعب نے جدائی نہیں کی لعان کرنے والوں میں ۔ میں نے اس کا ذکر کیا عبداالله بن عمرؓ سے ۔ انہوں نے کہا جناب رسول االله صلی اللہ علیہ وسلم نے جدائی کردی بنی عجلان کے مرد اور عورت میں ۔"],[3719,"عبداالله بن عمر رضی االله عنہ سے روایت ہے کہ ایک مرد نے لعانلعان کیا رسول االله صلی اللہ علیہ وسلم کے زمانے میں پھر آپ نے جدائی کردی دونوں میں اور بچے کا نسب ماں سے لگادیا ۔"],[3720,"عبداالله بن عمرؓ سے روایت ہے رسول االله صلی اللہ علیہ وسلم نے لعان کروایا درمیان ایک مرد انصاری اور اس کی عورت کے اور جدائی کردی ان دونوں میں ۔"],[3721,"وہی جو اوپر گزرا ۔"],[3722,"عبداالله بن مسعودؓ سے روایت ہے میں جمعہ کی رات کو مسجد میں تھا اتنے میں ایک مرد انصاری آیا اور بولا اگر کوئی اپنی جورو کے پاس کسی مرد کو پائے او رمنہ سے نکالے تو تم اس کو کوڑے لگاؤ گے ( حد قذف کے ) اگر مار ڈالے تو تم اس کو مار ڈالوگے ( قصاص میں ) اگر چپ رہے تو اپنا غصہ پی کر چپ رہے قسم االله کی میں جناب رسول االله صلی اللہ علیہ وسلم سے پوچھوں گا اس مسئلے کو جب دوسرا دن ہوا تو جناب رسول االله صلی اللہ علیہ وسلم کے پاس آیا اور آپ سے پوچھا اس نے کہا اگر کوئی شخص اپنی بی بی کے ساتھ کسی کو پائے پھر منہ سے نکالے تو تم کوڑے لگاؤگے اگر مار ڈالے تو تم اس کو بھی مار ڈالوگے اگر چپ رہے تو اپنا غصہ کھا کر چپ رہے ( یہ بھی نہیں ہوسکتا ) جناب رسول االله صلی اللہ علیہ وسلم نے فرمایا االله کھول دے ( اس مشکل کو ) اور دعا کرنے لگے تب لعان کی آیت اتری ۔ والذین یرمون ازواجھم ولم یکن لھم شھداء الا انفسھم ۔ اخیر تک پھر اس مرد کا امتحان لیا گیا لوگوں کے سامنے اور وہ اس کی جورو دونوں رسول االله صلی اللہ علیہ وسلم کے پاس آئے اور لعان کیا پہلے مرد نے گواہی دی چار بار کہ وہ سچا ہے پھر پانچویں بار لعنت کرکے کہا اگر وہ جھوٹا ہو تو اس پر لعنت ہے خداتعالیٰ کی پھر عورت چلی لعان کرنے کو آپ نے فرمایا ٹھہر ( اور اگر خاوند کی بات سچ ہے تو تو اپنے قصور کا اقرار کر ) لیکن اس نے نہ مانا اور لعان کیا جب پیٹھ موڑ کر چلے تو آپ نے فرمایا اس عورت کا بچہ شاید کالے رنگ کا گھرنگریالے بالوں والا پیدا ہوگا ( اس شخص کی صورت پر جس کا خاوند کو گمان تھا ) ۔ پھر ویسا ہی کالا گھونگریالے بالوں والا پیدا ہوا ۔"],[3723,"اعمش سے اس سند کے ساتھ اسی طرح منقول ہے ۔"],[3724,"محمد سے روایت ہے میں نے انس بن مالک سے پوچھا یہ سمجھ کر کہ ان کو معلوم ہے ۔ انہوں نے کہا کہ ہلال بن امیہ نے نسبت کی زنا کی اپنی بیوی کو شریک بن سحماء سے اور ہلالؓ بن امیہ براء بن مالکؓ کا مادری بھائی تھا ۔ اور اس نے سب سے پہلے لعان کیا اسلام میں ۔ راوی نے کہا پھر دونوں میاں بیوی نے لعان کیا تو رسول االله صلی اللہ علیہ وسلم نے فرمایا اس عورت کو دیکھتے رہو اگر اس کا بچہ سفید رنگ کا ، سیدھے بال والا ، لال آنکھوں والا پیدا ہو تو وہ ہلال بن امیہؓ کا ہے اور جو سرمئی آنکھوں والا ، گھونگریالے بالوں والا ، پتلی پنڈلیوں والا پیدا ہو تو وہ شریک بن سحماء کا ہے ۔ انسؓ نے کہا مجھ کو خبر پہنچی کہ اس عورت کا لڑکا سرمگیں آنکھ ، گھونگریالے بال اور پتلی پنڈلیوں والا پیدا ہوا ۔"],[3725,"عبداالله بن عباسؓ سے روایت ہے کہ رسول االله صلی اللہ علیہ وسلم کے پاس لعان کا ذکر ہوا ۔ عاصم بن عدی نے اس میں کچھ کہا پھر وہ چلے گئے ۔ تب ان کے پاس ان کی قوم کا ایک شخص آیا اور شکایت کرنے لگا کہ اس نے اپنی بی بی کے ساتھ ایک مرد کو دیکھا ۔ عاصم نے کہا میں اس بلا میں مبتلا ہوا اپنی بات کی وجہ سے ۔ پھر عاصمؓ اس کو لے کر رسول االله صلی اللہ علیہ وسلم کے پاس آئے ۔ اور اس شخص نے سارا حال آپ سے بیان کیا وہ شخص زرد رنگ دبلا سیدھے بالوں والا تھا ۔ او رجس پر دعویٰ کرتا تھا وہ پر گوشت پنڈلیوں والا ، گندم رنگ ، موٹا تھا ۔ جناب رسول االله صلی اللہ علیہ وسلم نے فرمایا االله تو کھول دے ۔ پھر وہ عورت بچہ جنی جو مشابہ تھا اس شخص کے جس پر تہمت تھی ۔ تب جناب رسول االله صلی اللہ علیہ وسلم نے لعان کروایا دونوں ۔ میں ایک شخص بولا اے ابن عباسؓ! کیا یہ عورت وہی عورت تھی جس کے لیے جناب رسول االله صلی اللہ علیہ وسلم نے فرمایا تھا اگر میں کسی کو بغیر گواہوں کے سنگسار کرتا تو اس عورت کو کرتا ۔ ابن عباسؓ نے کا نہیں وہ دوسری عورت تھی جو مسلمانوں میں برائی کے ساتھ مشہور تھی ( یعنی لوگ کہتے تھے کہ یہ فاحشہ ہے نہ گواہ تھے نہ اقرار تھا ) ۔"],[3726,"ترجمہ دوسری روایت کا وہی ہے جو اوپر گزرا ۔ اس میں اتنا زیادہ ہے کہ وہ شخص جس کے ساتھ تہمت تھی موٹا ، سخت گھونگریالے بالوں والا تھا ۔"],[3727,"قاسم بن محمد سے روایت ہے ابن عباس رضی االله عنہما کے سامنے لعان والوں کا ذکر ہوا تو عبداالله بن شداد نے کہا ان ہی میں وہ عورت تھی جس کے لیے رسول االله صلی اللہ علیہ وسلم نے فرمایا تھا اگر میں کسی کو بغیر گواہوں کے رجم کرتا تو اس عورت کو رجم کرتا ۔ ابن عباس رضی االله عنہما نے کہا نہیں وہ عورت دوسری عورت تھی جو علانیہ بدکار تھی ۔"],[3728,"ابوہریرہ رضی االله عنہ سے روایت ہے سعد بن عبادہ انصاریؓ ( انصار کے رئیس ) نے کہا یا رسول االله صلی اللہ علیہ وسلم! اگر کوئی شخص اپنی بی بی کے ساتھ کسی مرد کو پائے ( زنا کرتے ہوئے ) کیا اس کو مار ڈالے؟ رسول االله صلی اللہ علیہ وسلم نے فرمایا نہیں ۔ سعد نے کہا نہیں مار ڈالے قسم اس کی جس نے آپ کو سچائی کے ساتھ عزت دی ۔ رسول االله صلی اللہ علیہ وسلم نے فرمایا ( اور صحابہ سے ) سنو تمہارے سردار کیا کہتے ہیں ( یعنی تعجب ہے ان سے کہ ایسی بات کہتے ہیں االله تعالیٰ کے حکم کے سامنے طبیعت اور غصہ کو دخل نہ دینا چاہیے ) ۔"],[3729,"ابوہریرہ رضی االله عنہ سے روایت ہے سعد بن عبادہؓ نے کہا یارسول االله صلی اللہ علیہ وسلم! اگر میں اپنی بیوی کے پاس غیر مرد کو دیکھوں تو کیا اس کو مہلت دوں چار گواہ لانے تک؟ آپ نے فرمایا ہاں ۔"],[3730,"سیدنا ابوہریرہ رضی االله عنہ سے روایت ہے سعد بن عبادہؓ نے کہا یارسول االله صلی اللہ علیہ وسلم! اگر میں اپنی بیوی کے ساتھ کسی مرد کو دیکھوں تو میں اس کو ہاتھ نہ لگاؤں جب تک چار گواہ نہ لاؤں؟ آپ نے فرمایا بے شک ۔ سعدؓ نے کہا ہرگز نہیں میں تو قسم اس کی جس نے آپ کو سچائی کے ساتھ بھیجا جلدی اس کا علاج تلوار سے کردوں اس سے پہلے ۔ رسول االله صلی اللہ علیہ وسلم نے فرمایا سنو تمہارے سردار کیا کہتے ہیں وہ برے غیرت دار ہیں او رمیں ان سے زیادہ غیرت دار ہوں اور االله جل جلالہ مجھ سے زیادہ غیرت رکھتا ہے ۔"],[3731,"مغیرہ بن شعبہؓ سے روایت ہے سعد بن عبادہؓ نے کہا اگر میں اپنی بی بی کے پاس کسی مرد کو دیکھوں تو تلوار سے مار ڈالوں کبھی نہ چھوڑوں ۔ یہ خبر رسول االله صلی اللہ علیہ وسلم کو پہنچی آپ نے فرمایا تم سعد کی غیرت سے تعجب کرتے ہو قسم االله کی میں ان سے زیادہ غیرت دار ہوں اور االله جل جلالہ مجھ سے زیادہ غیرت دار ہے ۔ حرام کیا االله نے بے شرمی کی باتوں کو چھپی او رکھلی اسی غیرت کی وجہ سے اور کوئی شخص االله تعالیٰ سے زیادہ غیرت دار نہیں ہے اور االله سے زیادہ کسی شخص کو عذر پسند نہیں ہے ۔ اسی لیے االله تعالیٰ نے پیغمبروں کو بھیجا خوشی اور ڈر سناتے ہوئے ( تاکہ بندے سزا سے پہلے اس کی درگاہ میں عذر کرلیں اور توبہ کریں ) ۔ اور کسی شخص کو االله سے زیادہ تعریف پسند نہیں اس لیے االله تعالیٰ نے وعدہ کیا جنت کا ( تاکہ بندے اس کی عبادت اور تعریف کرکے جنت حاصل کرلیں ) ۔"],[3732,"اس سند سے بھی یہ حدیث مروی ہے اس روایت میں ’’غَیْرَ «مُصْفَعٍ» ‘‘ کے الفاظ ہیں اور ’عَنْہ ‘‘ نہیں ہے ۔"],[3733,"ابوہریرہ رضی االله عنہ سے روایت ہے ایک شخص بنی فزارہ میں سے آیا روسل االله صلی اللہ علیہ وسلم کے پاس او رکہا میری جورو کو ایک کالا بچہ پیدا ہوا ہے ( تو وہ میرا معلوم نہیں ہوتا کیونکہ میں کالا نہیں ہوں ) ۔ جناب رسول االله صلی اللہ علیہ وسلم نے فرمایا تیرے پاس اونٹ ہیں؟ اس کہا ہاں ہیں ۔ آپ نے فرمایا ان کا رنگ کیا ہے؟ وہ بولا لال ہے ۔ آپ نے فرمایا ان میں کوئی خاکی بھی ہے؟ اس نے کہا ہاں خاکی بھی ہیں ۔ آپ نے فرمایا پھر یہ رنگ کہاں سے آیا؟ اس نے کہا کسی رگ نے گھسیٹ لیا ہوگا ۔"],[3734,"زہری نے ابن عینیہ کی حدیث کی مانند روایت کی اس میں اتنا فرق ہے کہ کہا اے رسول االله صلی اللہ علیہ وسلم! میری عورت نے لڑکا سیاہ جنا ہے اور میرا ارادہ ہے کہ اس کا انکار کروں اور دوسری حدیث میں اتنا زیادہ ہے کہ پھر رسول االله صلی اللہ علیہ وسلم نے اس کے انکار کرنے کی اجازت نہ دی ۔"],[3735,"ابوہریرہ رضی االله عنہ سے روایت ہے کہ تحقیق ایک اعرابی آیا رسول االله صلی اللہ علیہ وسلم کے پاس او رکہا اے رسول االله صلی اللہ علیہ وسلم! میری عورت نے کالا بچہ جنا ہے اور میں اس کا انکار کرتا ہوں ، تو رسول االله صلی اللہ علیہ وسلم نے اس کو فرمایا تیرے پاس اونٹ ہیں؟ اس نے کہا ہاں ۔ آپ نے فرمایا ان کا رنگ کیسا ہے؟ اس نے کہا سرخ ۔ آپ نے پوچھا کہ ان میں کوئی کالا بھی ہے؟ وہ بولا ہاں تو رسول االله صلی اللہ علیہ وسلم نے فرمایا یہ رنگ کہاں سے آگیا؟ اعرابی بولا کہ اے رسول االله صلی اللہ علیہ وسلم کسی رگ نے گھسیٹ لیا ہوگا تو جناب رسول االله صلی اللہ علیہ وسلم نے فرمایا کہ یہاں بھی کسی رگ نے گھسیٹ لیا ہوگا ۔"],[3736,"سیدنا ابو ہریرہ رضی االله عنہ نبی اکرم صلی اللہ علیہ وسلم سے اسی طرح کی روایت بیان کرتے ہیں ۔"],[3737,"عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے رسول اللہ نے فرمایا جو شخص اپنا حصہ آزاد كرے بردہ میں سے ( یعنی وہ بردہ مشترك ہو ) اور ایك شریك اپنا حصہ آزاد كرے اور پھر آزاد كرنے والے كے پاس اس قدر مال ہو جق بردے كی قیمت كو پہنچ جا‎ئے تو اس بردے كی واجبی قیمت لگا‎‎ئی جائے اور باقی شریكوں كو ان كے حصے كی قیمت اس كے مال میں سے دی جائے گی اور كل بردہ اس كی طرف سے آزاد ہوجائے گا . اور جو وہ مال دار نہ ہو تو جس قدر حصہ اس بردہ كا آزاد ہوا اتنا ہی آزاد رہے گا . "],[3738,"اس حدیث کی دوسری اسناد مذکور ہیں ۔"],[3739,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جو بردہ دو آدمیوں میں مشترك ہو پھر ایك شریك اپنا حصہ آزاد كردیوے تو وہ ضامن ہوگا دوسرے شریك كے حصے كا ( اگر مال دار ہو)"],[3740,"ابو ہریرہ رضی اللہ عنہ سے رویت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جو شخص اپنا حصہ غلام میں آزاد كردے تو اس كا چھڑانا ( یعنی دوسرے حصے كا بھی آزاد كرنا ) بھی اسی كے مال سے ہوگا اگر مال دار ہو ، اگر مال دار نہ ہو تو غلام محنت مزدوری كرے اور اس پر جبر نہ كریں "],[3741,"ترجمہ دوسری روایت كا بھی وہی ہے جو اوپر گذرا اس میں اتنا زیادہ ہے كہ اگر وہ آزاد كرنے والا مال دار نہ ہو تو غلام كی واجبی قیمت لگائی جائے اور محنت كرے اپنے باقی حصے كے لیے جو آزاد نہیں ہوا مگر اس پر جبر نہیں ہوگا ۔ "],[3742,"قتادہ رضی اللہ عنہ نے ابن ابی عروبہ كی حدیث كی مانند روایت كی اور حدیث میں یہ بھی ذكر كیا كہ اس كی واجبی قیمت لگائی جائے ۔"],[3743,"سیدنا ابن عمر رضی اللہ عنہ نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ انہوں نے ایک لونڈی خرید کر اسے آزاد کرنے کا ارادہ کیا ۔ اس کے مالکوں نے کہا : ہم اس شرط پر یہ کنیز آپ کو بیچیں گے کہ اس کا حقِ ولاء ہمارا ہو گا ۔ سیدہ عائشہ رضی اللہ عنہا نے اس بات کا ذکر رسول اللہ صلی اللہ علیہ وسلم سے کیا تو آپ نے فرمایا : \"\" یہ ( شرط ) تمہیں ( اس کو خرید کر آزاد کرنے سے ) نہ روکے ( اس کنیز کو ضرور آزادی ملنی چاہئے ) بلاشبہ ولاء کا حق اسی کا ہے جس نے ( غلام یا کنیز کو ) آزاد کیا","",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ انہوں نے ایک لونڈی خرید کر اسے آزاد کرنے کا ارادہ کیا۔ اس کے مالکوں نے کہا: ہم اس شرط پر یہ کنیز آپ کو بیچیں گے کہ اس کا حقِ ولاء ہمارا ہو گا۔\nسیدہ عائشہ رضی اللہ عنہا نے اس بات کا ذکر رسول اللہ صلی اللہ علیہ وسلم سے کیا تو آپ نے فرمایا: \"یہ (شرط) تمہیں (اس کو خرید کر آزاد کرنے سے) نہ روکے (اس کنیز کو ضرور آزادی ملنی چاہئے) بلاشبہ ولاء کا حق اسی کا ہے جس نے (غلام یا کنیز کو) آزاد کیا"}],[3744,"لیث نے ہمیں ابن شہاب سے حدیث بیان کی ، انہوں نے عروہ سے روایت کی ، سیدہ عائشہ رضی اللہ عنہا نے انہیں خبر دی کہ بریرہ سیدہ عائشہ رضی اللہ عنہا کے پاس آئی ۔ وہ ان سے اپنی مکاتبت ( قیمت ادا کر کے آزادی کا معامدہ کرنے ) کے سلسلے میں مدد مانگ رہی تھی ، اس نے اپنی مکاتبت کی رقم میں سے کچھ بھی ادا نہیں کیا تھا ۔ سیدہ عائشہ رضی اللہ عنہا نے اس سے کہا : اپنے مالکوں کے پاس جاؤ ، اگر وہ پسند کریں کہ میں تمہاری مکاتبت کی رقم ادا کروں اور تمہارا حقِ ولاء میرے لیے ہو ، تو میں ( تمہاری قیمت کی ادائیگی ) کر دوں گی ۔ بریرہ رضی اللہ عنہا نے یہ اپنے مالکوں سے کہی تو انہوں نے انکار کر دیا ، اور کہا : اگر وہ تمہارے ساتھ نیکی کرنا چاہتی ہیں تو کریں ، لیکن تمہاری ولاء کا حق ہمارا ہی ہو گا ۔ اس پر انہوں ( عائشہ رضی اللہ عنہا ) نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے کی ۔ رسول اللہ صلی اللہ علیہ وسلم نے ان سے کہا : \" تم خرید لو اور آزاد کر دو ، کیونکہ ولاء کا حق اسی کا ہے جس نے آزاد کیا ۔ \" پھر رسول اللہ صلی اللہ علیہ وسلم ( منبر پر ) کھڑے ہوئے اور فرمایا : \" لوگوں کو کیا ہوا ہے وہ ایسی شرطیں رکھتے ہیں جو اللہ کی کتاب ( کی تعلیمات ) میں نہیں ۔ جس نے ایسی شرط رکھی جو اللہ کی کتاب میں نہیں ہے تو اسے اس کا کوئی حق نہیں چاہے وہ سو مرتبہ شرط رکھ لے ۔ اللہ کی شرط زیادہ حق رکھتی ہے اور وہی زیادہ مضبوط ہے","",{"u2":"لیث نے ہمیں ابن شہاب سے حدیث بیان کی، انہوں نے عروہ سے روایت کی، سیدہ عائشہ رضی اللہ عنہا نے انہیں خبر دی کہ بریرہ سیدہ عائشہ رضی اللہ عنہا کے پاس آئی۔ وہ ان سے اپنی مکاتبت (قیمت ادا کر کے آزادی کا معامدہ کرنے) کے سلسلے میں مدد مانگ رہی تھی، اس نے اپنی مکاتبت کی رقم میں سے کچھ بھی ادا نہیں کیا تھا۔ سیدہ عائشہ رضی اللہ عنہا نے اس سے کہا: اپنے مالکوں کے پاس جاؤ، اگر وہ پسند کریں کہ میں تمہاری مکاتبت کی رقم ادا کروں اور تمہارا حقِ ولاء میرے لیے ہو، تو میں (تمہاری قیمت کی ادائیگی) کر دوں گی۔ بریرہ رضی اللہ عنہا نے یہ اپنے مالکوں سے کہی تو انہوں نے انکار کر دیا، اور کہا: اگر وہ تمہارے ساتھ نیکی کرنا چاہتی ہیں تو کریں، لیکن تمہاری ولاء کا حق ہمارا ہی ہو گا۔ اس پر انہوں (عائشہ رضی اللہ عنہا) نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے کی۔ رسول اللہ صلی اللہ علیہ وسلم نے ان سے کہا: \"تم خرید لو اور آزاد کر دو، کیونکہ ولاء کا حق اسی کا ہے جس نے آزاد کیا۔\" پھر رسول اللہ صلی اللہ علیہ وسلم (منبر پر) کھڑے ہوئے اور فرمایا: \"لوگوں کو کیا ہوا ہے وہ ایسی شرطیں رکھتے ہیں جو اللہ کی کتاب (کی تعلیمات) میں نہیں۔ جس نے ایسی شرط رکھی جو اللہ کی کتاب میں نہیں ہے تو اسے اس کا کوئی حق نہیں چاہے وہ سو مرتبہ شرط رکھ لے۔ اللہ کی شرط زیادہ حق رکھتی ہے اور وہی زیادہ مضبوط ہے"}],[3745,"یونس نے مجھے ابن شہاب سے خبر دی ، انہوں نے عروہ بن زبیر سے ، انہوں نے نبی صلی اللہ علیہ وسلم کی اہلیہ سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : بریرہ میرے پاس آئی اور کہنے لگی : عائشہ! میں نے اپنے مالکوں سے 9 اوقیہ پر مکاتبت ( قیمت کی ادائیگی پر آزاد ہو جانے کا معاہدہ ) کیا ہے ، ہر سال میں ایک اوقیہ ( 40 درہم ادا کرنا ) ہے ، آگے لیث کی حدیث کے ہم معنی ہے اور ( اس میں ) یہ اضافہ کیا کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" تمہیں ان کی یہ بات ( بریرہ کو آزاد کرنے سے ) نہ روکے ۔ اسے خریدو اور آزاد کر دو ۔ \" اور ( یونس نے ) حدیث میں کہا : پھر رسول اللہ صلی اللہ علیہ وسلم لوگوں میں کھڑے ہوئے ، اللہ کی حمد و ثنا بیان کی ، پھر فرمایا : \" امابعد! \" ( خطبہ دیا جس میں شرط والی بات ارشاد فرمائی)","",{"u2":"یونس نے مجھے ابن شہاب سے خبر دی، انہوں نے عروہ بن زبیر سے، انہوں نے نبی صلی اللہ علیہ وسلم کی اہلیہ سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: بریرہ میرے پاس آئی اور کہنے لگی: عائشہ! میں نے اپنے مالکوں سے 9 اوقیہ پر مکاتبت (قیمت کی ادائیگی پر آزاد ہو جانے کا معاہدہ) کیا ہے، ہر سال میں ایک اوقیہ (40 درہم ادا کرنا) ہے، آگے لیث کی حدیث کے ہم معنی ہے اور (اس میں) یہ اضافہ کیا کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہیں ان کی یہ بات (بریرہ کو آزاد کرنے سے) نہ روکے۔ اسے خریدو اور آزاد کر دو۔\" اور (یونس نے) حدیث میں کہا: پھر رسول اللہ صلی اللہ علیہ وسلم لوگوں میں کھڑے ہوئے، اللہ کی حمد و ثنا بیان کی، پھر فرمایا: \"امابعد!\" (خطبہ دیا جس میں شرط والی بات ارشاد فرمائی"}],[3746,"ابواسامہ نے کہا : ہمیں ہشام بن عروہ نے حدیث بیان کی ، انہوں نے کہا : مجھے میرے والد نے سیدہ عائشہ رضی اللہ عنہا سے خبر دی ، انہوں نے کہا : بریرہ میرے پاس آئی اور کہنے لگی : میرے مالکوں نے میرے ساتھ 9 سالوں میں 9 اوقیہ ( کی ادائیگی ) کے بدلے مکاتبت کی ہے ۔ ہر سال میں ایک اوقیہ ( ادا کرنا ) ہے ۔ میری مدد کریں ۔ میں نے اس سے کہا : اگر تمہارے مالک چاہیں کہ میں انہیں یکمشت گن کر دوں اور تمہیں آزاد کر دوں اور ولاء کا حق میرا ہو ، تو میں ایسا کر لوں گی ۔ اس نے یہ بات اپنے مالکوں سے کی تو انہوں نے ( اسے ماننے سے ) انکار کر دیا الا یہ کہ حقِ ولاء ان کا ہو ۔ اس کے بعد وہ میرے پاس آئی اور یہ بات مجھے بتائی ۔ کہا : تو میں نے اس پر برہمی کا اظہار کیا ، اور کہا : اللہ کی قسم! پھر ایسا نہیں ہو سکتا ۔ رسول اللہ صلی اللہ علیہ وسلم نے یہ بات سنی تو مجھ سے پوچھا ، میں نے آپ کو ( پوری ) بات بتائی تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" اسے خریدو اور آزاد کر دو ، ان کے لیے ولاء کی شرط رکھ لو ، کیونکہ ( اصل میں تو ) ولاء کا حق اسی کا ہے جس نے آزاد کیا ۔ \" میں نے ایسا ہی کیا ۔ کہا : پھر رسول اللہ صلی اللہ علیہ وسلم نے شام کے وقت خطبہ دیا ، اللہ کی حمد و ثنا جو اس کے شایانِ شان تھی بیان کی ، پھر فرمایا : \" امابعد! لوگوں کو کیا ہوا ہے؟ وہ ایسی شرطیں رکھتے ہیں جو اللہ کی کتاب میں ( جائز ) نہیں ۔ جو بھی شرط اللہ کی کتاب میں ( روا ) نہیں ، وہ باطل ہے ، چاہے وہ سو شرطیں ہوں ، اللہ کی کتاب ہی سب سے سچی اور اللہ کی شرط سب سے مضبوط ہے ۔ تم میں سے بعض لوگوں کو کیا ہوا ہے ، ان میں سے کوئی کہتا ہے : فلاں کو آزاد تم کرو اور حقِ ولاء میرا ہو گا ۔ ( حالانکہ ) ولاء کا حق اسی کا ہے جس نے آزاد کیا","",{"u2":"ابواسامہ نے کہا: ہمیں ہشام بن عروہ نے حدیث بیان کی، انہوں نے کہا: مجھے میرے والد نے سیدہ عائشہ رضی اللہ عنہا سے خبر دی، انہوں نے کہا: بریرہ میرے پاس آئی اور کہنے لگی: میرے مالکوں نے میرے ساتھ 9 سالوں میں 9 اوقیہ (کی ادائیگی) کے بدلے مکاتبت کی ہے۔ ہر سال میں ایک اوقیہ (ادا کرنا) ہے۔ میری مدد کریں۔ میں نے اس سے کہا: اگر تمہارے مالک چاہیں کہ میں انہیں یکمشت گن کر دوں اور تمہیں آزاد کر دوں اور ولاء کا حق میرا ہو، تو میں ایسا کر لوں گی۔ اس نے یہ بات اپنے مالکوں سے کی تو انہوں نے (اسے ماننے سے) انکار کر دیا الا یہ کہ حقِ ولاء ان کا ہو۔ اس کے بعد وہ میرے پاس آئی اور یہ بات مجھے بتائی۔ کہا: تو میں نے اس پر برہمی کا اظہار کیا، اور کہا: اللہ کی قسم! پھر ایسا نہیں ہو سکتا۔ رسول اللہ صلی اللہ علیہ وسلم نے یہ بات سنی تو مجھ سے پوچھا، میں نے آپ کو (پوری) بات بتائی تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے خریدو اور آزاد کر دو، ان کے لیے ولاء کی شرط رکھ لو، کیونکہ (اصل میں تو) ولاء کا حق اسی کا ہے جس نے آزاد کیا۔\" میں نے ایسا ہی کیا۔ کہا: پھر رسول اللہ صلی اللہ علیہ وسلم نے شام کے وقت خطبہ دیا، اللہ کی حمد و ثنا جو اس کے شایانِ شان تھی بیان کی، پھر فرمایا: \"امابعد! لوگوں کو کیا ہوا ہے؟ وہ ایسی شرطیں رکھتے ہیں جو اللہ کی کتاب میں (جائز) نہیں۔ جو بھی شرط اللہ کی کتاب میں (روا) نہیں، وہ باطل ہے، چاہے وہ سو شرطیں ہوں، اللہ کی کتاب ہی سب سے سچی اور اللہ کی شرط سب سے مضبوط ہے۔ تم میں سے بعض لوگوں کو کیا ہوا ہے، ان میں سے کوئی کہتا ہے: فلاں کو آزاد تم کرو اور حقِ ولاء میرا ہو گا۔ (حالانکہ) ولاء کا حق اسی کا ہے جس نے آزاد کیا"}],[3747,"ابن نمیر ، وکیع اور جریر سب نے ہشام بن عروہ سے اسی سند کے ساتھ ابواسامہ کی حدیث کے ہم معنی روایت بیان کی ، لیکن جریر کی حدیث میں ہے ، کہا : اس ( بریرہ رضی اللہ عنہا ) کا شوہر غلام تھا ، رسول اللہ صلی اللہ علیہ وسلم نے اسے ( شادی برقرار رکھنے یا نہ رکھنے کے بارے میں ) اختیار دیا تو اس نے خود کو ( نکاح کی بندش سے آزاد دیکھنا ) پسند کیا ۔ اگر اس کا شوہر آزاد ہوتا تو آپ اسے یہ اختیار نہ دیتے ، اور ان کی حدیث میں امابعد کے الفاظ نہیں ہیں ۔ ( یہ الفاظ خطبے کی طرف اشارہ کرتے ہیں)","",{"u2":"ابن نمیر، وکیع اور جریر سب نے ہشام بن عروہ سے اسی سند کے ساتھ ابواسامہ کی حدیث کے ہم معنی روایت بیان کی، لیکن جریر کی حدیث میں ہے، کہا: اس (بریرہ رضی اللہ عنہا) کا شوہر غلام تھا، رسول اللہ صلی اللہ علیہ وسلم نے اسے (شادی برقرار رکھنے یا نہ رکھنے کے بارے میں) اختیار دیا تو اس نے خود کو (نکاح کی بندش سے آزاد دیکھنا) پسند کیا۔ اگر اس کا شوہر آزاد ہوتا تو آپ اسے یہ اختیار نہ دیتے، اور ان کی حدیث میں امابعد کے الفاظ نہیں ہیں۔ (یہ الفاظ خطبے کی طرف اشارہ کرتے ہیں"}],[3748,"ہشام بن عروہ نے ہمیں عبدالرحمٰن بن قاسم سے حدیث بیان کی ، انہوں نے اپنے والد سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، کہا : بریرہ رضی اللہ عنہا کے معاملے میں تین فیصلے ہوئے : اس کے مالکوں نے چاہا کہ اسے بیچ دیں اور اس کے حقِ ولاء کو ( اپنے لیے ) مشروط کر دیں ، میں نے یہ بات رسول اللہ صلی اللہ علیہ وسلم کو بتائی تو آپ نے فرمایا : \" اسے خریدو اور آزاد کر دو ، کیونکہ ولاء اسی کا حق ہے جس نے آزاد کیا ۔ \" ( عائشہ رضی اللہ عنہا نے ) کہا : وہ آزاد ہوئی تو رسول اللہ صلی اللہ علیہ وسلم نے اسے اختیار دیا ، اس نے اپنی ذات ( کو آزاد رکھنے ) کا انتخاب کیا ۔ ( سیدہ عائشہ نے ) کہا : لوگ اس پر صدقہ کرتے تھے اور وہ ( اس میں سے کچھ ) ہمیں ہدیہ کرتی تھی ، میں نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے عرض کی تو آپ نے فرمایا : \" وہ اس پر صدقہ ہے اور تم لوگوں کے لیے ہدیہ ہے ، لہٰذا اسے کھا لیا کرو","",{"u2":"ہشام بن عروہ نے ہمیں عبدالرحمٰن بن قاسم سے حدیث بیان کی، انہوں نے اپنے والد سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، کہا: بریرہ رضی اللہ عنہا کے معاملے میں تین فیصلے ہوئے: اس کے مالکوں نے چاہا کہ اسے بیچ دیں اور اس کے حقِ ولاء کو (اپنے لیے) مشروط کر دیں، میں نے یہ بات رسول اللہ صلی اللہ علیہ وسلم کو بتائی تو آپ نے فرمایا: \"اسے خریدو اور آزاد کر دو، کیونکہ ولاء اسی کا حق ہے جس نے آزاد کیا۔\" (عائشہ رضی اللہ عنہا نے) کہا: وہ آزاد ہوئی تو رسول اللہ صلی اللہ علیہ وسلم نے اسے اختیار دیا، اس نے اپنی ذات (کو آزاد رکھنے) کا انتخاب کیا۔ (حضرت عائشہ نے) کہا: لوگ اس پر صدقہ کرتے تھے اور وہ (اس میں سے کچھ) ہمیں ہدیہ کرتی تھی، میں نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے عرض کی تو آپ نے فرمایا: \"وہ اس پر صدقہ ہے اور تم لوگوں کے لیے ہدیہ ہے، لہذا اسے کھا لیا کرو"}],[3749,"سماک نے عبدالرحمٰن بن قاسم سے ، انہوں نے اپنے والد سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ انہوں نے بریرہ رضی اللہ عنہ کو انصار کے لوگوں سے خریدا ، انہوں نے ولاء کی شرط لگائی ، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ولاء ( کا حق ) اسی کے لیے ہے جس نے ( آزادی کی ) نعمت کا اہتمام کیا ۔ \" اور رسول اللہ صلی اللہ علیہ وسلم نے اسے اختیار دیا جبکہ اس کا شوہر غلام تھا ۔ اور اس نے سیدہ عائشہ رضی اللہ عنہا کو گوشت ہدیہ کیا ، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اگر تم ہمارے لیے اس گوشت سے ( سالن ) تیار کرتیں؟ \" سیدہ عائشہ نے کہا : یہ ( گوشت ) بریرہ پر صدقہ کیا گیا تھا تو آپ نے فرمایا : \" وہ اس کے لیے صدقہ تھا اور ہمارے لیے ہدیہ ہے","",{"u2":"سماک نے عبدالرحمٰن بن قاسم سے، انہوں نے اپنے والد سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ انہوں نے بریرہ رضی اللہ عنہ کو انصار کے لوگوں سے خریدا، انہوں نے ولاء کی شرط لگائی، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ولاء (کا حق) اسی کے لیے ہے جس نے (آزادی کی) نعمت کا اہتمام کیا۔\" اور رسول اللہ صلی اللہ علیہ وسلم نے اسے اختیار دیا جبکہ اس کا شوہر غلام تھا۔ اور اس نے سیدہ عائشہ رضی اللہ عنہا کو گوشت ہدیہ کیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم ہمارے لیے اس گوشت سے (سالن) تیار کرتیں؟\" حضرت عائشہ نے کہا: یہ (گوشت) بریرہ پر صدقہ کیا گیا تھا تو آپ نے فرمایا: \"وہ اس کے لیے صدقہ تھا اور ہمارے لیے ہدیہ ہے"}],[3750,"ہمیں محمد بن جعفر نے حدیث بیان کی ، کہا : ہمیں شعبہ نے حدیث بیان کی ، انہوں نے کہا : میں نے عبدالرحمٰن بن قاسم سے سنا ، انہوں نے کہا : میں نے قاسم سے سنا ، وہ سیدہ عائشہ رضی اللہ عنہا سے حدیث بیان کر رہے تھے کہ انہوں نے بریرہ رضی اللہ عنہا کو آزاد کرنے کے لیے خریدنا چاہا تو ان لوگوں ( مالکوں ) نے اس کی ولاء کی شرط لگا دی ۔ عائشہ رضی اللہ عنہا نے اس بات کا تذکرہ رسول اللہ صلی اللہ علیہ وسلم سے کیا ، تو آپ نے فرمایا : \" اسے خریدو اور آزاد کر دو کیونکہ ولاء اسی کے لیے ہے جس نے آزاد کیا ۔ \" رسول اللہ صلی اللہ علیہ وسلم کے لیے ( بریرہ رضی اللہ عنہا کی طرف سے ) گوشت کا ہدیہ بھیجا گیا تو انہوں ( گھر والوں ) نے نبی صلی اللہ علیہ وسلم سے عرض کی : یہ بریرہ پر صدقہ کیا گیا ہے ، آپ نے فرمایا : \" وہ اس کے لیے صدقہ ہے اور ہمارے لیے ہدیہ ہے ۔ \" اور اسے اختیار دیا گیا ۔ عبدالرحمٰن نے کہا : اس کا شوہر آزاد تھا ۔ شعبہ نے کہا : میں نے پھر سے اس کے شوہر کے بارے میں ان سے پوچھا تو انہوں نے کہا : میں نہیں جانتا ( وہ آزاد تھا یا غلام ۔ شک کے بغیر ، یقین کے ساتھ کی گئی روایت یہی ہے کہ وہ غلام تھا)","",{"u2":"ہمیں محمد بن جعفر نے حدیث بیان کی، کہا: ہمیں شعبہ نے حدیث بیان کی، انہوں نے کہا: میں نے عبدالرحمٰن بن قاسم سے سنا، انہوں نے کہا: میں نے قاسم سے سنا، وہ سیدہ عائشہ رضی اللہ عنہا سے حدیث بیان کر رہے تھے کہ انہوں نے بریرہ رضی اللہ عنہا کو آزاد کرنے کے لیے خریدنا چاہا تو ان لوگوں (مالکوں) نے اس کی ولاء کی شرط لگا دی۔ عائشہ رضی اللہ عنہا نے اس بات کا تذکرہ رسول اللہ صلی اللہ علیہ وسلم سے کیا، تو آپ نے فرمایا: \"اسے خریدو اور آزاد کر دو کیونکہ ولاء اسی کے لیے ہے جس نے آزاد کیا۔\" رسول اللہ صلی اللہ علیہ وسلم کے لیے (بریرہ رضی اللہ عنہا کی طرف سے) گوشت کا ہدیہ بھیجا گیا تو انہوں (گھر والوں) نے نبی صلی اللہ علیہ وسلم سے عرض کی: یہ بریرہ پر صدقہ کیا گیا ہے، آپ نے فرمایا: \"وہ اس کے لیے صدقہ ہے اور ہمارے لیے ہدیہ ہے۔\" اور اسے اختیار دیا گیا۔ عبدالرحمٰن نے کہا: اس کا شوہر آزاد تھا۔ شعبہ نے کہا: میں نے پھر سے اس کے شوہر کے بارے میں ان سے پوچھا تو انہوں نے کہا: میں نہیں جانتا (وہ آزاد تھا یا غلام۔ شک کے بغیر، یقین کے ساتھ کی گئی روایت یہی ہے کہ وہ غلام تھا"}],[3751,"ابوداؤد نے ہمیں حدیث بیان کی ، ( کہا : ) ہمیں شعبہ نے اسی سند سے اسی کے ہم معنی حدیث بیان کی","",{"u2":"ابوداؤد نے ہمیں حدیث بیان کی، (کہا:) ہمیں شعبہ نے اسی سند سے اسی کے ہم معنی حدیث بیان کی"}],[3752,"عروہ نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : بریرہ رضی اللہ عنہا کا شوہر غلام تھا","",{"u2":"عروہ نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: بریرہ رضی اللہ عنہا کا شوہر غلام تھا"}],[3753,"ربیعہ بن ابوعبدالرحمٰن نے قاسم بن محمد سے ، انہوں نے نبی صلی اللہ علیہ وسلم کی اہلیہ سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ انہوں نے کہا : بریرہ رضی اللہ عنہا کے معاملے میں تین سنتیں ( متعین ) ہوئیں : جب وہ آزاد ہوئی تو اس کے شوہر کے حوالے سے اسے اختیار دیا گیا ۔ اسے گوشت کا ہدیہ بھیجا گیا ، رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے تو ہنڈیا چولھے پر تھی ، آپ نے کھانا طلب فرمایا تو آپ کو روٹی اور گھر کے سالنوں میں سے ایک سالن پیش کیا گیا ، آپ نے فرمایا : \" کیا میں نے آگ پر چڑھی ہنڈیا نہیں دیکھی جس میں گوشت تھا؟ \" گھر والوں نے جواب دیا : کیوں نہیں ، اللہ کے رسول! وہ گوشت بریرہ رضی اللہ عنہا پر صدقہ کیا گیا تھا تو ہمیں اچھا نہ لگا کہ ہم آپ کو اس میں سے کھلائیں ۔ آپ صلی اللہ علیہ وسلم نے فرایا : \" وہ اس پر صدقہ ہے اور اس کی طرف سے ہمارے لیے ہدیہ ہے ۔ \" نبی صلی اللہ علیہ وسلم نے اسی ( بریرہ رضی اللہ عنہا ) کے بارے میں فرمایا تھا : \" حقِ ولاء اسی کے لیے ہے جس نے آزاد کیا","",{"u2":"ربیعہ بن ابوعبدالرحمٰن نے قاسم بن محمد سے، انہوں نے نبی صلی اللہ علیہ وسلم کی اہلیہ سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ انہوں نے کہا: بریرہ رضی اللہ عنہا کے معاملے میں تین سنتیں (متعین) ہوئیں: جب وہ آزاد ہوئی تو اس کے شوہر کے حوالے سے اسے اختیار دیا گیا۔ اسے گوشت کا ہدیہ بھیجا گیا، رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے تو ہنڈیا چولھے پر تھی، آپ نے کھانا طلب فرمایا تو آپ کو روٹی اور گھر کے سالنوں میں سے ایک سالن پیش کیا گیا، آپ نے فرمایا: \"کیا میں نے آگ پر چڑھی ہنڈیا نہیں دیکھی جس میں گوشت تھا؟\" گھر والوں نے جواب دیا: کیوں نہیں، اللہ کے رسول! وہ گوشت بریرہ رضی اللہ عنہا پر صدقہ کیا گیا تھا تو ہمیں اچھا نہ لگا کہ ہم آپ کو اس میں سے کھلائیں۔ آپ صلی اللہ علیہ وسلم نے فرایا: \" وہ اس پر صدقہ ہے اور اس کی طرف سے ہمارے لیے ہدیہ ہے۔\" نبی صلی اللہ علیہ وسلم نے اسی (بریرہ رضی اللہ عنہا) کے بارے میں فرمایا تھا: \"حقِ ولاء اسی کے لیے ہے جس نے آزاد کیا"}],[3754,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : سیدہ عائشہ رضی اللہ عنہا نے چاہا کہ ایک لونڈی خرید کر آزاد کریں تو اس کے مالکوں نے ( اسے بیچنے سے ) انکار کیا ، الا یہ کہ حقِ ولاء ان کا ہو ۔ سیدہ عائشہ رضی اللہ عنہا نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے عرض کی تو آپ نے فرمایا : \" یہ شرط تمہیں ( نیکی سے ) نہ روکے ، کیونکہ حق ولاء اسی کا ہے جس نے آزاد کیا","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: سیدہ عائشہ رضی اللہ عنہا نے چاہا کہ ایک لونڈی خرید کر آزاد کریں تو اس کے مالکوں نے (اسے بیچنے سے) انکار کیا، الا یہ کہ حقِ ولاء ان کا ہو۔ سیدہ عائشہ رضی اللہ عنہا نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے عرض کی تو آپ نے فرمایا: \"یہ شرط تمہیں (نیکی سے) نہ روکے، کیونکہ حق ولاء اسی کا ہے جس نے آزاد کیا"}],[3755,"سلیمان بن بلال نے ہمیں عبداللہ بن دینار سے خبر دی ، انہوں نے ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ولاء کو بیچنے اور ہبہ کرنے سے منع فرمایا ۔ ابراہیم نے کہا : میں نے مسلم بن حجاج کو یہ کہتے ہوئے سنا : اس حدیث میں تمام لوگ عبداللہ بن دینار ہی پر انحصار کرنے والے ہیں ۔ ( سب سندیں انہیں پر آ کر مل جاتی ہیں)","",{"u2":"سلیمان بن بلال نے ہمیں عبداللہ بن دینار سے خبر دی، انہوں نے ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ولاء کو بیچنے اور ہبہ کرنے سے منع فرمایا۔\nابراہیم نے کہا: میں نے مسلم بن حجاج کو یہ کہتے ہوئے سنا: اس حدیث میں تمام لوگ عبداللہ بن دینار ہی پر انحصار کرنے والے ہیں۔ (سب سندیں انہیں پر آ کر مل جاتی ہیں"}],[3756,"ابن عیینہ ، اسماعیل بن جعفر ، سفیان ثوری ، شعبہ ، عبیداللہ اور ضحاک بن عثمان سب نے عبداللہ بن دینار سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ، الا یہ کہ عبیداللہ سے ( عبدالوہاب ) ثقفی کی روایت کردہ حدیث میں صرف خرید و فروخت کا ذکر ہے ، انہوں نے ہبہ کا ذکر نہیں کیا","",{"u2":"ابن عیینہ، اسماعیل بن جعفر، سفیان ثوری، شعبہ، عبیداللہ اور ضحاک بن عثمان سب نے عبداللہ بن دینار سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی، الا یہ کہ عبیداللہ سے (عبدالوہاب) ثقفی کی روایت کردہ حدیث میں صرف خرید و فروخت کا ذکر ہے، انہوں نے ہبہ کا ذکر نہیں کیا"}],[3757,"سیدنا جابر بن عبداللہ رضی اللہ عنہ کہتے ہیں : نبی صلی اللہ علیہ وسلم نے ( میثاقِ مدینہ میں ) دیتوں ( عقول ) کی ادائیگی قبیلے کی ہر شاخ پر لازم ٹھہرائی ، پھر آپ نے لکھا : \" کسی مسلمان کے لیے جائز نہیں کہ کسی ( اور ) مسلمان کی اجازت کے بغیر اس کے ( مولیٰ ) غلام کو اپنا مولیٰ ( حقِ ولاء رکھنے والا ) بنا لے ۔ \" پھر مجھے خبر دی گئی کہ آپ نے ، اپنے صحیفے میں ، اس شخص پر جو یہ کام کرے ، لعنت بھیجی","",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ کہتے ہیں: نبی صلی اللہ علیہ وسلم نے (میثاقِ مدینہ میں) دیتوں (عقول) کی ادائیگی قبیلے کی ہر شاخ پر لازم ٹھہرائی، پھر آپ نے لکھا: \"کسی مسلمان کے لیے جائز نہیں کہ کسی (اور) مسلمان کی اجازت کے بغیر اس کے (مولیٰ) غلام کو اپنا مولیٰ (حقِ ولاء رکھنے والا) بنا لے۔\" پھر مجھے خبر دی گئی کہ آپ نے، اپنے صحیفے میں، اس شخص پر جو یہ کام کرے، لعنت بھیجی"}],[3758,"سہیل نے اپنے والد ( صالح سمان ) سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : : جس نے اپنے آزاد کرنے والوں کی اجازت کے بغیر کسی ( دوسری ) قوم کی ولاء اختیار کی ، اس پر اللہ کی اور فرشتوں کی لعنت ہے ۔ اور ( قیامت کے روز ) اس سے کوئی سفارش قبول کی جائے گی نہ فدیہ","",{"u2":"سہیل نے اپنے والد (صالح سمان) سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا::جس نے اپنے آزاد کرنے والوں کی اجازت کے بغیر کسی (دوسری) قوم کی ولاء اختیار کی، اس پر اللہ کی اور فرشتوں کی لعنت ہے۔ اور (قیامت کے روز) اس سے کوئی سفارش قبول کی جائے گی نہ فدیہ"}],[3759,"زائدہ نے سلیمان ( اعمش ) سے ، انہوں نے ابوصالح سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" جس نے اپنے آزاد کرنے والوں کی اجازت کے بغیر کسی ( دوسری ) قوم کی ولاء اختیار کی ، اس پر اللہ کی ، فرشتوں کی اور سب لوگوں کی لعنت ہے ، اور قیامت کے دن اس سے کوئی فدیہ قبول کیا جائے گا نہ کوئی سفارش","",{"u2":"زائدہ نے سلیمان (اعمش) سے، انہوں نے ابوصالح سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"جس نے اپنے آزاد کرنے والوں کی اجازت کے بغیر کسی (دوسری) قوم کی ولاء اختیار کی، اس پر اللہ کی، فرشتوں کی اور سب لوگوں کی لعنت ہے، اور قیامت کے دن اس سے کوئی فدیہ قبول کیا جائے گا نہ کوئی سفارش"}],[3760,"زائدہ نے سلیمان ( اعمش ) سے ، انہوں نے ابوصالح سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" جس نے اپنے آزاد کرنے والوں کی اجازت کے بغیر کسی ( دوسری ) قوم کی ولاء اختیار کی ، اس پر اللہ کی ، فرشتوں کی اور سب لوگوں کی لعنت ہے ، اور قیامت کے دن اس سے کوئی فدیہ قبول کیا جائے گا نہ کوئی سفارش","",{"u2":"شیبان نے اعمش سے اسی سند کے ساتھ حدیث بیان کی، البتہ انہوں نے کہا: \"جس نے اپنے آزاد کرنے والوں کے سوا، ان کی اجازت کے بغیر کسی اور کے ساتھ موالات کی"}],[3761,"ابراہیم تیمی کے والد یزید بن شریک سے روایت ہے ، انہوں نے کہا : سیدنا علی بن ابی طالب رضی اللہ عنہ نے ہمیں خطبہ دیا اور کہا : جس کا گمان ہے کہ ہمارے پاس کتاب اللہ اور اس صحیفے کے سوا ۔ ۔ ۔ کہا : وہ صحیفہ ان کی تلوار کی نیام سے لٹکا ہوا تھا ۔ ۔ کوئی اور چیز ہے جسے ہم پڑھتے ہیں تو وہ جھوٹا ہے ۔ اس میں ( دیت وغیرہ کے ) اونٹوں کی عمریں اور زخموں ( کی دیت ) سے متعلقہ کچھ چیزیں ( لکھی ہوئی ) ہیں ۔ اور اس میں ( یہ لکھا ہوا ہے کہ ) نبی صلی اللہ علیہ وسلم نے فرمایا : \" جبل عیر سے لے کر جبل ثور تک مدینہ حرم ہے ، جس نے اس میں ( گمراہی پھیلانے کی ) کوئی واردات کی یا واردات کرنے والے کسی شخص کو پناہ دی تو اس پر اللہ کی ، فرشتوں کی اور سب لوگوں کی لعنت ہے ، قیامت کے دن اللہ تعالیٰ اس سے کوئی سفارش قبول کرے گا نہ بدلہ ۔ تمام مسلمانوں کی پناہ ایک ہے ۔ ان کا ادنی آدمی بھی کسی کو پناہ دے سکتا ہے ۔ جس نے اپنے والد کے سوا کسی کی طرف نسبت کی یا ( کوئی غلام ) اپنے آزاد کرنے والے مالکوں کے سوا کسی اور کا مولیٰ بنا ، اس پر اللہ کی ، فرشتوں کی اور سب لوگوں کی لعنت ہے ، قیامت کے دن اللہ تعالیٰ اس سے کوئی سفارش قبول کرے گا نہ فدیہ","",{"u2":"ابراہیم تیمی کے والد یزید بن شریک سے روایت ہے، انہوں نے کہا: سیدنا علی بن ابی طالب رضی اللہ عنہ نے ہمیں خطبہ دیا اور کہا: جس کا گمان ہے کہ ہمارے پاس کتاب اللہ اور اس صحیفے کے سوا۔۔۔ کہا: وہ صحیفہ ان کی تلوار کی نیام سے لٹکا ہوا تھا۔۔ کوئی اور چیز ہے جسے ہم پڑھتے ہیں تو وہ جھوٹا ہے۔ اس میں (دیت وغیرہ کے) اونٹوں کی عمریں اور زخموں (کی دیت) سے متعلقہ کچھ چیزیں (لکھی ہوئی) ہیں۔ اور اس میں (یہ لکھا ہوا ہے کہ) نبی صلی اللہ علیہ وسلم نے فرمایا: \"جبل عیر سے لے کر جبل ثور تک مدینہ حرم ہے، جس نے اس میں (گمراہی پھیلانے کی) کوئی واردات کی یا واردات کرنے والے کسی شخص کو پناہ دی تو اس پر اللہ کی، فرشتوں کی اور سب لوگوں کی لعنت ہے، قیامت کے دن اللہ تعالیٰ اس سے کوئی سفارش قبول کرے گا نہ بدلہ۔ تمام مسلمانوں کی پناہ ایک ہے۔ ان کا ادنی آدمی بھی کسی کو پناہ دے سکتا ہے۔ جس نے اپنے والد کے سوا کسی کی طرف نسبت کی یا (کوئی غلام) اپنے آزاد کرنے والے مالکوں کے سوا کسی اور کا مولیٰ بنا، اس پر اللہ کی، فرشتوں کی اور سب لوگوں کی لعنت ہے، قیامت کے دن اللہ تعالیٰ اس سے کوئی سفارش قبول کرے گا نہ فدیہ"}],[3762,"اسماعیل بن ابی حکیم نے مجھے سعید بن مرجانہ سے حدیث بیان کی ، انہوں نے ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے کسی مومن گردن ( مومن غلام جس کی گردن میں غلامی کا طوق تھا ) کو آزاد کیا ، اللہ تعالیٰ اس ( آزاد کیے جانے والے ) کے ہر عضو کے بدلے اس ( آزاد کرنے والے ) کا وہی عضو آگ سے آزاد فرمائے گا","",{"u2":"اسماعیل بن ابی حکیم نے مجھے سعید بن مرجانہ سے حدیث بیان کی، انہوں نے ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کسی مومن گردن (مومن غلام جس کی گردن میں غلامی کا طوق تھا) کو آزاد کیا، اللہ تعالیٰ اس (آزاد کیے جانے والے) کے ہر عضو کے بدلے اس (آزاد کرنے والے) کا وہی عضو آگ سے آزاد فرمائے گا"}],[3763,"علی بن حسین نے سعید بن مرجانہ سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" جس نے کسی مومن گردن کو آزاد کیا تو اللہ تعالیٰ اس کے ہر عضو کے بدلے اس ( آزاد کرنے والے ) کے اعضاء میں سے وہی عضو آگ سے آزاد فرمائے گا حتی کہ اس کی شرمگاہ کے بدلے اس کی شرمگاہ کو بھی","",{"u2":"علی بن حسین نے سعید بن مرجانہ سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"جس نے کسی مومن گردن کو آزاد کیا تو اللہ تعالیٰ اس کے ہر عضو کے بدلے اس (آزاد کرنے والے) کے اعضاء میں سے وہی عضو آگ سے آزاد فرمائے گا حتی کہ اس کی شرمگاہ کے بدلے اس کی شرمگاہ کو بھی"}],[3764,"عمر بن ( زین العابدین ) علی بن حسین ( بن علی بن ابی طالب ) نے سعید بن مرجانہ سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : \" جس نے کسی مومن گردن کو آزاد کیا ، اللہ تعالیٰ اس کے ہر عضو کے بدلے ( اس آزاد کرنے والے کا ہی ) عضو آگ سے آزاد کرے گا ، حتی کہ اس کی شرمگاہ کے بدلے اس کی شرمگاہ کو بھی آزاد کر دے گا","",{"u2":"عمر بن (زین العابدین) علی بن حسین (بن علی بن ابی طالب) نے سعید بن مرجانہ سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: \"جس نے کسی مومن گردن کو آزاد کیا، اللہ تعالیٰ اس کے ہر عضو کے بدلے (اس آزاد کرنے والے کا ہی) عضو آگ سے آزاد کرے گا، حتی کہ اس کی شرمگاہ کے بدلے اس کی شرمگاہ کو بھی آزاد کر دے گا"}],[3765,"واقد بن محمد نے ہمیں حدیث بیان کی ، ( کہا : ) مجھے علی بن حسین ( بن علی بن ابی طالب ) کے ساتھی ( شاگرد ) سعید بن مرجانہ نے حدیث بیان کی ، انہوں نے کہا : میں نے سیدنا ابوہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس مسلمان نے کسی مسلمان کو آزاد کیا ، تو اللہ تعالیٰ اس کے ( آزاد کیے جانے والے ) ہر عضو کے بدلے اس کا وہی عضو آگ سے بچا لے گا ۔ \" ( سعید بن مرجانہ نے ) کہا : جب میں نے ابوہریرہ رضی اللہ عنہ سے یہ حدیث سنی تو میں نکلا اور علی بن حسین کے سامنے اس کا تذکرہ کیا تو انہوں نے اپنا وہ غلام آزاد کر دیا جس ( کو خریدنے ) کے لیے ( عبداللہ ) ابن جعفر نے انہیں دس ہزار درہم یا ایک ہزار دینار دینے کی پیش کش کی تھی","",{"u2":"واقد بن محمد نے ہمیں حدیث بیان کی، (کہا:) مجھے علی بن حسین (بن علی بن ابی طالب) کے ساتھی (شاگرد) سعید بن مرجانہ نے حدیث بیان کی، انہوں نے کہا: میں نے سیدنا ابوہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس مسلمان نے کسی مسلمان کو آزاد کیا، تو اللہ تعالیٰ اس کے (آزاد کیے جانے والے) ہر عضو کے بدلے اس کا وہی عضو آگ سے بچا لے گا۔\" (سعید بن مرجانہ نے) کہا: جب میں نے ابوہریرہ رضی اللہ عنہ سے یہ حدیث سنی تو میں نکلا اور علی بن حسین کے سامنے اس کا تذکرہ کیا تو انہوں نے اپنا وہ غلام آزاد کر دیا جس (کو خریدنے) کے لیے (عبداللہ) ابن جعفر نے انہیں دس ہزار درہم یا ایک ہزار دینار دینے کی پیش کش کی تھی"}],[3766,"ابوبکر بن ابی شیبہ اور زہیر بن حرب نے کہا : ہمیں جرید نے سہیل سے حدیث بیان کی ، انہوں نے اپنے والد ( ابو صالح سمان ) سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی بیٹا والد کا حق ادا نہیں کر سکتا ، الا یہ کہ اسے غلام پائے ، اسے خریدے اور آزاد کر دے ۔ \" ابن ابی شیبہ کی روایت میں : \" کوئی بیٹا اپنے والد کا \" کے الفاظ ہیں","",{"u2":"ابوبکر بن ابی شیبہ اور زہیر بن حرب نے کہا: ہمیں جرید نے سہیل سے حدیث بیان کی، انہوں نے اپنے والد (ابو صالح سمان) سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی بیٹا والد کا حق ادا نہیں کر سکتا، الا یہ کہ اسے غلام پائے، اسے خریدے اور آزاد کر دے۔\" ابن ابی شیبہ کی روایت میں: \"کوئی بیٹا اپنے والد کا\" کے الفاظ ہیں"}],[3767,"وکیع ، عبداللہ بن نمیر اور ابو احمد زبیری سب نے سفیان سے ، انہوں نے سہیل سے اسی سند کے ساتھ اسی کے مانند روایت کی اور ان سب نے بھی \" کوئی بیٹا اپنے والد کا \" کے الفاظ کہے","",{"u2":"وکیع، عبداللہ بن نمیر اور ابو احمد زبیری سب نے سفیان سے، انہوں نے سہیل سے اسی سند کے ساتھ اسی کے مانند روایت کی اور ان سب نے بھی \"کوئی بیٹا اپنے والد کا\" کے الفاظ کہے"}],[3768,"محمد بن یحییٰ بن حبان نے اعرج سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ملامسہ اور منابذہ کی بیعوں سے منع فرمایا","",{"u2":"محمد بن یحییٰ بن حبان نے اعرج سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ملامسہ اور منابذہ کی بیعوں سے منع فرمایا"}],[3769,"ابوزناد نے اعرج سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی","",{"u2":"ابوزناد نے اعرج سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی"}],[3770,"حفص بن عاصم نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی","",{"u2":"حفص بن عاصم نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی"}],[3771,"ابوصالح نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی","",{"u2":"ابوصالح نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی"}],[3772,"عمرو بن دینار نے عطاء بن میناء سے روایت کی کہ انہوں نے ان ( عطاء ) کو سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کرتے ہوئے سنا ، انہوں نے کہا : دو قسم کی بیعوں ( یعنی ) ملامسہ اور منابذہ سے منع کیا گیا ہے ۔ ملامسہ یہ ہے کہ دونوں ( بیچنے والے اور خریدنے والے ) میں سے ہر ایک بغیر سوچے ( اور غور کیے ) اپنے ساتھی کے کپڑے کو چھوئے ، اور منابذہ یہ ہے کہ دونوں میں سے ہر ایک اپنا کپڑا دوسرے کی طرف پھینکے اور کسی نے بھی اپنے ساتھی کے کپڑے کو ( جس کے ساتھ اس کے کپڑے کا تبادلہ ہو رہا ہے ) نہ دیکھا ہو ۔ ( اور اسی سے بیع کی تکمیل ہو جائے)","",{"u2":"عمرو بن دینار نے عطاء بن میناء سے روایت کی کہ انہوں نے ان (عطاء) کو سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کرتے ہوئے سنا، انہوں نے کہا: دو قسم کی بیعوں (یعنی) ملامسہ اور منابذہ سے منع کیا گیا ہے۔ ملامسہ یہ ہے کہ دونوں (بیچنے والے اور خریدنے والے) میں سے ہر ایک بغیر سوچے (اور غور کیے) اپنے ساتھی کے کپڑے کو چھوئے، اور منابذہ یہ ہے کہ دونوں میں سے ہر ایک اپنا کپڑا دوسرے کی طرف پھینکے اور کسی نے بھی اپنے ساتھی کے کپڑے کو (جس کے ساتھ اس کے کپڑے کا تبادلہ ہو رہا ہے) نہ دیکھا ہو۔ (اور اسی سے بیع کی تکمیل ہو جائے"}],[3773,"یونس نے مجھے ابن شہاب سے خبر دی ، انہوں نے کہا : مجھے عامر بن سعد بن ابی وقاص نے بتایا کہ سیدنا ابوسعید خدری رضی اللہ عنہ نے کہا : اللہ کے رسول صلی اللہ علیہ وسلم نے ہمیں دو قسم کی بیعوں اور دو قسم کے پہناووں سے منع فرمایا : بیع میں آپ نے ملامسہ اور منابذہ سے منع فرمایا ۔ ملامسہ یہ ہے کہ کوئی آدمی دوسرے کے کپڑے کو دن میں یا رات میں اپنے ہاتھ سے چھوئے اور اس کے علاوہ اسے الٹ کر بھی نہ دیکھے ۔ اور منابذہ یہ ہے کہ کوئی آدمی دوسرے آدمی کی طرف اپنا کپڑا پھینکے اور دوسرا اس کی طرف اپنا کپڑا پھینکے اور بغیر دیکھے اور ( بغیر حقیقی ) رضامندی کے یہی ان کی بیع ہو","",{"u2":"یونس نے مجھے ابن شہاب سے خبر دی، انہوں نے کہا: مجھے عامر بن سعد بن ابی وقاص نے بتایا کہ سیدنا ابوسعید خدری رضی اللہ عنہ نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم نے ہمیں دو قسم کی بیعوں اور دو قسم کے پہناووں سے منع فرمایا: بیع میں آپ نے ملامسہ اور منابذہ سے منع فرمایا۔ ملامسہ یہ ہے کہ کوئی آدمی دوسرے کے کپڑے کو دن میں یا رات میں اپنے ہاتھ سے چھوئے اور اس کے علاوہ اسے الٹ کر بھی نہ دیکھے۔ اور منابذہ یہ ہے کہ کوئی آدمی دوسرے آدمی کی طرف اپنا کپڑا پھینکے اور دوسرا اس کی طرف اپنا کپڑا پھینکے اور بغیر دیکھے اور (بغیر حقیقی) رضامندی کے یہی ان کی بیع ہو"}],[3774,"صالح نے ابن شہاب سے اسی سند کے ساتھ یہی حدیث بیان کی","",{"u2":"صالح نے ابن شہاب سے اسی سند کے ساتھ یہی حدیث بیان کی"}],[3775,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے کنکر پھینک کر بیع کرنے اور دھوکے والی بیع سے منع فرمایا ہے","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے کنکر پھینک کر بیع کرنے اور دھوکے والی بیع سے منع فرمایا ہے"}],[3776,"لیث نے نافع سے ، انہوں نے سیدنا عبداللہ ( بن عمر رضی اللہ عنہ ) سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے حبل الحبلہ کی بیع سے منع فرمایا ہے","",{"u2":"لیث نے نافع سے، انہوں نے حضرت عبداللہ (بن عمر رضی اللہ عنہ) سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے حبل الحبلہ کی بیع سے منع فرمایا ہے"}],[3777,"عبیداللہ سے روایت ہے ، انہوں نے کہا : مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی ، انہوں نے کہا : اہل جاہلیت اونٹ کے گوشت کی حبل الحبلہ تک بیع کرتے تھے ۔ اور حبل الحبلہ یہ ہے کہ اونٹنی ( مادہ ) بچہ جنے ، پھر وہ بچہ جو پیدا ہوا ہے ، حاملہ ہو ( اس کی یا اس کے گوشت کی بیع ) تو اللہ کے رسول صلی اللہ علیہ وسلم نے انہیں اس سے منع فرما دیا","",{"u2":"عبیداللہ سے روایت ہے، انہوں نے کہا: مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی، انہوں نے کہا: اہل جاہلیت اونٹ کے گوشت کی حبل الحبلہ تک بیع کرتے تھے۔ اور حبل الحبلہ یہ ہے کہ اونٹنی (مادہ) بچہ جنے، پھر وہ بچہ جو پیدا ہوا ہے، حاملہ ہو (اس کی یا اس کے گوشت کی بیع) تو اللہ کے رسول صلی اللہ علیہ وسلم نے انہیں اس سے منع فرما دیا"}],[3778,"امام مالک نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کوئی کسی کی بیع پر بیع نہ کرے","",{"u2":"امام مالک نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی کسی کی بیع پر بیع نہ کرے"}],[3779,"عبیداللہ نے کہا : مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" کوئی آدمی اپنے ( مسلمان ) بھائی کی بیع پر بیع نہ کرے اور نہ اپنے ( مسلمان ) بھائی کے پیغامِ نکاح پر پیغام بھیجے ، الا یہ کہ وہ اسے اجازت دے","",{"u2":"عبیداللہ نے کہا: مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"کوئی آدمی اپنے (مسلمان) بھائی کی بیع پر بیع نہ کرے اور نہ اپنے (مسلمان) بھائی کے پیغامِ نکاح پر پیغام بھیجے، الا یہ کہ وہ اسے اجازت دے"}],[3780,"اسماعیل بن جعفر نے ہمیں علاء سے حدیث بیان کی ، انہوں نے اپنے والد ( عبدالرحمٰن ) سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی مسلمان کسی مسلمان کے سودے پر سودا بازی نہ کرے","",{"u2":"اسماعیل بن جعفر نے ہمیں علاء سے حدیث بیان کی، انہوں نے اپنے والد (عبدالرحمٰن) سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی مسلمان کسی مسلمان کے سودے پر سودا بازی نہ کرے"}],[3781,"احمد بن ابراہیم دورقی نے مجھے یہی حدیث بیان کی ، کہا : مجھے عبدالصمد نے حدیث بیان کی ، کہا : ہمیں شعبہ نے علاء اور سہیل سے حدیث بیان کی ، ان دونوں نے اپنے اپنے والد ( عبدالرحمٰن بن یعقوب اور ابوصالح سمان ) سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، نیز ہمیں محمد بن مثنیٰ نے یہی حدیث بیان کی ، کہا : ہمیں عبدالصمد نے حدیث بیان کی ، کہا : ہمیں شعبہ نے اعمش سے حدیث بیان کی ، انہوں نے ابوصالح سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، نیز عبیداللہ بن معاذ نے ہمیں حدیث بیان کی ، کہا : ہمیں میرے والد نے حدیث بیان کی ، کہا : ہمیں شعبہ نے عدی بن ثابت سے حدیث بیان کی ، انہوں نے ابوحازم سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ اللہ کے رسول صلی اللہ علیہ وسلم نے اس سے منع فرمایا کہ کوئی آدمی اپنے ( مسلمان ) بھائی کے کیے گئے سودے پر سودا کرے ، اور دَورقی کی روایت میں ( سوم اخيه کی بجائے ) سيمة اخيه ( چھوٹے سے سودے ) کے الفاظ ہیں"],[3783,"احمد بن ابراہیم دورقی نے مجھے یہی حدیث بیان کی ، کہا : مجھے عبدالصمد نے حدیث بیان کی ، کہا : ہمیں شعبہ نے علاء اور سہیل سے حدیث بیان کی ، ان دونوں نے اپنے اپنے والد ( عبدالرحمٰن بن یعقوب اور ابوصالح سمان ) سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، نیز ہمیں محمد بن مثنیٰ نے یہی حدیث بیان کی ، کہا : ہمیں عبدالصمد نے حدیث بیان کی ، کہا : ہمیں شعبہ نے اعمش سے حدیث بیان کی ، انہوں نے ابوصالح سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، نیز عبیداللہ بن معاذ نے ہمیں حدیث بیان کی ، کہا : ہمیں میرے والد نے حدیث بیان کی ، کہا : ہمیں شعبہ نے عدی بن ثابت سے حدیث بیان کی ، انہوں نے ابوحازم سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ اللہ کے رسول صلی اللہ علیہ وسلم نے اس سے منع فرمایا کہ کوئی آدمی اپنے ( مسلمان ) بھائی کے کیے گئے سودے پر سودا کرے ، اور دَورقی کی روایت میں ( سوم اخيه کی بجائے ) سيمة اخيه ( چھوٹے سے سودے ) کے الفاظ ہیں",""],[3784,"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" بیع کے لیے قافلے کے ساتھ راستے میں ( جا کر ) ملاقات نہ کی جائے ، نہ تم میں سے کوئی دوسرے کی بیع پر بیع کرے ، نہ خریدنے کی نیت کے بغیر محض بھاؤ بڑھانے کے لیے قیمت لگاؤ ، نہ کوئی شہری کسی دیہاتی کے لیے بیع کرے اور نہ تم اونٹنی اور بکری کا دودھ روکو ، جس نے انہیں اس کے بعد خرید لیا تو ان کا دودھ دوہنے کے بعد اسے دو باتوں کا اختیار ہے : اگر اسے وہ پسند ہے تو اسے رکھ لے اور اگر اسے ناپسند ہے تو ایک صاع کھجور کے ساتھ اسے واپس کر دے","",{"u2":"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بیع کے لیے قافلے کے ساتھ راستے میں (جا کر) ملاقات نہ کی جائے، نہ تم میں سے کوئی دوسرے کی بیع پر بیع کرے، نہ خریدنے کی نیت کے بغیر محض بھاؤ بڑھانے کے لیے قیمت لگاؤ، نہ کوئی شہری کسی دیہاتی کے لیے بیع کرے اور نہ تم اونٹنی اور بکری کا دودھ روکو، جس نے انہیں اس کے بعد خرید لیا تو ان کا دودھ دوہنے کے بعد اسے دو باتوں کا اختیار ہے: اگر اسے وہ پسند ہے تو اسے رکھ لے اور اگر اسے ناپسند ہے تو ایک صاع کھجور کے ساتھ اسے واپس کر دے"}],[3785,"معاذ عنبری نے کہا : ہمیں شعبہ نے عدی بن ثابت سے حدیث بیان کی ، انہوں نے ابوحازم سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ( تجارتی ) قافلوں کو آگے جا کر ( ان کے راستوں میں ) ملنے سے ، شہری کو کسی دیہاتی کے لیے بیع کرنے سے ، عورت کو اپنی ( مسلمان ) بہن کی طلاق کا مطالبہ کرنے سے ، محض بھاؤ چڑھانے کے لیے قیمت لگانے سے ، جانور کے تھنوں میں دودھ روکنے سے ، اور اپنے بھائی کے کیے گئے سودے پر سودا کرنے سے منع فرمایا ۔","",{"u2":"معاذ عنبری نے کہا: ہمیں شعبہ نے عدی بن ثابت سے حدیث بیان کی، انہوں نے ابوحازم سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے (تجارتی) قافلوں کو آگے جا کر (ان کے راستوں میں) ملنے سے، شہری کو کسی دیہاتی کے لیے بیع کرنے سے، عورت کو اپنی (مسلمان) بہن کی طلاق کا مطالبہ کرنے سے، محض بھاؤ چڑھانے کے لیے قیمت لگانے سے، جانور کے تھنوں میں دودھ روکنے سے، اور اپنے بھائی کے کیے گئے سودے پر سودا کرنے سے منع فرمایا۔"}],[3786,"غندر ، وہب بن جریر اور عبدالصمد بن عبدالوارث سب نے کہا : ہمیں شعبہ نے اسی سند کے ساتھ شعبہ سے روایت کردہ معاذ کی حدیث کی طرح حدیث بیان کی ، غندر اور وہب کی حدیث میں ( مجہول کے صیغے کے ساتھ ) ہے : \" منع کیا گیا ہے \" اور عبدالصمد کی حدیث میں ( معروف کے صیغے کے ساتھ ) ہے : \" رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا","",{"u2":"غندر، وہب بن جریر اور عبدالصمد بن عبدالوارث سب نے کہا: ہمیں شعبہ نے اسی سند کے ساتھ شعبہ سے روایت کردہ معاذ کی حدیث کی طرح حدیث بیان کی، غندر اور وہب کی حدیث میں (مجہول کے صیغے کے ساتھ) ہے: \"منع کیا گیا ہے\" اور عبدالصمد کی حدیث میں (معروف کے صیغے کے ساتھ) ہے: \"رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا"}],[3787,"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ( خریدنے کے ارادے کے بغیر ) بھاؤ چڑھانے کے لیے قیمت لگانے سے منع فرمایا","",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے (خریدنے کے ارادے کے بغیر) بھاؤ چڑھانے کے لیے قیمت لگانے سے منع فرمایا"}],[3788,"ابن ابی زائدہ ، یحییٰ بن سعید اور ( عبداللہ ) ابن نمیر ، ان سب نے عبیداللہ سے ، انہوں نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ بازار میں پہنچنے سے پہلے سامان حاصل کیا جائے ۔ یہ ابن نمیر کے الفاظ ہیں اور دوسرے دونوں نے کہا : نبی صلی اللہ علیہ وسلم نے ( سامانِ تجارت لانے والوں کو ) راستے میں جا کر ملنے سے منع فرمایا ۔"],[3789,"امام مالک نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے عبیداللہ سے ابن نمیر کی روایت کردہ حدیث کے مانند روایت کی","",{"u2":"ابن ابی زائدہ، یحییٰ بن سعید اور (عبداللہ) ابن نمیر، ان سب نے عبیداللہ سے، انہوں نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ بازار میں پہنچنے سے پہلے سامان حاصل کیا جائے۔ یہ ابن نمیر کے الفاظ ہیں اور دوسرے دونوں نے کہا: نبی صلی اللہ علیہ وسلم نے (سامانِ تجارت لانے والوں کو) راستے میں جا کر ملنے سے منع فرمایا۔\nامام مالک نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے عبیداللہ سے ابن نمیر کی روایت کردہ حدیث کے مانند روایت کی"}],[3790,"سیدنا عبداللہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے ( راستے میں ) جا کر سامان تجارت لینے سے منع فرمایا","",{"u2":"سیدنا عبداللہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے (راستے میں) جا کر سامان تجارت لینے سے منع فرمایا"}],[3791,"ہُشَیم نے ہمیں ہشام سے خبر دی ، انہوں نے ابن سیرین سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ( راستے میں ) جا کر باہر سے لائے جانے والے سامان تجارت کو حاصل کرنے سے منع فرمایا","",{"u2":"ہُشَیم نے ہمیں ہشام سے خبر دی، انہوں نے ابن سیرین سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے (راستے میں) جا کر باہر سے لائے جانے والے سامان تجارت کو حاصل کرنے سے منع فرمایا"}],[3792,"ابن جریج نے کہا : مجھے ہشام قردوسی نے ابن سیرین سے خبر دی ، انہوں نے کہا : میں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" سامانِ تجارت کو راستے میں جا کر حاصل نہ کرو ۔ جس نے باہر مل کر ان سے سامان خرید لیا ، تو جب اس کا مالک بازار میں آئے گا تو اسے ( بیع کو برقرار رکھنے یا فسخ کرنے کا ) اختیار ہو گا","",{"u2":"ابن جریج نے کہا: مجھے ہشام قردوسی نے ابن سیرین سے خبر دی، انہوں نے کہا: میں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سامانِ تجارت کو راستے میں جا کر حاصل نہ کرو۔ جس نے باہر مل کر ان سے سامان خرید لیا، تو جب اس کا مالک بازار میں آئے گا تو اسے (بیع کو برقرار رکھنے یا فسخ کرنے کا) اختیار ہو گا"}],[3793,"ابوبکر بن ابی شیبہ ، عمرو ناقد اور زُہَیر بن حرب نے کہا : ہمیں سفیان نے زہری سے حدیث بیان کی ، انہوں نے سعید بن مسیب سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، وہ اس ( سند ) کو نبی صلی اللہ علیہ وسلم تک پہنچاتے تھے ، آپ نے فرمایا : \"\" کوئی شہری کسی دیہاتی کے لیے بیع نہ کرے ۔ \"\" زہیر نے کہا : نبی صلی اللہ علیہ وسلم سے روایت ہے کہ آپ نے اس بات سے منع فرمایا کہ کوئی شہری کسی دیہاتی کی طرف سے بیع کرے","",{"u2":"ابوبکر بن ابی شیبہ، عمرو ناقد اور زُہَیر بن حرب نے کہا: ہمیں سفیان نے زہری سے حدیث بیان کی، انہوں نے سعید بن مسیب سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، وہ اس (سند) کو نبی صلی اللہ علیہ وسلم تک پہنچاتے تھے، آپ نے فرمایا: \"کوئی شہری کسی دیہاتی کے لیے بیع نہ کرے۔\"\nزہیر نے کہا: نبی صلی اللہ علیہ وسلم سے روایت ہے کہ آپ نے اس بات سے منع فرمایا کہ کوئی شہری کسی دیہاتی کی طرف سے بیع کرے"}],[3794,"طاوس کے بیٹے نے اپنے والد سے ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے اس بات سے منع فرمایا کہ باہر نکل کر قافلے والوں سے ملا جائے اور اس سے کہ کوئی شہری کسی دیہاتی کی طرف سے بیع کرے ۔ ( طاوس نے ) کہا : میں نے ابن عباس رضی اللہ عنہ سے پوچھا : آپ کے فرمان : \" کوئی شہری دیہاتی کی طرف سے ( بیع نہ کرے ) \" کا کیا مفہوم ہے؟ انہوں نے جواب دیا : وہ اس کا دلال نہ بنے","",{"u2":"طاوس کے بیٹے نے اپنے والد سے، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے اس بات سے منع فرمایا کہ باہر نکل کر قافلے والوں سے ملا جائے اور اس سے کہ کوئی شہری کسی دیہاتی کی طرف سے بیع کرے۔ (طاوس نے) کہا: میں نے ابن عباس رضی اللہ عنہ سے پوچھا: آپ کے فرمان: \"کوئی شہری دیہاتی کی طرف سے (بیع نہ کرے)\" کا کیا مفہوم ہے؟ انہوں نے جواب دیا: وہ اس کا دلال نہ بنے"}],[3795,"یحییٰ بن یحییٰ تمیمی اور احمد بن یونس نے کہا : ہمیں ابوخثیمہ زہیر نے حدیث سنائی ، کہا : ہمیں ابوزبیر نے سیدنا جابر رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی شہری کسی دیہاتی کی طرف سے بیع نہ کرے ۔ لوگوں کو چھوڑ دو ، اللہ تعالیٰ ان میں سے بعض کو بعض کے ذریعے سے رزق دیتا ہے ۔ \" البتہ یحییٰ کی روایت میں ( مجہول کے صیغے کے ساتھ ) ہے : \" رزق دیا جاتا ہے"],[3796,"یحییٰ بن یحییٰ تمیمی اور احمد بن یونس نے کہا : ہمیں ابوخثیمہ زہیر نے حدیث سنائی ، کہا : ہمیں ابوزبیر نے سیدنا جابر رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی شہری کسی دیہاتی کی طرف سے بیع نہ کرے ۔ لوگوں کو چھوڑ دو ، اللہ تعالیٰ ان میں سے بعض کو بعض کے ذریعے سے رزق دیتا ہے ۔ \" البتہ یحییٰ کی روایت میں ( مجہول کے صیغے کے ساتھ ) ہے : \" رزق دیا جاتا ہے",""],[3797,"سفیان بن عیینہ نے ہمیں ابوزہیر سے حدیث بیان کی ، انہوں نے سیدنا جابر رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔ ( 3828 ) یونس نے ابن سیرین سے ، انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ہمیں منع کیا گیا ہے کہ کوئی شہری کسی دیہاتی کی طرف سے بیع کرے ، خواہ وہ اس کا بھائی ہو یا والد","",{"u2":"سفیان بن عیینہ نے ہمیں ابوزہیر سے حدیث بیان کی، انہوں نے سیدنا جابر رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔\n(3828) یونس نے ابن سیرین سے، انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ہمیں منع کیا گیا ہے کہ کوئی شہری کسی دیہاتی کی طرف سے بیع کرے، خواہ وہ اس کا بھائی ہو یا والد"}],[3798,"یونس نے ابن سیرین سے ، انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ہمیں منع کیا گیا ہے کہ کوئی شہری کسی دیہاتی کی طرف سے بیع کرے ، خواہ وہ اس کا بھائی ہو یا والد","",{"u2":"یونس نے ابن سیرین سے، انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ہمیں منع کیا گیا ہے کہ کوئی شہری کسی دیہاتی کی طرف سے بیع کرے، خواہ وہ اس کا بھائی ہو یا والد"}],[3799,"ابن عون نے ہمیں محمد ( بن سیرین ) سے حدیث بیان کی ، کہا : سیدنا انس بن مالک رضی اللہ عنہ نے کہا : ہمیں اس بات سے منع کیا گیا کہ کوئی شہری کسی دیہاتی کے لیے بیع کرے"],[3800,"ابن عون نے ہمیں محمد ( بن سیرین ) سے حدیث بیان کی ، کہا : سیدنا انس بن مالک رضی اللہ عنہ نے کہا : ہمیں اس بات سے منع کیا گیا کہ کوئی شہری کسی دیہاتی کے لیے بیع کرے",""],[3801,"موسیٰ بن یسار نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے دودھ روکی گئی بھیڑ ( یا بکری ) خرید لی تو وہ اسے لے کر گھر واپس آئے اور اس کا دودھ نکالے ، اگر وہ اس کے ددھ دینے سے راضی ہو تو اسے رکھ لے ، ورنہ کھجور کے ایک صاع سمیت اسے واپس کر دے","",{"u2":"موسیٰ بن یسار نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے دودھ روکی گئی بھیڑ (یا بکری) خرید لی تو وہ اسے لے کر گھر واپس آئے اور اس کا دودھ نکالے، اگر وہ اس کے ددھ دینے سے راضی ہو تو اسے رکھ لے، ورنہ کھجور کے ایک صاع سمیت اسے واپس کر دے"}],[3802,"سہیل کے والد ( ابوصالح ) نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے ایسی بھیڑ ( یا بکری ) خرید لی جس کا دودھ روکا گیا ہے تو اسے تین دن تک اس کے بارے میں اختیار ہے ، اگر چاہے تو رکھ لے اور چاہے تو واپس کر دے اور اس کے ساتھ کھجور کا ایک صاع بھی واپس کرے","",{"u2":"سہیل کے والد (ابوصالح) نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے ایسی بھیڑ (یا بکری) خرید لی جس کا دودھ روکا گیا ہے تو اسے تین دن تک اس کے بارے میں اختیار ہے، اگر چاہے تو رکھ لے اور چاہے تو واپس کر دے اور اس کے ساتھ کھجور کا ایک صاع بھی واپس کرے"}],[3803,"قرہ نے ہمیں محمد ( بن سیرین ) سے حدیث بیان کی ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ، آپ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے دودھ روکی ہوئی بھیڑ ( یا بکری ) خرید لی تو اسے تین دن تک اختیار ہے ۔ اگر وہ اسے واپس کرے تو اس کے ساتھ غلے کا ایک صاع بھی واپس کرے ، گندم کا نہیں","",{"u2":"قرہ نے ہمیں محمد (بن سیرین) سے حدیث بیان کی، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی، آپ صلی اللہ علیہ وسلم نے فرمایا: \" جس نے دودھ روکی ہوئی بھیڑ (یا بکری) خرید لی تو اسے تین دن تک اختیار ہے۔ اگر وہ اسے واپس کرے تو اس کے ساتھ غلے کا ایک صاع بھی واپس کرے، گندم کا نہیں"}],[3804,"سفیان نے ہمیں ایوب سے حدیث بیان کی ، انہوں نے محمد ( بن سیرین ) سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے دودھ روکی ہوئی بکری خرید لی ، اسے دو باتوں کا اختیار ہے ۔ اگر چاہے تو اسے رکھ لے اور اگر چاہے تو اسے واپس کر دے ، اور کھجور کا ایک صاع بھی واپس کر دے ، گندم کا نہیں","",{"u2":"سفیان نے ہمیں ایوب سے حدیث بیان کی، انہوں نے محمد (بن سیرین) سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے دودھ روکی ہوئی بکری خرید لی، اسے دو باتوں کا اختیار ہے۔ اگر چاہے تو اسے رکھ لے اور اگر چاہے تو اسے واپس کر دے، اور کھجور کا ایک صاع بھی واپس کر دے، گندم کا نہیں"}],[3805,"عبدالوہاب نے ایوب سے اسی سند کے ساتھ حدیث بیان کی ، لیکن انہوں نے کہا : \" جس نے ( دودھ روکی ہوئی ) کوئی بھیڑ یا بکری خریدی اسے اختیار ہے","",{"u2":"عبدالوہاب نے ایوب سے اسی سند کے ساتھ حدیث بیان کی، لیکن انہوں نے کہا: \"جس نے (دودھ روکی ہوئی) کوئی بھیڑ یا بکری خریدی اسے اختیار ہے"}],[3806,"ہمام بن منبہ سے روایت ہے ، انہوں نے کہا : یہ احادیث ہیں جو ہمیں سیدنا ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں ، اس کے بعد انہوں نے کئی احادیث بیان کیں ، ان میں سے ایک یہ تھی : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی دودھ روکی گئی اونٹنی یا بھیڑ ( یا بکری ) خرید لے تو اسے اس کا دودھ نکالنے کے بعد دو باتوں کا اختیار ہے یا تو وہ ( جانور ) لے لے ورنہ کھجور کے ایک صاع سمیت اسے واپس کر دے","",{"u2":"ہمام بن منبہ سے روایت ہے، انہوں نے کہا: یہ احادیث ہیں جو ہمیں سیدنا ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں، اس کے بعد انہوں نے کئی احادیث بیان کیں، ان میں سے ایک یہ تھی: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی دودھ روکی گئی اونٹنی یا بھیڑ (یا بکری) خرید لے تو اسے اس کا دودھ نکالنے کے بعد دو باتوں کا اختیار ہے یا تو وہ (جانور) لے لے ورنہ کھجور کے ایک صاع سمیت اسے واپس کر دے"}],[3807,"سفیان بن عیینہ اور سفیان ثوری نے عمرو بن دینار سے اسی سند کے ساتھ اسی کے مطابق روایت کی","",{"u2":"حماد نے ہمیں عمرو بن دینار سے حدیث بیان کی، انہوں نے طاوس سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے غلہ خریدا تو وہ اسے پورا کر لینے سے پہلے آگے فروخت نہ کرے۔\"\nسیدنا ابن عباس رضی اللہ عنہ نے کہا: میں ہر چیز کو اسی کے مانند خیال کرتا ہوں"}],[3808,"معمر نے ابن طاوس سے خبر دی ، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے غلہ خریدا تو وہ اسے فروخت نہ کرے حتی کہ اسے اپنے قبضے میں لے لےسیدنا ابن عباس رضی اللہ عنہ نے کہا : میں ہر چیز کو غلے کی طرح سمجھتا ہوں","",{"u2":"سفیان بن عیینہ اور سفیان ثوری نے عمرو بن دینار سے اسی سند کے ساتھ اسی کے مطابق روایت کی"}],[3809,"ابوبکر بن ابی شیبہ ، ابو کُرَیب اور اسحاق بن ابراہیم نے ہمیں حدیث بیان کی ۔ ۔ اسحاق نے کہا : ہمیں خبر دی اور دیگر نے کہا : ہمیں حدیث بیان کی ۔ ۔ وکیع نے سفیان سے ، انہوں نے ابن طاوس سے ، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جو غلہ خریدے تو اسے آگے فروخت نہ کرے حتی کہ اسے ماپ ( کر قبضے میں لے ) لے","",{"u2":"معمر نے ابن طاوس سے خبر دی، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے غلہ خریدا تو وہ اسے فروخت نہ کرے حتی کہ اسے اپنے قبضے میں لے لےسیدنا ابن عباس رضی اللہ عنہ نے کہا: میں ہر چیز کو غلے کی طرح سمجھتا ہوں"}],[3811,"عبداللہ بن مسلمہ قعنبی نے ہمیں حدیث سنائی ، کہا : ہمیں مالک نے حدیث سنائی ۔ اور یحییٰ بن یحییٰ نے ہمیں حدیث سنائی ، کہا : میں نے مالک کے سامنے قراءت کی کہ نافع سے روایت ہے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جو شخص غلہ خریدے تو پورا حاصل کرنے سے پہلے اسے فروخت نہ کرے","",{"u2":"عبداللہ بن مسلمہ قعنبی نے ہمیں حدیث سنائی، کہا: ہمیں مالک نے حدیث سنائی۔ اور یحییٰ بن یحییٰ نے ہمیں حدیث سنائی، کہا: میں نے مالک کے سامنے قراءت کی کہ نافع سے روایت ہے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص غلہ خریدے تو پورا حاصل کرنے سے پہلے اسے فروخت نہ کرے"}],[3812,"یحییٰ بن یحییٰ نے سابقہ سند کے ساتھ سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ہم غلہ خریدا کرتے تھے تو آپ صلی اللہ علیہ وسلم ہم پر ایسے آدمی مقرر فرماتے جو ہمیں حکم دیتے کہ اسے فروخت کرنے سے پہلے اس جگہ سے جہاں ہم نے اسے خریدا تھا ، کسی دوسری جگہ منتقل کریں","",{"u2":"یحییٰ بن یحییٰ نے سابقہ سند کے ساتھ سیدنا ابن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ہم غلہ خریدا کرتے تھے تو آپ صلی اللہ علیہ وسلم ہم پر ایسے آدمی مقرر فرماتے جو ہمیں حکم دیتے کہ اسے فروخت کرنے سے پہلے اس جگہ سے جہاں ہم نے اسے خریدا تھا، کسی دوسری جگہ منتقل کریں"}],[3813,"عبیداللہ نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جو شخص غلہ خریدے تو وہ اسے پورا کر لینے تک آگے فروخت نہ کرے",""],[3814,"نیز انہوں ( سیدنا ابن عمر رضی اللہ عنہ ) نے کہا : ہم اہل قافلہ سے بغیر ماپ ( اور وزن ) کے غلہ خریدا کرتے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں منع فرمایا کہ ہم اسے ، اس کی جگہ سے منتقل کرنے سے پلے ، آگے فروخت کریں","",{"u2":"عمر بن محمد نے نافع سے، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی کہ اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص غلہ خریدے تو اسے پورا کر لینے اور اپنے قبضے میں لینے سے پہلے فروخت نہ کرے"}],[3815,"عمر بن محمد نے نافع سے ، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی کہ اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا : \" جو شخص غلہ خریدے تو اسے پورا کر لینے اور اپنے قبضے میں لینے سے پہلے فروخت نہ کرے","",{"u2":"عبداللہ بن دینار سے روایت ہے کہ انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص غلہ خریدے تو اسے قبضے میں لینے سے پہلے آگے فروخت نہ کرے"}],[3817,"یونس نے مجھے ابن شہاب ( زہری ) سے خبر دی ، انہوں نے کہا : مجھے سالم بن عبداللہ نے بتایا کہ ان کے والد ( عبداللہ بن عمر رضی اللہ عنہ ) نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں لوگوں کو دیکھا کہ جب وہ ( ناپ تول کے بغیر ) اندازے سے غلہ خریدتے تو اس بات پر انہیں مار پڑی تھی کہ وہ اس کو گھروں میں منتقل کرنے سے پہلے ، اسی جگہ اسے بیچیں ۔ ابن شہاب نے کہا : مجھے عبیداللہ بن عبداللہ بن عمر نے حدیث بیان کی کہ ان کے والد اندازے سے غلہ خریدتے ، پھر اسے اپنے گھر اٹھا لاتے"],[3818,"یونس نے مجھے ابن شہاب ( زہری ) سے خبر دی ، انہوں نے کہا : مجھے سالم بن عبداللہ نے بتایا کہ ان کے والد ( عبداللہ بن عمر رضی اللہ عنہ ) نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں لوگوں کو دیکھا کہ جب وہ ( ناپ تول کے بغیر ) اندازے سے غلہ خریدتے تو اس بات پر انہیں مار پڑی تھی کہ وہ اس کو گھروں میں منتقل کرنے سے پہلے ، اسی جگہ اسے بیچیں ۔ ابن شہاب نے کہا : مجھے عبیداللہ بن عبداللہ بن عمر نے حدیث بیان کی کہ ان کے والد اندازے سے غلہ خریدتے ، پھر اسے اپنے گھر اٹھا لاتے",""],[3819,"ابوبکر بن ابی شیبہ ، ابن نمیر اور ابو کریب نے کہا : ہمیں زید بن حباب نے ضحاک بن عثمان سے حدیث بیان کی ، انہوں نے بُکَیر بن عبداللہ بن اشج سے ، انہوں نے سلیمان بن یسار سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" جو شخص غلہ خریدے تو اسے ناپ کر لے لینے سے پہلے آگے فروخت نہ کرے ۔ \"\" ابوبکر کی روایت میں ( من الشترى کی بجائے ) من ابتاع کے الفاظ ہیں ( معنی ایک جیسے ہیں)","",{"u2":"ابوبکر بن ابی شیبہ، ابن نمیر اور ابو کریب نے کہا: ہمیں زید بن حباب نے ضحاک بن عثمان سے حدیث بیان کی، انہوں نے بُکَیر بن عبداللہ بن اشج سے، انہوں نے سلیمان بن یسار سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص غلہ خریدے تو اسے ناپ کر لے لینے سے پہلے آگے فروخت نہ کرے۔\"\nابوبکر کی روایت میں (من الشتری کی بجائے) من ابتاع کے الفاظ ہیں (معنی ایک جیسے ہیں"}],[3820,"عبداللہ بن حارث مخزومی نے ہمیں خبر دی ، کہا : ہمیں ضحاک بن عثمان نے بکیر بن عبداللہ بن اشج سے حدیث بیان کی ، انہوں نے سلیمان بن یسار سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ انہوں نے مروان سے کہا : تم نے سودی تجارت حلال کر دی ہے؟ مروان نے جواب دیا : میں نے ایسا کیا کیا ہے؟ ابوہریرہ رضی اللہ عنہ نے کہا : تم نے ادائیگی کی دستاویزات ( چیکوں ) کی بیع حلال قرار دی ہے حالانکہ رسول اللہ صلی اللہ علیہ وسلم نے مکمل قبضہ کرنے سے پہلے غلے کو بیچنے سے منع فرمایا ہے ۔ کہا : اس پر مروان نے لوگوں کو خطبہ دیا اور ان ( چیکوں ) کی بیع سے منع کر دیا ۔ سلیمان نے کہا : میں نے محافظوں کو دیکھا وہ انہیں لوگوں کے ہاتھوں سے واپس لے رہے تھے","",{"u2":"عبداللہ بن حارث مخزومی نے ہمیں خبر دی، کہا: ہمیں ضحاک بن عثمان نے بکیر بن عبداللہ بن اشج سے حدیث بیان کی، انہوں نے سلیمان بن یسار سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ انہوں نے مروان سے کہا: تم نے سودی تجارت حلال کر دی ہے؟ مروان نے جواب دیا: میں نے ایسا کیا کیا ہے؟ ابوہریرہ رضی اللہ عنہ نے کہا: تم نے ادائیگی کی دستاویزات (چیکوں) کی بیع حلال قرار دی ہے حالانکہ رسول اللہ صلی اللہ علیہ وسلم نے مکمل قبضہ کرنے سے پہلے غلے کو بیچنے سے منع فرمایا ہے۔ کہا: اس پر مروان نے لوگوں کو خطبہ دیا اور ان (چیکوں) کی بیع سے منع کر دیا۔\nسلیمان نے کہا: میں نے محافظوں کو دیکھا وہ انہیں لوگوں کے ہاتھوں سے واپس لے رہے تھے"}],[3821,"سیدنا جابر بن عبداللہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے : \" جب تم غلہ خریدو تو اسے پوری طرح قبضے میں لینے سے پہلے نہ بیچو","",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے: \"جب تم غلہ خریدو تو اسے پوری طرح قبضے میں لینے سے پہلے نہ بیچو"}],[3822,"روح بن عبادہ نے ہمیں حدیث بیان کی ، کہا : ہمیں ابن جریج نے ابوزبیر سے خبر دی ، انہوں نے جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ۔ ۔ ۔ اسی ( مذکورہ بالا روایت ) کے مانند ، لیکن انہوں نے حدیث کے آخر میں من التمر کے الفاظ ذکر نہیں کیے","",{"u2":"روح بن عبادہ نے ہمیں حدیث بیان کی، کہا: ہمیں ابن جریج نے ابوزبیر سے خبر دی، انہوں نے جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا۔۔۔ اسی (مذکورہ بالا روایت) کے مانند، لیکن انہوں نے حدیث کے آخر میں من التمر کے الفاظ ذکر نہیں کیے"}],[3823,"روح بن عبادہ نے ہمیں حدیث بیان کی ، کہا : ہمیں ابن جریج نے ابوزبیر سے خبر دی ، انہوں نے جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ۔ ۔ ۔ اسی ( مذکورہ بالا روایت ) کے مانند ، لیکن انہوں نے حدیث کے آخر میں من التمر کے الفاظ ذکر نہیں کیے","",{"u2":"روح بن عبادہ نے ہمیں حدیث بیان کی، کہا: ہمیں ابن جریج نے ابوزبیر سے خبر دی، انہوں نے جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا۔۔۔ اسی (مذکورہ بالا روایت) کے مانند، لیکن انہوں نے حدیث کے آخر میں من التمر کے الفاظ ذکر نہیں کیے"}],[3824,"امام مالک نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا : \" بیع کرنے والے دونوں میں سے ہر ایک کو اپنے ساتھی کے خلاف ( بیع فسخ کرنے کا ) اختیار ہے جب تک وہ جدا نہ ہوں ، الا یہ کہ اختیار والی بیع ہو","",{"u2":"امام مالک نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا: \"بیع کرنے والے دونوں میں سے ہر ایک کو اپنے ساتھی کے خلاف (بیع فسخ کرنے کا) اختیار ہے جب تک وہ جدا نہ ہوں، الا یہ کہ اختیار والی بیع ہو"}],[3825,"عبیداللہ ، ایوب ، یحییٰ بن سعید اور ضحاک نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ، نافع سے امام مالک کی حدیث کی طرح روایت کی"],[3826,"عبیداللہ ، ایوب ، یحییٰ بن سعید اور ضحاک نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ، نافع سے امام مالک کی حدیث کی طرح روایت کی"],[3827,"عبیداللہ ، ایوب ، یحییٰ بن سعید اور ضحاک نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ، نافع سے امام مالک کی حدیث کی طرح روایت کی",""],[3828,"لیث نے ہمیں نافع سے خبر دی ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" جب دو آدمی باہم بیع کریں تو دونوں میں سے ہر ایک کو ( سودا ختم کرنے کا ) اختیار ہے جب تک وہ دونوں جدا نہ ہو جائیں اور اکٹھے ہوں ۔ یا ان دونوں میں سے ایک دوسرے کو اختیار دے ، اگر ان میں سے ایک دوسرے کو اختیار دے اور اسی پر دونوں بیع کر لیں تو بیع لازم ہو گئی ، اور اگر باہم بیع کرنے کے بعد دونوں جدا ہوئے اور ان میں سے کسی نے بیع کو ترک نہیں کیا تو بھی بیع لازم ہو گئی","",{"u2":"لیث نے ہمیں نافع سے خبر دی، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"جب دو آدمی باہم بیع کریں تو دونوں میں سے ہر ایک کو (سودا ختم کرنے کا) اختیار ہے جب تک وہ دونوں جدا نہ ہو جائیں اور اکٹھے ہوں۔ یا ان دونوں میں سے ایک دوسرے کو اختیار دے، اگر ان میں سے ایک دوسرے کو اختیار دے اور اسی پر دونوں بیع کر لیں تو بیع لازم ہو گئی، اور اگر باہم بیع کرنے کے بعد دونوں جدا ہوئے اور ان میں سے کسی نے بیع کو ترک نہیں کیا تو بھی بیع لازم ہو گئی"}],[3829,"زہیر بن حرب اور ابن ابی عمر دونوں نے سفیان سے روایت کی ۔ زہیر نے کہا : ہمیں سفیان بن عیینہ نے ابن جریج سے حدیث بیان کی ، انہوں نے کہا : مجھے نافع نے ( حدیث ) املا کرائی کہ انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" جب دو بیع کرنے والے باہم خرید و فروخت کریں تو ان میں سے ہر ایک کو اپنی بیع ( ختم کرنے ) کا اختیار ہے جب تک وہ باہم جدا نہ ہوں یا ان کی بیع اختیار سے ہوئی ہو ( انہوں نے اختیار استعمال کر لیا ہو ۔ ) اگر ان کی بیع اختیار سے ہوئی ہے تو لازم ہو گئی ہے ۔ \"\" ابن ابی عمر نے اپنی روایت میں اضافہ کیا کہ نافع نے کہا : جب وہ ( ابن عمر رضی اللہ عنہ ) کسی آدمی سے بیع کرتے اور چاہتے کہ وہ آدمی ان سے بیع کی واپسی کا مطالبہ ( اقالہ ) نہ کرے تو وہ ( خیارِ مجلس ختم کرنے کے لیے ) اٹھتے ، تھوڑا سا چلتے ، پھر اس کے پاس واپس آ جاتے","",{"u2":"زہیر بن حرب اور ابن ابی عمر دونوں نے سفیان سے روایت کی۔ زہیر نے کہا: ہمیں سفیان بن عیینہ نے ابن جریج سے حدیث بیان کی، انہوں نے کہا: مجھے نافع نے (حدیث) املا کرائی کہ انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب دو بیع کرنے والے باہم خرید و فروخت کریں تو ان میں سے ہر ایک کو اپنی بیع (ختم کرنے) کا اختیار ہے جب تک وہ باہم جدا نہ ہوں یا ان کی بیع اختیار سے ہوئی ہو (انہوں نے اختیار استعمال کر لیا ہو۔) اگر ان کی بیع اختیار سے ہوئی ہے تو لازم ہو گئی ہے۔\"\nابن ابی عمر نے اپنی روایت میں اضافہ کیا کہ نافع نے کہا: جب وہ (ابن عمر رضی اللہ عنہ) کسی آدمی سے بیع کرتے اور چاہتے کہ وہ آدمی ان سے بیع کی واپسی کا مطالبہ (اقالہ) نہ کرے تو وہ (خیارِ مجلس ختم کرنے کے لیے) اٹھتے، تھوڑا سا چلتے، پھر اس کے پاس واپس آ جاتے"}],[3830,"عبداللہ بن دینار سے روایت ہے کہ انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا وہ کہہ رہے تھے ۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" دو بیع کرنے والوں کے درمیان ( اس وقت تک ) بیع ( لازم ) نہیں ہوتی ، یہاں تک کہ وہ ایک دوسرے سے جدا ہو جائیں ، الا یہ کہ خیار ( اختیار ) والی بیع ہو ۔ \" ( جس میں خیار کی مدت طے کر لی جائے یا اختیار استعمال کر کے بیع کو پکا کر لیا جائے)","",{"u2":"عبداللہ بن دینار سے روایت ہے کہ انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا وہ کہہ رہے تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دو بیع کرنے والوں کے درمیان (اس وقت تک) بیع (لازم) نہیں ہوتی، یہاں تک کہ وہ ایک دوسرے سے جدا ہو جائیں، الا یہ کہ خیار (اختیار) والی بیع ہو۔\" (جس میں خیار کی مدت طے کر لی جائے یا اختیار استعمال کر کے بیع کو پکا کر لیا جائے"}],[3831,"ابوخلیل نے عبداللہ بن حارث سے ، انہوں نے سیدنا حکیم بن حزام رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" بیع کرنے والے دونوں فریقوں کو اختیار ہے جب تک جدا نہ ہوں ۔ اگر وہ دونوں سچ بولیں اور حقیقت کو واضح کریں تو ان کی بیع میں برکت ڈالی جاتی ہے ، اور اگر وہ جھوٹ بولیں اور ( عیب وغیرہ ) چھپائیں تو ان کی بیع سے برکت مٹا دی جاتی ہے","",{"u2":"ابوخلیل نے عبداللہ بن حارث سے، انہوں نے سیدنا حکیم بن حزام رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"بیع کرنے والے دونوں فریقوں کو اختیار ہے جب تک جدا نہ ہوں۔اگر وہ دونوں سچ بولیں اور حقیقت کو واضح کریں تو ان کی بیع میں برکت ڈالی جاتی ہے، اور اگر وہ جھوٹ بولیں اور (عیب وغیرہ) چھپائیں تو ان کی بیع سے برکت مٹا دی جاتی ہے"}],[3832,"ابوتیاح سے روایت ہے ، انہوں نے کہا : میں نے عبداللہ بن حارث سے سنا ، وہ حکیم بن حزام رضی اللہ عنہ سے حدیث بیان کر رہے تھے ، انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔ امام مسلم بن حجاج رحمۃ اللہ علیہ نے کہا : سیدنا حکیم بن حزام رضی اللہ عنہ کعبہ کے اندر پیدا ہوئے تھے اور انہوں نے 120 سال زندگی پائی","",{"u2":"ابوتیاح سے روایت ہے، انہوں نے کہا: میں نے عبداللہ بن حارث سے سنا، وہ حکیم بن حزام رضی اللہ عنہ سے حدیث بیان کر رہے تھے، انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔\nامام مسلم بن حجاج رحمۃ اللہ علیہ نے کہا: سیدنا حکیم بن حزام رضی اللہ عنہ کعبہ کے اندر پیدا ہوئے تھے اور انہوں نے 120 سال زندگی پائی"}],[3833,"اسماعیل بن جعفر نے عبداللہ بن دینار سے روایت کی ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کی کہ اسے بیع میں دھوکا دے دیا جاتا ہے ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" تم جس سے بھی بیع کرو تو کہہ دیا کرو : دھوکا نہیں ہو گا ۔ \"\" ( بعد ازیں ) وہ جب بھی بیع کرتا تو کہتا : دھوکا نہیں ہو گا","",{"u2":"اسماعیل بن جعفر نے عبداللہ بن دینار سے روایت کی، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کی کہ اسے بیع میں دھوکا دے دیا جاتا ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم جس سے بھی بیع کرو تو کہہ دیا کرو: دھوکا نہیں ہو گا۔\"\n(بعد ازیں) وہ جب بھی بیع کرتا تو کہتا: دھوکا نہیں ہو گا"}],[3834,"سفیان اور شعبہ دونوں نے عبداللہ بن دینار سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ، لیکن ان دونوں کی حدیث میں یہ الفاظ نہیں ہیں : وہ جب سودا کرتا تو کہتا تھا : دھوکا نہیں ہو گا","",{"u2":"سفیان اور شعبہ دونوں نے عبداللہ بن دینار سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی، لیکن ان دونوں کی حدیث میں یہ الفاظ نہیں ہیں: وہ جب سودا کرتا تو کہتا تھا: دھوکا نہیں ہو گا"}],[3835,"امام مالک نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ اللہ کے رسول صلی اللہ علیہ وسلم نے ( اس وقت تک درختوں پر لگے ہوئے ) پھلوں کی بیع سے منع فرمایا یہاں تک کہ ان کی ( پکنے کی ) صلاحیت ظاہر ہو جائے ۔ آپ نے بیچنے والے اور خریدنے والے دونوں کو ( ایسی بیع سے ) منع فرمایا","",{"u2":"امام مالک نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ اللہ کے رسول صلی اللہ علیہ وسلم نے (اس وقت تک درختوں پر لگے ہوئے) پھلوں کی بیع سے منع فرمایا یہاں تک کہ ان کی (پکنے کی) صلاحیت ظاہر ہو جائے۔ آپ نے بیچنے والے اور خریدنے والے دونوں کو (ایسی بیع سے) منع فرمایا"}],[3836,"عبیداللہ نے ہمیں نافع سے حدیث بیان کی ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی","",{"u2":"عبیداللہ نے ہمیں نافع سے حدیث بیان کی، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی"}],[3837,"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کھجور کی بیع سے منع فرمایا حتی کہ وہ سرخ یا زرد ہو جائے اور کِھیل ( سٹہ ) ( کی بیع ) سے حتی کہ وہ ( دانے بھر کر ) سفید اور آفات سے محفوظ ہو جائے ۔ آپ نے بیچنے اور خریدنے والے دونوں کو منع فرمایا","",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کھجور کی بیع سے منع فرمایا حتی کہ وہ سرخ یا زرد ہو جائے اور کِھیل (سٹہ) (کی بیع) سے حتی کہ وہ (دانے بھر کر) سفید اور آفات سے محفوظ ہو جائے۔آپ نے بیچنے اور خریدنے والے دونوں کو منع فرمایا"}],[3838,"جریر نے ہمیں یحییٰ بن سعید سے حدیث بیان کی ، انہوں نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" تم پھل مت خریدو حتی کہ ان کی صلاحیت ظاہر ہو جائے اور اس سے آفت ( کا امکان ) ختم ہو جائے ۔ \"\" ( ابن عمر رضی اللہ عنہ نے ) کہا : اس کی صلاحیت ( ظاہر ہونے ) سے اس کی سرخی اور زردی مراد ہے","",{"u2":"جریر نے ہمیں یحییٰ بن سعید سے حدیث بیان کی، انہوں نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم پھل مت خریدو حتی کہ ان کی صلاحیت ظاہر ہو جائے اور اس سے آفت (کا امکان) ختم ہو جائے۔\"\n(ابن عمر رضی اللہ عنہ نے) کہا: اس کی صلاحیت (ظاہر ہونے) سے اس کی سرخی اور زردی مراد ہے"}],[3839,"عبدالوہاب نے یحییٰ سے اسی سند کے ساتھ \" حتیٰ کہ اس کی صلاحیت واضح ہو جائے \" تک حدیث بیان کی ، اس کے بعد والا حصہ بیان نہیں کیا","",{"u2":"عبدالوہاب نے یحییٰ سے اسی سند کے ساتھ \"حتیٰ کہ اس کی صلاحیت واضح ہو جائے\" تک حدیث بیان کی، اس کے بعد والا حصہ بیان نہیں کیا"}],[3840,"ابن ابی فُدیک نے ہمیں حدیث بیان کی ، کہا : ہمیں ضحاک نے نافع سے خبر دی ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے عبدالوہاب کی حدیث کی طرح روایت کی","",{"u2":"ابن ابی فُدیک نے ہمیں حدیث بیان کی، کہا: ہمیں ضحاک نے نافع سے خبر دی، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے عبدالوہاب کی حدیث کی طرح روایت کی"}],[3841,"موسیٰ بن عقبہ نے مجھے نافع سے حدیث بیان کی ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے امام مالک اور عبیداللہ کی حدیث کے مانند روایت بیان کی","",{"u2":"موسیٰ بن عقبہ نے مجھے نافع سے حدیث بیان کی، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے امام مالک اور عبیداللہ کی حدیث کے مانند روایت بیان کی"}],[3842,"اسماعیل بن جعفر نے عبداللہ بن دینار سے روایت کی کہ انہوں نے ابن عمر رضی اللہ عنہ سے سنا ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم پھل نہ بیچو یہاں تک کہ اس کی صلاحیت ظاہر ہو جائے","",{"u2":"اسماعیل بن جعفر نے عبداللہ بن دینار سے روایت کی کہ انہوں نے ابن عمر رضی اللہ عنہ سے سنا، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم پھل نہ بیچو یہاں تک کہ اس کی صلاحیت ظاہر ہو جائے"}],[3843,"سفیان اور شعبہ دونوں نے عبداللہ بن دینار سے اسی سند کے ساتھ حدیث بیان کی ، شعبہ کی حدیث میں یہ اضافہ ہے کہ ابن عمر رضی اللہ عنہ سے کہا گیا : اس کی صلاحیت سے کیا مراد ہے؟ انہوں نے کہا : اس سے آفت ( بورگر جانے اور بیماری لگ جانے ) کا وقت ختم ہو جائے","",{"u2":"سفیان اور شعبہ دونوں نے عبداللہ بن دینار سے اسی سند کے ساتھ حدیث بیان کی، شعبہ کی حدیث میں یہ اضافہ ہے کہ ابن عمر رضی اللہ عنہ سے کہا گیا: اس کی صلاحیت سے کیا مراد ہے؟ انہوں نے کہا: اس سے آفت (بورگر جانے اور بیماری لگ جانے) کا وقت ختم ہو جائے"}],[3845,"ابوزبیر نے ہمیں سیدنا جابر رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ( اس وقت تک ) درخت پر لگے پھل کو بیچنے سے منع فرمایا ۔ ۔ یا کہا : ہمیں منع فرمایا ۔ ۔ یہاں تک کہ وہ ٹھیک ہو جائے",""],[3846,"عمرو بن دینار نے حدیث بیان کی کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا وہ کہہ رہے تھے : اللہ کے رسول صلی اللہ علیہ وسلم نے ( اس وقت تک ) درخت پر لگے پھل کو بیچنے سے منع فرمایا یہاں تک کہ اس کی صلاحیت ظاہر ہو جائے","",{"u2":"عمرو بن دینار نے حدیث بیان کی کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا وہ کہہ رہے تھے: اللہ کے رسول صلی اللہ علیہ وسلم نے (اس وقت تک) درخت پر لگے پھل کو بیچنے سے منع فرمایا یہاں تک کہ اس کی صلاحیت ظاہر ہو جائے"}],[3847,"ابو بختری سے روایت ہے ، انہوں نے کہا : میں نے سیدنا ابن عباس رضی اللہ عنہ سے کھجور کی بیع کے بارے میں دریافت کیا تو انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے کھجور کی بیع سے منع فرمایا حتی کہ وہ اس سے خود کھا سکے یا وہ کھائے جانے کے قابل ہو جائے ، اور یہاں تک کہ اس کا وزن کیا جا سکے ۔ میں نے کہا : اس کا وزن کیے جانے سے کیا مراد ہے؟ ان کے پاس موجود ایک شخص نے کہا : اس ( کے وزن ) کا اندازہ لگایا جا سکے","",{"u2":"ابو بختری سے روایت ہے، انہوں نے کہا: میں نے سیدنا ابن عباس رضی اللہ عنہ سے کھجور کی بیع کے بارے میں دریافت کیا تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے کھجور کی بیع سے منع فرمایا حتی کہ وہ اس سے خود کھا سکے یا وہ کھائے جانے کے قابل ہو جائے، اور یہاں تک کہ اس کا وزن کیا جا سکے۔ میں نے کہا: اس کا وزن کیے جانے سے کیا مراد ہے؟ ان کے پاس موجود ایک شخص نے کہا: اس (کے وزن) کا اندازہ لگایا جا سکے"}],[3848,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ( درختوں پر لگا ہوا ) پھل نہ خریدو یہاں تک کہ اس کی صلاحیت ظاہر ہو جائے","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(درختوں پر لگا ہوا) پھل نہ خریدو یہاں تک کہ اس کی صلاحیت ظاہر ہو جائے"}],[3849,"ہمیں یحییٰ بن یحییٰ نے حدیث بیان کی ، کہا : ہمیں سفیان بن عیینہ نے زہری سے خبر دی ، نیز ہمیں ابن نمیر اور زہیر بن حرب نے حدیث بیان کی ۔ ۔ الفاظ انہی دونوں کے ہیں ۔ ۔ دونوں نے کہا : ہمیں سفیان نے حدیث بیان کی کہ ہمیں زہری نے سالم سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے ( پکنے کی ) صلاحیت ظاہر ہونے سے پہل ہے پھل کی بیع سے اور پھل کو خشک کھجور کے عوض بیچنے سے منع فرمایا","",{"u2":"ہمیں یحییٰ بن یحییٰ نے حدیث بیان کی، کہا: ہمیں سفیان بن عیینہ نے زہری سے خبر دی، نیز ہمیں ابن نمیر اور زہیر بن حرب نے حدیث بیان کی۔۔ الفاظ انہی دونوں کے ہیں۔۔ دونوں نے کہا: ہمیں سفیان نے حدیث بیان کی کہ ہمیں زہری نے سالم سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے (پکنے کی) صلاحیت ظاہر ہونے سے پہلہے پھل کی بیع سے اور پھل کو خشک کھجور کے عوض بیچنے سے منع فرمایا"}],[3850,"ابن عمر رضی اللہ عنہ نے کہا : ہمیں زید بن ثابت نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع عرایا کی اجازت دی ۔ ابن نمیر نے اپنی روایت میں یہ اضافہ کیا : ( اجازت دی ) کہ اسے بیچا ( یا خریدا ) جائے","",{"u2":"ابن عمر رضی اللہ عنہ نے کہا: ہمیں زید بن ثابت نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع عرایا کی اجازت دی۔ ابن نمیر نے اپنی روایت میں یہ اضافہ کیا: (اجازت دی) کہ اسے بیچا (یا خریدا) جائے"}],[3851,"ابن شہاب سے روایت ہے ، انہوں نے کہا : مجھے سعید بن مسیب اور ابوسلمہ بن عبدالرحمٰن نے حدیث بیان کی کہ سیدنا ابوہریرہ رضی اللہ عنہ نے کہا : اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا : \"\" پھل ( پکنے ) کی صلاحیت ظاہر ہونے سے پہلے مت خریدو اور نہ خشک کھجور کے عوض ( درخت پر لگا ) پھل خریدو ۔ \"\" ابن شہاب نے کہا : مجھے سالم بن عبداللہ بن عمرو نے اپنے والد سے حدیث بیان کی ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، بالکل اسی کے مانند"],[3852,"ابن شہاب سے روایت ہے ، انہوں نے کہا : مجھے سعید بن مسیب اور ابوسلمہ بن عبدالرحمٰن نے حدیث بیان کی کہ سیدنا ابوہریرہ رضی اللہ عنہ نے کہا : اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا : \"\" پھل ( پکنے ) کی صلاحیت ظاہر ہونے سے پہلے مت خریدو اور نہ خشک کھجور کے عوض ( درخت پر لگا ) پھل خریدو ۔ \"\" ابن شہاب نے کہا : مجھے سالم بن عبداللہ بن عمرو نے اپنے والد سے حدیث بیان کی ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، بالکل اسی کے مانند",""],[3853,"ابن شہاب نے سعید بن مسیب سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ اور محاقلہ کی بیع سے منع فرمایا ۔ مزابنہ یہ ہے کہ کھجور پر لگے پھل کو خشک کھجور کے عوض فروخت کیا جائے ، اور محاقلہ یہ ہے کہ کھیتی کو ( کٹنے سے پہلے ) گندم کے عوض فروخت کیا جائے اور زمین کو گندم کے عوض کرائے پر دیا جائے ۔ ( ابن شہاب نے ) کہا : مجھے سالم بن عبداللہ نے رسول اللہ صلی اللہ علیہ وسلم سے خبر دی کہ آپ نے فرمایا : \"\" صلاحیت ظاہر ہونے سے پہلے پھل نہ خریدو ، اور نہ ( درخت پر لگے ) پھل کو خشک کھجور کے عوض خریدو ۔ \"\" سالم نے کہا : مجھے سیدنا عبداللہ رضی اللہ عنہ نے سیدنا زید بن ثابت رضی اللہ عنہ سے خبر دی ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے اس ( ممانعت کے عام حکم ) کے بعد عَرِیہ کی بیع میں تروتازہ یا خشک کھجور کے عوض بیع کی رخصت دی ، اور اس کے سوا کسی بیع میں رخصت نہیں دی"],[3854,"ابن شہاب نے سعید بن مسیب سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ اور محاقلہ کی بیع سے منع فرمایا ۔ مزابنہ یہ ہے کہ کھجور پر لگے پھل کو خشک کھجور کے عوض فروخت کیا جائے ، اور محاقلہ یہ ہے کہ کھیتی کو ( کٹنے سے پہلے ) گندم کے عوض فروخت کیا جائے اور زمین کو گندم کے عوض کرائے پر دیا جائے ۔ ( ابن شہاب نے ) کہا : مجھے سالم بن عبداللہ نے رسول اللہ صلی اللہ علیہ وسلم سے خبر دی کہ آپ نے فرمایا : \"\" صلاحیت ظاہر ہونے سے پہلے پھل نہ خریدو ، اور نہ ( درخت پر لگے ) پھل کو خشک کھجور کے عوض خریدو ۔ \"\" سالم نے کہا : مجھے سیدنا عبداللہ رضی اللہ عنہ نے سیدنا زید بن ثابت رضی اللہ عنہ سے خبر دی ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے اس ( ممانعت کے عام حکم ) کے بعد عَرِیہ کی بیع میں تروتازہ یا خشک کھجور کے عوض بیع کی رخصت دی ، اور اس کے سوا کسی بیع میں رخصت نہیں دی"],[3855,"ابن شہاب نے سعید بن مسیب سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ اور محاقلہ کی بیع سے منع فرمایا ۔ مزابنہ یہ ہے کہ کھجور پر لگے پھل کو خشک کھجور کے عوض فروخت کیا جائے ، اور محاقلہ یہ ہے کہ کھیتی کو ( کٹنے سے پہلے ) گندم کے عوض فروخت کیا جائے اور زمین کو گندم کے عوض کرائے پر دیا جائے ۔ ( ابن شہاب نے ) کہا : مجھے سالم بن عبداللہ نے رسول اللہ صلی اللہ علیہ وسلم سے خبر دی کہ آپ نے فرمایا : \"\" صلاحیت ظاہر ہونے سے پہلے پھل نہ خریدو ، اور نہ ( درخت پر لگے ) پھل کو خشک کھجور کے عوض خریدو ۔ \"\" سالم نے کہا : مجھے سیدنا عبداللہ رضی اللہ عنہ نے سیدنا زید بن ثابت رضی اللہ عنہ سے خبر دی ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے اس ( ممانعت کے عام حکم ) کے بعد عَرِیہ کی بیع میں تروتازہ یا خشک کھجور کے عوض بیع کی رخصت دی ، اور اس کے سوا کسی بیع میں رخصت نہیں دی",""],[3856,"امام مالک نے نافع سے ، انہوں نے ابن عمر رضی اللہ عنہ سے ، انہوں نے سیدنا زید بن ثابت رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے عریہ والے کو اجازت دی کہ وہ اسے ( اس پر موجود پھل کو ) مقدار کا اندازہ کرتے ہوئے خشک کھجور کے عوض بیچ لے","",{"u2":"امام مالک نے نافع سے، انہوں نے ابن عمر رضی اللہ عنہ سے، انہوں نے سیدنا زید بن ثابت رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے عریہ والے کو اجازت دی کہ وہ اسے (اس پر موجود پھل کو) مقدار کا اندازہ کرتے ہوئے خشک کھجور کے عوض بیچ لے"}],[3857,"سلیمان بن بلال نے ہمیں یحییٰ بن سعید سے خبر دی کہا : مجھے نافع نے خبر دی کہ انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے سنا ، وہ حدیث بیان کر رہے تھے کہ سیدنا زید بن ثابت رضی اللہ عنہ نے انہیں حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے عریہ کے بارے میں رخصت دی ( عریہ یہ ہے ) کہ گھر والے ( اپنی طرف سے دیے گئے درخت کے پھل کا ) خشک کھجور کے حوالے سے اندازہ لگا کر اسے لے لیں تاکہ وہ تازہ کھجور کھا سکیں","",{"u2":"سلیمان بن بلال نے ہمیں یحییٰ بن سعید سے خبر دی کہا: مجھے نافع نے خبر دی کہ انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے سنا، وہ حدیث بیان کر رہے تھے کہ سیدنا زید بن ثابت رضی اللہ عنہ نے انہیں حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے عریہ کے بارے میں رخصت دی (عریہ یہ ہے) کہ گھر والے (اپنی طرف سے دیے گئے درخت کے پھل کا) خشک کھجور کے حوالے سے اندازہ لگا کر اسے لے لیں تاکہ وہ تازہ کھجور کھا سکیں"}],[3858,"عبدالوہاب نے ہمیں کہا کہ میں نے یحییٰ بن سعید سے سنا وہ کہہ رہے تھے : مجھے نافع نے اسی سند سے اسی کے مانند خبر دی","",{"u2":"عبدالوہاب نے ہمیں کہا کہ میں نے یحییٰ بن سعید سے سنا وہ کہہ رہے تھے: مجھے نافع نے اسی سند سے اسی کے مانند خبر دی"}],[3859,"ہشیم نے ہمیں یحییٰ بن سعید سے اسی سند کے ساتھ خبر دی ، البتہ انہوں نے کہا : عریہ سے وہ کھجور کا درخت مراد ہے جو لوگوں کو ( بطور عطیہ ) دیا جاتا ہے ۔ وہ ( درخت پر لگے پھل کو ) اندازے کے بقدر خشک کھجوروں کے عوض فروخت کر دیتے ہیں","",{"u2":"ہشیم نے ہمیں یحییٰ بن سعید سے اسی سند کے ساتھ خبر دی، البتہ انہوں نے کہا: عریہ سے وہ کھجور کا درخت مراد ہے جو لوگوں کو (بطور عطیہ) دیا جاتا ہے۔ وہ (درخت پر لگے پھل کو) اندازے کے بقدر خشک کھجوروں کے عوض فروخت کر دیتے ہیں"}],[3860,"لیث نے ہمیں یحییٰ بن سعید سے خبر دی ، انہوں نے نافع سے ، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : مجھے زید بن ثابت رضی اللہ عنہ نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے عریہ کو ( اس سے حاصل ہونے والی ) خشک کھجور کی مقدار کے اندازے سے فروخت کرنے کی اجازت دی ۔ یحییٰ نے کہا : عریہ یہ ہے کہ کوئی آدمی اپنے گھر والوں کی خوراک کے لیے کھجور کا تازہ پھل ( اس سے حاصل ہونے والی ) خشک کھجور کے اندازے کے عوض خرید لے ۔ ( یہ تعریف تازہ پھل لینے والے کے نقطہ نظر سے ہے ۔ مفہوم ایک ہی ہے)","",{"u2":"لیث نے ہمیں یحییٰ بن سعید سے خبر دی، انہوں نے نافع سے، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: مجھے زید بن ثابت رضی اللہ عنہ نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے عریہ کو (اس سے حاصل ہونے والی) خشک کھجور کی مقدار کے اندازے سے فروخت کرنے کی اجازت دی۔\nیحییٰ نے کہا: عریہ یہ ہے کہ کوئی آدمی اپنے گھر والوں کی خوراک کے لیے کھجور کا تازہ پھل (اس سے حاصل ہونے والی) خشک کھجور کے اندازے کے عوض خرید لے۔ (یہ تعریف تازہ پھل لینے والے کے نقطہ نظر سے ہے۔ مفہوم ایک ہی ہے"}],[3861,"عبداللہ بن نمیر نے ہمیں حدیث بیان کی ، کہا : ہمیں عبیداللہ نے حدیث سنائی ، انہوں نے کہا : مجھے نافع نے ابن عمر رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے سیدنا زید بن ثابت رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے عرایا میں رخصت دی کہ اس ( کے پھل ) کا اندازہ کرتے ہوئے اسے کھجور کی ماپی ہوئی مقدار کے عوض فروخت کر دیا جائے","",{"u2":"عبداللہ بن نمیر نے ہمیں حدیث بیان کی، کہا: ہمیں عبیداللہ نے حدیث سنائی، انہوں نے کہا: مجھے نافع نے ابن عمر رضی اللہ عنہ سے حدیث بیان کی، انہوں نے سیدنا زید بن ثابت رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے عرایا میں رخصت دی کہ اس (کے پھل) کا اندازہ کرتے ہوئے اسے کھجور کی ماپی ہوئی مقدار کے عوض فروخت کر دیا جائے"}],[3862,"یحییٰ بن سعید نے عبیداللہ سے اسی سند کے ساتھ حدیث روایت کی ، اور ( فروخت کر دیا جائے کی بجائے ) \" حاصل کر لیا جائے \" کے الفاظ بیان کیے","",{"u2":"یحییٰ بن سعید نے عبیداللہ سے اسی سند کے ساتھ حدیث روایت کی، اور (فروخت کر دیا جائے کی بجائے) \"حاصل کر لیا جائے\" کے الفاظ بیان کیے"}],[3863,"ایوب نے نافع سے اسی سند کے ساتھ روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے عرایا کی بیع میں اس کے اندازے کی مقدار ( کے حساب سے لین دین ) کی اجازت دی","",{"u2":"ایوب نے نافع سے اسی سند کے ساتھ روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے عرایا کی بیع میں اس کے اندازے کی مقدار (کے حساب سے لین دین) کی اجازت دی"}],[3864,"سلیمان بن بلال نے ہمیں یحییٰ بن سعید سے حدیث بیان کی ، انہوں نے بُشیر بن یسار سے ، انہوں نے اپنے گھرانے سے تعلق رکھنے والے رسول اللہ صلی اللہ علیہ وسلم کے بعض صحابہ سے ، جن میں سہل بن ابی حثمہ رضی اللہ عنہ بھی شامل ہیں ، روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ( درخت پر لگے ) پھل کو خشک کھجور کے عوض فروخت کرنے سے منع فرمایا ۔ اور آپ نے فرمایا : \" یہ سود ہے ، یہی ( بیع ) مزابنہ ( کھجور کے درخت پر لگے ہوئے پھل کو خشک کھجور کے عوض فروخت کرنا ) ہے ۔ \" ہاں ، البتہ آپ نے عریہ کو بیچنے یا خریدنے کی اجازت دی ( عَرِیہ یہ ہے ) کہ کوئی خاندان ایک دو کھجور کے درخت ( جو بطور عطیہ دے گئے ) ان سے حاصل ہونے والی خشک کھجور کے اندازے کے مطابق لے لیں تاکہ وہ اس کا تازہ پھل کھائیں ( اور جنہیں درخت دیے گئے ہیں ، انہیں خشک کھجور دے دیں)","",{"u2":"سلیمان بن بلال نے ہمیں یحییٰ بن سعید سے حدیث بیان کی، انہوں نے بُشیر بن یسار سے، انہوں نے اپنے گھرانے سے تعلق رکھنے والے رسول اللہ صلی اللہ علیہ وسلم کے بعض صحابہ سے، جن میں سہل بن ابی حثمہ رضی اللہ عنہ بھی شامل ہیں، روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے (درخت پر لگے) پھل کو خشک کھجور کے عوض فروخت کرنے سے منع فرمایا۔ اور آپ نے فرمایا: \"یہ سود ہے، یہی (بیع) مزابنہ (کھجور کے درخت پر لگے ہوئے پھل کو خشک کھجور کے عوض فروخت کرنا) ہے۔\" ہاں، البتہ آپ نے عریہ کو بیچنے یا خریدنے کی اجازت دی (عَرِیہ یہ ہے) کہ کوئی خاندان ایک دو کھجور کے درخت (جو بطور عطیہ دے گئے) ان سے حاصل ہونے والی خشک کھجور کے اندازے کے مطابق لے لیں تاکہ وہ اس کا تازہ پھل کھائیں (اور جنہیں درخت دیے گئے ہیں، انہیں خشک کھجور دے دیں"}],[3865,"لیث نے ہمیں یحییٰ بن سعید سے خبر دی ، انہوں نے بُشیر بن یسار سے اور انہوں نے اللہ کے رسول صلی اللہ علیہ وسلم کے ( بعض ) صحابہ سے روایت کی کہ انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے عریہ کو ( اس سے حاصل ہونے ولی ) خشک کھجور کی مقدار کے اندازے سے فروخت کرنے کی اجازت دی","",{"u2":"لیث نے ہمیں یحییٰ بن سعید سے خبر دی، انہوں نے بُشیر بن یسار سے اور انہوں نے اللہ کے رسول صلی اللہ علیہ وسلم کے (بعض) صحابہ سے روایت کی کہ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے عریہ کو (اس سے حاصل ہونے ولی) خشک کھجور کی مقدار کے اندازے سے فروخت کرنے کی اجازت دی"}],[3866,"محمد بن مثنیٰ ، اسحاق بن ابراہیم اور ابن ابی عمر سب نے ( عبدالوہاب ) ثقفی سے روایت کی ، انہوں نے کہا : میں نے یحییٰ بن سعید سے سنا وہ کہہ رہے تھے : مجھے بشیر بن یسار نے اپنے خاندان سے تعلق رکھنے والے رسول اللہ صلی اللہ علیہ وسلم کے بعض اصحاب سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ۔ آگے یحییٰ سے سلیمان بن بلال کی حدیث ( 3887 ) کے مانند حدیث ذکر کی ۔ لیکن اسحاق اور ابن مثنیٰ نے لفظ ربا کی بجائے لفظ زبن ( مزابنہ ) استعمال کیا ہے ، تاہم ابن ابی عمر نے رِبا ہی کہا","",{"u2":"محمد بن مثنیٰ، اسحاق بن ابراہیم اور ابن ابی عمر سب نے (عبدالوہاب) ثقفی سے روایت کی، انہوں نے کہا: میں نے یحییٰ بن سعید سے سنا وہ کہہ رہے تھے: مجھے بشیر بن یسار نے اپنے خاندان سے تعلق رکھنے والے رسول اللہ صلی اللہ علیہ وسلم کے بعض اصحاب سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا۔ آگے یحییٰ سے سلیمان بن بلال کی حدیث (3887) کے مانند حدیث ذکر کی۔ لیکن اسحاق اور ابن مثنیٰ نے لفظ ربا کی بجائے لفظ زبن (مزابنہ) استعمال کیا ہے، تاہم ابن ابی عمر نے رِبا ہی کہا"}],[3867,"سفیان بن عیینہ نے ہمیں یحییٰ بن سعید سے حدیث بیان کی ، انہوں نے بشیر بن یسار سے ، انہوں نے سہل بن ابی حثمہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ۔ ۔ ۔ انہی ( سلیمان ، لیث اور ثقفی ) کی حدیث کے ہم معنی","",{"u2":"سفیان بن عیینہ نے ہمیں یحییٰ بن سعید سے حدیث بیان کی، انہوں نے بشیر بن یسار سے، انہوں نے سہل بن ابی حثمہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی۔۔۔ انہی (سلیمان، لیث اور ثقفی) کی حدیث کے ہم معنی"}],[3868,"ولید بن کثیر نے کہا : مجھے بنو حارثہ کے مولیٰ بشیر بن یسار نے حدیث بیان کی کہ رافع بن خدیج اور سہل بن ابی حثمہ رضی اللہ عنہ دونوں نے اسے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ ، یعنی تازہ کھجور کی خشک کھجور کے عوض بیع سے منع فرمایا ، سوائے عرایا والوں کے کیونکہ انہیں آپ صلی اللہ علیہ وسلم نے اجازت دی تھی","",{"u2":"ولید بن کثیر نے کہا: مجھے بنو حارثہ کے مولیٰ بشیر بن یسار نے حدیث بیان کی کہ رافع بن خدیج اور سہل بن ابی حثمہ رضی اللہ عنہ دونوں نے اسے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ، یعنی تازہ کھجور کی خشک کھجور کے عوض بیع سے منع فرمایا، سوائے عرایا والوں کے کیونکہ انہیں آپ صلی اللہ علیہ وسلم نے اجازت دی تھی"}],[3869,"یحییٰ بن یحییٰ نے کہا : میں نے امام مالک سے پوچھا : کیا آپ کو داود بن حصین نے ابن ابی احمد کے آزاد کردہ غلام ابوسفیان ( وہب ) سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے عرایا کو پانچ وسق سے کم یا پانچ وسق تک اندازے سے بیچنے کی رخصت دی ہے؟ ۔ ۔ ( امام مسلم رحمۃ اللہ علیہ نے کہا : ) شک داود کو ہے کہ انہوں ( ابوسفیان ) نے پانچ وسق کہا یا پانچ وسق سے کم کہا ۔ ۔ تو انہوں ( امام مالک ) نے جواب دیا : ہاں","",{"u2":"یحییٰ بن یحییٰ نے کہا: میں نے امام مالک سے پوچھا: کیا آپ کو داود بن حصین نے ابن ابی احمد کے آزاد کردہ غلام ابوسفیان (وہب) سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے عرایا کو پانچ وسق سے کم یا پانچ وسق تک اندازے سے بیچنے کی رخصت دی ہے؟۔۔ (امام مسلم رحمۃ اللہ علیہ نے کہا:) شک داود کو ہے کہ انہوں (ابوسفیان) نے پانچ وسق کہا یا پانچ وسق سے کم کہا۔۔ تو انہوں (امام مالک) نے جواب دیا: ہاں"}],[3870,"امام مالک نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ سے منع فرمایا اور مزابنہ سے مراد ( کھجور کے تازہ ) پھل کو خشک کھجور کی ماپی ( یا تولی ہوئی ) مقدار کے عوض اور انگور کو منقیٰ کی ماپی ( یا تولی ہوئی ) مقدار کے عوض فروخت کرنا ہے","",{"u2":"امام مالک نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ سے منع فرمایا اور مزابنہ سے مراد (کھجور کے تازہ) پھل کو خشک کھجور کی ماپی (یا تولی ہوئی) مقدار کے عوض اور انگور کو منقیٰ کی ماپی (یا تولی ہوئی) مقدار کے عوض فروخت کرنا ہے"}],[3871,"محمد بن بشیر نے کہا : ہمیں عبیداللہ نے نافع سے حدیث بیان کی کہ سیدنا عبداللہ ( بن عمر رضی اللہ عنہ ) نے انہیں خبر دی کہ نبی صلی اللہ علیہ وسلم نے مزابنہ سے منع فرمایا ، اور مزابنہ یہ ہے کہ کھجور کے تازہ پھل کو خشک کھجور کی ماپی ہوئی مقدار کے عوض بیچا جائے اور انگور کو منقیٰ کی ماپی ہوئی مقدار کے عوض بیچا جائے اور ( خوشیوں میں ) گندم کی کھیتی کو ماپی ہوئی مقدار کے عوض بیچا جائے","",{"u2":"محمد بن بشیر نے کہا: ہمیں عبیداللہ نے نافع سے حدیث بیان کی کہ حضرت عبداللہ (بن عمر رضی اللہ عنہ) نے انہیں خبر دی کہ نبی صلی اللہ علیہ وسلم نے مزابنہ سے منع فرمایا، اور مزابنہ یہ ہے کہ کھجور کے تازہ پھل کو خشک کھجور کی ماپی ہوئی مقدار کے عوض بیچا جائے اور انگور کو منقیٰ کی ماپی ہوئی مقدار کے عوض بیچا جائے اور (خوشیوں میں) گندم کی کھیتی کو ماپی ہوئی مقدار کے عوض بیچا جائے"}],[3872,"ابن ابی زائدہ نے عبیداللہ سے اسی سند کے ساتھ اسی کے مانند روایت کی","",{"u2":"ابن ابی زائدہ نے عبیداللہ سے اسی سند کے ساتھ اسی کے مانند روایت کی"}],[3873,"ابو اسامہ نے ہم سے بیان کیا ، کہا : ہمیں عبیداللہ نے نافع سے حدیث بیان کی ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ سے منع فرمایا ۔ اور مزابنہ یہ ہے کہ کھجور کے ( تازہ ) پھل کو خشک کھجور کے ماپ کی مقررہ مقدار کے عوض اور انگور کو منقیٰ کے ماپ کی مقررہ مقدار کے عوض فروخت کیا جائے اور کسی بھی پھل کو اندازے کی بنیاد پر ( اسی طرح ) فروخت کرنے سے منع فرمایا","",{"u2":"ابو اسامہ نے ہم سے بیان کیا، کہا: ہمیں عبیداللہ نے نافع سے حدیث بیان کی، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ سے منع فرمایا۔ اور مزابنہ یہ ہے کہ کھجور کے (تازہ) پھل کو خشک کھجور کے ماپ کی مقررہ مقدار کے عوض اور انگور کو منقیٰ کے ماپ کی مقررہ مقدار کے عوض فروخت کیا جائے اور کسی بھی پھل کو اندازے کی بنیاد پر (اسی طرح) فروخت کرنے سے منع فرمایا"}],[3874,"اسماعیل بن ابراہیم نے ہمیں ایوب سے حدیث بیان کی ، انہوں نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ سے منع فرمایا اور مزابنہ یہ ہے کہ کھجور پر جو پھل لگا ہوا ہے اسے ماپ کی مقررہ مقدار کے ساتھ خشک کھجور کے عوض بیچا جائے کہ اگر بڑھ گیا تو میرا اور اگر کم ہو گیا تو اس کی ذمہ داری بھی مجھ پر ہو گی","",{"u2":"اسماعیل بن ابراہیم نے ہمیں ایوب سے حدیث بیان کی، انہوں نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ سے منع فرمایا اور مزابنہ یہ ہے کہ کھجور پر جو پھل لگا ہوا ہے اسے ماپ کی مقررہ مقدار کے ساتھ خشک کھجور کے عوض بیچا جائے کہ اگر بڑھ گیا تو میرا اور اگر کم ہو گیا تو اس کی ذمہ داری بھی مجھ پر ہو گی"}],[3875,"حماد نے ایوب سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی","",{"u2":"حماد نے ایوب سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی"}],[3876,"قتیبہ بن سعید اور محمد بن رُمح نے لیث سے حدیث بیان کی ، انہوں نے نافع سے ، انہوں نے سیدنا عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ سے منع فرمایا ( مزابنہ یہ ہے ) کہ کوئی آدمی اپنے باغ کا پھل اگر کھجور ہو تو خشک کھجور کے مقررہ ماپ کے عوض فروخت کرے اور اگر انگور ہو تو منقیٰ کے مقررہ ماپ کے عوض فروخت کرے اور اگر کھیتی ہو تو غلے کے مقررہ ماپ کے عوض اسے فروخت کرے ۔ آپ صلی اللہ علیہ وسلم نے ان سب ( سودوں ) سے منع فرمایا ۔ قتیبہ کی روایت میں ( وان كان زرعا \"\" اور اگر کھیتی ہو \"\" کے بجائے ) \"\" یا کھیتی ہو \"\" کے الفاظ ہیں ۔","",{"u2":"قتیبہ بن سعید اور محمد بن رُمح نے لیث سے حدیث بیان کی، انہوں نے نافع سے، انہوں نے سیدنا عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ سے منع فرمایا (مزابنہ یہ ہے) کہ کوئی آدمی اپنے باغ کا پھل اگر کھجور ہو تو خشک کھجور کے مقررہ ماپ کے عوض فروخت کرے اور اگر انگور ہو تو منقیٰ کے مقررہ ماپ کے عوض فروخت کرے اور اگر کھیتی ہو تو غلے کے مقررہ ماپ کے عوض اسے فروخت کرے۔ آپ صلی اللہ علیہ وسلم نے ان سب (سودوں) سے منع فرمایا۔\nقتیبہ کی روایت میں (وان کان زرعا \"اور اگر کھیتی ہو\" کے بجائے) \"یا کھیتی ہو\" کے الفاظ ہیں۔"}],[3877,"یونس ، ضحاک اور موسیٰ بن عقبہ سب نے نافع سے اسی سند کے ساتھ ان ( عبیداللہ ، ایوب اور لیث ) کی حدیث کی طرح حدیث بیان کی","",{"u2":"یونس، ضحاک اور موسیٰ بن عقبہ سب نے نافع سے اسی سند کے ساتھ ان (عبیداللہ، ایوب اور لیث) کی حدیث کی طرح حدیث بیان کی"}],[3878,"یحییٰ بن یحییٰ نے کہا : میں نے امام مالک کے سامنے قراءت کی ، انہوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے کھجور کا ایسا درخت فروخت کیا جس پر نر کھجور کا بورڈ ڈالا گیا ہو تو اس کا پھل فروخت کرنے والے کا ہے الا یہ کہ خریدار ( بیع کے دوران میں ) شرط طے کر لے","",{"u2":"یحییٰ بن یحییٰ نے کہا: میں نے امام مالک کے سامنے قراءت کی، انہوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کھجور کا ایسا درخت فروخت کیا جس پر نر کھجور کا بورڈ ڈالا گیا ہو تو اس کا پھل فروخت کرنے والے کا ہے الا یہ کہ خریدار (بیع کے دوران میں) شرط طے کر لے"}],[3879,"عبیداللہ نے ہمیں نافع سے حدیث بیان کی اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کھجور کا جو درخت خریدا گیا اور اس کی تابیر کی گئی تھی تو اس کا پھل اسی کے لیے ہے جس نے تابیر کی ، مگر یہ کہ وہ آدمی جس نے اسے خریدا ( سودے میں اس کی ) شرط طے کر لے","",{"u2":"عبیداللہ نے ہمیں نافع سے حدیث بیان کی اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کھجور کا جو درخت خریدا گیا اور اس کی تابیر کی گئی تھی تو اس کا پھل اسی کے لیے ہے جس نے تابیر کی، مگر یہ کہ وہ آدمی جس نے اسے خریدا (سودے میں اس کی) شرط طے کر لے"}],[3880,"لیث نے ہمیں نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \" جس نے کھجور کی تابیر ( نر کھجور کا بور ڈال کر اس کی پرداخت ) کی پھر اس کے درخت کو بیچ دیا ، تو کھجور کا پھل اسی کا ہے جس نے تابیر کی ، الا یہ کہ خریدنے والا شرط طے کر لے","",{"u2":"لیث نے ہمیں نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کھجور کی تابیر (نر کھجور کا بور ڈال کر اس کی پرداخت) کی پھر اس کے درخت کو بیچ دیا، تو کھجور کا پھل اسی کا ہے جس نے تابیر کی، الا یہ کہ خریدنے والا شرط طے کر لے"}],[3881,"ایوب نے نافع سے اسی سند کے ساتھ اسی طرح روایت کی","",{"u2":"ایوب نے نافع سے اسی سند کے ساتھ اسی طرح روایت کی"}],[3882,"لیث نے ہمیں ابن شہاب سے خبر دی ، انہوں نے سالم بن عبداللہ بن عمر سے اور انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ فرما رہے تھے : \" جس نے تابیر کیے جانے کے بعد کھجور کا درخت خریدا ، تو اس کا پھل اسی کا ہے جس نے اسے بیچا ، الا یہ کہ خریدار شرط طے کر لے اور جس نے غلام خریدا تو اسی کا مال اسی کا ہے جس نے اسے فروخت کیا ، الا یہ کہ خریدار شرط طے کر لے","",{"u2":"لیث نے ہمیں ابن شہاب سے خبر دی، انہوں نے سالم بن عبداللہ بن عمر سے اور انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ فرما رہے تھے: \"جس نے تابیر کیے جانے کے بعد کھجور کا درخت خریدا، تو اس کا پھل اسی کا ہے جس نے اسے بیچا، الا یہ کہ خریدار شرط طے کر لے اور جس نے غلام خریدا تو اسی کا مال اسی کا ہے جس نے اسے فروخت کیا، الا یہ کہ خریدار شرط طے کر لے"}],[3883,"سفیان بن عیینہ نے زہری سے اسی سند کے ساتھ اسی کے مانند روایت کی","",{"u2":"سفیان بن عیینہ نے زہری سے اسی سند کے ساتھ اسی کے مانند روایت کی"}],[3884,"یونس نے مجھے ابن شہاب سے خبر دی ، کہا : مجھے سالم بن عبداللہ بن عمر نے حدیث بیان کی کہ ان کے والد نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے ۔ ۔ ۔ اسی کے مانند","",{"u2":"یونس نے مجھے ابن شہاب سے خبر دی، کہا: مجھے سالم بن عبداللہ بن عمر نے حدیث بیان کی کہ ان کے والد نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے۔۔۔ اسی کے مانند"}],[3885,"سفیان بن عیینہ نے ہمیں ابن جریج سے حدیث بیان کی ، انہوں نے عطاء سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے محاقالہ ، مزابنہ ، مخابرہ اور ( پکنے کی ) صلاحیت ظاہر ہونے سے پہلے پھلوں کی بیع سے منع فرمایا اور ( حکم دیا کہ ) عرایا ( کی بیع ) کے سوا ( پھل یا کھیتی کو ) صرف دینار اور درہم کے عوض ہی فروخت کیا جائے","",{"u2":"سفیان بن عیینہ نے ہمیں ابن جریج سے حدیث بیان کی، انہوں نے عطاء سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے محاقالہ، مزابنہ، مخابرہ اور (پکنے کی) صلاحیت ظاہر ہونے سے پہلے پھلوں کی بیع سے منع فرمایا اور (حکم دیا کہ) عرایا (کی بیع) کے سوا (پھل یا کھیتی کو) صرف دینار اور درہم کے عوض ہی فروخت کیا جائے\nسفیان بن عیینہ نے ہمیں ابن جریج سے حدیث بیان کی، انہوں نے عطاء سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے محاقالہ، مزابنہ، مخابرہ اور (پکنے کی) صلاحیت ظاہر ہونے سے پہلے پھلوں کی بیع سے منع فرمایا اور (حکم دیا کہ) عرایا (کی بیع) کے سوا (پھل یا کھیتی کو) صرف دینار اور درہم کے عوض ہی فروخت کیا جائے"}],[3886,"ابوعاصم نے ہمیں خبر دی ، کہا : ہمیں ابن جریج نے عطاء اور ابوزبیر سے خبر دی ، ان دونوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ۔ ۔ ۔ آگے اسی کے مانند بیان کیا","",{"u2":"ابوعاصم نے ہمیں خبر دی، کہا: ہمیں ابن جریج نے عطاء اور ابوزبیر سے خبر دی، ان دونوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا۔۔۔ آگے اسی کے مانند بیان کیا"}],[3887,"مخلد بن یزید جزری نے ہمیں خبر دی ، کہا : ہمیں ابن جریج نے حدیث سنائی ، انہوں نے کہا : مجھے عطاء نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے مخابرہ ، محاقلہ ، مزابنہ اور کھانے کے قابل ہونے سے پہلے پھلوں کی فروخت کرنے سے منع فرمایا اور ( حکم دیا کہ پھلوں اور اجناس کی ) صرف درہم و دینار ہی سے بیع کی جائے ، سوائے عرایا کے ۔ عطاء نے کہا : سیدنا جابر رضی اللہ عنہ نے ان الفاظ کی وضاحت کرتے ہوئے کہا : مخابرہ سے مراد وہ چٹیل زمین ہے جو ایک آدمی دوسرے کے حوالے کرے تو وہ اس میں خرچ کرے ، پھر وہ ( زمین دینے والا ) اس کی پیداوار میں سے حصہ لے ۔ اور ان کا خیال ہے کہ مزابنہ سے مراد کھجور پر لگی ہوئی تازہ کھجور کی خشک کھجور ( کی معینہ مقدار ) کے عوض بیع ہے اور محاقلہ یہ ہے کہ آدمی کھڑی فصل کو ماپے ہوئے غلے کے عوض بیچ دے","",{"u2":"مخلد بن یزید جزری نے ہمیں خبر دی، کہا: ہمیں ابن جریج نے حدیث سنائی، انہوں نے کہا: مجھے عطاء نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے مخابرہ، محاقلہ، مزابنہ اور کھانے کے قابل ہونے سے پہلے پھلوں کی فروخت کرنے سے منع فرمایا اور (حکم دیا کہ پھلوں اور اجناس کی) صرف درہم و دینار ہی سے بیع کی جائے، سوائے عرایا کے۔\nعطاء نے کہا: سیدنا جابر رضی اللہ عنہ نے ان الفاظ کی وضاحت کرتے ہوئے کہا: مخابرہ سے مراد وہ چٹیل زمین ہے جو ایک آدمی دوسرے کے حوالے کرے تو وہ اس میں خرچ کرے، پھر وہ (زمین دینے والا) اس کی پیداوار میں سے حصہ لے۔ اور ان کا خیال ہے کہ مزابنہ سے مراد کھجور پر لگی ہوئی تازہ کھجور کی خشک کھجور (کی معینہ مقدار) کے عوض بیع ہے اور محاقلہ یہ ہے کہ آدمی کھڑی فصل کو ماپے ہوئے غلے کے عوض بیچ دے"}],[3888,"زید بن ابی انیسہ سے روایت ہے ، انہوں نے کہا : ہم سے ابوولید مکی نے حدیث بیان کی جبکہ وہ عطاء بن ابی رباح کے پاس بیٹھے ہوئے تھے ، انہوں ( زید ) نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے محاقلہ ، مزابنہ ، مخابرہ اور اس بات سے منع فرمایا ہے کہ اِشقاہ سے پہلے ( درخت پر لگا ہوا ) کھجور ( کا پھل ) خریدا جائے ۔ اِشقاہ یہ ہے کہ اس میں سرخی یا زردی پیدا ہو جائے یا اس میں سے کچھ کھایا جا سکے 0سارا پھل بیک وقت نہیں بکتا ، کچھ کھانے کے قابل ہو جائے تو بیع جائز ہے ۔ ) اور محاقلہ یہ ہے کہ کھیتی کی بیع غلے کی متعین مقدار ( صاع ، وسق وغیرہ یا وزن ) کے ساتھ کی جائے اور مزابنہ یہ ہے کہ درخت پر لگی کھجور کی بیع خشک کھجور کی ( ماپ یا تول کے ذریعے سے ) متعین مقدار کے ساتھ کی جائے اور مخابرہ یہ ہے کہ زمین کو ( جواز کی شروط پوری کیے بغیر ) تہائی ، چوتھائی یا اس طرح کے ( کسی متعین ) حصے کے عوض ( بٹائی پر ) دیا جائے ۔ زید نے کہا : میں نے ( ساتھ بیٹھے ) عطاء بن ابی رباح رحمۃ اللہ علیہ سے پوچھا : کیا آپ نے ( بھی ) سیدنا جابر بن عبداللہ رضی اللہ عنہ کو رسول اللہ صلی اللہ علیہ وسلم سے یہ حدیث بیان کرتے ہوئے سنا؟ انہوں نے جواب دیا : ہاں","",{"u2":"زید بن ابی انیسہ سے روایت ہے، انہوں نے کہا: ہم سے ابوولید مکی نے حدیث بیان کی جبکہ وہ عطاء بن ابی رباح کے پاس بیٹھے ہوئے تھے، انہوں (زید) نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے محاقلہ، مزابنہ، مخابرہ اور اس بات سے منع فرمایا ہے کہ اِشقاہ سے پہلے (درخت پر لگا ہوا) کھجور (کا پھل) خریدا جائے۔ اِشقاہ یہ ہے کہ اس میں سرخی یا زردی پیدا ہو جائے یا اس میں سے کچھ کھایا جا سکے 0سارا پھل بیک وقت نہیں بکتا، کچھ کھانے کے قابل ہو جائے تو بیع جائز ہے۔) اور محاقلہ یہ ہے کہ کھیتی کی بیع غلے کی متعین مقدار (صاع، وسق وغیرہ یا وزن) کے ساتھ کی جائے اور مزابنہ یہ ہے کہ درخت پر لگی کھجور کی بیع خشک کھجور کی (ماپ یا تول کے ذریعے سے) متعین مقدار کے ساتھ کی جائے اور مخابرہ یہ ہے کہ زمین کو (جواز کی شروط پوری کیے بغیر) تہائی، چوتھائی یا اس طرح کے (کسی متعین) حصے کے عوض (بٹائی پر) دیا جائے۔\nزید نے کہا: میں نے (ساتھ بیٹھے) عطاء بن ابی رباح رحمۃ اللہ علیہ سے پوچھا: کیا آپ نے (بھی) سیدنا جابر بن عبداللہ رضی اللہ عنہ کو رسول اللہ صلی اللہ علیہ وسلم سے یہ حدیث بیان کرتے ہوئے سنا؟ انہوں نے جواب دیا: ہاں"}],[3889,"سلیم بن حیان نے ہمیں حدیث بیان کی ، کہا : ہمیں سعید بن میناء نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ ، محاقلہ ، مخابرہ اور رنگ تبدیل ہونے ( اشقاح ) سے پہلے پھلوں کی بیع سے منع فرمایا ۔ ( سلیم بن حیان نے ) کہا : میں نے سعید سے پوچھا : اشقاح سے کیا مراد ہے؟ انہوں نے کہا : ان میں سرخی اور زردی پیدا ہو جائے اور اس میں سے کھایا جا سکے","",{"u2":"سلیم بن حیان نے ہمیں حدیث بیان کی، کہا: ہمیں سعید بن میناء نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ، محاقلہ، مخابرہ اور رنگ تبدیل ہونے (اشقاح) سے پہلے پھلوں کی بیع سے منع فرمایا۔\n(سلیم بن حیان نے) کہا: میں نے سعید سے پوچھا: اشقاح سے کیا مراد ہے؟ انہوں نے کہا: ان میں سرخی اور زردی پیدا ہو جائے اور اس میں سے کھایا جا سکے"}],[3890,"حماد بن زید نے ہمیں حدیث بیان کی ، کہا : ہمیں ایوب نے ابوزبیر اور سعید بن میناء سے حدیث بیان کی ، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے محاقلہ ، مزابنہ ، معاومہ ، مخابرہ ۔ ۔ ان دونوں ( ابوزبیر اور سعید ) میں سے ایک نے کہا : کئی سالوں کے لیے بیع کرنا ہی معاومہ ہے ۔ اور استثاء والی بیر سے منع فرمایا اور عرایا ( کو خشک پھل کے عوض بیچنے ) کی اجازت دی","",{"u2":"حماد بن زید نے ہمیں حدیث بیان کی، کہا: ہمیں ایوب نے ابوزبیر اور سعید بن میناء سے حدیث بیان کی، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے محاقلہ، مزابنہ، معاومہ، مخابرہ۔۔ ان دونوں (ابوزبیر اور سعید) میں سے ایک نے کہا: کئی سالوں کے لیے بیع کرنا ہی معاومہ ہے۔ اور استثاء والی بیر سے منع فرمایا اور عرایا (کو خشک پھل کے عوض بیچنے) کی اجازت دی"}],[3891,"اسماعیل بن علیہ نے ہمیں ایوب سے حدیث بیان کی ، انہوں نے ابوزبیر سے ، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ۔ ۔ اسی کے مانند ، البتہ انہوں نے یہ ذکر نہیں کیا کہ کئی سالوں کے لیے بیع کرنا ہی معاومہ ہے","",{"u2":"اسماعیل بن علیہ نے ہمیں ایوب سے حدیث بیان کی، انہوں نے ابوزبیر سے، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی۔۔ اسی کے مانند، البتہ انہوں نے یہ ذکر نہیں کیا کہ کئی سالوں کے لیے بیع کرنا ہی معاومہ ہے"}],[3892,"رباح بن ابی معروف نے ہمیں حدیث بیان کی ، انہوں نے کہا : میں نے عطاء سے سنا ، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے زمین کو ( اس کی اپنی پیداوار کے بدلے کرائے پر دینے ، اس ( کے پھل ) کو کئی سالوں کے لیے بیچنے اور پکنے سے پہلے پھلوں کی بیع سے منع فرمایا","",{"u2":"رباح بن ابی معروف نے ہمیں حدیث بیان کی،انہوں نے کہا: میں نے عطاء سے سنا، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے زمین کو (اس کی اپنی پیداوار کے بدلے کرائے پر دینے، اس (کے پھل) کو کئی سالوں کے لیے بیچنے اور پکنے سے پہلے پھلوں کی بیع سے منع فرمایا"}],[3893,"حماد بن زید نے ہمیں مطروراق سے حدیث بیان کی ، انہوں نے عطاء سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کو کرائے پر دینے سے منع فرمایا","",{"u2":"حماد بن زید نے ہمیں مطروراق سے حدیث بیان کی، انہوں نے عطاء سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کو کرائے پر دینے سے منع فرمایا"}],[3894,"مہدی بن میمون نے ہمیں حدیث بیان کی ، کہا : ہمیں مطروراق نے عطاء سے حدیث بیان کی ، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس شخص کی زمین ہو تو ( بہتر ہے ) وہ اسے خود کاشت کرے ۔ اگر وہ خود کاشت نہ کرے تو اپنے بھائی کو کاشت کاری کے لیے دے دے","",{"u2":"مہدی بن میمون نے ہمیں حدیث بیان کی، کہا: ہمیں مطروراق نے عطاء سے حدیث بیان کی، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص کی زمین ہو تو (بہتر ہے) وہ اسے خود کاشت کرے۔ اگر وہ خود کاشت نہ کرے تو اپنے بھائی کو کاشت کاری کے لیے دے دے"}],[3895,"اوزاعی نے عطاء سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے کچھ صحابہ کے پاس ضرورت سے زائد زمینیں تھیں تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس کے پاس ضرورت سے زائد زمین ہو وہ یا تو اسے خود کاشت کرے یا اپنے بھائی کو عاریتا دے دے ۔ اگر وہ نہیں مانتا تو وہ اپنی زمین اپنے پاس رکھ لے ۔ \" ( کسی غیر شرعی طریقے سے کرائے پر نہ دے)","",{"u2":"اوزاعی نے عطاء سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے کچھ صحابہ کے پاس ضرورت سے زائد زمینیں تھیں تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کے پاس ضرورت سے زائد زمین ہو وہ یا تو اسے خود کاشت کرے یا اپنے بھائی کو عاریتا دے دے۔ اگر وہ نہیں مانتا تو وہ اپنی زمین اپنے پاس رکھ لے۔\" (کسی غیر شرعی طریقے سے کرائے پر نہ دے"}],[3896,"بکیر بن اخنس نے عطاء سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ زمین کی اجرت ( کرایہ ) یا ( اس کی ہونے والی پیداوار کا ) متعین ( مقدار میں ) حصہ لیا جائے","",{"u2":"بکیر بن اخنس نے عطاء سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ زمین کی اجرت (کرایہ) یا (اس کی ہونے والی پیداوار کا) متعین (مقدار میں) حصہ لیا جائے"}],[3897,"عبدالملک نے ہمیں عطاء سے حدیث بیان کی اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس کے پاس زمین ہو ، وہ اسے خود کاشت کرے ، اگر وہ اس میں کاشتکاری کی استطاعت نہ پائے اور عاجز ہو تو ( بہتر ہے ) اپنے کسی مسلمان بھائی کو عاریتا دے دے اور اس کے ساتھ زمین کی اجرت کا معاملہ نہ کرے","",{"u2":"عبدالملک نے ہمیں عطاء سے حدیث بیان کی اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کے پاس زمین ہو، وہ اسے خود کاشت کرے، اگر وہ اس میں کاشتکاری کی استطاعت نہ پائے اور عاجز ہو تو (بہتر ہے) اپنے کسی مسلمان بھائی کو عاریتا دے دے اور اس کے ساتھ زمین کی اجرت کا معاملہ نہ کرے"}],[3898,"ہمام نے حدیث بیان کی ، کہا : سلیمان بن موسیٰ نے عطاء سے سوال کیا اور کہا : کیا آپ کو سیدنا جابر بن عبداللہ رضی اللہ عنہ نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس کے پاس زمین ہو ( تو بہتر ہے ) وہ اسے کاشت کرے یا اپنے بھائی کو کاشتکاری کے لیے دے دے اور اسے کرائے پر نہ دے؟ \" انہوں نے جواب دیا : ہاں","",{"u2":"ہمام نے حدیث بیان کی، کہا: سلیمان بن موسیٰ نے عطاء سے سوال کیا اور کہا: کیا آپ کو سیدنا جابر بن عبداللہ رضی اللہ عنہ نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کے پاس زمین ہو (تو بہتر ہے) وہ اسے کاشت کرے یا اپنے بھائی کو کاشتکاری کے لیے دے دے اور اسے کرائے پر نہ دے؟\" انہوں نے جواب دیا: ہاں"}],[3899,"عمرو ( بن دینار ) نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے مخابرہ ( غلط شرطوں کے ساتھ بٹائی پر دینے ) سے منع فرمایا","",{"u2":"عمرو (بن دینار) نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے مخابرہ (غلط شرطوں کے ساتھ بٹائی پر دینے) سے منع فرمایا"}],[3900,"سعید بن میناء نے ہمیں حدیث بیان کی ، انہوں نے کہا : میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس کے پاس فالتو زمین ہو وہ اسے خود کاشت کرے یا اپنے بھائی کو کاشتکاری کے لیے دے دے اور اسے ( استفادے کے لیے ) فروخت نہ کرو ۔ \" میں ( سلیم بن حیان ) نے سعید سے پوچھا : \" اسے فروخت نہ کرو \" سے کیا مراد ہے؟ کیا آپ کی مراد کرایہ پر دینے سے تھی؟ انہوں نے جواب دیا : ہاں","",{"u2":"سعید بن میناء نے ہمیں حدیث بیان کی، انہوں نے کہا: میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کے پاس فالتو زمین ہو وہ اسے خود کاشت کرے یا اپنے بھائی کو کاشتکاری کے لیے دے دے اور اسے (استفادے کے لیے) فروخت نہ کرو۔\" میں (سلیم بن حیان) نے سعید سے پوچھا: \"اسے فروخت نہ کرو\" سے کیا مراد ہے؟ کیا آپ کی مراد کرایہ پر دینے سے تھی؟ انہوں نے جواب دیا: ہاں"}],[3901,"زہیر نے ہمیں حدیث بیان کی ، کہا : ابوزبیر نے ہمیں سیدنا جابر رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں زمین بٹائی پر دیتے اور ( باقی ساری پیداوار میں سے حصے کے علاوہ ) گاہے جانے کے بعد خوشوں میں بچ جانے والی گندم اور اس طرح کی چیزیں ( پانی کی گزرگاہوں کے ارد گرد ہونے والی پیداوار ) وصول کرتے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس کے پاس زمین ہو وہ اسے خود کاشت کرے یا اپنے کسی بھائی کو کاشت کاری کے لیے ( عاریتا ) دے دے ورنہ اسے ( خالی ) پڑا دہنے دے","",{"u2":"زہیر نے ہمیں حدیث بیان کی، کہا: ابوزبیر نے ہمیں سیدنا جابر رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں زمین بٹائی پر دیتے اور (باقی ساری پیداوار میں سے حصے کے علاوہ) گاہے جانے کے بعد خوشوں میں بچ جانے والی گندم اور اس طرح کی چیزیں (پانی کی گزرگاہوں کے ارد گرد ہونے والی پیداوار) وصول کرتے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کے پاس زمین ہو وہ اسے خود کاشت کرے یا اپنے کسی بھائی کو کاشت کاری کے لیے (عاریتا) دے دے ورنہ اسے (خالی) پڑا دہنے دے"}],[3902,"ہشام بن سعد نے مجھے حدیث بیان کی کہ انہیں ابوزبیر مکی نے حدیث بیان کی ، انہوں نے کہا : میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : ہم رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں تہائی یا چوتھائی حصے کے عوض ، نالوں ( کے کناروں کی پیداوار ) کے عوض زمین لیتے تھے تو رسول اللہ صلی اللہ علیہ وسلم اس بارے میں ( خطبہ دینے کے لیے ) کھڑے ہوئے اور فرمایا : \" جس کے پاس زمین ہو تو ( بہتر ہے ) وہ اسے کاشت کرے ۔ \" اگر وہ خود اسے کاشت نہیں کرتا تو اپنے بھائی کوعاریتا دے دے ، اگر وہ اسے اپنے بھائی کو بھی نہیں دیتا تو اس کو اپنے پاس رکھ لے","",{"u2":"ہشام بن سعد نے مجھے حدیث بیان کی کہ انہیں ابوزبیر مکی نے حدیث بیان کی، انہوں نے کہا: میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: ہم رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں تہائی یا چوتھائی حصے کے عوض، نالوں (کے کناروں کی پیداوار) کے عوض زمین لیتے تھے تو رسول اللہ صلی اللہ علیہ وسلم اس بارے میں (خطبہ دینے کے لیے) کھڑے ہوئے اور فرمایا: \"جس کے پاس زمین ہو تو (بہتر ہے) وہ اسے کاشت کرے۔\" اگر وہ خود اسے کاشت نہیں کرتا تو اپنے بھائی کوعاریتا دے دے، اگر وہ اسے اپنے بھائی کو بھی نہیں دیتا تو اس کو اپنے پاس رکھ لے"}],[3903,"ابو عوانہ نے ہمیں سلیمان ( اعمش ) سے حدیث بیان کی ، کہا : ہمیں ابوسفیان ( طلحہ بن نافع ) نے سیدنا جابر رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : میں نے نبی صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : \" جس کے پاس زمین ہو تو ( بہتر ہے کہ ) وہ اسے ہبہ کرے یا عاریتا دے دے","",{"u2":"ابو عوانہ نے ہمیں سلیمان (اعمش) سے حدیث بیان کی، کہا: ہمیں ابوسفیان (طلحہ بن نافع) نے سیدنا جابر رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: میں نے نبی صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: \"جس کے پاس زمین ہو تو (بہتر ہے کہ) وہ اسے ہبہ کرے یا عاریتا دے دے"}],[3904,"عمار بن رُزَیق نے اعمش سے اسی سند کے ساتھ یہی حدیث بیان کی ، البتہ انہوں نے کہا : \" وہ اسے کاشت کرے یا کسی اور آدمی کو کاشت کاری کے لیے دے","",{"u2":"عمار بن رُزَیق نے اعمش سے اسی سند کے ساتھ یہی حدیث بیان کی، البتہ انہوں نے کہا: \"وہ اسے کاشت کرے یا کسی اور آدمی کو کاشت کاری کے لیے دے"}],[3905,"بکیر نے حدیث بیان کی کہ انہیں عبداللہ بن ابی سلمہ نے نعمان بن ابی عیاش سے حدیث بیان کی اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کو ( ممنوعہ طریقے سے ) کرائے پر دینے سے منع فرمایا ۔ بکیر نے کہا : مجھے نافع نے حدیث بیان کی کہ انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : ہم اپنی زمینیں بٹائی پر دیتے تھے ، پھر جب ہم نے سیدنا رافع بن خدیج رضی اللہ عنہ کی حدیث سنی تو اسے ترک کر دیا"],[3906,"بکیر نے حدیث بیان کی کہ انہیں عبداللہ بن ابی سلمہ نے نعمان بن ابی عیاش سے حدیث بیان کی اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کو ( ممنوعہ طریقے سے ) کرائے پر دینے سے منع فرمایا ۔ بکیر نے کہا : مجھے نافع نے حدیث بیان کی کہ انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : ہم اپنی زمینیں بٹائی پر دیتے تھے ، پھر جب ہم نے سیدنا رافع بن خدیج رضی اللہ عنہ کی حدیث سنی تو اسے ترک کر دیا",""],[3907,"ابوزبیر نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے خالی زمین کی دو یا تین سالوں کے لیے بیع کرنے سے منع فرمایا","",{"u2":"ابوزبیر نے سیدنا جابر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے خالی زمین کی دو یا تین سالوں کے لیے بیع کرنے سے منع فرمایا\nابوزبیر نے سیدنا جابر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے خالی زمین کی دو یا تین سالوں کے لیے بیع کرنے سے منع فرمایا"}],[3908,"سعید بن منصور ، ابوبکر بن ابی شیبہ ، عمرو ناقد اور زہیر بن حرب نے کہا : ہمیں سفیان بن عیینہ نے حمید اعرج سے حدیث بیان کی ، انہوں نے سلیمان بن عتیق سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے کئی سالوں کی بیع سے منع فرمایا ۔ ابوبکر بن ابی شیبہ کی روایت میں ہے : پھلوں کی کئی سال کے لیے بیع سے ( منع فرمایا)","",{"u2":"سعید بن منصور، ابوبکر بن ابی شیبہ، عمرو ناقد اور زہیر بن حرب نے کہا: ہمیں سفیان بن عیینہ نے حمید اعرج سے حدیث بیان کی، انہوں نے سلیمان بن عتیق سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے کئی سالوں کی بیع سے منع فرمایا۔\nابوبکر بن ابی شیبہ کی روایت میں ہے: پھلوں کی کئی سال کے لیے بیع سے (منع فرمایا"}],[3909,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس کی زمین ہو وہ اسے خود کاشت کرے یا اپنے بھائی کو عاریتا دے دے ، اگر وہ نہیں مانتا تو اپنی زمین اپنے پاس رکھے ۔ \" ( غلط طریقے سے بٹائی پر نہ دے)","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کی زمین ہو وہ اسے خود کاشت کرے یا اپنے بھائی کو عاریتا دے دے، اگر وہ نہیں مانتا تو اپنی زمین اپنے پاس رکھے۔\" (غلط طریقے سے بٹائی پر نہ دے"}],[3910,"سیدنا جابر بن عبداللہ رضی اللہ عنہ نے خبر دی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ مزابنہ اور حُقول سے منع فرما رہے تھے ۔ سیدنا جابر بن عبداللہ رضی اللہ عنہ نے کہا : مزابنہ سے مراد ( کھجور پر لگے ) پھل کی خشک کھجور سے بیع ہے اور حقول سے مراد زمین کو ( اس کی پیداوار کے متعین حصے کے عوض ) بٹائی پر دینا ہے","",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ نے خبر دی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ مزابنہ اور حُقول سے منع فرما رہے تھے۔ سیدنا جابر بن عبداللہ رضی اللہ عنہ نے کہا: مزابنہ سے مراد (کھجور پر لگے) پھل کی خشک کھجور سے بیع ہے اور حقول سے مراد زمین کو (اس کی پیداوار کے متعین حصے کے عوض) بٹائی پر دینا ہے"}],[3911,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے محاقلہ اور مزابنہ سے منع فرمایا","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے محاقلہ اور مزابنہ سے منع فرمایا"}],[3912,"سیدنا ابوسعید خدری رضی اللہ عنہ کہتے ہیں : رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ اور محاقلہ سے منع فرمایا ۔ مزابنہ درخت پر لگی کھجور کو ( خشک کھجور کے عوض ) خریدنا ہے اور محاقلہ سے مراد زمین کو کرائے پر دینا ہے","",{"u2":"سیدنا ابوسعید خدری رضی اللہ عنہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ اور محاقلہ سے منع فرمایا۔ مزابنہ درخت پر لگی کھجور کو (خشک کھجور کے عوض) خریدنا ہے اور محاقلہ سے مراد زمین کو کرائے پر دینا ہے"}],[3913,"حماد بن زید نے ہمیں عمرو ( بن دینار ) سے خبر دی ، انہوں نے کہا : میں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : ہم مخابرہ میں کوئی حرج نہیں سمجھتے تھے حتی کہ وہ پہلا سال آیا جس میں ( یزید کی امارت کے لیے بیعت لی گئی ) تو سیدنا رافع رضی اللہ عنہ نے خیال کیا کہ نبی صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے","",{"u2":"حماد بن زید نے ہمیں عمرو (بن دینار) سے خبر دی، انہوں نے کہا: میں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: ہم مخابرہ میں کوئی حرج نہیں سمجھتے تھے حتی کہ وہ پہلا سال آیا جس میں (یزید کی امارت کے لیے بیعت لی گئی) تو سیدنا رافع رضی اللہ عنہ نے خیال کیا کہ نبی صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے"}],[3914,"سفیان ( بن عیینہ ) ، ایوب اور سفیان ( ثوری ) سب نے عمرو بن دینار سے اسی سند کے ساتھ اسی کے مانند روایت کی اور ابن عیینہ کی حدیث میں یہ اضافہ کیا : تو ہم نے ان ( رافع رضی اللہ عنہ ) کی وجہ سے ( احتیاطا ) اسے چھوڑ دیا","",{"u2":"سفیان (بن عیینہ)، ایوب اور سفیان (ثوری) سب نے عمرو بن دینار سے اسی سند کے ساتھ اسی کے مانند روایت کی اور ابن عیینہ کی حدیث میں یہ اضافہ کیا: تو ہم نے ان (رافع رضی اللہ عنہ) کی وجہ سے (احتیاطا) اسے چھوڑ دیا"}],[3915,"مجاہد سے روایت ہے ، انہوں نے کہا : سیدنا ابن عمر رضی اللہ عنہ نے کہا : رافع رضی اللہ عنہ نے ہماری زمین کا منافع ہم سے روک دیا","",{"u2":"مجاہد سے روایت ہے، انہوں نے کہا: سیدنا ابن عمر رضی اللہ عنہ نے کہا: رافع رضی اللہ عنہ نے ہماری زمین کا منافع ہم سے روک دیا"}],[3916,"یزید بن زریع نے ہمیں ایوب سے خبر دی اور انہوں نے نافع سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں اور سیدنا ابوبکر ، عمر اور عثمان رضی اللہ عنہ کے دور امارت میں اور سیدنا معاویہ رضی اللہ عنہ کی خلافت کے ابتدائی ایام تک سیدنا ابن عمر رضی اللہ عنہ اپنی زمینوں کو بٹائی پر دیتے تھے حتی کہ سیدنا معاویہ کی خلافت کے آخری ایام میں انہیں یہ بات پہنچی کہ سیدنا رافع بن خدیج رضی اللہ عنہ اس کے بارے میں نبی صلی اللہ علیہ وسلم سے ممانعت بیان کرتے ہیں ، چنانچہ وہ ان کے پاس گئے ، میں بھی ان کے ساتھ تھا ، انہوں نے ان سے دریافت کیا تو انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم زمینوں کو بٹائی پر دینے سے منع فرماتے تھے ۔ اس کے بعد ابن عمر رضی اللہ عنہ نے اسے چھوڑ دیا ۔ بعد ازیں جب سیدنا ابن عمر رضی اللہ عنہ سے اس کے بارے میں پوچھا جاتا تو وہ کہتے : رافع بن خدیج رضی اللہ عنہ کا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے","",{"u2":"یزید بن زریع نے ہمیں ایوب سے خبر دی اور انہوں نے نافع سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں اور حضرت ابوبکر، عمر اور عثمان رضی اللہ عنہ کے دور امارت میں اور سیدنا معاویہ رضی اللہ عنہ کی خلافت کے ابتدائی ایام تک سیدنا ابن عمر رضی اللہ عنہ اپنی زمینوں کو بٹائی پر دیتے تھے حتی کہ حضرت معاویہ کی خلافت کے آخری ایام میں انہیں یہ بات پہنچی کہ سیدنا رافع بن خدیج رضی اللہ عنہ اس کے بارے میں نبی صلی اللہ علیہ وسلم سے ممانعت بیان کرتے ہیں، چنانچہ وہ ان کے پاس گئے، میں بھی ان کے ساتھ تھا، انہوں نے ان سے دریافت کیا تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم زمینوں کو بٹائی پر دینے سے منع فرماتے تھے۔اس کے بعد ابن عمر رضی اللہ عنہ نے اسے چھوڑ دیا۔\nبعد ازیں جب سیدنا ابن عمر رضی اللہ عنہ سے اس کے بارے میں پوچھا جاتا تو وہ کہتے: رافع بن خدیج رضی اللہ عنہ کا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے"}],[3917,"حماد بن زید اور اسماعیل ( ابن علیہ ) دونوں نے ایوب سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی اور ابن علیہ کی حدیث میں یہ اضافہ ہے ، کہا : اس کے بعد سیدنا ابن عمر رضی اللہ عنہ نے اسے چھوڑ دیا اور وہ اسے ( اپنی زمین کو ) کرائے پر نہیں دیتے تھے","",{"u2":"حماد بن زید اور اسماعیل (ابن علیہ) دونوں نے ایوب سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی اور ابن علیہ کی حدیث میں یہ اضافہ ہے، کہا: اس کے بعد سیدنا ابن عمر رضی اللہ عنہ نے اسے چھوڑ دیا اور وہ اسے (اپنی زمین کو) کرائے پر نہیں دیتے تھے"}],[3918,"عبیداللہ نے ہمیں نافع سے حدیث بیان کی ، انہوں نے کہا : میں سیدنا ابن عمر رضی اللہ عنہ کے ساتھ سیدنا رافع بن خدیج رضی اللہ عنہ کی طرف گیا یہاں تک وہ ان کے پاس بَلاط کے مقام پر پہنچے تو انہوں نے انہیں ( ابن عمر رضی اللہ عنہ کو ) بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے زمینوں کو کرائے پر دینے سے منع فرمایا تھا","",{"u2":"عبیداللہ نے ہمیں نافع سے حدیث بیان کی، انہوں نے کہا: میں سیدنا ابن عمر رضی اللہ عنہ کے ساتھ سیدنا رافع بن خدیج رضی اللہ عنہ کی طرف گیا یہاں تک وہ ان کے پاس بَلاط کے مقام پر پہنچے تو انہوں نے انہیں (ابن عمر رضی اللہ عنہ کو) بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے زمینوں کو کرائے پر دینے سے منع فرمایا تھا"}],[3919,"حکم نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ وہ سیدنا رافع رضی اللہ عنہ کے پاس آئے ۔ ۔ پھر ( ان کے حوالے سے ) یہی حدیث نبی صلی اللہ علیہ وسلم سے روایت کرتے ہوئے بیان کی","",{"u2":"حکم نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ وہ سیدنا رافع رضی اللہ عنہ کے پاس آئے۔۔ پھر (ان کے حوالے سے) یہی حدیث نبی صلی اللہ علیہ وسلم سے روایت کرتے ہوئے بیان کی"}],[3920,"حسین بن حسن بن یسار نے ہمیں حدیث بیان کی ، کہا : ہمیں ابن عون نے نافع سے حدیث بیان کی کہ سیدنا ابن عمر رضی اللہ عنہ زمین کو اجرت پر دیتے تھے ، کہا : انہیں سیدنا رافع بن خدیج رضی اللہ عنہ کے حوالے سے حدیث بتائی گئی ، کہا : وہ میرے ساتھ ان کے ہاں گئے تو انہوں نے اپنے بعض چچاؤں سے بیان کیا ، انہوں نے اس حدیث میں نبی صلی اللہ علیہ وسلم سے بیان کیا کہ آپ نے زمین کو کرائے پر دینے سے منع فرمایا ہے ۔ کہا : تو سیدنا ابن عمر رضی اللہ عنہ نے اسے چھوڑ دیا اور زمین اجرت پر نہ دی","",{"u2":"حسین بن حسن بن یسار نے ہمیں حدیث بیان کی، کہا: ہمیں ابن عون نے نافع سے حدیث بیان کی کہ سیدنا ابن عمر رضی اللہ عنہ زمین کو اجرت پر دیتے تھے، کہا: انہیں سیدنا رافع بن خدیج رضی اللہ عنہ کے حوالے سے حدیث بتائی گئی، کہا: وہ میرے ساتھ ان کے ہاں گئے تو انہوں نے اپنے بعض چچاؤں سے بیان کیا، انہوں نے اس حدیث میں نبی صلی اللہ علیہ وسلم سے بیان کیا کہ آپ نے زمین کو کرائے پر دینے سے منع فرمایا ہے۔ کہا: تو سیدنا ابن عمر رضی اللہ عنہ نے اسے چھوڑ دیا اور زمین اجرت پر نہ دی"}],[3921,"یزید بن ہارون نے کہا : ہمیں ابن عون نے اسی سند کے ساتھ حدیث بیان کی اور کہا : انہوں نے اپنے بعض چچاؤں کے واسطے سے نبی صلی اللہ علیہ وسلم سے یہ حدیث بیان کی","",{"u2":"یزید بن ہارون نے کہا: ہمیں ابن عون نے اسی سند کے ساتھ حدیث بیان کی اور کہا: انہوں نے اپنے بعض چچاؤں کے واسطے سے نبی صلی اللہ علیہ وسلم سے یہ حدیث بیان کی"}],[3922,"سالم بن عبداللہ نے خبر دی کہ سیدنا عبداللہ بن عمر رضی اللہ عنہ اپنی زمینیں کرائے پر دیتے تھے حتی کہ انہیں یہ بات پہنچی کہ سیدنا رافع بن خدیج رضی اللہ عنہ زمین کو کرائے پر دینے سے منع کرتے ہیں ، چنانچہ سیدنا عبداللہ رضی اللہ عنہ نے ان سے ملاقات کی اور کہا : ابن خدیج! آپ زمین کو کرائے پر دینے کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے کیا بیان کرتے ہیں؟ سیدنا رافع بن خدیج رضی اللہ عنہ نے سیدنا عبداللہ رضی اللہ عنہ سے کہا : میں نے اپنے دو چچاؤں سے سنا اور وہ دونوں بدر میں شریک ہوئے تھے ، وہ اپنے گھرانے کے لوگوں کو حدیث بیان کر رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کو بٹائی پر دینے سے منع فرمایا ہے ۔ سیدنا عبداللہ رضی اللہ عنہ نے کہا : میں رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں بخوبی جانتا تھا کہ زمین کرائے پر دی جاتی تھی ۔ پھر سیدنا عبداللہ رضی اللہ عنہ کو خوف ہوا کہ ( ممکن ہے ) رسول اللہ صلی اللہ علیہ وسلم نے اس کے بارے میں کوئی نیا حکم جاری کیا ہو جس کا انہیں علم نہ ہوا ہو ، لہٰذا انہوں نے زمین کو کرائے پر دینا چھوڑ دیا","",{"u2":"سالم بن عبداللہ نے خبر دی کہ سیدنا عبداللہ بن عمر رضی اللہ عنہ اپنی زمینیں کرائے پر دیتے تھے حتی کہ انہیں یہ بات پہنچی کہ سیدنا رافع بن خدیج رضی اللہ عنہ زمین کو کرائے پر دینے سے منع کرتے ہیں، چنانچہ سیدنا عبداللہ رضی اللہ عنہ نے ان سے ملاقات کی اور کہا: ابن خدیج! آپ زمین کو کرائے پر دینے کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے کیا بیان کرتے ہیں؟ سیدنا رافع بن خدیج رضی اللہ عنہ نے سیدنا عبداللہ رضی اللہ عنہ سے کہا: میں نے اپنے دو چچاؤں سے سنا اور وہ دونوں بدر میں شریک ہوئے تھے، وہ اپنے گھرانے کے لوگوں کو حدیث بیان کر رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کو بٹائی پر دینے سے منع فرمایا ہے۔ سیدنا عبداللہ رضی اللہ عنہ نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں بخوبی جانتا تھا کہ زمین کرائے پر دی جاتی تھی۔ پھر سیدنا عبداللہ رضی اللہ عنہ کو خوف ہوا کہ (ممکن ہے) رسول اللہ صلی اللہ علیہ وسلم نے اس کے بارے میں کوئی نیا حکم جاری کیا ہو جس کا انہیں علم نہ ہوا ہو، لہذا انہوں نے زمین کو کرائے پر دینا چھوڑ دیا"}],[3923,"اسماعیل بن علیہ نے ہمیں ایوب سے حدیث بیان کی ، انہوں نے یعلیٰ بن حکیم سے ، انہوں نے سلیمان بن یسار سے اور انہوں نے سیدنا رافع بن خدیج رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ہم زمین کو اس کی پیداوار کے حصے پر دیتے تھے اور اسے تہائی اور چوتھائی حصے اور ( اس کے ساتھ ) متعین مقدار میں غلے کے عوض کرائے پر دیتے ، ایک روز ہمارے پاس میرے چچاؤں میں سے ایک آدمی آیا اور کہنے لگا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک ایسے کام سے منع کیا ہے جو ہمارے لئے نفع مند تھا لیکن اللہ اور اس کے رسول کی اطاعت ہمارے لیے زیادہ نفع بخش ہے ، آپ نے ہمیں منع کیا ہے کہ ہم زمین کو بٹائی پر مدیں اور اسے تہائی اور چوتھائی حصے اور متعین غلے کے عوض کرائے پر دیں ۔ اور آپ نے زمین کے مالک کو حکم دیا کہ وہ خود اس میں کاشت کرے یا کاشت کے لیے ( اپنے مسلمان بھائی کو ) دے دے اور آپ نے اس کے کرائے پر دینے اور اس کے سوا ( غلے کے ایک متعین حصے پر دینے ) کو ناپسند کیا ہے","",{"u2":"اسماعیل بن علیہ نے ہمیں ایوب سے حدیث بیان کی، انہوں نے یعلیٰ بن حکیم سے، انہوں نے سلیمان بن یسار سے اور انہوں نے سیدنا رافع بن خدیج رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ہم زمین کو اس کی پیداوار کے حصے پر دیتے تھے اور اسے تہائی اور چوتھائی حصے اور (اس کے ساتھ) متعین مقدار میں غلے کے عوض کرائے پر دیتے، ایک روز ہمارے پاس میرے چچاؤں میں سے ایک آدمی آیا اور کہنے لگا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک ایسے کام سے منع کیا ہے جو ہمارے لئے نفع مند تھا لیکن اللہ اور اس کے رسول کی اطاعت ہمارے لیے زیادہ نفع بخش ہے، آپ نے ہمیں منع کیا ہے کہ ہم زمین کو بٹائی پر مدیں اور اسے تہائی اور چوتھائی حصے اور متعین غلے کے عوض کرائے پر دیں۔ اور آپ نے زمین کے مالک کو حکم دیا کہ وہ خود اس میں کاشت کرے یا کاشت کے لیے (اپنے مسلمان بھائی کو) دے دے اور آپ نے اس کے کرائے پر دینے اور اس کے سوا (غلے کے ایک متعین حصے پر دینے) کو ناپسند کیا ہے\nاسماعیل بن علیہ نے ہمیں ایوب سے حدیث بیان کی، انہوں نے یعلیٰ بن حکیم سے، انہوں نے سلیمان بن یسار سے اور انہوں نے سیدنا رافع بن خدیج رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ہم زمین کو اس کی پیداوار کے حصے پر دیتے تھے اور اسے تہائی اور چوتھائی حصے اور (اس کے ساتھ) متعین مقدار میں غلے کے عوض کرائے پر دیتے، ایک روز ہمارے پاس میرے چچاؤں میں سے ایک آدمی آیا اور کہنے لگا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک ایسے کام سے منع کیا ہے جو ہمارے لئے نفع مند تھا لیکن اللہ اور اس کے رسول کی اطاعت ہمارے لیے زیادہ نفع بخش ہے، آپ نے ہمیں منع کیا ہے کہ ہم زمین کو بٹائی پر مدیں اور اسے تہائی اور چوتھائی حصے اور متعین غلے کے عوض کرائے پر دیں۔ اور آپ نے زمین کے مالک کو حکم دیا کہ وہ خود اس میں کاشت کرے یا کاشت کے لیے (اپنے مسلمان بھائی کو) دے دے اور آپ نے اس کے کرائے پر دینے اور اس کے سوا (غلے کے ایک متعین حصے پر دینے) کو ناپسند کیا ہے"}],[3924,"حماد بن زید نے ہمیں ایوب سے خبر دی ، انہوں نے کہا : یعلیٰ بن حکیم نے میری طرف لکھا ، انہوں نے کہا : میں نے سلیمان بن یسار سے سنا ، وہ سیدنا رافع بن خدیج رضی اللہ عنہ سے حدیث بیان کر رہے تھے ، انہوں نے کہا : ہم زمین کو بٹائی پر دیتے اور اسے تہائی اور چوتھائی حصے پر کرائے پر دیتے تھے ۔ ۔ ۔ آگے ابن علیہ کی ( سابقہ ) حدیث کے مانند بیان کیا","",{"u2":"حماد بن زید نے ہمیں ایوب سے خبر دی، انہوں نے کہا: یعلیٰ بن حکیم نے میری طرف لکھا، انہوں نے کہا: میں نے سلیمان بن یسار سے سنا، وہ سیدنا رافع بن خدیج رضی اللہ عنہ سے حدیث بیان کر رہے تھے، انہوں نے کہا: ہم زمین کو بٹائی پر دیتے اور اسے تہائی اور چوتھائی حصے پر کرائے پر دیتے تھے۔۔۔ آگے ابن علیہ کی (سابقہ) حدیث کے مانند بیان کیا"}],[3925,"ابن ابی عروبہ نے یعلیٰ بن حکیم سے اسی سند کے ساتھ اسی کے مانند روایت بیان کی","",{"u2":"ابن ابی عروبہ نے یعلیٰ بن حکیم سے اسی سند کے ساتھ اسی کے مانند روایت بیان کی"}],[3926,"جریر بن حازم نے یعلیٰ بن حکیم کی اسی سند کے ساتھ روایت کی ، انہوں نے ( سلیمان کے واسطے سے ) رافع بن خدیج رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، انہوں نے ( اپنے چچاؤں میں سے ایک ) کے الفاظ نہیں کہے","",{"u2":"جریر بن حازم نے یعلیٰ بن حکیم کی اسی سند کے ساتھ روایت کی، انہوں نے (سلیمان کے واسطے سے) رافع بن خدیج رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، انہوں نے (اپنے چچاؤں میں سے ایک) کے الفاظ نہیں کہے"}],[3927,"ابوعمرو اوزاعی نے مجھے رافع بن خدیج رضی اللہ عنہ کے آزاد کردہ غلام ابونجاشی سے حدیث بیان کی اور انہوں نے سیدنا رافع رضی اللہ عنہ سے روایت کی ظُہیر بن رافع ان کے چچا تھے ، کہا : ظہیر رضی اللہ عنہ میرے پاس آئے تو انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ایک ایسے کام سے منع فرمایا ہے جو ہمیں سہولت دینے والا تھا ۔ میں نے پوچھا : وہ کیا ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے جو فرمایا وہ برحق ہے ۔ کہا : آپ نے مجھ سے پوچھا : \" تم اپنے کھیتوں کا کیا معاملہ کرتے ہو؟ \" میں نے عرض کی : اے اللہ کے رسول! ہم انہیں چھوٹی نہر ( کے کناروں کی پیداوار ) پر یا کھجور یا جو کے ( متعینہ ) وسقوں پر اجرت پر دیتے ہیں ۔ آپ نے فرمایا : \" تو ایسا نہ کرو ، اسے خود کاشت کرو یا کاشت کے لیے کسی کو دے دو یا ویسے ہی اپنے ہاتھ میں رکھو","",{"u2":"ابوعمرو اوزاعی نے مجھے رافع بن خدیج رضی اللہ عنہ کے آزاد کردہ غلام ابونجاشی سے حدیث بیان کی اور انہوں نے سیدنا رافع رضی اللہ عنہ سے روایت کی ظُہیر بن رافع ان کے چچا تھے، کہا: ظہیر رضی اللہ عنہ میرے پاس آئے تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ایک ایسے کام سے منع فرمایا ہے جو ہمیں سہولت دینے والا تھا۔ میں نے پوچھا: وہ کیا ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے جو فرمایا وہ برحق ہے۔ کہا: آپ نے مجھ سے پوچھا: \"تم اپنے کھیتوں کا کیا معاملہ کرتے ہو؟\" میں نے عرض کی: اے اللہ کے رسول! ہم انہیں چھوٹی نہر (کے کناروں کی پیداوار) پر یا کھجور یا جو کے (متعینہ) وسقوں پر اجرت پر دیتے ہیں۔ آپ نے فرمایا: \"تو ایسا نہ کرو، اسے خود کاشت کرو یا کاشت کے لیے کسی کو دے دو یا ویسے ہی اپنے ہاتھ میں رکھو"}],[3928,"عکرمہ بن عمار نے ابونجاشی سے ، انہوں نے سیدنا رافع رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث روایت کی اور انہوں نے اپنے چچا ظہیر رضی اللہ عنہ سے روایت کا تذکرہ نہیں کیا","",{"u2":"عکرمہ بن عمار نے ابونجاشی سے، انہوں نے سیدنا رافع رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث روایت کی اور انہوں نے اپنے چچا ظہیر رضی اللہ عنہ سے روایت کا تذکرہ نہیں کیا"}],[3929,"امام مالک نے ربیعہ بن ابی عبدالرحمٰن سے اور انہوں نے حنظلہ بن قیس سے روایت کی کہ انہوں نے سیدنا رافع بن خدیج رضی اللہ عنہ سے زمین کو کرائے پر دینے کے بارے میں دریافت کیا تو انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے زمین کو کرائے پر دینے سے منع فرمایا ہے ۔ کہا : میں نے پوچھا : کیا سونے اور چاندی کے عوض بھی؟ انہوں نے جواب دیا : البتہ سونے اور چاندی کے عوض دینے میں کوئی حرج نہیں","",{"u2":"امام مالک نے ربیعہ بن ابی عبدالرحمٰن سے اور انہوں نے حنظلہ بن قیس سے روایت کی کہ انہوں نے سیدنا رافع بن خدیج رضی اللہ عنہ سے زمین کو کرائے پر دینے کے بارے میں دریافت کیا تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے زمین کو کرائے پر دینے سے منع فرمایا ہے۔ کہا: میں نے پوچھا: کیا سونے اور چاندی کے عوض بھی؟ انہوں نے جواب دیا: البتہ سونے اور چاندی کے عوض دینے میں کوئی حرج نہیں"}],[3930,"اوزاعی نے ہمیں ربیعہ بن ابی عبدالرحمٰن سے حدیث بیان کی ، کہا : مجھے حنظلہ بن قیس انصاری نے حدیث سنائی ، انہوں نے کہا : میں نے سیدنا رافع بن خدیج رضی اللہ عنہ سے سونے اور چاندی ( دینار اور درہم ) کے عوض زمین کو بٹائی پر دینے کے بارے میں سوال کیا تو انہوں نے کہا : اس میں کوئی حرج نہیں ۔ ( امر واقع یہ ہے کہ ) رسول اللہ صلی اللہ علیہ وسلم کے عہد میں لوگ نہروں کی زمین ، چھوٹے نالوں کے کناروں کی زمین اور ( متعین مقدار میں ) فصل کی کچھ اشیاء کے عوض زمین اجرت پر دیتے تھے ۔ کبھی یہ ( حصہ ) تباہ ہو جاتا اور وہ محفوظ رہتا اور کبھی یہ محفوظ رہتا اور وہ تباہ ہو جاتا ، لوگوں میں بٹائی ( کرائے پر دینے ) کی صرف یہی صورت تھی ، اسی لیے اس سے منع کیا گیا ، البتہ معلوم اور محفوظ چیز جس کی ادایگی کی ضمانت دی جا سکتی ہو تو اس میں کوئی حرج نہیں","",{"u2":"اوزاعی نے ہمیں ربیعہ بن ابی عبدالرحمٰن سے حدیث بیان کی، کہا: مجھے حنظلہ بن قیس انصاری نے حدیث سنائی، انہوں نے کہا: میں نے سیدنا رافع بن خدیج رضی اللہ عنہ سے سونے اور چاندی (دینار اور درہم) کے عوض زمین کو بٹائی پر دینے کے بارے میں سوال کیا تو انہوں نے کہا: اس میں کوئی حرج نہیں۔ (امر واقع یہ ہے کہ) رسول اللہ صلی اللہ علیہ وسلم کے عہد میں لوگ نہروں کی زمین، چھوٹے نالوں کے کناروں کی زمین اور (متعین مقدار میں) فصل کی کچھ اشیاء کے عوض زمین اجرت پر دیتے تھے۔ کبھی یہ (حصہ) تباہ ہو جاتا اور وہ محفوظ رہتا اور کبھی یہ محفوظ رہتا اور وہ تباہ ہو جاتا، لوگوں میں بٹائی (کرائے پر دینے) کی صرف یہی صورت تھی، اسی لیے اس سے منع کیا گیا، البتہ معلوم اور محفوظ چیز جس کی ادایگی کی ضمانت دی جا سکتی ہو تو اس میں کوئی حرج نہیں"}],[3931,"سفیان بن عیینہ نے ہمیں یحییٰ بن سعید سے حدیث بیان کی ، انہوں نے حنظلہ زُرَقی سے روایت کی کہ انہوں نے سیدنا رافع بن خدیج رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : انصار میں سب سے زیادہ ہمارے کھیت تھے ۔ کہا : ہم زمین کو اس شرط پر کرائے پر دیتے کہ یہ ( حصہ ) ہمارے لیے ہے اور وہ ( حصہ ) ان کے لیے ہے ، بسا اوقات اس حصے میں پیداوار ہوتی اور اس میں نہ ہوتی ، تو آپ نے ہمیں اس سے منع کر دیا ۔ البتہ آپ نے ہمیں چاندی کے عوض دینے سے منع نہیں کیا","",{"u2":"سفیان بن عیینہ نے ہمیں یحییٰ بن سعید سے حدیث بیان کی، انہوں نے حنظلہ زُرَقی سے روایت کی کہ انہوں نے سیدنا رافع بن خدیج رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: انصار میں سب سے زیادہ ہمارے کھیت تھے۔ کہا: ہم زمین کو اس شرط پر کرائے پر دیتے کہ یہ (حصہ) ہمارے لیے ہے اور وہ (حصہ) ان کے لیے ہے، بسا اوقات اس حصے میں پیداوار ہوتی اور اس میں نہ ہوتی، تو آپ نے ہمیں اس سے منع کر دیا۔ البتہ آپ نے ہمیں چاندی کے عوض دینے سے منع نہیں کیا"}],[3932,"حماد اور یزید بن ہارون نے یحییٰ بن سعید سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی","",{"u2":"حماد اور یزید بن ہارون نے یحییٰ بن سعید سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی"}],[3933,"یحییٰ بن یحییٰ نے کہا : ہمیں عبدالواحد بن زیاد نے خبر دی ، نیز ابوبکر بن ابی شیبہ نے کہا : ہمیں علی بن مسہر نے حدیث بیان کی ، ان دونوں ( عبدالواحد اور علی ) نے ( سلیمان ) شیبانی سے اور انہوں نے عبداللہ بن سائب سے روایت کی ، انہوں نے کہا : میں نے عبداللہ بن معقل سے مزارعت ( زمین کی پیداوار کی متعین مقدار پر بٹائی ) کے بارے میں پوچھا تو انہوں نے کہا : مجھے سیدنا ثابت بن ضحاک رضی اللہ عنہ نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے مزارعت سے منع فرمایا ۔ ابن ابی شیبہ کی روایت میں ہے : آپ نے اس سے منع فرمایا ۔ اور انہوں نے کہا : میں نے ابن معقل سے پوچھا ۔ عبداللہ کا نام نہیں لیا","",{"u2":"یحییٰ بن یحییٰ نے کہا: ہمیں عبدالواحد بن زیاد نے خبر دی، نیز ابوبکر بن ابی شیبہ نے کہا: ہمیں علی بن مسہر نے حدیث بیان کی، ان دونوں (عبدالواحد اور علی) نے (سلیمان) شیبانی سے اور انہوں نے عبداللہ بن سائب سے روایت کی، انہوں نے کہا: میں نے عبداللہ بن معقل سے مزارعت (زمین کی پیداوار کی متعین مقدار پر بٹائی) کے بارے میں پوچھا تو انہوں نے کہا: مجھے سیدنا ثابت بن ضحاک رضی اللہ عنہ نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے مزارعت سے منع فرمایا۔ ابن ابی شیبہ کی روایت میں ہے: آپ نے اس سے منع فرمایا۔ اور انہوں نے کہا: میں نے ابن معقل سے پوچھا۔ عبداللہ کا نام نہیں لیا"}],[3934,"ابوعوانہ نے ہمیں سلیمان شیبانی سے خبر دی ، انہوں نے عبداللہ بن سائب سے روایت کی ، انہوں نے کہا : ہم عبداللہ بن معقل کے پاس گئے ، ہم نے ان سے مزارعت کے بارے میں سوال کیا تو انہوں نے کہا : سیدنا ثابت رضی اللہ عنہ کا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مزارعت سے منع فرمایا اور مؤاجرت ( نقدی کے عوض کرائے پر دینے ) کا حکم دیا ہے اور فرمایا : \" اس میں کوئی حرج نہیں","",{"u2":"ابوعوانہ نے ہمیں سلیمان شیبانی سے خبر دی، انہوں نے عبداللہ بن سائب سے روایت کی، انہوں نے کہا: ہم عبداللہ بن معقل کے پاس گئے، ہم نے ان سے مزارعت کے بارے میں سوال کیا تو انہوں نے کہا: سیدنا ثابت رضی اللہ عنہ کا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مزارعت سے منع فرمایا اور مؤاجرت (نقدی کے عوض کرائے پر دینے) کا حکم دیا ہے اور فرمایا: \"اس میں کوئی حرج نہیں"}],[3935,"حماد بن زید نے ہمیں عمرو ( بن دینار ) سے خبر دی کہ مجاہد نے طاوس سے کہا : ہمارے ساتھ سیدنا رافع بن خدیج رضی اللہ عنہ کے بیٹے کے پاس چلو اور ان سے ان کے والد کے واسطے سے نبی صلی اللہ علیہ وسلم سے روایت کردہ حدیث سنو ، کہا : انہوں ( طاوس ) نے انہیں ڈانٹا اور کہا : اللہ کی قسم : اگر مجھے علم ہوتا کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے تو میں یہ کام ( کبھی ) نہ کرتا لیکن مجھے اس شخص نے حدیث بیان کی جو اسے ان سب سے زیادہ جاننے والا ہے ، ان کی مراد سیدنا ابن عباس رضی اللہ عنہ سے تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کوئی اپنی زمین اپنے بھائی کو عاریتا دے ، یہ اس کے لیے اس سے بہتر ہے کہ اس پر متعین پیداوار وصول کرے ۔ \" ( اس سے اللہ کی رضا بھی حاصل ہو گی اور جھگڑوں سے محفوظ بھی رہے گا)","",{"u2":"حماد بن زید نے ہمیں عمرو (بن دینار) سے خبر دی کہ مجاہد نے طاوس سے کہا: ہمارے ساتھ سیدنا رافع بن خدیج رضی اللہ عنہ کے بیٹے کے پاس چلو اور ان سے ان کے والد کے واسطے سے نبی صلی اللہ علیہ وسلم سے روایت کردہ حدیث سنو، کہا: انہوں (طاوس) نے انہیں ڈانٹا اور کہا: اللہ کی قسم: اگر مجھے علم ہوتا کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے تو میں یہ کام (کبھی) نہ کرتا لیکن مجھے اس شخص نے حدیث بیان کی جو اسے ان سب سے زیادہ جاننے والا ہے، ان کی مراد سیدنا ابن عباس رضی اللہ عنہ سے تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی اپنی زمین اپنے بھائی کو عاریتا دے، یہ اس کے لیے اس سے بہتر ہے کہ اس پر متعین پیداوار وصول کرے۔\" (اس سے اللہ کی رضا بھی حاصل ہو گی اور جھگڑوں سے محفوظ بھی رہے گا"}],[3936,"سفیان نے ہمیں عمرو اور ابن طاوس سے حدیث بیان کی اور انہوں نے طاوس سے روایت کی کہ وہ ( نقدی کے عوض ) بٹائی پر زمین دیتے تھے ۔ عمرو نے کہا : میں نے ان سے کہا : ابو عبدالرحمٰن! اگر آپ مخابرہ چھوڑ دیں ( تو بہتر ہے ) کیونکہ لوگ سمجھتے ہیں کہ نبی صلی اللہ علیہ وسلم نے مخابرہ سے منع فرمایا ہے ۔ انہوں نے کہا : عمرو! مجھے اس مسئلے کو ان سب کی نسبت زیادہ جاننے والے ، یعنی سیدنا ابن عباس رضی اللہ عنہ نے بتایا ہے کہ نبی صلی اللہ علیہ وسلم نے اس سے منع نہیں فرمایا ، آپ نے تو صرف فرمایا تھا : \" تم میں سے کوئی اپنے بھائی کو ( زمین ) عاریتا دے یہ اس کے لیے اس کی نسبت بہتر ہے کہ اس پر متعین پیداوار وصول کرے ۔ \" ( بلا عوض دینے سے اسے غیر متعین ، وسیع منفعت حاصل ہو گی)","",{"u2":"سفیان نے ہمیں عمرو اور ابن طاوس سے حدیث بیان کی اور انہوں نے طاوس سے روایت کی کہ وہ (نقدی کے عوض) بٹائی پر زمین دیتے تھے۔ عمرو نے کہا: میں نے ان سے کہا: ابو عبدالرحمٰن! اگر آپ مخابرہ چھوڑ دیں (تو بہتر ہے) کیونکہ لوگ سمجھتے ہیں کہ نبی صلی اللہ علیہ وسلم نے مخابرہ سے منع فرمایا ہے۔ انہوں نے کہا: عمرو! مجھے اس مسئلے کو ان سب کی نسبت زیادہ جاننے والے، یعنی سیدنا ابن عباس رضی اللہ عنہ نے بتایا ہے کہ نبی صلی اللہ علیہ وسلم نے اس سے منع نہیں فرمایا، آپ نے تو صرف فرمایا تھا: \"تم میں سے کوئی اپنے بھائی کو (زمین) عاریتا دے یہ اس کے لیے اس کی نسبت بہتر ہے کہ اس پر متعین پیداوار وصول کرے۔\" (بلا عوض دینے سے اسے غیر متعین، وسیع منفعت حاصل ہو گی"}],[3937,"ایوب ، سفیان ، ابن جریج اور شعبہ سب نے عمرو بن دینار سے ، انہوں نے طاوس سے ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ان کی حدیث کی طرح بیان کیا","",{"u2":"ایوب، سفیان، ابن جریج اور شعبہ سب نے عمرو بن دینار سے، انہوں نے طاوس سے، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ان کی حدیث کی طرح بیان کیا"}],[3938,"معمر نے ابن طاوس سے ، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \"\" تم میں سے کوئی اپنی زمین اپنے بھائی کو دے یہ اس کے لیے اس سے بہتر ہے کہ اس پر اتنا اتنا ، یعنی متعین مقدار میں وصول کرے ۔ \"\" کہا : سیدنا ابن عباس رضی اللہ عنہ نے کہا : یہی حقل ہے اور انصار کی زبان میں محاقلہ ہے","",{"u2":"معمر نے ابن طاوس سے، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی اپنی زمین اپنے بھائی کو دے یہ اس کے لیے اس سے بہتر ہے کہ اس پر اتنا اتنا، یعنی متعین مقدار میں وصول کرے۔\"\nکہا: سیدنا ابن عباس رضی اللہ عنہ نے کہا: یہی حقل ہے اور انصار کی زبان میں محاقلہ ہے"}],[3939,"عبدالملک بن زید نے طاوس سے ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" جس کی زمین ہو ، وہ اگر اسے اپنے بھائی کو عاریتا دے دے تو یہ اس کے لیے بہتر ہے","",{"u2":"عبدالملک بن زید نے طاوس سے، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"جس کی زمین ہو، وہ اگر اسے اپنے بھائی کو عاریتا دے دے تو یہ اس کے لیے بہتر ہے"}],[3940,"یحییٰ قطان نے ہمیں عبیداللہ سے حدیث بیان کی ، کہا : مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے اہل خیبر سے اس کی پیداوار کے نصف پر معاملہ کیا جو وہاں سے پھلوں اور کھیتی کی صورت میں حاصل ہو گی","",{"u2":"یحییٰ قطان نے ہمیں عبیداللہ سے حدیث بیان کی، کہا: مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے اہل خیبر سے اس کی پیداوار کے نصف پر معاملہ کیا جو وہاں سے پھلوں اور کھیتی کی صورت میں حاصل ہو گی"}],[3941,"علی بن مسہر نے ہمیں حدیث بیان کی ، کہا : ہمیں عبیداللہ نے نافع سے حدیث بیان کی اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے خیبر ( کی زمین ) اس پیداوار کے آدھے حصے پر دی جو وہاں سے پھلوں اور کھیتی کی صورت میں حاصل ہو گی ۔ آپ اپنی ازواج کو ہر سال ایک سو وسق دیتے ، اسی ( 80 ) وسق کھجور کے اور بیس وسق جو کے ۔ بعد ازاں جب خیبر کی تقسیم سیدنا عمر رضی اللہ عنہ کی ذمہ داری میں آئی تو انہوں نے نبی صلی اللہ علیہ وسلم کی ازواج کو اختیار دیا کہ ان کے لیے زمین اور پانی کا حصہ مقرر کر دیا جائے یا ان کو ہر سال ( مقررہ ) وسق مل جانے کی ضمانت دیں ۔ تو ان کا ( ان دونوں میں سے انتخاب کرنے میں ) باہم اختلاف ہو گیا ۔ ان میں سے کچھ نے زمین اور پانی کو منتخب کیا اور کچھ نے ہر سال ( مقررہ ) وسق لینے پسند کیے ۔ سیدہ حفصہ اور عائشہ رضی اللہ عنھن ان میں سے تھیں جنہوں نے زمین اور پانی کو چنا","",{"u2":"علی بن مسہر نے ہمیں حدیث بیان کی، کہا: ہمیں عبیداللہ نے نافع سے حدیث بیان کی اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے خیبر (کی زمین) اس پیداوار کے آدھے حصے پر دی جو وہاں سے پھلوں اور کھیتی کی صورت میں حاصل ہو گی۔ آپ اپنی ازواج کو ہر سال ایک سو وسق دیتے، اسی (80) وسق کھجور کے اور بیس وسق جو کے۔ بعد ازاں جب خیبر کی تقسیم سیدنا عمر رضی اللہ عنہ کی ذمہ داری میں آئی تو انہوں نے نبی صلی اللہ علیہ وسلم کی ازواج کو اختیار دیا کہ ان کے لیے زمین اور پانی کا حصہ مقرر کر دیا جائے یا ان کو ہر سال (مقررہ) وسق مل جانے کی ضمانت دیں۔ تو ان کا (ان دونوں میں سے انتخاب کرنے میں) باہم اختلاف ہو گیا۔ ان میں سے کچھ نے زمین اور پانی کو منتخب کیا اور کچھ نے ہر سال (مقررہ) وسق لینے پسند کیے۔ حضرت حفصہ اور عائشہ رضی اللہ عنھن ان میں سے تھیں جنہوں نے زمین اور پانی کو چنا"}],[3942,"عبداللہ بن نمیر نے ہمیں حدیث بیان کی ، کہا : ہمیں عبیداللہ نے حدیث بیان کی ، انہوں نے کہا : مجھے نافع نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اہل خیبر کے ساتھ وہاں کی کھیتی اور پھلوں کی پیداوار کے آدھے حصے پر معاملہ ( کھیتی باڑی کے کام کاج کا معاہدہ ) کیا ۔ ۔ ۔ آگے علی بن مسہر کی حدیث کی طرح بیان کیا اور انہوں نے یہ ذکر نہیں کیا کہ سیدہ عائشہ اور سیدہ حفصہ رضی اللہ عنھن ان میں سے تھیں جنہوں نے زمین اور پانی کو انتخاب کیا ۔ اور کہا : انہوں نے نبی صلی اللہ علیہ وسلم کی ازواج کو اختیار دیا کہ ان کے لیے زمین خاص کر دی جائے ۔ اور انہوں نے پانی کا ( بھی ) ذکر نہیں کیا","",{"u2":"عبداللہ بن نمیر نے ہمیں حدیث بیان کی، کہا: ہمیں عبیداللہ نے حدیث بیان کی، انہوں نے کہا: مجھے نافع نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اہل خیبر کے ساتھ وہاں کی کھیتی اور پھلوں کی پیداوار کے آدھے حصے پر معاملہ (کھیتی باڑی کے کام کاج کا معاہدہ) کیا۔۔۔ آگے علی بن مسہر کی حدیث کی طرح بیان کیا اور انہوں نے یہ ذکر نہیں کیا کہ حضرت عائشہ اور سیدنا حفصہ رضی اللہ عنھن ان میں سے تھیں جنہوں نے زمین اور پانی کو انتخاب کیا۔ اور کہا: انہوں نے نبی صلی اللہ علیہ وسلم کی ازواج کو اختیار دیا کہ ان کے لیے زمین خاص کر دی جائے۔ اور انہوں نے پانی کا (بھی) ذکر نہیں کیا"}],[3943,"اسامہ بن زید لیثی نے مجھے نافع سے خبر دی ، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : جب خیبر فتح ہوا تو یہود نے رسول اللہ صلی اللہ علیہ وسلم سے درخواست کی کہ آپ انہیں اس شرط پر وہیں دینے دیں کہ وہ لوگ وہاں سے حاصل ہونے والی پھلوں اور غلے کی پیداوار کے نصف حصے پر کام کریں ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" میں تمہیں اس شرط پر جب تک ہم چاہیں گے رہنے دیتا ہوں ۔ \" پھر عبیداللہ سے روایت کردہ ابن نمیر اور ابن مسہر کی حدیث کی طرح حدیث بیان کی ، اور اس میں یہ اضافہ کیا : خیبر کی پیداوار کے نصف پھلوں کو ( غنیمتوں کے ) حصوں کے مطابق تقسیم کیا جاتا تھا ، رسول اللہ صلی اللہ علیہ وسلم خمس لیتے تھے","",{"u2":"اسامہ بن زید لیثی نے مجھے نافع سے خبر دی، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: جب خیبر فتح ہوا تو یہود نے رسول اللہ صلی اللہ علیہ وسلم سے درخواست کی کہ آپ انہیں اس شرط پر وہیں دینے دیں کہ وہ لوگ وہاں سے حاصل ہونے والی پھلوں اور غلے کی پیداوار کے نصف حصے پر کام کریں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں تمہیں اس شرط پر جب تک ہم چاہیں گے رہنے دیتا ہوں۔\" پھر عبیداللہ سے روایت کردہ ابن نمیر اور ابن مسہر کی حدیث کی طرح حدیث بیان کی، اور اس میں یہ اضافہ کیا: خیبر کی پیداوار کے نصف پھلوں کو (غنیمتوں کے) حصوں کے مطابق تقسیم کیا جاتا تھا، رسول اللہ صلی اللہ علیہ وسلم خمس لیتے تھے"}],[3944,"محمد بن عبدالرحمٰن نے نافع سے ، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے خیبر کے نخلستان اور زمینیں اس شرط پر خیبر کے یہودیوں کے سپرد کیں کہ وہ اپنے اموال لگا کر اس ( کی زمینوں اور باغوں کی دیکھ بھال اور کھیتی باڑی ) کا کام کاج کریں گے اور اس کی پیداوار کا آدھا حصہ رسول اللہ صلی اللہ علیہ وسلم کا ہو گا","",{"u2":"محمد بن عبدالرحمٰن نے نافع سے، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے خیبر کے نخلستان اور زمینیں اس شرط پر خیبر کے یہودیوں کے سپرد کیں کہ وہ اپنے اموال لگا کر اس (کی زمینوں اور باغوں کی دیکھ بھال اور کھیتی باڑی) کا کام کاج کریں گے اور اس کی پیداوار کا آدھا حصہ رسول اللہ صلی اللہ علیہ وسلم کا ہو گا"}],[3945,"موسیٰ بن عقبہ نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے یہود اور نصاریٰ کو سرزمین حجاز سے جلا وطن کیا ، اور یہ کہ جب رسول اللہ صلی اللہ علیہ وسلم نے خیبر پر غلبہ حاصل کیا تو آپ نے یہود کو وہاں سے نکالنے کا ارادہ فرمایا ، آپ صلی اللہ علیہ وسلم کے اس پر غلبہ پا لینے کے بعد وہ زمین اللہ عزوجل ، اس کے رسول اور مسلمانوں کی تھی ۔ آپ نے یہود کو وہاں سے نکالنے کا ارادہ کیا تو یہود نے رسول اللہ صلی اللہ علیہ وسلم سے درخواست کی کہ آپ انہیں اس شرط پر وہیں دینے دیں کہ وہ کام ( باغوں اور کھیتوں کی نگہداشت اور کاشت ) کی ذمہ داری لے لیں گے اور آدھا پھل ( پیداوار ) ان کا ہو گا ، تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا : \" ہم جب تک چاہیں گے تمہیں وہاں رہنے دیں گے ۔ \" پھر وہ وہیں رہے حتی کہ سیدنا عمر رضی اللہ عنہ نے انہیں تیماء ور اریحاء کی طرف جلا وطن کر دیا","",{"u2":"موسیٰ بن عقبہ نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے یہود اور نصاریٰ کو سرزمین حجاز سے جلا وطن کیا، اور یہ کہ جب رسول اللہ صلی اللہ علیہ وسلم نے خیبر پر غلبہ حاصل کیا تو آپ نے یہود کو وہاں سے نکالنے کا ارادہ فرمایا، آپ صلی اللہ علیہ وسلم کے اس پر غلبہ پا لینے کے بعد وہ زمین اللہ عزوجل، اس کے رسول اور مسلمانوں کی تھی۔ آپ نے یہود کو وہاں سے نکالنے کا ارادہ کیا تو یہود نے رسول اللہ صلی اللہ علیہ وسلم سے درخواست کی کہ آپ انہیں اس شرط پر وہیں دینے دیں کہ وہ کام (باغوں اور کھیتوں کی نگہداشت اور کاشت) کی ذمہ داری لے لیں گے اور آدھا پھل (پیداوار) ان کا ہو گا، تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"ہم جب تک چاہیں گے تمہیں وہاں رہنے دیں گے۔\" پھر وہ وہیں رہے حتی کہ سیدنا عمر رضی اللہ عنہ نے انہیں تیماء ور اریحاء کی طرف جلا وطن کر دیا"}],[3946,"عطاء نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی بھی مسلمان ( جو ) درخت لگاتا ہے ، اس میں سے جو بھی کھایا جائے وہ اس کے لیے صدقہ ہوتا ہے ، اور اس میں سے جو چوری کیا جائے وہ اس کے لیے صدقہ ہوتا ہے اور جنگلی جانور اس میں سے جو کھا جائیں وہ بھی اس کے لیے صدقہ ہوتا ہے اور جو پرندے کھا جائیں وہ بھی اس کے لیے صدقہ ہوتا ہے اور کوئی اس میں ( کسی طرح کی ) کمی نہیں کرتا مگر وہ اس کے لیے صدقہ ہوتا ہے","",{"u2":"عطاء نے سیدنا جابر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی بھی مسلمان (جو) درخت لگاتا ہے، اس میں سے جو بھی کھایا جائے وہ اس کے لیے صدقہ ہوتا ہے، اور اس میں سے جو چوری کیا جائے وہ اس کے لیے صدقہ ہوتا ہے اور جنگلی جانور اس میں سے جو کھا جائیں وہ بھی اس کے لیے صدقہ ہوتا ہے اور جو پرندے کھا جائیں وہ بھی اس کے لیے صدقہ ہوتا ہے اور کوئی اس میں (کسی طرح کی) کمی نہیں کرتا مگر وہ اس کے لیے صدقہ ہوتا ہے"}],[3947,"لیث نے ہمیں ابوزبیر سے خبر دی ، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم ام مبشر انصاریہ رضی اللہ عنہا کے ہاں ان کے نخلستان میں تشریف لے گئے تو نبی صلی اللہ علیہ وسلم نے ان سے فرمایا : \" یہ کھجور کے درخت کس نے لگائے ہیں ، کسی مسلمان نے یا کافر نے؟ \" انہوں نے عرض کی : بلکہ مسلمان نے ۔ تو آپ نے فرمایا : \" جو مسلمان درخت لگاتا ہے یا کاشت کاری کرتا ہے ، پھر اس میں سے انسان ، چوپایہ یا کوئی بھی ( جانور ) کھاتا ہے تو وہ اس کے لیے صدقہ ہوتا ہے","",{"u2":"لیث نے ہمیں ابوزبیر سے خبر دی، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم ام مبشر انصاریہ رضی اللہ عنہا کے ہاں ان کے نخلستان میں تشریف لے گئے تو نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: \"یہ کھجور کے درخت کس نے لگائے ہیں، کسی مسلمان نے یا کافر نے؟\" انہوں نے عرض کی: بلکہ مسلمان نے۔ تو آپ نے فرمایا: \"جو مسلمان درخت لگاتا ہے یا کاشت کاری کرتا ہے، پھر اس میں سے انسان، چوپایہ یا کوئی بھی (جانور) کھاتا ہے تو وہ اس کے لیے صدقہ ہوتا ہے"}],[3948,"محمد بن حاتم اور ابن ابی خلف نے مجھے حدیث بیان کی ، دونوں نے کہا : ہمیں رَوح نے حدیث بیان کی ، انہوں نے کہا : ہمیں ابن جریج نے حدیث بیان کی ، کہا : مجھے ابوزبیر نے خبر دی کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : \" جو بھی مسلمان آدمی درخت لگاتا ہے اور کاشت کاری کرتا ہے ، پھر اس سے کوئی جنگلی جانور ، پرندہ یا کوئی بھی کھائے تو اس کے لیے اس میں اجر ہے ۔ \" ابن ابی خلف نے ( یا کے بغیر ) \" پرندہ کوئی چیز \" کہا","",{"u2":"محمد بن حاتم اور ابن ابی خلف نے مجھے حدیث بیان کی، دونوں نے کہا: ہمیں رَوح نے حدیث بیان کی، انہوں نے کہا: ہمیں ابن جریج نے حدیث بیان کی، کہا: مجھے ابوزبیر نے خبر دی کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: \"جو بھی مسلمان آدمی درخت لگاتا ہے اور کاشت کاری کرتا ہے، پھر اس سے کوئی جنگلی جانور، پرندہ یا کوئی بھی کھائے تو اس کے لیے اس میں اجر ہے۔\" ابن ابی خلف نے (یا کے بغیر) \"پرندہ کوئی چیز\" کہا"}],[3949,"مجھے عمرو بن دینار نے بتایا کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، کہہ رہے تھے : نبی صلی اللہ علیہ وسلم ام معبد رضی اللہ عنہا ( خلیدہ ، سیدنا زید بن حارثہ رضی اللہ عنہ کی اہلیہ ، ان کی دوسری کنیت ام مبشر بھی تھی ) کے پاس باغ میں تشریف لے گئے تو آپ نے پوچھا : \" ام معبد! یہ کھجور کے درخت کس نے لگائے ہیں ، کسی مسلمان نے یا کافر نے؟ \" انہوں نے عرض کی : بلکہ مسلمان نے ۔ آپ نے فرمایا : \" جو بھی مسلمان درخت لگاتا ہے ، پھر اس میں سے کوئی انسان ، چوپایہ اور پرندہ نہیں کھاتا مگر وہ اس کے لیے قیامت کے دن تک صدقہ ہوتا ہے","",{"u2":"مجھے عمرو بن دینار نے بتایا کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا، کہہ رہے تھے: نبی صلی اللہ علیہ وسلم ام معبد رضی اللہ عنہا (خلیدہ، سیدنا زید بن حارثہ رضی اللہ عنہ کی اہلیہ، ان کی دوسری کنیت ام مبشر بھی تھی) کے پاس باغ میں تشریف لے گئے تو آپ نے پوچھا: \"ام معبد! یہ کھجور کے درخت کس نے لگائے ہیں، کسی مسلمان نے یا کافر نے؟\" انہوں نے عرض کی: بلکہ مسلمان نے۔ آپ نے فرمایا: \"جو بھی مسلمان درخت لگاتا ہے، پھر اس میں سے کوئی انسان، چوپایہ اور پرندہ نہیں کھاتا مگر وہ اس کے لیے قیامت کے دن تک صدقہ ہوتا ہے"}],[3950,"ابوبکر بن ابی شیبہ نے کہا : ہمیں حفص بن غیاث نے حدیث بیان کی ، نیز ابوکریب اور اسحاق بن ابراہیم نے ابومعاویہ سے روایت کی ، اور عمرو ناقد نے کہا : ہمیں عمار بن محمد نے حدیث بیان کی ، نیز ابوبکر بن ابی شیبہ نے کہا : ہمیں ابن فُضیل نے حدیث بیان کی ، ان سب ( حفص ، ابومعاویہ ، عمار اور ابن فضیل ) نے اعمش سے ، انہوں نے ابوسفیان ( واسطی ) سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی ۔ عمرو ( ناقد ) نے عمار سے روایت کردہ روایت میں اور ابوکریب نے ابومعاویہ سے روایت کردہ اپنی روایت میں کہا : ام مبشر رضی اللہ عنہا سے روایت ہے ۔ ابن فضیل کی روایت میں ہے : زید بن حارثہ رضی اللہ عنہ کی بیوی سے روایت ہے ، ابومعاویہ سے اسحاق کی روایت میں ہے ، انہوں نے کہا : کبھی انہوں نے ( ابومعاویہ ) نے کہا : ام مبشر نے نبی صلی اللہ علیہ وسلم سے روایت کی اور بسا اوقات انہوں نے ( ام مبشر ) نہیں کہا ۔ ان سب نے کہا : نبی صلی اللہ علیہ وسلم سے روایت ہے ۔ ۔ ۔ ( آگے ) عطاء ، اور ابوزبیر اور عمرو بن دینار کی حدیث ( 3968-3971 ) کی طرح ہے","",{"u2":"ابوبکر بن ابی شیبہ نے کہا: ہمیں حفص بن غیاث نے حدیث بیان کی، نیز ابوکریب اور اسحاق بن ابراہیم نے ابومعاویہ سے روایت کی، اور عمرو ناقد نے کہا: ہمیں عمار بن محمد نے حدیث بیان کی، نیز ابوبکر بن ابی شیبہ نے کہا: ہمیں ابن فُضیل نے حدیث بیان کی، ان سب (حفص، ابومعاویہ، عمار اور ابن فضیل) نے اعمش سے، انہوں نے ابوسفیان (واسطی) سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی۔ عمرو (ناقد) نے عمار سے روایت کردہ روایت میں اور ابوکریب نے ابومعاویہ سے روایت کردہ اپنی روایت میں کہا: ام مبشر رضی اللہ عنہا سے روایت ہے۔ ابن فضیل کی روایت میں ہے: زید بن حارثہ رضی اللہ عنہ کی بیوی سے روایت ہے، ابومعاویہ سے اسحاق کی روایت میں ہے، انہوں نے کہا: کبھی انہوں نے (ابومعاویہ) نے کہا: ام مبشر نے نبی صلی اللہ علیہ وسلم سے روایت کی اور بسا اوقات انہوں نے (ام مبشر) نہیں کہا۔ ان سب نے کہا: نبی صلی اللہ علیہ وسلم سے روایت ہے۔۔۔ (آگے) عطاء، اور ابوزبیر اور عمرو بن دینار کی حدیث (3968-3971) کی طرح ہے"}],[3951,"ابوعوانہ نے قتادہ سے اور انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی مسلمان نہیں جو درخت لگائے یا کاشت کاری کرے ، پھر اس سے کوئی پرندہ ، انسان یا چوپایہ کھائے مگر اس کے بدلے میں اس کے لیے صدقہ ہو گا","",{"u2":"ابوعوانہ نے قتادہ سے اور انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی مسلمان نہیں جو درخت لگائے یا کاشت کاری کرے، پھر اس سے کوئی پرندہ، انسان یا چوپایہ کھائے مگر اس کے بدلے میں اس کے لیے صدقہ ہو گا"}],[3952,"ابان بن یزید نے ہمیں حدیث بیان کی ، کہا : ہمیں قتادہ نے حدیث بیان کی ، کہا : ہمیں سیدنا انس بن مالک رضی اللہ عنہ نے حدیث بیان کی کہ نبی صلی اللہ علیہ وسلم انصار کی ایک عورت ام مبشر رضی اللہ عنہا کے نخلستان میں داخل ہوئے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" یہ کھجور کے درخت کس نے لگائے ہیں ، کسی مسلمان نے یا کسی کافر نے؟ \" ان لوگوں نے کہا : مسلمان نے ۔ ۔ ۔ ( آگے ) ان سب کی حدیث کی طرح ہے","",{"u2":"ابان بن یزید نے ہمیں حدیث بیان کی، کہا: ہمیں قتادہ نے حدیث بیان کی، کہا: ہمیں سیدنا انس بن مالک رضی اللہ عنہ نے حدیث بیان کی کہ نبی صلی اللہ علیہ وسلم انصار کی ایک عورت ام مبشر رضی اللہ عنہا کے نخلستان میں داخل ہوئے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ کھجور کے درخت کس نے لگائے ہیں، کسی مسلمان نے یا کسی کافر نے؟\" ان لوگوں نے کہا: مسلمان نے۔۔۔ (آگے) ان سب کی حدیث کی طرح ہے"}],[3953,"ابن وہب نے ہمیں ابن جریج سے خبر دی کہ ابوزبیر نے انہیں جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اگر تم نے اپنے بھائی کو پھل بیچا ہے ۔ \" نیز ابوضمرہ نے ہمیں ابن جریج سے حدیث بیان کی ، انہوں نے ابوزبیر سے روایت کی کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اگر تم اپنے بھائی کو پھل بیچو اور وہ کسی قدرتی آفات کا شکار ہو جائے تو تمہارے لیے حلال نہیں کہ تم اس سے کچھ وصول کرو ۔ تم ناحق اپنے بھائی کا مال کس بنا پر وصول کرو گے"],[3954,"ابن وہب نے ہمیں ابن جریج سے خبر دی کہ ابوزبیر نے انہیں جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اگر تم نے اپنے بھائی کو پھل بیچا ہے ۔ \" نیز ابوضمرہ نے ہمیں ابن جریج سے حدیث بیان کی ، انہوں نے ابوزبیر سے روایت کی کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اگر تم اپنے بھائی کو پھل بیچو اور وہ کسی قدرتی آفات کا شکار ہو جائے تو تمہارے لیے حلال نہیں کہ تم اس سے کچھ وصول کرو ۔ تم ناحق اپنے بھائی کا مال کس بنا پر وصول کرو گے",""],[3955,"ابوعاصم نے ابن جریج سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی","",{"u2":"ابوعاصم نے ابن جریج سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی"}],[3956,"اسماعیل بن جعفر نے حمید سے اور انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے رنگ بدلنے تک کھجور کا پھل بیچنے سے منع فرمایا ۔ ہم نے سیدنا انس رضی اللہ عنہ سے پوچھا : اس کے رنگ بدلنے ( زھو ) سے کیا مراد ہے؟ انہوں نے کہا : وہ سرخ ہو جائے اور زرد ہو جائے ، تمہاری کیا رائے ہے اگر اللہ تعالیٰ نے پھل روک دیا ، تو تم کس بنیاد پر اپنے بھائی کا مال اپنے لیے حلال سمجھو گے","",{"u2":"اسماعیل بن جعفر نے حمید سے اور انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے رنگ بدلنے تک کھجور کا پھل بیچنے سے منع فرمایا۔ ہم نے سیدنا انس رضی اللہ عنہ سے پوچھا: اس کے رنگ بدلنے (زھو) سے کیا مراد ہے؟ انہوں نے کہا: وہ سرخ ہو جائے اور زرد ہو جائے، تمہاری کیا رائے ہے اگر اللہ تعالیٰ نے پھل روک دیا، تو تم کس بنیاد پر اپنے بھائی کا مال اپنے لیے حلال سمجھو گے"}],[3957,"امام مالک نے حمید الطویل سے اور انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے رنگ پکڑنے سے پہلے پھل کی بیع سے منع فرمایا ۔ لوگوں نے پوچھا : رنگ پکڑنے سے کیا مراد ہے؟ انہوں نے جواب دیا : وہ سرخ ہو جائے اور کہا : جب اللہ تعالیٰ پھلوں سے محروم کر دے تو تم کس بنیاد پر اپنے بھائی کا مال اپنے لیے حلال سمجھو گے","",{"u2":"امام مالک نے حمید الطویل سے اور انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے رنگ پکڑنے سے پہلے پھل کی بیع سے منع فرمایا۔ لوگوں نے پوچھا: رنگ پکڑنے سے کیا مراد ہے؟ انہوں نے جواب دیا: وہ سرخ ہو جائے اور کہا: جب اللہ تعالیٰ پھلوں سے محروم کر دے تو تم کس بنیاد پر اپنے بھائی کا مال اپنے لیے حلال سمجھو گے"}],[3958,"عبدالعزیز بن محمد نے حمید کے واسطے سے سیدنا انس رضی اللہ عنہ سے حدیث بیان کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \" اگر اللہ تعالیٰ اسے بارآور نہ کرے تو تم میں سے کوئی اپنے بھائی کے مال کو کس بنیاد پر اپنے یے حلال سمجھے گا","",{"u2":"عبدالعزیز بن محمد نے حمید کے واسطے سے سیدنا انس رضی اللہ عنہ سے حدیث بیان کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"اگر اللہ تعالیٰ اسے بارآور نہ کرے تو تم میں سے کوئی اپنے بھائی کے مال کو کس بنیاد پر اپنے یے حلال سمجھے گا"}],[3959,"بشر بن حکم ، ابراہیم بن دینار اور عبدالجبار بن علاء سے روایت ہے ، الفاظ بشر کے ہیں ، سب نے کہا : ہمیں سفیان بن عیینہ نے حمید اعرج سے حدیث بیان کی ، انہوں نے سلیمان بن عتیق سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے آفات سے پہنچنے والے نقصان کی صورت میں ( قیمت ) ساقط کر دینے کا حکم دیا ہے ۔ ابواسحاق ابراہیم نے ، وہ امام مسلم کے شاگرد ہیں ، کہا : مجھے عبدالرحمٰن بن بشر نے بھی سفیان سے یہی حدیث بیان کی"],[3960,"بشر بن حکم ، ابراہیم بن دینار اور عبدالجبار بن علاء سے روایت ہے ، الفاظ بشر کے ہیں ، سب نے کہا : ہمیں سفیان بن عیینہ نے حمید اعرج سے حدیث بیان کی ، انہوں نے سلیمان بن عتیق سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے آفات سے پہنچنے والے نقصان کی صورت میں ( قیمت ) ساقط کر دینے کا حکم دیا ہے ۔ ابواسحاق ابراہیم نے ، وہ امام مسلم کے شاگرد ہیں ، کہا : مجھے عبدالرحمٰن بن بشر نے بھی سفیان سے یہی حدیث بیان کی",""],[3961,"لیث نے ہمیں بکیر سے حدیث بیان کی ، انہوں نے عیاض بن عبداللہ سے اور انہوں نے سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک آدمی کا ان پھلوں میں نقصان ہو گیا جو اس نے خریدے تھے ، اس کا قرض بڑھ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اس پر صدقہ کرو ۔ \" لوگوں نے اس پر صدقہ کیا لیکن وہ بھی قرض کی ادائیگی ( جتنی مالیت ) تک نہ پہنچا ، تو رسول اللہ صلی اللہ علیہ وسلم نے اس کے قرض داروں سے فرمایا : \" جو تمہیں مل جائے ، وہ لے لو ، تمہارے لیے اس کے علاوہ اور کچھ نہیں","",{"u2":"لیث نے ہمیں بکیر سے حدیث بیان کی، انہوں نے عیاض بن عبداللہ سے اور انہوں نے سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک آدمی کا ان پھلوں میں نقصان ہو گیا جو اس نے خریدے تھے، اس کا قرض بڑھ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس پر صدقہ کرو۔\" لوگوں نے اس پر صدقہ کیا لیکن وہ بھی قرض کی ادائیگی (جتنی مالیت) تک نہ پہنچا، تو رسول اللہ صلی اللہ علیہ وسلم نے اس کے قرض داروں سے فرمایا: \"جو تمہیں مل جائے، وہ لے لو، تمہارے لیے اس کے علاوہ اور کچھ نہیں"}],[3962,"عمرو بن حارث نے بکیر بن اشج سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی","",{"u2":"عمرو بن حارث نے بکیر بن اشج سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی"}],[3963,"عمرہ بنت عبدالرحمان ( بن عوف ) نے کہا : میں نے سیدہ عائشہ رضی اللہ عنہا کو کہتے ہوئے سنا : رسول اللہ صلی اللہ علیہ وسلم نے دروازے کے پاس جھگڑا کرنے والوں کی آواز سنی ، ان دونوں کی آوازیں بلند تھیں اور ان میں سے ایک دوسرے سے کچھ کمی کرنے کی اور کسی چیز میں نرمی کی درخواست کر رہا تھا اور وہ ( دوسرا ) کہہ رہا تھا : اللہ کی قسم! میں ایسا نہیں کروں گا ۔ رسول اللہ صلی اللہ علیہ وسلم ان دونوں کے پاس باہر تشریف لے گئے اور فرمانے لگے : \" اللہ ( کے نام ) پر قسم اٹھانے والا کہاں ہے کہ وہ نیکی کا کام نہیں کرے گا؟ \" اس نے عرض کی : اے اللہ کے رسول! میں ہوں ، اس شخص کے لیے وی صورت ہے جو یہ پسند کرے ۔ ( وہ فورا اپنے بھائی کا مطالبہ مان گیا)","",{"u2":"عمرہ بنت عبدالرحمان (بن عوف) نے کہا: میں نے سیدہ عائشہ رضی اللہ عنہا کو کہتے ہوئے سنا: رسول اللہ صلی اللہ علیہ وسلم نے دروازے کے پاس جھگڑا کرنے والوں کی آواز سنی، ان دونوں کی آوازیں بلند تھیں اور ان میں سے ایک دوسرے سے کچھ کمی کرنے کی اور کسی چیز میں نرمی کی درخواست کر رہا تھا اور وہ (دوسرا) کہہ رہا تھا: اللہ کی قسم! میں ایسا نہیں کروں گا۔ رسول اللہ صلی اللہ علیہ وسلم ان دونوں کے پاس باہر تشریف لے گئے اور فرمانے لگے: \"اللہ (کے نام) پر قسم اٹھانے والا کہاں ہے کہ وہ نیکی کا کام نہیں کرے گا؟\" اس نے عرض کی: اے اللہ کے رسول! میں ہوں، اس شخص کے لیے وی صورت ہے جو یہ پسند کرے۔ (وہ فورا اپنے بھائی کا مطالبہ مان گیا"}],[3964,"عبداللہ بن وہب نے ہمیں خبر دی ، کہا : مجھے یونس نے ابن شہاب سے خبر دی ، کہا : مجھے عبداللہ بن کعب بن مالک نے حدیث بیان کی ، انہوں نے اپنے والد سے خبر دی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ، مسجد میں ، ابن ابی حدرد رضی اللہ عنہ سے قرض کا مطالبہ کیا جو ان کے ذمے تھا تو ان کی آوازیں بلند ہو گئیں ، یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم نے گھر کے اندر ان کی آوازیں سنیں تو رسول اللہ صلی اللہ علیہ وسلم ان کی طرف گئے یہاں تک کہ آپ نے اپنے حجرے کا پردہ ہٹایا اور کعب بن مالک کو آواز دی : \" کعب! \" انہوں نے عرض کی : حاضر ہوں ، اے اللہ کے رسول! آپ نے اپنے ہاتھ سے انہیں اشارہ کیا کہ اپنے قرض کا آدھا حصہ معاف کر دو ۔ کعب نے کہا : اللہ کے رسول! کر دیا ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے ( دوسرے سے ) فرمایا : \" اٹھو اور اس کا قرض چکا دو","",{"u2":"عبداللہ بن وہب نے ہمیں خبر دی، کہا: مجھے یونس نے ابن شہاب سے خبر دی، کہا: مجھے عبداللہ بن کعب بن مالک نے حدیث بیان کی، انہوں نے اپنے والد سے خبر دی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں، مسجد میں، ابن ابی حدرد رضی اللہ عنہ سے قرض کا مطالبہ کیا جو ان کے ذمے تھا تو ان کی آوازیں بلند ہو گئیں، یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم نے گھر کے اندر ان کی آوازیں سنیں تو رسول اللہ صلی اللہ علیہ وسلم ان کی طرف گئے یہاں تک کہ آپ نے اپنے حجرے کا پردہ ہٹایا اور کعب بن مالک کو آواز دی: \"کعب!\" انہوں نے عرض کی: حاضر ہوں، اے اللہ کے رسول! آپ نے اپنے ہاتھ سے انہیں اشارہ کیا کہ اپنے قرض کا آدھا حصہ معاف کر دو۔ کعب نے کہا: اللہ کے رسول! کر دیا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے (دوسرے سے) فرمایا: \"اٹھو اور اس کا قرض چکا دو"}],[3965,"عبدالرحمٰن بن ہُرمز نے عبداللہ بن کعب بن مالک سے اور انہوں نے سیدنا کعب بن مالک رضی اللہ عنہ سے روایت کی کہ ان کا کچھ مال عبداللہ بن ابی حدرد اسلمی رضی اللہ عنہ کے ذمے تھا ۔ وہ انہیں ملے تو کعب رضی اللہ عنہ ان کے ساتھ لگ گئے ، ان کی باہم تکرار ہوئی حتی کہ ان کی آوازیں بلند ہو گئیں ۔ رسول اللہ صلی اللہ علیہ وسلم کا ان سے پاس سے گزرا تو آپ نے فرمایا : \" کعب! \" پھر آپ نے اپنے ہاتھ سے اشارہ کیا ، گویا آپ فرما رہے تھے کہ آدھا لے لو ، چنانچہ انہوں نے اس مال میں سے جو اس ( ابن ابی حدرد اسلمی رضی اللہ عنہ ) کے ذمے تھا ، آدھا لے لیا اور آدھا چھوڑ دیا",""],[3966,"زہیر بن حرب نے کہا : ہمیں یحییٰ بن سعید نے حدیث بیان کی ، کہا : مجھے ابوبکر بن محمد بن عمرو بن حزم نے خبر دی کہ انہیں عمر بن عبدالعزیز نے خبر دی ، انہیں ابوبکر بن عبدالرحمٰن بن حارث بن ہشام نے بتایا کہ انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ۔ ۔ یا ( اس طرح کہا : ) میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے ۔ ۔ : \" جس نے اپنا مال جوں کا توں اس شخص کے پاس پایا جو مفلس ہو چکا ہے ۔ ۔ یا اس انسان کے پاس جو مفلس ہو چکا ہے ۔ ۔ تو وہ دوسروں کی نسبت اس ( مال ) کا زیادہ حق دار ہے","",{"u2":"زہیر بن حرب نے کہا: ہمیں یحییٰ بن سعید نے حدیث بیان کی، کہا: مجھے ابوبکر بن محمد بن عمرو بن حزم نے خبر دی کہ انہیں عمر بن عبدالعزیز نے خبر دی، انہیں ابوبکر بن عبدالرحمٰن بن حارث بن ہشام نے بتایا کہ انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا۔۔ یا (اس طرح کہا:) میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے۔۔: \"جس نے اپنا مال جوں کا توں اس شخص کے پاس پایا جو مفلس ہو چکا ہے۔۔ یا اس انسان کے پاس جو مفلس ہو چکا ہے۔۔ تو وہ دوسروں کی نسبت اس (مال) کا زیادہ حق دار ہے"}],[3967,"یحییٰ بن یحییٰ نے ہمیں حدیث بیان کی ، کہا : ہمیں ہشیم نے خبر دی ، ( اسی طرح ) قتیبہ بن سعید اور محمد بن رمح دونوں نے لیث بن سعد سے روایت کی اور ( اسی طرح ) ابوربیع اور یحییٰ بن حبیب حارثی نے کہا : ہمیں حماد بن زید نے حدیث بیان کی ۔ ابوبکر بن ابی شیبہ نے کہا : ہمیں سفیان بن عیینہ نے حدیث سنائی ۔ محمد بن مثنیٰ نے بیان کیا : ہمیں عبدالوہاب ، یحییٰ بن سعید ( القطان ) اور حفص بن غیاث ، سب نے یحییٰ بن سعید سے ، اسی سند کے ساتھ زہیر کی حدیث کے ہم معنی حدیث بیان کی ، البتہ ان میں سے ابن رمح نے اپنی روایت میں کہا : \" جس کسی آدمی کو مفلس قرار دیا گیا ہو","",{"u2":"یحییٰ بن یحییٰ نے ہمیں حدیث بیان کی، کہا: ہمیں ہشیم نے خبر دی، (اسی طرح) قتیبہ بن سعید اور محمد بن رمح دونوں نے لیث بن سعد سے روایت کی اور (اسی طرح) ابوربیع اور یحییٰ بن حبیب حارثی نے کہا: ہمیں حماد بن زید نے حدیث بیان کی۔ ابوبکر بن ابی شیبہ نے کہا: ہمیں سفیان بن عیینہ نے حدیث سنائی۔ محمد بن مثنیٰ نے بیان کیا: ہمیں عبدالوہاب، یحییٰ بن سعید (القطان) اور حفص بن غیاث، سب نے یحییٰ بن سعید سے، اسی سند کے ساتھ زہیر کی حدیث کے ہم معنی حدیث بیان کی، البتہ ان میں سے ابن رمح نے اپنی روایت میں کہا: \"جس کسی آدمی کو مفلس قرار دیا گیا ہو"}],[3968,"ابن ابی حسین نے مجھے حدیث بیان کی کہ انہیں ابوبکر بن محمد بن عمرو بن حزم نے خبر دی کہ انہیں عمر بن عبدالعزیز نے ابوبکر بن عبدالرحمٰن کی ( روایت کردہ ) حدیث سنائی ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ کی ( روایت کردہ ) حدیث بیان کی ، انہوں نے نبی صلی اللہ علیہ وسلم سے اس شخص کے بارے میں روایت کی جو کنگال ہو جائے ، جب اس کے پاس سامان ملے اور اس نے اس میں تصرف نہ کیا ہو ، ( فرمایا : ) \" تو وہ اس کے مالک کا ہے ، جس نے اسے فروخت کیا تھا","",{"u2":"ابن ابی حسین نے مجھے حدیث بیان کی کہ انہیں ابوبکر بن محمد بن عمرو بن حزم نے خبر دی کہ انہیں عمر بن عبدالعزیز نے ابوبکر بن عبدالرحمٰن کی (روایت کردہ) حدیث سنائی، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ کی (روایت کردہ) حدیث بیان کی، انہوں نے نبی صلی اللہ علیہ وسلم سے اس شخص کے بارے میں روایت کی جو کنگال ہو جائے، جب اس کے پاس سامان ملے اور اس نے اس میں تصرف نہ کیا ہو، (فرمایا:) \"تو وہ اس کے مالک کا ہے، جس نے اسے فروخت کیا تھا"}],[3969,"شعبہ نے ہمیں قتادہ سے حدیث بیان کی ، انہیں نے نضر بن انس سے ، انہوں نے بشیر بن نہیک سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" جب کوئی آدمی مفلس ہو جائے اور کوئی آدمی ( اس کے پاس ) اپنا مال جوں کا توں پائے تو وہ اس کا زیادہ حق دار ہے","",{"u2":"شعبہ نے ہمیں قتادہ سے حدیث بیان کی، انہیں نے نضر بن انس سے، انہوں نے بشیر بن نہیک سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"جب کوئی آدمی مفلس ہو جائے اور کوئی آدمی (اس کے پاس) اپنا مال جوں کا توں پائے تو وہ اس کا زیادہ حق دار ہے"}],[3970,"سعید اور ہشام دونوں نے قتادہ سے اسی سند کے ساتھ اسی کی مانند روایت کی اور کہا : \" تو وہ ( دیگر ) قرض خواہوں کی نسبت اس ( مال ) کا زیادہ حقدار ہے ۔","",{"u2":"سعید اور ہشام دونوں نے قتادہ سے اسی سند کے ساتھ اسی کی مانند روایت کی اور کہا: \"تو وہ (دیگر) قرض خواہوں کی نسبت اس (مال) کا زیادہ حقدار ہے۔\""}],[3971,"عراک بن مالک نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب کوئی آدمی مفلس قرار دیا جائے اور ( کسی بیچنے والے ) شخص کو اس کے ہاں اپنا سامان جوں کا توں مل جائے تو وہ اس کا زیادہ حقدار ہے ۔","",{"u2":"عراک بن مالک نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب کوئی آدمی مفلس قرار دیا جائے اور (کسی بیچنےوالے) شخص کو اس کے ہاں اپنا سامان جوں کا توں مل جائے تو وہ اس کا زیادہ حقدار ہے۔\""}],[3972,"منصور نے ہمیں ربعی بن حراش سے حدیث بیان کی کہ سیدنا حذیفہ ( بن یمان رضی اللہ عنہ ) نے انہیں حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم سے پہلے لوگوں میں سے ایک آدمی کی روح کا فرشتوں نے استقبال کیا تو انہوں نے پوچھا : \" کیا تو نے کوئی نیکی کی ہے؟ اس نے کہا : نہیں ، انہوں نے کہا : یاد کر ، اس نے کہا : میں ( دنیا میں ) لوگوں کے ساتھ قرض کا معاملہ کرتا تو اپنے خادموں کو حکم دیتا تھا کہ وہ تنگدست کو مہلت دیں اور خوشحال سے نرمی برتیں ۔ ( انہوں نے ) کہا : اللہ عزوجل نے فرمایا ہے : ( تم بھی ) اس کے ساتھ نرمی کا سلوک کرو ۔","",{"u2":"منصور نے ہمیں ربعی بن حراش سے حدیث بیان کی کہ حضرت حذیفہ (بن یمان رضی اللہ عنہ) نے انہیں حدیث بیان کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم سے پہلے لوگوں میں سے ایک آدمی کی روح کا فرشتوں نے استقبال کیا تو انہوں نے پوچھا: \"کیا تو نے کوئی نیکی کی ہے؟ اس نے کہا: نہیں، انہوں نے کہا: یاد کر، اس نے کہا: میں (دنیا میں) لوگوں کے ساتھ قرض کا معاملہ کرتا تو اپنے خادموں کو حکم دیتا تھا کہ وہ تنگدست کو مہلت دیں اور خوشحال سے نرمی برتیں۔ (انہوں نے)کہا: اللہ عزوجل نے فرمایا ہے: (تم بھی) اس کے ساتھ نرمی کا سلوک کرو۔"}],[3973,"نُعَیم بن ابی ہند نے ربعی بن حراش سے روایت کی ، انہوں نے کہا : سیدنا حذیفہ اور سیدنا ابومسعود ( انصاری ) رضی اللہ عنہ اکٹھے ہوئے تو سیدنا حذیفہ رضی اللہ عنہ نے کہا : ایک آدمی اللہ عزوجل کے حضور پیش ہوا تو اللہ نے پوچھا : \" تو نے کیا عمل کیا؟ \" اس نے کہا : میں نے کوئی نیکی نہیں کی ، سوائے اس کے کہ میں مالدار آدمی تھا ، میں لوگوں سے اس ( میں سے دیے ہوئے قرض ) کا مطالبہ کرتا تو مالدار سے خوش دلی سے قبول کرتا اور تنگ دست سے درگزر ( مزید مہلت دیتا یا نہ دے سکتا تو معاف ) کرتا ۔ فرمایا : \" ( تم بھی ) میرے بندے سے درگزر کرو ۔ \" ( یہ سن کر ) سیدنا ابومسعود رضی اللہ عنہ نے کہا : میں نے بھی رسول اللہ صلی اللہ علیہ وسلم کو اس طرح فرماتے ہوئے سنا ہے ۔","",{"u2":"نُعَیم بن ابی ہند نے ربعی بن حراش سے روایت کی، انہوں نے کہا: حضرت حذیفہ اور حضرت ابومسعود (انصاری) رضی اللہ عنہ اکٹھے ہوئے تو سیدنا حذیفہ رضی اللہ عنہ نے کہا: ایک آدمی اللہ عزوجل کے حضور پیش ہوا تو اللہ نے پوچھا: \"تو نے کیا عمل کیا؟\" اس نے کہا: میں نے کوئی نیکی نہیں کی، سوائے اس کے کہ میں مالدار آدمی تھا، میں لوگوں سے اس (میں سے دیے ہوئے قرض) کا مطالبہ کرتا تو مالدار سے خوش دلی سے قبول کرتا اور تنگ دست سے درگزر (مزید مہلت دیتا یا نہ دے سکتا تو معاف) کرتا۔ فرمایا: \"(تم بھی) میرے بندے سے درگزر کرو۔\" (یہ سن کر) سیدنا ابومسعود رضی اللہ عنہ نے کہا: میں نے بھی رسول اللہ صلی اللہ علیہ وسلم کو اس طرح فرماتے ہوئے سنا ہے۔"}],[3974,"عبدالملک بن عمیر نے ربعی بن حراش سے ، انہوں نے سیدنا حذیفہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی : \" ایک آدمی فوت ہوا اور جنت میں داخل ہوا تو اس سے کہا گیا : تو کیا عمل کرتا تھا؟ ۔ ۔ کہا : اس نے خود یاد کیا یا اسے یاد کرایا گیا ۔ ۔ اس نے کہا : ( اے میرے پروردگار! ) میں لوگوں سے ( قرض پر ) خرید و فروخت کرتا تھا ، تو میں تنگ دست کو مہلت دیتا اور سکہ اور نقدی وصول کرنے میں نرمی کرتا تھا ، تو اس کی مغفرت کر دی گئی \" اس پر سیدنا ابومسعود رضی اللہ عنہ نے کہا : میں نے بھی یہی حدیث رسول اللہ صلی اللہ علیہ وسلم سے سنی تھی ۔","",{"u2":"عبدالملک بن عمیر نے ربعی بن حراش سے، انہوں نے سیدنا حذیفہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی: \"ایک آدمی فوت ہوا اور جنت میں داخل ہوا تو اس سے کہا گیا: تو کیا عمل کرتا تھا؟۔۔ کہا: اس نے خود یاد کیا یا اسے یاد کرایا گیا۔۔ اس نے کہا: (اے میرے پروردگار!) میں لوگوں سے (قرض پر) خرید و فروخت کرتا تھا، تو میں تنگ دست کو مہلت دیتا اور سکہ اور نقدی وصول کرنے میں نرمی کرتا تھا، تو اس کی مغفرت کر دی گئی\" اس پر سیدنا ابومسعود رضی اللہ عنہ نے کہا: میں نے بھی یہی حدیث رسول اللہ صلی اللہ علیہ وسلم سے سنی تھی۔"}],[3975,"حذیفہ رضی االله عنہ سے روایت ہے االله عزوجل کے پس اس کا ایک بندہ لایا گیا جس کو اس نے مال دیا تھا تو االله تعالیٰ نے اس سے پوچھا تو نے دنیا میں کیا عمل کیا؟ اور االله سے کچھ نہیں چھپا سکتے ۔ بندے نے کہا اے میرے مالک! تونے اپنا مال مجھ کو دیا تھا میں لوگوں کے ہاتھ بیچتا تھا اور میری عادت تھی درگزر کرنے کی ( اور معاف کرنے کی ) تو میں آسانی کرتا تھا مالدار پر اور مہلت دیتا تھا نادار کو ۔ تب اللها نے فرمایا پھر میں تو زیادہ لائق ہوں معاف کرنے کے لیے تجھ سے ، درگزر کرو میرے بندے سے ۔ پھر عقبہ بن عامرجہنیؓ اور ابومسعود انصاری رضی االله عنہ نے کہا ہم نے ایسا ہی سُنا ہے رسول االله صلی اللہ علیہ وسلم کے منہ مبارک سے ۔"],[3976,"سیدنا ابی مسعود رضی االله عنہ سے روایت ہے رسول االله صلی اللہ علیہ وسلم نے فرمایا تم سے پہلے ایک شخص کا حساب ہوا تو اس کی کوئی نیکی نہ نکلی مگر اتنی کہ وہ لوگوں سے معاملہ کرتا تھا اور مالدار تھا تو اپنے غلاموں کو حکم کرتا نادار کو معاف کردینے کا ۔ تب االله تعالیٰ نے فرمایا ہم زیادہ حق رکھتے ہیں معاف کرنے کا تجھ سے اور حکم دیا کہ معاف کرو اس کے گناہوں کو ۔"],[3977,"ابوہریرہؓ سے روایت ہے رسول االله صلی اللہ علیہ وسلم نے فرمایا ایک شخص لوگوں کو قرض دیا کرتا اور وہ اپنے نوکروں سے کہتا جو مفلس ہو اس کو معاف کردینا شاید االله تعالیٰ اس کے بدلے ہم کو معاف کرے ۔ پھر وہ االله تعالیٰ سے ملا االله نے اس کو بخش دیا ۔ باب : حد لگانے سے گناہ مٹ جاتا ہے ۔"],[3978,"یونس نے ابن شہاب سے خبر دی کہ انہیں عبیداللہ بن عبداللہ بن عتبہ نے حدیث بیان کی کہ انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے ۔ ۔ ۔ اسی ( سابقہ حدیث ) کے مانند ۔","",{"u2":"یونس نے ابن شہاب سے خبر دی کہ انہیں عبیداللہ بن عبداللہ بن عتبہ نے حدیث بیان کی کہ انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے۔۔۔ اسی (سابقہ حدیث) کے مانند۔"}],[3979,"حماد بن زید نے ہمیں ایوب سے حدیث بیان کی ، انہوں نے یحییٰ بن ابی کثیر سے اور انہوں نے عبداللہ بن ابی قتادہ سے روایت کی کہ سیدنا ابو قتادہ نے اپنے ایک قرض دار کو تلاش کیا تو وہ ان سے چھپ گیا ، پھر ( بعد میں ) انہوں نے اسے پا لیا تو اس نے کہا : میں تنگ دست ہوں ۔ انہوں نے کہا : اللہ کی قسم؟ اس نے جواب دیا : اللہ کی قسم! انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : \" جسے یہ بات اچھی لگے کہ اللہ تعالیٰ اسے قیامت کے دن کی سختیوں سے نجات دے تو وہ تنگ دست کو سہولت دے یا اسے معاف کر دے ۔","",{"u2":"حماد بن زید نے ہمیں ایوب سے حدیث بیان کی، انہوں نے یحییٰ بن ابی کثیر سے اور انہوں نے عبداللہ بن ابی قتادہ سے روایت کی کہ حضرت ابو قتادہ نے اپنے ایک قرض دار کو تلاش کیا تو وہ ان سے چھپ گیا، پھر (بعد میں) انہوں نے اسے پا لیا تو اس نے کہا: میں تنگ دست ہوں۔ انہوں نے کہا: اللہ کی قسم؟ اس نے جواب دیا: اللہ کی قسم! انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: \"جسے یہ بات اچھی لگے کہ اللہ تعالیٰ اسے قیامت کے دن کی سختیوں سے نجات دے تو وہ تنگ دست کو سہولت دے یا اسے معاف کر دے۔\""}],[3980,"جریر بن حازم نے ایوب سے اسی سند کے ساتھ اسی طرح حدیث بیان کی ۔",""],[3981,"اعرج ( عبدالرحمٰن بن ہرمز مدنی ) نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" غنی آدمی کا ٹال مٹول کرنا ظلم ہے اور جب تم میں سے کسی کو کسی مال دار ( سے وصولی ) پر لگایا جائے تو اسے لگ جانا چاہئے ۔","",{"u2":"اعرج (عبدالرحمٰن بن ہرمز مدنی) نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"غنی آدمی کا ٹال مٹول کرنا ظلم ہے اور جب تم میں سے کسی کو کسی مال دار (سے وصولی) پر لگایا جائے تو اسے لگ جانا چاہئے۔\""}],[3982,"ہمام بن منبہ نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ۔ ۔ اسی کے مانند","",{"u2":"ہمام بن منبہ نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی۔۔ اسی کے مانند"}],[3983,"وکیع اور یحییٰ بن سعید نے ابن جریج سے حدیث بیان کی ، انہوں نے ابوزبیر سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے بچ جانے والے پانی کو فروخت کرنے سے منع فرمایا ۔","",{"u2":") وکیع اور یحییٰ بن سعید نے ابن جریج سے حدیث بیان کی، انہوں نے ابوزبیر سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے بچ جانے والے پانی کو فروخت کرنے سے منع فرمایا۔\nوکیع اور یحییٰ بن سعید نے ابن جریج سے حدیث بیان کی، انہوں نے ابوزبیر سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے بچ جانے والے پانی کو فروخت کرنے سے منع فرمایا۔) وکیع اور یحییٰ بن سعید نے ابن جریج سے حدیث بیان کی، انہوں نے ابوزبیر سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے بچ جانے والے پانی کو فروخت کرنے سے منع فرمایا۔"}],[3984,"روح بن عبادہ نے ہمیں خبر دی ، کہا : ہمیں ابن جریج نے حدیث بیان کی ، کہا : مجھے ابوزبیر نے بتایا کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے اونٹ کی جفتی فروخت کرنے ، کاشتکاری کے لیے پانی اور زمین کو فروخت کرنے سے منع فرمایا ۔ رسول اللہ صلی اللہ علیہ وسلم نے ان ساری باتوں سے منع فرمایا ہے ۔","",{"u2":"روح بن عبادہ نے ہمیں خبر دی، کہا: ہمیں ابن جریج نے حدیث بیان کی، کہا: مجھے ابوزبیر نے بتایا کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے اونٹ کی جفتی فروخت کرنے، کاشتکاری کے لیے پانی اور زمین کو فروخت کرنے سے منع فرمایا۔ رسول اللہ صلی اللہ علیہ وسلم نے ان ساری باتوں سے منع فرمایا ہے۔"}],[3985,"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" زائد پانی کو نہ روکا جائے کہ اس کے ذریعے سے گھاس روکی جائے ۔","",{"u2":"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"زائد پانی کو نہ روکا جائے کہ اس کے ذریعے سے گھاس روکی جائے۔\""}],[3986,"ابن شہاب سے روایت ہے ، کہا : مجھے سعید بن مسیب اور ابوسلمہ بن عبدالرحمٰن نے حدیث بیان کی کہ سیدنا ابوہریرہ رضی اللہ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" زائد پانی نہ روکو کہ اس کے ذریعے سے تم گھاس روک دو ۔","",{"u2":"ابن شہاب سے روایت ہے، کہا: مجھے سعید بن مسیب اور ابوسلمہ بن عبدالرحمٰن نے حدیث بیان کی کہ سیدنا ابوہریرہ رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"زائد پانی نہ روکو کہ اس کے ذریعے سے تم گھاس روک دو۔\""}],[3987,"ہلال بن اسامہ نے خبر دی کہ ابوسلمہ بن عبدالرحمٰن نے انہیں بتایا کہ انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" زائد پانی کو فروخت نہ کیا جائے کہ اس کے ذریعے سے گھاس کو فروخت کیا جائے ۔","",{"u2":"ہلال بن اسامہ نے خبر دی کہ ابوسلمہ بن عبدالرحمٰن نے انہیں بتایا کہ انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"زائد پانی کو فروخت نہ کیا جائے کہ اس کے ذریعے سے گھاس کو فروخت کیا جائے۔\""}],[3988,"امام مالک نے ابن شہاب سے ، انہوں نے ابوبکر بن عبدالرحمٰن سے اور انہوں نے سیدنا ابومسعود انصاری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے کتے کی قیمت ، زانیہ کے معاوضے اور کاہن کے نذرانے سے منع فرمایا ۔","",{"u2":"امام مالک نے ابن شہاب سے، انہوں نے ابوبکر بن عبدالرحمٰن سے اور انہوں نے سیدنا ابومسعود انصاری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے کتے کی قیمت، زانیہ کے معاوضے اور کاہن کے نذرانے سے منع فرمایا۔"}],[3989,"قتیبہ بن سعید اور محمد بن رُمح نے لیث بن سعد سے روایت کی ، نیز ابوبکر بن ابی شیبہ نے کہا : ہمیں سفیان بن عیینہ نے حدیث سنائی ، ان دونوں ( لیث بن سعد اور سفیابن بن عیینہ ) نے زہری سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ۔ ابن رمح کی روایت کردہ لیث کی حدیث میں ہے کہ انہوں ( ابوبکر بن عبدالرحمان ) نے سیدنا ابومسعود رضی اللہ عنہ سے سماعت کی ۔","",{"u2":") قتیبہ بن سعید اور محمد بن رُمح نے لیث بن سعد سے روایت کی، نیز ابوبکر بن ابی شیبہ نے کہا: ہمیں سفیان بن عیینہ نے حدیث سنائی، ان دونوں (لیث بن سعد اور سفیابن بن عیینہ) نے زہری سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی۔\nابن رمح کی روایت کردہ لیث کی حدیث میں ہے کہ انہوں (ابوبکر بن عبدالرحمان) نے سیدنا ابومسعود رضی اللہ عنہ سے سماعت کی۔"}],[3990,"محمد بن یوسف سے روایت ہے ، انہوں نے کہا : میں نے سائب بن یزید سے سنا ، وہ سیدنا رافع بن خدیج رضی اللہ عنہ سے حدیث بیان کر رہے تھے ، انہوں نے کہا : میں نے نبی صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : \" بدترین کمائی زانیہ کی اجرت ، کتے کی قیمت اور پچھنے لگانے والے کی کمائی ہے","",{"u2":"محمد بن یوسف سے روایت ہے، انہوں نے کہا: میں نے سائب بن یزید سے سنا، وہ سیدنا رافع بن خدیج رضی اللہ عنہ سے حدیث بیان کر رہے تھے، انہوں نے کہا: میں نے نبی صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: \"بدترین کمائی زانیہ کی اجرت، کتے کی قیمت اور پچھنے لگانے والے کی کمائی ہے"}],[3991,"اوزاعی نے یحییٰ بن ابی کثیر سے روایت کی ، کہا : مجھے ابراہیم بن قارظ نے سائب بن یزید سے حدیث بیان کی ، انہوں نے کہا : مجھے سیدنا رافع بن خدیج رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کی ، آپ نے فرمایا : \" کتے کی قیمت خبیث ( ناپاک اور گندی ) ہے ۔ زانیہ کی اجرت خبیث ہے اور پچھنے لگانے والے کی کمائی خبیث ہے ۔","",{"u2":"اوزاعی نے یحییٰ بن ابی کثیر سے روایت کی، کہا: مجھے ابراہیم بن قارظ نے سائب بن یزید سے حدیث بیان کی، انہوں نے کہا: مجھے سیدنا رافع بن خدیج رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کی، آپ نے فرمایا: \"کتے کی قیمت خبیث (ناپاک اور گندی) ہے۔ زانیہ کی اجرت خبیث ہے اور پچھنے لگانے والے کی کمائی خبیث ہے۔\""}],[3992,"معمر نے یحییٰ بن ابی کثیر سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ۔","",{"u2":"معمر نے یحییٰ بن ابی کثیر سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی۔"}],[3993,"ہشام نے ہمیں یحییٰ بن ابی کثیر سے حدیث بیان کی ، کہا : مجھے ابراہیم نے عبداللہ نے سائب بن یزید سے حدیث بیان کی ، انہوں نے کہا : ہمیں سیدنا رافع بن خدیج رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اسی کے مانند حدیث بیان کی ۔","",{"u2":"ہشام نے ہمیں یحییٰ بن ابی کثیر سے حدیث بیان کی، کہا: مجھے ابراہیم نے عبداللہ نے سائب بن یزید سے حدیث بیان کی، انہوں نے کہا: ہمیں سیدنا رافع بن خدیج رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اسی کے مانند حدیث بیان کی۔"}],[3994,"ابوزبیر سے روایت ہے ، انہوں نے کہا : میں نے سیدنا جابر رضی اللہ عنہ سے کتے اور بلی کی قیمت کے بارے میں پوچھا تو انہوں نے کہا : نبی صلی اللہ علیہ وسلم نےاس سے جھڑک کر روکا ہے ۔"],[3995,"امام مالک نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے کتوں کو مار دینے کا حکم دیا","",{"u2":"امام مالک نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے کتوں کو مار دینے کا حکم دیا"}],[3996,"عبیداللہ نے ہمیں نافع کے حوالے سے سیدنا ابن عمر رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے کتوں کو مارنے کا حکم دیا ۔ آپ نے انہیں مارنے کے لیے مدینہ کی اطراف میں آدمی روانہ کیے ۔","",{"u2":"عبیداللہ نے ہمیں نافع کے حوالے سے سیدنا ابن عمر رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے کتوں کو مارنے کا حکم دیا۔ آپ نے انہیں مارنے کے لیے مدینہ کی اطراف میں آدمی روانہ کیے۔"}],[3997,"اسماعیل بن امیہ نے ہمیں نافع سے حدیث بیان کی ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کتوں کو مارنے کا حکم دیتے تھے ۔ میں مدینہ اور اس کی اطراف میں تلاش کرتا ، ہم کوئی کتا نہ چھوڑتے مگر اسے مار ڈالتے ، حتی کہ ہم دیہات سے آنے والی عورت کے کتے کو بھی ، جو اس کے پیچھے آ جاتا تھا ، قتل کر دیتے تھے ۔","",{"u2":"اسماعیل بن امیہ نے ہمیں نافع سے حدیث بیان کی، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کتوں کو مارنے کا حکم دیتے تھے۔ میں مدینہ اور اس کی اطراف میں تلاش کرتا، ہم کوئی کتا نہ چھوڑتے مگر اسے مار ڈالتے، حتی کہ ہم دیہات سے آنے والی عورت کے کتے کو بھی، جو اس کے پیچھے آ جاتا تھا، قتل کر دیتے تھے۔"}],[3998,"عمرو بن دینار نے ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے شکاری کتے ، بکریوں یا مویشیوں ( کی حفاظت ) کے کتے کے سوا ( باقی ) تمام کتوں کو مار ڈالنے کا حکم دیا ۔ سیدنا ابن عمر رضی اللہ عنہ سے کہا گیا : سیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں : یا کھیت کی حفاظت کرنے والے کتے کے ۔ تو سیدنا ابن عمر رضی اللہ عنہ نے کہا : بے شبہ ابوہریرہ رضی اللہ عنہ کا کھیت بھی ہے ۔","",{"u2":"عمرو بن دینار نے ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے شکاری کتے، بکریوں یا مویشیوں (کی حفاظت) کے کتے کے سوا (باقی) تمام کتوں کو مار ڈالنے کا حکم دیا۔ سیدنا ابن عمر رضی اللہ عنہ سے کہا گیا: سیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں: یا کھیت کی حفاظت کرنے والے کتے کے۔ تو سیدنا ابن عمر رضی اللہ عنہ نے کہا: بے شبہ ابوہریرہ رضی اللہ عنہ کا کھیت بھی ہے۔"}],[3999,"ابوزبیر نے خبر دی کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں کتوں کو مار ڈالنے کا حکم دیا حتی کہ کوئی عورت بادیہ سے اپنے کتے کے ساتھ آتی تو ہم اس کتے کو بھی مار ڈالتے ، پھر نبی صلی اللہ علیہ وسلم نے ہمیں ان کو مارنے سے منع کر دیا اور فرمایا : \" تم ( آنکھوں کے اوپر ) دو ( سفید ) نقطوں والے کالے سیاہ کتے کو نہ چھوڑو ، بلاشبہ وہ شیطان ہے ۔","",{"u2":"ابوزبیر نےخبر دی کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں کتوں کو مار ڈالنے کا حکم دیا حتی کہ کوئی عورت بادیہ سے اپنے کتے کے ساتھ آتی تو ہم اس کتے کو بھی مار ڈالتے، پھر نبی صلی اللہ علیہ وسلم نے ہمیں ان کو مارنے سے منع کر دیا اور فرمایا: \"تم (آنکھوں کے اوپر) دو (سفید) نقطوں والے کالے سیاہ کتے کو نہ چھوڑو، بلاشبہ وہ شیطان ہے۔\""}],[4000,"معاذ عنبری نے ہمیں حدیث بیان کی ، کہا : ہمیں شعبہ نے ابوتیاح سے حدیث سنائی ، انہوں نے مطرف بن عبداللہ سے سنا اور انہوں نے سیدنا ( عبداللہ ) بن مغفل رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے کتوں کو مارنے کا حکم دیا ، پھر فرمایا : \" ان لوگوں کا کتوں سے کیا واسطہ ہے؟ \" بعد میں آپ نے شکاری کتے اور بکریوں ( کی حفاظت ) والے کتے کی اجازت دے دی ۔","",{"u2":"معاذ عنبری نے ہمیں حدیث بیان کی، کہا: ہمیں شعبہ نے ابوتیاح سے حدیث سنائی، انہوں نے مطرف بن عبداللہ سے سنا اور انہوں نے حضرت (عبداللہ) بن مغفل رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے کتوں کو مارنے کا حکم دیا، پھر فرمایا: \"ان لوگوں کا کتوں سے کیا واسطہ ہے؟\" بعد میں آپ نے شکاری کتے اور بکریوں (کی حفاظت) والے کتے کی اجازت دے دی۔"}],[4001,"یحییٰ بن حبیب نے کہا : ہمیں خالد بن حارث نے حدیث بیان کی ۔ محمد بن حاتم نے کہا : ہمیں یحییٰ بن سعید نے حدیث سنائی ۔ محمد بن ولید نے کہا : ہمیں محمد بن جعفر نے حدیث بیان کی ۔ اسحٰق بن ابراہیم نے کہا : ہمیں نضر نے خبر دی ۔ محمد بن مثنیٰ نے کہا : ہمیں وہب بن جریر نے حدیث بیان کی ، ( خالد بن حارث ، یحییٰ بن سعید ، محمد بن جعفر ، نضر اور وہب بن جریر ) سب نے شعبہ سے اسی سند کے ساتھ ( یہی ) حدیث بیان کی ۔ ابن حاتم نے اپنی حدیث میں کہا : یحییٰ سے روایت ہے ۔ ( اور آگے یہ کہا : ) اور آپ صلی اللہ علیہ وسلم نے بکریوں کی رکھوالی ، شکار اور کھیت کی حفاظت کرنے والے کتے کی اجازت دے دی ۔","",{"u2":"یحییٰ بن حبیب نے کہا: ہمیں خالد بن حارث نے حدیث بیان کی۔ محمد بن حاتم نے کہا: ہمیں یحییٰ بن سعید نے حدیث سنائی۔ محمد بن ولید نے کہا: ہمیں محمد بن جعفر نے حدیث بیان کی۔ اسحٰق بن ابراہیم نے کہا: ہمیں نضر نے خبر دی۔ محمد بن مثنیٰ نے کہا: ہمیں وہب بن جریر نے حدیث بیان کی، (خالد بن حارث، یحییٰ بن سعید، محمد بن جعفر، نضر اور وہب بن جریر) سب نے شعبہ سے اسی سند کے ساتھ (یہی) حدیث بیان کی۔\nابن حاتم نے اپنی حدیث میں کہا: یحییٰ سے روایت ہے۔ (اور آگے یہ کہا:) اور آپ صلی اللہ علیہ وسلم نے بکریوں کی رکھوالی، شکار اور کھیت کی حفاظت کرنے والے کتے کی اجازت دے دی۔"}],[4002,"نافع نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے مویشیوں کی حفاظت کرنے والے اور شکاری کتے کے سوا کتا پالا اس کے اجر میں سے ہر روز دو قیراط کم ہوں گے","",{"u2":") نافع نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے مویشیوں کی حفاظت کرنے والے اور شکاری کتے کے سوا کتا پالا اس کے اجر میں سے ہر روز دو قیراط کم ہوں گے"}],[4003,"زہری نے سالم سے ، انہوں نے اپنے والد ( سیدنا عبداللہ بن عمر رضی اللہ عنہ ) سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" جس نے شکار یا مویشیوں کے کتے کے سوا کتا رکھا اس کے اجر میں سے ہر روز دو قیراط کم ہوں گے ۔","",{"u2":"زہری نے سالم سے، انہوں نے اپنے والد (سیدنا عبداللہ بن عمر رضی اللہ عنہ) سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"جس نے شکار یا مویشیوں کے کتے کے سوا کتا رکھا اس کے اجر میں سے ہر روز دو قیراط کم ہوں گے۔\""}],[4004,"عبداللہ بن دینار سے روایت ہے کہ انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے شکار یا مویشیوں کے کتے کے سوا کتا رکھا اس کے عمل میں س ہر روز دو قیراط کم ہوں گے ۔","",{"u2":"عبداللہ بن دینار سے روایت ہے کہ انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے شکار یا مویشیوں کے کتے کے سوا کتا رکھا اس کے عمل میں س ہر روز دو قیراط کم ہوں گے۔\""}],[4005,"محمد بن ابی حرملہ نے سالم بن عبداللہ سے اور انہوں نے اپنے والد ( عبداللہ بن عمر رضی اللہ عنہ ) سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" جس نے مویشیوں کے کتے یا شکار کے کتے کے سوا کتا رکھا تو اس کے عمل سے ہر روز ایک قیراط کم ہو گا ۔ \"\" سیدنا عبداللہ رضی اللہ عنہ نے کہا : سیدنا ابوہریرہ رضی اللہ عنہ نے کہا : \"\" یا کھیتی کے کتے ( کے سوا ۔)","",{"u2":"محمد بن ابی حرملہ نے سالم بن عبداللہ سے اور انہوں نے اپنے والد (عبداللہ بن عمر رضی اللہ عنہ) سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے مویشیوں کے کتے یا شکار کے کتے کے سوا کتا رکھا تو اس کے عمل سے ہر روز ایک قیراط کم ہو گا۔\"\nسیدنا عبداللہ رضی اللہ عنہ نے کہا: سیدنا ابوہریرہ رضی اللہ عنہ نے کہا: \"یا کھیتی کے کتے (کے سوا۔)\""}],[4006,"حنظلہ بن ابی سفیان ( اسود بن عبدالرحمان بن صفوان بن امیہ ) نے سالم سے ، انہوں نے اپنے والد ( عبداللہ بن عمر رضی اللہ عنہ ) سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \"\" جس نے شکاری کتے یا مویشیوں کے کتے کے سوا کتا پالا اس کے عمل سے ہر دو روز قیراط کم ہوں گے ۔ \"\" سالم نے کہا : سیدنا ابوہریرہ رضی اللہ عنہ کہتے تھے : \"\" یا کھیتی کے کتے ( کے سوا ۔ ) \"\" اور وہ ( خود ) کھیتی کے مالک تھے ۔ ( اس لیے انہیں یہ بات یاد تھی ۔)","",{"u2":"حنظلہ بن ابی سفیان (اسود بن عبدالرحمان بن صفوان بن امیہ) نے سالم سے، انہوں نے اپنے والد (عبداللہ بن عمر رضی اللہ عنہ) سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"جس نے شکاری کتے یا مویشیوں کے کتے کے سوا کتا پالا اس کے عمل سے ہر دو روز قیراط کم ہوں گے۔\"\nسالم نے کہا: سیدنا ابوہریرہ رضی اللہ عنہ کہتے تھے: \"یا کھیتی کے کتے (کے سوا۔)\" اور وہ (خود) کھیتی کے مالک تھے۔ (اس لیے انہیں یہ بات یاد تھی۔)"}],[4007,"عمر بن حمزہ بن عبداللہ بن عمر نے ہمیں خبر دی ، کہا : ہمیں سالم بن عبداللہ نے اپنے والد سے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جن گھر والوں نے مویشیوں ( کی حفاظت ) والے کتے یا شکاری کتے کے سوا کتا رکھا ، تو ان کے عمل سے ہر روز دو قیراط کم ہوں گے ۔","",{"u2":"عمر بن حمزہ بن عبداللہ بن عمر نے ہمیں خبر دی، کہا: ہمیں سالم بن عبداللہ نے اپنے والد سے حدیث بیان کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جن گھر والوں نے مویشیوں (کی حفاظت) والے کتے یا شکاری کتے کے سوا کتا رکھا، تو ان کے عمل سے ہر روز دو قیراط کم ہوں گے۔\""}],[4008,"ابوحکم سے روایت ہے ، انہوں نے کہا : میں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا ، وہ نبی صلی اللہ علیہ وسلم سے حدیث بیان کر رہے تھے ، آپ نے فرمایا : \" جس نے کھیتی یا بکریوں ( کی حفاظت ) یا شکار کے کتے کے سوا کتا رکھا اس کے اجر میں سے ہر روز ایک قیراط کم ہو گا ۔","",{"u2":"ابوحکم سے روایت ہے، انہوں نے کہا: میں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا، وہ نبی صلی اللہ علیہ وسلم سے حدیث بیان کر رہے تھے، آپ نے فرمایا: \"جس نے کھیتی یا بکریوں (کی حفاظت) یا شکار کے کتے کے سوا کتا رکھا اس کے اجر میں سے ہر روز ایک قیراط کم ہو گا۔\""}],[4009,"ابوطاہر اور حرملہ نے کہا : ہمیں ابن وہب نے خبر دی ، انہوں نے کہا : مجھے یونس نے ابن شہاب سے خبر دی ، انہوں نے سعید بن مسیب سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \"\" جس شخص نے کتا پالا جو شکاری ہے ، نہ مویشیوں کے لیے ہے اور نہ ہی زمین کے لیے ، اس کے اجر سے ہر روز دو قیراط کم ہوں گے ۔ \"\" ابوطاہر کی حدیث میں \"\" نہ زمین کے لیے \"\" کے الفاظ نہیں ہیں ۔","",{"u2":"ابوطاہر اور حرملہ نے کہا: ہمیں ابن وہب نے خبر دی، انہوں نے کہا: مجھے یونس نے ابن شہاب سے خبر دی، انہوں نے سعید بن مسیب سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"جس شخص نے کتا پالا جو شکاری ہے، نہ مویشیوں کے لیے ہے اور نہ ہی زمین کے لیے، اس کے اجر سے ہر روز دو قیراط کم ہوں گے۔\"\nابوطاہر کی حدیث میں \"نہ زمین کے لیے\" کے الفاظ نہیں ہیں۔"}],[4010,"امام زہری نے ابوسلمہ سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" جس نے مویشیوں ، شکار یا کھیتی ( کی حفاظت کرنے ) والے کتے کے سوا ( کوئی اور ) کتا رکھا اس کے اجر سے ہر روز ایک قیراط کم ہو گا ۔ \"\" امام زہری نے کہا : سیدنا ابن عمر رضی اللہ عنہ کے سامنے سیدنا ابوہریرہ رضی اللہ عنہ کے اس قول کا تذکرہ کیا گیا تو انہوں نے کہا : اللہ تعالیٰ ، ابوہریرہ رضی اللہ عنہ پر رحم فرمائے! وہ ( خود ) کھیت کے مالک تھے ۔ ( انہوں نے یہ بات ضبط کی ۔)","",{"u2":"امام زہری نے ابوسلمہ سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے مویشیوں، شکار یا کھیتی (کی حفاظت کرنے) والے کتے کے سوا (کوئی اور) کتا رکھا اس کے اجر سے ہر روز ایک قیراط کم ہو گا۔\"\nامام زہری نے کہا: سیدنا ابن عمر رضی اللہ عنہ کے سامنے سیدنا ابوہریرہ رضی اللہ عنہ کے اس قول کا تذکرہ کیا گیا تو انہوں نے کہا: اللہ تعالیٰ، ابوہریرہ رضی اللہ عنہ پر رحم فرمائے! وہ (خود) کھیت کے مالک تھے۔ (انہوں نے یہ بات ضبط کی۔)"}],[4011,"ہشام دستوائی نے ہمیں حدیث بیان کی ، کہا : ہمیں یحییٰ بن ابی کثیر نے ابوسلمہ سے حدیث بیان کی ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے کتا رکھا ، اس کے عمل سے ہر روز ایک قیراط کم ہو گا ، سوائے کھیتی یا مویشیوں ( کی حفاظت کرنے ) والے کتے کے ۔","",{"u2":"ہشام دستوائی نے ہمیں حدیث بیان کی، کہا: ہمیں یحییٰ بن ابی کثیر نے ابوسلمہ سے حدیث بیان کی، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کتا رکھا، اس کے عمل سے ہر روز ایک قیراط کم ہو گا، سوائے کھیتی یا مویشیوں (کی حفاظت کرنے) والے کتے کے۔\""}],[4012,"اوزاعی نے ہمیں حدیث بیان کی ، کہا : مجھے یحییٰ بن ابی کثیر نے حدیث سنائی ، کہا : مجھے ابوسلمہ بن عبدالرحمٰن نے حدیث سنائی ، کہا : مجھے سیدنا ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اسی کے مانند حدیث بیان کی ۔","",{"u2":"اوزاعی نے ہمیں حدیث بیان کی، کہا: مجھے یحییٰ بن ابی کثیر نے حدیث سنائی، کہا: مجھے ابوسلمہ بن عبدالرحمٰن نے حدیث سنائی، کہا: مجھے سیدنا ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اسی کے مانند حدیث بیان کی۔"}],[4013,"حرب نے یحییٰ بن ابی کثیر سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ۔","",{"u2":"حرب نے یحییٰ بن ابی کثیر سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی۔"}],[4014,"ابورزین نے ہمیں حدیث بیان کی ، کہا : میں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے ( ایسا ) کتا رکھا جو شکار یا بکریوں کا کتا نہیں ہے تو اس کے عمل سے ہر روز ایک قیراط کم ہو گا ۔","",{"u2":"ابورزین نے ہمیں حدیث بیان کی، کہا: میں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے (ایسا) کتا رکھا جو شکار یا بکریوں کا کتا نہیں ہے تو اس کے عمل سے ہر روز ایک قیراط کم ہو گا۔\""}],[4015,"امام مالک نے زیدی بن خصفیہ سے روایت کی کہ انہیں سائب بن یزید نے بتایا کہ انہوں نے سفیان بن ابی زہیر سے سنا اورہ وہ شنوءہ قبیلے سے تعلق رکھنے والے ، رسول اللہ صلی اللہ علیہ وسلم کے صحابی تھے ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : \" جس نے کتا رکھا جو اسے کھیتی اور تھن ( والے جانوروں کی حفاظت ) کا فائدہ نہیں دیتا تو اس کے عمل سے ہر روز ایک قیراط کم ہو گا ۔ \" ( سائب نے ) کہا : کیا آپ نے خود یہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے سنی ہے؟ انہوں نے کہا : ہاں ، اس مسجد کے رب کی قسم","",{"u2":"امام مالک نے زیدی بن خصفیہ سے روایت کی کہ انہیں سائب بن یزید نے بتایا کہ انہوں نے سفیان بن ابی زہیر سے سنا اورہ وہ شنوءہ قبیلے سے تعلق رکھنے والے، رسول اللہ صلی اللہ علیہ وسلم کے صحابی تھے، کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: \"جس نے کتا رکھا جو اسے کھیتی اور تھن (والے جانوروں کی حفاظت) کا فائدہ نہیں دیتا تو اس کے عمل سے ہر روز ایک قیراط کم ہو گا۔\" (سائب نے) کہا: کیا آپ نے خود یہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے سنی ہے؟ انہوں نے کہا: ہاں، اس مسجد کے رب کی قسم!"}],[4016,"اسماعیل نے ہمیں یزید بن خصفیہ سے حدیث بیان کی ، کہا : مجھے سائب بن یزید نے خبر دی کہ ان کے پاس سفیان بن ابی زہیر شنئي ( قبیلہ شنوءہ سے تعلق رکھنے والے ) آئے اور کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ۔ ۔ ۔ اسی کے مانند","",{"u2":"اسماعیل نے ہمیں یزید بن خصفیہ سے حدیث بیان کی، کہا: مجھے سائب بن یزید نے خبر دی کہ ان کے پاس سفیان بن ابی زہیر شنئی (قبیلہ شنوءہ سے تعلق رکھنے والے) آئے اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا۔۔۔ اسی کے مانند"}],[4017,"اسماعیل بن جعفر نے ہمیں حمید سے حدیث بیان کی ، انہوں نے کہا : سیدنا انس بن مالک رضی اللہ عنہ سے پچھنے ( سینگی ) لگانے والے کی کمائی کے بارے میں پوچھا گیا تو انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے پچھنے لگوائے ، آپ کو ابوطیبہ نے پچھنے لگائے تو آپ نے اسے غلے سے دو صاع دینے کا حکم دیا اور اس کے مالکوں سے بات کی تو انہوں نے اس کے محصول میں کچھ تخفیف کر دی اور آپ نے فرمایا : \" تم لوگ جو علاج کرواؤ اس میں سے بہترین سینگی لگوانا ہے یا ( فرمایا : ) یہ تمہارے بہترین علاجوں میں سے ہے ۔","",{"u2":"اسماعیل بن جعفر نے ہمیں حمید سے حدیث بیان کی، انہوں نے کہا: سیدنا انس بن مالک رضی اللہ عنہ سے پچھنے (سینگی) لگانے والے کی کمائی کے بارے میں پوچھا گیا تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے پچھنے لگوائے، آپ کو ابوطیبہ نے پچھنے لگائے تو آپ نے اسے غلے سے دو صاع دینے کا حکم دیا اور اس کے مالکوں سے بات کی تو انہوں نے اس کے محصول میں کچھ تخفیف کر دی اور آپ نے فرمایا: \"تم لوگ جو علاج کرواؤ اس میں سے بہترین سینگی لگوانا ہے یا (فرمایا:) یہ تمہارے بہترین علاجوں میں سے ہے۔\""}],[4018,"مروان فزاری نے ہمیں حمید سے حدیث بیان کی ، انہوں نے کہا : سیدنا انس رضی اللہ عنہ سے سینگی لگانے والے کی کمائی کے بارے میں پوچھا گیا ۔ ۔ ۔ آگے اسی کے مانند بیان کیا ، مگر انہوں نے کہا : \" بلاشبہ سب سے افضل جس کے ذریعے سے تم علاج کراؤ ، پچھنے لگوانا اور عود بحری ( کا استعمال ) ہے اور تم اپنے بچوں کو گلا دبا کر ( مَل کر ) تکلیف نہ دو ۔","",{"u2":"مروان فزاری نے ہمیں حمید سے حدیث بیان کی، انہوں نے کہا: سیدنا انس رضی اللہ عنہ سے سینگی لگانے والے کی کمائی کے بارے میں پوچھا گیا۔۔۔ آگے اسی کے مانند بیان کیا، مگر انہوں نے کہا: \"بلاشبہ سب سے افضل جس کے ذریعے سے تم علاج کراؤ، پچھنے لگوانا اور عود بحری (کا استعمال) ہے اور تم اپنے بچوں کو گلا دبا کر (مَل کر) تکلیف نہ دو۔\""}],[4019,"شعبہ نے ہمیں حمید سے حدیث بیان کی ، انہوں نے کہا : میں نے سیدنا انس رضی اللہ عنہ کو کہتے سنا : نبی صلی اللہ علیہ وسلم نے ہمارے ایک پچھنے لگانے والے غلام کو بلایا اس نے آپ کو پچھنے لگائے تو آپ نے اسے ایک صاع ، ایک مد یا دو مد دینے کا حکم دیا اور اس کے متعلق ( اس کے مالکوں سے ) بات کی تو اس کے محصول میں کمی کر دی گئی ۔","",{"u2":") شعبہ نے ہمیں حمید سے حدیث بیان کی، انہوں نے کہا: میں نے سیدنا انس رضی اللہ عنہ کو کہتے سنا: نبی صلی اللہ علیہ وسلم نے ہمارے ایک پچھنے لگانے والے غلام کو بلایا اس نے آپ کو پچھنے لگائے تو آپ نے اسے ایک صاع، ایک مد یا دو مد دینے کا حکم دیا اور اس کے متعلق (اس کے مالکوں سے) بات کی تو اس کے محصول میں کمی کر دی گئی۔"}],[4020,"طاوس نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے پچھنے لگوائے اور سینگی لگانے والے کو اس کی اجرت دی اور آپ نے ناک کے ذریعے سے دوا لی ۔","",{"u2":"طاوس نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے پچھنے لگوائے اور سینگی لگانے والے کو اس کی اجرت دی اور آپ نے ناک کے ذریعے سے دوا لی۔"}],[4021,"شعبی نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : بنو بیاضہ کے ایک غلام نے نبی صلی اللہ علیہ وسلم جو پچھنے لگائے تو نبی صلی اللہ علیہ وسلم نے اسے اس کی اجرت دی اور آپ نے اس کے مالک سے بات کی تو اس نے اس کے محصول میں کچھ تخفیف کر دی اور اگر یہ ( اجرت ) حرام ہوتی تو نبی صلی اللہ علیہ وسلم اس کو نہ دیتے ۔","",{"u2":"شعبی نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: بنو بیاضہ کے ایک غلام نے نبی صلی اللہ علیہ وسلم جو پچھنے لگائے تو نبی صلی اللہ علیہ وسلم نے اسے اس کی اجرت دی اور آپ نے اس کے مالک سے بات کی تو اس نے اس کے محصول میں کچھ تخفیف کر دی اور اگر یہ (اجرت) حرام ہوتی تو نبی صلی اللہ علیہ وسلم اس کو نہ دیتے۔"}],[4022,"سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ مدینہ میں خطبہ دے رہے تھے ، آپ نے فرمایاؒ \" لوگو! اللہ تعالیٰ شراب ( کی حرمت ) کے بارے میں اشارہ فرما رہا ہے اور شاید اللہ تعالیٰ جلد ہی اس کے بارے میں کوئی ( قطعی ) حکم نازل کر دے ۔ جس کے پاس اس ( شراب ) میں سے کچھ موجود ہے وہ اسے بیچ دے اور اس سے فائدہ اٹھا لے ۔ \" کہا : پھر ہم نے تھوڑا ہی عرصہ اس عالم میں گزارا کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالیٰ نے یقینا شراب کو حرام کر دیا ہے ، جس شخص تک یہ آیت پہنچے اور اس کے پاس اس ( شراب ) میں سے کچھ ( حصہ باقی ) ہے تو نہ وہ اسے پیے اور نہ فروخت کرے ۔ \" کہا : لوگوں کے پاس جو بھی شراب تھی وہ اسے لے کر مدینہ کے راستے میں نکل آئے اور اسے بہا دیا ۔","",{"u2":"سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ مدینہ میں خطبہ دے رہے تھے، آپ نے فرمایا رحمہ اللہ \"لوگو! اللہ تعالیٰ شراب (کی حرمت) کے بارے میں اشارہ فرما رہا ہے اور شاید اللہ تعالیٰ جلد ہی اس کے بارے میں کوئی (قطعی) حکم نازل کر دے۔ جس کے پاس اس (شراب) میں سے کچھ موجود ہے وہ اسے بیچ دے اور اس سے فائدہ اٹھا لے۔\" کہا: پھر ہم نے تھوڑا ہی عرصہ اس عالم میں گزارا کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ نے یقینا شراب کو حرام کر دیا ہے، جس شخص تک یہ آیت پہنچے اور اس کے پاس اس (شراب) میں سے کچھ (حصہ باقی) ہے تو نہ وہ اسے پیے اور نہ فروخت کرے۔\" کہا: لوگوں کے پاس جو بھی شراب تھی وہ اسے لے کر مدینہ کے راستے میں نکل آئے اور اسے بہا دیا۔"}],[4023,"سوید بن سعید نے ہمیں حدیث بیان کی ، کہا : ہمیں حفص بن میسرہ نے زید بن اسلم سے حدیث سنائی ، انہوں نے ۔ ۔ اہل مصر کے آدمی ۔ ۔ عبدالرحمٰن بن وعلہ سے روایت کی کہ وہ سیدنا عبداللہ بن عباس رضی اللہ عنہ کے پاس آئے ۔ اور مجھے ابوطاہر نے حدیث بیان کی ۔ ۔ الفاظ انہی کے ہیں ۔ ۔ : ہمیں ابن وہب نے خبر دی : مجھے مالک بن انس اور دوسروں نے زید بن اسلم سے ، انہوں نے ۔ ۔ مصر کے باشندوں میں سے ۔ ۔ عبدالرحمان بن وعلہ سبئی سے روایت کی کہ انہوں نے سیدنا عبداللہ بن عباس رضی اللہ عنہ سے اس چیز کے بارے میں سوال کیا جو انگور سے نچوڑی جاتی ہے ۔ سیدنا ابن عباس رضی اللہ عنہ نے کہا : ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم کو شراب کا ایک مشکیزہ ہدیہ کیا تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا : \" کیا تمہیں علم ہے کہ اللہ تعالیٰ نے اسے حرام قررا دیا ہے؟ \" اس نے جواب دیا : نہیں ، اس کے بعد اس نے ایک انسان سے سرگوشی کی تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا : \" تم نے اس سے کیا سرگوشی کی ہے؟ \" اس نے جواب دیا : میں نے اس سے یہ فروخت کرنے کو کہا ہے ۔ تو آپ نے فرمایا : \" جس ( اللہ ) نے اس کا پینا حرام کیا ہے اس نے اس کی بیع بھی حرام قرار دی ہے ۔ \" کہا : اس پر اس شخص نے مشکیزے کا منہ کھول دیا حتی کہ جو اس میں تھا ، بہہ گیا ۔"],[4024,"سوید بن سعید نے ہمیں حدیث بیان کی ، کہا : ہمیں حفص بن میسرہ نے زید بن اسلم سے حدیث سنائی ، انہوں نے ۔ ۔ اہل مصر کے آدمی ۔ ۔ عبدالرحمٰن بن وعلہ سے روایت کی کہ وہ سیدنا عبداللہ بن عباس رضی اللہ عنہ کے پاس آئے ۔ اور مجھے ابوطاہر نے حدیث بیان کی ۔ ۔ الفاظ انہی کے ہیں ۔ ۔ : ہمیں ابن وہب نے خبر دی : مجھے مالک بن انس اور دوسروں نے زید بن اسلم سے ، انہوں نے ۔ ۔ مصر کے باشندوں میں سے ۔ ۔ عبدالرحمان بن وعلہ سبئی سے روایت کی کہ انہوں نے سیدنا عبداللہ بن عباس رضی اللہ عنہ سے اس چیز کے بارے میں سوال کیا جو انگور سے نچوڑی جاتی ہے ۔ سیدنا ابن عباس رضی اللہ عنہ نے کہا : ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم کو شراب کا ایک مشکیزہ ہدیہ کیا تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا : \" کیا تمہیں علم ہے کہ اللہ تعالیٰ نے اسے حرام قررا دیا ہے؟ \" اس نے جواب دیا : نہیں ، اس کے بعد اس نے ایک انسان سے سرگوشی کی تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا : \" تم نے اس سے کیا سرگوشی کی ہے؟ \" اس نے جواب دیا : میں نے اس سے یہ فروخت کرنے کو کہا ہے ۔ تو آپ نے فرمایا : \" جس ( اللہ ) نے اس کا پینا حرام کیا ہے اس نے اس کی بیع بھی حرام قرار دی ہے ۔ \" کہا : اس پر اس شخص نے مشکیزے کا منہ کھول دیا حتی کہ جو اس میں تھا ، بہہ گیا ۔","",{"u2":"سوید بن سعید نے ہمیں حدیث بیان کی، کہا: ہمیں حفص بن میسرہ نے زید بن اسلم سے حدیث سنائی، انہوں نے۔۔ اہل مصر کے آدمی۔۔ عبدالرحمٰن بن وعلہ سے روایت کی کہ وہ سیدنا عبداللہ بن عباس رضی اللہ عنہ کے پاس آئے۔ اور مجھے ابوطاہر نے حدیث بیان کی۔۔ الفاظ انہی کے ہیں۔۔: ہمیں ابن وہب نے خبر دی: مجھے مالک بن انس اور دوسروں نے زید بن اسلم سے، انہوں نے۔۔ مصر کے باشندوں میں سے۔۔ عبدالرحمان بن وعلہ سبئی سے روایت کی کہ انہوں نے سیدنا عبداللہ بن عباس رضی اللہ عنہ سے اس چیز کے بارے میں سوال کیا جو انگور سے نچوڑی جاتی ہے۔ سیدنا ابن عباس رضی اللہ عنہ نے کہا: ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم کو شراب کا ایک مشکیزہ ہدیہ کیا تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"کیا تمہیں علم ہے کہ اللہ تعالیٰ نے اسے حرام قررا دیا ہے؟\" اس نے جواب دیا: نہیں، اس کے بعد اس نے ایک انسان سے سرگوشی کی تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا: \"تم نے اس سے کیا سرگوشی کی ہے؟\" اس نے جواب دیا: میں نے اس سے یہ فروخت کرنے کو کہا ہے۔ تو آپ نے فرمایا: \"جس (اللہ) نے اس کا پینا حرام کیا ہے اس نے اس کی بیع بھی حرام قرار دی ہے۔\" کہا: اس پر اس شخص نے مشکیزے کا منہ کھول دیا حتی کہ جو اس میں تھا، بہہ گیا۔"}],[4025,"یحییٰ بن سعید نے عبدالرحمٰن بن وعلہ سے ، انہوں نے سیدنا عبداللہ بن عباس رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے ، اسی کے مانند روایت کی ۔","",{"u2":"یحییٰ بن سعید نے عبدالرحمٰن بن وعلہ سے، انہوں نے سیدنا عبداللہ بن عباس رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے، اسی کے مانند روایت کی۔"}],[4026,"منصور نے ابوضحیٰ ( مسلم بن صبیح ) سے ، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : جب سورہ بقرہ کے آخری حصے کی آیات نازل ہوئیں تو رسول اللہ صلی اللہ علیہ وسلم باہر تشریف لے گئے ۔ آپ نے لوگوں کے سامنے ان کی تلاوت کی ، پھر آپ نے شراب کی تجارت سے بھی منع فرما دیا ۔","",{"u2":"منصور نے ابوضحیٰ (مسلم بن صبیح) سے، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: جب سورہ بقرہ کے آخری حصے کی آیات نازل ہوئیں تو رسول اللہ صلی اللہ علیہ وسلم باہر تشریف لے گئے۔ آپ نے لوگوں کے سامنے ان کی تلاوت کی، پھر آپ نے شراب کی تجارت سے بھی منع فرما دیا۔"}],[4027,"اعمش نے ( ابوضحیٰ ) مسلم سے ، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : جب سود کے بارے میں سورہ بقرہ کی آکری آیات نازل کی گئیں ، کہا : تو رسول اللہ صلی اللہ علیہ وسلم مسجد کی طرف تشریف لے گئے اور آپ نے شراب کی تجارت کو بھی حرام قرار دیا","",{"u2":") اعمش نے (ابوضحیٰ) مسلم سے، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: جب سود کے بارے میں سورہ بقرہ کی آکری آیات نازل کی گئیں، کہا: تو رسول اللہ صلی اللہ علیہ وسلم مسجد کی طرف تشریف لے گئے اور آپ نے شراب کی تجارت کو بھی حرام قرار دیا"}],[4028,"لیث نے ہمیں یزید بن ابی حبیب سے حدیث بیان کی ، انہوں نے عطاء بن ابی رباح سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فتح مکہ کے سال ، جب آپ مکہ ہی میں تھے ، فرماتے ہوئے سنا : \" بلاشبہ اللہ اور اس کے رسول صلی اللہ علیہ وسلم نے شراب ، مردار ، خنزیر اور بتوں کی بیع حرام قرار دی ہے ۔ \" کہا گیا : اے اللہ کے رسول! مردار جانور کی چربی کے بارے میں آپ کی کیا رائے ہے ، اس سے کشتیوں ( کے تختے ) کو روغن کیا جاتا ہے اور چمڑوں کو نرم کیا جاتا ہے اور لوگ اس سے چراغ جلاتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" نہیں ، وہ حرام ہے ۔ \" پھر اسی وقت ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ یہود کو ہلاک کرے! اللہ نے جب ان لے لیے ان جانوروں کی چربی حرام کی تو انہوں نے اسے پھگلایا ، پھر اسے فروخت کیا اور اس کی قیمت لے کر کھائی ۔","",{"u2":"لیث نے ہمیں یزید بن ابی حبیب سے حدیث بیان کی، انہوں نے عطاء بن ابی رباح سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فتح مکہ کے سال، جب آپ مکہ ہی میں تھے، فرماتے ہوئے سنا: \"بلاشبہ اللہ اور اس کے رسول صلی اللہ علیہ وسلم نے شراب، مردار، خنزیر اور بتوں کی بیع حرام قرار دی ہے۔\" کہا گیا: اے اللہ کے رسول! مردار جانور کی چربی کے بارے میں آپ کی کیا رائے ہے، اس سے کشتیوں (کے تختے) کو روغن کیا جاتا ہے اور چمڑوں کو نرم کیا جاتا ہے اور لوگ اس سے چراغ جلاتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں، وہ حرام ہے۔\" پھر اسی وقت، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ یہود کو ہلاک کرے! اللہ نے جب ان لے لیے ان جانوروں کی چربی حرام کی تو انہوں نے اسے پھگلایا، پھر اسے فروخت کیا اور اس کی قیمت لے کر کھائی۔\""}],[4029,"عبدالحمید سے روایت ہے ، کہا : مجھے یزید بن ابی حبیب نے حدیث بیان کی ، انہوں نے کہا : عطاء نے مجھے لکھ بھیجا کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ کو کہتے ہوئے سنا : میں نے فتح مکہ کے سال رسول اللہ صلی اللہ علیہ وسلم سے سنا ۔ ۔ آگے لیث کی حدیث کی طرح ہے ۔"],[4030,"عبدالحمید سے روایت ہے ، کہا : مجھے یزید بن ابی حبیب نے حدیث بیان کی ، انہوں نے کہا : عطاء نے مجھے لکھ بھیجا کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ کو کہتے ہوئے سنا : میں نے فتح مکہ کے سال رسول اللہ صلی اللہ علیہ وسلم سے سنا ۔ ۔ آگے لیث کی حدیث کی طرح ہے ۔",""],[4031,"سفیان بن عیینہ نے ہمیں عمرو سے حدیث بیان کی ، انہوں نے طاوس سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : سیدنا عمر رضی اللہ عنہ کو اطلاع ملی کہ سیدنا سمرہ رضی اللہ عنہ نے شراب فروخت کی ہے تو انہوں نے کہا : اللہ سمرہ کو ہلاک کرے! کیا وہ نہیں جانتا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ یہود پر لعنت کرے! ( کہ ) ان پر چربی حرام کی گئی تو انہوں نے اسے پھگلایا اور فروخت کیا \" ؟","",{"u2":") سفیان بن عیینہ نے ہمیں عمرو سے حدیث بیان کی، انہوں نے طاوس سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: سیدنا عمر رضی اللہ عنہ کو اطلاع ملی کہ سیدنا سمرہ رضی اللہ عنہ نے شراب فروخت کی ہے تو انہوں نے کہا: اللہ سمرہ کو ہلاک کرے! کیا وہ نہیں جانتا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ یہود پر لعنت کرے! (کہ) ان پر چربی حرام کی گئی تو انہوں نے اسے پھگلایا اور فروخت کیا\"؟"}],[4032,"روح بن قاسم نے عمرو بن دینار سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ۔","",{"u2":"روح بن قاسم نے عمرو بن دینار سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی۔"}],[4033,"ابن جریج نے ہمیں حدیث بیان کی ، کہا : مجھے ابن شہاب نے سعید بن مسیب سے خبر دی کہ انہوں نے انہیں ( ابن شہاب کو ) سیدنا ابوہریرہ رضی اللہ عنہ کے واسطے سے رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کی ، آپ نے فرمایا : \" اللہ یہود کو ہلاک کرے! اللہ نے ان پر چربی حرام کی تو انہوں نے اسے بیچا اور اس کی قیمت کھائی ۔","",{"u2":"ابن جریج نے ہمیں حدیث بیان کی، کہا: مجھے ابن شہاب نے سعید بن مسیب سے خبر دی کہ انہوں نے انہیں (ابن شہاب کو) سیدنا ابوہریرہ رضی اللہ عنہ کے واسطے سے رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کی، آپ نے فرمایا: \"اللہ یہود کو ہلاک کرے! اللہ نے ان پر چربی حرام کی تو انہوں نے اسے بیچا اور اس کی قیمت کھائی۔\""}],[4034,"یونس نے مجھے ابن شہاب سے خبر دی ، انہوں نے سعید بن مسیب سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ یہود کو ہلاک کرے! ان پر چربی حرام کی گئی تو انہوں نے اسے بیچا اور اس کی قیمت کھائی ۔","",{"u2":") یونس نے مجھے ابن شہاب سے خبر دی، انہوں نے سعید بن مسیب سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ یہود کو ہلاک کرے! ان پر چربی حرام کی گئی تو انہوں نے اسے بیچا اور اس کی قیمت کھائی۔\""}],[4035,"امام مالک نے نافع سے اور انہوں نے سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم سونے کے عوض سونے کی بیع نہ کرو ، الا یہ کہ برابر برابر ہو اور اسے ایک دوسرے سے کم زیادہ نہ کرو اور نہ تم چاندی کی بیع چاندی کے عوض کرو ، الا یہ کہ مثل بمثل ( یکساں ) ہو اور اسے ایک دوسرے سے کم زیادہ نہ کرو اور اس میں سے جو غیر موجود ہو اس کی بیع موجود کے عوض نہ کرو ۔","",{"u2":"امام مالک نے نافع سے اور انہوں نے سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم سونے کے عوض سونے کی بیع نہ کرو، الا یہ کہ برابر برابر ہو اور اسے ایک دوسرے سے کم زیادہ نہ کرو اور نہ تم چاندی کی بیع چاندی کے عوض کرو، الا یہ کہ مثل بمثل (یکساں) ہو اور اسے ایک دوسرے سے کم زیادہ نہ کرو اور اس میں سے جو غیر موجود ہو اس کی بیع موجود کے عوض نہ کرو۔\""}],[4036,"قتیبہ بن سعید اور محمد بن رمح نے لیث سے حدیث بیان کی اور انہوں نے نافع سے روایت کی کہ بنو لیث کے ایک شخص نے حجرت ابن عمر رضی اللہ عنہ سے کہا : سیدنا ابوسعید خدری رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے یہ بات بیان کرتے ہیں ۔ قتیبہ کی روایت میں ہے : سیدنا عبداللہ رضی اللہ عنہ چلے اور نافع بھی ساتھ تھے ۔ ۔ اور ابن رمح کی حدیث میں ہے : نافع نے کہا : سیدنا عبداللہ رضی اللہ عنہ چلے ، میں اور لیثی بھی ان کے ساتھ تھے ۔ ۔ حتی کہ وہ سیدنا ابوسعید خدری رضی اللہ عنہ کے ہاں آئے اور کہا : اس آدمی نے مجھے بتایا ہے کہ آپ حدیث بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے چاندی کی چاندی کے عوض بیع سے منع فرمایا ہے مگر یہ کہ برابر برابر ہو اور سونے کی سونے کے عوض بیع سے ( منع فرمایا ) الا یہ کہ برابر برابر ہو؟ سیدنا ابوسعید رضی اللہ عنہ نے اپنی دو انگلیوں سے اپنی دونوں آنکھوں اور دونوں کانوں کی طرف اشارہ کیا اور کہا : میری دونوں آنکھوں نے دیکھا اور میرے دونوں کانوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : \" تم سونے کے عوض سونے کی اور چاندی کے عوض چاندی کی بیع نہ کرو مگر یہ کہ یکساں اور اسے ایک دوسرے سے کم زیادہ نہ کرو اور اس میں سے کسی غیر موجود چیز کی موجود کے ساتھ بیع نہ کرو ، الا یہ کہ دست بدست ہو ۔","",{"u2":"قتیبہ بن سعید اور محمد بن رمح نے لیث سے حدیث بیان کی اور انہوں نے نافع سے روایت کی کہ بنو لیث کے ایک شخص نے حجرت ابن عمر رضی اللہ عنہ سے کہا: سیدنا ابوسعید خدری رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے یہ بات بیان کرتے ہیں۔ قتیبہ کی روایت میں ہے: سیدنا عبداللہ رضی اللہ عنہ چلے اور نافع بھی ساتھ تھے۔۔ اور ابن رمح کی حدیث میں ہے: نافع نے کہا: سیدنا عبداللہ رضی اللہ عنہ چلے، میں اور لیثی بھی ان کے ساتھ تھے۔۔ حتی کہ وہ سیدنا ابوسعید خدری رضی اللہ عنہ کے ہاں آئے اور کہا: اس آدمی نے مجھے بتایا ہے کہ آپ حدیث بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے چاندی کی چاندی کے عوض بیع سے منع فرمایا ہے مگر یہ کہ برابر برابر ہو اور سونے کی سونے کے عوض بیع سے (منع فرمایا) الا یہ کہ برابر برابر ہو؟ سیدنا ابوسعید رضی اللہ عنہ نے اپنی دو انگلیوں سے اپنی دونوں آنکھوں اور دونوں کانوں کی طرف اشارہ کیا اور کہا: میری دونوں آنکھوں نے دیکھا اور میرے دونوں کانوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: \"تم سونے کے عوض سونے کی اور چاندی کے عوض چاندی کی بیع نہ کرو مگر یہ کہ یکساں اور اسے ایک دوسرےسے کم زیادہ نہ کرو اور اس میں سے کسی غیر موجود چیز کی موجود کے ساتھ بیع نہ کرو، الا یہ کہ دست بدست ہو۔\""}],[4037,"جریر بن حازم ، یحییٰ بن سعید اور ابن عون ، سب نے نافع سے روایت کی ، لیث کے نافع سے ، ان کی سیدنا ابوسعید خدری رضی اللہ عنہ سے اور ان کی نبی صلی اللہ علیہ وسلم سے روایت کی طرح ۔","",{"u2":"جریر بن حازم، یحییٰ بن سعید اور ابن عون، سب نے نافع سے روایت کی، لیث کے نافع سے، ان کی سیدنا ابوسعید خدری رضی اللہ عنہ سے اور ان کی نبی صلی اللہ علیہ وسلم سے روایت کی طرح۔"}],[4038,"ابوصالح نے سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم سونے کی سونے کے عوض اور چاندی کی چاندی کے عوض بیع نہ کرو مگر یہ کہ وزن بوزن مثل بمثل ( معیار میں یکساں ) برابر برابر ہو ۔","",{"u2":") ابوصالح نے سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم سونے کی سونے کے عوض اور چاندی کی چاندی کے عوض بیع نہ کرو مگر یہ کہ وزن بوزن مثل بمثل (معیار میں یکساں) برابر برابر ہو۔\""}],[4039,"سیدنا عثمان بن عفان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم ایک دینار کی دو دیناروں کے عوض اور ایک درہم کی دو درہموں کے عوض بیع نہ کرو ۔","",{"u2":"سیدنا عثمان بن عفان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم ایک دینار کی دو دیناروں کے عوض اور ایک درہم کی دو درہموں کے عوض بیع نہ کرو۔\""}],[4040,"لیث نے ہمیں ابن شہاب سے خبر دی اور انہوں نے مالک بن اوس بن حدثان سے روایت کی کہ انہوں نے کہا : میں ( لوگوں کے سامنے ) یہ کہتا ہوا آیا : ( سونے کے عوض ) درہموں کا تبادلہ کون کرے گا؟ تو حجرت طلحہ بن عبیداللہ رضی اللہ عنہ نے کہا ۔ ۔ اور وہ سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس تھے ۔ ۔ ہمیں اپنا سونا دکھاؤ ، پھر ( ذرا ٹھہر کے ) ہمارے پاس آنا ، جب ہمارا خادم آئے گا تو ہم تمہیں تمہاری چاندی ( کے درہم ) دے دیں گے ۔ اس پر عمر بن خطاب رضی اللہ عنہ نے کہا : ہرگز نہیں ، اللہ کی قسم! تم انہیں چاندی دو یا ان کا سونا انہیں واپس کرو کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے : \" سونے کے عوض چاندی ( کی بیع ) سود ہے ، الا یہ کہ ہاتھوں ہاتھ ( دست بدست ) ہو اور گندم کے عوض گندم سود ہے ، الا یہ کہ ہاتھوں ہاتھ ہو اور جو کے عوض جو سود ہے ، الا یہ کہ ہاتھوں ہاتھ ہو اور کھجور کے عوض کھجور سود ہے ، الا یہ کہ ہاتھوں ہاتھ ہو ۔","",{"u2":"لیث نے ہمیں ابن شہاب سے خبر دی اور انہوں نے مالک بن اوس بن حدثان سے روایت کی کہ انہوں نے کہا: میں (لوگوں کے سامنے) یہ کہتا ہوا آیا: (سونے کے عوض) درہموں کا تبادلہ کون کرے گا؟ تو حجرت طلحہ بن عبیداللہ رضی اللہ عنہ نے کہا۔۔ اور وہ سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس تھے۔۔ ہمیں اپنا سونا دکھاؤ، پھر (ذرا ٹھہر کے) ہمارے پاس آنا، جب ہمارا خادم آئے گا تو ہم تمہیں تمہاری چاندی (کے درہم) دے دیں گے۔ اس پر عمر بن خطاب رضی اللہ عنہ نے کہا: ہرگز نہیں، اللہ کی قسم! تم انہیں چاندی دو یا ان کا سونا انہیں واپس کرو کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"سونے کے عوض چاندی (کی بیع) سود ہے، الا یہ کہ ہاتھوں ہاتھ (دست بدست) ہو اور گندم کے عوض گندم سود ہے، الا یہ کہ ہاتھوں ہاتھ ہو اور جو کے عوض جو سود ہے، الا یہ کہ ہاتھوں ہاتھ ہو اور کھجور کے عوض کھجور سود ہے، الا یہ کہ ہاتھوں ہاتھ ہو۔\""}],[4041,"ابن عیینہ نے زہری سے اسی سند کے ساتھ ( یہی ) روایت بیان کی ۔","",{"u2":"ابن عیینہ نے زہری سے اسی سند کے ساتھ (یہی) روایت بیان کی۔"}],[4042,"حماد بن زید نے ہمیں ایوب سے حدیث بیان کی اور انہوں نے ابوقلابہ سے روایت کی ، انہوں نے کہا : میں شام میں ایک مجلس میں تھا جس میں مسلم بن یسار بھی تھے ، اتنے میں ابواشعث آئے تو لوگوں نے کہا : ابواشعث ، ( آگئے ) میں نے کہا : ( اچھا ) ابو اشعث! وہ بیٹھ گئے تو میں نے ان سے کہا : ہمارے بھائی! ہمیں سیدنا عبادہ بن صامت رضی اللہ عنہ کی حدیث بیان کیجیے ۔ انہوں نے کہا : ہاں ، ہم نے ایک غزوہ لڑا اور لوگوں کے امیر سیدنا معاویہ رضی اللہ عنہ نے ایک آدمی کو حکم دیا کہ وہ انہیں لوگوں کو ملنے والے عطیات ( کے بدلے ) میں فروخت کر دے ۔ ( جب عطیات ملیں گے تو قیمت اس وقت دراہم کی صورت میں لے لی جائے گی ) لوگوں نے ان ( کو خریدنے ) میں جلدی کی ۔ یہ بات سیدنا عبادہ بن صامت رضی اللہ عنہ کو پہنچی تو وہ کھڑے ہوئے اور کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ سونے کے عوض سونے کی ، چاندی کے عوض چاندی کی ، گندم کے عوض گندم کی ، جو کے عوض جو کی ، کھجور کے عوض کھجور کی اور نمک کے عوض نمک کی بیع سے منع فرما رہے تھے ، الا یہ کہ برابر برابر ، نقد بنقد ہو ۔ جس نے زیادہ دیا یا زیادہ لیا تو اس نے سود کا لین دین کیا ۔ ( یہ سن کر ) لوگوں نے جو لیا تھا واپس کر دیا ۔ سیدنا معاویہ رضی اللہ عنہ کو یہ بات پہنچی تو وہ خطبہ دینے کے لیے کھڑے ہوئے اور کہا : سنو! لوگوں کا حال کیا ہے! وہ رسول اللہ صلی اللہ علیہ وسلم سے احادیث بیان کرتے ہیں ، ہم بھی آپ کے پاس حاضر ہوتے اور آپ کے ساتھ رہتے تھے لیکن ہم نے آپ سے وہ ( احادیث ) نہیں سنیں ۔ اس پر سیدنا عبادہ بن صامت رضی اللہ عنہ کھڑے ہو گئے ، ( رسول اللہ صلی اللہ علیہ وسلم سے سنا ہوا ) سارا واقعہ دہرایا اور کہا : ہم وہ احادیث ضرور بیان کریں گے جو ہم نے رسول اللہ صلی اللہ علیہ وسلم سے سنیں ، خواہ معاویہ رضی اللہ عنہ ناپسند کریں ۔ ۔ یا کہا : خواہ ان کی ناک خاک آلود ہو ۔ ۔ مجھے پروا نہیں کہ میں ان کے لشکر میں ان کے ساتھ ایک سیاہ رات بھی نہ رہوں ۔ حماد نے کہا : یہ ( کہا : ) یا اس کے ہم معنی ۔","",{"u2":"حماد بن زید نے ہمیں ایوب سے حدیث بیان کی اور انہوں نے ابوقلابہ سے روایت کی، انہوں نے کہا: میں شام میں ایک مجلس میں تھا جس میں مسلم بن یسار بھی تھے، اتنے میں ابواشعث آئے تو لوگوں نے کہا: ابواشعث، (آگئے) میں نے کہا: (اچھا) ابو اشعث! وہ بیٹھ گئے تو میں نے ان سے کہا: ہمارے بھائی! ہمیں سیدنا عبادہ بن صامت رضی اللہ عنہ کی حدیث بیان کیجیے۔ انہوں نے کہا: ہاں، ہم نے ایک غزوہ لڑا اور لوگوں کے امیر سیدنا معاویہ رضی اللہ عنہ نے ایک آدمی کو حکم دیا کہ وہ انہیں لوگوں کو ملنے والے عطیات (کے بدلے) میں فروخت کر دے۔ (جب عطیات ملیں گے تو قیمت اس وقت دراہم کی صورت میں لے لی جائے گی) لوگوں نے ان (کو خریدنے) میں جلدی کی۔ یہ بات سیدنا عبادہ بن صامت رضی اللہ عنہ کو پہنچی تو وہ کھڑے ہوئے اور کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ سونے کے عوض سونے کی، چاندی کے عوض چاندی کی، گندم کے عوض گندم کی، جو کے عوض جو کی، کھجور کے عوض کھجور کی اور نمک کے عوض نمک کی بیع سے منع فرما رہے تھے، الا یہ کہ برابر برابر، نقد بنقد ہو۔ جس نے زیادہ دیا یا زیادہ لیا تو اس نے سود کا لین دین کیا۔ (یہ سن کر) لوگوں نے جو لیا تھا واپس کر دیا۔سیدنا معاویہ رضی اللہ عنہ کو یہ بات پہنچی تو وہ خطبہ دینے کے لیے کھڑے ہوئے اور کہا: سنو! لوگوں کا حال کیا ہے! وہ رسول اللہ صلی اللہ علیہ وسلم سے احادیث بیان کرتے ہیں، ہم بھی آپ کے پاس حاضر ہوتے اور آپ کے ساتھ رہتے تھے لیکن ہم نے آپ سے وہ (احادیث) نہیں سنیں۔ اس پر سیدنا عبادہ بن صامت رضی اللہ عنہ کھڑے ہو گئے، (رسول اللہ صلی اللہ علیہ وسلم سے سنا ہوا) سارا واقعہ دہرایا اور کہا: ہم وہ احادیث ضرور بیان کریں گے جو ہم نے رسول اللہ صلی اللہ علیہ وسلم سے سنیں، خواہ معاویہ رضی اللہ عنہ ناپسند کریں۔۔ یا کہا: خواہ ان کی ناک خاک آلود ہو۔۔ مجھے پروا نہیں کہ میں ان کے لشکر میں ان کے ساتھ ایک سیاہ رات بھی نہ رہوں۔\nحماد نے کہا: یہ (کہا:) یا اس کے ہم معنی۔"}],[4043,"عبدالوہاب ثقفی نے ایوب سے اسی سند کے ساتھ اسی کی طرح روایت بیان کی ۔","",{"u2":"عبدالوہاب ثقفی نے ایوب سے اسی سند کے ساتھ اسی کی طرح روایت بیان کی۔"}],[4044,"خالد حذاء نے ابوقلابہ سے ، انہوں نے ابواشعث سے اور انہوں نے سیدنا عبادہ بن صامت رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" سونے کے عوض سونا ، چاندی کے عوض چاندی ، گندم کے عوض گندم ، جو کے عوض جو ، کھجور کے عوض کھجور اور نمک کے عوض نمک ( کا لین دین ) مثل بمثل ، یکساں ، برابر برابر اور نقد بنقد ہے ۔ جب اصناف مختلف ہوں تو جیسے چاہو بیع کرو بشرطیکہ وہ دست بدست ہو ۔","",{"u2":"خالد حذاء نے ابوقلابہ سے، انہوں نے ابواشعث سے اور انہوں نے سیدنا عبادہ بن صامت رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سونے کے عوض سونا، چاندی کے عوض چاندی، گندم کے عوض گندم، جو کے عوض جو، کھجور کے عوض کھجور اور نمک کے عوض نمک (کا لین دین) مثل بمثل، یکساں، برابر برابر اور نقد بنقد ہے۔ جب اصناف مختلف ہوں تو جیسے چاہو بیع کرو بشرطیکہ وہ دست بدست ہو۔\""}],[4045,"اسماعیل بن مسلم عبدی نے ہمیں حدیث بیان کی ، کہا : ہمیں ابومتوکل ناجی نے سیدنا ابوسعید خدری رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" سونے کے عوض سونا ، چاندی کے عوض چاندی ، گندم کے عوض گندم ، جو کے عوض جو ، کھجور کے عوض کھجور اور نمک کے عوض نمک ( کی بیع ) مثل بمثل ( ایک جیسی ) ہاتھوں ہاتھ ہو ۔ جس نے زیادہ دیا یا زیادہ لیا اس نے سود کا لین دین کیا ، اس میں لینے والا اور دینے والا برابر ہیں ۔","",{"u2":") اسماعیل بن مسلم عبدی نے ہمیں حدیث بیان کی، کہا: ہمیں ابومتوکل ناجی نے سیدنا ابوسعید خدری رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سونے کے عوض سونا، چاندی کے عوض چاندی، گندم کے عوض گندم، جو کے عوض جو، کھجور کے عوض کھجور اور نمک کے عوض نمک (کی بیع) مثل بمثل (ایک جیسی) ہاتھوں ہاتھ ہو۔ جس نے زیادہ دیا یا زیادہ لیا اس نے سود کا لین دین کیا، اس میں لینے والا اور دینے والا برابر ہیں۔\""}],[4046,"سلیمان ربعی نے ہمیں خبر دی ، کہا : ہمیں ابومتوکل ناجی نے حضترت ابوسعید خدری رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" سونے کے عوض سونے ( کی بیع ) برابر مثل بمثل ( ایک جیسی ) ہے ۔ ۔ ۔ \" ( آگے ) سابقہ حدیث کے مانند بیان کیا ۔","",{"u2":"سلیمان ربعی نے ہمیں خبر دی، کہا: ہمیں ابومتوکل ناجی نے حضترت ابوسعید خدری رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سونے کے عوض سونے (کی بیع) برابر مثل بمثل (ایک جیسی) ہے۔۔۔\" (آگے) سابقہ حدیث کے مانند بیان کیا۔"}],[4047,"فضیل کے بیٹے ( محمد ) نے ہمیں اپنے والد سے حدیث بیان کی ، انہوں نے ابوزرعہ سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کھجور کے عوض کھجور ، گندم کے عوض گندم ، جو کے عوض جو اور نمک کے عوض نمک ( کی بیع ) مثل بمثل ( ایک جیسی ) دست بدست ہو ۔ جس نے زیادہ دیا یا زیادہ لیا اس نے سود کا ( لین دین ) کیا ، الا یہ کہ ان کی اجناس الگ الگ ہوں ۔","",{"u2":") فضیل کے بیٹے (محمد) نے ہمیں اپنے والد سے حدیث بیان کی، انہوں نے ابوزرعہ سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کھجور کے عوض کھجور، گندم کے عوض گندم، جو کے عوض جو اور نمک کے عوض نمک (کی بیع) مثل بمثل (ایک جیسی) دست بدست ہو۔ جس نے زیادہ دیا یا زیادہ لیا اس نے سود کا (لین دین) کیا، الا یہ کہ ان کی اجناس الگ الگ ہوں۔\""}],[4048,"محاربی نے فضیل بن گزوان سے اسی سند کے ساتھ حدیث بیان کی اور انہوں نے \" دست بدست \" کے الفاظ بیان نہیں کیے ۔","",{"u2":"محاربی نے فضیل بن گزوان سے اسی سند کے ساتھ حدیث بیان کی اور انہوں نے \"دست بدست\" کے الفاظ بیان نہیں کیے۔"}],[4049,"ابن ابی نُعیم نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" سونے کے عوض سونے کی بیع ہم وزن اور مثل بمثل ( ایک جیسی ) ہے اور چاندی کے عوض چاندی ہم وزن اور مثل بمثل ہے ۔ جس نے زیادہ دیا یا زیادہ لیا تو وہ سود ہے ۔","",{"u2":"ابن ابی نُعیم نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سونے کے عوض سونے کی بیع ہم وزن اور مثل بمثل (ایک جیسی) ہے اور چاندی کے عوض چاندی ہم وزن اور مثل بمثل ہے۔ جس نے زیادہ دیا یا زیادہ لیا تو وہ سود ہے۔\""}],[4050,"سلیمان بن ہلال نے ہمیں موسیٰ بن ابی تمیم سے حدیث بیان کی ، انہوں نے سعید بن یسار سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" دینار سے دینار کی بیع میں ان کے درمیان اضافہ ( جائز ) نہیں اور درہم سے درہم کے تبادلے میں ان کے درمیان اضافہ ( جائز ) نہیں ۔","",{"u2":"سلیمان بن ہلال نے ہمیں موسیٰ بن ابی تمیم سے حدیث بیان کی، انہوں نے سعید بن یسار سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دینار سے دینار کی بیع میں ان کے درمیان اضافہ (جائز) نہیں اور درہم سے درہم کے تبادلے میں ان کے درمیان اضافہ (جائز) نہیں۔\""}],[4051,"امام مالک بن انس نے کہا : مجھے موسیٰ بن ابی تمیم نے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ۔","",{"u2":"امام مالک بن انس نے کہا: مجھے موسیٰ بن ابی تمیم نے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی۔"}],[4052,"عمرو ( بن دینار ) نے ابومنہال سے روایت کی ، انہوں نے کہا : میرے ایک شریک نے موسم ( حج کے موسم ) تک یا حج تک چاندی ادھار فروخت کی ، وہ میرے پاس آیا اور مجھے بتایا تو میں نے کہا : یہ معاملہ درست نہیں ۔ اس نے کہا : میں نے وہ بازار میں فروخت کی ہے اور اسے کسی نے میرے سامنے ناقابل قبول قرار نہیں دیا ۔ اس پر میں سیدنا براء بن عازب رضی اللہ عنہ کے پاس آیا اور ان سے پوچھا تو انہوں نے کہا : نبی صلی اللہ علیہ وسلم مدینہ تشریف لائے اور ہم یہ بیع کیا کرتے تھے تو آپ نے فرمایا : \" جو دست بدست ہے اس میں کوئی حرج نہیں اور جو ادھار ہے وہ سود ہے ۔ \" زید بن ارقم رضی اللہ عنہ کے پاس جاؤ اور ان کا کاروبار مجھ سے وسیع ہے ، چنانچہ میں ان کے پاس آیا اور ان سے پوچھا تو انہوں نے بھی اسی کے مانند کہا ۔","",{"u2":"عمرو (بن دینار) نے ابومنہال سے روایت کی، انہوں نے کہا: میرے ایک شریک نے موسم (حج کے موسم) تک یا حج تک چاندی ادھار فروخت کی، وہ میرے پاس آیا اور مجھے بتایا تو میں نے کہا: یہ معاملہ درست نہیں۔ اس نے کہا: میں نے وہ بازار میں فروخت کی ہے اور اسے کسی نے میرے سامنے ناقابل قبول قرار نہیں دیا۔ اس پر میں سیدنا براء بن عازب رضی اللہ عنہ کے پاس آیا اور ان سے پوچھا تو انہوں نے کہا: نبی صلی اللہ علیہ وسلم مدینہ تشریف لائے اور ہم یہ بیع کیا کرتے تھے تو آپ نے فرمایا: \"جو دست بدست ہے اس میں کوئی حرج نہیں اور جو ادھار ہے وہ سود ہے۔\" زید بن ارقم رضی اللہ عنہ کے پاس جاؤ اور ان کا کاروبار مجھ سے وسیع ہے، چنانچہ میں ان کے پاس آیا اور ان سے پوچھا تو انہوں نے بھی اسی کے مانند کہا۔\nعمرو (بن دینار) نے ابومنہال سے روایت کی، انہوں نے کہا: میرے ایک شریک نے موسم (حج کے موسم) تک یا حج تک چاندی ادھار فروخت کی، وہ میرے پاس آیا اور مجھے بتایا تو میں نے کہا: یہ معاملہ درست نہیں۔ اس نے کہا: میں نے وہ بازار میں فروخت کی ہے اور اسے کسی نے میرے سامنے ناقابل قبول قرار نہیں دیا۔ اس پر میں سیدنا براء بن عازب رضی اللہ عنہ کے پاس آیا اور ان سے پوچھا تو انہوں نے کہا: نبی صلی اللہ علیہ وسلم مدینہ تشریف لائے اور ہم یہ بیع کیا کرتے تھے تو آپ نے فرمایا: \"جو دست بدست ہے اس میں کوئی حرج نہیں اور جو ادھار ہے وہ سود ہے۔\" زید بن ارقم رضی اللہ عنہ کے پاس جاؤ اور ان کا کاروبار مجھ سے وسیع ہے، چنانچہ میں ان کے پاس آیا اور ان سے پوچھا تو انہوں نے بھی اسی کے مانند کہا۔"}],[4053,"حبیب سے روایت ہے کہ انہوں نے ابومنہال سے سنا ، وہ کہہ رہے تھے : میں نے سیدنا براء بن عازب رضی اللہ عنہ سے دینار کی درہم سے یا سونے کی چاندی سے بیع کے بارے میں پوچھا تو انہوں نے کہا : زید بن ارقم سے پوچھو ، وہ زیادہ جاننے والے ہیں ، چنانچہ میں نے سیدنا زید رضی اللہ عنہ سے پوچھا تو انہوں نے کہا : براء سے پوچھو ، وہ زیادہ جاننے والے ہیں ، پھر دونوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے سونے کے عوض چاندی کی ادھار بیع سے منع فرمایا ۔","",{"u2":"حبیب سے روایت ہے کہ انہوں نے ابومنہال سے سنا، وہ کہہ رہے تھے: میں نے سیدنا براء بن عازب رضی اللہ عنہ سے دینار کی درہم سے یا سونے کی چاندی سے بیع کے بارے میں پوچھا تو انہوں نے کہا: زید بن ارقم سے پوچھو، وہ زیادہ جاننے والے ہیں، چنانچہ میں نے سیدنا زید رضی اللہ عنہ سے پوچھا تو انہوں نے کہا: براء سے پوچھو، وہ زیادہ جاننے والے ہیں، پھر دونوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے سونے کے عوض چاندی کی ادھار بیع سے منع فرمایا۔"}],[4054,"عباد بن عوام نے کہا : یحییٰ بن ابی اسحاق نے ہمیں خبر دی ، انہوں نے کہا : ہمیں عبدالرحمٰن بن ابی بکرہ نے اپنے والد سے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے چاندی کے عوض چاندی اور سونے کے عوض سونے کی بیع سے منع فرمایا ، الا یہ کہ برابر برابر ہو اور آپ نے ہمیں حکم دیا کہ ہم سونے کے عوض چاندی جیسے چاہیں خریدیں اور چاندی کے عوض سونا جیسے چاہیں خریدیں ۔ کہا : اس پر ایک آدمی نے ان سے سوال کیا اور کہا : دست بدست؟ تو انہوں نے کہا : میں نے اسی طرح سنا ہے ۔","",{"u2":"عباد بن عوام نے کہا: یحییٰ بن ابی اسحاق نے ہمیں خبر دی، انہوں نے کہا: ہمیں عبدالرحمٰن بن ابی بکرہ نے اپنے والد سے حدیث بیان کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے چاندی کے عوض چاندی اور سونے کے عوض سونے کی بیع سے منع فرمایا، الا یہ کہ برابر برابر ہو اور آپ نے ہمیں حکم دیا کہ ہم سونے کے عوض چاندی جیسے چاہیں خریدیں اور چاندی کے عوض سونا جیسے چاہیں خریدیں۔ کہا: اس پر ایک آدمی نے ان سے سوال کیا اور کہا: دست بدست؟ تو انہوں نے کہا: میں نے اسی طرح سنا ہے۔"}],[4055,"یحییٰ بن ابی کثیر نے یحییٰ بن ابی اسحاق سے روایت کی کہ انہیں عبدالرحمان بن ابی بکرہ نے بتایا کہ سیدنا ابوبکرہ رضی اللہ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں منع فرمایا ۔ ۔ ( آگے ) اسی کے مانند ہے ۔","",{"u2":"یحییٰ بن ابی کثیر نے یحییٰ بن ابی اسحاق سے روایت کی کہ انہیں عبدالرحمان بن ابی بکرہ نے بتایا کہ سیدنا ابوبکرہ رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں منع فرمایا۔۔ (آگے) اسی کے مانند ہے۔\nیحییٰ بن ابی کثیر نے یحییٰ بن ابی اسحاق سے روایت کی کہ انہیں عبدالرحمان بن ابی بکرہ نے بتایا کہ سیدنا ابوبکرہ رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں منع فرمایا۔۔ (آگے) اسی کے مانند ہے۔"}],[4056,"علی بن رباح لخمی نے کہا : میں نے سیدنا فضالہ بن عبید رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم کے پاس ، جبکہ آپ خیبر میں تھے ، ایک ہار لایا گیا ، اس میں نگینے تھے اور سونا تھا اور وہ ان غنائم میں سے تھا جو فروخت کی جا رہی تھیں تو رسول اللہ صلی اللہ علیہ وسلم نے اس سونے کے بارے میں حکم دیا جو ہار میں تھا ، تو اکیلے اسی کو الگ کر دیا گیا ، پھر رسول اللہ صلی اللہ علیہ وسلم نے ان لوگوں سے ( جو لین دین کر رہے تھے ) فرمایا : \" سونے کے عوض سونا برابر برابر وزن کا ( خریدو اور بیچو ۔)","",{"u2":"علی بن رباح لخمی نے کہا: میں نے سیدنا فضالہ بن عبید رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم کے پاس، جبکہ آپ خیبر میں تھے، ایک ہار لایا گیا، اس میں نگینے تھے اور سونا تھا اور وہ ان غنائم میں سے تھا جو فروخت کی جا رہی تھیں تو رسول اللہ صلی اللہ علیہ وسلم نے اس سونے کے بارے میں حکم دیا جو ہار میں تھا، تو اکیلے اسی کو الگ کر دیا گیا، پھر رسول اللہ صلی اللہ علیہ وسلم نے ان لوگوں سے (جو لین دین کر رہے تھے) فرمایا: \"سونے کے عوض سونا برابر برابر وزن کا (خریدو اور بیچو۔)\""}],[4057,"لیث نے ہمیں ابوشجاع سعید بن یزید سے حدیث بیان کی ، انہوں نے خالد بن ابی عمران سے ، انہوں نے حنش صنعانی سے اور انہوں نے سیدنا فضالہ بن عبید رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں نے خیبر کے دن بارہ دینار میں ایک ہار خریدا ، اس میں سونا اور نگینے تھے ۔ میں نے انہیں الگ الگ کیا تو مجھے اس میں بارہ دینار سے زیادہ مل گئے ، میں نے اس بات کا تذکرہ نبی صلی اللہ علیہ وسلم سے کیا تو آپ نے فرمایا : \" اسے الگ الگ کرنے سے پہلے فروخت نہ کیا جائے ۔","",{"u2":"لیث نے ہمیں ابوشجاع سعید بن یزید سے حدیث بیان کی، انہوں نے خالد بن ابی عمران سے، انہوں نے حنش صنعانی سے اور انہوں نے سیدنا فضالہ بن عبید رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں نے خیبر کے دن بارہ دینار میں ایک ہار خریدا، اس میں سونا اور نگینے تھے۔ میں نے انہیں الگ الگ کیا تو مجھے اس میں بارہ دینار سے زیادہ مل گئے، میں نے اس بات کا تذکرہ نبی صلی اللہ علیہ وسلم سے کیا تو آپ نے فرمایا: \"اسے الگ الگ کرنے سے پہلے فروخت نہ کیا جائے۔\""}],[4058,"ابن مبارک نے سعید بن یزید سے اسی سند کے ساتھ اسی طرح حدیث بیان کی ۔","",{"u2":") ابن مبارک نے سعید بن یزید سے اسی سند کے ساتھ اسی طرح حدیث بیان کی۔"}],[4059,"جلاح ابوکثیر سے روایت ہے ، انہوں نے کہا : مجھے حنش صنعانی نے سیدنا فضالہ بن عبید رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : خیبر کے دن ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے ، ہم یہود کے ساتھ دو یا تین دیناروں کے عوض ایک اوقیہ سونے کی بیع کرتے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" سونے کے عوض سونے کی بیع نہ کرو مگر برابر برابر وزن کے ساتھ ۔","",{"u2":"جلاح ابوکثیر سے روایت ہے، انہوں نے کہا: مجھے حنش صنعانی نے سیدنا فضالہ بن عبید رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: خیبر کے دن ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، ہم یہود کے ساتھ دو یا تین دیناروں کے عوض ایک اوقیہ سونے کی بیع کرتے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سونے کے عوض سونے کی بیع نہ کرو مگر برابر برابر وزن کے ساتھ۔\""}],[4060,"عامر بن یحییٰ معافری نے حنش سے خبر دی کہ انہوں نے کہا : ہم ایک غزوے میں سیدنا فضالہ بن عبید رضی اللہ عنہ کے ساتھ تھے ، میرے اور میرے ساتھیوں کے حصے میں ایک ہار آیا جس میں سونا ، چاندی اور جواہر تھے ۔ میں نے اسے خریدنے کا ارادہ کیا ، چنانچہ میں نے سیدنا فضالہ بن عبید رضی اللہ عنہ سے پوچھا تو انہوں نے کہا : اس کا سونا اتار لو اور اسے ایک پلڑے میں رکھو اور اپنا سونا دوسرے پلڑے میں رکھو ، پھر برابر برابر کے سوا نہ لو ( کیونکہ ) میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے ، آپ فرما رہے تھے : \" جو اللہ اور یومِ آخرت پر ایمان رکھتا ہے وہ ( اس طرح کی بیع میں ) مثل بمثل ( یکساں ) کے سوا ہرگز نہ لے ۔","",{"u2":"عامر بن یحییٰ معافری نے حنش سے خبر دی کہ انہوں نے کہا: ہم ایک غزوے میں سیدنا فضالہ بن عبید رضی اللہ عنہ کے ساتھ تھے، میرے اور میرے ساتھیوں کے حصے میں ایک ہار آیا جس میں سونا، چاندی اور جواہر تھے۔ میں نے اسے خریدنے کا ارادہ کیا، چنانچہ میں نے سیدنا فضالہ بن عبید رضی اللہ عنہ سے پوچھا تو انہوں نے کہا: اس کا سونا اتار لو اور اسے ایک پلڑے میں رکھو اور اپنا سونا دوسرے پلڑے میں رکھو، پھر برابر برابر کے سوا نہ لو (کیونکہ) میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے، آپ فرما رہے تھے: \"جو اللہ اور یومِ آخرت پر ایمان رکھتا ہے وہ (اس طرح کی بیع میں) مثل بمثل (یکساں) کے سوا ہرگز نہ لے۔\""}],[4061,"بُسر بن سعید نے معمر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ انہوں نے گندم کا ایک صاع دے کر اپنا غلام بھیجا اور کہا : اسے بیچ دو ، پھر اس ( کی قیمت ) سے جو خرید لاؤ ۔ غلام گیا اور ( گندم کے صاع کے عوض ) ایک صاع اور صاع سے کچھ زیادہ ( جو ) لے آیا ، جب وہ معمر رضی اللہ عنہ کے پاس آیا تو انہیں یہ بات بتائی ، تو سیدنا معمر رضی اللہ عنہ نے اس سے کہا : تم نے یہ کام کیوں کیا؟ جاؤ اور اسے واپس کرو اور مثل بمثل کے سوا کچھ نہ لو ، میں رسول اللہ صلی اللہ علیہ وسلم سے سنا کرتے تھا ، آپ فرماتے تھے : \" غلے کے عوض غلے کی بیع مثل بمثل ہے ۔ \" کہا : ان دنوں ہماری خوراک جَو کی تھی ۔ ان سے کہا گیا : وہ تو اس ( گندم ) کی مثل نہیں ہے ۔ ( یعنی دو الگ جنسیں ہیں ، اس لیے تفاضل جائز ہے ۔ ) انہوں نے کہا : مجھے خدشہ ہے کہ وہ اس کے مشابہ ہو گی ۔","",{"u2":"بُسر بن سعید نے معمر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ انہوں نے گندم کا ایک صاع دے کر اپنا غلام بھیجا اور کہا: اسے بیچ دو، پھر اس (کی قیمت) سے جو خرید لاؤ۔ غلام گیا اور (گندم کے صاع کے عوض) ایک صاع اور صاع سے کچھ زیادہ (جو) لے آیا، جب وہ معمر رضی اللہ عنہ کے پاس آیا تو انہیں یہ بات بتائی، تو سیدنا معمر رضی اللہ عنہ نے اس سے کہا: تم نے یہ کام کیوں کیا؟ جاؤ اور اسے واپس کرو اور مثل بمثل کے سوا کچھ نہ لو، میں رسول اللہ صلی اللہ علیہ وسلم سے سنا کرتے تھا، آپ فرماتے تھے: \"غلے کے عوض غلے کی بیع مثل بمثل ہے۔\" کہا: ان دنوں ہماری خوراک جَو کی تھی۔ ان سے کہا گیا: وہ تو اس (گندم) کی مثل نہیں ہے۔ (یعنی دو الگ جنسیں ہیں، اس لیے تفاضل جائز ہے۔) انہوں نے کہا: مجھے خدشہ ہے کہ وہ اس کے مشابہ ہو گی۔"}],[4062,"سلیمان بن بلال نے ہمیں عبدالمجید بن سہیل بن عبدالرحمان سے حدیث بیان کی کہ انہوں نے سعید بن مسیب سے سنا ، وہ حدیث بیان کر رہے تھے کہ سیدنا ابوہریرہ اور سیدنا ابو سعید خدری رضی اللہ عنہ نے انہیں حدیث بیان کی ، رسول اللہ صلی اللہ علیہ وسلم نے بنو عدی سے تعلق رکھنے والے ایک انصاری کو بھیجا اور اسے خیبر کا عامل مقرر کیا ، وہ جنیب ( عمدہ قسم کی ) کھجور لے کر آیا ، تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا : \" کیا خیبر کی تمام کھجور اسی طرح کی ہے؟ اس نے عرض کی : اللہ کے رسول! واللہ! نہیں ۔ ہم ملی جلی کھجور کے دو صاع کے عوض ( عمدہ کھجور کا ) ایک صاع خریدتے ہیں ، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایسا نہ کرو بلکہ مثل بمثل ( یکساں خریدو بیچو ) یا پھر اسے بیچ دو اور اس کی قیمت سے دوسری قسم خرید لو ، اسی طرح وزن ( کے ذریعے سے لین دین کرنا ہو تو بھی برابر ہونا ضروری ) ہے ۔","",{"u2":") سلیمان بن بلال نے ہمیں عبدالمجید بن سہیل بن عبدالرحمان سے حدیث بیان کی کہ انہوں نے سعید بن مسیب سے سنا، وہ حدیث بیان کر رہے تھے کہ حضرت ابوہریرہ اور سیدنا ابو سعید خدری رضی اللہ عنہ نے انہیں حدیث بیان کی، رسول اللہ صلی اللہ علیہ وسلم نے بنو عدی سے تعلق رکھنے والے ایک انصاری کو بھیجا اور اسے خیبر کا عامل مقرر کیا، وہ جنیب (عمدہ قسم کی) کھجور لے کر آیا، تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا: \"کیا خیبر کی تمام کھجور اسی طرح کی ہے؟ اس نے عرض کی: اللہ کے رسول! واللہ! نہیں۔ہم ملی جلی کھجور کے دو صاع کے عوض (عمدہ کھجور کا) ایک صاع خریدتے ہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایسا نہ کرو بلکہ مثل بمثل (یکساں خریدو بیچو) یا پھر اسے بیچ دو اور اس کی قیمت سے دوسری قسم خرید لو، اسی طرح وزن (کے ذریعے سے لین دین کرنا ہو تو بھی برابر ہونا ضروری) ہے۔\""}],[4063,"امام مالک نے عبدالمجید بن سہیل بن عبدالرحمان بن عوف سے ، انہوں نے سعید بن مسیب سے اور انہوں نے سیدنا ابوسعید خدری اور سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو خیبر کو عامل مقرر کیا ، وہ آپ کے پاس جنیب ( عمدہ قسم کی ) کھجور لے آیا تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا : \" کیا خیبر کی تمام کھجور اسی طرح کی ہے؟ \" اس نے عرض کی : واللہ! یا رسول اللہ! نہیں ۔ ہم ( ملی جلی کھجور کے ) دو صاع کے عوض اس کا ایک صاع اور تین کے عوض دو صاع لیتے ہیں ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایسا نہ کرو ، ملی جلی کھجور کو درہموں کے عوض بیچ دو ، پھر درہموں سے جنیب ( عمدہ ) کھجور خرید لو ۔","",{"u2":") امام مالک نے عبدالمجید بن سہیل بن عبدالرحمان بن عوف سے، انہوں نے سعید بن مسیب سے اور انہوں نے حضرت ابوسعید خدری اور سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو خیبر کو عامل مقرر کیا، وہ آپ کے پاس جنیب (عمدہ قسم کی) کھجور لے آیا تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا: \"کیا خیبر کی تمام کھجور اسی طرح کی ہے؟\" اس نے عرض کی: واللہ! یا رسول اللہ! نہیں۔ ہم (ملی جلی کھجور کے) دو صاع کے عوض اس کا ایک صاع اور تین کے عوض دو صاع لیتے ہیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایسا نہ کرو، ملی جلی کھجور کو درہموں کے عوض بیچ دو، پھر درہموں سے جنیب (عمدہ) کھجور خرید لو۔\""}],[4064,"اسحاق بن منصور نے کہا : ہمیں یحییٰ بن صالح وحاظی سے حدیث بیان کی ، انہوں نے کہا : ہمیں معاویہ بن سلام نے حدیث سنائی ۔ نیز محمد بن سہیل تمیمی اور عبداللہ بن عبدالرحمٰن دارمی نے ۔ ۔ الفاظ دونوں کے یہی ہیں ۔ ۔ دونوں نے مجھے یحییٰ بن حسان سے حدیث بیان کی ، کہا : ہمیں معاویہ بن سلام نے حدیث سنائی ، انہوں نے کہا : مجھے یحییٰ بن ابی کثیر نے خبر دی ، انہوں نے کہا : میں نے عقبہ بن عبدالغافر سے سنا ، وہ کہہ رہے تھے : میں نے سیدنا ابوسعید رضی اللہ عنہ سے سنا وہ کہہ رہے تھے : سیدنا بلال رضی اللہ عنہ برنی کھجور لے کر آئے تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے پوچھا : \"\" یہ کہاں سے لائے ہو؟ \"\" تو سیدنا بلال رضی اللہ عنہ نے کہا : ہمارے پاس ردی کھجور تھی ، میں نے نبی صلی اللہ علیہ وسلم کے کھانے کے لیے اُسے دو صاع کے عوض ( اِس کے ) ایک صاع سے بیچ دیا ۔ تو اس وقت رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" مجھے افسوس ہوا! تو یہ عین سود ہے ، ایسا نہ کرو بلکہ جب تم کھجور خریدنا چاہو تو اسے ( ردی کھجور کو ) دوسری ( نقدی وغیرہ کے عوض کی گئی ) بیع کے ذریعے سے بیچ دو ، پھر اس ( کی قیمت ) سے ( دوسری قسم ) خرید لو ۔ \"\" ابن سہل نے اپنی حدیث میں \"\" اس وقت \"\" کے الفاظ بیان نہیں کیے","",{"u2":"اسحاق بن منصور نے کہا: ہمیں یحییٰ بن صالح وحاظی سے حدیث بیان کی، انہوں نے کہا: ہمیں معاویہ بن سلام نے حدیث سنائی۔ نیز محمد بن سہیل تمیمی اور عبداللہ بن عبدالرحمٰن دارمی نے۔۔ الفاظ دونوں کے یہی ہیں۔۔ دونوں نے مجھے یحییٰ بن حسان سے حدیث بیان کی، کہا: ہمیں معاویہ بن سلام نے حدیث سنائی، انہوں نے کہا: مجھے یحییٰ بن ابی کثیر نے خبر دی، انہوں نے کہا: میں نے عقبہ بن عبدالغافر سے سنا، وہ کہہ رہے تھے: میں نے سیدنا ابوسعید رضی اللہ عنہ سے سنا وہ کہہ رہے تھے: سیدنا بلال رضی اللہ عنہ برنی کھجور لے کر آئے تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے پوچھا: \"یہ کہاں سے لائے ہو؟\" تو سیدنا بلال رضی اللہ عنہ نے کہا: ہمارے پاس ردی کھجور تھی، میں نے نبی صلی اللہ علیہ وسلم کے کھانے کے لیے اُسے دو صاع کے عوض (اِس کے) ایک صاع سے بیچ دیا۔ تو اس وقت رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے افسوس ہوا! تو یہ عین سود ہے، ایسا نہ کرو بلکہ جب تم کھجور خریدنا چاہو تو اسے (ردی کھجور کو) دوسری (نقدی وغیرہ کے عوض کی گئی) بیع کے ذریعے سے بیچ دو، پھر اس (کی قیمت) سے (دوسری قسم) خرید لو۔\"\nابن سہل نے اپنی حدیث میں \"اس وقت\" کے الفاظ بیان نہیں کیے"}],[4065,"ابونضرہ نے سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے پاس کھجور لائی گئی تو آپ نے فرمایا : \" یہ کھجور ہماری کھجور میں سے نہیں ۔ \" اس پر ایک آدمی نے کہا : اللہ کے رسول! ہم نے اپنی کھجور کے دو صاع اس کھجور کے ایک صاع کے عوض بیچے ہیں ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" یہ سود ہے ، اسے واپس کرو ، پھر ہماری کھجور ( نقدی کے عوض ) فروخت کرو اور ( اس کی قیمت سے ) ہمارے لیے یہ کھجور خریدو ۔","",{"u2":"ابونضرہ نے سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے پاس کھجور لائی گئی تو آپ نے فرمایا: \"یہ کھجور ہماری کھجور میں سے نہیں۔\" اس پر ایک آدمی نے کہا: اللہ کے رسول! ہم نے اپنی کھجور کے دو صاع اس کھجور کے ایک صاع کے عوض بیچے ہیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ سود ہے، اسے واپس کرو، پھر ہماری کھجور (نقدی کے عوض) فروخت کرو اور (اس کی قیمت سے) ہمارے لیے یہ کھجور خریدو۔\""}],[4066,"سیدنا ابوسعید رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ہمیں ( ہمارے حصے میں ) عام کھجور دی جاتی تھی اور وہ ملی جلی کھجور ہوتی تھی تو ہم اس کے دو صاع کے عوض ایک صاع کا سودا کرتے ، رسول اللہ صلی اللہ علیہ وسلم کو یہ بات پہنچی تو آپ نے فرمایا : \" کھجور کے دو صاع ایک صاع کے عوض ( جائز ) نہیں ، گندم کے دو صاع ایک صاع کے عوض ( جائز ) نہیں اور نہ ایک درہم دو درہموں کے عوض ( جائز ہے ۔)","",{"u2":"سیدنا ابوسعید رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ہمیں (ہمارے حصے میں) عام کھجور دی جاتی تھی اور وہ ملی جلی کھجور ہوتی تھی تو ہم اس کے دو صاع کے عوض ایک صاع کا سودا کرتے، رسول اللہ صلی اللہ علیہ وسلم کو یہ بات پہنچی تو آپ نے فرمایا: \"کھجور کے دو صاع ایک صاع کے عوض (جائز) نہیں، گندم کے دو صاع ایک صاع کے عوض (جائز) نہیں اور نہ ایک درہم دو درہموں کے عوض (جائز ہے۔)\""}],[4067,"سعید جریری نے ابونضرہ سے روایت کی ، انہوں نے کہا : میں نے سیدنا ابن عباس رضی اللہ عنہ سے دینار و درہم یا سونے چاندی کے تبادلے کے بارے میں سوال کیا تو انہوں نے کہا : کہا یہ دست بدست ہے؟ میں نے جواب دیا : جی ہاں ، انہوں نے کہا : اس میں کوئی حرج نہیں ۔ میں نے سیدنا ابوسعید رضی اللہ عنہ کو خبر دی ، میں نے کہا : میں نے سیدنا ابن عباس رضی اللہ عنہ سے دینار و درہم یا سونے چاندی کے تبادلے کے بارے میں سوال کیا تھا تو انہوں نے کہا تھا : کیا دست بدست ہے؟ میں نے جواب دیا تھا : ہاں ، تو انہوں نے کہا تھا : اس میں کوئی حرج نہیں ( انہوں نے ایک ہی جنس کی صورت میں مساوات کی شرط لگائے بغیر اسے علی الاطلاق جائز قرار دیا ۔ ) انہوں ( ابوسعید ) نے کہا : کیا انہوں نے یہ بات کہی ہے؟ ہم ان کی طرف لکھیں گے تو وہ تمہیں ( غیر مشروط جواز کا ) یہ فتویٰ نہیں دیں گے ۔ اللہ کی قسم! رسول اللہ صلی اللہ علیہ وسلم کے خدام سے کوئی کھجوریں لے کر آیا تو آپ نے انہیں نہ پہچانا اور فرمایا : \" ایسا لگتا ہے کہ یہ ہماری سرزمین کی کھجوروں میں سے نہیں ہیں ۔ \" اس نے کہا : اس سال ہماری زمین کی کھجوروں میں ۔ ۔ یا ہماری کھجوروں میں ۔ ۔ کوئی چیز ( خرابی ) تھی ، میں نے یہ ( عمدہ کھجوریں ) لے لیں اور بدلے میں کچھ زیادہ دے دیں ، تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" تم نے دوگنا دیں ، تم نے سود کا لین دین کیا ، اس کے قریب ( بھی ) مت جاؤ ، جب تمہیں اپنی کھجور کے بارے میں کسی چیز ( نقص وغیرہ ) کا شک ہو تو اسے فروخت کرو ، پھر کھجور میں سے تم جو چاہتے ہو ( نقدی کے عوج ) خرید لو ۔","",{"u2":"سعید جریری نے ابونضرہ سے روایت کی، انہوں نے کہا: میں نے سیدنا ابن عباس رضی اللہ عنہ سے دینار و درہم یا سونے چاندی کے تبادلے کے بارے میں سوال کیا تو انہوں نے کہا: کہا یہ دست بدست ہے؟ میں نے جواب دیا: جی ہاں، انہوں نے کہا: اس میں کوئی حرج نہیں۔ میں نے سیدنا ابوسعید رضی اللہ عنہ کو خبر دی، میں نے کہا: میں نے سیدنا ابن عباس رضی اللہ عنہ سے دینار و درہم یا سونے چاندی کے تبادلے کے بارے میں سوال کیا تھا تو انہوں نے کہا تھا: کیا دست بدست ہے؟ میں نے جواب دیا تھا: ہاں، تو انہوں نے کہا تھا: اس میں کوئی حرج نہیں (انہوں نے ایک ہی جنس کی صورت میں مساوات کی شرط لگائے بغیر اسے علی الاطلاق جائز قرار دیا۔) انہوں (ابوسعید) نے کہا: کیا انہوں نے یہ بات کہی ہے؟ ہم ان کی طرف لکھیں گے تو وہ تمہیں (غیر مشروط جواز کا) یہ فتویٰ نہیں دیں گے۔ اللہ کی قسم! رسول اللہ صلی اللہ علیہ وسلم کے خدام سے کوئی کھجوریں لے کر آیا تو آپ نے انہیں نہ پہچانا اور فرمایا: \"ایسا لگتا ہے کہ یہ ہماری سرزمین کی کھجوروں میں سے نہیں ہیں۔\" اس نے کہا: اس سال ہماری زمین کی کھجوروں میں۔۔ یا ہماری کھجوروں میں۔۔ کوئی چیز (خرابی) تھی، میں نے یہ (عمدہ کھجوریں) لے لیں اور بدلے میں کچھ زیادہ دے دیں، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم نے دوگنا دیں، تم نے سود کا لین دین کیا، اس کے قریب (بھی) مت جاؤ، جب تمہیں اپنی کھجور کے بارے میں کسی چیز (نقص وغیرہ) کا شک ہو تو اسے فروخت کرو، پھر کھجور میں سے تم جو چاہتے ہو (نقدی کے عوج) خرید لو۔\""}],[4068,"داود نے ہمیں ابونضرہ سے خبر دی ، انہوں نے کہا : میں نے سیدنا ابن عمر رضی اللہ عنہ اور سیدنا ابن عباس رضی اللہ عنہ سے سونا چاندی کے تبادلے کے بارے میں پوچھا تو ان دونوں نے اس میں کوئی حرج نہ دیکھا ۔ میں سیدنا ابوسعید خدری رضی اللہ عنہ کے پاس بیٹھا ہوا تھا تو میں نے ان سے اس تبادلے کے بارے میں پوچھا ، تو انہوں نے کہا : ( ایک ہی جنس کے تبادلے میں ) جو اضافہ ہو گا وہ سود ہے ۔ میں نے ان دونوں کے قول کی بنا پر ( جس میں انہوں نے ایسی کوئی شرط نہ لگائی تھی ) اس بات کا انکار کیا تو انہوں نے کہا : میں تمہیں وہی حدیث بیان کروں گا جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ۔ آپ کے باغ کا نگران آپ کے پاس عمدہ کھجور کا ایک صاع لایا اور نبی صلی اللہ علیہ وسلم کی کھجور اس ( عام ) قسم کی تھی تو نبی صلی اللہ علیہ وسلم نے اس سے پوچھا : \"\" یہ تمہارے پاس کہاں سے آئیں؟ \"\" اس نے کہا : میں ( اس کے ) دو صاع لے کر گیا اور ان کے عوض میں نے یہ ایک صاع خرید لی ، بازار میں اِس کا نرخ اتنا ہے اور اُس کا اتنا ہے ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" تم پر افسوس! تم نے سود کا معاملہ کیا ، جب تم یہ ( عمدہ کھجور ) لینا چاہو تو اپنی کھجور کسی ( اور ) تجارتی چیز کے عوض فروخت کر دو ، پھر اپنی چیز سے جو کھجور چاہو ، خرید لو ۔ \"\" سیدنا ابوسعید رضی اللہ عنہ نے کہا : کھجور کے عوض کھجور ، زیادہ لائق ہے کہ سود ہو ، یا چاندی کے عوض چاندی؟ ( ابونضرہ نے ) کہا : میں اس کے بعد سیدنا ابن عمر رضی اللہ عنہ کے پاس آیا تو انہوں نے مجھے اس سے منع کیا اور میں سیدنا ابن عباس رضی اللہ عنہ کے پاس نہیں آیا ۔ کہا : مجھے ابوصبہاء نے حدیث بیان کی کہ انہوں نے مکہ میں سیدنا ابن عباس رضی اللہ عنہ سے اس کے بارے میں سوال کیا تو انہوں نے بھی اسے ناپسند کیا تھا ۔","",{"u2":"داود نے ہمیں ابونضرہ سے خبر دی، انہوں نے کہا: میں نے سیدنا ابن عمر رضی اللہ عنہ اور سیدنا ابن عباس رضی اللہ عنہ سے سونا چاندی کے تبادلے کے بارے میں پوچھا تو ان دونوں نے اس میں کوئی حرج نہ دیکھا۔ میں سیدنا ابوسعید خدری رضی اللہ عنہ کے پاس بیٹھا ہوا تھا تو میں نے ان سے اس تبادلے کے بارے میں پوچھا، تو انہوں نے کہا: (ایک ہی جنس کے تبادلے میں) جو اضافہ ہو گا وہ سود ہے۔ میں نے ان دونوں کے قول کی بنا پر (جس میں انہوں نے ایسی کوئی شرط نہ لگائی تھی) اس بات کا انکار کیا تو انہوں نے کہا: میں تمہیں وہی حدیث بیان کروں گا جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنی۔ آپ کے باغ کا نگران آپ کے پاس عمدہ کھجور کا ایک صاع لایا اور نبی صلی اللہ علیہ وسلم کی کھجور اس (عام) قسم کی تھی تو نبی صلی اللہ علیہ وسلم نے اس سے پوچھا: \"یہ تمہارے پاس کہاں سے آئیں؟\" اس نے کہا: میں (اس کے) دو صاع لے کر گیا اور ان کے عوض میں نے یہ ایک صاع خرید لی، بازار میں اِس کا نرخ اتنا ہے اور اُس کا اتنا ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم پر افسوس! تم نے سود کا معاملہ کیا، جب تم یہ (عمدہ کھجور) لینا چاہو تو اپنی کھجور کسی (اور) تجارتی چیز کے عوض فروخت کر دو، پھر اپنی چیز سے جو کھجور چاہو، خرید لو۔\"\nسیدنا ابوسعید رضی اللہ عنہ نے کہا: کھجور کے عوض کھجور، زیادہ لائق ہے کہ سود ہو، یا چاندی کے عوض چاندی؟ (ابونضرہ نے) کہا: میں اس کے بعد سیدنا ابن عمر رضی اللہ عنہ کے پاس آیا تو انہوں نے مجھے اس سے منع کیا اور میں سیدنا ابن عباس رضی اللہ عنہ کے پاس نہیں آیا۔ کہا: مجھے ابوصبہاء نے حدیث بیان کی کہ انہوں نے مکہ میں سیدنا ابن عباس رضی اللہ عنہ سے اس کے بارے میں سوال کیا تو انہوں نے بھی اسے ناپسند کیا تھا۔"}],[4069,"ابوصالح سے روایت ہے ، انہوں نے کہا : میں نے سیدنا ابوسعید خدری رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : دینار کے بدلے دینار اور درہم کے بدلے درہم مثل بمثل ہو ، جس نے زیادہ دیا یا زیادہ لیا ، اس نے سود کا معاملہ کیا ۔ میں نے ان سے کہا : سیدنا ابن عباس رضی اللہ عنہ تو اس سے مختلف بات کہتے ہیں ، تو انہوں نے کہا : میں نے خود ابن عباس رضی اللہ عنہ سے ملاقات کی اور کہا : آپ کی کیا رائے ہے ، یہ جو آپ کہتے ہیں کیا آپ نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے سنی ہے یا اللہ کی کتاب میں پائی ہے؟ تو انہوں نے کہا : نہ میں نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے سنی نہ کتاب اللہ میں پائی ، بلکہ مجھے اسامہ بن زید رضی اللہ عنہ نے بیان کیا ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \" سود ادھار میں ہے","",{"u2":"ابوصالح سے روایت ہے، انہوں نے کہا: میں نے سیدنا ابوسعید خدری رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: دینار کے بدلے دینار اور درہم کے بدلے درہم مثل بمثل ہو، جس نے زیادہ دیا یا زیادہ لیا، اس نے سود کا معاملہ کیا۔ میں نے ان سے کہا: سیدنا ابن عباس رضی اللہ عنہ تو اس سے مختلف بات کہتے ہیں، تو انہوں نے کہا: میں نے خود ابن عباس رضی اللہ عنہ سے ملاقات کی اور کہا: آپ کی کیا رائے ہے، یہ جو آپ کہتے ہیں کیا آپ نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے سنی ہے یا اللہ کی کتاب میں پائی ہے؟ تو انہوں نے کہا: نہ میں نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے سنی نہ کتاب اللہ میں پائی، بلکہ مجھے اسامہ بن زید رضی اللہ عنہ نے بیان کیا ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"سود ادھار میں ہے"}],[4070,"عبیداللہ بن ابی یزید سے روایت ہے کہ انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : مجھے اسامہ بن زید رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے خبر دی ، آپ نے فرمایا : \" ( اگر جنسیں مختلف ہوں تو ) سود ادھار میں ہی ہے ۔","",{"u2":") عبیداللہ بن ابی یزید سے روایت ہے کہ انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: مجھے اسامہ بن زید رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے خبر دی، آپ نے فرمایا: \"(اگر جنسیں مختلف ہوں تو) سود ادھار میں ہی ہے۔\""}],[4071,"طاوس نے سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے سیدنا اسامہ بن زید رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ( مختلف چیزوں کے تبادلے میں ) جو دست بدست ہو اس میں سود نہیں ہے ۔","",{"u2":"طاوس نے سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے سیدنا اسامہ بن زید رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(مختلف چیزوں کے تبادلے میں) جو دست بدست ہو اس میں سود نہیں ہے۔\""}],[4072,"عطاء بن ابی رباح نے مجھے حدیث بیان کی کہ سیدنا ابوسعید خدری رضی اللہ عنہ نے سیدنا ابن عباس رضی اللہ عنہ سے ملاقات کی اور ان سے کہا : بیع صَرف ( نقدی یا سونے چاندی کے تبادلے ) کے حوالے سے آپ کی اپنے قول کے بارے میں کیا رائے ہے ، کیا آپ نے یہ چیز رسول اللہ صؒی اللہ علیہ وسلم سے سنی ہے یا اللہ کی کتاب میں پائی ہے؟ سیدنا ابن عباس رضی اللہ عنہ نے کہا : میں ان میں سے کوئی بات نہیں کہتا ، رسول اللہ صلی اللہ علیہ وسلم کو تم مجھ سے زیادہ جاننے والے ہو اور رہی اللہ کی کتاب تو میں ( اس میں ) اس بات کو نہیں جانتا ، البتہ اسامہ بن زید رضی اللہ عنہ نے مجھے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" متنبہ رہو! سود ادھار میں ہی ہے ۔","",{"u2":"عطاء بن ابی رباح نے مجھے حدیث بیان کی کہ سیدنا ابوسعید خدری رضی اللہ عنہ نے سیدنا ابن عباس رضی اللہ عنہ سے ملاقات کی اور ان سے کہا: بیع صَرف (نقدی یا سونے چاندی کے تبادلے) کے حوالے سے آپ کی اپنے قول کے بارے میں کیا رائے ہے، کیا آپ نے یہ چیز رسول اللہ ص رحمہ اللہ ی اللہ علیہ وسلم سے سنی ہے یا اللہ کی کتاب میں پائی ہے؟ سیدنا ابن عباس رضی اللہ عنہ نے کہا: میں ان میں سے کوئی بات نہیں کہتا، رسول اللہ صلی اللہ علیہ وسلم کو تم مجھ سے زیادہ جاننے والے ہو اور رہی اللہ کی کتاب تو میں (اس میں) اس بات کو نہیں جانتا، البتہ اسامہ بن زید رضی اللہ عنہ نے مجھے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"متنبہ رہو! سود ادھار میں ہی ہے۔\""}],[4073,"علقمہ نے سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے سود کھانے اور کھلانے والے پر لعنت کی ۔ کہا : میں نے پوچھا : اس کے لکھنے والے اور دونوں گواہوں پر بھی؟ انہوں نے کہا : ہم صرف وہ حدیث بیان کرتے ہیں جو ہم نے سنی ہے ۔","",{"u2":") علقمہ نے حضرت عبداللہ (بن مسعود رضی اللہ عنہ) سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے سود کھانے اور کھلانے والے پر لعنت کی۔ کہا: میں نے پوچھا: اس کے لکھنے والے اور دونوں گواہوں پر بھی؟ انہوں نے کہا: ہم صرف وہ حدیث بیان کرتے ہیں جو ہم نے سنی ہے۔"}],[4074,"سیدنا جابر رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے سود کھانے والے ، کھلانے والے ، لکھنے والے اور اس کے دونوں گواہوں پر لعنت کی اور فرمایا : ( گناہ میں ) یہ سب برابر ہیں ۔","",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے سود کھانے والے، کھلانے والے، لکھنے والے اور اس کے دونوں گواہوں پر لعنت کی اور فرمایا: (گناہ میں) یہ سب برابر ہیں۔"}],[4075,"عبداللہ بن نمیر ہمدانی نے ہمیں حدیث بیان کی ، کہا : ہمیں زکریا نے شعبی سے حدیث بیان کی ، انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی ، ( شعبی نے ) کہا : میں نے ان سے سنا ، وہ کہہ رہے تھے : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، ۔ ۔ اور سیدنا نعمان رضی اللہ عنہ نے اپنی دونوں انگلیوں سے اپنے دونوں کانوں کی طرف اشارہ کیا ۔ ۔ آپ فرما رہے تھے : \" بلاشبہ حلال واضح ہے اور حرام واضح ہے اور ان دونوں کے درمیان شبہات ہیں لوگوں کی بڑی تعداد ان کو نہیں جانتی ، جو شبہات سے بچا اس نے اپنے دین اور عزت کو بچا لیا اور جو شبہات میں پڑ گیا وہ حرام میں پڑ گیا ، جیسے چرواہا ( جو ) چراگاہ کے اردگرد ( بکریاں ) چراتا ہے ، قریب ہے وہ اس ( چراگاہ ) میں چرنے لگیں ، دیکھو! ہر بادشاہ کی چراگاہ ہے ۔ دھیان رکھو! اللہ کی چراگاہ اس کی حرام کردہ اشیاء ہیں ۔ سنو! جسم میں ایک ٹکڑا ہے ، اگر ٹھیک رہا تو سارا جسم ٹھیک رہا اور اگر وہ بگڑ گیا تو سارا جسم بگڑ گیا ۔ سنو! وہ دل ہے ۔ \" ( سوچ اور نیت سے ہر عمل کی درستی ہے یا خرابی ۔)","",{"u2":"عبداللہ بن نمیر ہمدانی نے ہمیں حدیث بیان کی، کہا: ہمیں زکریا نے شعبی سے حدیث بیان کی، انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی، (شعبی نے) کہا: میں نے ان سے سنا، وہ کہہ رہے تھے: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا،۔۔ اور سیدنا نعمان رضی اللہ عنہ نے اپنی دونوں انگلیوں سے اپنے دونوں کانوں کی طرف اشارہ کیا۔۔ آپ فرما رہے تھے: \"بلاشبہ حلال واضح ہے اور حرام واضح ہے اور ان دونوں کے درمیان شبہات ہیں لوگوں کی بڑی تعداد ان کو نہیں جانتی، جو شبہات سے بچا اس نے اپنے دین اور عزت کو بچا لیا اور جو شبہات میں پڑ گیا وہ حرام میں پڑ گیا، جیسے چرواہا (جو) چراگاہ کے اردگرد (بکریاں) چراتا ہے، قریب ہے وہ اس (چراگاہ) میں چرنے لگیں، دیکھو! ہر بادشاہ کی چراگاہ ہے۔ دھیان رکھو! اللہ کی چراگاہ اس کی حرام کردہ اشیاء ہیں۔ سنو! جسم میں ایک ٹکڑا ہے، اگر ٹھیک رہا تو سارا جسم ٹھیک رہا اور اگر وہ بگڑ گیا تو سارا جسم بگڑ گیا۔ سنو! وہ دل ہے۔\" (سوچ اور نیت سے ہر عمل کی درستی ہے یا خرابی۔)"}],[4076,"وکیع اور عیسیٰ بن یونس نے زکریا سے اسی سند کے ساتھ اسی کی مانند حدیث بیان کی ۔","",{"u2":"وکیع اور عیسیٰ بن یونس نے زکریا سے اسی سند کے ساتھ اسی کی مانند حدیث بیان کی۔"}],[4077,"اس سند سے بھی مذکورہ بالا حدیث مروی ہے ۔ لیکن زکریا کی حدیث ان سب سے زیادہ مکمل ہے ۔"],[4078,"نعمان بن بشیر بن سعد سے روایت ہے جو صحابی تھے رسول االله صلی اللہ علیہ وسلم کے اور وہ خطبہ سناتے تھے لوگوں کو حمص میں ( ایک شہر کا نام ہے شام میں ) اور کہتے تھے میں نے سنا رسول االله صلی اللہ علیہ وسلم سے آپ فرماتے تھے حلال کھلا ہوا ہے اور حرام کھلا ہوا ہے ۔ پھر بیان کیا حدیث کو اسی طرح جیسے اوپر گزری ۔ یوشک ان یقع فیہ تک ۔"],[4079,"جابر بن عبداالله رضی االله عنہ سے روایت ہے وہ جارہے تھے ایک اونٹ پر جو تھک گیا تھا انہوں نے چاہا اس کو آزاد کردینا ( یعنی چھوڑ دینا جنگل میں ) جابرؓ نے کہا رسول االله صلی اللہ علیہ وسلم مجھ سے آن کر ملے او رمیرے لیے دعا کی اور اونٹ کو مارا پھر وہ ایسا چلا کہ وہ ایسا کبھی نہیں چلا تھا ( یہ آپ کا معجزہ تھا ) ۔ آپ نے فرمایا اس کو میرے ہاتھ بیچ ڈال ایک اوقیہ پر ( دوسری روایت میں پانچ اوقیہ ہیں اور ایک اوقیہ زیادہ دیا اور ایک روایت میں دو اوقیہ اور ایک درم یا دو درم ہیں اور ایک روایت میں سونے کا ایک اوقیہ اور ایک روایت میں چار دینار اور بخاری نے ایک روایت میں آٹھ سو درم اور ایک روایت میں بیس دینرا او رایک روایت میں چار اوقیہ نقل کیے ہیں ) ۔ میں نے کہا نہیں پھر آپ نے فرمایا اس کو میرے ہاتھ بیچ ڈال ۔ میں نے ایک اوقیہ پر آپ صلی اللہ علیہ وسلم کے ہاتھ بیچ ڈالا اور شرط کی اس پر سواری کی اپنے گھر تک ۔ جب میں اپنے گھر پہنچا تو اونٹ آپ کے پاس لے کر آیا آپ نے اس کی قیمت میرے حوالے کی ۔ میں لوتا پھر آپ نے مجھ کو بلا بھیجا اور فرمایا کیا میں تجھ سے قیمت کم کراتا تھا تیرا اونٹ لینے کے لیے اپنا اونٹ لے جا او رروپیہ بھی تیرا ہے ۔"],[4080,"مذکورہ بالا حدیث اس سند سے بھی مروی ہے ۔"],[4081,"جابر بن عبداالله رضی االله عنہ سے روایت ہے میں نے جہاد کیا رسول االله صلی اللہ علیہ وسلم کے ساتھ تو آپ مجھ سے ملے ( راہ میں ) اور میری سواری میں ایک اونٹ تھا پانی کا وہ تھک گیا تھا اور بالکل چل نہ سکتا تھا ۔ آپ نے پوچھا تیرے اونٹ کو کیا ہوا ہے؟ میں نے عرض کیا وہ بیمار ہے ۔ یہ سن کر جناب رسول االله صلی اللہ علیہ وسلم پیچھے ہٹے اور اونٹ کو ڈانٹا اور اس کے لیے دعا کی پھر وہ ہمیشہ سب اونٹوں کے آگے ہی چلتا رہا ۔ آپ نے فرمایا اب تیرا اونٹ کیسا ہے؟ میں نے کا اچھا ہے آپ کی دعا کی برکت سے آپ نے فرمایا میرے ہاتھ بیچتا ہے مجھے شرم آئی اور ہمارے پاس او رکوئی اونٹ پانی لانے کے لیے نہ تھا آخر میں نے کہا ہاں بیچتا ہوں پھر میں نے اس اونٹ کو آپ ہاتھ بیچ ڈالا اس شرط سے کہ میں اس پر سواری کروں گا مدینے تک پھر میں نے عرض کیا یا رسول االله صلی اللہ علیہ وسلم میں نوشہ ہوں ( یعنی ابھی میرا نکاح ہوا ہے ) مجھے اجازت دیجیے ( لوگوں سے پہلے مدینہ جانے کی ) ۔ آپ نے اجازت دی میں لوگوں سے آگے برھ کر مدینہ آپہنچا وہاں میرے ماموں ملے اور اونٹ کا حال پوچھا ۔ میں نے سب حال بیان کیا ۔ انہوں نے مجھ کو ملامت کی ( کہ ایک ہی اونٹ تھا تیرے پاس اور گھر والے بہت ہیں اس کو بھی تونے بیچ ڈالا اور اس کو یہ معلوم نہ تھا کہ خداوند کریم کو جابرؓ کا فائدہ منظور ہے ) ۔ جابرؓ نے کہاجب میں نے آپ سے اجازت مانگی تو آپ نے فرمایا تونے کنواری سے شادی کی ہے یا نکاحی سے؟ میں نے کہا نکاحی سے ۔ آپ نے فرمایا کنواری سے کیوں نے کی وہ تجھ سے کھیلتی اور تو اس سے کھیلتا؟ میں نے عرض کی یا رسول االله! میرا باپ مرگیا یا شہید ہوگیا میری کئی بہن ہیں چھوڑ کر چھوٹی چھوٹی تو مجھے برا معلوم ہوا کہ میں شادی کرکے ایک اور لڑکی لاؤں ان کے برابر جو نہ ان کو ادب سکھائے اور نہ ان کو دبائے ۔ اس لیے میں نے ایک نکاحی سے شادی کی تاکہ ان کو دابے اور تمیز سکھائے ۔ جابرؓ نے کہا پھر جب رسول االله صلی اللہ علیہ وسلم مدینہ میں تشریف لائے میں اونٹ صبح ہی لے گیا آپ نے اس کی قیمت مجھ کو دی اور اونٹ بھی پھیر دیا ۔"],[4082,"سالم بن ابی جعد نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کی معیت میں مکہ ( کی جانب ) سے مدینہ آئے ، تو میرا اونٹ بیمار ہو گیا ۔ ۔ ۔ اور انہوں نے ( ان سے ) مکمل قصے سمیت حدیث بیان کی ، اس میں ہے : پھر آپ نے مجھ سے فرمایا : \" مجھے اپنا یہ اونٹ فروخت کر دو ۔ \" میں نے کہا : نہیں ، بلکہ وہ ( ویسے ہی ) آپ ہی کا ہے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" نہیں ، بلکہ وہ مجھے فروخت کر دو ۔ \" میں نے کہا : نہیں ، اے اللہ کے رسول! وہ آپ ہی کا ہے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" نہیں ، بلکہ اسے میرے یاتھ فروخت کر دو ۔ \" میں نے کہا : ایک آدمی کا میرے ذمے سونے کا ایک اوقیہ ( تقریبا 29 گرام ) ہے ، اس کے عوض یہ آپ کا ہوا ۔ آپ نے فرمایا : \" میں نے لے لیا ، تم اس پر مدینہ تک پہنچ جاؤ ۔ \" کہا : جب میں مدینہ پہنچا ، رسول اللہ صلی اللہ علیہ وسلم نے بلال رضی اللہ عنہ سے فرمایا : \" انہیں ایک اوقیہ سونا اور کچھ زیادہ بھی دو ۔ \" کہا : انہوں نے مجھے ایک اوقیہ سونا دیا اور ایک قیراط زائد دیا ۔ کہا : میں نے ( دل میں ) کہا : رسول اللہ صلی اللہ علیہ وسلم کا یہ زائد عطیہ مجھ سے کبھی الگ نہ ہو گا ۔ کہا : تو وہ میری تھیلی میں رہا حتی کہ حرہ کی جنگ کے دن اہل شام نے اسے ( مجھ سے ) چھین لیا ۔","",{"u2":"سالم بن ابی جعد نے سیدنا جابر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کی معیت میں مکہ (کی جانب) سے مدینہ آئے، تو میرا اونٹ بیمار ہو گیا۔۔۔ اور انہوں نے (ان سے) مکمل قصے سمیت حدیث بیان کی، اس میں ہے: پھر آپ نے مجھ سے فرمایا: \"مجھے اپنا یہ اونٹ فروخت کر دو۔\" میں نے کہا: نہیں، بلکہ وہ (ویسے ہی) آپ ہی کا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں، بلکہ وہ مجھے فروخت کر دو۔\" میں نے کہا: نہیں، اے اللہ کے رسول! وہ آپ ہی کا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں، بلکہ اسے میرے یاتھ فروخت کر دو۔\" میں نے کہا: ایک آدمی کا میرے ذمے سونے کا ایک اوقیہ (تقریبا 29 گرام) ہے، اس کے عوض یہ آپ کا ہوا۔ آپ نے فرمایا: \"میں نے لے لیا، تم اس پر مدینہ تک پہنچ جاؤ۔\" کہا: جب میں مدینہ پہنچا، رسول اللہ صلی اللہ علیہ وسلم نے بلال رضی اللہ عنہ سے فرمایا: \"انہیں ایک اوقیہ سونا اور کچھ زیادہ بھی دو۔\" کہا: انہوں نے مجھے ایک اوقیہ سونا دیا اور ایک قیراط زائد دیا۔ کہا: میں نے (دل میں) کہا: رسول اللہ صلی اللہ علیہ وسلم کا یہ زائد عطیہ مجھ سے کبھی الگ نہ ہو گا۔ کہا: تو وہ میری تھیلی میں رہا حتی کہ حرہ کی جنگ کے دن اہل شام نے اسے (مجھ سے) چھین لیا۔"}],[4083,"ابونضرہ نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ایک سفر میں ہم نبی صلی اللہ علیہ وسلم کے ساتھ تھے ، میرا اونٹ پیچھے رہ گیا ۔ ۔ اور ( پوری ) حدیث بیان کی اور اس میں کہا : رسول اللہ صلی اللہ علیہ وسلم نے اسے کچوکا لگایا ، پھر مجھ سے فرمایا : \" اللہ کا نام لے کر سوار ہو جاؤ ۔ \" اور یہ اضافہ بھی کیا ، کہا : آپ مسلسل مجھے زیادہ کی پیشکش کرتے اور فرماتے رہے : \" اللہ تمہیں معاف فرمائے ۔","",{"u2":"ابونضرہ نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ایک سفر میں ہم نبی صلی اللہ علیہ وسلم کے ساتھ تھے، میرا اونٹ پیچھے رہ گیا۔۔ اور (پوری) حدیث بیان کی اور اس میں کہا: رسول اللہ صلی اللہ علیہ وسلم نے اسے کچوکا لگایا، پھر مجھ سے فرمایا: \"اللہ کا نام لے کر سوار ہو جاؤ۔\" اور یہ اضافہ بھی کیا، کہا: آپ مسلسل مجھے زیادہ کی پیشکش کرتے اور فرماتے رہے: \"اللہ تمہیں معاف فرمائے۔\""}],[4084,"ابوزبیر نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : جب نبی صلی اللہ علیہ وسلم میرے پاس آئے اور میرا اونٹ تھک چکا تھا تو آپ نے اسے کچوکا لگایا ، وہ اچھل پڑا ۔ اس کے بعد میں اس کی لگام کھینچتا تاکہ آپ کی بات سنوں لیکن میں اس پر قابو نہ پا رہا تھا ، نبی صلی اللہ علیہ وسلم مجھے ملے تو فرمایا : \" یہ مجھے بیچ دو ۔ \" میں نے وہ ( اونٹ ) آپ کو پانچ اوقیہ ( چاندی جو ایک اوقیہ سونے کے برابر تھی ) کے عوض فروخت کر دیا ۔ میں نے کہا : اس شرط پر کہ مدینہ تک اس کی پیٹھ ( پر سواری ) میرے لیے ہو گی ۔ آپ نے فرمایا : \" مدینہ تک اس کی پیٹھ ( پر سواری ) تمہاری ہو گی ۔ \" کہا : جب میں مدینہ پہنچا ، اس ( اونٹ ) کو آپ کے پاس لایا تو آپ نے مجھے ایک اوقیہ ( طے شدہ قیمت کا چوتھا حصہ ) زائد دیا ، پھر آپ نے مجھے ( اونٹ بھی ) ہبہ کر دیا ۔","",{"u2":"ابوزبیر نے سیدنا جابر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: جب نبی صلی اللہ علیہ وسلم میرے پاس آئے اور میرا اونٹ تھک چکا تھا تو آپ نے اسے کچوکا لگایا، وہ اچھل پڑا۔ اس کے بعد میں اس کی لگام کھینچتا تاکہ آپ کی بات سنوں لیکن میں اس پر قابو نہ پا رہا تھا، نبی صلی اللہ علیہ وسلم مجھے ملے تو فرمایا: \"یہ مجھے بیچ دو۔\"میں نے وہ (اونٹ) آپ کو پانچ اوقیہ (چاندی جو ایک اوقیہ سونے کے برابر تھی) کے عوض فروخت کر دیا۔ میں نے کہا: اس شرط پر کہ مدینہ تک اس کی پیٹھ (پر سواری) میرے لیے ہو گی۔ آپ نے فرمایا: \"مدینہ تک اس کی پیٹھ (پر سواری) تمہاری ہو گی۔\" کہا: جب میں مدینہ پہنچا، اس (اونٹ) کو آپ کے پاس لایا تو آپ نے مجھے ایک اوقیہ (طے شدہ قیمت کا چوتھا حصہ) زائد دیا، پھر آپ نے مجھے (اونٹ بھی) ہبہ کر دیا۔"}],[4085,"ابومتوکل ناجی نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر کیا ۔ ۔ میرا خیال ہے کہ انہوں نے جنگی سفر کہا ۔ ۔ اور حدیث بیان کی اور اس میں یہ اضافہ کیا ، آپ صلی اللہ علیہ وسلم نے فرمایا : \" جابر! کیا تم نے پوری قیمت لے لی ہے؟ \" میں نے کہا : جی ہاں ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" قیمت بھی تمہاری ، اونٹ بھی تمہارا ، ( پھر فرمایا : ) قیمت بھی تمہاری ، اونٹ بھی تمہارا ۔","",{"u2":"ابومتوکل ناجی نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر کیا۔۔ میرا خیال ہے کہ انہوں نے جنگی سفر کہا۔۔ اور حدیث بیان کی اور اس میں یہ اضافہ کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جابر! کیا تم نے پوری قیمت لے لی ہے؟\" میں نے کہا: جی ہاں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"قیمت بھی تمہاری، اونٹ بھی تمہارا، (پھر فرمایا:) قیمت بھی تمہاری، اونٹ بھی تمہارا۔\""}],[4086,"معاذ عنبری نے ہمیں حدیث بیان کی ، کہا : ہمیں شعبہ نے محارب سے حدیث بیان کی کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے دو اوقیہ اور ایک یا دو درہموں میں اونٹ خریدا ۔ جب آپ صرار ( کے مقام پر ) آئے تو آپ نے گائے ( ذبح کرنے ) کا حکم دیا ، وہ ذبح کی گئی ، لوگوں نے اسے کھایا ، جب آپ مدینہ تشریف لائے تو آپ نے مجھے حکم دیا کہ میں مسجد آؤں اور دو رکعتیں پڑھوں ۔ آپ نے میرے لیے اونٹ کی قیمت ( کے برابر سونے یا چاندی ) کا وزن کیا اور میرے لیے پلڑا جھکا دیا ۔ فائدہ : قیمت کے حوالے سے سیدنا جابر رضی اللہ عنہ سے اس حدیث کے راوی محارب ( بن وثار ) کو وہم ہوا ہے جس طرح اگلی حدیث سے ثابت ہوتا ہے ، وہ اصل قیمت کو صحیح طور پر یاد نہیں رکھ سکے ۔ سیدنا جابر رضی اللہ عنہ نے جب چاندی کے حساب سے اونٹ کی قیمت بتائی تو اس وقت چاندی کا ایک اوقیہ زائد دیے جانے کی بات کی ہے ۔ ( دیکھیے ، حدیث : 4103 ) چاندی کے اس اوقیے کو غلطی سے سونے کے ایک اوقیے کے ساتھ ملا کر دو اوقیے کر دیا گیا ہے ، ان احادیث میں قیمت یا سونے میں بیان کی گئی ہے یا اس کی قیمت کے برابر چاندی میں یا اسی کے برابر دیناروں میں ۔ بعض نے اضافے کو قیمت کے ساتھ شامل کر دیا ہے جس سے التباس پیدا ہوا ہے ۔ البتہ سب احادیث اصل مسئلہ میں ایک دوسرے کی تائید کرتی ہیں ۔","",{"u2":"معاذ عنبری نے ہمیں حدیث بیان کی، کہا: ہمیں شعبہ نے محارب سے حدیث بیان کی کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے دو اوقیہ اور ایک یا دو درہموں میں اونٹ خریدا۔ جب آپ صرار (کے مقام پر) آئے تو آپ نے گائے (ذبح کرنے) کا حکم دیا، وہ ذبح کی گئی، لوگوں نے اسے کھایا، جب آپ مدینہ تشریف لائے تو آپ نے مجھے حکم دیا کہ میں مسجد آؤں اور دو رکعتیں پڑھوں۔ آپ نے میرے لیے اونٹ کی قیمت (کے برابر سونے یا چاندی) کا وزن کیا اور میرے لیے پلڑا جھکا دیا۔\nفائدہ: قیمت کے حوالے سے سیدنا جابر رضی اللہ عنہ سے اس حدیث کے راوی محارب (بن وثار) کو وہم ہوا ہے جس طرح اگلی حدیث سے ثابت ہوتا ہے، وہ اصل قیمت کو صحیح طور پر یاد نہیں رکھ سکے۔ سیدنا جابر رضی اللہ عنہ نے جب چاندی کے حساب سے اونٹ کی قیمت بتائی تو اس وقت چاندی کا ایک اوقیہ زائد دیے جانے کی بات کی ہے۔ (دیکھیے، حدیث: 4103) چاندی کے اس اوقیے کو غلطی سے سونے کے ایک اوقیے کے ساتھ ملا کر دو اوقیے کر دیا گیا ہے، ان احادیث میں قیمت یا سونے میں بیان کی گئی ہے یا اس کی قیمت کے برابر چاندی میں یا اسی کے برابر دیناروں میں۔ بعض نے اضافے کو قیمت کے ساتھ شامل کر دیا ہے جس سے التباس پیدا ہوا ہے۔ البتہ سب احادیث اصل مسئلہ میں ایک دوسرے کی تائید کرتی ہیں۔"}],[4087,"خالد بن حارث نے ہمیں حدیث بیان کی ، کہا : ہمیں شعبہ نے حدیث بیان کی ، انہوں نے کہا : مجھے محارب نے سیدنا جابر رضی اللہ عنہ سے خبر دی اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی قصہ بیان کیا ، مگر انہوں نے کہا : آپ نے مجھ سے اونٹ قیمتا خرید لیا جس کی انہوں ( جابر رضی اللہ عنہ ) نے تعیین بھی کی ، ( اس روایت میں ) انہوں نے دو اوقیہ ، ایک درہم اور دو درہموں کا تذکرہ نہیں کیا اور کہا : آپ نے گائے کا حکم دیا تو اسے ذبح کیا گیا ، پھر آپ نے اس کا گوشت تقسیم کر دیا ۔","",{"u2":"خالد بن حارث نے ہمیں حدیث بیان کی، کہا: ہمیں شعبہ نے حدیث بیان کی، انہوں نے کہا: مجھے محارب نے سیدنا جابر رضی اللہ عنہ سے خبر دی اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی قصہ بیان کیا، مگر انہوں نے کہا: آپ نے مجھ سے اونٹ قیمتا خرید لیا جس کی انہوں (جابر رضی اللہ عنہ) نے تعیین بھی کی، (اس روایت میں) انہوں نے دو اوقیہ، ایک درہم اور دو درہموں کا تذکرہ نہیں کیا اور کہا: آپ نے گائے کا حکم دیا تو اسے ذبح کیا گیا، پھر آپ نے اس کا گوشت تقسیم کر دیا۔"}],[4088,"عطاء نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے ان سے فرمایا : \" میں نے تمہارا اونٹ چار دینار ( جو سونے کے ایک اوقیہ کے برابر ہے ) میں لیا اور مدینہ تک اس کی پیٹھ ( پر سواری ) کا حق تمہارا ہے ۔","",{"u2":"عطاء نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: \"میں نے تمہارا اونٹ چار دینار (جو سونے کے ایک اوقیہ کے برابر ہے) میں لیا اور مدینہ تک اس کی پیٹھ (پر سواری) کا حق تمہارا ہے۔\""}],[4089,"امام مالک بن انس نے زید بن اسلم سے ، انہوں نے عطاء بن یسار سے اور انہوں نے سیدنا ابورافع رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی سے بعد میں ادائیگی ( سلف ) کے عوض ایک نو عمر اونٹ لیا ، آپ کے پاس زکاۃ کے اونٹ آئے تو آپ نے سیدنا ابورافع رضی اللہ عنہ کو حکم دیا کہ وہ اس آدمی کو اس کے نو عمر اونٹ کی ادائیگی کر دیں ۔ سیدنا ابورافع رضی اللہ عنہ لوٹ کر آپ کے پاس آئے اور عرض کی : میں نے تو ( آئے ہوئے ) ان اونٹوں میں ساتویں سال کا بہت اچھا اونٹ ہی پایا ہے ۔ تو آپ نے فرمایا : \" اسے وہی دے دو ، لوگوں میں سے بہترین وہ ہے جو ادا کرنے میں بہترین ہو ۔","",{"u2":"امام مالک بن انس نے زید بن اسلم سے، انہوں نے عطاء بن یسار سے اور انہوں نے سیدنا ابورافع رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی سے بعد میں ادائیگی (سلف) کے عوض ایک نو عمر اونٹ لیا، آپ کے پاس زکاۃ کے اونٹ آئے تو آپ نے سیدنا ابورافع رضی اللہ عنہ کو حکم دیا کہ وہ اس آدمی کو اس کے نو عمر اونٹ کی ادائیگی کر دیں۔ سیدنا ابورافع رضی اللہ عنہ لوٹ کر آپ کے پاس آئے اور عرض کی: میں نے تو (آئے ہوئے) ان اونٹوں میں ساتویں سال کا بہت اچھا اونٹ ہی پایا ہے۔ تو آپ نے فرمایا: \"اسے وہی دے دو، لوگوں میں سے بہترین وہ ہے جو ادا کرنے میں بہترین ہو۔\""}],[4090,"محمد بن جعفر سے روایت ہے ، میں نے زید بن اسلم سے سنا ، انہوں نے کہا : ہمیں عطاء بن یسار نے رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام ابورافع رضی اللہ عنہ سے خبر دی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ایک نو عمر اونٹ بعد کی ادائیگی پر لیا ۔ ۔ ۔ اسی کے مانند ، مگر انہوں نے کہا : \" اللہ کے بندوں میں سے بہترین وہ ہے جو ان میں سے ادائیگی میں بہترین ہے ۔","",{"u2":"محمد بن جعفر سے روایت ہے، میں نے زید بن اسلم سے سنا، انہوں نے کہا: ہمیں عطاء بن یسار نے رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام ابورافع رضی اللہ عنہ سے خبر دی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ایک نو عمر اونٹ بعد کی ادائیگی پر لیا۔۔۔اسی کے مانند، مگر انہوں نے کہا: \"اللہ کے بندوں میں سے بہترین وہ ہے جو ان میں سے ادائیگی میں بہترین ہے۔\""}],[4091,"شعبہ نے ہمیں سلمہ بن کہیل سے حدیث بیان کی ، انہوں نے ابوسلمہ سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ایک آدمی کا رسول اللہ صلی اللہ علیہ وسلم پر حق ( قرض ) تھا ، اس نے آپ کے ساتھ سخت کلامی کی تو نبی صلی اللہ علیہ وسلم کے ساتھیوں نے ( اسے جواب دینے کا ) ارادہ کیا تو نبی صلی اللہ علیہ وسلم نے فرمایا : \" جس شخص کا حق ہو ، وہ بات کرتا ہے ۔ \" اور آپ نے انہیں فرمایا : \" اس کے لیے ( اس کے اونٹ کا ) ہم عمر اونٹ خریدو اور وہ اسے دے دو ۔ \" انہوں نے عرض کی : ہمیں اس سے بہتر عمر کا اونٹ ہی ملتا ہے ۔ تو آپ نے فرمایا : \" وہی خریدو اور اسے دے دو ، بلاشبہ تم میں سے بہترین وہ ہے جو ادائیگی میں بہترین ہے ۔","",{"u2":"شعبہ نے ہمیں سلمہ بن کہیل سے حدیث بیان کی، انہوں نے ابوسلمہ سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ایک آدمی کا رسول اللہ صلی اللہ علیہ وسلم پر حق (قرض) تھا، اس نے آپ کے ساتھ سخت کلامی کی تو نبی صلی اللہ علیہ وسلم کے ساتھیوں نے (اسے جواب دینے کا) ارادہ کیا تو نبی صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص کا حق ہو، وہ بات کرتا ہے۔\" اور آپ نے انہیں فرمایا: \"اس کے لیے (اس کے اونٹ کا) ہم عمر اونٹ خریدو اور وہ اسے دے دو۔\" انہوں نے عرض کی: ہمیں اس سے بہتر عمر کا اونٹ ہی ملتا ہے۔ تو آپ نے فرمایا: \"وہی خریدو اور اسے دے دو، بلاشبہ تم میں سے بہترین وہ ہے جو ادائیگی میں بہترین ہے۔"}],[4092,"علی بن صالح نے سلمہ بن کہیل سے ، انہوں نے ابوسلمہ سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ایک نو عمر اونٹ ادھار لیا تو آپ نے اس سے بہتر جوان اونٹ دیا اور فرمایا : \" تم میں سے بہترین وہ ہے جو ادئیگی میں بہترین ہے","",{"u2":"علی بن صالح نے سلمہ بن کہیل سے، انہوں نے ابوسلمہ سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ایک نو عمر اونٹ ادھار لیا تو آپ نے اس سے بہتر جوان اونٹ دیا اور فرمایا: \"تم میں سے بہترین وہ ہے جو ادئیگی میں بہترین ہے"}],[4093,"سفیان نے ہمیں سلمہ بن کہیل سے حدیث بیان کی ، انہوں نے ابوسلمہ سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ایک آدمی آیا ، وہ رسول اللہ صلی اللہ علیہ وسلم سے اونٹ کا مطالبہ کر رہا تھا تو آپ نے فرمایا : \" اسے اس کے اونٹ سے بہتر عمر کا اونٹ دے دو ۔ \" اور فرمایا : \" تم میں سے بہتر وہ ہے جو ادائیگی میں بہتر ہو ۔","",{"u2":"سفیان نے ہمیں سلمہ بن کہیل سے حدیث بیان کی، انہوں نے ابوسلمہ سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ایک آدمی آیا، وہ رسول اللہ صلی اللہ علیہ وسلم سے اونٹ کا مطالبہ کر رہا تھا تو آپ نے فرمایا: \"اسے اس کے اونٹ سے بہتر عمر کا اونٹ دے دو۔\" اور فرمایا: \"تم میں سے بہتر وہ ہے جو ادائیگی میں بہتر ہو۔\""}],[4094,"سیدنا جابر رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : ایک غلام آیا ، اس نے ہجرت پر نبی صلی اللہ علیہ وسلم کے ساتھ بیعت کی جبکہ آپ کو پتہ نہیں چلا کہ وہ غلام ہے ۔ اس کا آقا اسے لینے کے لیے آیا تو نبی صلی اللہ علیہ وسلم نے اس سے فرمایا : \" یہ مجھے فروخت کر دو ۔ \" چنانچہ آپ نے دو سیاہ غلاموں کے عوض اسے خرید لیا ، پھر اس کے بعد آپ کسی سے بیعت نہ لیتے تھے یہاں تک کہ ( پہلے ) پوچھ لیتے : \" کیا وہ غلام ہے؟","",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: ایک غلام آیا، اس نے ہجرت پر نبی صلی اللہ علیہ وسلم کے ساتھ بیعت کی جبکہ آپ کو پتہ نہیں چلا کہ وہ غلام ہے۔ اس کا آقا اسے لینے کے لیے آیا تو نبی صلی اللہ علیہ وسلم نے اس سے فرمایا: \"یہ مجھے فروخت کر دو۔\" چنانچہ آپ نے دو سیاہ غلاموں کے عوض اسے خرید لیا، پھر اس کے بعد آپ کسی سے بیعت نہ لیتے تھے یہاں تک کہ (پہلے) پوچھ لیتے: \"کیا وہ غلام ہے؟\""}],[4095,"ابومعاویہ نے اعمش سے ، انہوں نے ابراہیم سے ، انہوں نے اسود سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ایک یہودی سے ادھار غلہ خریدا اور آپ نے اسے اپنی زرہ بطور رہن دی ۔","",{"u2":"ابومعاویہ نے اعمش سے، انہوں نے ابراہیم سے، انہوں نے اسود سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ایک یہودی سے ادھار غلہ خریدا اور آپ نے اسے اپنی زرہ بطور رہن دی۔"}],[4096,"عیسیٰ بن یونس نے ہمیں اعمش سے خبر دی ، انہوں نے ابراہیم سے ، انہوں نے اسود سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ایک یہودی سے غلہ خریدا اور آپ نے لوہے کی زرہ اس کے ہاں گروی رکھی ۔","",{"u2":") عیسیٰ بن یونس نے ہمیں اعمش سے خبر دی، انہوں نے ابراہیم سے، انہوں نے اسود سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ایک یہودی سے غلہ خریدا اور آپ نے لوہے کی زرہ اس کے ہاں گروی رکھی۔"}],[4097,"عبدالواحد بن زیاد نے ہمیں اعمش سے حدیث بیان کی ، انہوں نے کہا : ہم نے ابراہیم نخعی کے پاس بیع سلم میں رہن کی بات کی تو انہوں نے کہا : ہمیں اسود بن یزید نے سیدہ عائشہ رضی اللہ عنہا سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک یہودی سے آئندہ مقررہ وقت تک ادائیگی پر غلہ خریدا اور اپنی لوہے کی زرہ اس کے ہاں گروی رکھی ۔","",{"u2":"عبدالواحد بن زیاد نے ہمیں اعمش سے حدیث بیان کی، انہوں نے کہا: ہم نے ابراہیم نخعی کے پاس بیع سلم میں رہن کی بات کی تو انہوں نے کہا: ہمیں اسود بن یزید نے سیدہ عائشہ رضی اللہ عنہا سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک یہودی سے آئندہ مقررہ وقت تک ادائیگی پر غلہ خریدا اور اپنی لوہے کی زرہ اس کے ہاں گروی رکھی۔"}],[4098,"حفص بن غیاث نے ہمیں اعمش سے حدیث بیان کی ، انہوں نے ابراہیم سے روایت کی ، انہوں نے کہا : مجھے اسود نے سیدہ عائشہ رضی اللہ عنہا سے حدیث بیان کی اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔ ۔ ۔ اور انہوں نے \" لوہے کی زرہ \" کے الفاظ بیان کیے ۔","",{"u2":"حفص بن غیاث نے ہمیں اعمش سے حدیث بیان کی، انہوں نے ابراہیم سے روایت کی، انہوں نے کہا: مجھے اسود نے سیدہ عائشہ رضی اللہ عنہا سے حدیث بیان کی اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔۔۔ اور انہوں نے \"لوہے کی زرہ\" کے الفاظ بیان کیے۔"}],[4099,"یحییٰ بن یحییٰ اور عمرو ناقد نے ہمیں حدیث بیان کی ۔ ۔ الفاظ یحییٰ کے ہیں ، عمرو نے کہا : ہمیں حدیث بیان کی اور یحییٰ نے کہا : ہمیں خبر دی ۔ ۔ سفیان بن عیینہ نے ہمیں ابن ابی نجیح سے خبر دی ، انہوں نے عبداللہ بن کثیر سے ، انہوں نے ابومنہال سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : نبی صلی اللہ علیہ وسلم مدینہ تشریف لائے اور وہ لوگ پھلوں میں ایک دو سال تک کے لیے بیع سلف کرتے تھے تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" جو کھجور میں بیع سلف کرے تو وہ معلوم ماپ اور معلوم وزن میں معلوم مدت تک کے لیے کرے ۔","",{"u2":") یحییٰ بن یحییٰ اور عمرو ناقد نے ہمیں حدیث بیان کی۔۔ الفاظ یحییٰ کے ہیں، عمرو نے کہا: ہمیں حدیث بیان کی اور یحییٰ نے کہا: ہمیں خبر دی۔۔ سفیان بن عیینہ نے ہمیں ابن ابی نجیح سے خبر دی، انہوں نے عبداللہ بن کثیر سے، انہوں نے ابومنہال سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: نبی صلی اللہ علیہ وسلم مدینہ تشریف لائے اور وہ لوگ پھلوں میں ایک دو سال تک کے لیے بیع سلف کرتے تھے تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو کھجور میں بیع سلف کرے تو وہ معلوم ماپ اور معلوم وزن میں معلوم مدت تک کے لیے کرے۔\""}],[4100,"عبدالوارث نے ہمیں ابن ابی نجیح سے حدیث بیان کی ، کہا : ہمیں عبداللہ بن کثیر نے ابومنہال سے حدیث بیان کی ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم ( مدینہ ) تشریف لائے اور لوگ بیع سلف کرتے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا : \" جو بیع سلف کرے ، وہ معین ماپ اور معین وزن کے بغیر نہ کرے ۔","",{"u2":"عبدالوارث نے ہمیں ابن ابی نجیح سے حدیث بیان کی، کہا: ہمیں عبداللہ بن کثیر نے ابومنہال سے حدیث بیان کی، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم (مدینہ) تشریف لائے اور لوگ بیع سلف کرتے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"جو بیع سلف کرے، وہ معین ماپ اور معین وزن کے بغیر نہ کرے۔\""}],[4101,"یحییٰ بن یحییٰ ، ابوبکر بن ابی شیبہ اور اسماعیل سالم سب نے ( سفیان ) بن عیینہ سے ، انہوں نے ابن ابی نجیح سے اسی سند کے ساتھ عبدالوارث کی حدیث کی طرح روایت بیان کی اور انہوں نے بھی \" معین مدت تک \" کے الفاظ ذکر نہیں کیے ۔","",{"u2":"یحییٰ بن یحییٰ، ابوبکر بن ابی شیبہ اور اسماعیل سالم سب نے (سفیان) بن عیینہ سے، انہوں نے ابن ابی نجیح سے اسی سند کے ساتھ عبدالوارث کی حدیث کی طرح روایت بیان کی اور انہوں نے بھی \"معین مدت تک\" کے الفاظ ذکر نہیں کیے۔"}],[4102,"وکیع اور عبدالرحمان بن مہدی دونوں نے سفیان ( ثوری ) سے ، انہوں نے ابن ابی نجیح سے انہی کی سند کے ساتھ ابن عیینہ کی حدیث کی طرح روایت بیان کی اور انہوں نے اس میں \" معین مدت تک \" کے الفاظ ( بھی ) بیان کیے ۔","",{"u2":"وکیع اور عبدالرحمان بن مہدی دونوں نے سفیان (ثوری) سے، انہوں نے ابن ابی نجیح سے انہی کی سند کے ساتھ ابن عیینہ کی حدیث کی طرح روایت بیان کی اور انہوں نے اس میں \"معین مدت تک\" کے الفاظ (بھی) بیان کیے۔"}],[4103,"سلیمان بن بلال نے ہمیں یحییٰ بن سعید سے حدیث بیان کی ، انہوں نے کہا : سعید بن مسیب حدیث بیان کرتے تھے کہ سیدنا معمر رضی اللہ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے ذخیرہ اندوزی کی وہ گناہ گار ہے ۔ \" سعید سے کہا گیا : آپ خود ( کھانے کی بنیادی چیزوں کے سوا دوسری اشیاء میں ) ذخیرہ اندوزی کرتے ہیں؟ سعید نے کہا : سیدنا معمر رضی اللہ عنہ جو یہ حدیث بیان کرتے تھے ، وہ بھی ( اس طرح کی ) ذخیرہ اندوزی کرتے تھے ۔","",{"u2":"سلیمان بن بلال نے ہمیں یحییٰ بن سعید سے حدیث بیان کی، انہوں نے کہا: سعید بن مسیب حدیث بیان کرتے تھے کہ سیدنا معمر رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے ذخیرہ اندوزی کی وہ گناہ گار ہے۔\" سعید سے کہا گیا: آپ خود (کھانے کی بنیادی چیزوں کے سوا دوسری اشیاء میں) ذخیرہ اندوزی کرتے ہیں؟ سعید نے کہا: سیدنا معمر رضی اللہ عنہ جو یہ حدیث بیان کرتے تھے، وہ بھی (اس طرح کی) ذخیرہ اندوزی کرتے تھے۔"}],[4104,"محمد بن عجلان نے محمد بن عمرو بن عطاء سے ، انہوں نے سعید بن مسیب سے ، انہوں نے سیدنا معمر بن عبداللہ رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" گناہ گار کے سوا کوئی اور شخص ذخیرہ اندوزی نہیں کرتا ۔","",{"u2":"محمد بن عجلان نے محمد بن عمرو بن عطاء سے، انہوں نے سعید بن مسیب سے، انہوں نے سیدنا معمر بن عبداللہ رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"گناہ گار کے سوا کوئی اور شخص ذخیرہ اندوزی نہیں کرتا۔\""}],[4105,"عمرو بن یحییٰ نے محمد بن عمرو سے ، انہوں نے سعید بن مسیب سے اور انہوں نے بنو عدی بن کعب کے ایک فرد سیدنا معمر بن ابی معمر سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ۔ ۔ آگے یحییٰ سے سلیمان بن بلال کی روایت کردہ حدیث کی طرح بیان کیا ۔","",{"u2":"عمرو بن یحییٰ نے محمد بن عمرو سے، انہوں نے سعید بن مسیب سے اور انہوں نے بنو عدی بن کعب کے ایک فرد حضرت معمر بن ابی معمر سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا۔۔ آگے یحییٰ سے سلیمان بن بلال کی روایت کردہ حدیث کی طرح بیان کیا۔"}],[4106,"سیدنا ابوہریرہ رضی اللہ عنہ نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : \" قسم سامان کو فروغ دینے والی ، ( بعد ازاں ) نفع کو مٹانے والی ہے ۔","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: \"قسم سامان کو فروغ دینے والی، (بعد ازاں) نفع کو مٹانے والی ہے۔\""}],[4107,"سیدنا ابوقتادہ انصاری رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : \" بیع میں زیادہ قسمیں کھانے سے بچو کیونکہ وہ ( پہلے بیع کو ) فروغ دیتی ہے ، پھر ( نفع کو ) مٹا دیتی ہے ۔","",{"u2":"سیدنا ابوقتادہ انصاری رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: \"بیع میں زیادہ قسمیں کھانے سے بچو کیونکہ وہ (پہلے بیع کو) فروغ دیتی ہے، پھر (نفع کو) مٹا دیتی ہے۔\""}],[4108,"ابوخثیمہ نے ہمیں ابوزبیر سے خبر دی ، اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس شخص کا گھر میں یا باغ میں کوئی شریک ہو تو اسے حق نہیں کہ اسے بیچے ، یہاں تک کہ اپنے شریک کو بتائے ، پھر اگر وہ راضی ہو تو ( اسے ) لے لے اور اگر ناپسند کرے تو چھوڑ دے ۔ \" ( اور وہ دوسرے کو بیچ دیا جائے ۔)","",{"u2":"ابوخثیمہ نے ہمیں ابوزبیر سے خبر دی، اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص کا گھر میں یا باغ میں کوئی شریک ہو تو اسے حق نہیں کہ اسے بیچے، یہاں تک کہ اپنے شریک کو بتائے، پھر اگر وہ راضی ہو تو (اسے) لے لے اور اگر ناپسند کرے تو چھوڑ دے۔\" (اور وہ دوسرے کو بیچ دیا جائے۔)"}],[4109,"عبداللہ بن ادریس نے ہمیں حدیث بیان کی ، کہا : ہمیں ابن جریج نے ابوزبیر سے حدیث بیان کی ، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہر مشترک جائیداد پر ، جو تقسیم نہ ہوئی ہو شفعہ کا فیصلہ فرمایا ، وہ گھر ہو یا باغ ہو اس کے لیے ( جو اس کا شریک ملکیت ہے ) اسے بیچنا جائز نہیں یہاں تک کہ وہ اپنے شریک کو بتائے اگر وہ ( شریک ) چاہے تو لے لے اور اگر چاہے تو چھوڑ دے ۔ اگر اس نے ( اسے ) فروخت کر دیا اور اس ( شریک ) کو اطلاق نہ دی تو یہی اس کا زیادہ حقدار ہو گا ۔","",{"u2":"عبداللہ بن ادریس نے ہمیں حدیث بیان کی، کہا: ہمیں ابن جریج نے ابوزبیر سے حدیث بیان کی، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہر مشترک جائیداد پر، جو تقسیم نہ ہوئی ہو شفعہ کا فیصلہ فرمایا، وہ گھر ہو یا باغ ہو اس کے لیے (جو اس کا شریک ملکیت ہے) اسے بیچنا جائز نہیں یہاں تک کہ وہ اپنے شریک کو بتائے اگر وہ (شریک) چاہے تو لے لے اور اگر چاہے تو چھوڑ دے۔ اگر اس نے (اسے) فروخت کر دیا اور اس (شریک) کو اطلاق نہ دی تو یہی اس کا زیادہ حقدار ہو گا۔"}],[4110,"ابن وہب نے ہمیں ابن جریج سے خبر دی کہ انہیں ابوزبیر نے بتایا کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ہر مشترک جائیداد ، زمین ، گھر یا باغ میں شفعہ ہے ۔ ( کسی ایک شریک کے لیے ) اسے فروخت کرنا درست نہیں جب تک کہ وہ اپنے شریک کو پیشکش ( نہ ) کرے وہ ( چاہے تو ) اسے لے لے یا چھوڑ دے ۔ اگر وہ ایسا نہ کرے تو اس کا شریک ہی اس کا زیادہ حقدار ہے جب تک کہ اسے بتا نہ دے ۔","",{"u2":"ابن وہب نے ہمیں ابن جریج سے خبر دی کہ انہیں ابوزبیر نے بتایا کہ انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر مشترک جائیداد، زمین، گھر یا باغ میں شفعہ ہے۔ (کسی ایک شریک کے لیے) اسے فروخت کرنا درست نہیں جب تک کہ وہ اپنے شریک کو پیشکش (نہ) کرے وہ (چاہے تو) اسے لے لے یا چھوڑ دے۔ اگر وہ ایسا نہ کرے تو اس کا شریک ہی اس کا زیادہ حقدار ہے جب تک کہ اسے بتا نہ دے۔\""}],[4111,"سیدنا ابوہریرہ ؓ سے روایت ہے ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ”کوئی تم سے اپنے ہمسایہ کو اپنی دیوار میں لکڑی گاڑنے سے منع نہ کرے ۔ “ (کیونکہ یہ مروت کے خلاف ہے اور اپنا کوئی نقصان نہیں بلکہ اگر ہمسایہ ادھر چھت ڈالے تو اور دیوار کی حفاظت ہے) سیدنا ابوہریرہ ؓ کہتے تھے (لوگوں سے) میں دیکھتا ہوں تم اس حدیث سے دل چراتے ہو ، قسم اللہ کی ! میں اس کو بیان کروں گا تم لوگوں میں ۔","",{"u2":") امام مالک نے ابن شہاب سے، انہوں نے اعرج سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی اپنے پڑوسی کو اپنی دیوار میں لکڑی (شہتیر وغیرہ) رکھنے سے نہ روکے۔\"\nکہا: پھر سیدنا ابوہریرہ رضی اللہ عنہ کہتے: کیا وجہ ہے کہ میں تمہیں اس سے اعراض کرتے ہوئے دیکھتا ہوں؟ اللہ کی قسم! میں اس بات کو تمہارے کندھوں کے درمیان (تمہارے منہ پر) دے ماروں گا۔"}],[4112,"سفیان بن عیینہ ، یونس اور معمر سب نے زہری سے اسی سند کے ساتھ اسی طرح روایت کی ۔","",{"u2":"سفیان بن عیینہ، یونس اور معمر سب نے زہری سے اسی سند کے ساتھ اسی طرح روایت کی۔"}],[4113,"عباس بن سہل بن سعد ساعدی نے سیدنا سعید بن زید بن عمرو بن نفیل رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس کسی نے زمین کی ایک بالشت ( بھی ) ظلم کرتے ہوئے کاٹ لی ، قیامت کے دن اللہ تعالیٰ اسے سات زمینوں سے اس کا طوق ( بنا کر ) پہنائے گا ۔","",{"u2":"عباس بن سہل بن سعد ساعدی نے حضرت سعید بن زید بن عمرو بن نفیل رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کسی نے زمین کی ایک بالشت (بھی) ظلم کرتے ہوئے کاٹ لی، قیامت کے دن اللہ تعالیٰ اسے سات زمینوں سے اس کا طوق (بنا کر) پہنائے گا۔\""}],[4114,"عمر بن محمد کے والد ( محمد بن زید ) نے سیدنا سعید بن زید بن عمرو بن نفیل رضی اللہ عنہ سے حدیث بیان کی کہ ارویٰ نے ان کے ساتھ گھر کے کسی حصے کے بارے میں جھگڑا کیا تو انہوں نے کہا : اسے اور گھر کو چھوڑ دو ، ( جو چاہے کرتی رہے ) میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا ، آپ فرما رہے تھے : \"\" جس نے حق کے بغیر ایک بالشت زمین بھی حاصل کی ، قیامت کے دن وہ سات زمینوں ( تک ) اس کی گردن کا طوق بنا دی جائے گی ۔ \"\" ( پھر اس کی ایذا رسانی سے تنگ آ کر انہوں نے دعا کی : ) اے اللہ! اگر یہ جھوٹی ہے تو اس کی آنکھوں کو اندھا کر دے اور اس کے گھر ہی میں اس کی قبر بنا دے ۔ ( محمد بن زید نے ) کہا : میں نے اس عورت کو دیکھا وہ اندھی ہو گئی تھی ، دیواریں ٹٹولتی پھرتی تھی اور کہتی تھی : مجھے سعید بن زید کی بددعا لگ گئی ہے ۔ ایک مرتبہ وہ گھر میں چل رہی تھی ، گھر میں کنویں کے پاس سے گزری تو اس میں گزر گئی اور وہی کنواں اس کی قبر بن گیا ۔","",{"u2":"عمر بن محمد کے والد (محمد بن زید) نے حضرت سعید بن زید بن عمرو بن نفیل رضی اللہ عنہ سے حدیث بیان کی کہ ارویٰ نے ان کے ساتھ گھر کے کسی حصے کے بارے میں جھگڑا کیا تو انہوں نے کہا: اسے اور گھر کو چھوڑ دو، (جو چاہے کرتی رہے) میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا، آپ فرما رہے تھے: \"جس نے حق کے بغیر ایک بالشت زمین بھی حاصل کی، قیامت کے دن وہ سات زمینوں (تک) اس کی گردن کا طوق بنا دی جائے گی۔\" (پھر اس کی ایذا رسانی سے تنگ آ کر انہوں نے دعا کی:) اے اللہ! اگر یہ جھوٹی ہے تو اس کی آنکھوں کو اندھا کر دے اور اس کے گھر ہی میں اس کی قبر بنا دے۔\n(محمد بن زید نے) کہا: میں نے اس عورت کو دیکھا وہ اندھی ہو گئی تھی، دیواریں ٹٹولتی پھرتی تھی اور کہتی تھی: مجھے سعید بن زید کی بددعا لگ گئی ہے۔ ایک مرتبہ وہ گھر میں چل رہی تھی، گھر میں کنویں کے پاس سے گزری تو اس میں گزر گئی اور وہی کنواں اس کی قبر بن گیا۔"}],[4115,"حماد بن زید نے ہمیں ہشام بن عروہ سے حدیث بیان کی ، انہوں نے اپنے والد سے روایت کی کہ ارویٰ بنت اویس نے سعید بن زید رضی اللہ عنہ کے خلاف دعویٰ کیا کہ انہوں نے اس کی کچھ زمین پر قبضہ کر لیا ہے اور مروان بن حکم کے پاس مقدمہ لے کر گئی تو سیدنا سعید رضی اللہ عنہ نے کہا : کیا میں اس بات کے بعد بھی اس کی زمین کے کسی حصے پر قبضہ کر سکتا ہوں جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنی؟ اس ( مروان ) نے کہا : آپ نے رسول اللہ صلی اللہ علیہ وسلم سے کیا سنا؟ انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : \" جس نے ( عام یا کسی کی ) زمین میں سے ایک بالشت بھی ظلم سے حاصل کی اسے سات زمینوں تک کا طوق پہنایا جائے گا ۔ \" تو مروان نے ان سے کہا : اس کے بعد میں آپ سے کسی شہادت کا مطالبہ نہیں کروں گا ۔ اس کے بعد انہوں ( سعید ) نے کہا : اے اللہ! اگر یہ جھوٹی ہے تو اس کی آنکھوں کو اندھا کر دے اور اسے اس کی زمین ہی میں ہلاک کر دے ۔ ( عروہ نے ) کہا : وہ ( اس وقت تک ) نہ مری یہاں تک کہ اس کی بینائی ختم ہو گئی ، پھر ایک مرتبہ وہ اپنی زمین میں چل رہی تھی کہ ایک گڑھے میں جا گری اور مر گئی ۔","",{"u2":"حماد بن زید نے ہمیں ہشام بن عروہ سے حدیث بیان کی، انہوں نے اپنے والد سے روایت کی کہ ارویٰ بنت اویس نے سعید بن زید رضی اللہ عنہ کے خلاف دعویٰ کیا کہ انہوں نے اس کی کچھ زمین پر قبضہ کر لیا ہے اور مروان بن حکم کے پاس مقدمہ لے کر گئی تو سیدنا سعید رضی اللہ عنہ نے کہا: کیا میں اس بات کے بعد بھی اس کی زمین کے کسی حصے پر قبضہ کر سکتا ہوں جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنی؟ اس (مروان) نے کہا: آپ نے رسول اللہ صلی اللہ علیہ وسلم سے کیا سنا؟ انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: \"جس نے (عام یا کسی کی) زمین میں سے ایک بالشت بھی ظلم سے حاصل کی اسے سات زمینوں تک کا طوق پہنایا جائے گا۔\" تو مروان نے ان سے کہا: اس کے بعد میں آپ سے کسی شہادت کا مطالبہ نہیں کروں گا۔ اس کے بعد انہوں (سعید) نے کہا: اے اللہ! اگر یہ جھوٹی ہے تو اس کی آنکھوں کو اندھا کر دے اور اسے اس کی زمین ہی میں ہلاک کر دے۔ (عروہ نے) کہا: وہ (اس وقت تک) نہ مری یہاں تک کہ اس کی بینائی ختم ہو گئی، پھر ایک مرتبہ وہ اپنی زمین میں چل رہی تھی کہ ایک گڑھے میں جا گری اور مر گئی۔"}],[4116,"یحییٰ بن زکریا بن ابی زائدہ نے ہمیں ہشام سے حدیث بیان کی ، انہوں نے اپنے والد سے اور انہوں نے سیدنا سعید بن زید رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں نے نبی صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : \" جس نے زمین میں سے ایک بالشت بھی ظلم کرتے ہوئے حاصل کی قیامت کے دن اسے سات زمینوں سے طوق پہنایا جائے گا ۔","",{"u2":"یحییٰ بن زکریا بن ابی زائدہ نے ہمیں ہشام سے حدیث بیان کی، انہوں نے اپنے والد سے اور انہوں نے سیدنا سعید بن زید رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں نے نبی صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: \"جس نے زمین میں سے ایک بالشت بھی ظلم کرتے ہوئے حاصل کی قیامت کے دن اسے سات زمینوں سے طوق پہنایا جائے گا۔\""}],[4117,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی شخص حق کے بغیر زمین کی ایک بالشت ( بھی ) حاصل نہیں کرتا مگر قیامت کے دن اللہ تعالیٰ اسے سات زمینوں تک کا طوق پہنائے گا ۔","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی شخص حق کے بغیر زمین کی ایک بالشت (بھی) حاصل نہیں کرتا مگر قیامت کے دن اللہ تعالیٰ اسے سات زمینوں تک کا طوق پہنائے گا۔\""}],[4118,"حرب بن شداد نے ہمیں حدیث بیان کی ، کہا : ہمیں یحییٰ بن ابی کثیر نے محمد بن ابراہیم سے حدیث بیان کی ، انہیں ابوسلمہ نے حدیث بیان کی کہ ان کے اور ان کی قوم کے درمیان ایک زمین کے بارے میں جھگڑا تھا ، وہ سیدہ عائشہ رضی اللہ عنہا کی خدمت میں حاضر ہوئے اور ان کے سامنے اس بات کا تذکرہ کیا تو انہوں نے کہا : ابوسلمہ! زمین سے کنارہ کش ہو جاؤ ، کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے : \" جس نے ایک بالشت برابر زمین پر بھی ظلم سے قبضہ کیا ، اسے سات زمینوں کا طوق پہنایا جائے گا ۔","",{"u2":"حرب بن شداد نے ہمیں حدیث بیان کی، کہا: ہمیں یحییٰ بن ابی کثیر نے محمد بن ابراہیم سے حدیث بیان کی، انہیں ابوسلمہ نے حدیث بیان کی کہ ان کے اور ان کی قوم کے درمیان ایک زمین کے بارے میں جھگڑا تھا، وہ سیدہ عائشہ رضی اللہ عنہا کی خدمت میں حاضر ہوئے اور ان کے سامنے اس بات کا تذکرہ کیا تو انہوں نے کہا: ابوسلمہ! زمین سے کنارہ کش ہو جاؤ، کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"جس نے ایک بالشت برابر زمین پر بھی ظلم سے قبضہ کیا، اسے سات زمینوں کا طوق پہنایا جائے گا۔\""}],[4119,"ابان نے ہمیں حدیث بیان کی ، کہا : ہمیں یحییٰ نے حدیث بیان کی کہ انہیں محمد بن ابراہیم نے حدیث بیان کی ، انہیں ابوسلمہ نے حدیث بیان کی کہ وہ سیدہ عائشہ رضی اللہ عنہا کی خدمت میں حاضر ہوئے ۔ ۔ آگے اسی کے مانند بیان کیا ۔","",{"u2":"ابان نے ہمیں حدیث بیان کی، کہا: ہمیں یحییٰ نے حدیث بیان کی کہ انہیں محمد بن ابراہیم نے حدیث بیان کی، انہیں ابوسلمہ نے حدیث بیان کی کہ وہ سیدہ عائشہ رضی اللہ عنہا کی خدمت میں حاضر ہوئے۔۔ آگے اسی کے مانند بیان کیا۔"}],[4120,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \" جب تمہارا راستے ( کی پیمائش ) کے بارے میں اختلاف ہو جائے تو اس ( راستے ) کی چوڑائی سات ہاتھ رکھی جائے ۔","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"جب تمہارا راستے (کی پیمائش) کے بارے میں اختلاف ہو جائے تو اس (راستے) کی چوڑائی سات ہاتھ رکھی جائے۔\""}],[4121,"سیدنا اسامہ بن زید رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \" مسلمان کافر کا وارث نہیں بنتا ، نہ کافر مسلمان کا وارث بنتا ہے ۔","",{"u2":"سیدنا اسامہ بن زید رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان کافر کا وارث نہیں بنتا، نہ کافر مسلمان کا وارث بنتا ہے۔\""}],[4122,"وہیب نے ہمیں ابن طاوس سے حدیث بیان کی ، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" مقررہ حصے حقداروں کو دو اور جو بچ جائے وہ سب سے قریبی رشتہ رکھنے والے مرد کے لیے ہے ۔","",{"u2":") وہیب نے ہمیں ابن طاوس سے حدیث بیان کی، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مقررہ حصے حقداروں کو دو اور جو بچ جائے وہ سب سے قریبی رشتہ رکھنے والے مرد کے لیے ہے۔\""}],[4123,"روح بن قاسم نے باقی ماندہ سابقہ سند کے ساتھ سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" مقررہ حصے ان کے حقداروں کو دو اور ان سے جو باقی بچے وہ سب سے قریبی مرد کا ہے ۔","",{"u2":"روح بن قاسم نے باقی ماندہ سابقہ سند کے ساتھ سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"مقررہ حصے ان کے حقداروں کو دو اور ان سے جو باقی بچے وہ سب سے قریبی مرد کا ہے۔\""}],[4124,"معمر نے ہمیں ابن طاوس سے باقی ماندہ سابقہ سند سے روایت کی : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" مال کو اللہ کی کتاب کی رو سے مقررہ کردہ حصے والوں کے درمیان تقسیم کرو اور جو ان حصوں سے بچ جائے وہ سب سے قریبی مرد کے لیے ہے ۔","",{"u2":"معمر نے ہمیں ابن طاوس سے باقی ماندہ سابقہ سند سے روایت کی: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مال کو اللہ کی کتاب کی رو سے مقررہ کردہ حصے والوں کے درمیان تقسیم کرو اور جو ان حصوں سے بچ جائے وہ سب سے قریبی مرد کے لیے ہے۔\""}],[4125,"یحییٰ بن ایوب نے ابن طاوس سے اسی سند کے ساتھ وہیب اور روح بن قاسم کی حدیث کے ہم معنی روایت بیان کی","",{"u2":"یحییٰ بن ایوب نے ابن طاوس سے اسی سند کے ساتھ وہیب اور روح بن قاسم کی حدیث کے ہم معنی روایت بیان کی"}],[4126,"سفیان بن عیینہ نے ہمیں محمد بن منکدر سے حدیث بیان کی : انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، انہوں نے کہا : میں بیمار ہوا تو رسول اللہ صلی اللہ علیہ وسلم اور سیدنا ابوبکر رضی اللہ عنہ میری عیادت کرنے کے لیے پیدل چل کر تشریف لائے ، مجھ پر غشی ہو گئی تو رسول اللہ صلی اللہ علیہ وسلم نے وضو کیا ، پھر اپنے وضو کا پانی مجھ پر ڈالا تو مجھے افاقہ ہو گیا ، میں نے عرض کی : اے اللہ کے رسول! میں اپنے مال کے بارے میں کیسے فیصلہ کروں؟ ( اس کو ایسے ہی چھوڑ جاؤں یا وصیت کروں ، وصیت کروں تو کتنے حصے میں؟ اس وقت سیدنا جابر رضی اللہ عنہ کے والد زندہ تھے نہ اور کوئی بیٹا تھا ۔ ) آپ نے مجھے جواب نہ دیا حتی کہ وراثت کی آیت نازل ہوئی : \" وہ آپ سے فتویٰ مانتے ہیں ، کہہ دیجئے : اللہ تمہیں کلالہ کے بارے میں فتویٰ دیتا ہے ۔","",{"u2":"سفیان بن عیینہ نے ہمیں محمد بن منکدر سے حدیث بیان کی: انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا، انہوں نے کہا: میں بیمار ہوا تو رسول اللہ صلی اللہ علیہ وسلم اور سیدنا ابوبکر رضی اللہ عنہ میری عیادت کرنے کے لیے پیدل چل کر تشریف لائے، مجھ پر غشی ہو گئی تو رسول اللہ صلی اللہ علیہ وسلم نے وضو کیا، پھر اپنے وضو کا پانی مجھ پر ڈالا تو مجھے افاقہ ہو گیا، میں نے عرض کی: اے اللہ کے رسول! میں اپنے مال کے بارے میں کیسے فیصلہ کروں؟ (اس کو ایسے ہی چھوڑ جاؤں یا وصیت کروں، وصیت کروں تو کتنے حصے میں؟ اس وقت سیدنا جابر رضی اللہ عنہ کے والد زندہ تھے نہ اور کوئی بیٹا تھا۔) آپ نے مجھے جواب نہ دیا حتی کہ وراثت کی آیت نازل ہوئی: \"وہ آپ سے فتویٰ مانتے ہیں، کہہ دیجئے: اللہ تمہیں کلالہ کے بارے میں فتویٰ دیتا ہے۔\""}],[4127,"ابن جریج نے ہمیں حدیث بیان کی ، انہوں نے کہا : مجھے ابن منکدر نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے خبر دی ، انہوں نے کہا : نبی صلی اللہ علیہ وسلم اور سیدنا ابوبکر رضی اللہ عنہ نے بنوسلمہ ( کے علاقے ) میں پیدل چل کر میری عیادت کی ، آپ نے مجھے اس حالت میں پایا کہ میں کچھ سمجھ نہیں پا رہا تھا ، آپ نے پانی منگوایا ، وضو کیا ، پھر اس میں سے مجھ پر چھینٹے مارے تو مجھے افاقہ ہو گیا ، میں نے کہا : اللہ کے رسول! میں اپنے مال میں کیا کروں؟ تو ( یہ آیت ) نازل ہوئی : \" اللہ تمہیں تمہاری اولاد کے بارے میں تاکیدی حکم دیتا ہے ، مرد کے لیے دو عورتوں کے حصے کے برابر ہے ۔","",{"u2":"ابن جریج نے ہمیں حدیث بیان کی، انہوں نے کہا: مجھے ابن منکدر نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے خبر دی، انہوں نے کہا: نبی صلی اللہ علیہ وسلم اور سیدنا ابوبکر رضی اللہ عنہ نے بنوسلمہ (کے علاقے) میں پیدل چل کر میری عیادت کی، آپ نے مجھے اس حالت میں پایا کہ میں کچھ سمجھ نہیں پا رہا تھا، آپ نے پانی منگوایا، وضو کیا، پھر اس میں سے مجھ پر چھینٹے مارے تو مجھے افاقہ ہو گیا، میں نے کہا: اللہ کے رسول! میں اپنے مال میں کیا کروں؟ تو (یہ آیت) نازل ہوئی: \"اللہ تمہیں تمہاری اولاد کے بارے میں تاکیدی حکم دیتا ہے، مرد کے لیے دو عورتوں کے حصے کے برابر ہے۔\""}],[4128,"سفیان ( ثوری ) نے ہمیں حدیث بیان کی ، انہوں نے کہا : میں نے محمد بن منکدر سے سنا ، انہوں نے کہا : میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : میں بیمار تھا تو رسول اللہ صلی اللہ علیہ وسلم نے میری عیادت کی ، آپ کے ساتھ سیدنا ابوبکر رضی اللہ عنہ بھی تھے ، دونوں پیدل چل کر تشریف لائے ۔ آپ نے مجھے ( اس حالت میں ) پایا کہ مجھ پر غشی طاری تھی ، رسول اللہ صلی اللہ علیہ وسلم نے وضو کیا ، پھر اپنے وضو کا بچا ہوا پانی مجھ پر ڈالا ، میں ہوش میں آ گیا تو دیکھا سامنے رسول اللہ صلی اللہ علیہ وسلم تشریف فرما ہیں ، میں نے عرض کی : اے اللہ کے رسول! میں اپنے مال کے بارے میں کیا کروں؟ کہا : آپ نے مجھے کوئی جواب نہ دیا یہاں تک کہ وراثت کی آیت نازل ہوئی ۔","",{"u2":"سفیان (ثوری) نے ہمیں حدیث بیان کی، انہوں نے کہا: میں نے محمد بن منکدر سے سنا، انہوں نے کہا: میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: میں بیمار تھا تو رسول اللہ صلی اللہ علیہ وسلم نے میری عیادت کی، آپ کے ساتھ سیدنا ابوبکر رضی اللہ عنہ بھی تھے، دونوں پیدل چل کر تشریف لائے۔ آپ نے مجھے (اس حالت میں) پایا کہ مجھ پر غشی طاری تھی، رسول اللہ صلی اللہ علیہ وسلم نے وضو کیا، پھر اپنے وضو کا بچا ہوا پانی مجھ پر ڈالا، میں ہوش میں آ گیا تو دیکھا سامنے رسول اللہ صلی اللہ علیہ وسلم تشریف فرما ہیں، میں نے عرض کی: اے اللہ کے رسول! میں اپنے مال کے بارے میں کیا کروں؟ کہا: آپ نے مجھے کوئی جواب نہ دیا یہاں تک کہ وراثت کی آیت نازل ہوئی۔"}],[4129,"بہز نے ہمیں حدیث بیان کی : شعبہ نے ہمیں حدیث بیان کی : مجھے محمد بن منکدر نے خبر دی ، انہوں نے کہا : میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے جبکہ میں بیمار تھا اور بے ہوش تھا ، آپ نے وضو کیا تو لوگوں نے آپ کے وضو کا بچا ہوا پانی مجھ پر ڈالا ، ( اس پر ) مجھے افاقہ ہوا تو میں نے کہا : اے اللہ کے رسول! میرا وارث کلالہ بنے گا ۔ ( اس وقت سیدنا جابر رضی اللہ عنہ کی بہنیں ہی تھیں جو وارث بنتی تھیں ) اس پر وراثت کی آیت نازل ہوئی ۔ میں نے محمد بن منکدر سے پوچھا : ( «يَسْتَفْتُونَكَ قُلِ» اللَّـهُ «يُفْتِيكُمْ فِي الْكَلَالَةِ» ۚ ) ( والی آیت ) ؟ انہوں نے کہا : اسی طرح ( سیدنا جابر رضی اللہ عنہ کے سوال پر ) نازل کی گئی ۔","",{"u2":"بہز نے ہمیں حدیث بیان کی: شعبہ نے ہمیں حدیث بیان کی: مجھے محمد بن منکدر نے خبر دی، انہوں نے کہا: میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے جبکہ میں بیمار تھا اور بے ہوش تھا، آپ نے وضو کیا تو لوگوں نے آپ کے وضو کا بچا ہوا پانی مجھ پر ڈالا، (اس پر) مجھے افاقہ ہوا تو میں نے کہا: اے اللہ کے رسول! میرا وارث کلالہ بنے گا۔ (اس وقت سیدنا جابر رضی اللہ عنہ کی بہنیں ہی تھیں جو وارث بنتی تھیں) اس پر وراثت کی آیت نازل ہوئی۔ میں نے محمد بن منکدر سے پوچھا: (یَسْتَفْتُونَکَ قُلِ اللَّـہُ یُفْتِیکُمْ فِی الْکَلَالَۃِ ۚ) (والی آیت)؟ انہوں نے کہا: اسی طرح (سیدنا جابر رضی اللہ عنہ کے سوال پر) نازل کی گئی۔"}],[4130,"نضر بن شمیل ، ابو عامر عقدی اور وہب بن جریر سب نے شعبہ سے اسی سند کے ساتھ حدیث بیان کی ، وہب بن جریر کی حدیث میں ہے : تو آیت فرائض نازل ہوئی ۔ اور ان میں سے کسی کی حدیث میں ابن منکدر سے شعبہ کے سوال کا تذکرہ نہیں ہے ۔","",{"u2":"نضر بن شمیل، ابو عامر عقدی اور وہب بن جریر سب نے شعبہ سے اسی سند کے ساتھ حدیث بیان کی، وہب بن جریر کی حدیث میں ہے: تو آیت فرائض نازل ہوئی۔ اور ان میں سے کسی کی حدیث میں ابن منکدر سے شعبہ کے سوال کا تذکرہ نہیں ہے۔"}],[4131,"ہشام نے ہمیں حدیث بیان کی : ہمیں قتادہ نے سالم بن ابی جعد سے حدیث بیان کی ، انہوں نے معدان بن ابی طلحہ سے روایت کی کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے جمعہ کے دن خطبہ دیا ، انہوں نے نبی صلی اللہ علیہ وسلم کا تذکرہ کیا اور سیدنا ابوبکر رضی اللہ عنہ کا تذکرہ کیا ، پھر کہا : میں اپنے بعد کوئی ایسی چیز نہیں چھوڑ رہا جو میرے ہاں کلالہ سے زیادہ اہم ہو ، میں نے رسول اللہ صلی اللہ علیہ وسلم سے کسی چیز کے بارے میں اتنی مراجعت نہیں کی جتنی کلالہ کے بارے میں کی ، اور آپ نے بھی مجھ سے کسی چیز کے بارے میں اتنی شدت اختیار نہیں فرمائی جتنی کلالہ کے بارے میں فرمائی حتی کہ آپ نے اپنی انگلی میرے سینے میں چبھوئی اور فرمایا : \" اے عمر! تمہیں موسم گرما ( میں نازل ہونے ) والی آیت کافی نہیں جو سورہ نساء کے آخر میں ہے؟ ( جس سے مسئلہ واضح ہو گیا ہے ) \" اور میں ( عمر ) اگر زندہ رہا تو اس کے بارے میں ایسا واضح فیصلہ کروں گا جس ( کو دیکھتے ہوئے ) ایسا شخص ( بھی ) فیصلہ کر سکے گا جو قرآن پڑھتا ( اور سمجھتا ) ہے اور وہ بھی جو قرآن نہیں پڑھتا ۔","",{"u2":"ہشام نے ہمیں حدیث بیان کی: ہمیں قتادہ نے سالم بن ابی جعد سے حدیث بیان کی، انہوں نے معدان بن ابی طلحہ سے روایت کی کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے جمعہ کے دن خطبہ دیا، انہوں نے نبی صلی اللہ علیہ وسلم کا تذکرہ کیا اور سیدنا ابوبکر رضی اللہ عنہ کا تذکرہ کیا، پھر کہا: میں اپنے بعد کوئی ایسی چیز نہیں چھوڑ رہا جو میرے ہاں کلالہ سے زیادہ اہم ہو، میں نے رسول اللہ صلی اللہ علیہ وسلم سے کسی چیز کے بارے میں اتنی مراجعت نہیں کی جتنی کلالہ کے بارے میں کی، اور آپ نے بھی مجھ سے کسی چیز کے بارے میں اتنی شدت اختیار نہیں فرمائی جتنی کلالہ کے بارے میں فرمائی حتی کہ آپ نے اپنی انگلی میرے سینے میں چبھوئی اور فرمایا: \"اے عمر! تمہیں موسم گرما (میں نازل ہونے) والی آیت کافی نہیں جو سورہ نساء کے آخر میں ہے؟ (جس سے مسئلہ واضح ہو گیا ہے)\" اور میں (عمر) اگر زندہ رہا تو اس کے بارے میں ایسا واضح فیصلہ کروں گا جس (کو دیکھتے ہوئے) ایسا شخص (بھی) فیصلہ کر سکے گا جو قرآن پڑھتا (اور سمجھتا) ہے اور وہ بھی جو قرآن نہیں پڑھتا۔"}],[4132,"سعید بن ابی عروبہ اور شعبہ دونوں نے قتادہ سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی","",{"u2":"سعید بن ابی عروبہ اور شعبہ دونوں نے قتادہ سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی"}],[4133,"ابن ابی خالد نے ابواسحاق سے اور انہوں نے سیدنا براء ( بن عازب ) رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : قرآن کی آخری آیت جو نازل ہوئی ( یہ تھی ) ( «يَسْتَفْتُونَكَ قُلِ» اللَّـهُ «يُفْتِيكُمْ فِي الْكَلَالَةِ» ۚ ) \" وہ آپ سے فتویٰ مانگتے ہیں ، کہہ دیجئے : اللہ تمہیں کلالہ کے بارے میں فتویٰ دیتا ہے","",{"u2":"ابن ابی خالد نے ابواسحاق سے اور انہوں نے حضرت براء (بن عازب) رضی اللہ عنہ سے روایت کی، انہوں نے کہا: قرآن کی آخری آیت جو نازل ہوئی (یہ تھی) (یَسْتَفْتُونَکَ قُلِ اللَّـہُ یُفْتِیکُمْ فِی الْکَلَالَۃِ ۚ) \"وہ آپ سے فتویٰ مانگتے ہیں،کہہ دیجئے: اللہ تمہیں کلالہ کے بارے میں فتویٰ دیتا ہے"}],[4134,"شعبہ نے ہمیں ابواسحاق سے حدیث بیان کی ، انہوں نے کہا : میں نے سیدنا براء بن عازب رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : آخری آیت جو نازل کی گئی ، آیت کلالہ ہے اور آخری سورت جو نازل کی گئی ، سورہ براءت ہے ۔ ( سورہ توبہ کا دوسرا نام ، سورت براءت ہے)","",{"u2":"شعبہ نے ہمیں ابواسحاق سے حدیث بیان کی، انہوں نے کہا: میں نے سیدنا براء بن عازب رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: آخری آیت جو نازل کی گئی، آیت کلالہ ہے اور آخری سورت جو نازل کی گئی، سورہ براءت ہے۔ (سورہ توبہ کا دوسرا نام، سورت براءت ہے"}],[4135,"زکریا نے ہمیں ابواسحاق کے واسطے سے سیدنا براء رضی اللہ عنہ سے حدیث بیان کی کہ آخری سورت جو پوری نازل کی گئی ، سورہ توبہ ہے اور آخری آیت جو نازل کی گئی ، آیت کلالہ ہے","",{"u2":"زکریا نے ہمیں ابواسحاق کے واسطے سے سیدنا براء رضی اللہ عنہ سے حدیث بیان کی کہ آخری سورت جو پوری نازل کی گئی، سورہ توبہ ہے اور آخری آیت جو نازل کی گئی، آیت کلالہ ہے"}],[4136,"عمار بن رزیق نے ہمیں ابواسحاق کے حوالے سے سیدنا براء رضی اللہ عنہ سے اسی کے مانند حدیث بیان کی مگر انہوں نے کہا : آخری سورت جو مکمل نازل کی گئی ۔ ( تامة کے بجائے كاملة کے الفاظ ہیں)","",{"u2":"عمار بن رزیق نے ہمیں ابواسحاق کے حوالے سے سیدنا براء رضی اللہ عنہ سے اسی کے مانند حدیث بیان کی مگر انہوں نے کہا: آخری سورت جو مکمل نازل کی گئی۔ (تامۃ کے بجائے کاملۃ کے الفاظ ہیں"}],[4137,"ابوسفر نے سیدنا براء رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : آخری آیت جو اتاری گئی ، ( «يَسْتَفْتُونَكَ» ) ہے","",{"u2":"ابوسفر نے سیدنا براء رضی اللہ عنہ سے روایت کی، انہوں نے کہا: آخری آیت جو اتاری گئی، (یَسْتَفْتُونَکَ) ہے"}],[4138,"یونس نے مجھے ابن شہاب سے خبر دی ، انہوں نے ابوسلمہ بن عبدالرحمان سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس کسی ( ایسے ) شخص کی میت لائی جاتی جس پر قرض ہوتا تو آپ پوچھتے","",{"u2":"یونس نے مجھے ابن شہاب سے خبر دی، انہوں نے ابوسلمہ بن عبدالرحمان سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس کسی (ایسے) شخص کی میت لائی جاتی جس پر قرض ہوتا تو آپ پوچھتے"}],[4139,"عقیل ، ابن شہاب ( زہری ) کے بھتیجے اور ابن ابی ذئب سب نے زہری سے اسی سند کے ساتھ یہ حدیث بیان کی","",{"u2":"عقیل، ابن شہاب (زہری) کے بھتیجے اور ابن ابی ذئب سب نے زہری سے اسی سند کے ساتھ یہ حدیث بیان کی"}],[4140,"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" اس ذات کی قسم جس کے ہاتھ میں محمد کی جان ہے! روئے زمین پر کوئی مومن نہیں مگر میں سب لوگوں کی نسبت اس کے زیادہ قریب ہوں ، تم میں سے جس نے بھی جو قرض یا اولاد چھوڑی ( جس کے ضائع ہونے کا ڈر ہے ) تو میں اس کا ذمہ دار ہوں اور جس نے مال چھوڑا وہ عصبہ ( قرابت دار جو کسی طرح بھی وارث بن سکتا ہو اس ) کا ہے ، وہ جو بھی ہو","",{"u2":"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"اس ذات کی قسم جس کے ہاتھ میں محمد کی جان ہے! روئے زمین پر کوئی مومن نہیں مگر میں سب لوگوں کی نسبت اس کے زیادہ قریب ہوں، تم میں سے جس نے بھی جو قرض یا اولاد چھوڑی (جس کے ضائع ہونے کا ڈر ہے) تو میں اس کا ذمہ دار ہوں اور جس نے مال چھوڑا وہ عصبہ (قرابت دار جو کسی طرح بھی وارث بن سکتا ہو اس) کا ہے، وہ جو بھی ہو"}],[4141,"ہمام بن منبہ سے روایت ہے ، انہوں نے کہا : یہ وہ احادیث ہیں جو ہمیں سیدنا ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں ، پھر انہوں نے چند احادیث بیان کیں ، ان میں سے یہ بھی تھی اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : اللہ عزوجل کی کتاب کی رو سے میں مومنوں کے ، ( ان کی اپنی ذات سمیت ) سب لوگوں کی نسبت زیادہ قریب ہوں ، تم میں سے جو قرض یا اولاد چھوڑ جائے تو مجھے بلانا میں اس کا ولی ہوں اور جو مال چھوڑ جائے تو اس کے مال کے معاملے میں ( ذوی الفروض کے حصے دینے کے بعد ) اس کے عصبہ ( قریب ترین مرد رشتہ دار ) کو ترجیح دی جائے ، وہ جو بھی ہو","",{"u2":"ہمام بن منبہ سے روایت ہے، انہوں نے کہا: یہ وہ احادیث ہیں جو ہمیں سیدنا ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں، پھر انہوں نے چند احادیث بیان کیں، ان میں سے یہ بھی تھی اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اللہ عزوجل کی کتاب کی رو سے میں مومنوں کے، (ان کی اپنی ذات سمیت) سب لوگوں کی نسبت زیادہ قریب ہوں، تم میں سے جو قرض یا اولاد چھوڑ جائے تو مجھے بلانا میں اس کا ولی ہوں اور جو مال چھوڑ جائے تو اس کے مال کے معاملے میں (ذوی الفروض کے حصے دینے کے بعد) اس کے عصبہ (قریب ترین مرد رشتہ دار) کو ترجیح دی جائے، وہ جو بھی ہو"}],[4142,"معاذ عنبری نے ہمیں حدیث بیان کی : ہمیں شعبہ نے عدی سے حدیث بیان کی کہ انہوں نے ابوحازم سے سنا ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" جس نے مال چھوڑا وہ اس کے ورثاء کا ہے اور جس نے بوجھ ( بے سہارا اولاد ہو یا قرض ) چھوڑا وہ ہمارے ذمہ ہے","",{"u2":"معاذ عنبری نے ہمیں حدیث بیان کی: ہمیں شعبہ نے عدی سے حدیث بیان کی کہ انہوں نے ابوحازم سے سنا، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"جس نے مال چھوڑا وہ اس کے ورثاء کا ہے اور جس نے بوجھ (بے سہارا اولاد ہو یا قرض) چھوڑا وہ ہمارے ذمہ ہے"}],[4143,"(محمد بن جعفر ) غندر اور عبدالرحمان بن مہدی نے کہا : ہمیں شعبہ نے اسی سند کے ساتھ حدیث بیان کی ، مگر غندر کی حدیث میں ہے : \" جس نے بوجھ چھوڑا اس کی ذمہ داری میں نے لے لی","",{"u2":"محمد بن جعفر) غندر اور عبدالرحمان بن مہدی نے کہا: ہمیں شعبہ نے اسی سند کے ساتھ حدیث بیان کی، مگر غندر کی حدیث میں ہے: \"جس نے بوجھ چھوڑا اس کی ذمہ داری میں نے لے لی"}],[4144,"عبداللہ بن مسلمہ بن قعنب نے ہمیں حدیث بیان کی : ہمیں مالک بن انس نے زید بن اسلم سے حدیث بیان کی ، انہوں نے اپنے والد سے روایت کی کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے کہا : میں نے اللہ کی راہ میں ( جہاد کرنے کے لیے کسی کو ) ایک عمدہ گھوڑے پر سوار کیا ( اسے دے دیا ) تو اس کے ( نئے ) مالک نے اسے ضائع کر دیا ( اس کی ٹھیک طرح سے خبر گیری نہ کی ) ، میں نے خیال کیا کہ وہ اسے کم قیمت پر فروخت کر دے گا ، چنانچہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے بارے میں پوچھا تو آپ نے فرمایا : اسے مت خریدو اور نہ اپنا ( دیا ہوا ) صدقہ واپس لو کیونکہ صدقہ واپس لینے والا ایسے کتے کی طرح ہے جو قے ( چاٹنے کے لیے ) اس کی طرف لوٹتا ہے","",{"u2":"عبداللہ بن مسلمہ بن قعنب نے ہمیں حدیث بیان کی: ہمیں مالک بن انس نے زید بن اسلم سے حدیث بیان کی، انہوں نے اپنے والد سے روایت کی کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے کہا: میں نے اللہ کی راہ میں (جہاد کرنے کے لیے کسی کو) ایک عمدہ گھوڑے پر سوار کیا (اسے دے دیا) تو اس کے (نئے) مالک نے اسے ضائع کر دیا (اس کی ٹھیک طرح سے خبر گیری نہ کی)، میں نے خیال کیا کہ وہ اسے کم قیمت پر فروخت کر دے گا، چنانچہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے بارے میں پوچھا تو آپ نے فرمایا:اسے مت خریدو اور نہ اپنا (دیا ہوا) صدقہ واپس لو کیونکہ صدقہ واپس لینے والا ایسے کتے کی طرح ہے جو قے (چاٹنے کے لیے) اس کی طرف لوٹتا ہے"}],[4145,"عبدالرحمان بن مہدی نے ہمیں مالک بن انس سے اسی سند کے ساتھ ( یہ ) حدیث بیان کی اور اضافہ کیا : اسے مت خریدو ، چاہے وہ اسے تم کو ایک درہم میں دے","",{"u2":") عبدالرحمان بن مہدی نے ہمیں مالک بن انس سے اسی سند کے ساتھ (یہ) حدیث بیان کی اور اضافہ کیا:اسے مت خریدو، چاہے وہ اسے تم کو ایک درہم میں دے"}],[4146,"روح بن قاسم نے ہمیں زید بن اسلم سے حدیث بیان کی ، انہوں نے اپنے والد سے اور انہوں نے سیدنا عمر رضی اللہ عنہ سے روایت کی کہ انہوں نے اللہ کی راہ میں ایک گھوڑا سواری کے طور پر دیا ، تو انہوں نے اسے اس کے مالک کے ہاں اس حال میں پایا کہ اس نے اسے ضائع کر دیا تھا اور وہ تنگ دست تھا ، چنانچہ انہوں ( سیدنا عمر رضی اللہ عنہ ) نے اسے خریدنے کا ارادہ کیا ، وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ کو یہ بات بتائی تو آپ نے فرمایا : \" اسے مت خریدو ، چاہے وہ تمہیں ایک درہم میں دیا جائے ، صدقہ واپس لینے والے کی مثال اس کتے کے جیسی ہے جو اپنی قے میں لوٹ جاتا ہے ( چاٹتا ہے)","",{"u2":"روح بن قاسم نے ہمیں زید بن اسلم سے حدیث بیان کی، انہوں نے اپنے والد سے اور انہوں نے سیدنا عمر رضی اللہ عنہ سے روایت کی کہ انہوں نے اللہ کی راہ میں ایک گھوڑا سواری کے طور پر دیا، تو انہوں نے اسے اس کے مالک کے ہاں اس حال میں پایا کہ اس نے اسے ضائع کر دیا تھا اور وہ تنگ دست تھا، چنانچہ انہوں (سیدنا عمر رضی اللہ عنہ) نے اسے خریدنے کا ارادہ کیا، وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ کو یہ بات بتائی تو آپ نے فرمایا: \"اسے مت خریدو، چاہے وہ تمہیں ایک درہم میں دیا جائے، صدقہ واپس لینے والے کی مثال اس کتے کے جیسی ہے جو اپنی قے میں لوٹ جاتا ہے (چاٹتا ہے"}],[4147,"فیان نے زید بن اسلم سے اسی سند کے ساتھ ( یہی ) حدیث بیان کی ، البتہ مالک اور روح کی حدیث زیادہ مکمل اور زیادہ ( مفصل ) ہے","",{"u2":"فیان نے زید بن اسلم سے اسی سند کے ساتھ (یہی) حدیث بیان کی، البتہ مالک اور روح کی حدیث زیادہ مکمل اور زیادہ (مفصل) ہے"}],[4148,"امام مالک نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے اللہ کی راہ میں ایک گھوڑا سواری کے طور پر دیا ، پھر انہوں نے اسے اس حالت میں پایا کہ اس کو فروخت کیا جا رہا تھا ، انہوں نے اسے خریدنے کا ارادہ کیا تو رسول اللہ صلی اللہ علیہ وسلم سے اس کے بارے میں پوچھا ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اسے مت خریدو اور ( کبھی ) اپنا صدقہ واپس نہ لو","",{"u2":"امام مالک نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے اللہ کی راہ میں ایک گھوڑا سواری کے طور پر دیا، پھر انہوں نے اسے اس حالت میں پایا کہ اس کو فروخت کیا جا رہا تھا، انہوں نے اسے خریدنے کا ارادہ کیا تو رسول اللہ صلی اللہ علیہ وسلم سے اس کے بارے میں پوچھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے مت خریدو اور (کبھی) اپنا صدقہ واپس نہ لو"}],[4149,"لیث بن سعد اور عبیداللہ دونوں نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے مالک کی حدیث کی طرح روایت کی","",{"u2":"لیث بن سعد اور عبیداللہ دونوں نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے مالک کی حدیث کی طرح روایت کی"}],[4150,"سالم نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ سیدنا عمر رضی اللہ عنہ نے اللہ کی راہ میں سواری کے لیے ایک گھوڑا دیا ، پھر انہوں نے اسے دیکھا کہ فروخت کیا جا رہا ہے ۔ تو انہوں نے اس کو خریدنے کا ارادہ کر لیا ، پھر نبی صلی اللہ علیہ وسلم سے پوچھا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اے عمر! اپنا صدقہ واپس مت لو","",{"u2":"سالم نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ سیدنا عمر رضی اللہ عنہ نے اللہ کی راہ میں سواری کے لیے ایک گھوڑا دیا، پھر انہوں نے اسے دیکھا کہ فروخت کیا جا رہا ہے۔ تو انہوں نے اس کو خریدنے کا ارادہ کر لیا، پھر نبی صلی اللہ علیہ وسلم سے پوچھا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے عمر! اپنا صدقہ واپس مت لو"}],[4151,"عیسیٰ بن یونس نے ہمیں خبر دی : ہمیں اوزاعی نے ابوجعفر محمد بن علی سے حدیث بیان کی ، انہوں نے ابن مسیب سے ، انہوں نے ابن عباس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" اس شخص کی مثال جو صدقہ واپس لیتا ہے اس کتے کی طرح ہے جو قے کرتا ہے ، پھر اپنی قے کی طرف لوٹتا ہے اور کھاتا ہے","",{"u2":"عیسیٰ بن یونس نے ہمیں خبر دی: ہمیں اوزاعی نے ابوجعفر محمد بن علی سے حدیث بیان کی، انہوں نے ابن مسیب سے، انہوں نے ابن عباس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"اس شخص کی مثال جو صدقہ واپس لیتا ہے اس کتے کی طرح ہے جو قے کرتا ہے، پھر اپنی قے کی طرف لوٹتا ہے اور کھاتا ہے"}],[4152,"ابن مبارک نے ہمیں اوزاعی سے خبر دی ، انہوں نے کہا : میں نے ( ابوجعفر ) محمد بن ( زین العابدین ) علی بن حسین رحمہم اللہ سے سنا ، وہ اسی سند سے اسی طرح بیان کر رہے تھے","",{"u2":"ابن مبارک نے ہمیں اوزاعی سے خبر دی، انہوں نے کہا: میں نے (ابوجعفر) محمد بن (زین العابدین) علی بن حسین رحمہم اللہ سے سنا، وہ اسی سند سے اسی طرح بیان کر رہے تھے"}],[4153,"یحییٰ بن ابی کثیر نے ہمیں حدیث بیان کی : مجھے عبدالرحمان بن عمرو نے حدیث بیان کی کہ انہیں فاطمہ بنت رسول اللہ صلی اللہ علیہ وسلم کے فرزند ( پڑپوتے ) ، محمد ( الباقر ) نے یہ حدیث اسی سند کے ساتھ انہی کی حدیث کی طرح بیان کی","",{"u2":"یحییٰ بن ابی کثیر نے ہمیں حدیث بیان کی: مجھے عبدالرحمان بن عمرو نے حدیث بیان کی کہ انہیں فاطمہ بنت رسول اللہ صلی اللہ علیہ وسلم کے فرزند (پڑپوتے)، محمد (الباقر) نے یہ حدیث اسی سند کے ساتھ انہی کی حدیث کی طرح بیان کی"}],[4154,"بکیر سے روایت ہے کہ انہوں نے سعید بن مسیب سے سنا ، وہ کہہ رہے تھے : میں نے سیدنا ابن عباس رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : اس شخص کی مثال جو صدقہ کرتا ہے ، پھر اپنے صدقے کو واپس لے لیتا ہےاس کتے کی طرح ہے جو قے کرتا ہے پھر اپنی قے کھاتا ہے","",{"u2":"بکیر سے روایت ہے کہ انہوں نے سعید بن مسیب سے سنا، وہ کہہ رہے تھے: میں نے سیدنا ابن عباس رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: اس شخص کی مثال جو صدقہ کرتا ہے، پھر اپنے صدقے کو واپس لے لیتا ہےاس کتے کی طرح ہے جو قے کرتا ہے پھر اپنی قے کھاتا ہے"}],[4155,"شعبہ نے ہمیں حدیث بیان کی : میں نے قتادہ سے سنا ، وہ سعید بن مسیب سے حدیث بیان کر رہے تھے ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : اپنے ہبہ کو واپس لینے والا اپنی قے کی طرف لوٹنے والے کی طرح ہے","",{"u2":"شعبہ نے ہمیں حدیث بیان کی: میں نے قتادہ سے سنا، وہ سعید بن مسیب سے حدیث بیان کر رہے تھے، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا:اپنے ہبہ کو واپس لینے والا اپنی قے کی طرف لوٹنے والے کی طرح ہے"}],[4156,"سعید نے قتادہ سے اسی سند کے ساتھ اسی کے مانند روایت کی","",{"u2":"سعید نے قتادہ سے اسی سند کے ساتھ اسی کے مانند روایت کی"}],[4157,"سیدنا ابن عباس رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" اپنا ہبہ واپس لینے والا کتے کی طرح ہے جو قے کرتا ہے ، پھر اپنی قے کی طرف لوٹتا ہے","",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"اپنا ہبہ واپس لینے والا کتے کی طرح ہے جو قے کرتا ہے، پھر اپنی قے کی طرف لوٹتا ہے"}],[4158,"امام مالک نے ابن شہاب سے اور انہوں نے حمید بن عبدالرحمان اور محمد بن نعمان بن بشیر سے روایت کی ، وہ دونوں سیدنا نعمان بن بشیر رضی اللہ عنہ سے حدیث بیان کر رہے تھے کہ انہوں نے کہا : ان کے والد انہیں لے کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور کہا : میں نے اپنے اس بیٹے کو غلام تحفے میں دیا ہے جو میرا تھا ، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کیا تم نے اپنے سب بچوں کو اس جیسا تحفہ دیا ہے؟ \" انہوں نے کہا : نہیں ، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اسے واپس لو","",{"u2":"امام مالک نے ابن شہاب سے اور انہوں نے حمید بن عبدالرحمان اور محمد بن نعمان بن بشیر سے روایت کی، وہ دونوں سیدنا نعمان بن بشیر رضی اللہ عنہ سے حدیث بیان کر رہے تھے کہ انہوں نے کہا: ان کے والد انہیں لے کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور کہا: میں نے اپنے اس بیٹے کو غلام تحفے میں دیا ہے جو میرا تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم نے اپنے سب بچوں کو اس جیسا تحفہ دیا ہے؟\" انہوں نے کہا: نہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے واپس لو"}],[4159,"ابراہیم بن سعد نے ہمیں ابن شہاب سے خبر دی ، انہوں نے حمید بن عبدالرحمٰن اور محمد بن نعمان سے اور انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میرے والد مجھے لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور کہا : میں نے اپنے اس بیٹے کو ایک غلام تحفے میں دیا ہے ۔ تو آپ نے پوچھا : \" کیا تم نے اپنے سب بیٹوں کو ( ایسا ) تحفہ دیا ہے؟ \" انہوں نے جواب دیا : نہیں ۔ آپ نے فرمایا : \" اسے واپس لو","",{"u2":"ابراہیم بن سعد نے ہمیں ابن شہاب سے خبر دی، انہوں نے حمید بن عبدالرحمٰن اور محمد بن نعمان سے اور انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میرے والد مجھے لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور کہا: میں نے اپنے اس بیٹے کو ایک غلام تحفے میں دیا ہے۔ تو آپ نے پوچھا: \"کیا تم نے اپنے سب بیٹوں کو (ایسا) تحفہ دیا ہے؟\" انہوں نے جواب دیا: نہیں۔ آپ نے فرمایا: \"اسے واپس لو"}],[4160,"ابن عیینہ ، لیث بن سعد ، یونس اور معمر سب نے زہری سے اسی سند کے ساتھ حدیث بیان کی ، البتہ یونس اور معمر کی حدیث میں \" تمام بیٹوں کو \" کے الفاظ ہیں اور لیث اور ابن عیینہ کی حدیث میں \" تمام اولاد کو \" ہے اور محمد بن نعمان اور حمید بن عبدالرحمان سے روایت کردہ لیث کی روایت ( یوں ) ہے کہ سیدنا بشیر رضی اللہ عنہ ( اپنے بیٹے ) نعمان رضی اللہ عنہ کو لے کر آئے","",{"u2":") ابن عیینہ، لیث بن سعد، یونس اور معمر سب نے زہری سے اسی سند کے ساتھ حدیث بیان کی، البتہ یونس اور معمر کی حدیث میں \"تمام بیٹوں کو\" کے الفاظ ہیں اور لیث اور ابن عیینہ کی حدیث میں \"تمام اولاد کو\" ہے اور محمد بن نعمان اور حمید بن عبدالرحمان سے روایت کردہ لیث کی روایت (یوں) ہے کہ سیدنا بشیر رضی اللہ عنہ (اپنے بیٹے) نعمان رضی اللہ عنہ کو لے کر آئے"}],[4161,"عروہ سے روایت ہے ، انہوں نے کہا : ہمیں سیدنا نعمان بن بشیر رضی اللہ عنہ نے حدیث بیان کی ، انہوں نے کہا : ان کے والد نے انہیں ایک غلام دیا تو نبی صلی اللہ علیہ وسلم نے ان سے پوچھا : \" یہ کیسا غلام ہے؟ \" انہوں نے کہا : یہ میرے والد نے مجھے دیا ہے ۔ ( پھر ) آپ نے ( نعمان رضی اللہ عنہ کے والد سے ) پوچھا : \" تم نے اس کے تمام بھائیوں کو بھی اسی طرح عطیہ دیا ہے جیسے اس کو دیا ہے؟ \" انہوں نے جواب دیا : نہیں ۔ آپ نے فرمایا : \" اسے واپس لو","",{"u2":"عروہ سے روایت ہے، انہوں نے کہا: ہمیں سیدنا نعمان بن بشیر رضی اللہ عنہ نے حدیث بیان کی، انہوں نے کہا: ان کے والد نے انہیں ایک غلام دیا تو نبی صلی اللہ علیہ وسلم نے ان سے پوچھا: \"یہ کیسا غلام ہے؟\" انہوں نے کہا: یہ میرے والد نے مجھے دیا ہے۔ (پھر) آپ نے (نعمان رضی اللہ عنہ کے والد سے) پوچھا: \"تم نے اس کے تمام بھائیوں کو بھی اسی طرح عطیہ دیا ہے جیسے اس کو دیا ہے؟\" انہوں نے جواب دیا: نہیں۔ آپ نے فرمایا: \"اسے واپس لو"}],[4162,"حصین نے شعبی سے ، انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میرے والد نے اپنے مال میں سے مجھے ہبہ کیا ( یہاں صدقہ ہبہ کے معنی میں ہے ) تو میری والدہ عمرہ بنت رواحہ نے کہا : میں راضی نہیں ہوں گی یہاں تک کہ تم اللہ کے رسول صلی اللہ علیہ وسلم کو گواہ بنا لو ۔ میرے والد مجھے لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تاکہ آپ کو مجھ پر کیے گئے صدقہ ( ہبہ ) پر گواہ بنائیں ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے پوچھا : \" کیا تم نے یہ ( سلوک ) اپنے تمام بچوں کے ساتھ کیا ہے؟ \" انہوں نے جواب دیا : نہیں ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" تم سب اللہ سے ڈرو اور اپنے بچوں کے مابین عدل کرو ۔ \" چنانچہ میرے والد واپس آئے اور وہ صدقہ ( ہبہ ) واپس لے لیا"],[4163,"حصین نے شعبی سے ، انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میرے والد نے اپنے مال میں سے مجھے ہبہ کیا ( یہاں صدقہ ہبہ کے معنی میں ہے ) تو میری والدہ عمرہ بنت رواحہ نے کہا : میں راضی نہیں ہوں گی یہاں تک کہ تم اللہ کے رسول صلی اللہ علیہ وسلم کو گواہ بنا لو ۔ میرے والد مجھے لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تاکہ آپ کو مجھ پر کیے گئے صدقہ ( ہبہ ) پر گواہ بنائیں ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے پوچھا : \" کیا تم نے یہ ( سلوک ) اپنے تمام بچوں کے ساتھ کیا ہے؟ \" انہوں نے جواب دیا : نہیں ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" تم سب اللہ سے ڈرو اور اپنے بچوں کے مابین عدل کرو ۔ \" چنانچہ میرے والد واپس آئے اور وہ صدقہ ( ہبہ ) واپس لے لیا","",{"u2":"حصین نے شعبی سے، انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میرے والد نے اپنے مال میں سے مجھے ہبہ کیا (یہاں صدقہ ہبہ کے معنی میں ہے) تو میری والدہ عمرہ بنت رواحہ نے کہا: میں راضی نہیں ہوں گی یہاں تک کہ تم اللہ کے رسول صلی اللہ علیہ وسلم کو گواہ بنا لو۔ میرے والد مجھے لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تاکہ آپ کو مجھ پر کیے گئے صدقہ (ہبہ) پر گواہ بنائیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے پوچھا: \"کیا تم نے یہ (سلوک) اپنے تمام بچوں کے ساتھ کیا ہے؟\" انہوں نے جواب دیا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم سب اللہ سے ڈرو اور اپنے بچوں کے مابین عدل کرو۔\" چنانچہ میرے والد واپس آئے اور وہ صدقہ (ہبہ) واپس لے لیا"}],[4164,"ابوحیان تیمی نے ہمیں شعبی سے حدیث بیان کی : مجھے سیدنا نعمان بن بشیر رضی اللہ عنہ نے حدیث بیان کی کہ ان کی والدہ ، ( عمرہ ) بنت رواحہ نے ان کے والد سے ، ان کے مال میں سے ، اپنے بیٹے کے لیے ( باغ ، زمین وغیرہ ) کچھ ہبہ کیے جانے کا مطالبہ کیا ، انہوں نے اسے ایک سال تک التوا میں رکھا ، پھر انہیں ( اس کا ) خیال آیا تو انہوں ( والدہ ) نے کہا : میں راضی نہیں ہوں گی یہاں تک کہ تم اس پر ، جو تم نے میرے بیٹے کے لیے ہبہ کیا ہے ، رسول اللہ صلی اللہ علیہ وسلم کو گواہ بنا لو ۔ اس پر میرے والد نے میرا ہاتھ تھاما ، میں ان دنوں بچہ تھا ، اور رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی : اے اللہ کے رسول! اس کی والدہ بنت رواحہ کو یہ پسند ہے کہ میں آپ کو اس چیز پر گواہ بناؤں جو میں نے اس کے بیٹے کو دی ہے ، تو رسول اللہ صلی اللہ علیہ وسلم نے پوچھا : بشیر! کیا اس کے سوا بھی تمہارے بچے ہیں؟ انہوں نے جواب دیا : جی ہاں! آپ نے پوچھا : کیا ان سب میں سے ہر ایک کو تم نے اسی طرح ہبہ کیا ہے؟ \" انہوں نے جواب دیا : نہیںآپ نے فرمایا : پھر مجھے گواہ نہ بناؤ ، میں ظلم پر گواہ نہیں بنتا"],[4165,"ابوحیان تیمی نے ہمیں شعبی سے حدیث بیان کی : مجھے سیدنا نعمان بن بشیر رضی اللہ عنہ نے حدیث بیان کی کہ ان کی والدہ ، ( عمرہ ) بنت رواحہ نے ان کے والد سے ، ان کے مال میں سے ، اپنے بیٹے کے لیے ( باغ ، زمین وغیرہ ) کچھ ہبہ کیے جانے کا مطالبہ کیا ، انہوں نے اسے ایک سال تک التوا میں رکھا ، پھر انہیں ( اس کا ) خیال آیا تو انہوں ( والدہ ) نے کہا : میں راضی نہیں ہوں گی یہاں تک کہ تم اس پر ، جو تم نے میرے بیٹے کے لیے ہبہ کیا ہے ، رسول اللہ صلی اللہ علیہ وسلم کو گواہ بنا لو ۔ اس پر میرے والد نے میرا ہاتھ تھاما ، میں ان دنوں بچہ تھا ، اور رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی : اے اللہ کے رسول! اس کی والدہ بنت رواحہ کو یہ پسند ہے کہ میں آپ کو اس چیز پر گواہ بناؤں جو میں نے اس کے بیٹے کو دی ہے ، تو رسول اللہ صلی اللہ علیہ وسلم نے پوچھا : بشیر! کیا اس کے سوا بھی تمہارے بچے ہیں؟ انہوں نے جواب دیا : جی ہاں! آپ نے پوچھا : کیا ان سب میں سے ہر ایک کو تم نے اسی طرح ہبہ کیا ہے؟ \" انہوں نے جواب دیا : نہیںآپ نے فرمایا : پھر مجھے گواہ نہ بناؤ ، میں ظلم پر گواہ نہیں بنتا","",{"u2":"ابوحیان تیمی نے ہمیں شعبی سے حدیث بیان کی: مجھے سیدنا نعمان بن بشیر رضی اللہ عنہ نے حدیث بیان کی کہ ان کی والدہ، (عمرہ) بنت رواحہ نے ان کے والد سے، ان کے مال میں سے، اپنے بیٹے کے لیے (باغ، زمین وغیرہ) کچھ ہبہ کیے جانے کا مطالبہ کیا، انہوں نے اسے ایک سال تک التوا میں رکھا، پھر انہیں (اس کا) خیال آیا تو انہوں (والدہ) نے کہا: میں راضی نہیں ہوں گی یہاں تک کہ تم اس پر، جو تم نے میرے بیٹے کے لیے ہبہ کیا ہے، رسول اللہ صلی اللہ علیہ وسلم کو گواہ بنا لو۔ اس پر میرے والد نے میرا ہاتھ تھاما، میں ان دنوں بچہ تھا، اور رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی: اے اللہ کے رسول! اس کی والدہ بنت رواحہ کو یہ پسند ہے کہ میں آپ کو اس چیز پر گواہ بناؤں جو میں نے اس کے بیٹے کو دی ہے، تو رسول اللہ صلی اللہ علیہ وسلم نے پوچھا:بشیر! کیا اس کے سوا بھی تمہارے بچے ہیں؟ انہوں نے جواب دیا: جی ہاں! آپ نے پوچھا:کیا ان سب میں سے ہر ایک کو تم نے اسی طرح ہبہ کیا ہے؟\" انہوں نے جواب دیا: نہیںآپ نے فرمایا:پھر مجھے گواہ نہ بناؤ، میں ظلم پر گواہ نہیں بنتا"}],[4166,"اسماعیل نے ہمیں شعبی سے حدیث بیان کی ، انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کیا اس کے سوا بھی تمہارے بیٹے ہیں؟ \" انہوں نے کہا : جی ہاں ۔ آپ صلی اللہ علیہ وسلم نے پوچھا : \" کیا ان سب کو بھی تم نے اس جیسا عطیہ دیا ہے؟ \" انہوں نے جواب دیا : نہیں ۔ آپ نے فرمایا : \" تو میں ظلم پر گواہ نہیں بنتا","",{"u2":"اسماعیل نے ہمیں شعبی سے حدیث بیان کی، انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا اس کے سوا بھی تمہارے بیٹے ہیں؟\" انہوں نے کہا: جی ہاں۔ آپ صلی اللہ علیہ وسلم نے پوچھا: \"کیا ان سب کو بھی تم نے اس جیسا عطیہ دیا ہے؟\" انہوں نے جواب دیا: نہیں۔ آپ نے فرمایا: \"تو میں ظلم پر گواہ نہیں بنتا"}],[4167,"عاصم احول نے شعبی سے اور انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے والد سے فرمایا : \" مجھے ظلم پر گواہ مت بناؤ","",{"u2":"عاصم احول نے شعبی سے اور انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے والد سے فرمایا: \"مجھے ظلم پر گواہ مت بناؤ"}],[4168,"داود بن ابی ہند نے شعبی سے اور انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میرے والد مجھے اٹھائے ہوئے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی : اے اللہ کے رسول! گواہ رہیں کہ میں نے نعمان کو اپنے مال میں سے اتنا اتنا دیا ہے ۔ آپ نے فرمایا : \" کیا تم نے اپنے سب بیٹوں کو اسی جیسا عطیہ دیا ہے جیسا تم نے نعمان کو دیا ہے؟ \" انہوں نے جواب دیا : نہیں ۔ آپ نے فرمایا : \" اس پر میرے سوا کسی اور کو گواہ بناؤ ۔ \" پھر فرمایا : \" کیا تمہیں یہ بات اچھی لگتی ہے کہ وہ سب تمہارے ساتھ نیکی ( حسنِ سلوک ) کرنے میں برابر ہوں؟ \" انہوں نے کہا : کیوں نہیں! آپ نے فرمایا : \" تو پھر ( تم بھی ایسا ) نہ کرو","",{"u2":"داود بن ابی ہند نے شعبی سے اور انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میرے والد مجھے اٹھائے ہوئے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی: اے اللہ کے رسول! گواہ رہیں کہ میں نے نعمان کو اپنے مال میں سے اتنا اتنا دیا ہے۔ آپ نے فرمایا: \"کیا تم نے اپنے سب بیٹوں کو اسی جیسا عطیہ دیا ہے جیسا تم نے نعمان کو دیا ہے؟\" انہوں نے جواب دیا: نہیں۔ آپ نے فرمایا: \"اس پر میرے سوا کسی اور کو گواہ بناؤ۔\" پھر فرمایا: \"کیا تمہیں یہ بات اچھی لگتی ہے کہ وہ سب تمہارے ساتھ نیکی (حسنِ سلوک) کرنے میں برابر ہوں؟\" انہوں نے کہا: کیوں نہیں! آپ نے فرمایا: \"تو پھر (تم بھی ایسا) نہ کرو"}],[4169,"ابن عون نے ہمیں شعبی سے ، انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : میرے والد نے مجھے ایک تحفہ دیا ، پھر مجھے لے کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے تاکہ آپ کو گواہ بنائیں ۔ آپ نے پوچھا : \"\" کیا تم نے اپنے سب بچوں کو یہ ( اسی طرح کا ) تحفہ دیا ہے؟ \"\" انہوں نے جواب دیا : نہیں ۔ آپ نے پوچھا : \"\" کیا تم ان سب سے اسی طرح کا نیک سلوک نہیں چاہتے جس طرح اس ( بیٹے ) سے چاہتے ہو؟ \"\" انہوں نے جواب دیا : کیوں نہیں! آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" تو میں ( ظلم پر ) گواہ نہیں بنتا ۔ \"\" ( کیونکہ اس عمل کی بنا پر پہلے تمہاری طرف سے اور پھر جوابا ان کی طرف سے ظلم کا ارتکاب ہو گا ۔ \"\" ابن عون نے کہا : میں نے یہ حدیث محمد ( بن سیرین ) کو سنائی تو انہوں نے کہا : مجھے بیان کیا گیا ہے کہ آپ نے فرمایا : اپنے بیٹوں کے درمیان یکسانیت روا رکھو ( لفظی معنی ہیں : تقریبا ایک جیسا سلوک \"\" یعنی ان کو اس بات کا عادی بناؤ)","",{"u2":"ابن عون نے ہمیں شعبی سے، انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: میرے والد نے مجھے ایک تحفہ دیا، پھر مجھے لے کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے تاکہ آپ کو گواہ بنائیں۔ آپ نے پوچھا: \"کیا تم نے اپنے سب بچوں کو یہ (اسی طرح کا) تحفہ دیا ہے؟\" انہوں نے جواب دیا: نہیں۔ آپ نے پوچھا: \"کیا تم ان سب سے اسی طرح کا نیک سلوک نہیں چاہتے جس طرح اس (بیٹے) سے چاہتے ہو؟\" انہوں نے جواب دیا: کیوں نہیں! آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو میں (ظلم پر) گواہ نہیں بنتا۔\" (کیونکہ اس عمل کی بنا پر پہلے تمہاری طرف سے اور پھر جوابا ان کی طرف سے ظلم کا ارتکاب ہو گا۔\"\nابن عون نے کہا: میں نے یہ حدیث محمد (بن سیرین) کو سنائی تو انہوں نے کہا: مجھے بیان کیا گیا ہے کہ آپ نے فرمایا:اپنے بیٹوں کے درمیان یکسانیت روا رکھو(لفظی معنی ہیں:تقریبا ایک جیسا سلوک\" یعنی ان کو اس بات کا عادی بناؤ"}],[4170,"سیدنا جابر رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : سیدنا بشیر رضی اللہ عنہ کی بیوی نے کہا : میرے بیٹے کو اپنا غلام ہبہ کر دو اور میرے لیے رسول اللہ صلی اللہ علیہ وسلم کو گواہ بناؤ ۔ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور کہا : فلاں کی بیٹی نے مجھ سے مطالبہ کیا ہے کہ میں اس کے بیٹے کو اپنا غلام ہبہ کر دوں اور اس نے کہا ہے : میرے لیے ( اس پر ) رسول اللہ صلی اللہ علیہ وسلم کو گواہ بناؤ ۔ تو آپ نے پوچھا : \" کیا اس کے اور بھائی ہیں؟ \" انہوں نے جواب دیا : جی ہاں ۔ آپ نے پوچھا : \" کیا ان سب کو بھی تم نے اسی طرح عطیہ دیا ہے جس طرح اسے دیا ہے؟ \" انہوں نے جواب دیا : نہیں ۔ آپ نے فرمایا : \" یہ درست نہیں اور میں صرف حق پر گواہ بنتا ہوں","",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: سیدنا بشیر رضی اللہ عنہ کی بیوی نے کہا: میرے بیٹے کو اپنا غلام ہبہ کر دو اور میرے لیے رسول اللہ صلی اللہ علیہ وسلم کو گواہ بناؤ۔ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور کہا: فلاں کی بیٹی نے مجھ سے مطالبہ کیا ہے کہ میں اس کے بیٹے کو اپنا غلام ہبہ کر دوں اور اس نے کہا ہے: میرے لیے (اس پر) رسول اللہ صلی اللہ علیہ وسلم کو گواہ بناؤ۔ تو آپ نے پوچھا: \"کیا اس کے اور بھائی ہیں؟\" انہوں نے جواب دیا: جی ہاں۔ آپ نے پوچھا: \"کیا ان سب کو بھی تم نے اسی طرح عطیہ دیا ہے جس طرح اسے دیا ہے؟\" انہوں نے جواب دیا: نہیں۔ آپ نے فرمایا: \"یہ درست نہیں اور میں صرف حق پر گواہ بنتا ہوں"}],[4171,"امام مالک نے ابن شہاب سے ، انہوں نے ابوسلمہ بن عبدالرحمان سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس آدمی کو عمر بھر کے لیے دی جانے والی چیز اس کے اور اس کی اولاد کے لیے دی گئی تو وہ اسی کی ہے جسے دی گئی ، وہ اس شخص کو واپس نہیں ملے گی جس نے دی تھی ، کیونکہ اس نے ایسا عطیہ دیا ہے جس میں وراثت جاری ہو گئی ہے","",{"u2":"امام مالک نے ابن شہاب سے،انہوں نے ابوسلمہ بن عبدالرحمان سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس آدمی کو عمر بھر کے لیے دی جانے والی چیز اس کے اور اس کی اولاد کے لیے دی گئی تو وہ اسی کی ہے جسے دی گئی، وہ اس شخص کو واپس نہیں ملے گی جس نے دی تھی، کیونکہ اس نے ایسا عطیہ دیا ہے جس میں وراثت جاری ہو گئی ہے"}],[4172,"لیث نے ہمیں ابن شہاب سے حدیث بیان کی ، انہوں نے ابوسلمہ سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : \"\" جس نے کسی شخص کو عمر بھر کے لیے عطیہ دیا کہ وہ اس کا اور اس کی اولاد کا ہے تو اس کی اس بات نے ، اس چیز میں ، اس کے حق کو ختم کر دیا اور وہ اسی کی ہے جسے عمر بھر کے لیے دی گئی اور اس کی اولاد کی ۔ \"\" مگر یحییٰ نے ، اپنی حدیث کے آغاز ہی میں کہا : \"\" جس شخص کے عمر بھر کے لیے عطیہ دیا گیا تو وہ اسی کا اور اس کی اولاد کا ہے","",{"u2":"لیث نے ہمیں ابن شہاب سے حدیث بیان کی، انہوں نے ابوسلمہ سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: \"جس نے کسی شخص کو عمر بھر کے لیے عطیہ دیا کہ وہ اس کا اور اس کی اولاد کا ہے تو اس کی اس بات نے، اس چیز میں، اس کے حق کو ختم کر دیا اور وہ اسی کی ہے جسے عمر بھر کے لیے دی گئی اور اس کی اولاد کی۔\"\nمگر یحییٰ نے، اپنی حدیث کے آغاز ہی میں کہا: \"جس شخص کے عمر بھر کے لیے عطیہ دیا گیا تو وہ اسی کا اور اس کی اولاد کا ہے"}],[4173,"ابن جریج نے ہمیں خبر دی : مجھے ابن شہاب نے ابوسلمہ بن عبدالرحمان کی حدیث کی رو سے عمریٰ اور اس کے طریقے کے بارے میں بتایا کہ انہیں سیدنا جابر بن عبداللہ انصاری رضی اللہ عنہ نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس آدمی نے کسی دوسرے شخص کو عمر بھر کے لیے تحفہ دیا کہ وہ اس کا اور اس کی اولاد کا ہے اور کہا : میں نے تمہیں اور تمہاری اولاد کو دیا جب تک تم میں سے کوئی زندہ ہے ، تو وہ اسی کا ہے جسے دیا گیا ہے اور وہ اس کے ( پہلے ) مالک کو واپس نہیں ہو گا کیونکہ اس نے ایسا عطیہ دیا ہے جس میں وراثت جاری ہو گئی ہے","",{"u2":"ابن جریج نے ہمیں خبر دی: مجھے ابن شہاب نے ابوسلمہ بن عبدالرحمان کی حدیث کی رو سے عمریٰ اور اس کے طریقے کے بارے میں بتایا کہ انہیں سیدنا جابر بن عبداللہ انصاری رضی اللہ عنہ نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس آدمی نے کسی دوسرے شخص کو عمر بھر کے لیے تحفہ دیا کہ وہ اس کا اور اس کی اولاد کا ہے اور کہا: میں نے تمہیں اور تمہاری اولاد کو دیا جب تک تم میں سے کوئی زندہ ہے، تو وہ اسی کا ہے جسے دیا گیا ہے اور وہ اس کے (پہلے) مالک کو واپس نہیں ہو گا کیونکہ اس نے ایسا عطیہ دیا ہے جس میں وراثت جاری ہو گئی ہے"}],[4174,"معمر نے ہمیں زہری رحمۃ اللہ علیہ سے خبر دی ، انہوں نے ابوسلمہ سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : وہ عمریٰ جسے رسول اللہ صلی اللہ علیہ وسلم نے نافذ کیا یہ ہے کہ آدمی کہے : یہ تمہارے لیے اور تمہاری اولاد کے لیے ہے ، البتہ جب وہ کہے : یہ تمہارے لیے ہے جب تک تم زندہ ہو ، تو وہ اسکے مالک کو واپس مل جائے گا ۔ معمر نے کہا : امام زہری رحمۃ اللہ علیہ اسی کے مطابق فتویٰ دیتے تھے","",{"u2":"معمر نے ہمیں زہری رحمۃ اللہ علیہ سے خبر دی، انہوں نے ابوسلمہ سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: وہ عمریٰ جسے رسول اللہ صلی اللہ علیہ وسلم نے نافذ کیا یہ ہے کہ آدمی کہے: یہ تمہارے لیے اور تمہاری اولاد کے لیے ہے، البتہ جب وہ کہے: یہ تمہارے لیے ہے جب تک تم زندہ ہو، تو وہ اسکے مالک کو واپس مل جائے گا۔\nمعمر نے کہا: امام زہری رحمۃ اللہ علیہ اسی کے مطابق فتویٰ دیتے تھے"}],[4175,"ابن ابی ذئب نے ابن شہاب سے ، انہوں نے ابوسلمہ بن عبدالرحمان سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اس شخص کے بارے میں فیصلہ کیا جسے عمر بھر کے لیے ( یہ کہہ کر ) عطیہ دیا گیا کہ وہ اس کا اور اس کی اولاد کا ہے تو وہ حتمی طور پر اسی کا ہو گا ، اس ( صورت ) میں دینے والے کے لیے کوئی شرط لگانا اور استثناء کرنا جائز نہیں ۔ ابوسلمہ نے کہا : کیونکہ اس نے ایسا عطیہ دیا ہے جس میں وراثت جاری ہو چکی ہے تو وراثت نے اس کی شرط کو ختم کر دیا","",{"u2":"ابن ابی ذئب نے ابن شہاب سے، انہوں نے ابوسلمہ بن عبدالرحمان سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اس شخص کے بارے میں فیصلہ کیا جسے عمر بھر کے لیے (یہ کہہ کر) عطیہ دیا گیا کہ وہ اس کا اور اس کی اولاد کا ہے تو وہ حتمی طور پر اسی کا ہو گا، اس(صورت) میں دینے والے کے لیے کوئی شرط لگانا اور استثناء کرنا جائز نہیں۔\nابوسلمہ نے کہا: کیونکہ اس نے ایسا عطیہ دیا ہے جس میں وراثت جاری ہو چکی ہے تو وراثت نے اس کی شرط کو ختم کر دیا"}],[4176,"خالد بن حارث نے ہمیں حدیث بیان کی : ہمیں ہشام نے یحییٰ بن ابی کثیر سے حدیث بیان کی : ہمیں ابوسلمہ بن عبدالرحمان نے حدیث بیان کی ، انہوں نے کہا : میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" عمریٰ اسی کا ہے جسے ہبہ کیا گیا ہے","",{"u2":"خالد بن حارث نے ہمیں حدیث بیان کی: ہمیں ہشام نے یحییٰ بن ابی کثیر سے حدیث بیان کی: ہمیں ابوسلمہ بن عبدالرحمان نے حدیث بیان کی، انہوں نے کہا: میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عمریٰ اسی کا ہے جسے ہبہ کیا گیا ہے"}],[4177,"معاذ بن ہشام نے ہمیں حدیث بیان کی : مجھے میرے والد نے یحییٰ بن ابی کثیر سے حدیث بیان کی : ہمیں ابوسلمہ بن عبدالرحمان نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ۔ ۔ ۔ اسی کی مانند","",{"u2":"معاذ بن ہشام نے ہمیں حدیث بیان کی: مجھے میرے والد نے یحییٰ بن ابی کثیر سے حدیث بیان کی: ہمیں ابوسلمہ بن عبدالرحمان نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا۔۔۔ اسی کی مانند"}],[4178,"احمد بن یونس نے ہمیں حدیث بیان کی : ہمیں زہیر نے حدیث بیان کی : ہمیں ابوزبیر نے سیدنا جابر رضی اللہ عنہ سے حدیث سنائی ، وہ اس کی نسبت نبی صلی اللہ علیہ وسلم کی طرف کر رہے تھے","",{"u2":"احمد بن یونس نے ہمیں حدیث بیان کی: ہمیں زہیر نے حدیث بیان کی: ہمیں ابوزبیر نے سیدنا جابر رضی اللہ عنہ سے حدیث سنائی، وہ اس کی نسبت نبی صلی اللہ علیہ وسلم کی طرف کر رہے تھے"}],[4179,"نیز یحییٰ بن یحییٰ نے ہمیں حدیث بیان کی ۔ ۔ الفاظ انہی کے ہیں ۔ ۔ ہمیں ابوخثیمہ نے ابوزبیر سے خبر دی ، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اپنے اموال اپنے پاس روکے رکھو اور انہیں خراب نہ کرو ، کیونکہ جس نے بطور عمریٰ کوئی چیز دی تو وہ اسی کی ہے جسے دی گئی ہے ، وہ زندہ ہو یا مروہ ، اور اس کے وارثوں کی ہے ۔ \" ( یعنی جب اس کو اور اس کے وارثوں کو دی گئی یا غیر مؤقت دی گئی)","",{"u2":"نیز یحییٰ بن یحییٰ نے ہمیں حدیث بیان کی۔۔ الفاظ انہی کے ہیں۔۔ ہمیں ابوخثیمہ نے ابوزبیر سے خبر دی، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اپنے اموال اپنے پاس روکے رکھو اور انہیں خراب نہ کرو، کیونکہ جس نے بطور عمریٰ کوئی چیز دی تو وہ اسی کی ہے جسے دی گئی ہے، وہ زندہ ہو یا مروہ، اور اس کے وارثوں کی ہے۔\" (یعنی جب اس کو اور اس کے وارثوں کو دی گئی یا غیر مؤقت دی گئی"}],[4180,"حجاج بن ابوعثمان ، سفیان اور ایوب سب نے ابوزبیر سے ، انہوں نے سیدنا جابر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ۔ ۔ آگے ابوخثیمہ کی حدیث کے ہم معنی ہے ۔ ایوب کی حدیث میں کچھ اضافہ ہے ، انہوں نے کہا : انصار نے مہاجرین کو عمر بھر کے لیے دینا شروع کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اپنے اموال اپنے پاس رکھو","",{"u2":"حجاج بن ابوعثمان، سفیان اور ایوب سب نے ابوزبیر سے، انہوں نے سیدنا جابر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی۔۔ آگے ابوخثیمہ کی حدیث کے ہم معنی ہے۔ ایوب کی حدیث میں کچھ اضافہ ہے، انہوں نے کہا: انصار نے مہاجرین کو عمر بھر کے لیے دینا شروع کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اپنے اموال اپنے پاس رکھو"}],[4181,"ابن جریج نے ہمیں خبر دی ، مجھے ابوزبیر نے سیدنا جابر رضی اللہ عنہ سے خبر دی ، انہوں نے کہا : مدینہ میں ایک عورت نے اپنے بیٹے کو اپنا باغ بطور عمریٰ دیا ، پھر وہ فوت ہو گیا اور اس کے بعد وہ بھی فوت ہو گئی ، اس ( لڑکے ) نے اولاد چھوڑی اور اس کے بھائی بھی تھے جو بطور عمریٰ دینے والی عورت کے بیٹے تھے ، تو بطور عمریٰ دینے والی عورت کی اولاد نے کہا : باغ ہمیں واپس مل گیا ۔ اور جسے بطور عمریٰ ہبہ کیا گیا تھا اس کے بیٹوں نے کہا : زندگی اور موت دونوں صورتوں میں وہ ہمارے باپ ہی کا ہے ۔ چنانچہ وہ سیدنا عثمان کے آزاد کردہ غلام طارق کے پاس ( جو عبدالملک بن مروان کی طرف سے مدینے کا گورنر تھا ) جھگڑا لے کر گئے ، انہوں نے سیدنا جابر رضی اللہ عنہ کو بلایا تو انہوں نے عمریٰ کی بابت رسول اللہ صلی اللہ علیہ وسلم ( کے فرمان ) پر گواہی دی کہ وہ اس کے ( موجودہ ) مالک کا ہے ۔ طارق نے اسی کے مطابق فیصلہ کیا ، پھر انہوں نے عبدالملک کی طرف لکھا اور انہیں اس واقعے کی اطلاع دی اور سیدنا جابر رضی اللہ عنہ کی گواہی کے بارے میں بھی بتایا تو عبدالملک نے کہا : سیدنا جابر رضی اللہ عنہ نے سچ کہا ، تو طارق نے اس ( حکم ) کو نافذ کر دیا ، چنانچہ وہ باغ آج تک اسی کے بیٹوں کے پاس ہے جسے بطور عمریٰ دیا گیا تھا","",{"u2":"ابن جریج نے ہمیں خبر دی، مجھے ابوزبیر نے سیدنا جابر رضی اللہ عنہ سے خبر دی، انہوں نے کہا: مدینہ میں ایک عورت نے اپنے بیٹے کو اپنا باغ بطور عمریٰ دیا، پھر وہ فوت ہو گیا اور اس کے بعد وہ بھی فوت ہو گئی، اس (لڑکے) نے اولاد چھوڑی اور اس کے بھائی بھی تھے جو بطور عمریٰ دینے والی عورت کے بیٹے تھے، تو بطور عمریٰ دینے والی عورت کی اولاد نے کہا: باغ ہمیں واپس مل گیا۔ اور جسے بطور عمریٰ ہبہ کیا گیا تھا اس کے بیٹوں نے کہا: زندگی اور موت دونوں صورتوں میں وہ ہمارے باپ ہی کا ہے۔ چنانچہ وہ حضرت عثمان کے آزاد کردہ غلام طارق کے پاس (جو عبدالملک بن مروان کی طرف سے مدینے کا گورنر تھا) جھگڑا لے کر گئے، انہوں نے سیدنا جابر رضی اللہ عنہ کو بلایا تو انہوں نے عمریٰ کی بابت رسول اللہ صلی اللہ علیہ وسلم (کے فرمان) پر گواہی دی کہ وہ اس کے (موجودہ) مالک کا ہے۔ طارق نے اسی کے مطابق فیصلہ کیا، پھر انہوں نے عبدالملک کی طرف لکھا اور انہیں اس واقعے کی اطلاع دی اور سیدنا جابر رضی اللہ عنہ کی گواہی کے بارے میں بھی بتایا تو عبدالملک نے کہا: سیدنا جابر رضی اللہ عنہ نے سچ کہا، تو طارق نے اس (حکم) کو نافذ کر دیا، چنانچہ وہ باغ آج تک اسی کے بیٹوں کے پاس ہے جسےبطور عمریٰ دیا گیا تھا"}],[4182,"سلیمان بن یسار سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے روایت کردہ سیدنا جابر بن عبداللہ رضی اللہ عنہ کے قول کی بنا پر طارق نے عمریٰ کا فیصلہ وارث کے حق میں کیا تھا","",{"u2":"سلیمان بن یسار سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے روایت کردہ سیدنا جابر بن عبداللہ رضی اللہ عنہ کے قول کی بنا پر طارق نے عمریٰ کا فیصلہ وارث کے حق میں کیا تھا"}],[4183,"شعبہ نے ہمیں حدیث بیان کی ، کہا : میں نے قتادہ سے سنا ، وہ عطاء کے واسطے سے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے حدیث بیان کر رہے تھے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" عمریٰ جائز ہے ۔ \" ( یہ عطیہ درست ہے اور آگے چلتا ہے)","",{"u2":"شعبہ نے ہمیں حدیث بیان کی، کہا: میں نے قتادہ سے سنا، وہ عطاء کے واسطے سے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے حدیث بیان کر رہے تھے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"عمریٰ جائز ہے۔\" (یہ عطیہ درست ہے اور آگے چلتا ہے"}],[4184,"سعید نے ہمیں قتادہ سے حدیث بیان کی ، انہوں نے عطاء سے ، انہوں نے سیدنا جابر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" عمریٰ اس کے خاندان ( میں سے وراثت کے حقداروں ) کی میراث ہے","",{"u2":") سعید نے ہمیں قتادہ سے حدیث بیان کی، انہوں نے عطاء سے، انہوں نے سیدنا جابر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"عمریٰ اس کے خاندان (میں سے وراثت کے حقداروں) کی میراث ہے"}],[4185,"شعبہ نے ہمیں قتادہ سے حدیث بیان کی ، انہوں نے نضر بن انس سے ، انہوں نے بشیر بن نہیک سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" عمریٰ درست ہے","",{"u2":"شعبہ نے ہمیں قتادہ سے حدیث بیان کی، انہوں نے نضر بن انس سے، انہوں نے بشیر بن نہیک سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"عمریٰ درست ہے"}],[4186,"سعید نے ہمیں قتادہ سے اسی سند کے ساتھ حدیث بیان کی ، البتہ انہوں ( قتادہ ) نے کہا : \" اس کے خاندان کی وراثت \" کہا یا \" جائز \" کہا","",{"u2":"سعید نے ہمیں قتادہ سے اسی سند کے ساتھ حدیث بیان کی، البتہ انہوں (قتادہ) نے کہا: \"اس کے خاندان کی وراثت\" کہا یا \"جائز\" کہا"}],[4187,"یحییٰ بن سعید قطان نے ہمیں عبیداللہ سے حدیث بیان کی کہا : مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کسی مسلمان کو ، جس کے پاس کچھ ہو اور وہ اس میں وصیت کرنا چاہتا ہو ، اس بات کا حق نہیں کہ وہ دو راتیں ( بھی ) گزارے مگر اس طرح کہ اس کی وصیت اس کے پاس لکھی ہوئی ہو","",{"u2":"یحییٰ بن سعید قطان نے ہمیں عبیداللہ سے حدیث بیان کی کہا: مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی مسلمان کو، جس کے پاس کچھ ہو اور وہ اس میں وصیت کرنا چاہتا ہو، اس بات کا حق نہیں کہ وہ دو راتیں (بھی) گزارے مگر اس طرح کہ اس کی وصیت اس کے پاس لکھی ہوئی ہو"}],[4188,"عبدہ بن سلیمان اور عبداللہ بن نمیر دونوں نے عبیداللہ سے اسی سند کے ساتھ روایت کی ، البتہ ان دونوں نے کہا : \" اس کے پاس ( مال ) ہو جس میں وصیت کرے ( قابل وصیت مال ہو ۔ ) \" اور اس طرح نہیں کہا : \" جس میں وصیت کرنا چاہتا ہو ۔ \" ( مفہوم وہی ہے ، الفاظ کا فرق ہے)","",{"u2":"عبدہ بن سلیمان اور عبداللہ بن نمیر دونوں نے عبیداللہ سے اسی سند کے ساتھ روایت کی، البتہ ان دونوں نے کہا: \"اس کے پاس (مال) ہو جس میں وصیت کرے (قابل وصیت مال ہو۔)\" اور اس طرح نہیں کہا: \"جس میں وصیت کرنا چاہتا ہو۔\" (مفہوم وہی ہے، الفاظ کا فرق ہے"}],[4189,"ایوب ، یونس ، اسامہ بن زید لیثی اور ہشام بن سعد سب نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے عبیداللہ کی حدیث کی طرح حدیث بیان کی اور ان سب نے کہا : \" اس کے پاس کوئی ( ایسی ) چیز ہے جس میں وہ وصیت کرے ۔ \" البتہ ایوب کی حدیث میں ہے کہ انہوں نے کہا : \" وہ اس میں وصیت کرنا چاہتا ہو \" عبیداللہ سے یحییٰ کی روایت کی طرح","",{"u2":"ایوب، یونس، اسامہ بن زید لیثی اور ہشام بن سعد سب نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے عبیداللہ کی حدیث کی طرح حدیث بیان کی اور ان سب نے کہا: \"اس کے پاس کوئی (ایسی) چیز ہے جس میں وہ وصیت کرے۔\" البتہ ایوب کی حدیث میں ہے کہ انہوں نے کہا: \"وہ اس میں وصیت کرنا چاہتا ہو\" عبیداللہ سے یحییٰ کی روایت کی طرح"}],[4190,"عمرو بن حارث نے مجھے ابن شہاب سے خبر دی ، انہوں نے سالم سے اور انہوں نے اپنے والد سے روایت کی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ نے فرمایا : کسی مسلمان آدمی کے لیے ، جس کے پاس کوئی ( ایسی ) چیز ہو جس میں وہ وصیت کرے ، یہ جائز نہیں کہ وہ تین راتیں ( بھی ) گزارے مگر اس طرح کہ اس کی وصیت اس کے پاس لکھی ہوئی ہو ۔ \"\" سیدنا عبداللہ بن عمر رضی اللہ عنہ نے کہا : میں نے جب سے رسول اللہ صلی اللہ علیہ وسلم کا یہ فرمان سنا ہے مجھ پر ایک رات بھی نہیں گزری مگر میری وصیت میرے پاس موجود تھی","",{"u2":"عمرو بن حارث نے مجھے ابن شہاب سے خبر دی، انہوں نے سالم سے اور انہوں نے اپنے والد سے روایت کی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ نے فرمایا:کسی مسلمان آدمی کے لیے، جس کے پاس کوئی (ایسی) چیز ہو جس میں وہ وصیت کرے، یہ جائز نہیں کہ وہ تین راتیں (بھی) گزارے مگر اس طرح کہ اس کی وصیت اس کے پاس لکھی ہوئی ہو۔\"\nسیدنا عبداللہ بن عمر رضی اللہ عنہ نے کہا: میں نے جب سے رسول اللہ صلی اللہ علیہ وسلم کا یہ فرمان سنا ہے مجھ پر ایک رات بھی نہیں گزری مگر میری وصیت میرےپاس موجود تھی"}],[4191,"یونس ، عقیل اور معمر سب نے زہری سے اسی سند کے ساتھ عمرو بن حارث کی حدیث کی طرح حدیث بیان کی","",{"u2":"یونس، عقیل اور معمر سب نے زہری سے اسی سند کے ساتھ عمرو بن حارث کی حدیث کی طرح حدیث بیان کی"}],[4192,"ابراہیم بن سعد ( بن ابراہیم بن عبدالرحمان بن عوف ) نے ہمیں ابن شہاب سے خبر دی ، انہوں نے عامر بن سعد اور انہوں نے اپنے والد ( سیدنا سعد بن ابی وقاص رضی اللہ عنہ ) سے روایت کی ، انہوں نے کہا : حجۃ الوداع کی موقع پر رسول اللہ صلی اللہ علیہ وسلم نے ایسی بیماری میں میری عیادت کی جس کی وجہ سے میں موت کے کنارے پہنچ چکا تھا ۔ میں نے عرض کی : اللہ کے رسول! مجھے ایسی بیماری نے آ لیا ہے جو آپ دیکھ رہے ہیں اور میں مالدار آدمی ہوں اور صرف ایک بیٹی کے سوا میرا کوئی وارث نہیں ( بنتا ۔ ) تو کیا میں اپنے مال کا دو تہائی حصہ صدقہ کر دوں؟ آپ نے فرمایا : \" نہیں ۔ \" میں نے عرض کی : کیا میں اس کا آدھا حصہ صدقہ کر دوں؟ آپ نے فرمایا : \" نہیں ، ( البتہ ) ایک تہائی ( صدقہ کر دو ) اور ایک تہائی بہت ہے ، بلاشبہ اگر تم اپنے ورثاء کو مالدار چھوڑ جاؤ ، وہ لوگوں کے سامنے دست سوال دراز کرتے پھریں ، اور تم کوئی چیز بھی خرچ نہیں کرتے جس کے ذریعے سے تم اللہ کی رضا چاہتے ہو ، مگر تمہیں اس کا اجر دیا جاتا ہے حتی کہ اس لقمے کا بھی جو تم اپنی بیوی کے منہ میں ڈالتے ہو ۔ \" کہا : میں نے عرض کی : اللہ کے رسول! میں اپنے ساتھیوں کے ( مدینہ لوٹ جانے کے بعد ) پیچھے ( یہیں مکہ میں ) چھوڑ دیا جاؤں گا؟ آپ نے فرمایا : \" تمہیں پیچھے نہیں چھوڑا جائے گا ، پھر تم کوئی ایسا عمل نہیں کرو گے جس کے ذریعے سے تم اللہ کی رضا چاہتے ہو گے ، مگر اس کی بنا پر تم درجے اور بلندی میں ( اور ) بڑھ جاؤ گے اور شاید تمہیں چھوڑ دیا جائے ( لمبی عمر دی جائے ) حتی کہ تمہارے ذریعے سے بہت سی قوموں کو نفع ملے اور دوسری بہت سی قوموں کو نقصان پہنچے ۔ اے اللہ! میرے ساتھیوں کے لیے ان کی ہجرت کو جاری رکھ اور انہیں ان کی ایڑیوں کے بل واپس نہ لوٹا ، لیکن بے چارے سعد بن خولہ ( وہ تو فوت ہو ہی گئے ۔ ) کہا : رسول اللہ صلی اللہ علیہ وسلم نے اس وجہ سے ان کے لیے غم کا اظہارِ افسوس کیا کہ وہ ( اس سے پہلے ہی ) مکہ میں ( آ کر ) فوت ہو گئے تھے ۔","",{"u2":"ابراہیم بن سعد (بن ابراہیم بن عبدالرحمان بن عوف) نے ہمیں ابن شہاب سے خبر دی، انہوں نے عامر بن سعد اور انہوں نے اپنے والد (سیدنا سعد بن ابی وقاص رضی اللہ عنہ) سے روایت کی، انہوں نے کہا: حجۃ الوداع کی موقع پر رسول اللہ صلی اللہ علیہ وسلم نے ایسی بیماری میں میری عیادت کی جس کی وجہ سے میں موت کے کنارے پہنچ چکا تھا۔ میں نے عرض کی: اللہ کے رسول! مجھے ایسی بیماری نے آ لیا ہے جو آپ دیکھ رہے ہیں اور میں مالدار آدمی ہوں اور صرف ایک بیٹی کے سوا میرا کوئی وارث نہیں (بنتا۔) تو کیا میں اپنے مال کا دو تہائی حصہ صدقہ کر دوں؟ آپ نے فرمایا: \"نہیں۔\" میں نے عرض کی: کیا میں اس کا آدھا حصہ صدقہ کر دوں؟ آپ نے فرمایا: \"نہیں، (البتہ) ایک تہائی (صدقہ کر دو) اور ایک تہائی بہت ہے، بلاشبہ اگر تم اپنے ورثاء کو مالدار چھوڑ جاؤ، وہ لوگوں کے سامنے دست سوال دراز کرتے پھریں، اور تم کوئی چیز بھی خرچ نہیں کرتے جس کے ذریعے سے تم اللہ کی رضا چاہتے ہو، مگر تمہیں اس کا اجر دیا جاتا ہے حتی کہ اس لقمے کا بھی جو تم اپنی بیوی کے منہ میں ڈالتے ہو۔\" کہا: میں نے عرض کی: اللہ کے رسول! میں اپنے ساتھیوں کے (مدینہ لوٹ جانے کے بعد) پیچھے (یہیں مکہ میں) چھوڑ دیا جاؤں گا؟ آپ نے فرمایا: \"تمہیں پیچھے نہیں چھوڑا جائے گا، پھر تم کوئی ایسا عمل نہیں کرو گے جس کے ذریعے سے تم اللہ کی رضا چاہتے ہو گے، مگر اس کی بنا پر تم درجے اور بلندی میں (اور) بڑھ جاؤ گے اور شاید تمہیں چھوڑ دیا جائے (لمبی عمر دی جائے) حتی کہ تمہارے ذریعے سے بہت سی قوموں کو نفع ملے اور دوسری بہت سی قوموں کو نقصان پہنچے۔ اے اللہ! میرے ساتھیوں کے لیے ان کی ہجرت کو جاری رکھ اور انہیں ان کی ایڑیوں کے بل واپس نہ لوٹا، لیکن بے چارے سعد بن خولہ (وہ تو فوت ہو ہی گئے۔)کہا: رسول اللہ صلی اللہ علیہ وسلم نے اس وجہ سے ان کے لیے غم کا اظہارِ افسوس کیا کہ وہ (اس سے پہلے ہی) مکہ میں (آ کر) فوت ہو گئے تھے۔"}],[4193,"سفیان بن عیینہ ، یونس اور معمر سب نے ابن شہاب سے اسی سند کے ساتھ اسی طرح حدیث بیان کی","",{"u2":"سفیان بن عیینہ، یونس اور معمر سب نے ابن شہاب سے اسی سند کے ساتھ اسی طرح حدیث بیان کی"}],[4194,"سعد بن ابراہیم نے عامر بن سعد سے اور انہوں نے سیدنا سعد رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : نبی صلی اللہ علیہ وسلم میری عیادت کرنے کے لیے میرے ہاں تشریف لائے ۔ ۔ ۔ آگے زہری کی حدیث کے ہم معنی بیان کیا اور انہوں نے سعد بن خولہ رضی اللہ عنہ کے بارے میں نبی صلی اللہ علیہ وسلم کے فرمان کا تذکرہ نہیں کیا ، مگر انہوں نے کہا : اور وہ ( سیدنا سعد بن خولہ رضی اللہ عنہ ) ناپسند کرتے تھے کہ اس سرزمین میں وفات پائیں جہاں سے ہجرت کر گئے تھے","",{"u2":"سعد بن ابراہیم نے عامر بن سعد سے اور انہوں نے سیدنا سعد رضی اللہ عنہ سے روایت کی، انہوں نے کہا: نبی صلی اللہ علیہ وسلم میری عیادت کرنے کے لیے میرے ہاں تشریف لائے۔۔۔ آگے زہری کی حدیث کے ہم معنی بیان کیا اور انہوں نے سعد بن خولہ رضی اللہ عنہ کے بارے میں نبی صلی اللہ علیہ وسلم کے فرمان کا تذکرہ نہیں کیا، مگر انہوں نے کہا: اور وہ (سیدنا سعد بن خولہ رضی اللہ عنہ) ناپسند کرتے تھے کہ اس سرزمین میں وفات پائیں جہاں سے ہجرت کر گئے تھے"}],[4195,"زہیر نے ہمیں حدیث بیان کی ، کہا : ہمیں سماک بن حرب نے حدیث بیان کی ، کہا : مجھے مصعب بن سعد ( بن ابی وقاص ) نے اپنے والد سے حدیث بیان کی ، انہوں نے کہا : میں بیمار ہوا تو میں نے نبی صلی اللہ علیہ وسلم کے پاس پیغام بھیجا ، میں نے عرض کی : مجھے اجازت دیجیے کہ میں اپنا مال جہاں چاہوں تقسیم کر دوں ۔ آپ نے انکار فرمایا ، میں نے عرض کی : آدھا مال ( تقسیم کر دوں؟ ) آپ نے انکار فرمایا ، میں نے عرض کی : ایک تہائی؟ کہا : ( میرے ) ایک تہائی ( کہنے ) کے بعد آپ خاموش ہو گئے ۔ ( ایک تہائی کی وصیت سے آپ نے منع نہ فرمایا مگر اس کے بارے میں بھی یہ فرمایا : ایک تہائی بھی بہت ہے ، حدیث : 4215 ، 4214 ) کہا : اس کے بعد ایک تہائی ( کی وصیت ) جائز ٹھہری ۔","",{"u2":"زہیر نے ہمیں حدیث بیان کی، کہا: ہمیں سماک بن حرب نے حدیث بیان کی، کہا: مجھے مصعب بن سعد (بن ابی وقاص) نے اپنے والد سے حدیث بیان کی، انہوں نے کہا: میں بیمار ہوا تو میں نے نبی صلی اللہ علیہ وسلم کے پاس پیغام بھیجا، میں نے عرض کی: مجھے اجازت دیجیے کہ میں اپنا مال جہاں چاہوں تقسیم کر دوں۔ آپ نے انکار فرمایا، میں نےعرض کی: آدھا مال (تقسیم کر دوں؟) آپ نے انکار فرمایا، میں نے عرض کی: ایک تہائی؟ کہا: (میرے) ایک تہائی (کہنے) کے بعد آپ خاموش ہو گئے۔ (ایک تہائی کی وصیت سے آپ نے منع نہ فرمایا مگر اس کے بارے میں بھی یہ فرمایا: ایک تہائی بھی بہت ہے، حدیث: 4215، 4214)\nکہا:اس کے بعد ایک تہائی (کی وصیت) جائز ٹھہری۔"}],[4196,"شعبہ نے سماک سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی اور انہوں نے یہ بیان نہیں کیا : \" اس کے بعد ایک تہائی ( کی وصیت ) جائز ٹھہری","",{"u2":"شعبہ نے سماک سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی اور انہوں نے یہ بیان نہیں کیا: \"اس کے بعد ایک تہائی (کی وصیت) جائز ٹھہری"}],[4197,"عبدالملک بن عُمَیر نے مُصعب بن سعد سے اور انہوں نے اپنے والد سے روایت کی ، انہوں نے کہا : نبی صلی اللہ علیہ وسلم نے میری عیادت کی تو میں نے عرض کی : کیا میں اپنے سارے مال کی وصیت کر دوں؟ آپ نے فرمایا : \" نہیں ۔ \" میں نے عرض کی : تو آدھے کی؟ آپ نے فرمایا : \" نہیں ۔ \" میں نے عرض کی : ایک تہائی کی؟ تو آپ نے فرمایا : \" ہاں ، اور تہائی بھی زیادہ ہے","",{"u2":"عبدالملک بن عُمَیر نے مُصعب بن سعد سے اور انہوں نے اپنے والد سے روایت کی، انہوں نے کہا: نبی صلی اللہ علیہ وسلم نے میری عیادت کی تو میں نے عرض کی: کیا میں اپنے سارے مال کی وصیت کر دوں؟ آپ نے فرمایا: \"نہیں۔\" میں نے عرض کی: تو آدھے کی؟ آپ نے فرمایا: \"نہیں۔\" میں نے عرض کی: ایک تہائی کی؟ تو آپ نے فرمایا: \"ہاں، اور تہائی بھی زیادہ ہے"}],[4198,"(عبدالوہاب ) ثقفی نے ہمیں ایوب سختیانی سے حدیث بیان کی ، انہوں نے عمرو بن سعید سے ، انہوں نے حُمید بن عبدالرحمان حمیری سے اور انہوں نے سیدنا سعد رضی اللہ عنہ کے ( دس سے زائد میں سے ) تین بیٹوں ( عامر ، مصعب اور محمد ) سے روایت کی ، وہ سب اپنے والد سے حدیث بیان کرتے تھے کہ مکہ میں نبی صلی اللہ علیہ وسلم عیادت کرنے کے لیے سیدنا سعد رضی اللہ عنہ کے ہاں تشریف لائے تو وہ رونے لگے ، آپ نے پوچھا : \" تمہیں کیا بات رلا رہی ہے؟ \" انہوں نے کہا : مجھے ڈر ہے کہ میں اس سرزمین میں فوت ہو جاؤں گا جہاں سے ہجرت کی تھی ، جیسے سعد بن خولہ رضی اللہ عنہ فوت ہو گئے ۔ تو نبی صلی اللہ علیہ وسلم نے فرمایا : \" اے اللہ! سعد کو شفا دے ۔ اے اللہ! سعد کو شفا دے ۔ \" تین بار فرمایا ۔ انہوں نے کہا : اللہ کے رسول! میرے پاس بہت سا مال ہے اور میری وارث صرف میری بیٹی بنے گی ، کیا میں اپنے سارے مال کی وصیت کر دوں؟ آپ نے فرمایا : \" نہیں ۔ \" انہوں نے کہا : دو تہائی کی؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" نہیں ۔ \" انہوں نے کہا : نصف کی؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" نہیں ۔ \" انہوں نے کہا : ایک تہائی کی؟ آپ نے فرمایا : \" ( ہاں ) ایک تہائی کی ( وصیت کر دو ) اور ایک تہائی بھی زیادہ ہے ۔ اپنے مال میں سے تمہارا صدقہ کرنا صدقہ ہے ، اپنے عیال پر تمہارا خرچ کرنا صدقہ ہے اور جو تمہارے مال سے تمہاری بیوی کھاتی ہے صدقہ ہے اور تم اپنے اہل و عیال کو ( کافی مال دے کر ) خیر کے عالم میں چھوڑ جاؤ ۔ ۔ یا فرمایا : ( اچھی ) گزران کے ساتھ چھوڑ جاؤ ۔ ۔ یہ اس سے بہتر ہے کہ تم انہیں اس حال میں چھوڑو کہ وہ لوگوں کے سامنے ہاتھ پھیلاتے پھریں ۔ \" اور آپ نے اپنے ہاتھ سے اشارہ کر کے دکھایا ۔","",{"u2":"عبدالوہاب) ثقفی نے ہمیں ایوب سختیانی سے حدیث بیان کی، انہوں نے عمرو بن سعید سے، انہوں نے حُمید بن عبدالرحمان حمیری سے اور انہوں نے سیدنا سعد رضی اللہ عنہ کے (دس سے زائد میں سے) تین بیٹوں (عامر، مصعب اور محمد) سے روایت کی، وہ سب اپنے والد سے حدیث بیان کرتے تھے کہ مکہ میں نبی صلی اللہ علیہ وسلم عیادت کرنے کے لیے سیدنا سعد رضی اللہ عنہ کے ہاں تشریف لائے تو وہ رونے لگے، آپ نے پوچھا: \"تمہیں کیا بات رلا رہی ہے؟\" انہوں نے کہا: مجھے ڈر ہے کہ میں اس سرزمین میں فوت ہو جاؤں گا جہاں سے ہجرت کی تھی، جیسے سعد بن خولہ رضی اللہ عنہ فوت ہو گئے۔ تو نبی صلی اللہ علیہ وسلم نے فرمایا: \"اے اللہ! سعد کو شفا دے۔ اے اللہ! سعد کو شفا دے۔\" تین بار فرمایا۔ انہوں نے کہا: اللہ کے رسول! میرے پاس بہت سا مال ہے اور میری وارث صرف میری بیٹی بنے گی، کیا میں اپنے سارے مال کی وصیت کر دوں؟ آپ نے فرمایا: \"نہیں۔\" انہوں نے کہا: دو تہائی کی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں۔\" انہوں نے کہا: نصف کی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں۔\" انہوں نے کہا: ایک تہائی کی؟ آپ نے فرمایا: \"(ہاں) ایک تہائی کی (وصیت کر دو) اور ایک تہائی بھی زیادہ ہے۔ اپنے مال میں سے تمہارا صدقہ کرنا صدقہ ہے، اپنے عیال پر تمہارا خرچ کرنا صدقہ ہے اور جو تمہارے مال سے تمہاری بیوی کھاتی ہے صدقہ ہے اور تم اپنے اہل و عیال کو (کافی مال دے کر) خیر کے عالم میں چھوڑ جاؤ۔۔ یا فرمایا: (اچھی) گزران کے ساتھ چھوڑ جاؤ۔۔ یہ اس سے بہتر ہے کہ تم انہیں اس حال میں چھوڑو کہ وہ لوگوں کے سامنے ہاتھ پھیلاتے پھریں۔\" اور آپ نے اپنے ہاتھ سےاشارہ کر کے دکھایا۔"}],[4199,"ہمیں حماد نے حدیث بیان کی ، انہوں نے کہا : ہمیں ایوب نے عمرو بن سعید سے حدیث بیان کی ، انہوں نے حمید بن عبدالرحمان حمیری سے اور انہوں نے سیدنا سعد رضی اللہ عنہ کے تین بیٹوں سے روایت کی ، انہوں نے کہا : سیدنا سعد رضی اللہ عنہ مکہ میں بیمار ہوئے تو رسول اللہ صلی اللہ علیہ وسلم ان کی عیادت کرنے کے لیے ان کے ہاں تشریف لائے ۔ ۔ آگے ثقفی کی حدیث کے ہم معنی ہے","",{"u2":"ہمیں حماد نے حدیث بیان کی، انہوں نے کہا: ہمیں ایوب نے عمرو بن سعید سے حدیث بیان کی، انہوں نے حمید بن عبدالرحمان حمیری سے اور انہوں نے سیدنا سعد رضی اللہ عنہ کے تین بیٹوں سے روایت کی، انہوں نے کہا: سیدنا سعد رضی اللہ عنہ مکہ میں بیمار ہوئے تو رسول اللہ صلی اللہ علیہ وسلم ان کی عیادت کرنے کے لیے ان کے ہاں تشریف لائے۔۔ آگے ثقفی کی حدیث کے ہم معنی ہے"}],[4200,"محمد نے حمید بن عبدالرحمان سے روایت کی ، انہوں نے کہا : مجھے سیدنا سعد بن مالک رضی اللہ عنہ کے تین بیٹوں نے حدیث بیان کی ، ان میں ہر ایک مجھے اپنے دوسرے ساتھی کے مانند حدیث بیان کر رہا تھا ، کہا : سیدنا سعد رضی اللہ عنہ مکہ میں بیمار ہوئے تو نبی صلی اللہ علیہ وسلم ان کی عیادت کے لیے تشریف لائے ۔ ۔ آگے حمید حمیری سے عمرو بن سعید کی حدیث کے ہم معنی ہے","",{"u2":"محمد نے حمید بن عبدالرحمان سے روایت کی، انہوں نے کہا: مجھے سیدنا سعد بن مالک رضی اللہ عنہ کے تین بیٹوں نے حدیث بیان کی، ان میں ہر ایک مجھے اپنے دوسرے ساتھی کے مانند حدیث بیان کر رہا تھا، کہا: سیدنا سعد رضی اللہ عنہ مکہ میں بیمار ہوئے تو نبی صلی اللہ علیہ وسلم ان کی عیادت کے لیے تشریف لائے۔۔ آگے حمید حمیری سے عمرو بن سعید کی حدیث کے ہم معنی ہے"}],[4201,"عیسیٰ بن یونس ، وکیع اور ابن نمیر سب نے ہشام بن عروہ سے حدیث بیان کی ، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : کاش لوگ تہائی سے کم کر کے چوتھائی کی وصیت کریں کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے : \"\" تہائی ( تک کی وصیت کرو ) ، اور تہائی بھی زیادہ ہے وکیع کی حدیث میں \"\" بڑا ہے \"\" یا \"\" زیادہ ہے \"\" کے الفاظ ہیں","",{"u2":"عیسیٰ بن یونس، وکیع اور ابن نمیر سب نے ہشام بن عروہ سے حدیث بیان کی، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: کاش لوگ تہائی سے کم کر کے چوتھائی کی وصیت کریں کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"تہائی (تک کی وصیت کرو)، اور تہائی بھی زیادہ ہے\nوکیع کی حدیث میں \"بڑا ہے\" یا \"زیادہ ہے\" کے الفاظ ہیں"}],[4202,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے نبی صلی اللہ علیہ وسلم سے عرض کی : میرے والد فوت ہو گئے ہیں ، انہوں نے مال چھوڑا ہے اور وصیت نہیں کی ، اگر ( یہ مال ) ان کی طرف سے صدقہ کر دیا جائے تو کیا ( یہ ) ان کی طرف سے کفارہ بنے گا؟ آپ نے فرمایا : \" ہاں","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے نبی صلی اللہ علیہ وسلم سے عرض کی: میرے والد فوت ہو گئے ہیں، انہوں نے مال چھوڑا ہے اور وصیت نہیں کی، اگر (یہ مال) ان کی طرف سے صدقہ کر دیا جائے تو کیا (یہ) ان کی طرف سے کفارہ بنے گا؟ آپ نے فرمایا: \"ہاں"}],[4203,"یحییٰ بن سعید نے ہمیں ہشام بن عروہ سے حدیث بیان کی ، کہا : مجھے میرے والد نے سیدہ عائشہ سے خبر دی کہ ایک آدمی نے نبی صلی اللہ علیہ وسلم سے عرض کی : میری والدہ اچانک وفات پا گئیں ، مجھے ان کے بارے میں یقین ہے کہ اگر وہ بات کرتیں تو صدقہ کرتیں ، اگر میں ان کی طرف سے صدقہ کر دوں تو کیا میرے لیے اجر ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" ہاں","",{"u2":"یحییٰ بن سعید نے ہمیں ہشام بن عروہ سے حدیث بیان کی، کہا: مجھے میرے والد نے حضرت عائشہ سے خبر دی کہ ایک آدمی نے نبی صلی اللہ علیہ وسلم سے عرض کی: میری والدہ اچانک وفات پا گئیں، مجھے ان کے بارے میں یقین ہے کہ اگر وہ بات کرتیں تو صدقہ کرتیں، اگر میں ان کی طرف سے صدقہ کر دوں تو کیا میرے لیے اجر ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں"}],[4204,"محمد بن بشر نے ہمیں حدیث بیان کی ، کہا : ہمیں ہشام نے اپنے والد سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے حدیث بیان کی کہ ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا اور کہا : اللہ کے رسول! میری والدہ اچانک فوت ہو گئی ہیں اور وصیت نہیں کر سکیں ، مجھے ان کے بارے میں یقین ہے کہ اگر وہ کلام کرتیں تو ضرور صدقہ کرتیں ، اگر میں ان کی طرف سے صدقہ کر دوں تو کیا ان کے لیے اجر ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" ہاں","",{"u2":"محمد بن بشر نے ہمیں حدیث بیان کی، کہا: ہمیں ہشام نے اپنے والد سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے حدیث بیان کی کہ ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا اور کہا: اللہ کے رسول! میری والدہ اچانک فوت ہو گئی ہیں اور وصیت نہیں کر سکیں، مجھے ان کے بارے میں یقین ہے کہ اگر وہ کلام کرتیں تو ضرور صدقہ کرتیں، اگر میں ان کی طرف سے صدقہ کر دوں تو کیا ان کے لیے اجر ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں"}],[4205,"ابواسامہ ، شعیب بن اسحاق ، روح بن قاسم اور جعفر بن عون ، سب نے ہشام بن عروہ سے اسی سند کے ساتھ حدیث بیان کی ۔ ابواسامہ اور روح کی حدیث میں ہے : کیا میرے لیے اجر ہے؟ جس طرح یحییٰ بن سعید نے کہا ۔ اور شعیب اور جعفر کی حدیث میں ہے : کیا ان کے لیے اجر ہے؟ جس طرح ابن بشیر کی روایت ہے","",{"u2":"ابواسامہ، شعیب بن اسحاق، روح بن قاسم اور جعفر بن عون، سب نے ہشام بن عروہ سے اسی سند کے ساتھ حدیث بیان کی۔ ابواسامہ اور روح کی حدیث میں ہے: کیا میرے لیے اجر ہے؟ جس طرح یحییٰ بن سعید نے کہا۔ اور شعیب اور جعفر کی حدیث میں ہے: کیا ان کے لیے اجر ہے؟ جس طرح ابن بشیر کی روایت ہے"}],[4206,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب انسان فوت ہو جائے تو اس کا عمل منقطع ہو جاتا ہے سوائے تین اعمال کے ( وہ منقطع نہیں ہوتے ) : صدقہ جاریہ یا ایسا علم جس سے فائدہ اٹھایا جائے یا نیک بیٹا جو اس کے لیے دعا کرے","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب انسان فوت ہو جائے تو اس کا عمل منقطع ہو جاتا ہے سوائے تین اعمال کے (وہ منقطع نہیں ہوتے): صدقہ جاریہ یا ایسا علم جس سے فائدہ اٹھایا جائے یا نیک بیٹا جو اس کے لیے دعا کرے"}],[4207,"سُلیم بن اخضر نے ہمیں ابن عون سے خبر دی ، انہوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : سیدنا عمر رضی اللہ عنہ کو خیبر میں زمین ملی ، وہ اس کے بارے میں مشورہ کرنے کے لیے نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی : اے اللہ کے رسول! مجھے خیبر میں زمین ملی ہے ، مجھے کبھی کوئی ایسا مال نہیں ملا جو میرے نزدیک اس سے زیادہ عمدہ ہو ، تو آپ مجھے اس کے بارے میں کیا حکم دیتے ہیں؟ آپ نے فرمایا : \"\" اگر تم چاہو تو اس کی اصل وقف کر دو اور اس ( کی آمدنی ) سے صدقہ کرو ۔ \"\" کہا : سیدنا عمر رضی اللہ عنہ نے اسے ( اس شرط کے ساتھ ) صدقہ کیا کہ اس کی اصل نہ بیچی جائے ، نہ اسے خریدا جائے ، نہ ورثے میں حاصل کی جائے اور نہ ہبہ کی جائے ۔ کہا : سیدنا عمر رضی اللہ عنہ نے اس ( کی آمدنی ) کو فقراء ، اقرباء ، غلاموں ، فی سبیل اللہ ، مسافروں اور مہمانوں میں صدقہ کیا اور ( قرار دیا کہ ) اس شخص پر کوئی گناہ نہیں جو اس کا نگران ہے کہ وہ اس میں تمول حاصل کیے ( مالدار بنے ) بغیر معروف طریقے سے اس میں سے خود کھائے یا کسی دوست کو کھلائے ۔ ( ابن عون نے ) کہا : میں نے یہ حدیث محمد ( بن سیرین ) کو بیان کی ، جب میں اس جگہ \"\" اس میں تمول حاصل کیے بغیر \"\" پر پہنچا تو محمد نے ( ان الفاظ کے بجائے ) \"\" مال جمع کیے بغیر کے الفاظ کہے ۔ ابن عون نے کہا : مجھے اس شخص نے خبر دی جس نے اس کتاب ( لکھے ہوئے وصیت نامے ) کو پڑھا تھا کہ اس میں \"\" مال جمع کیے بغیر \"\" کے الفاظ ہیں","",{"u2":"سُلیم بن اخضر نے ہمیں ابن عون سے خبر دی، انہوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: سیدنا عمر رضی اللہ عنہ کو خیبر میں زمین ملی، وہ اس کے بارے میں مشورہ کرنے کے لیے نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی: اے اللہ کے رسول! مجھے خیبر میں زمین ملی ہے، مجھے کبھی کوئی ایسا مال نہیں ملا جو میرے نزدیک اس سے زیادہ عمدہ ہو، تو آپ مجھے اس کے بارے میں کیا حکم دیتے ہیں؟ آپ نے فرمایا: \"اگر تم چاہو تو اس کی اصل وقف کر دو اور اس (کی آمدنی) سے صدقہ کرو۔\" کہا: سیدنا عمر رضی اللہ عنہ نے اسے (اس شرط کے ساتھ) صدقہ کیا کہ اس کی اصل نہ بیچی جائے، نہ اسے خریدا جائے، نہ ورثے میں حاصل کی جائے اور نہ ہبہ کی جائے۔ کہا: سیدنا عمر رضی اللہ عنہ نے اس (کی آمدنی) کو فقراء، اقرباء، غلاموں، فی سبیل اللہ، مسافروں اور مہمانوں میں صدقہ کیا اور (قرار دیا کہ) اس شخص پر کوئی گناہ نہیں جو اس کا نگران ہے کہ وہ اس میں تمول حاصل کیے (مالدار بنے) بغیر معروف طریقے سے اس میں سے خود کھائے یا کسی دوست کو کھلائے۔\n(ابن عون نے) کہا: میں نے یہ حدیث محمد (بن سیرین) کو بیان کی، جب میں اس جگہ \"اس میں تمول حاصل کیے بغیر\" پر پہنچا تو محمد نے (ان الفاظ کے بجائے) \"مال جمع کیے بغیر کے الفاظ کہے۔\nابن عون نے کہا: مجھے اس شخص نے خبر دی جس نے اس کتاب (لکھے ہوئے وصیت نامے) کو پڑھا تھا کہ اس میں \"مال جمع کیے بغیر\" کے الفاظ ہیں"}],[4208,"ابن ابی زائدہ ، ازہر سمان اور ابن ابی عدی سب نے ابن عون سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی ، البتہ ابن ابی زائدہ اور ازہر کی حدیث سیدنا عمر رضی اللہ عنہ کے اس قول پر ختم ہو گئی : \" یا تمول حاصل کیے بغیر کسی دوست کو کھلائے ۔ \" اس کے بعد والا حصہ بیان نہیں کیا ۔ اور ابن ابی عدی کی حدیث میں وہ قول ہے جو سلیم نے ذکر کیا کہ میں نے یہ حدیث محمد ( بن سیرین ) کو بیان کی ، آخر تک","",{"u2":"ابن ابی زائدہ، ازہر سمان اور ابن ابی عدی سب نے ابن عون سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی، البتہ ابن ابی زائدہ اور ازہر کی حدیث سیدنا عمر رضی اللہ عنہ کے اس قول پر ختم ہو گئی: \"یا تمول حاصل کیے بغیر کسی دوست کو کھلائے۔\" اس کے بعد والا حصہ بیان نہیں کیا۔ اور ابن ابی عدی کی حدیث میں وہ قول ہے جو سلیم نے ذکر کیا کہ میں نے یہ حدیث محمد (بن سیرین) کو بیان کی، آخر تک"}],[4209,"سفیان نے ابن عون سے ، انہوں نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے سیدنا عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : مجھے خیبر کی زمینوں سے ایک زمین ملی ، میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور کہا : مجھے ایک زمین ملی ہے ، مجھے کبھی کوئی مال ایسا نہیں ملا جو مجھے اس سے زیادہ محبوب اور میرے نزدیک اس سے زیادہ عمدہ ہو انہوں نے ان سب کی حدیث کی طرح بیان کیا اور انہوں نے میں نے یہ حدیث محمد کو بیان کی اور اس کے بعد والا حصہ بیان نہیں کیا","",{"u2":"سفیان نے ابن عون سے، انہوں نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے سیدنا عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا:مجھے خیبر کی زمینوں سے ایک زمین ملی، میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور کہا: مجھے ایک زمین ملی ہے، مجھے کبھی کوئی مال ایسا نہیں ملا جو مجھے اس سے زیادہ محبوب اور میرے نزدیک اس سے زیادہ عمدہ ہوانہوں نے ان سب کی حدیث کی طرح بیان کیا اور انہوں نےمیں نے یہ حدیث محمد کو بیان کی اور اس کے بعد والا حصہ بیان نہیں کیا"}],[4210,"عبدالرحمان بن مہدی نے ہمیں مالک بن مغول سے خبر دی اور انہوں نے طلحہ بن مصرف سے روایت کی ، انہوں نے کہا : میں نے سیدنا عبداللہ بن ابی اوفیٰ رضی اللہ عنہ سے پوچھا : کیا رسول اللہ صلی اللہ علیہ وسلم نے وصیت کی؟ انہوں نے جواب دیا : نہیں ۔ میں نے پوچھا : تو مسلمانوں پر وصیت کرنا کیوں فرض کیا گیا ہے یا انہیں وصیت کا حکم کیوں دیا گیا ہے؟ انہوں نے جواب دیا : آپ صلی اللہ علیہ وسلم نے ( ترکے کو تقسیم کرنے کی وصیت نہیں کی بلکہ ) اللہ تعالیٰ کی کتاب ( کو اپنانے ، عمل کرنے ) کی وصیت کی","",{"u2":"عبدالرحمان بن مہدی نے ہمیں مالک بن مغول سے خبر دی اور انہوں نے طلحہ بن مصرف سے روایت کی، انہوں نے کہا: میں نے سیدنا عبداللہ بن ابی اوفیٰ رضی اللہ عنہ سے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم نے وصیت کی؟ انہوں نے جواب دیا: نہیں۔ میں نے پوچھا: تو مسلمانوں پر وصیت کرنا کیوں فرض کیا گیا ہے یا انہیں وصیت کا حکم کیوں دیا گیا ہے؟ انہوں نے جواب دیا: آپ صلی اللہ علیہ وسلم نے (ترکے کو تقسیم کرنے کی وصیت نہیں کی بلکہ) اللہ تعالیٰ کی کتاب (کو اپنانے، عمل کرنے) کی وصیت کی"}],[4211,"وکیع اور ابن نمیر دونوں نے مالک بن مغول سے اسی سند کے ساتھ اسی طرح حدیث بیان کی ، البتہ وکیع کی حدیث میں ہے : میں نے پوچھا : تو لوگوں کو وصیت کا کیسے حکم دیا گیا ہے؟ اور ابن نمیر کی حدیث میں ہے : میں نے پوچھا : مسلمانوں پر وصیت کیسے فرض کی گئی ہے","",{"u2":"وکیع اور ابن نمیر دونوں نے مالک بن مغول سے اسی سند کے ساتھ اسی طرح حدیث بیان کی، البتہ وکیع کی حدیث میں ہے: میں نے پوچھا: تو لوگوں کو وصیت کا کیسے حکم دیا گیا ہے؟ اور ابن نمیر کی حدیث میں ہے: میں نے پوچھا: مسلمانوں پر وصیت کیسے فرض کی گئی ہے"}],[4212,"عبداللہ بن نمیر اور ابومعاویہ دونوں نے کہا : ہمیں اعمش نے ابووائل سے حدیث بیان کی ، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے نہ کوئی دینار ترکہ میں چھوڑا نہ درہم ، نہ کوئی بکری ، نہ اونٹ اور نہ ہی آپ نے ( اس طرح کی ) کسی چیز کے بارے میں وصیت کی","",{"u2":"عبداللہ بن نمیر اور ابومعاویہ دونوں نے کہا: ہمیں اعمش نے ابووائل سے حدیث بیان کی، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے نہ کوئی دینار ترکہ میں چھوڑا نہ درہم، نہ کوئی بکری، نہ اونٹ اور نہ ہی آپ نے (اس طرح کی) کسی چیز کے بارے میں وصیت کی"}],[4213,"جریر اور عیسیٰ بن یونس نے اعمش سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی","",{"u2":"جریر اور عیسیٰ بن یونس نے اعمش سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی"}],[4214,"اسود بن یزید سے روایت ہے ، انہوں نے کہا : لوگوں نے سیدہ عائشہ رضی اللہ عنہا کے پاس ذکر کیا کہ سیدنا علی رضی اللہ عنہ وصی ( جسے وصیت کی جائے ) تھے ۔ تو انہوں نے کہا : آپ صلی اللہ علیہ وسلم نے انہیں کب وصیت کی؟ بلاشبہ آپ کو اپنے سینے سے ۔ ۔ یا کہا : اپنی گود سے ۔ ۔ سہارا دینے والی میں تھی ، آپ نے برتن منگوایا ، اس کے بعد آپ ( کمزوری سے ) میری گود ہی میں جھک گئے اور مجھے پتہ بھی نہ چلا کہ آپ کی وفات ہو گئی ، تو آپ نے انہیں کب وصیت کی","",{"u2":"اسود بن یزید سے روایت ہے، انہوں نے کہا: لوگوں نے سیدہ عائشہ رضی اللہ عنہا کے پاس ذکر کیا کہ سیدنا علی رضی اللہ عنہ وصی (جسے وصیت کی جائے) تھے۔ تو انہوں نے کہا: آپ صلی اللہ علیہ وسلم نے انہیں کب وصیت کی؟ بلاشبہ آپ کو اپنے سینے سے۔۔ یا کہا: اپنی گود سے۔۔ سہارا دینے والی میں تھی، آپ نے برتن منگوایا، اس کے بعد آپ (کمزوری سے) میری گود ہی میں جھک گئے اور مجھے پتہ بھی نہ چلا کہ آپ کی وفات ہو گئی، تو آپ نے انہیں کب وصیت کی"}],[4215,"ہمیں سعید بن منصور ، قتیبہ بن سعید ، ابوبکر بن ابی شیبہ اور عمرو ناقد نے حدیث بیان کی ۔ ۔ الفاظ سعید کے ہیں ۔ ۔ سب نے کہا : ہمیں سفیان نے سلیمان احول سے حدیث بیان کی ، انہوں نے سعید بن جبیر سے روایت کی ، انہوں نے کہا : سیدنا ابن عباس رضی اللہ عنہ نے کہا : جمعرات کا دن ، اور جمعرات کا دن کیسا تھا! پھر وہ رونے لگے یہاں تک کہ ان کے آنسوؤں نے سنگریزوں کو تر کر دیا ۔ میں نے کہا : ابوعباس! جمعرات کا دن کیا تھا؟ انہون نے کہا : رسول اللہ صلی اللہ علیہ وسلم کا مرض شدت اختیار کر گیا تو آپ نے فرمایا : \"\" میرے پاس ( لکھنے کا سامان ) لاؤ ، میں تمہیں ایک کتاب ( تحریر ) لکھ دوں تاکہ تم میرے بعد گمراہ نہ ہو ۔ \"\" تو لوگ جھگڑ پڑے ، اور کسی بھی نبی کے پاس جھگڑنا مناسب نہیں ۔ انہوں نے کہا : آپ کا کیا حال ہے؟ کیا آپ نے بیماری کے زیر اثر گفتگو کی ہے؟ آپ ہی سے اس کا مفہوم پوچھو! آپ نے فرمایا : \"\" مجھے چھوڑ دو ، میں جس حالت میں ہوں وہ بہتر ہے ۔ میں تمہیں تین چیزوں کی وصیت کرتا ہوں؛ مشرکوں کو جزیرہ عرب سے نکال دینا اور آنے والے وفود کو اسی طرح عطیے دینا جس طرح میں انہیں دیا کرتا تھا ۔ \"\" ( سلیمان احول نے ) کہا : وہ ( سعید بن جبیر ) تیسری بات کہنے سے خاموش ہو گئے یا انہوں نے کہی اور میں اسے بھول گیا ۔ ابواسحاق ابراہیم نے کہا : ہمیں حسن بن بشر نے حدیث بیان کی ، کہا : ہمیں سفیان نے یہی حدیث بیان کي","",{"u2":"ہمیں سعید بن منصور،قتیبہ بن سعید، ابوبکر بن ابی شیبہ اور عمرو ناقد نے حدیث بیان کی۔۔ الفاظ سعید کے ہیں۔۔ سب نے کہا: ہمیں سفیان نے سلیمان احول سے حدیث بیان کی، انہوں نے سعید بن جبیر سے روایت کی، انہوں نے کہا: سیدنا ابن عباس رضی اللہ عنہ نے کہا: جمعرات کا دن، اور جمعرات کا دن کیسا تھا! پھر وہ رونے لگے یہاں تک کہ ان کے آنسوؤں نے سنگریزوں کو تر کر دیا۔ میں نے کہا: ابوعباس! جمعرات کا دن کیا تھا؟ انہون نے کہا: رسول اللہ صلی اللہ علیہ وسلم کا مرض شدت اختیار کر گیا تو آپ نے فرمایا: \"میرے پاس (لکھنے کا سامان) لاؤ، میں تمہیں ایک کتاب (تحریر) لکھ دوں تاکہ تم میرے بعد گمراہ نہ ہو۔\" تو لوگ جھگڑ پڑے، اور کسی بھی نبی کے پاس جھگڑنا مناسب نہیں۔ انہوں نے کہا: آپ کا کیا حال ہے؟ کیا آپ نے بیماری کے زیر اثر گفتگو کی ہے؟ آپ ہی سے اس کا مفہوم پوچھو! آپ نے فرمایا: \"مجھے چھوڑ دو، میں جس حالت میں ہوں وہ بہتر ہے۔ میں تمہیں تین چیزوں کی وصیت کرتا ہوں؛ مشرکوں کو جزیرہ عرب سے نکال دینا اور آنے والے وفود کو اسی طرح عطیے دینا جس طرح میں انہیں دیا کرتا تھا۔\" (سلیمان احول نے) کہا: وہ (سعید بن جبیر) تیسری بات کہنے سے خاموش ہو گئے یا انہوں نے کہی اور میں اسے بھول گیا۔\nابواسحاق ابراہیم نے کہا: ہمیں حسن بن بشر نے حدیث بیان کی، کہا: ہمیں سفیان نے یہی حدیث بیان کی"}],[4216,"ہمیں سعید بن منصور ، قتیبہ بن سعید ، ابوبکر بن ابی شیبہ اور عمرو ناقد نے حدیث بیان کی ۔ ۔ الفاظ سعید کے ہیں ۔ ۔ سب نے کہا : ہمیں سفیان نے سلیمان احول سے حدیث بیان کی ، انہوں نے سعید بن جبیر سے روایت کی ، انہوں نے کہا : سیدنا ابن عباس رضی اللہ عنہ نے کہا : جمعرات کا دن ، اور جمعرات کا دن کیسا تھا! پھر وہ رونے لگے یہاں تک کہ ان کے آنسوؤں نے سنگریزوں کو تر کر دیا ۔ میں نے کہا : ابوعباس! جمعرات کا دن کیا تھا؟ انہون نے کہا : رسول اللہ صلی اللہ علیہ وسلم کا مرض شدت اختیار کر گیا تو آپ نے فرمایا : \"\" میرے پاس ( لکھنے کا سامان ) لاؤ ، میں تمہیں ایک کتاب ( تحریر ) لکھ دوں تاکہ تم میرے بعد گمراہ نہ ہو ۔ \"\" تو لوگ جھگڑ پڑے ، اور کسی بھی نبی کے پاس جھگڑنا مناسب نہیں ۔ انہوں نے کہا : آپ کا کیا حال ہے؟ کیا آپ نے بیماری کے زیر اثر گفتگو کی ہے؟ آپ ہی سے اس کا مفہوم پوچھو! آپ نے فرمایا : \"\" مجھے چھوڑ دو ، میں جس حالت میں ہوں وہ بہتر ہے ۔ میں تمہیں تین چیزوں کی وصیت کرتا ہوں؛ مشرکوں کو جزیرہ عرب سے نکال دینا اور آنے والے وفود کو اسی طرح عطیے دینا جس طرح میں انہیں دیا کرتا تھا ۔ \"\" ( سلیمان احول نے ) کہا : وہ ( سعید بن جبیر ) تیسری بات کہنے سے خاموش ہو گئے یا انہوں نے کہی اور میں اسے بھول گیا ۔ ابواسحاق ابراہیم نے کہا : ہمیں حسن بن بشر نے حدیث بیان کی ، کہا : ہمیں سفیان نے یہی حدیث بیان کي",""],[4217,"طلحہ بن مُصرف نے سعید بن جبیر سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا : جمعرات کا دن ، جمعرات کا دن کیسا تھا! پھر ان کے آنسو بہنے لگے حتی کہ میں نے ان کے دونوں رخساروں پر دیکھا گویا موتیوں کی لڑی ہو ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" میرے پاس شانے کی ہڈی اور دوات لاؤ ۔ ۔ یا تختی اور دوات ۔ ۔ میں تمہیں ایک کتاب ( تحریر ) لکھ دوں ، اس کے بعد تم ہرگز کبھی گمراہ نہ ہو گے ۔ \" تو لوگوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم بیماری کے زیر اثر گفتگو فرما رہے ہیں","",{"u2":"طلحہ بن مُصرف نے سعید بن جبیر سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا: جمعرات کا دن، جمعرات کا دن کیسا تھا! پھر ان کے آنسو بہنے لگے حتی کہ میں نے ان کے دونوں رخساروں پر دیکھا گویا موتیوں کی لڑی ہو، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میرے پاس شانے کی ہڈی اور دوات لاؤ۔۔ یا تختی اور دوات۔۔ میں تمہیں ایک کتاب (تحریر) لکھ دوں، اس کے بعد تم ہرگز کبھی گمراہ نہ ہو گے۔\" تو لوگوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم بیماری کے زیر اثر گفتگو فرما رہے ہیں"}],[4218,"عبیداللہ بن عبداللہ بن عتبہ نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : جب رسول اللہ صلی اللہ علیہ وسلم کی وفات کا وقت قریب آیا ، گھر میں کچھ آدمی موجود تھے ، ان میں عمر بن خطاب رضی اللہ عنہ بھی تھے ، تو نبی صلی اللہ علیہ وسلم نے فرمایا : \"\" میرے پاس آؤ ، میں تمہیں ایک کتاب ( تحریر ) لکھ دوں ، اس کے بعد تم گمراہ نہیں ہو گے ۔ \"\" تو سیدنا عمر رضی اللہ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم پر تکلیف اور درد کا غلبہ ہے اور تمہارے پاس قرآن موجود ہے ، ہمیں اللہ کی کتاب کافی ہے ۔ اس پر گھر کے افراد نے اختلاف کیا اور جھگڑ پڑے ، ان میں سے کچھ کہہ رہے تھے : ( لکھنے کا سامان ) قریب لاؤ ، رسول اللہ صلی اللہ علیہ وسلم تمہیں کتاب لکھ دیں تاکہ اس کے بعد تم کبھی گمراہ نہ ہو ۔ اور ان میں سے کچھ وہی کہہ رہے تھے جو سیدنا عمر رضی اللہ عنہ نے کہا تھا ۔ جب انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس زیادہ شور اور اختلاف کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" اٹھ جاؤ ۔ \"\" عبیداللہ نے کہا : سیدنا ابن عباس رضی اللہ عنہ کہا کرتے تھے : یقینا مصیبت تھی بڑی مصیبت جو ان کے اختلاف اور شور کی وجہ سے رسول اللہ صلی اللہ علیہ وسلم اور آپ کے وہ تحریر لکھنے کے درمیان حائل ہو گئی ( کہ آپ کتابت نہ کرا سکے)","",{"u2":"عبیداللہ بن عبداللہ بن عتبہ نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: جب رسول اللہ صلی اللہ علیہ وسلم کی وفات کا وقت قریب آیا، گھر میں کچھ آدمی موجود تھے، ان میں عمر بن خطاب رضی اللہ عنہ بھی تھے، تو نبی صلی اللہ علیہ وسلم نے فرمایا: \"میرے پاس آؤ، میں تمہیں ایک کتاب (تحریر) لکھ دوں، اس کے بعد تم گمراہ نہیں ہو گے۔\" تو سیدنا عمر رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم پر تکلیف اور درد کا غلبہ ہے اور تمہارے پاس قرآن موجود ہے، ہمیں اللہ کی کتاب کافی ہے۔ اس پر گھر کے افراد نے اختلاف کیا اور جھگڑ پڑے، ان میں سے کچھ کہہ رہے تھے: (لکھنے کا سامان) قریب لاؤ، رسول اللہ صلی اللہ علیہ وسلم تمہیں کتاب لکھ دیں تاکہ اس کے بعد تم کبھی گمراہ نہ ہو۔ اور ان میں سے کچھ وہی کہہ رہے تھے جو سیدنا عمر رضی اللہ عنہ نے کہا تھا۔ جب انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس زیادہ شور اور اختلاف کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اٹھ جاؤ۔\"\nعبیداللہ نے کہا: سیدنا ابن عباس رضی اللہ عنہ کہا کرتے تھے: یقینا مصیبت تھی بڑی مصیبت جو ان کے اختلاف اور شور کی وجہ سے رسول اللہ صلی اللہ علیہ وسلم اور آپ کے وہ تحریر لکھنے کے درمیان حائل ہو گئی (کہ آپ کتابت نہ کرا سکے"}],[4219,"لیث نے ہمیں ابن شہاب سے حدیث بیان کی ، انہوں نے عبیداللہ بن عبداللہ سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا : سیدنا سعد بن عبادہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اس نذر کے بارے میں فتویٰ پوچھا جو ان کی والدہ کے ذمہ تھی ، وہ اسے پورا کرنے سے پہلے ہی فوت ہو گئی تھیں ، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اسے ان کی طرف سے تم پورا کرو ۔","",{"u2":") لیث نے ہمیں ابن شہاب سے حدیث بیان کی، انہوں نے عبیداللہ بن عبداللہ سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا: سیدنا سعد بن عبادہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اس نذر کے بارے میں فتویٰ پوچھا جو ان کی والدہ کے ذمہ تھی، وہ اسے پورا کرنے سے پہلے ہی فوت ہو گئی تھیں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے ان کی طرف سے تم پورا کرو۔\""}],[4220,"امام مالک ، ابن عیینہ ، یونس ، معمر اور بکر بن وائل سب نے زہری سے لیث کی مذکورہ سند کے ساتھ ، انہی کی حدیث کے ہم معنیٰ حدیث بیان کی","",{"u2":"امام مالک، ابن عیینہ، یونس، معمر اور بکر بن وائل سب نے زہری سے لیث کی مذکورہ سند کے ساتھ، انہی کی حدیث کے ہم معنیٰ حدیث بیان کی"}],[4221,"جریر نے منصور سے ، انہوں نے عبداللہ بن مرہ سے اور انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم ایک دن ہمیں نذر سے منع کرنے لگے ، آپ فرمانے لگے : \" یہ کسی چیز کو نہیں ٹالتی ، اس کے ذریعے سے تو بخیل سے ( اللہ کی راہ میں کچھ ) نکلوایا جاتا ہے","",{"u2":"جریر نے منصور سے، انہوں نے عبداللہ بن مرہ سے اور انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ایک دن ہمیں نذر سے منع کرنے لگے، آپ فرمانے لگے: \"یہ کسی چیز کو نہیں ٹالتی، اس کے ذریعے سے تو بخیل سے (اللہ کی راہ میں کچھ) نکلوایا جاتا ہے"}],[4222,"عبداللہ بن دینار نے سیدنا ابن عمر رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" نذر کسی چیز کو آگے کرتی ہے نہ پیچھے ، اس کے ذریعے سے تو بخیل سے ( مال ) نکلوایا جاتا ہے","",{"u2":"عبداللہ بن دینار نے سیدنا ابن عمر رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نذر کسی چیز کو آگے کرتی ہے نہ پیچھے، اس کے ذریعے سے تو بخیل سے (مال) نکلوایا جاتا ہے"}],[4223,"شعبہ نے ہمیں منصور سے حدیث بیان کی ، انہوں نے عبداللہ بن مرہ سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے نذر سے منع کیا اور فرمایا : \" بلاشبہ یہ کوئی خیر لے کر نہیں آتی ، اس کے ذریعے سے تو بخیل سے ( کچھ ) نکلوایا جاتا ہے","",{"u2":"شعبہ نے ہمیں منصور سے حدیث بیان کی، انہوں نے عبداللہ بن مرہ سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے نذر سے منع کیا اور فرمایا: \"بلاشبہ یہ کوئی خیر لے کر نہیں آتی، اس کے ذریعے سے تو بخیل سے (کچھ) نکلوایا جاتا ہے"}],[4224,"مفضل اور سفیان دونوں نے منصور سے اسی سند کے ساتھ جریر کی حدیث کی طرح حدیث بیان کی","",{"u2":"مفضل اور سفیان دونوں نے منصور سے اسی سند کے ساتھ جریر کی حدیث کی طرح حدیث بیان کی"}],[4225,"عبدالعزیز دراوردی نے ہمیں علاء سے حدیث بیان کی ، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" نذر نہ مانا کرو ، نذر تقدیر کے معاملے میں کوئی فائدہ نہیں دیتی ، اس کے ذریعے سے تو بخیل سے ( مال ) نکلوایا جاتا ہے","",{"u2":"عبدالعزیز دراوردی نے ہمیں علاء سے حدیث بیان کی، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نذر نہ مانا کرو، نذر تقدیر کے معاملے میں کوئی فائدہ نہیں دیتی، اس کے ذریعے سے تو بخیل سے (مال) نکلوایا جاتا ہے"}],[4226,"شعبہ نے ہمیں حدیث بیان کی ، کہا : میں نے علاء سے سنا ، وہ اپنے والد سے اور وہ سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کر رہے تھے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے منت ماننے سے منع کیا اور فرمایا : \" یہ تقدیر کے کسی فیصلے کو نہیں ٹال سکتی ، اس کے ذریعے سے تو بخیل سے ( مال ) نکلوایا جاتا ہے","",{"u2":"شعبہ نے ہمیں حدیث بیان کی، کہا: میں نے علاء سے سنا، وہ اپنے والد سے اور وہ سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کر رہے تھے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے منت ماننے سے منع کیا اور فرمایا: \"یہ تقدیر کے کسی فیصلے کو نہیں ٹال سکتی، اس کے ذریعے سے تو بخیل سے (مال) نکلوایا جاتا ہے"}],[4227,"اسماعیل بن جعفر نے ہمیں عمرو بن ابی عمرو سے حدیث بیان کی ، انہوں نے عبدالرحمان اعرج سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" بلاشبہ نذر کسی چیز کو ابن آدم کے قریب نہیں کرتی ، جو اللہ نے اس کے لیے مقدر نہیں کی ، بلکہ نذر تقدیر کے ساتھ موافقت کرتی ہے ، اس کے ذریعے سے بخیل سے وہ کچھ نکلوایا جاتا ہے جسے بخیل نکالنا نہیں چاہتا","",{"u2":"اسماعیل بن جعفر نے ہمیں عمرو بن ابی عمرو سے حدیث بیان کی، انہوں نے عبدالرحمان اعرج سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"بلاشبہ نذر کسی چیز کو ابن آدم کے قریب نہیں کرتی، جو اللہ نے اس کے لیے مقدر نہیں کی، بلکہ نذر تقدیر کے ساتھ موافقت کرتی ہے، اس کے ذریعے سے بخیل سے وہ کچھ نکلوایا جاتا ہے جسے بخیل نکالنا نہیں چاہتا"}],[4228,"عقوب بن عبدالرحمان القاری اور عبدالعزیز دراوردی دونوں نے عمرو بن ابی عمرو سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی","",{"u2":"عقوب بن عبدالرحمان القاری اور عبدالعزیز دراوردی دونوں نے عمرو بن ابی عمرو سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی"}],[4229,"مجھے زہیر بن حرب اور علی بن حجر سعدی نے حدیث بیان کی ۔ ۔ الفاظ زہیر کے ہیں ۔ ۔ ان دونوں نے کہا ہمیں اسماعیل بن ابراہیم نے حدیث سنائی ، کہا : ہمیں ایوب نے ابوقلابہ سے حدیث بیان کی ، انہوں نے ابومہلب سے اور انہوں نے سیدنا عمران بن حصین رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ثقیف ، بنو عقیل کے حلیف تھے ، ثقیف نے رسول اللہ صلی اللہ علیہ وسلم کے اصحاب میں سے دو آدمیوں کو قید کر لیا ، ( بدلے میں ) رسول اللہ صلی اللہ علیہ وسلم کے اصحاب نے بنو عقیل کے ایک آدمی کو قیدی بنا لیا اور انہوں نے اس کے ساتھ اونٹنی عضباء بھی حاصل کر لی ، رسول اللہ صلی اللہ علیہ وسلم اس آدمی کے پاس سے گزرے ، وہ بندھا ہوا تھا ، اس نے کہا : اے محمد! آپ صلی اللہ علیہ وسلم اس کے پاس آئے اور پوچھا : \"\" کیا بات ہے؟ \"\" اس نے کہا : آپ نے مجھے کس وجہ سے پکڑا ہوا اور حاجیوں ( کی سواریوں ) سے سبقت لے جانے والی اونٹنی کو کیوں پکڑا ہے؟ آپ نے ۔ ۔ اس معاملے کو سنگین خیال کرتے ہوئے ۔ ۔ جواب دیا : \"\" میں نے تمہیں تمہارے حلیف ثقیف کے جرم کی بنا پر ( اس کے ازالے کے لیے ) پکڑا ہے ۔ \"\" پھر آپ وہاں سے پلٹے تو اس نے ( پھر سے ) آپ کو آواز دی اور کہا : اے محمد! اے محمد ( صلی اللہ علیہ وسلم ) ! رسول اللہ صلی اللہ علیہ وسلم بہت رحم کرنے والے ، نرم دل تھے ۔ پھر سے آپ اس کے پاس واپس آئے اور فرمایا : \"\" کیا بات ہے؟ \"\" اس نے کہا : ( اب ) میں مسلمان ہوں ۔ آپ نے فرمایا : اگر تم یہ بات اس وقت کہتے جب تم اپنے مالک آپ تھے ( آزاد تھے ) تو تم پوری بھلائی حاصل کر لیتے ( اب بھی ملے گی لیکن پوری نہ ہو گی ۔ ) \"\" پھر آپ پلٹے تو اس نے آپ کو آواز دی اور کہا : اے محمد! اے محمد ( صلی اللہ علیہ وسلم ) ! آپ ( پھر ) اس کے پاس آئے اور پوچھا : \"\" کیا بات ہے؟ \"\" اس نے کہا : میں بھوکا ہوں مجھے ( کھانا ) کھلائیے اور پیاسا ہوں مجھے ( پانی ) پلائیے ۔ آپ نے فرمایا : \"\" ( ہاں ) یہ تمہاری ( فورا پوری کی جانے والی ) ضرورت ہے ۔ \"\" اس کے بعد ( معاملات طے کر کے ) اسے دونوں آدمیوں کے بدلے میں چھوڑ دیا گیا ۔ ( اونٹنی پیچھے رہ گئی اور رسول اللہ صلی اللہ علیہ وسلم کے حصے میں آئی ۔ لیکن مشرکین نے دوبارہ حملے کر کے پھر اسے اپنے قبضے میں لے لیا ۔ ) کہا : ( بعد میں ، غزوہ ذات القرد کے موقع پر ، مدینہ پر حملے کے دوران ) ایک انصاری عورت قید کر لی گئی اور عضباء اونٹنی بھی پکڑ لی گئی ، عورت بندھنوں میں ( جکڑی ہوئی ) تھی ۔ لوگ اپنے اونٹ اپنے گھروں کے سامنے رات کو آرام ( کرنے کے لیے بٹھا ) دیتے تھے ، ایک رات وہ ( خاتون ) اچانک بیڑیوں ( بندھنوں ) سے نکل بھاگی اور اونٹوں کے پاس آئی ، وہ ( سواری کے لیے ) جس اونٹ کے بھی قریب جاتی وہ بلبلانے لگتا تو وہ اسے چھوڑ دیتی حتی کہ وہ عضباء تک پہنچ گئی تو وہ نہ بلبلائی ، کہا : وہ سدھائی ہوئی اونٹنی تھی تو وہ اس کی پیٹھ کے پچھلے حصے پر بیٹھی ، اور اسے دوڑایا تو وہ چل پڑی ۔ لوگوں کو اس ( کے جانے ) کا علم ہو گیا ، انہوں نے اس کا تعاقب کیا لیکن اس نے انہیں بے بس کر دیا ۔ کہا : اس عورت نے اللہ کے لیے نذر مانی کہ اگر اللہ نے اس اونٹنی پر اسے نجات دی تو وہ اسے ( اللہ کی رضا کے لیے ) نحر کر دے گی ۔ جب وہ مدینہ پہنچی ، لوگوں نے اسے دیکھا تو کہنے لگے : یہ عضباء ہے ، رسول اللہ صلی اللہ علیہ وسلم کی اونٹنی ۔ وہ عورت کہنے لگی کہ اس نے یہ نذر مانی ہے کہ اگر اللہ نے اسے اس اونٹنی پر نجات عطا فرما دی تو وہ اس اونٹنی کو ( اللہ کی راہ میں ) نحر کر دے گی ۔ اس پر لوگ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ کو یہ بات بتائی تو آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" سبحان اللہ! اس عورت نے اسے جو بدلہ دیا وہ کتنا برا ہے! اس نے اللہ کے لیے یہ نذر مانی ہے کہ اگر اللہ نے اس کو اس اونٹنی پر نجات دے دی تو وہ اسے ذبح کر دے گی ، معصیت میں نذر پوری نہیں کی جا سکتی ، نہ ہی اس چیز میں جس کا بندہ مالک نہ ہو ۔ \"\" ابن حجر کی روایت میں ہے : \"\" اللہ کی معصیت میں کوئی نذر ( جائز ) نہیں","",{"u2":"مجھے زہیر بن حرب اور علی بن حجر سعدی نے حدیث بیان کی۔۔ الفاظ زہیر کے ہیں۔۔ ان دونوں نے کہا ہمیں اسماعیل بن ابراہیم نے حدیث سنائی، کہا: ہمیں ایوب نے ابوقلابہ سے حدیث بیان کی، انہوں نے ابومہلب سے اور انہوں نے سیدنا عمران بن حصین رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ثقیف، بنو عقیل کے حلیف تھے، ثقیف نے رسول اللہ صلی اللہ علیہ وسلم کے اصحاب میں سے دو آدمیوں کو قید کر لیا، (بدلے میں) رسول اللہ صلی اللہ علیہ وسلم کے اصحاب نے بنو عقیل کے ایک آدمی کو قیدی بنا لیا اور انہوں نے اس کے ساتھ اونٹنی عضباء بھی حاصل کر لی، رسول اللہ صلی اللہ علیہ وسلم اس آدمی کے پاس سے گزرے، وہ بندھا ہوا تھا، اس نے کہا: اے محمد! آپ صلی اللہ علیہ وسلم اس کے پاس آئے اور پوچھا: \"کیا بات ہے؟\" اس نے کہا: آپ نے مجھے کس وجہ سے پکڑا ہوا اور حاجیوں (کی سواریوں) سے سبقت لے جانے والی اونٹنی کو کیوں پکڑا ہے؟ آپ نے۔۔ اس معاملے کو سنگین خیال کرتے ہوئے۔۔ جواب دیا: \"میں نے تمہیں تمہارے حلیف ثقیف کے جرم کی بنا پر (اس کے ازالے کے لیے) پکڑا ہے۔\" پھر آپ وہاں سے پلٹے تو اس نے (پھر سے) آپ کو آواز دی اور کہا: اے محمد! اے محمد (صلی اللہ علیہ وسلم)! رسول اللہ صلی اللہ علیہ وسلم بہت رحم کرنے والے، نرم دل تھے۔پھر سے آپ اس کے پاس واپس آئے اور فرمایا: \"کیا بات ہے؟\" اس نے کہا: (اب) میں مسلمان ہوں۔ آپ نے فرمایا: اگر تم یہ بات اس وقت کہتے جب تم اپنے مالک آپ تھے (آزاد تھے) تو تم پوری بھلائی حاصل کر لیتے (اب بھی ملے گی لیکن پوری نہ ہو گی۔)\" پھر آپ پلٹے تو اس نے آپ کو آواز دی اور کہا: اے محمد! اے محمد (صلی اللہ علیہ وسلم)! آپ (پھر) اس کے پاس آئے اور پوچھا: \"کیا بات ہے؟\" اس نے کہا: میں بھوکا ہوں مجھے (کھانا) کھلائیے اور پیاسا ہوں مجھے (پانی) پلائیے۔ آپ نے فرمایا: \"(ہاں) یہ تمہاری (فورا پوری کی جانے والی) ضرورت ہے۔\" اس کے بعد (معاملات طے کر کے) اسے دونوں آدمیوں کے بدلے میں چھوڑ دیا گیا۔ (اونٹنی پیچھے رہ گئی اور رسول اللہ صلی اللہ علیہ وسلم کے حصے میں آئی۔ لیکن مشرکین نے دوبارہ حملے کر کے پھر اسے اپنے قبضے میں لے لیا۔)\nکہا: (بعد میں، غزوہ ذات القرد کے موقع پر، مدینہ پر حملے کے دوران) ایک انصاری عورت قید کر لی گئی اور عضباء اونٹنی بھی پکڑ لی گئی، عورت بندھنوں میں (جکڑی ہوئی) تھی۔ لوگ اپنے اونٹ اپنے گھروں کے سامنے رات کو آرام (کرنے کے لیے بٹھا) دیتے تھے، ایک رات وہ (خاتون) اچانک بیڑیوں (بندھنوں) سے نکل بھاگی اور اونٹوں کے پاس آئی، وہ (سواری کے لیے) جس اونٹ کے بھی قریب جاتی وہ بلبلانے لگتا تو وہ اسے چھوڑ دیتی حتی کہ وہ عضباء تک پہنچ گئی تو وہ نہ بلبلائی، کہا: وہ سدھائی ہوئی اونٹنی تھی تو وہ اس کی پیٹھ کے پچھلے حصے پر بیٹھی، اور اسے دوڑایا تو وہ چل پڑی۔ لوگوں کو اس (کے جانے) کا علم ہو گیا، انہوں نے اس کا تعاقب کیا لیکن اس نے انہیں بے بس کر دیا۔ کہا: اس عورت نے اللہ کے لیے نذر مانی کہ اگر اللہ نے اس اونٹنی پر اسے نجات دی تو وہ اسے (اللہ کی رضا کے لیے) نحر کر دے گی۔ جب وہ مدینہ پہنچی، لوگوں نے اسے دیکھا تو کہنے لگے: یہ عضباء ہے، رسول اللہ صلی اللہ علیہ وسلم کی اونٹنی۔ وہ عورت کہنے لگی کہ اس نے یہ نذر مانی ہے کہ اگر اللہ نے اسے اس اونٹنی پر نجات عطا فرما دی تو وہ اس اونٹنی کو (اللہ کی راہ میں) نحر کر دے گی۔ اس پر لوگ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ کو یہ بات بتائی تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"سبحان اللہ! اس عورت نے اسے جو بدلہ دیا وہ کتنا برا ہے! اس نے اللہ کے لیے یہ نذر مانی ہے کہ اگر اللہ نے اس کو اس اونٹنی پر نجات دے دی تو وہ اسے ذبح کر دے گی، معصیت میں نذر پوری نہیں کی جا سکتی، نہ ہی اس چیز میں جس کا بندہ مالک نہ ہو۔\"\nابن حجر کی روایت میں ہے: \"اللہ کی معصیت میں کوئی نذر (جائز) نہیں"}],[4230,"حماد بن زید اور عبدالوہاب ثفقی دونوں نے ایوب سے اسی سند کے ساتھ اس کے ہم معنی حدیث بیان کی ، حماد کی حدیث میں ہے : انہوں نے کہا : عضباء اونٹنی بنو عقیل کے ایک آدمی کی تھی اور وہ حاجیوں کی سواریوں میں سب سے آگے رہنے والی اونٹنیوں میں سے تھی ( تیز رفتار تھی ۔ ) اور ان کی حدیث میں یہ بھی ہے : اور وہ ( قیدی عورت ) سدھائی ہوئی مَشاق اونٹنی پر ( بیٹھ کر ) آئی ، اور ثقفی کی حدیث میں ہے : وہ سدھائی ہوئی اونٹنی تھی ۔","",{"u2":") حماد بن زید اور عبدالوہاب ثفقی دونوں نے ایوب سے اسی سند کے ساتھ اس کے ہم معنی حدیث بیان کی، حماد کی حدیث میں ہے: انہوں نے کہا: عضباء اونٹنی بنو عقیل کے ایک آدمی کی تھی اور وہ حاجیوں کی سواریوں میں سب سے آگے رہنے والی اونٹنیوں میں سے تھی (تیز رفتار تھی۔) اور ان کی حدیث میں یہ بھی ہے: اور وہ (قیدی عورت) سدھائی ہوئی مَشاق اونٹنی پر (بیٹھ کر) آئی، اور ثقفی کی حدیث میں ہے: وہ سدھائی ہوئی اونٹنی تھی۔"}],[4231,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ایک بوڑھے آدمی کو دیکھا وہ اپنے دو بیٹیوں کے سہارے چلا کر لے جایا جا رہا تھا ، آپ نے پوچھا : \" اس کا کیا معاملہ ہے؟ \" لوگوں نے کہا : اس نے پیدل چلنے کی نذر مانی ہے ۔ آپ نے فرمایا : \" بلاشبہ اللہ تعالیٰ اس شخص کے اپنے آپ کو عذاب دینے سے بے نیاز ہے ۔ \" اور ( اس کے پاس پیدل چل کر جانے کی استطاعت ہی نہ تھی ، اس لیے ) آپ نے اسے سوار ہونے کا حکم دیا"],[4232,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ایک بوڑھے آدمی کو دیکھا وہ اپنے دو بیٹیوں کے سہارے چلا کر لے جایا جا رہا تھا ، آپ نے پوچھا : \" اس کا کیا معاملہ ہے؟ \" لوگوں نے کہا : اس نے پیدل چلنے کی نذر مانی ہے ۔ آپ نے فرمایا : \" بلاشبہ اللہ تعالیٰ اس شخص کے اپنے آپ کو عذاب دینے سے بے نیاز ہے ۔ \" اور ( اس کے پاس پیدل چل کر جانے کی استطاعت ہی نہ تھی ، اس لیے ) آپ نے اسے سوار ہونے کا حکم دیا",""],[4233,"یحییٰ بن ایوب ، قتیبہ اور ابن حجر نے ہمیں حدیث بیان کی ، انہوں نے کہا : ہمیں اسماعیل بن جعفر نے عمرو بن ابی عمرو سے حدیث بیان کی ، انہوں نے عبدالرحمان اعرج سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم ایک بوڑھے آدمی کو ملے جو اپنے دو بیٹوں کے درمیان ، ان کا سہارا لیے چل رہا تھا تو نبی صلی اللہ علیہ وسلم نے پوچھا : \" اس کا معاملہ کیا ہے؟ \" اس کے دونوں بیٹوں نے کہا : اللہ کے رسول! اس کے ذمے نذر تھی ۔ تو نبی صلی اللہ علیہ وسلم نے فرمایا : \" اے بزرگ! سوار ہو جاؤ ، اللہ تعالیٰ تم سے اور تمہاری نذر سے بے نیاز ہے ( اسے اس کی ضرورت نہیں ۔ ) ۔ ۔ الفاظ قتیبہ اور ابن حجر کے ہیں","",{"u2":"یحییٰ بن ایوب، قتیبہ اور ابن حجر نے ہمیں حدیث بیان کی، انہوں نے کہا: ہمیں اسماعیل بن جعفر نے عمرو بن ابی عمرو سے حدیث بیان کی، انہوں نے عبدالرحمان اعرج سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم ایک بوڑھے آدمی کو ملے جو اپنے دو بیٹوں کے درمیان، ان کا سہارا لیے چل رہا تھا تو نبی صلی اللہ علیہ وسلم نے پوچھا: \"اس کا معاملہ کیا ہے؟\" اس کے دونوں بیٹوں نے کہا: اللہ کے رسول! اس کے ذمے نذر تھی۔ تو نبی صلی اللہ علیہ وسلم نے فرمایا: \"اے بزرگ! سوار ہو جاؤ، اللہ تعالیٰ تم سے اور تمہاری نذر سے بے نیاز ہے (اسے اس کی ضرورت نہیں۔)۔۔ الفاظ قتیبہ اور ابن حجر کے ہیں"}],[4234,"عبدالعزیز دراوردی نے عمرو بن ابی عمرو سے ، اسی سند کے ساتھ اسی کے مانند حدیث بیان کی","",{"u2":"عبدالعزیز دراوردی نے عمرو بن ابی عمرو سے، اسی سند کے ساتھ اسی کے مانند حدیث بیان کی"}],[4235,"مفضل بن فضالہ نے ہمیں حدیث بیان کی ، ( کہا : ) مجھے عبداللہ بن عیاش نے یزید بن ابی حبیب سے حدیث بیان کی ، انہوں نے ابوالخیر سے اور انہوں نے سیدنا عقبہ بن عامر رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا : میری بہن نے ننگے پاؤں پیدل چل کر بیت اللہ جانے کی نذر مانی اور مجھ سے کہا کہ میں رسول اللہ صلی اللہ علیہ وسلم سے اس کے لیے فتویٰ لوں ، میں نے آپ سے فتویٰ پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" وہ ( بقدر استطاعت ) پیدل چلے اور سوار ہو","",{"u2":"مفضل بن فضالہ نے ہمیں حدیث بیان کی، (کہا:) مجھے عبداللہ بن عیاش نے یزید بن ابی حبیب سے حدیث بیان کی، انہوں نے ابوالخیر سے اور انہوں نے سیدنا عقبہ بن عامر رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا: میری بہن نے ننگے پاؤں پیدل چل کر بیت اللہ جانے کی نذر مانی اور مجھ سے کہا کہ میں رسول اللہ صلی اللہ علیہ وسلم سے اس کے لیے فتویٰ لوں، میں نے آپ سے فتویٰ پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ (بقدر استطاعت) پیدل چلے اور سوار ہو"}],[4236,"اوپر والی حدیث اسی سند سے مروی ہے "],[4237,"اوپر والی حدیث اسی سند سے مروی ہے ","",{"u2":"رَوح بن عبادہ نے ہمیں حدیث بیان کی، (کہا:) ہمیں ابن جریج نے حدیث سنائی، (کہا:) مجھے یحییٰ بن ایوب نے خبر دی کہ انہیں یزید بن ابی حبیب نے اسی سند سے خبر دی۔۔ عبدالرزاق کی حدیث کے مانند"}],[4238,"سیدنا عقبہ بن عامر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" نذر کا کفارہ ( وہی ہے جو ) قسم کا کفارہ ہے","",{"u2":"سیدنا عقبہ بن عامر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"نذر کا کفارہ (وہی ہے جو) قسم کا کفارہ ہے"}],[4239,"یونس نے ابن شہاب سے ، انہوں نے سالم بن عبداللہ سے اور انہوں نے اپنے والد سے روایت کی ، انہوں نے کہا : میں نے سیدنا عمر بن خطاب رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" بلاشبہ اللہ تعالیٰ تمہیں اپنے آباء و اجداد کی قسم کھانے سے منع کرتا ہے ۔ \"\" سیدنا عمر رضی اللہ عنہ نے کہا : اللہ کی قسم! جب سے میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا کہ آپ نے اس سے منع فرمایا ہے ، میں نے نہ ( اپنی طرف سے ) نہ ( کسی کی ) پیروی کرتے ہوئے کبھی ان ( آباء و اجداد کی ) قسم کھائی ۔ ( آباء و اجداد کی قسم کے الفاظ ہی زبان سے ادا نہیں کیے)","",{"u2":"یونس نے ابن شہاب سے، انہوں نے سالم بن عبداللہ سے اور انہوں نے اپنے والد سے روایت کی، انہوں نے کہا: میں نے سیدنا عمر بن خطاب رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بلاشبہ اللہ تعالیٰ تمہیں اپنے آباء و اجداد کی قسم کھانے سے منع کرتا ہے۔\"\nسیدنا عمر رضی اللہ عنہ نے کہا: اللہ کی قسم! جب سے میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا کہ آپ نے اس سے منع فرمایا ہے، میں نے نہ (اپنی طرف سے) نہ (کسی کی) پیروی کرتے ہوئے کبھی ان (آباء و اجداد کی) قسم کھائی۔ (آباء و اجداد کی قسم کے الفاظ ہی زبان سے ادا نہیں کیے"}],[4240,"عقیل بن خالد اور معمر دونوں نے زہری سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ، البتہ عقیل کی حدیث میں ہے : میں نے جب سے رسول اللہ صلی اللہ علیہ وسلم کو اس سے منع کرتے ہوئے سنا ، نہ ان کی قسم کھائی اور نہ ایسی قسم کے الفاظ بولے ۔ انہوں نے \" نہ اپنی طرف سے نہ کسی کی پیروی کرتے ہوئے \" کے الفاظ نہیں کہے","",{"u2":"عقیل بن خالد اور معمر دونوں نے زہری سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی، البتہ عقیل کی حدیث میں ہے: میں نے جب سے رسول اللہ صلی اللہ علیہ وسلم کو اس سے منع کرتے ہوئے سنا، نہ ان کی قسم کھائی اور نہ ایسی قسم کے الفاظ بولے۔ انہوں نے \"نہ اپنی طرف سے نہ کسی کی پیروی کرتے ہوئے\" کے الفاظ نہیں کہے"}],[4241,"سفیان بن عیینہ نے زہری سے ، انہوں نے سالم سے اور انہوں نے اپنے والد سے روایت کی ، انہوں نے کہا : نبی صلی اللہ علیہ وسلم نے سیدنا عمر رضی اللہ عنہ کو سنا ، وہ اپنے والد کی قسم کھا رہے تھے ۔ ۔ ( آگے ) یونس اور معمر کی روایت کے مانند ہے ۔","",{"u2":"سفیان بن عیینہ نے زہری سے، انہوں نے سالم سے اور انہوں نے اپنے والد سے روایت کی، انہوں نے کہا: نبی صلی اللہ علیہ وسلم نے سیدنا عمر رضی اللہ عنہ کو سنا، وہ اپنے والد کی قسم کھا رہے تھے۔۔ (آگے) یونس اور معمر کی روایت کے مانند ہے۔"}],[4242,"لیث نے نافع سے ، انہوں نے سیدنا عبداللہ رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے عمر بن خطاب رضی اللہ عنہ کو ایک قافلے میں پایا اور عمر رضی اللہ عنہ اپنے والد کی قسم کھا رہے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں پکار کر فرمایا : \" سن رکھو! بلاشبہ اللہ تمہیں منع کرتا ہے کہ تم اپنے آباء و اجداد کی قسم کھاؤ ، جس نے قسم کھانی ہے وہ اللہ کی قسم کھائے یا خاموش رہے","",{"u2":"لیث نے نافع سے، انہوں نے سیدنا عبداللہ رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے عمر بن خطاب رضی اللہ عنہ کو ایک قافلے میں پایا اور عمر رضی اللہ عنہ اپنے والد کی قسم کھا رہے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں پکار کر فرمایا: \"سن رکھو! بلاشبہ اللہ تمہیں منع کرتا ہے کہ تم اپنے آباء و اجداد کی قسم کھاؤ، جس نے قسم کھانی ہے وہ اللہ کی قسم کھائے یا خاموش رہے"}],[4243,"عبداللہ بن نمیر ، عبیداللہ ، ایوب ، ولید بن کثیر ، اسماعیل بن امیہ ، ضحاک ، ابن ابی ذئب اور عبدالکریم ، ان سب کے شاگردوں نے ان سے اور انہوں نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی قصے کے مانند بیان کیا","",{"u2":"عبداللہ بن نمیر، عبیداللہ، ایوب، ولید بن کثیر، اسماعیل بن امیہ، ضحاک، ابن ابی ذئب اور عبدالکریم، ان سب کے شاگردوں نے ان سے اور انہوں نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی قصے کے مانند بیان کیا"}],[4244,"عبداللہ بن دینار سے روایت ہے کہ انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے قسم کھانی ہے وہ اللہ کے سوا کسی کی قسم نہ کھائے ۔ \" اور قریش اپنے آباء و اجداد کی قسم کھاتے تھے تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" اپنے آباء و اجداد کی قسم نہ کھاؤ","",{"u2":"عبداللہ بن دینار سے روایت ہے کہ انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے سنا، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے قسم کھانی ہے وہ اللہ کے سوا کسی کی قسم نہ کھائے۔\" اور قریش اپنے آباء و اجداد کی قسم کھاتے تھے تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنے آباء و اجداد کی قسم نہ کھاؤ"}],[4245,"یونس نے ابن شہاب سے روایت کی ، کہا : مجھے حمید بن عبدالرحمان بن عوف نے بتایا کہ سیدنا ابوہریرہ رضی اللہ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے جس نے حلف اٹھایا اور اپنے حلف میں کہا : لات کی قسم! تو وہ لا اله الا اللہ کہے اور جس نے اپنے ساتھی سے کہا : آؤ ، جوا کھیلیں تو وہ صدقہ کرے","",{"u2":"یونس نے ابن شہاب سے روایت کی، کہا: مجھے حمید بن عبدالرحمان بن عوف نے بتایا کہ سیدنا ابوہریرہ رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے جس نے حلف اٹھایا اور اپنے حلف میں کہا: لات کی قسم! تو وہ لا الہ الا اللہ کہے اور جس نے اپنے ساتھی سے کہا: آؤ، جوا کھیلیں تو وہ صدقہ کرے"}],[4246,"اوزاعی اور معمر دونوں نے زہری سے اسی سند کے ساتھ حدیث بیان کی اور معمر کی حدیث یونس کی حدیث کے مانند ہے ، البتہ انہوں نے کہا : \"\" تو وہ کچھ صدقہ کرے ۔ \"\" اور اوزاعی کی حدیث میں ہے : \"\" جس نے لات اور عزیٰ کی قسم کھائی ۔ \"\" ابوحسین مسلم ( مؤلف کتاب ) نے کہا : یہ کلمہ ، آپ کے فرمان : \"\" ( جو کہے ) آؤ ، میں تمہارے ساتھ جوا کھیلوں تو وہ صدقہ کرے ۔ \"\" اسے امام زہری کے علاوہ اور کوئی روایت نہیں کرتا ۔ انہوں نے کہا : اور زہری رحمۃ اللہ علیہ کے تقریبا نوے کلمات ( جملے ) ہیں جو وہ نبی صلی اللہ علیہ وسلم سے جید سندوں کے ساتھ روایت کرتے ہیں ، جن ( کے بیان کرنے ) میں اور کوئی ان کا شریک نہیں ہے","",{"u2":"اوزاعی اور معمر دونوں نے زہری سے اسی سند کے ساتھ حدیث بیان کی اور معمر کی حدیث یونس کی حدیث کے مانند ہے، البتہ انہوں نے کہا: \"تو وہ کچھ صدقہ کرے۔\" اور اوزاعی کی حدیث میں ہے: \"جس نے لات اور عزیٰ کی قسم کھائی۔\"\nابوحسین مسلم (مؤلف کتاب) نے کہا: یہ کلمہ، آپ کے فرمان: \"(جو کہے) آؤ، میں تمہارے ساتھ جوا کھیلوں تو وہ صدقہ کرے۔\" اسے امام زہری کے علاوہ اور کوئی روایت نہیں کرتا۔ انہوں نے کہا: اور زہری رحمۃ اللہ علیہ کے تقریبا نوے کلمات (جملے) ہیں جو وہ نبی صلی اللہ علیہ وسلم سے جید سندوں کے ساتھ روایت کرتے ہیں، جن (کے بیان کرنے) میں اور کوئی ان کا شریک نہیں ہے"}],[4247,"سیدنا عبدالرحمان بن سمرہ رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم بتوں کی قسم نہ کھاؤ ، نہ ہی اپنے آباء و اجداد کی","",{"u2":"سیدنا عبدالرحمان بن سمرہ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم بتوں کی قسم نہ کھاؤ، نہ ہی اپنے آباء و اجداد کی"}],[4248,"غیلان بن جریر نے ابو بردہ سے اور انہوں نے سیدنا ابوموسیٰ اشعری رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا ، میں اشعریوں کی ایک جماعت کے ساتھ تھا ۔ ہم آپ سے سواری کے طلبگار تھے ۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ کی قسم! میں تمہیں سواری مہیا نہیں کروں گا اور نہ میرے پاس ( کوئی سواری ) ہے جس پر میں تمہیں سوار کروں ۔ \" کہا : جتنی دیر اللہ نے چاہا ہم ٹھہرے ، پھر ( آپ کے پاس ) اونٹ لائے گئے تو آپ نے ہمیں سفید کوہان والے تین ( جوڑے ) اونٹ دینے کا حکم دیا ، جب ہم چلے ، ہم نے کہا : یا ہم نے ایک دوسرے سے کہا ۔ ۔ اللہ ہمیں برکت نہیں دے گا ، ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں سواری حاصل کرنے کے لیے حاضر ہوئے تھے تو آپ نے ہمیں سواری نہ دینے کی قسم کھائی ، پھر آپ نے ہمیں سواری دے دی ، چنانچہ وہ لوگ آپ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ صلی اللہ علیہ وسلم سے یہ بات عرض کی تو آپ نے فرمایا : \" میں نے تمہیں سوار نہیں کیا ، بلکہ اللہ نے تمہیں سواری مہیا کی ہے اور اللہ کی قسم! اگر اللہ چاہے ، میں کسی چیز پر قسم نہیں کھاتا اور پھر ( کسی دوسرے کام کو ) اس سے بہتر خیال کرتا ہوں ، تو میں اپنی قسم کا کفارہ دیتا ہوں اور وہی کام کرتا ہوں جو بہتر ہے","",{"u2":"غیلان بن جریر نے ابو بردہ سے اور انہوں نے سیدنا ابوموسیٰ اشعری رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، میں اشعریوں کی ایک جماعت کے ساتھ تھا۔ ہم آپ سے سواری کے طلبگار تھے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی قسم! میں تمہیں سواری مہیا نہیں کروں گا اور نہ میرے پاس (کوئی سواری) ہے جس پر میں تمہیں سوار کروں۔\" کہا: جتنی دیر اللہ نے چاہا ہم ٹھہرے، پھر (آپ کے پاس) اونٹ لائے گئے تو آپ نے ہمیں سفید کوہان والے تین (جوڑے) اونٹ دینے کا حکم دیا، جب ہم چلے، ہم نے کہا: یا ہم نے ایک دوسرے سے کہا۔۔ اللہ ہمیں برکت نہیں دے گا، ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں سواری حاصل کرنے کے لیے حاضر ہوئے تھے تو آپ نے ہمیں سواری نہ دینے کی قسم کھائی، پھر آپ نے ہمیں سواری دے دی، چنانچہ وہ لوگ آپ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ صلی اللہ علیہ وسلم سے یہ بات عرض کی تو آپ نے فرمایا: \"میں نے تمہیں سوار نہیں کیا، بلکہ اللہ نے تمہیں سواری مہیا کی ہے اور اللہ کی قسم! اگر اللہ چاہے، میں کسی چیز پر قسم نہیں کھاتا اور پھر (کسی دوسرے کام کو) اس سے بہتر خیال کرتا ہوں، تو میں اپنی قسم کا کفارہ دیتا ہوں اور وہی کام کرتا ہوں جو بہتر ہے"}],[4249,"بُرید نے ابوبردہ سے اور انہوں نے سیدنا ابوموسیٰ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میرے ساتھیوں نے مجھے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں بھیجا تاکہ میں آپ سے ان کے لیے سواریاں مانگوں ، ( یہ اس موقع کی بات ہے ) جب وہ آپ کے ساتھ جیش العسرۃ میں تھے ۔ ۔ اور اس سے مراد غزوہ تبوک ہے ۔ ۔ تو میں نے عرض کی : اللہ کے نبی! میرے ساتھیوں نے مجھے آپ کے پاس بھیجا ہے تاکہ آپ انہیں سواریاں دیں ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" اللہ کی قسم! میں تمہیں کسی چیز پر سوار نہیں کروں گا ۔ \"\" اور میں ایسے وقت آپ کے پاس گیا تھا کہ آپ غصے میں تھے اور مجھے معلوم نہ تھا ۔ میں رسول اللہ صلی اللہ علیہ وسلم کے انکار کی وجہ سے اور اس ڈر سے کہ آپ اپنے دل میں مجھ سے ناراض ہو گئے ہیں ، غمگین واپس ہوا ۔ میں اپنے ساتھیوں کے پاس واپس آیا اور جو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا ، انہیں بتایا ۔ میں نے ایک چھوٹی سی گھڑی ہی گزاری ہو گی کہ اچانک میں نے بلال رضی اللہ عنہ کو سنا ، وہ پکار رہے تھے : اے عبداللہ بن قیس! میں نے انہیں جواب دیا تو انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو جاؤ ، وہ تمہیں بلا رہے ہیں ۔ جب میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" یہ دو اکٹھے بندھے ہوئے اونٹ لے لو ، یہ جوڑا اور یہ جوڑا بھی لے لو ۔ ۔ چھ اونٹوں کی طرف اشارہ کیا جو آپ نے اسی وقت سیدنا سعد رضی اللہ عنہ سے خریدے تھے ۔ ۔ اور انہیں اپنے ساتھیوں کے پاس لے جاؤ اور کہو : اللہ تعالیٰ ۔ ۔ یا فرمایا : رسول اللہ صلی اللہ علیہ وسلم ۔ ۔ تمہیں یہ سواریاں مہیا کر رہے ہیں ، ان پر سواری کرو ۔ \"\" سیدنا ابو موسیٰ رضی اللہ عنہ نے کہا : میں انہیں لے کر اپنے ساتھیوں کے پاس گیا اور کہا : بلاشبہ رسول اللہ صلی اللہ علیہ وسلم تمہیں ان پر سوار کر رہے ہیں لیکن اللہ کی قسم! میں اس وقت تک تمہیں نہیں چھوڑوں گا یہاں تک کہ تم میں سے کوئی میرے ساتھ اس آدمی کے پاس جائے جس نے اس وقت رسول اللہ صلی اللہ علیہ وسلم کی بات سنی تھی جب میں نے آپ سے تمہارے لیے سوال کیا تھا ، اور پہلی مرتبہ آپ کے منع کرنے اور اس کے بعد مجھے عطا کرنے کی بات بھی سنی تھی ، مبادا تم سمجھو کہ میں نے تمہیں ایسی بات بتائی ہے جو آپ نے نہیں فرمائی ۔ تو انہوں نے مجھ سے کہا : اللہ کی قسم! آپ ہمارے نزدیک سچے ہیں اور جو آپ کو پسند ہے وہ بھی ہم ضرور کریں گے ، چنانچہ سیدنا ابو موسیٰ رضی اللہ عنہ ان میں سے چند لوگوں کو ساتھ لے کر چل پڑے یہاں تک کہ ان لوگوں کے پاس آئے جنہوں نے رسول اللہ صلی اللہ علیہ وسلم کی بات اور آپ کے انکار کرنے کے بعد عطا کرنے کے بارے میں خود سنا تھا ۔ انہوں نے بالکل وہی بات کی جو سیدنا ابو موسیٰ رضی اللہ عنہ نے ( اپنے ) لوگوں کو بتائی تھی ۔ فائدہ : اس حدیث میں واقعے کے پہلے حصے کی زیادہ تفصیل بیان کی گئی ہے جبکہ آخری حصے کی تفصیل پچھلی حدیث میں ہے ۔ سیدنا ابوموسیٰ رضی اللہ عنہ کو ساتھیوں نے بھیجا ، رسول اللہ صلی اللہ علیہ وسلم نے انہیں جواب دیا ، پھر بلا کر اونٹ عطا فرمائے ، پھر یہ لوگ ان لوگوں کے پاس گئے جو سارے واقعے کے دوران میں رسول اللہ صلی اللہ علیہ وسلم کے سامنے موجود تھے ، پھر یہ حضرات رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور قسم والی بات بتائی ۔ اس پر آپ نے وہی جواب دیا جو پہلی حدیث میں مذکور ہے","",{"u2":"بُرید نے ابوبردہ سے اور انہوں نے سیدنا ابوموسیٰ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میرے ساتھیوں نے مجھے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں بھیجا تاکہ میں آپ سے ان کے لیے سواریاں مانگوں، (یہ اس موقع کی بات ہے) جب وہ آپ کے ساتھ جیش العسرۃ میں تھے۔۔ اور اس سے مراد غزوہ تبوک ہے۔۔ تو میں نے عرض کی: اللہ کے نبی! میرے ساتھیوں نے مجھے آپ کے پاس بھیجا ہے تاکہ آپ انہیں سواریاں دیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی قسم! میں تمہیں کسی چیز پر سوار نہیں کروں گا۔\" اور میں ایسے وقت آپ کے پاس گیا تھا کہ آپ غصے میں تھے اور مجھے معلوم نہ تھا۔ میں رسول اللہ صلی اللہ علیہ وسلم کے انکار کی وجہ سے اور اس ڈر سے کہ آپ اپنے دل میں مجھ سے ناراض ہو گئے ہیں، غمگین واپس ہوا۔ میں اپنے ساتھیوں کے پاس واپس آیا اور جو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا، انہیں بتایا۔ میں نے ایک چھوٹی سی گھڑی ہی گزاری ہو گی کہ اچانک میں نے بلال رضی اللہ عنہ کو سنا، وہ پکار رہے تھے: اے عبداللہ بن قیس! میں نے انہیں جواب دیا تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو جاؤ، وہ تمہیں بلا رہے ہیں۔ جب میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ دو اکٹھے بندھے ہوئے اونٹ لے لو، یہ جوڑا اور یہ جوڑا بھی لے لو۔۔ چھ اونٹوں کی طرف اشارہ کیا جو آپ نے اسی وقت سیدنا سعد رضی اللہ عنہ سے خریدے تھے۔۔ اور انہیں اپنے ساتھیوں کے پاس لے جاؤ اور کہو: اللہ تعالیٰ۔۔ یا فرمایا: رسول اللہ صلی اللہ علیہ وسلم۔۔ تمہیں یہ سواریاں مہیا کر رہے ہیں، ان پر سواری کرو۔\"\nسیدنا ابو موسیٰ رضی اللہ عنہ نے کہا: میں انہیں لے کر اپنے ساتھیوں کے پاس گیا اور کہا: بلاشبہ رسول اللہ صلی اللہ علیہ وسلم تمہیں ان پر سوار کر رہے ہیں لیکن اللہ کی قسم! میں اس وقت تک تمہیں نہیں چھوڑوں گا یہاں تک کہ تم میں سے کوئی میرے ساتھ اس آدمی کے پاس جائے جس نے اس وقت رسول اللہ صلی اللہ علیہ وسلم کی بات سنی تھی جب میں نے آپ سے تمہارے لیے سوال کیا تھا، اور پہلی مرتبہ آپ کے منع کرنے اور اس کے بعد مجھے عطا کرنے کی بات بھی سنی تھی، مبادا تم سمجھو کہ میں نے تمہیں ایسی بات بتائی ہے جو آپ نے نہیں فرمائی۔ تو انہوں نے مجھ سے کہا: اللہ کی قسم! آپ ہمارے نزدیک سچے ہیں اور جو آپ کو پسند ہے وہ بھی ہم ضرور کریں گے، چنانچہ سیدنا ابو موسیٰ رضی اللہ عنہ ان میں سے چند لوگوں کو ساتھ لے کر چل پڑے یہاں تک کہ ان لوگوں کے پاس آئے جنہوں نے رسول اللہ صلی اللہ علیہ وسلم کی بات اور آپ کے انکار کرنے کے بعد عطا کرنے کے بارے میں خود سنا تھا۔ انہوں نے بالکل وہی بات کی جو سیدنا ابو موسیٰ رضی اللہ عنہ نے (اپنے) لوگوں کو بتائی تھی۔\nفائدہ: اس حدیث میں واقعے کے پہلے حصے کی زیادہ تفصیل بیان کی گئی ہے جبکہ آخری حصے کی تفصیل پچھلی حدیث میں ہے۔ سیدنا ابوموسیٰ رضی اللہ عنہ کو ساتھیوں نے بھیجا، رسول اللہ صلی اللہ علیہ وسلم نے انہیں جواب دیا، پھر بلا کر اونٹ عطا فرمائے، پھر یہ لوگ ان لوگوں کے پاس گئے جو سارے واقعے کے دوران میں رسول اللہ صلی اللہ علیہ وسلم کے سامنے موجود تھے، پھر یہ حضرات رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور قسم والی بات بتائی۔ اس پر آپ نے وہی جواب دیا جو پہلی حدیث میں مذکور ہے"}],[4250,"حماد بن زید نے ہمیں ایوب سے حدیث بیان کی ، انہوں نے ابوقلابہ اور قاسم بن عاصم سے اور انہوں نے زَہدم جرمی سے روایت کی ۔ ۔ ایوب نے کہا : ابوقلابہ کی حدیث کی نسبت مجھے قاسم کی حدیث زیادہ یاد ہے ۔ ۔ انہوں ( زہدم ) نے کہا : ہم سیدنا ابو موسیٰ رضی اللہ عنہ کے پاس تھے ، انہوں نے اپنا دسترخوان منگوایا جس پر مرغی کا گوشت تھا ، اتنے میں بنو تیمِ اللہ میں سے ایک آدمی اندر داخل ہوا ، وہ سرخ رنگ کا موالی جیسا شخص تھا ، تو انہوں نے اس سے کہا : آؤ ۔ وہ ہچکچایا تو انہوں نے کہا : آؤ ، میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس ( مرغی کے گوشت ) میں سے کھاتے ہوئے دیکھا ہے ۔ اس آدمی نے کہا : میں نے اسے کوئی ایسی چیز کھاتے ہوئے دیکھا تھا جس سے مجھے اس سے گھن آئی تو میں نے قسم کھائی تھی کہ میں اس ( کے گوشت ) کو کبھی نہیں کھاؤں گا ۔ اس پر انہوں نے کہا : آؤ ، میں تمہیں اس کے بارے میں حدیث سناتا ہوں ، میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا ، میں اشعریوں کے ایک گروہ کے ساتھ تھا ، ہم آپ سے سواریوں کے طلبگار تھے ، تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ کی قسم! میں تمہیں سواری مہیا نہیں کروں گا اور نہ میرے پاس کوئی ایسی چیز ہے جس پر میں تمہیں سوار کروں ۔ \" جتنا اللہ نے چاہا ہم رکے ، پھر رسول اللہ صلی اللہ علیہ وسلم کے پاس ( کافروں سے ) چھینے ہوئے اونٹ ( جو آپ نے سعد رضی اللہ عنہ سے خرید لیے تھے ) لائے گئے تو آپ نے ہمیں بلوایا ، آپ نے ہمیں سفید کوہان والے پانچ ( یا چھ ، حدیث : 4264 ) اونٹ دینے کا حکم دیا ۔ کہا : جب ہم چلے ، تو ہم میں سے کچھ لوگوں نے دوسروں سے کہا : ( غالبا ) ہم نے رسول اللہ صلی اللہ علیہ وسلم کو اپنی قسم سے غافل کر دیا ، ہمیں برکت نہ دی جائے گی ، چنانچہ ہم واپس آپ کی خدمت میں حاضر ہوئے اور عرض کی : اے اللہ کے رسول! ہم آپ کی خدمت میں سواریاں لینے کے لیے حاضر ہوئے تھے اور آپ نے ہمیں سواری نہ دینے کی قسم کھائی تھی ، پھر آپ نے ہمیں سواریاں دے دی ہیں تو اللہ کے رسول! کیا آپ بھول گئے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ کی قسم! اللہ کی مشیت سے میں جب بھی کسی چیز پر قسم کھاتا ہوں ، پھر اس کے علاوہ کسی اور کام کو اس سے بہتر خیال کرتا ہوں تو وہی کام کرتا ہوں جو بہتر ہے اور ( قسم کا کفارہ ادا کر کے ) اس کا بندھن کھول دیتا ہوں ۔ تم جاؤ ، تمہیں اللہ عزوجل نے سوار کیا ہے","",{"u2":"حماد بن زید نے ہمیں ایوب سے حدیث بیان کی، انہوں نے ابوقلابہ اور قاسم بن عاصم سے اور انہوں نے زَہدم جرمی سے روایت کی۔۔ ایوب نے کہا: ابوقلابہ کی حدیث کی نسبت مجھے قاسم کی حدیث زیادہ یاد ہے۔۔ انہوں (زہدم) نے کہا: ہم سیدنا ابو موسیٰ رضی اللہ عنہ کے پاس تھے، انہوں نے اپنا دسترخوان منگوایا جس پر مرغی کا گوشت تھا، اتنے میں بنو تیمِ اللہ میں سے ایک آدمی اندر داخل ہوا، وہ سرخ رنگ کا موالی جیسا شخص تھا، تو انہوں نے اس سے کہا: آؤ۔ وہ ہچکچایا تو انہوں نے کہا: آؤ، میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس (مرغی کے گوشت) میں سے کھاتے ہوئے دیکھا ہے۔ اس آدمی نے کہا: میں نے اسے کوئی ایسی چیز کھاتے ہوئے دیکھا تھا جس سے مجھے اس سے گھن آئی تو میں نے قسم کھائی تھی کہ میں اس (کے گوشت) کو کبھی نہیں کھاؤں گا۔ اس پر انہوں نے کہا: آؤ، میں تمہیں اس کے بارے میں حدیث سناتا ہوں، میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، میں اشعریوں کے ایک گروہ کے ساتھ تھا، ہم آپ سے سواریوں کے طلبگار تھے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی قسم! میں تمہیں سواری مہیا نہیں کروں گا اور نہ میرے پاس کوئی ایسی چیز ہے جس پر میں تمہیں سوار کروں۔\" جتنا اللہ نے چاہا ہم رکے، پھر رسول اللہ صلی اللہ علیہ وسلم کے پاس (کافروں سے) چھینے ہوئے اونٹ (جو آپ نے سعد رضی اللہ عنہ سے خرید لیے تھے) لائے گئے تو آپ نے ہمیں بلوایا، آپ نے ہمیں سفید کوہان والے پانچ (یا چھ، حدیث: 4264) اونٹ دینے کا حکم دیا۔ کہا: جب ہم چلے، تو ہم میں سے کچھ لوگوں نے دوسروں سے کہا: (غالبا) ہم نے رسول اللہ صلی اللہ علیہ وسلم کو اپنی قسم سے غافل کر دیا، ہمیں برکت نہ دی جائے گی، چنانچہ ہم واپس آپ کی خدمت میں حاضر ہوئے اور عرض کی: اے اللہ کے رسول! ہم آپ کی خدمت میں سواریاں لینے کے لیے حاضر ہوئے تھے اور آپ نے ہمیں سواری نہ دینے کی قسم کھائی تھی، پھر آپ نے ہمیں سواریاں دے دی ہیں تو اللہ کے رسول! کیا آپ بھول گئے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی قسم! اللہ کی مشیت سے میں جب بھی کسی چیز پر قسم کھاتا ہوں، پھر اس کے علاوہ کسی اور کام کو اس سے بہتر خیال کرتا ہوں تو وہی کام کرتا ہوں جو بہتر ہے اور (قسم کا کفارہ ادا کر کے) اس کا بندھن کھول دیتا ہوں۔ تم جاؤ، تمہیں اللہ عزوجل نے سوار کیا ہے"}],[4251,"عبدالوہاب ثقفی نے ہمیں ایوب سے حدیث بیان کی ، انہوں نے ابوقلابہ اور قاسم تمیمی سے اور انہوں نے زہدم جرمی سے روایت کی ، انہوں نے کہا : جَرم کے قبیلے اور اشعریوں کے درمیان محبت و اخوت کا رشتہ تھا ، ہم سیدنا ابو موسیٰ اشعری رضی اللہ عنہ کے پاس تھے ، انہیں کھانا پیش کیا گیا جس میں مرغی کا گوشت تھا ۔ ۔ آگے اسی کے ہم معنی بیان کیا","",{"u2":"عبدالوہاب ثقفی نے ہمیں ایوب سے حدیث بیان کی، انہوں نے ابوقلابہ اور قاسم تمیمی سے اور انہوں نے زہدم جرمی سے روایت کی، انہوں نے کہا: جَرم کے قبیلے اور اشعریوں کے درمیان محبت و اخوت کا رشتہ تھا، ہم سیدنا ابو موسیٰ اشعری رضی اللہ عنہ کے پاس تھے، انہیں کھانا پیش کیا گیا جس میں مرغی کا گوشت تھا۔۔ آگے اسی کے ہم معنی بیان کیا"}],[4252,"اسماعیل بن علیہ ، سفیان اور وہیب ، سب نے ایوب سے حدیث بیان کی ، انہوں نے ابوقلابہ اور قاسم سے اور انہوں نے زہدم جرمی سے روایت کی ، انہوں نے کہا : ہم سیدنا ابو موسیٰ رضی اللہ عنہ کے پاس تھے ۔ ۔ ان سب نے حماد بن زید کی حدیث کے ہم معنی حدیث بیان کی"],[4253,"اسماعیل بن علیہ ، سفیان اور وہیب ، سب نے ایوب سے حدیث بیان کی ، انہوں نے ابوقلابہ اور قاسم سے اور انہوں نے زہدم جرمی سے روایت کی ، انہوں نے کہا : ہم سیدنا ابو موسیٰ رضی اللہ عنہ کے پاس تھے ۔ ۔ ان سب نے حماد بن زید کی حدیث کے ہم معنی حدیث بیان کی"],[4254,"اسماعیل بن علیہ ، سفیان اور وہیب ، سب نے ایوب سے حدیث بیان کی ، انہوں نے ابوقلابہ اور قاسم سے اور انہوں نے زہدم جرمی سے روایت کی ، انہوں نے کہا : ہم سیدنا ابو موسیٰ رضی اللہ عنہ کے پاس تھے ۔ ۔ ان سب نے حماد بن زید کی حدیث کے ہم معنی حدیث بیان کی",""],[4255,"مطروراق نے ہمیں حدیث بیان کی ، کہا : ہمیں زہدم جرمی نے حدیث بیان کی ، انہوں نے کہا : میں سیدنا ابو موسیٰ رضی اللہ عنہ کے ہاں گیا ، وہ مرغی کا گوشت کھا رہے تھے ۔ ۔ انہوں نے ان سب کی حدیث کی طرح حدیث بیان کی اور اس میں یہ اضافہ کیا ، آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ کی قسم! میں اس ( اپنی قسم ) کو نہیں بھولا","",{"u2":"مطروراق نے ہمیں حدیث بیان کی، کہا: ہمیں زہدم جرمی نے حدیث بیان کی، انہوں نے کہا: میں سیدنا ابو موسیٰ رضی اللہ عنہ کے ہاں گیا، وہ مرغی کا گوشت کھا رہے تھے۔۔ انہوں نے ان سب کی حدیث کی طرح حدیث بیان کی اور اس میں یہ اضافہ کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی قسم! میں اس (اپنی قسم) کو نہیں بھولا"}],[4256,"جریر نے ہمیں سلیمان تیمی سے خبر دی ، انہوں نے ضرب بن نقیر قیسی سے ، انہوں نے زہدم سے اور انہوں نے سیدنا ابو موسیٰ اشعری رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں سواریاں حاصل کرنے کے لیے حاضر ہوئے تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" میرے پاس کوئی چیز نہیں ہے جس پر میں تمہیں سوار کروں ، اللہ کی قسم! میں تمہیں سوار نہیں کروں گا ۔ \" پھر رسول اللہ صلی اللہ علیہ وسلم نے ہماری طرف سفید کوہان والے تین ( جوڑے ) اونٹ بھیجے تو ہم نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آپ سے سواریاں حاصل کرنے کے لیے حاضر ہوئے تو آپ نے ہمیں سواری نہ دینے کی قسم کھائی تھی ، چنانچہ ہم آپ کی خدمت میں حاضر ہوئے اور آپ کو ( آپ کی قسم ) کے بارے میں ) خبر دی تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" میں کسی چیز پر قسم نہیں کھاتا ، پھر اس کے علاوہ کسی دوسرے کام کو اس سے بہتر خیال کرتا ہوں تو وہی کرتا ہوں جو بہتر ہو","",{"u2":"جریر نے ہمیں سلیمان تیمی سے خبر دی، انہوں نے ضرب بن نقیر قیسی سے، انہوں نے زہدم سے اور انہوں نے سیدنا ابو موسیٰ اشعری رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں سواریاں حاصل کرنے کے لیے حاضر ہوئے تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"میرے پاس کوئی چیز نہیں ہے جس پر میں تمہیں سوار کروں، اللہ کی قسم! میں تمہیں سوار نہیں کروں گا۔\" پھر رسول اللہ صلی اللہ علیہ وسلم نے ہماری طرف سفید کوہان والے تین (جوڑے) اونٹ بھیجے تو ہم نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آپ سے سواریاں حاصل کرنے کے لیے حاضر ہوئے تو آپ نے ہمیں سواری نہ دینے کی قسم کھائی تھی، چنانچہ ہم آپ کی خدمت میں حاضر ہوئے اور آپ کو (آپ کی قسم) کے بارے میں) خبر دی تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں کسی چیز پر قسم نہیں کھاتا، پھر اس کے علاوہ کسی دوسرے کام کو اس سے بہتر خیال کرتا ہوں تو وہی کرتا ہوں جو بہتر ہو"}],[4257,"معتمر نے اپنے والد سے روایت کی ، کہا : ہمیں ابو سلیل ( ضریب ) نے زہدم سے حدیث بیان کی ، وہ سیدنا ابو موسیٰ رضی اللہ عنہ سے حدیث بیان کر رہے تھے ، انہوں نے کہا : ہم پیدل تھے تو ہم نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے ، ہم آپ سے سواریاں حاصل کرنا چاہتے تھے ، ( آگے اسی طرح ہے ) جس طرح جریر کی حدیث ہے","",{"u2":"معتمر نے اپنے والد سے روایت کی، کہا: ہمیں ابو سلیل (ضریب) نے زہدم سے حدیث بیان کی، وہ سیدنا ابو موسیٰ رضی اللہ عنہ سے حدیث بیان کر رہے تھے، انہوں نے کہا: ہم پیدل تھے تو ہم نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے، ہم آپ سے سواریاں حاصل کرنا چاہتے تھے، (آگے اسی طرح ہے) جس طرح جریر کی حدیث ہے"}],[4258,"ابو حازم نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ایک آدمی رات کی تاریکی گہری ہونے تک نبی صلی اللہ علیہ وسلم کے پاس رہا ، پھر اپنے گھر لوٹا تو اس نے بچوں کو سویا ہوا پایا ، اس کی بیوی اس کے پاس کھانا لائی تو اس نے قسم کھائی کہ وہ بچوں ( کے سو جانے ) کی وجہ سے کھانا نہیں کھائے گا ، پھر اسے ( دوسرا ) خیال آیا تو اس نے کھانا کھا لیا ، اس کے بعد وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ سے اس بات کا تذکرہ کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے کوئی قسم کھائی ، پھر اس نے کسی دوسرے کام کو اس سے بہتر سمجھا تو وہ وہی کام کر لے اور اپنی قسم کا کفارہ ادا کر دے","",{"u2":"ابو حازم نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ایک آدمی رات کی تاریکی گہری ہونے تک نبی صلی اللہ علیہ وسلم کے پاس رہا، پھر اپنے گھر لوٹا تو اس نے بچوں کو سویا ہوا پایا، اس کی بیوی اس کے پاس کھانا لائی تو اس نے قسم کھائی کہ وہ بچوں (کے سو جانے) کی وجہ سے کھانا نہیں کھائے گا، پھر اسے (دوسرا) خیال آیا تو اس نے کھانا کھا لیا، اس کے بعد وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ سے اس بات کا تذکرہ کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کوئی قسم کھائی، پھر اس نے کسی دوسرے کام کو اس سے بہتر سمجھا تو وہ وہی کام کر لے اور اپنی قسم کا کفارہ ادا کر دے"}],[4259,"امام مالک نے سہیل بن ابی صالح سے خبر دی ، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے کوئی قسم کھائی ، پھر اس کے بجائے کسی دوسرے کام کو اس سے بہتر خیال کیا تو وہ اپنی قسم کا کفارہ دے اور وہ کام کر لے"],[4260,"عبدالعزیز بن مطلب نے سہیل بن ابی صالح سے روایت کی ، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے کوئی قسم کھائی ، پھر اس کے بجائے دوسرے کام کو اس سے بہتر خیال کیا تو وہ وہی کام کرے جو بہتر ہے اور اپنی قسم کا کفارہ ادا کرے","",{"u2":"عبدالعزیز بن مطلب نے سہیل بن ابی صالح سے روایت کی، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کوئی قسم کھائی، پھر اس کے بجائے دوسرے کام کو اس سے بہتر خیال کیا تو وہ وہی کام کرے جو بہتر ہے اور اپنی قسم کا کفارہ ادا کرے"}],[4261,"سلیمان بن بلال نے مجھے سہیل سے اسی سند کے ساتھ امام مالک کی حدیث کے ہم معنی حدیث ( ان الفاظ میں ) بیان کی : \" اسے چاہئے کہ اپنی قسم کا کفارہ دے اور وہ کام کرے جو بہتر ہے","",{"u2":"سلیمان بن بلال نے مجھے سہیل سے اسی سند کے ساتھ امام مالک کی حدیث کے ہم معنی حدیث (ان الفاظ میں) بیان کی: \"اسے چاہئے کہ اپنی قسم کا کفارہ دے اور وہ کام کرے جو بہتر ہے"}],[4262,"جریر نے عبدالعزیز بن رفیع سے ، انہوں نے تمیم بن طرفہ سے روایت کی ، انہوں نے کہا : سیدنا عدی بن حاتم رضی اللہ عنہ کے پاس ایک سائل آیا اور ان سے غلام کی قیمت یا غلام کی قیمت کا کچھ حصہ ( ادا کرنے کے لیے ) خرچے کا سوال کیا ، تو انہوں نے کہا ، میرے پاس تو تمہیں دینے کے لیے میری زرہ اور ( سر کے ) خَود کے سوا کچھ نہیں ، اس لیے میں اپنے گھر والوں کو لکھ دیتا ہوں کہ وہ یہ خرچہ تمہیں دے دیں ۔ کہا : وہ ( اس پر ) راضی نہ ہوا تو سیدنا عدی رضی اللہ عنہ ناراض ہو گئے اور کہا : اللہ کی قسم! میں تمہیں کچھ نہیں دوں گا ، پھر وہ آدمی ( اسی بات پر ) راضی ہو گیا تو انہوں نے کہا : اللہ کی قسم! اگر میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے نہ سنا ہوتا : \" جس نے کوئی قسم کھائی ، پھر کسی اور کام کو اللہ عزوجل کے تقوے کے زیادہ قریب دیکھا تو وہ تقوے والا کام کرے ۔ \" تو میں اپنی قسم نہ توڑتا","",{"u2":"جریر نے عبدالعزیز بن رفیع سے، انہوں نے تمیم بن طرفہ سے روایت کی، انہوں نے کہا: سیدنا عدی بن حاتم رضی اللہ عنہ کے پاس ایک سائل آیا اور ان سے غلام کی قیمت یا غلام کی قیمت کا کچھ حصہ (ادا کرنے کے لیے) خرچے کا سوال کیا، تو انہوں نے کہا، میرے پاس تو تمہیں دینے کے لیے میری زرہ اور (سر کے) خَود کے سوا کچھ نہیں، اس لیے میں اپنے گھر والوں کو لکھ دیتا ہوں کہ وہ یہ خرچہ تمہیں دے دیں۔ کہا: وہ (اس پر) راضی نہ ہوا تو سیدنا عدی رضی اللہ عنہ ناراض ہو گئے اور کہا: اللہ کی قسم! میں تمہیں کچھ نہیں دوں گا، پھر وہ آدمی (اسی بات پر) راضی ہو گیا تو انہوں نے کہا: اللہ کی قسم! اگر میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے نہ سنا ہوتا: \"جس نے کوئی قسم کھائی، پھر کسی اور کام کو اللہ عزوجل کے تقوے کے زیادہ قریب دیکھا تو وہ تقوے والا کام کرے۔\" تو میں اپنی قسم نہ توڑتا"}],[4263,"شعبہ نے عبدالعزیز بن رفیع سے ، انہوں نے تمیم بن طرفہ سے اور انہوں نے سیدنا عدی بن حاتم رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے کوئی قسم کھائی ، پھر کسی دوسرے کام کو اس سے بہتر سمجھا تو وہ وہی کام کرے جو بہتر ہے اور اپنی قسم کو ترک کر دے ۔ ( اور کفارہ ادا کر دے)","",{"u2":"شعبہ نے عبدالعزیز بن رفیع سے، انہوں نے تمیم بن طرفہ سے اور انہوں نے سیدنا عدی بن حاتم رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کوئی قسم کھائی، پھر کسی دوسرے کام کو اس سے بہتر سمجھا تو وہ وہی کام کرے جو بہتر ہے اور اپنی قسم کو ترک کر دے۔ (اور کفارہ ادا کر دے"}],[4264,"اعمش نے عبدالعزیز بن رفیع سے ، انہوں نے تمیم طائی سے اور انہوں نے سیدنا عدی رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی کسی کام کی قسم کھائے ، پھر اس سے بہتر ( کام ) دیکھے تو وہ اس ( قسم ) کا کفارہ ادا کر دے اور وہی کرے جو بہتر ہے","",{"u2":"اعمش نے عبدالعزیز بن رفیع سے، انہوں نے تمیم طائی سے اور انہوں نے سیدنا عدی رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی کسی کام کی قسم کھائے، پھر اس سے بہتر (کام) دیکھے تو وہ اس (قسم) کا کفارہ ادا کر دے اور وہی کرے جو بہتر ہے"}],[4265,"شیبانی نے عبدالعزیز بن رفیع سے ، انہوں نے تمیم طائی سے اور انہوں نے سیدنا عدی بن حاتم رضی اللہ عنہ سے روایت کی کہ انہوں نے نبی صلی اللہ علیہ وسلم سے سنا آپ یہی فرما رہے تھے","",{"u2":"شیبانی نے عبدالعزیز بن رفیع سے، انہوں نے تمیم طائی سے اور انہوں نے سیدنا عدی بن حاتم رضی اللہ عنہ سے روایت کی کہ انہوں نے نبی صلی اللہ علیہ وسلم سے سنا آپ یہی فرما رہے تھے"}],[4266,"محمد بن جعفر نے کہا : ہمیں شعبہ نے سماک بن حرب سے حدیث بیان کی اور انہوں نے تمیم بن طرفہ سے روایت کی ، انہوں نے کہا : میں نے سیدنا عدی بن حاتم رضی اللہ عنہ سے سنا ، ان کے پاس ایک آدمی ایک سو درہم مانگنے کے لیے آیا تھا ، ( غلام کی قیمت میں سے سو درہم کم تھے ) انہوں نے کہا : تو مجھ سے ( سرف ) سو درہم مانگ رہا جبکہ میں حاتم طائی کا بیٹا ہوں؟ اللہ کی قسم! میں تمہیں ( کچھ ) نہیں دوں گا ، پھر انہوں نے کہا : اگر میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے نہ سنا ہوتا : \" جس نے کوئی قسم کھائی ، پھر اس سے بہتر کام دیکھا تو وہ وہی کرے جو بہتر ہے ۔ \" ( تو میں تمہیں کچھ نہ دیتا)","",{"u2":"محمد بن جعفر نے کہا: ہمیں شعبہ نے سماک بن حرب سے حدیث بیان کی اور انہوں نے تمیم بن طرفہ سے روایت کی، انہوں نے کہا: میں نے سیدنا عدی بن حاتم رضی اللہ عنہ سے سنا، ان کے پاس ایک آدمی ایک سو درہم مانگنے کے لیے آیا تھا، (غلام کی قیمت میں سے سو درہم کم تھے) انہوں نے کہا: تو مجھ سے(سرف) سو درہم مانگ رہا جبکہ میں حاتم طائی کا بیٹا ہوں؟ اللہ کی قسم! میں تمہیں (کچھ) نہیں دوں گا، پھر انہوں نے کہا: اگر میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے نہ سنا ہوتا: \"جس نے کوئی قسم کھائی، پھر اس سے بہتر کام دیکھا تو وہ وہی کرے جو بہتر ہے۔\" (تو میں تمہیں کچھ نہ دیتا"}],[4267,"بہز نے کہا : ہمیں شعبہ نے حدیث سنائی اور کہا : ہمیں سماک بن حرب نے حدیث بیان کی ، انہوں نے کہا : میں نے تمیم بن طرفہ سے سنا ، انہوں نے کہا : میں نے سیدنا عدی بن حاتم رضی اللہ عنہ سے سنا کہ ایک آدمی نے ان سے سوال کیا ۔ ۔ آگے اسی ( سابقہ حدیث ) کے مانند بیان کیا اور یہ اضافہ کیا : میرے وظیفے میں سے چار سو ( درہم ) تمہارے","",{"u2":"بہز نے کہا: ہمیں شعبہ نے حدیث سنائی اور کہا: ہمیں سماک بن حرب نے حدیث بیان کی، انہوں نے کہا: میں نے تمیم بن طرفہ سے سنا، انہوں نے کہا: میں نے سیدنا عدی بن حاتم رضی اللہ عنہ سے سنا کہ ایک آدمی نے ان سے سوال کیا۔۔ آگے اسی (سابقہ حدیث) کے مانند بیان کیا اور یہ اضافہ کیا: میرے وظیفے میں سے چار سو (درہم) تمہارے"}],[4268,"شیبان بن فروخ نے کہا : ہمیں جریر بن حازم نے حدیث بیان کی ، ( کہا : ) ہمیں حسن نے حدیث سنائی ، ( کہا : ) ہمیں سیدنا عبدالرحمان بن سمرہ رضی اللہ عنہ نے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا : \"\" عبدالرحمان بن سمرہ! تم ( خود ) امارت کی درخواست مت کرو ، ( کیونکہ ) اگر وہ تمہیں مانگنے پر دی گئی تو تم اس کے حوالے کر دیے جاؤ گے اور اگر تمہیں بن مانگے ملے گی تو ( اللہ کی طرف سے ) تمہاری مدد کی جائے گی اور جب تم کسی کام پر قسم کھاؤ ، پھر اس کے بجائے کسی دوسرے کام کو اس سے بہتر دیکھو تو اپنی قسم کا کفارہ دو اور وہی اختیار کرو جو بہتر ہے ۔ \"\" ( امام مسلم کے شاگرد ) ابو احمد جلودی نے کہا : ہمیں ابو عباس ماسرجسی نے حدیث سنائی ، ( کہا : ) ہمیں شیبان بن فروخ نے حدیث بیان کی ، ( کہا : ) ہمیں جریر بن حازم نے اسی سند کے ساتھ ( یہی ) حدیث بیان کی"],[4269,"شیبان بن فروخ نے کہا : ہمیں جریر بن حازم نے حدیث بیان کی ، ( کہا : ) ہمیں حسن نے حدیث سنائی ، ( کہا : ) ہمیں سیدنا عبدالرحمان بن سمرہ رضی اللہ عنہ نے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا : \"\" عبدالرحمان بن سمرہ! تم ( خود ) امارت کی درخواست مت کرو ، ( کیونکہ ) اگر وہ تمہیں مانگنے پر دی گئی تو تم اس کے حوالے کر دیے جاؤ گے اور اگر تمہیں بن مانگے ملے گی تو ( اللہ کی طرف سے ) تمہاری مدد کی جائے گی اور جب تم کسی کام پر قسم کھاؤ ، پھر اس کے بجائے کسی دوسرے کام کو اس سے بہتر دیکھو تو اپنی قسم کا کفارہ دو اور وہی اختیار کرو جو بہتر ہے ۔ \"\" ( امام مسلم کے شاگرد ) ابو احمد جلودی نے کہا : ہمیں ابو عباس ماسرجسی نے حدیث سنائی ، ( کہا : ) ہمیں شیبان بن فروخ نے حدیث بیان کی ، ( کہا : ) ہمیں جریر بن حازم نے اسی سند کے ساتھ ( یہی ) حدیث بیان کی",""],[4270,"یونس ، منصور ، حمید ، سماک بن عطیہ ، ہشام بن حسان ، معتمر کے والد ( سلیمان طرخان ) اور قتادہ ، ان سب نے حسن سے ، انہوں نے سیدنا عبدالرحمان بن سمرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث بیان کی اور معتمر کی اپنے والد ( سلیمان طرخان ) سے روایت کردہ حدیث میں امارت ( والی بات ) کا ذکر نہیں","",{"u2":"یونس، منصور، حمید، سماک بن عطیہ،ہشام بن حسان، معتمر کے والد (سلیمان طرخان) اور قتادہ، ان سب نے حسن سے، انہوں نے سیدنا عبدالرحمان بن سمرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث بیان کی اور معتمر کی اپنے والد (سلیمان طرخان) سے روایت کردہ حدیث میں امارت (والی بات) کا ذکر نہیں"}],[4271,"یحییٰ بن یحییٰ اور عمرو الناقد نے ہمیں حدیث بیان کی ۔ ۔ یحییٰ نے کہا : ہمیں ہشیم بن بشیر نے عبداللہ بن ابی صالح سے خبر دی اور عمرو نے کہا : ہمیں ہشیم بن بشیر نے حدیث بیان کی ، کہا : ہمیں عبداللہ بن ابی صالح نے خبر دی ۔ ۔ انہوں نے اپنے والد سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تمہاری قسم اسی بات پر ہو گی جس پر تمہارا ساتھی ( قسم لینے والا ) تمہاری تصدیق کرے گا ۔ \" اور عمرو نے کہا : \" جس کی تصدیق تمہارا ساتھی کرے گا","",{"u2":"یحییٰ بن یحییٰ اور عمرو الناقد نے ہمیں حدیث بیان کی۔۔ یحییٰ نے کہا: ہمیں ہشیم بن بشیر نے عبداللہ بن ابی صالح سے خبر دی اور عمرو نے کہا: ہمیں ہشیم بن بشیر نے حدیث بیان کی، کہا: ہمیں عبداللہ بن ابی صالح نے خبر دی۔۔ انہوں نے اپنے والد سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہاری قسم اسی بات پر ہو گی جس پر تمہارا ساتھی (قسم لینے والا) تمہاری تصدیق کرے گا۔\" اور عمرو نے کہا: \"جس کی تصدیق تمہارا ساتھی کرے گا"}],[4272,"یزید بن ہارون نے ہشیم سے ، انہوں نے عباد بن ابی صالح سے ، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" قسم ، حلف لینے والے کی نیت کے مطابق ہو گی","",{"u2":"یزید بن ہارون نے ہشیم سے، انہوں نے عباد بن ابی صالح سے، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قسم، حلف لینے والے کی نیت کے مطابق ہو گی"}],[4273,"محمد ( بن سیرین ) نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : حضرت سلیمان علیہ السلام کی ساٹھ بیویاں تھیں ، انہوں نے کہا : ( واللہ ) آج رات میں ان سب کے پاس جاؤں گا تو ان میں سے ہر بیوی حاملہ ہو گی اور ہر بیوی ( ایک شہسوار ) بچے کو جنم دے گی ، جو اللہ کی راہ میں لڑائی کرے گا ۔ تو ایک کے سوا ان میں سے کوئی حاملہ نہ ہوئی اور اس نے بھی ادھورے ( ناقص الخلقت ) بچے کو جنم دیا ۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اگر وہ ان شاءاللہ کہتے تو ان میں سے ہر بیوی شہسوار بچے کو جنم دیتی جو اللہ کی راہ میں لڑائی کرتا","",{"u2":"محمد (بن سیرین) نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: حضرت سلیمان علیہ السلام کی ساٹھ بیویاں تھیں، انہوں نے کہا: (واللہ) آج رات میں ان سب کے پاس جاؤں گا تو ان میں سے ہر بیوی حاملہ ہو گی اور ہر بیوی (ایک شہسوار) بچے کو جنم دے گی، جو اللہ کی راہ میں لڑائی کرے گا۔ تو ایک کے سوا ان میں سے کوئی حاملہ نہ ہوئی اور اس نے بھی ادھورے (ناقص الخلقت) بچے کو جنم دیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر وہ ان شاءاللہ کہتے تو ان میں سے ہر بیوی شہسوار بچے کو جنم دیتی جو اللہ کی راہ میں لڑائی کرتا"}],[4274,"ہشام بن حجیر نے طاوس سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" اللہ کے نبی سلیمان بن داود علیہ السلام نے کہا : ( واللہ ) آج رات میں ستر عورتوں کے پاس جاؤں گا ، وہ سب ایک ایک بچے کو جنم دیں گی جو اللہ کی راہ میں لڑائی کرے گا ۔ تو ان سے ان کے کسی ساتھی یا فرشتے نے کہا : ان شاءاللہ کہیں ۔ انہوں نے نہ کہا ، انہیں بھلا دیا گیا ، ان کی عورتوں میں سے ایک عورت کے سوا کسی نے بچے کو جنم نہ دیا ، اس نے بھی ادھورے بچے کو جنم دیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : اگر وہ ان شاءاللہ کہتے تو قسم تشنہ تکمیل نہ رہتی اور یہ ( قسم ) ان کی ضرورت ( اپنی اولاد کے ذریعے سے جہاد فی سبیل اللہ ) کی تکمیل کا سبب بھی بن جاتی","",{"u2":"ہشام بن حجیر نے طاوس سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"اللہ کے نبی سلیمان بن داود علیہ السلام نے کہا: (واللہ) آج رات میں ستر عورتوں کے پاس جاؤں گا، وہ سب ایک ایک بچے کو جنم دیں گی جو اللہ کی راہ میں لڑائی کرے گا۔تو ان سے ان کے کسی ساتھی یا فرشتے نے کہا: ان شاءاللہ کہیں۔ انہوں نے نہ کہا، انہیں بھلا دیا گیا، ان کی عورتوں میں سے ایک عورت کے سوا کسی نے بچے کو جنم نہ دیا، اس نے بھی ادھورے بچے کو جنم دیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اگر وہ ان شاءاللہ کہتے تو قسم تشنہ تکمیل نہ رہتی اور یہ (قسم) ان کی ضرورت (اپنی اولاد کے ذریعے سے جہاد فی سبیل اللہ) کی تکمیل کا سبب بھی بن جاتی"}],[4275,"سفیان نے ابوزناد سے ، انہوں نے اعرج سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند یا اسی کے ہم معنی روایت بیان کی","",{"u2":"سفیان نے ابوزناد سے، انہوں نے اعرج سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند یا اسی کے ہم معنی روایت بیان کی"}],[4276,"طاوس کے بیٹے نے اپنے والد سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : حضرت سلیمان بن داود علیہ السلام نے کہا : آج رات میں ستر عورتوں کے پاس چکر لگاؤں گا ، ان میں سے ہر عورت ( بیوی یا کنیز ) ایک بچے کو جنم دے گی جو اللہ کی راہ میں لڑائی کرے گا ۔ تو ان سے کہا گیا : ان شاءاللہ کہئے ۔ انہوں نے نہ کہا ( انہیں بھلا دیا گیا ) ۔ وہ ان کے پاس گئے تو ان میں سے صرف ایک عورت نے ادھے انسان کو جنم دیا ۔ کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اگر وہ ان شاءاللہ کہہ لیتے تو قسم تشنہ تکمیل نہ رہتی اور یہ ( قسم ) ان کے دل کی حاجت پوری ہونے کا ذریعہ بھی بن جاتی","",{"u2":"طاوس کے بیٹے نے اپنے والد سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: حضرت سلیمان بن داود علیہ السلام نے کہا: آج رات میں ستر عورتوں کے پاس چکر لگاؤں گا، ان میں سے ہر عورت (بیوی یا کنیز) ایک بچے کو جنم دے گی جو اللہ کی راہ میں لڑائی کرے گا۔ تو ان سے کہا گیا: ان شاءاللہ کہئے۔ انہوں نے نہ کہا (انہیں بھلا دیا گیا)۔ وہ ان کے پاس گئے تو ان میں سے صرف ایک عورت نے ادھے انسان کو جنم دیا۔ کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر وہ ان شاءاللہ کہہ لیتے تو قسم تشنہ تکمیل نہ رہتی اور یہ (قسم) ان کے دل کی حاجت پوری ہونے کا ذریعہ بھی بن جاتی"}],[4277,"ورقاء نے ابوزناد سے ، انہوں نے اعرج سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" حضرت سلیمان بن داود علیہ السلام نے کہا : آج رات میں نوے عورتوں کے پاس جاؤں گا ان میں سے ہر عورت ایک شہسوار بچے کو جنم دے گی جو ( بڑا ہو کر ) اللہ کی راہ میں لڑائی کرے گا ۔ تو ان کے ساتھی نے ان سے کہا : ان شاءاللہ کہیں ۔ انہوں نے ان شاءاللہ نہ کہا ۔ وہ ان سب کے پاس گئے تو ان میں سے ایک عورت کے سوا کوئی حاملہ نہ ہوئی اور اس نے بھی آدھے بچے کو جنم دیا ۔ اس ذات کی قسم جس کے ہاتھ میں محمد ( صلی اللہ علیہ وسلم ) کی جان ہے! اگر وہ ان شاءاللہ کہہ دیتے تو وہ سب گھوڑوں پر سوار ہو کر اللہ کی راہ میں جہاد کرتے","",{"u2":"ورقاء نے ابوزناد سے، انہوں نے اعرج سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"حضرت سلیمان بن داود علیہ السلام نے کہا: آج رات میں نوے عورتوں کے پاس جاؤں گا ان میں سے ہر عورت ایک شہسوار بچے کو جنم دے گی جو (بڑا ہو کر) اللہ کی راہ میں لڑائی کرے گا۔ تو ان کے ساتھی نے ان سے کہا: ان شاءاللہ کہیں۔ انہوں نے ان شاءاللہ نہ کہا۔ وہ ان سب کے پاس گئے تو ان میں سے ایک عورت کے سوا کوئی حاملہ نہ ہوئی اور اس نے بھی آدھے بچے کو جنم دیا۔ اس ذات کی قسم جس کے ہاتھ میں محمد (صلی اللہ علیہ وسلم) کی جان ہے! اگر وہ ان شاءاللہ کہہ دیتے تو وہ سب گھوڑوں پر سوار ہو کر اللہ کی راہ میں جہاد کرتے"}],[4278,"موسیٰ بن عقبہ نے ابوزناد سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ، البتہ انہوں نے کہا : \" ان میں سے ہر ایک کے حمل میں ایسا بچہ ہوتا جو اللہ تعالیٰ کی راہ میں جہاد کرتا","",{"u2":"موسیٰ بن عقبہ نے ابوزناد سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی، البتہ انہوں نے کہا: \"ان میں سے ہر ایک کے حمل میں ایسا بچہ ہوتا جو اللہ تعالیٰ کی راہ میں جہاد کرتا"}],[4279,"ہمام بن منبہ سے روایت ہے ، انہوں نے کہا : یہ احادیث ہیں جو ہمیں سیدنا ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں ، پھر انہوں نے چند احادیث بیان کیں ، ان میں سے یہ تھی : اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ کی قسم! تم میں سے کسی کا اپنے گھر والوں کے بارے میں اپنی قسم پر اصرار کرنا اس کے لیے اللہ کے ہاں اس سے زیادہ گناہ کا باعث ہے کہ وہ اس قسم کے لیے اللہ کا مقرر کردہ کفارہ دے ۔ \" ( اور اسے توڑ کر درست کام کرے اور گھر والوں کو آرام پہنچائے)","",{"u2":"ہمام بن منبہ سے روایت ہے، انہوں نے کہا: یہ احادیث ہیں جو ہمیں سیدنا ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں، پھر انہوں نے چند احادیث بیان کیں، ان میں سے یہ تھی: اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی قسم! تم میں سے کسی کا اپنے گھر والوں کے بارے میں اپنی قسم پر اصرار کرنا اس کے لیے اللہ کے ہاں اس سے زیادہ گناہ کا باعث ہے کہ وہ اس قسم کے لیے اللہ کا مقرر کردہ کفارہ دے۔\" (اور اسے توڑ کر درست کام کرے اور گھر والوں کو آرام پہنچائے"}],[4280,"یحییٰ بن سعید قطان نے ہمیں عبیداللہ سے حدیث بیان کی ، انہوں نے کہا : مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی کہ سیدنا عمر رضی اللہ عنہ نے کہا : اللہ کے رسول! میں نے جاہلیت میں نذر مانی تھی کہ میں ایک رات مسجد حرام میں اعتکاف کروں گا ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اپنی نذر پوری کرو","",{"u2":"یحییٰ بن سعید قطان نے ہمیں عبیداللہ سے حدیث بیان کی، انہوں نے کہا: مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی کہ سیدنا عمر رضی اللہ عنہ نے کہا: اللہ کے رسول! میں نے جاہلیت میں نذر مانی تھی کہ میں ایک رات مسجد حرام میں اعتکاف کروں گا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنی نذر پوری کرو"}],[4281,"ابواسامہ ، عبدالوہاب ثقفی ، حفص بن غیاث اور شعبہ ، ان سب نے عبیداللہ سے حدیث بیان کی ، انہوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، ان میں سے حفص نے کہا : ( یہ حدیث ) سیدنا عمر رضی اللہ عنہ سے مروی ہے ، ابواسامہ اور ثقفی کی حدیث میں ایک رات اعتکاف کرنے کا تذکرہ ہے اور شعبہ کی حدیث میں ہے کہ انہوں نے کہا : دن کے اعتکاف کی نذر مانی ۔ حفص کی حدیث میں دن یا رات کا ذکر نہیں ہے","",{"u2":"ابواسامہ، عبدالوہاب ثقفی، حفص بن غیاث اور شعبہ، ان سب نے عبیداللہ سے حدیث بیان کی، انہوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی، ان میں سے حفص نے کہا: (یہ حدیث) سیدنا عمر رضی اللہ عنہ سے مروی ہے، ابواسامہ اور ثقفی کی حدیث میں ایک رات اعتکاف کرنے کا تذکرہ ہے اور شعبہ کی حدیث میں ہے کہ انہوں نے کہا: دن کے اعتکاف کی نذر مانی۔ حفص کی حدیث میں دن یا رات کا ذکر نہیں ہے"}],[4282,"جریر بن حازم نے ہمیں حدیث سنائی کہ ایوب نے انہیں حدیث بیان کی ، انہیں نافع نے حدیث سنائی ، انہیں سیدنا عبداللہ بن عمر رضی اللہ عنہ نے حدیث بیان کی کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا ، آپ اس وقت طائف سے لوٹنے کے بعد جعرنہ میں ( ٹھہرے ہوئے ) تھے ، انہوں نے عرض کی : اے اللہ کے رسول! میں نے جاہلیت میں نذر مانی تھی کہ میں ایک دن مسجد حرام میں اعتکاف کروں گا ، آپ کی کیا رائے ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" جاؤ اور ایک دن کا اعتکاف کرو ۔ \"\" کہا : رسول اللہ صلی اللہ علیہ وسلم نے انہیں خُمس سے ایک لونڈی عطا فرمائی تھی ، جب رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کے قیدیوں کو آزاد کیا ، تو سیدنا عمر بن خطاب رضی اللہ عنہ نے ان کی آوازیں سنیں ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں آزاد کر دیا ہے ۔ تو انہوں نے پوچھا : کیا ماجرا ہے؟ لوگوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کے قیدیوں کو آزاد کر دیا ہے ۔ تو سیدنا عمر رضی اللہ عنہ نے ( اپنے بیٹے سے ) کہا : عبداللہ! اس لونڈی کے پاس جاؤ اور اسے آزاد کر دو ۔ ( یہ حنین کا موقع تھا)","",{"u2":"جریر بن حازم نے ہمیں حدیث سنائی کہ ایوب نے انہیں حدیث بیان کی، انہیں نافع نے حدیث سنائی، انہیں سیدنا عبداللہ بن عمر رضی اللہ عنہ نے حدیث بیان کی کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا، آپ اس وقت طائف سے لوٹنے کے بعد جعرنہ میں (ٹھہرے ہوئے) تھے، انہوں نے عرض کی: اے اللہ کے رسول! میں نے جاہلیت میں نذر مانی تھی کہ میں ایک دن مسجد حرام میں اعتکاف کروں گا، آپ کی کیا رائے ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جاؤ اور ایک دن کا اعتکاف کرو۔\"\nکہا: رسول اللہ صلی اللہ علیہ وسلم نے انہیں خُمس سے ایک لونڈی عطا فرمائی تھی، جب رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کے قیدیوں کو آزاد کیا، تو سیدنا عمر بن خطاب رضی اللہ عنہ نے ان کی آوازیں سنیں، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں آزاد کر دیا ہے۔ تو انہوں نے پوچھا: کیا ماجرا ہے؟ لوگوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کے قیدیوں کو آزاد کر دیا ہے۔ تو سیدنا عمر رضی اللہ عنہ نے (اپنے بیٹے سے) کہا: عبداللہ! اس لونڈی کے پاس جاؤ اور اسے آزاد کر دو۔ (یہ حنین کا موقع تھا"}],[4283,"معمر نے ہمیں ایوب سے خبر دی ، انہوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : جب نبی صلی اللہ علیہ وسلم حنین سے واپس ہوئے تو سیدنا عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے ایک دن کے اعتکاف کی نذر کے متعلق پوچھا جو انہوں نے جاہلیت میں مانی تھی ۔ ۔ پھر جریر بن حازم کی حدیث کے ہم معنی بیان کیا","",{"u2":"معمر نے ہمیں ایوب سے خبر دی، انہوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: جب نبی صلی اللہ علیہ وسلم حنین سے واپس ہوئے تو سیدنا عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے ایک دن کے اعتکاف کی نذر کے متعلق پوچھا جو انہوں نے جاہلیت میں مانی تھی۔۔ پھر جریر بن حازم کی حدیث کے ہم معنی بیان کیا"}],[4284,"حماد بن زید نے ہمیں حدیث بیان کی ، کہا : ہمیں ایوب نے نافع سے حدیث بیان کی ، انہوں نے کہا : سیدنا ابن عمر رضی اللہ عنہ کے پاس جعرانہ سے رسول اللہ صلی اللہ علیہ وسلم کے عمرے کا تذکرہ کیا گیا تو انہوں نے کہا : آپ نے وہاں سے عمرہ نہیں کیا ۔ کہا : سیدنا عمر رضی اللہ عنہ نے جاہلیت میں ایک رات کے اعتکاف کی نذر مانی تھی ۔ ۔ پھر انہوں نے ایوب سے جریر بن حازم اور معمر کی روایت کردہ حدیث کے ہم معنیٰ بیان کیا","",{"u2":"حماد بن زید نے ہمیں حدیث بیان کی، کہا: ہمیں ایوب نے نافع سے حدیث بیان کی، انہوں نے کہا: سیدنا ابن عمر رضی اللہ عنہ کے پاس جعرانہ سے رسول اللہ صلی اللہ علیہ وسلم کے عمرے کا تذکرہ کیا گیا تو انہوں نے کہا: آپ نے وہاں سے عمرہ نہیں کیا۔ کہا: سیدنا عمر رضی اللہ عنہ نے جاہلیت میں ایک رات کے اعتکاف کی نذر مانی تھی۔۔ پھر انہوں نے ایوب سے جریر بن حازم اور معمر کی روایت کردہ حدیث کے ہم معنیٰ بیان کیا"}],[4285,"ایوب اور محمد بن اسحاق دونوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے نذر کے بارے میں یہی حدیث بیان کی اور ان دونوں کی حدیث میں ایک دن کے اعتکاف کا ذکر ہے","",{"u2":"ایوب اور محمد بن اسحاق دونوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے نذر کے بارے میں یہی حدیث بیان کی اور ان دونوں کی حدیث میں ایک دن کے اعتکاف کا ذکر ہے"}],[4286,"ابوعوانہ نے فراس سے ، انہوں نے ابوصالح ذکوان سے اور انہوں نے ابو عمر زاذان سے روایت کی ، انہوں نے کہا : میں سیدنا ابن عمر رضی اللہ عنہ کے ہاں آیا جبکہ انہوں نے ایک غلام کو آزاد کیا تھا ۔ کہا : انہوں نے زمین سے لکڑی یا کوئی چیز پکڑی اور کہا : اس میں اتنا بھی اجر نہیں جو اس کے برابر ہو اس کے سوا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \" جس نے اپنے غلام کو تھپڑ مارا یا اسے زد و کوب کیا تو اس کا کفارہ یہ ہے کہ اسے آزاد کرے \" ( اس حکم کو ماننے کا اجر ہو سکتا ہے)","",{"u2":"ابوعوانہ نے فراس سے، انہوں نے ابوصالح ذکوان سے اور انہوں نے ابو عمر زاذان سے روایت کی، انہوں نے کہا: میں سیدنا ابن عمر رضی اللہ عنہ کے ہاں آیا جبکہ انہوں نے ایک غلام کو آزاد کیا تھا۔ کہا: انہوں نے زمین سے لکڑی یا کوئی چیز پکڑی اور کہا: اس میں اتنا بھی اجر نہیں جو اس کے برابر ہو اس کے سوا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جس نے اپنے غلام کو تھپڑ مارا یا اسے زد و کوب کیا تو اس کا کفارہ یہ ہے کہ اسے آزاد کرے\" (اس حکم کو ماننے کا اجر ہو سکتا ہے"}],[4287,"شعبہ نے ہمیں فراس سے باقی ماندہ سابقہ سند سے حدیث بیان کی کہ سیدنا ابن عمر رضی اللہ عنہ نے اپنے غلام کو بلایا اور اس کی پشت پر ( ضرب کا ) نشان دیکھا تو اس سے کہا : میں نے تمہیں دکھ دیا ہے؟ اس نے کہا : نہیں ۔ انہوں نے کہا : تم آزاد ہو ۔ کہا : پھر انہوں نے زمین سے کوئی چیز پکڑی اور کہا : میرے لیے اس میں اتنا بھی اجر نہیں ہے جو اس کے برابر ہو ۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا ، آپ فرما رہے تھے : \"\" جس نے اپنے غلام کو حد لگانے کے لیے ( ایسے کام پر ) مارا جو اس نے نہیں کیا یا اسے طمانچہ مارا تو اس کا کفارہ یہ ہے کہ اسے آزاد کر دے","",{"u2":"شعبہ نے ہمیں فراس سے باقی ماندہ سابقہ سند سے حدیث بیان کی کہ سیدنا ابن عمر رضی اللہ عنہ نے اپنے غلام کو بلایا اور اس کی پشت پر (ضرب کا) نشان دیکھا تو اس سے کہا: میں نے تمہیں دکھ دیا ہے؟ اس نے کہا: نہیں۔ انہوں نے کہا: تم آزاد ہو۔\nکہا: پھر انہوں نے زمین سے کوئی چیز پکڑی اور کہا: میرے لیے اس میں اتنا بھی اجر نہیں ہے جو اس کے برابر ہو۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا، آپ فرما رہے تھے: \"جس نے اپنے غلام کو حد لگانے کے لیے (ایسے کام پر) مارا جو اس نے نہیں کیا یا اسے طمانچہ مارا تو اس کا کفارہ یہ ہے کہ اسے آزاد کر دے"}],[4288,"وکیع اور عبدالرحمان ( بن مہدی ) دونوں نے سفیان سے حدیث بیان کی ، انہوں نے فراس سے شعبہ اور ابو عوانہ کی سند کے ساتھ روایت کی ، ابن مہدی نے اپنی حدیث میں حد کا ذکر کیا ہے اور وکیع کی حدیث میں ہے : \" جس نے اپنے غلام کو طمانچہ مارا ۔ \" انہوں نے حد کا ذکر نہیں کیا","",{"u2":"وکیع اور عبدالرحمان (بن مہدی) دونوں نے سفیان سے حدیث بیان کی، انہوں نے فراس سے شعبہ اور ابو عوانہ کی سند کے ساتھ روایت کی، ابن مہدی نے اپنی حدیث میں حد کا ذکر کیا ہے اور وکیع کی حدیث میں ہے: \"جس نے اپنے غلام کو طمانچہ مارا۔\" انہوں نے حد کا ذکر نہیں کیا"}],[4289,"معاویہ بن سوید ( بن مُقرن ) سے روایت ہے ، انہوں نے کہا : میں نے اپنے ایک غلام کو طمانچہ مارا اور بھاگ گیا ، پھر میں ظہر سے تھوڑی دیر پہلے آیا اور اپنے والد کے پیچھے نماز پڑھی ، انہوں نے اسے اور مجھے بلایا ، پھر ( غلام سے ) کہا : اس سے پورا بدلہ لے لو تو اس نے معاف کر دیا ۔ پھر انہوں ( میرے والد ) نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے عہد میں ہم بنی مقرن کے پاس صرف ایک خادمہ تھی ، ہم میں سے کسی نے اسے طمانچہ مار دیا ، نبی صلی اللہ علیہ وسلم کو یہ بات پہنچی تو آپ نے فرمایا : اسے آزاد کر دو ۔ لوگوں نے کہا : ان کے پاس اس کے علاوہ اور خادم نہیں ہے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" وہ ( فی الحال ) اس سے خدمت لیں ، جب اس سے بے نیاز ہو جائیں ( دوسرا انتظام ہو جائے ) تو اس کا راستہ چھوڑ دیں ( اسے آزاد کر دیں)","",{"u2":"معاویہ بن سوید (بن مُقرن) سے روایت ہے، انہوں نے کہا: میں نے اپنے ایک غلام کو طمانچہ مارا اور بھاگ گیا، پھر میں ظہر سے تھوڑی دیر پہلے آیا اور اپنے والد کے پیچھے نماز پڑھی، انہوں نے اسے اور مجھے بلایا، پھر (غلام سے) کہا: اس سے پورا بدلہ لے لو تو اس نے معاف کر دیا۔ پھر انہوں (میرے والد) نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے عہد میں ہم بنی مقرن کے پاس صرف ایک خادمہ تھی، ہم میں سے کسی نے اسے طمانچہ مار دیا، نبی صلی اللہ علیہ وسلم کو یہ بات پہنچی تو آپ نے فرمایا: اسے آزاد کر دو۔ لوگوں نے کہا: ان کے پاس اس کے علاوہ اور خادم نہیں ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ (فی الحال) اس سے خدمت لیں، جب اس سے بے نیاز ہو جائیں (دوسرا انتظام ہو جائے) تو اس کا راستہ چھوڑ دیں (اسے آزاد کر دیں"}],[4290,"ابن ادریس نے ہمیں حصین سے حدیث بیان کی ، انہوں نے ہلال بن یساف سے روایت کی ، انہوں نے کہا : ایک بوڑھے نے جلدی کی اور اپنے خادم کو طمانچہ دے مارا ، تو سیدنا سوید بن مقرن رضی اللہ عنہ نے اس سے کہا : تمہیں اس کے شریف چہرے کے سوا اور کوئی جگہ نہ ملی؟ میں نے اپنے آپ کو مقرن کے بیٹوں میں سے ساتواں بیٹا پایا ، ہمارے پاس صرف ایک خادمہ تھی ، ہم میں سے سب سے چھوٹے نے اسے طمانچہ مارا تو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اس کو آزاد کر دینے کا حکم دیا","",{"u2":"ابن ادریس نے ہمیں حصین سے حدیث بیان کی، انہوں نے ہلال بن یساف سے روایت کی، انہوں نے کہا: ایک بوڑھے نے جلدی کی اور اپنے خادم کو طمانچہ دے مارا، تو سیدنا سوید بن مقرن رضی اللہ عنہ نے اس سے کہا: تمہیں اس کے شریف چہرے کے سوا اور کوئی جگہ نہ ملی؟ میں نے اپنے آپ کو مقرن کے بیٹوں میں سے ساتواں بیٹا پایا، ہمارے پاس صرف ایک خادمہ تھی، ہم میں سے سب سے چھوٹے نے اسے طمانچہ مارا تو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اس کو آزاد کر دینے کا حکم دیا"}],[4291,"ہلال بن یساف رضی اللہ عنہ سے روایت ہے ہم كپڑا بیچتے تھے سوید بن مقرن كے گھر میں جو نعمان بن مقرن كے بھائی تھے ، ایك لونڈی وہا ں نكلی اور اس نے ہم میں سے كسی كو كوئی بات كہی تو اس نے لونڈی كو طمانچہ مارا ۔ سوید ناراض ہوئے پھر بیان كیا اسی طرح جیسے اوپر گذرا ۔"],[4292,"عبدالصمد نے ہمیں حدیث سنائی ، کہا : ہمیں شعبہ نے حدیث سنائی ، کہا : مجھ سے محمد بن منکدر نے کہا : تمہارا نام کیا ہے؟ میں نے کہا : شعبہ ۔ تو محمد نے کہا : مجھے ابو شعبہ عراقی ( مولیٰ سوید بن مقرن ) نے سوید بن مقرن رضی اللہ عنہ سے حدیث بیان کی کہ ان کی لونڈی کو کسی انسان نے تھپڑ مارا تو سوید رضی اللہ عنہ نے اس سے کہا : کیا تمہیں معلوم نہیں کہ چہرہ حرمت والا ( ہوتا ) ہے اور کہا : میں نے خود کو ، اور میں اپنے بھائیوں میں ساتواں تھا ، رسول اللہ صلی اللہ علیہ وسلم کی معیت میں دیکھا اور ہمارے پاس سوائے ایک کے کوئی اور خادم نہ تھا ۔ ہم میں سے کسی نے عمدا اسے طمانچہ مار دیا تو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا کہ ہم اسے آزاد کر دی","",{"u2":"عبدالصمد نے ہمیں حدیث سنائی، کہا: ہمیں شعبہ نے حدیث سنائی، کہا: مجھ سے محمد بن منکدر نے کہا: تمہارا نام کیا ہے؟ میں نے کہا: شعبہ۔ تو محمد نے کہا: مجھے ابو شعبہ عراقی (مولیٰ سوید بن مقرن) نے سوید بن مقرن رضی اللہ عنہ سے حدیث بیان کی کہ ان کی لونڈی کو کسی انسان نے تھپڑ مارا تو سوید رضی اللہ عنہ نے اس سے کہا: کیا تمہیں معلوم نہیں کہ چہرہ حرمت والا (ہوتا) ہے اور کہا: میں نے خود کو، اور میں اپنے بھائیوں میں ساتواں تھا، رسول اللہ صلی اللہ علیہ وسلم کی معیت میں دیکھا اور ہمارے پاس سوائے ایک کے کوئی اور خادم نہ تھا۔ ہم میں سے کسی نے عمدا اسے طمانچہ مار دیا تو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا کہ ہم اسے آزاد کر دی"}],[4293,"وہب بن جریر نے کہا : ہمیں شعبہ نے خبر دی کہ محمد بن منکدر نے مجھ سے پوچھا : تمہارا نام کیا ہے؟ آگے عبدالصمد کی حدیث کے مانند بیان کیا","",{"u2":"وہب بن جریر نے کہا: ہمیں شعبہ نے خبر دی کہ محمد بن منکدر نے مجھ سے پوچھا: تمہارا نام کیا ہے؟ آگے عبدالصمد کی حدیث کے مانند بیان کیا"}],[4294,"عبدالواحد بن زیاد نے ہمیں حدیث بیان کی ، کہا : ہمیں اعمش نے ابراہیم تیمی سے حدیث سنائی ، انہوں نے اپنے والد ( یزید بن شریک تیمی ) سے روایت کی ، انہوں نے کہا : سیدنا ابو مسعود بدری رضی اللہ عنہ نے کہا : میں اپنے ایک غلام کو کوڑے سے مار رہا تھا تو میں نے اپنے پیچھے سے آواز سنی : \" ابو مسعود! جان لو ۔ \" میں غصے کی وجہ سے آواز نہ پہچان سکا ، کہا : جب وہ ( کہنے والے ) میرے قریب پہنچے تو وہ رسول اللہ صلی اللہ علیہ وسلم تھے ، آپ فرما رہے تھے : \" ابو مسعود! جان لو ، ابو مسعود! جان لو ۔ \" کہا : میں نے اپنے ہاتھ سے کوڑا پھینک دیا ، تو آپ نے فرمایا : \" ابو مسعود! جان لو ۔ اس غلام پر تمہیں جتنا اختیار ہے اس کی نسبت اللہ تم پر زیادہ اختیار رکھتا ہے ۔ \" کہا : تو میں نے کہا : اس کے بعد میں کسی غلام کو کبھی نہیں ماروں گا","",{"u2":"عبدالواحد بن زیاد نے ہمیں حدیث بیان کی، کہا: ہمیں اعمش نے ابراہیم تیمی سے حدیث سنائی، انہوں نے اپنے والد (یزید بن شریک تیمی) سے روایت کی، انہوں نے کہا: سیدنا ابو مسعود بدری رضی اللہ عنہ نے کہا: میں اپنے ایک غلام کو کوڑے سے مار رہا تھا تو میں نے اپنے پیچھے سے آواز سنی: \"ابو مسعود! جان لو۔\" میں غصے کی وجہ سے آواز نہ پہچان سکا، کہا: جب وہ (کہنے والے) میرے قریب پہنچے تو وہ رسول اللہ صلی اللہ علیہ وسلم تھے، آپ فرما رہے تھے: \"ابو مسعود! جان لو، ابو مسعود! جان لو۔\" کہا: میں نے اپنے ہاتھ سے کوڑا پھینک دیا، تو آپ نے فرمایا: \"ابو مسعود! جان لو۔ اس غلام پر تمہیں جتنا اختیار ہے اس کی نسبت اللہ تم پر زیادہ اختیار رکھتا ہے۔\" کہا: تو میں نے کہا: اس کے بعد میں کسی غلام کو کبھی نہیں ماروں گا"}],[4295,"جریر ، سفیان اور ابوعوانہ سب نے اعمش سے عبدالواحد کی ( سابقہ ) سند کے ساتھ اس کی حدیث کے ہم معنی حدیث بیان کی ، مگر جریر کی حدیث میں ہے : آپ کی ہیبت کی وجہ سے میرے ہاتھ سے کوڑا گر گیا","",{"u2":"جریر، سفیان اور ابوعوانہ سب نے اعمش سے عبدالواحد کی (سابقہ) سند کے ساتھ اس کی حدیث کے ہم معنی حدیث بیان کی، مگر جریر کی حدیث میں ہے: آپ کی ہیبت کی وجہ سے میرے ہاتھ سے کوڑا گر گیا"}],[4296,"ابومعاویہ نے ہمیں حدیث بیان کی ، کہا : ہمیں اعمش نے ابراہیم تیمی سے حدیث بیان کی ، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابو مسعود انصاری رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں اپنے غلام کو مار رہا تھا تو میں نے اپنے پیچھے سے آواز سنی : \" ابومسعود! جان لو ، اس پر تمہارا جتنا اختیار ہے ، اس کی نسبت اللہ تم پر زیادہ اختیار رکھتا ہے ۔ \" میں مڑا تو دیکھا رسول اللہ صلی اللہ علیہ وسلم تھے ، میں نے عرض کی : اللہ کے رسول! وہ اللہ کی رضا کے لیے آزاد ہے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" دیکھو! اگر تم ایسا نہ کرتے تو تمہیں آگ جھلساتی یا تمہیں آگ چھوتی","",{"u2":"ابومعاویہ نے ہمیں حدیث بیان کی، کہا: ہمیں اعمش نے ابراہیم تیمی سے حدیث بیان کی، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابو مسعود انصاری رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں اپنے غلام کو مار رہا تھا تو میں نے اپنے پیچھے سے آواز سنی: \"ابومسعود! جان لو، اس پر تمہارا جتنا اختیار ہے، اس کی نسبت اللہ تم پر زیادہ اختیار رکھتا ہے۔\" میں مڑا تو دیکھا رسول اللہ صلی اللہ علیہ وسلم تھے، میں نے عرض کی: اللہ کے رسول! وہ اللہ کی رضا کے لیے آزاد ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"دیکھو! اگر تم ایسا نہ کرتے تو تمہیں آگ جھلساتی یا تمہیں آگ چھوتی"}],[4297,"ابن ابی عدی نے شعبہ سے ، انہوں نے سلیمان سے ، انہوں نے ابراہیم تیمی سے ، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابو مسعود رضی اللہ عنہ سے روایت کی کہ وہ اپنے غلام کو مار رہے تھے تو اس نے اعوذباللہ ( میں تمہاری مار سے اللہ کی پناہ میں آتا ہوں ) کہنا شروع کر دیا ۔ کہا : تو ( وہ اس کی بات کی طرف متوجہ نہ ہو پائے اور ) اسے مارتے رہے ۔ پھر اس نے کہا : میں اللہ کے رسول صلی اللہ علیہ وسلم کی پناہ میں آتا ہوں تو ( انہیں اندازہ ہوا کہ رسول اللہ صلی اللہ علیہ وسلم تشریف لے آئے ہیں ) انہوں نے اسے چھوڑ دیا ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ کی قسم! اللہ تم پر اس سے زیادہ اختیار رکھتا ہے جتنا تم اس پر رکھتے ہو ۔ \" کہا : تو انہوں نے اسے آزاد کر دیا ۔","",{"u2":"ابن ابی عدی نے شعبہ سے، انہوں نے سلیمان سے، انہوں نے ابراہیم تیمی سے، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابو مسعود رضی اللہ عنہ سے روایت کی کہ وہ اپنے غلام کو مار رہے تھے تو اس نے اعوذباللہ (میں تمہاری مار سے اللہ کی پناہ میں آتا ہوں) کہنا شروع کر دیا۔ کہا: تو (وہ اس کی بات کی طرف متوجہ نہ ہو پائے اور) اسے مارتے رہے۔ پھر اس نے کہا: میں اللہ کے رسول صلی اللہ علیہ وسلم کی پناہ میں آتا ہوں تو (انہیں اندازہ ہوا کہ رسول اللہ صلی اللہ علیہ وسلم تشریف لے آئے ہیں) انہوں نے اسے چھوڑ دیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی قسم! اللہ تم پر اس سے زیادہ اختیار رکھتا ہے جتنا تم اس پر رکھتے ہو۔\" کہا: تو انہوں نے اسےآزاد کر دیا۔"}],[4298,"محمد بن جعفر نے ہمیں شعبہ سے ، اسی سند کے ساتھ خبر دی اور انہوں نے یہ الفاظ بیان نہیں کیے : \" میں اللہ کی پناہ میں آتا ہوں \" ( اور ) \" اللہ کے رسول صلی اللہ علیہ وسلم کی پناہ میں آتا ہوں","",{"u2":"محمد بن جعفر نے ہمیں شعبہ سے، اسی سند کے ساتھ خبر دی اور انہوں نے یہ الفاظ بیان نہیں کیے: \"میں اللہ کی پناہ میں آتا ہوں\" (اور) \"اللہ کے رسول صلی اللہ علیہ وسلم کی پناہ میں آتا ہوں"}],[4299,"عبداللہ بن نمیر نے کہا : ہمیں فضیل بن غزوان نے حدیث بیان کی ، انہوں نے کہا : میں نے عبدالرحمان بن ابی نعم سے سنا ( کہا : ) مجھے سیدنا ابوہریرہ رضی اللہ عنہ نے حدیث بیان کی ، انہوں نے کہا : ابوالقاسم صلی اللہ علیہ وسلم نے فرمایا : \" جس نے اپنے غلام پر زنا کی تہمت لگائی اسے قیامت کے دن حد لگائی جائے گی ، الا یہ کہ وہ ( غلام ) ویسا ہو جیسا اس نے کہا ہے","",{"u2":"عبداللہ بن نمیر نے کہا: ہمیں فضیل بن غزوان نے حدیث بیان کی، انہوں نے کہا: میں نے عبدالرحمان بن ابی نعم سے سنا (کہا:) مجھے سیدنا ابوہریرہ رضی اللہ عنہ نے حدیث بیان کی، انہوں نے کہا: ابوالقاسم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اپنے غلام پر زنا کی تہمت لگائی اسے قیامت کے دن حد لگائی جائے گی، الا یہ کہ وہ (غلام) ویسا ہو جیسا اس نے کہا ہے"}],[4300,"وکیع اور اسحاق بن یوسف ازرق دونوں نے فضیل بن غزوان سے اسی سند کے ساتھ حدیث بیان کی اور ان دونوں کی حدیث میں ہے : میں نے ابوالقاسم نبی التوبہ صلی اللہ علیہ وسلم سے سنا","",{"u2":"وکیع اور اسحاق بن یوسف ازرق دونوں نے فضیل بن غزوان سے اسی سند کے ساتھ حدیث بیان کی اور ان دونوں کی حدیث میں ہے: میں نے ابوالقاسم نبی التوبہ صلی اللہ علیہ وسلم سے سنا"}],[4301,"وکیع نے کہا : ہمیں اعمش نے معرور بن سوید سے حدیث بیان کی ، انہوں نے کہا : ہم زَبذہ ( کے مقام ) میں سیدنا ابوذر رضی اللہ عنہ کے ہاں سے گزرے ، ان ( کے جسم ) پر ایک چادر تھی اور ان کے غلام ( کے جسم ) پر بھی ویسی ہی چادر تھی ۔ تو ہم نے کہا : ابوذر! اگر آپ ان دونوں ( چادروں ) کو اکٹھا کر لیتے تو یہ ایک حلہ بن جاتا ۔ انہوں نے کہا : میرے اور میرے کسی ( مسلمان ) بھائی کے درمیان تلخ کلامی ہوئی ، اس کی ماں عجمی تھی ، میں نے اسے اس کی ماں کے حوالے سے عار دلائی تو اس نے نبی صلی اللہ علیہ وسلم کے پاس میری شکایت کر دی ، میں نبی صلی اللہ علیہ وسلم سے ملا تو آپ نے فرمایا : \" ابوذر! تم ایسے آدمی ہو کہ تم میں جاہلیت ( کی عادت موجود ) ہے ۔ \" میں نے کہا : اللہ کے رسول! جو دوسروں کو برا بھلا کہتا ہے وہ اس کے ماں اور باپ کو برا بھلا کہتے ہیں ۔ آپ نے فرمایا : \" ابوذر! تم ایسے آدمی ہو جس میں جاہلیت ہے ، وہ ( چاہے کنیز زادے ہوں یا غلام یا غلام زادے ) تمہارے بھائی ہیں ، اللہ نے انہیں تمہارے ماتحت کیا ہے ، تم انہیں وہی کھلاؤ جو خود کھاتے ہو اور وہی پہناؤ جو خود پہنتے ہو اور ان پر ایسے کام کی ذمہ داری نہ ڈالو جو ان کے بس سے باہر ہو ، اگر ان پر ( مشکل کام کی ) ذمہ داری ڈالو تو ان کی اعانت کرو","",{"u2":"وکیع نے کہا: ہمیں اعمش نے معرور بن سوید سے حدیث بیان کی، انہوں نے کہا: ہم زَبذہ (کے مقام) میں سیدنا ابوذر رضی اللہ عنہ کے ہاں سے گزرے، ان (کے جسم) پر ایک چادر تھی اور ان کے غلام (کے جسم) پر بھی ویسی ہی چادر تھی۔ تو ہم نے کہا: ابوذر! اگر آپ ان دونوں (چادروں) کو اکٹھا کر لیتے تو یہ ایک حلہ بن جاتا۔ انہوں نے کہا: میرے اور میرے کسی (مسلمان) بھائی کے درمیان تلخ کلامی ہوئی، اس کی ماں عجمی تھی، میں نے اسے اس کی ماں کے حوالے سے عار دلائی تو اس نے نبی صلی اللہ علیہ وسلم کے پاس میری شکایت کر دی، میں نبی صلی اللہ علیہ وسلم سے ملا تو آپ نے فرمایا: \"ابوذر! تم ایسے آدمی ہو کہ تم میں جاہلیت (کی عادت موجود) ہے۔\" میں نے کہا: اللہ کے رسول! جو دوسروں کو برا بھلا کہتا ہے وہ اس کے ماں اور باپ کو برا بھلا کہتے ہیں۔ آپ نے فرمایا: \"ابوذر! تم ایسے آدمی ہو جس میں جاہلیت ہے، وہ (چاہے کنیز زادے ہوں یا غلام یا غلام زادے) تمہارے بھائی ہیں، اللہ نے انہیں تمہارے ماتحت کیا ہے، تم انہیں وہی کھلاؤ جو خود کھاتے ہو اور وہی پہناؤ جو خود پہنتے ہو اور ان پر ایسے کام کی ذمہ داری نہ ڈالو جو ان کے بس سے باہر ہو، اگر ان پر (مشکل کام کی) ذمہ داری ڈالو تو ان کی اعانت کرو"}],[4302,"زہیر ، ابومعاویہ اور عیسیٰ بن یونس سب نے اعمش سے اسی سند کے ساتھ حدیث بیان کی ، زہیر اور ابو معاویہ کی حدیث میں آپ کے فرمان : \" تم ایسے آدمی ہو جس میں جاہلیت ہے \" کے بعد یہ اضافہ ہے ، انہوں نے کہا : میں نے عرض کی : بڑھاپے کی اس گھڑی کے باوجود بھی ( جاہلیت کی عادت باقی ہے؟ ) آپ صلی اللہ علیہ وسلم نے فرمایا : \" ہاں ۔ \" ابو معاویہ کی روایت میں ہے : \" ہاں ، تمہارے بڑھاپے کی اس گھڑی کے باوجود بھی \" عیسیٰ کی حدیث میں ہے : \" اگر وہ اس پر ایسی ذمہ داری ڈال دے جو اس کی طاقت سے باہر ہے تو ( بہتر ہے ) اسے بیچ دے ۔ \" ( غلام پر ظلم کے گناہ سے بچ جائے ۔ ) زہیر کی حدیث میں ہے : \" تو وہ اس ( کام ) میں اس کی اعانت کرے ۔ \" ابو معاویہ کی حدیث میں وہ اسے بیچ دے اور وہ اس کی اعانت کرے کے الفاظ نہیں ہیں اور ان کی حدیث آپ کے فرمان : اس پر ایسی ذمہ داری نہ ڈالے جو اس کے بس سے باہر ہوپر ختم ہو گئی","",{"u2":"زہیر، ابومعاویہ اور عیسیٰ بن یونس سب نے اعمش سے اسی سند کے ساتھ حدیث بیان کی، زہیر اور ابو معاویہ کی حدیث میں آپ کے فرمان: \"تم ایسے آدمی ہو جس میں جاہلیت ہے\" کے بعد یہ اضافہ ہے، انہوں نے کہا: میں نے عرض کی: بڑھاپے کی اس گھڑی کے باوجود بھی (جاہلیت کی عادت باقی ہے؟) آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں۔\" ابو معاویہ کی روایت میں ہے: \"ہاں، تمہارے بڑھاپے کی اس گھڑی کے باوجود بھی \"عیسیٰ کی حدیث میں ہے: \"اگر وہ اس پر ایسی ذمہ داری ڈال دے جو اس کی طاقت سے باہر ہے تو (بہتر ہے) اسے بیچ دے۔\" (غلام پر ظلم کے گناہ سے بچ جائے۔) زہیر کی حدیث میں ہے: \"تو وہ اس (کام) میں اس کی اعانت کرے۔\" ابو معاویہ کی حدیث میں وہ اسے بیچ دے اور وہ اس کی اعانت کرے کے الفاظ نہیں ہیں اور ان کی حدیث آپ کے فرمان:اس پر ایسی ذمہ داری نہ ڈالے جو اس کے بس سے باہر ہوپر ختم ہو گئی"}],[4303,"واصل احدب نے معرور بن سوید سے روایت کی ، انہوں نے کہا : میں نے سیدنا ابوذر رضی اللہ عنہ کو اس حالت میں دیکھا کہ ان ( کے جسم ) پر ( آدھا ) حلہ تھا اور ان کے غلام پر بھی اسی طرح کا ( آدھا ) حلہ تھا ، میں نے ان سے اس کے بارے میں پوچھا ، کہا : تو انہوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں انہوں نے ایک آدمی کو برا بھلا کہا اور اسے اس کی ماں ( کے عجمی ہونے ) کی ( بنا پر ) عار دلائی ، کہا : تو وہ آدمی نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ کو یہ بات بتائی ، اس پر نبی صلی اللہ علیہ وسلم نے فرمایا : \" تم ایسے آدمی ہو جس میں جاہلیت ( کی خو ) ہے ، وہ تمہارے بھائی اور خدمت گزار ہیں ، اللہ نے انہیں تمہارے ماتحت کیا ہے ، تو جس کا بھائی اس کے ماتحت ہو وہ اسے اسی کھانے میں سے کھلائے جو وہ خود کھاتا ہے اور وہی لباس پہنائے جو خود پہنتا ہے اور ان کے ذمے ایسا کام نہ لگاؤ جو ان کے بس سے باہر ہو اور اگر تم ان کے ذمے لگاؤ تو اس پر ان کی اعانت کرو","",{"u2":"واصل احدب نے معرور بن سوید سے روایت کی، انہوں نے کہا: میں نے سیدنا ابوذر رضی اللہ عنہ کو اس حالت میں دیکھا کہ ان (کے جسم) پر (آدھا) حلہ تھا اور ان کے غلام پر بھی اسی طرح کا (آدھا) حلہ تھا، میں نے ان سے اس کے بارے میں پوچھا، کہا: تو انہوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں انہوں نے ایک آدمی کو برا بھلا کہا اور اسے اس کی ماں (کے عجمی ہونے) کی (بنا پر) عار دلائی، کہا: تو وہ آدمی نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ کو یہ بات بتائی، اس پر نبی صلی اللہ علیہ وسلم نے فرمایا: \"تم ایسے آدمی ہو جس میں جاہلیت (کی خو) ہے، وہ تمہارے بھائی اور خدمت گزار ہیں، اللہ نے انہیں تمہارے ماتحت کیا ہے، تو جس کا بھائی اس کے ماتحت ہو وہ اسے اسی کھانے میں سے کھلائے جو وہ خود کھاتا ہے اور وہی لباس پہنائے جو خود پہنتا ہے اور ان کے ذمے ایسا کام نہ لگاؤ جو ان کے بس سے باہر ہو اور اگر تم ان کے ذمے لگاؤ تو اس پر ان کی اعانت کرو"}],[4304,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : طعام اور لباس غلام کا حق ہے اور اس پر کام کی اتنی ذمہ داری نہ ڈالی جائے جو اس کے بس میں نہ ہو ۔","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا:طعام اور لباس غلام کا حق ہے اور اس پر کام کی اتنی ذمہ داری نہ ڈالی جائے جو اس کے بس میں نہ ہو۔"}],[4305,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کسی کا خادم اس کے لیے کھانا تیار کرے ، پھر اس کے سامنے پیش کرے اور اسی نے ( آگ کی ) تپش اور دھواں برداشت کیا ہے تو وہ اسے اپنے ساتھ بٹھائے اور وہ ( غلام بھی اس کے ساتھ ) کھائے اور اگر کھانا بہت سے لوگوں نے کھانا لیا ہو ، ( یعنی ) کم ہو تو اس کے ہاتھ میں ایک یا دو لقمے ( ضرور ) دے","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کسی کا خادم اس کے لیے کھانا تیار کرے، پھر اس کے سامنے پیش کرے اور اسی نے (آگ کی) تپش اور دھواں برداشت کیا ہے تو وہ اسے اپنے ساتھ بٹھائے اور وہ (غلام بھی اس کے ساتھ) کھائے اور اگر کھانا بہت سے لوگوں نے کھانا لیا ہو، (یعنی) کم ہو تو اس کے ہاتھ میں ایک یا دو لقمے (ضرور) دے"}],[4306,"امام مالک نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" غلام جب اپنے آقا کی خیرخواہی کرے اور اچھی طرح اللہ کی بندگی کرے تو اس کے لیے دوہرا اجر ہے","",{"u2":"امام مالک نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"غلام جب اپنے آقا کی خیرخواہی کرے اور اچھی طرح اللہ کی بندگی کرے تو اس کے لیے دوہرا اجر ہے"}],[4307,"عبیداللہ اور اسامہ نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے امام مالک کی حدیث کے مانند حدیث بیان کی","",{"u2":"عبیداللہ اور اسامہ نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے امام مالک کی حدیث کے مانند حدیث بیان کی"}],[4308,"ابوطاہر اور حرملہ بن یحییٰ نے ہمیں حدیث بیان کی ، دونوں نے کہا : ہمیں ابن وہب نے خبر دی ، کہا : مجھے یونس نے ابن شہاب سے خبر دی ، انہوں نے کہا : میں نے سعید بن مسیب سے سنا ، وہ کہہ رہے تھے ، سیدنا ابوہریرہ رضی اللہ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" اچھی طرح ذمہ داریاں نبھانے والے کسی کے مملوک ( غلام ) کے لیے دو اجر ہیں ۔ \"\" اس ذات کی قسم جس کے ہاتھ میں ابوہریرہ کی جان ہے! اگر اللہ کی راہ میں جہاد ، حج اور اپنی والدہ کی خدمت ( جیسے کام ) نہ ہوتے تو میں پسند کرتا کہ میں مروں تو غلام ہوں ۔ ( سعید بن مسیب نے ) کہا : ہمیں یہ بات پہنچی ہے کہ سیدنا ابوہریرہ رضی اللہ عنہ اپنی والدہ کی وفات تک ان کے ساتھ رہنے ( اور خدمت کرنے ) کی بنا پر حج نہیں کرتے تھے ۔ ابوطاہر نے اپنی حدیث میں \"\" اچھی طرح ذمہ داریاں نبھانے والا \"\" عَبد \"\" ( غلام ) کہا ، \"\" مملوک \"\" نہیں کہا","",{"u2":"ابوطاہر اور حرملہ بن یحییٰ نے ہمیں حدیث بیان کی، دونوں نے کہا: ہمیں ابن وہب نے خبر دی، کہا: مجھے یونس نے ابن شہاب سے خبر دی، انہوں نے کہا: میں نے سعید بن مسیب سے سنا، وہ کہہ رہے تھے، سیدنا ابوہریرہ رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اچھی طرح ذمہ داریاں نبھانے والے کسی کے مملوک (غلام) کے لیے دو اجر ہیں۔\" اس ذات کی قسم جس کے ہاتھ میں ابوہریرہ کی جان ہے! اگر اللہ کی راہ میں جہاد، حج اور اپنی والدہ کی خدمت (جیسے کام) نہ ہوتے تو میں پسند کرتا کہ میں مروں تو غلام ہوں۔\n(سعید بن مسیب نے) کہا: ہمیں یہ بات پہنچی ہے کہ سیدنا ابوہریرہ رضی اللہ عنہ اپنی والدہ کی وفات تک ان کے ساتھ رہنے (اور خدمت کرنے) کی بنا پر حج نہیں کرتے تھے۔\nابوطاہر نے اپنی حدیث میں \"اچھی طرح ذمہ داریاں نبھانے والا \"عَبد\" (غلام) کہا، \"مملوک\" نہیں کہا"}],[4309,"ابوصفوان اموی نے ہمیں حدیث بیان کی ( کہا : ) مجھے یونس نے ابن شہاب سے اسی سند کے ساتھ خبر دی ، انہوں نے \" ہمیں یہ بات پہنچی \" اور اس کے بعد والا حصہ بیان نہیں کیا","",{"u2":"ابوصفوان اموی نے ہمیں حدیث بیان کی (کہا:) مجھے یونس نے ابن شہاب سے اسی سند کے ساتھ خبر دی، انہوں نے \"ہمیں یہ بات پہنچی\" اور اس کے بعد والا حصہ بیان نہیں کیا"}],[4310,"ابو معاویہ نے اعمش سے ، انہوں نے ابوصالح سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب غلام اللہ کا حق اور اپنے آقاؤں کا حق ادا کرے تو اس کے لیے دو اجر ہیں ۔ \" کہا : میں نے یہ حدیث کعب کو سنائی تو کعب نے کہا : نہ اس ( غلام ) کا حساب ہو گا نہ ہی کم مال والے مومن کا حساب ہو گا","",{"u2":"ابو معاویہ نے اعمش سے، انہوں نے ابوصالح سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب غلام اللہ کا حق اور اپنے آقاؤں کا حق ادا کرے تو اس کے لیے دو اجر ہیں۔\" کہا: میں نے یہ حدیث کعب کو سنائی تو کعب نے کہا: نہ اس (غلام) کا حساب ہو گا نہ ہی کم مال والے مومن کا حساب ہو گا"}],[4311,"جریر نے اعمش سے اسی سند کے ساتھ حدیث بیان کی","",{"u2":"جریر نے اعمش سے اسی سند کے ساتھ حدیث بیان کی"}],[4312,"ہمام بن منبہ نے کہا : یہ احادیث ہیں جو سیدنا ابوہریرہ رضی اللہ عنہ نے ہمیں رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں ، انہوں نے کئی احادیث بیان کیں ، ان میں سے یہ بھی تھی : اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : کسی غلام کا اس حال میں فوت ہو جانا کیا خوب ہے کہ وہ اللہ کی بندگی اور اپنے آقا کی خدمت اچھے طریقے سے کر رہا تھا! اس کے لیے کیا خوب ہے یہ ( زندگی)","",{"u2":"ہمام بن منبہ نے کہا: یہ احادیث ہیں جو سیدنا ابوہریرہ رضی اللہ عنہ نے ہمیں رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں، انہوں نے کئی احادیث بیان کیں، ان میں سے یہ بھی تھی: اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:کسی غلام کا اس حال میں فوت ہو جانا کیا خوب ہے کہ وہ اللہ کی بندگی اور اپنے آقا کی خدمت اچھے طریقے سے کر رہا تھا! اس کے لیے کیا خوب ہے یہ (زندگی)"}],[4313,"امام مالک نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے کسی ( مشترکہ ) غلام ( کی ملکیت میں ) سے اپنا حصہ آزاد کیا اور اس کے پاس اتنا مال ہے جو غلام کی قیمت کو پہنچتا ہے تو اس کی مصفانہ قیمت لگائی جائے گی اور اس کے شریکوں کو ان کے حصے دیے جائیں گے اور غلام اس کی طرف سے آزاد ہو جائے گا ورنہ وہ اتنا ہی آزاد رہے گا جتنا پہلے ہو گیا ہے","",{"u2":"امام مالک نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کسی (مشترکہ) غلام (کی ملکیت میں) سے اپنا حصہ آزاد کیا اور اس کے پاس اتنا مال ہے جو غلام کی قیمت کو پہنچتا ہے تو اس کی مصفانہ قیمت لگائی جائے گی اور اس کے شریکوں کو ان کے حصے دیے جائیں گے اور غلام اس کی طرف سے آزاد ہو جائے گا ورنہ وہ اتنا ہی آزاد رہے گا جتنا پہلے ہو گیا ہے"}],[4314,"عبیداللہ نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے کسی غلام ( کی ملکیت میں ) سے اپنا حصہ آزاد کیا ، اگر اس کے پاس اتنا مال ہے جو اس کی قیمت کو پہنچتا ہے تو اس کی پوری آزادی اس پر ( لازم ) ہے ۔ اور اگر اس کے پاس مال نہیں ہے تو وہ جتنا آزاد ہو چکا تھا اتنا ہی آزاد رہے گا","",{"u2":"عبیداللہ نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کسی غلام (کی ملکیت میں) سے اپنا حصہ آزاد کیا، اگر اس کے پاس اتنا مال ہے جو اس کی قیمت کو پہنچتا ہے تو اس کی پوری آزادی اس پر (لازم) ہے۔ اور اگر اس کے پاس مال نہیں ہے تو وہ جتنا آزاد ہو چکا تھا اتنا ہی آزاد رہے گا"}],[4315,"جریر بن حازم نے عبداللہ بن عمر رضی اللہ عنہ کے مولیٰ نافع سے ، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے کسی ( مشترکہ ) غلام ( کی ملکیت میں ) سے اپنا حصہ آزاد کیا اور اس کے پاس اتنی مقدار میں مال ہے جو اس کی قیمت کو پہنچتا ہے ، تو اس کی منصفانہ قیمت لگائی جائے گی ( اور شریک کو اس کا حصہ ادا کر کے غلام اس کی طرف سے آزاد کیا جائے گا ۔ ) ورنہ وہ جتنا آزاد ہو چکا تھا اتنا ہی آزاد رہے گا","",{"u2":"جریر بن حازم نے عبداللہ بن عمر رضی اللہ عنہ کے مولیٰ نافع سے، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کسی (مشترکہ) غلام (کی ملکیت میں) سے اپنا حصہ آزاد کیا اور اس کے پاس اتنی مقدار میں مال ہے جو اس کی قیمت کو پہنچتا ہے، تو اس کی منصفانہ قیمت لگائی جائے گی (اور شریک کو اس کا حصہ ادا کر کے غلام اس کی طرف سے آزاد کیا جائے گا۔) ورنہ وہ جتنا آزاد ہو چکا تھا اتنا ہی آزاد رہے گا"}],[4316,"لیث بن سعد ، یحییٰ بن سعید ، ایوب ، اسماعیل بن امیہ ، ابن ابی ذئب اور اسامہ بن زید سب نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث بیان کی ، ایوب اور یحییٰ بن سعید کی حدیث کے سوا ان میں سے کسی کی حدیث میں یہ الفاظ نہیں ہیں : \" اور اگر اس کے پال مال نہیں تو وہ جتنا آزاد ہو چکا تھا اتنا ہی آزاد رہے گا ۔ \" اور انہی دونوں نے یہ جملہ کہا اور ان دونوں ( ایوب اور یحییٰ ) نے یہ بھی کہا : ہمیں معلوم نہیں ہے کہ یہ حدیث کا حصہ ہے یا نافع نے اپنی طرف سے کہا ہے ۔ اور لیث بن سعد کی حدیث کے سوا ان میں سے کسی کی روایت میں سمعت رسول اللہ صلی اللہ علیہ وسلم ( میں نے رسول اللہ صلی اللہ علیہ وسلم سےسنا ) کے الفاظ نہیں ہیں ۔","",{"u2":"لیث بن سعد، یحییٰ بن سعید، ایوب، اسماعیل بن امیہ، ابن ابی ذئب اور اسامہ بن زید سب نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث بیان کی، ایوب اور یحییٰ بن سعید کی حدیث کے سوا ان میں سے کسی کی حدیث میں یہ الفاظ نہیں ہیں: \"اور اگر اس کے پال مال نہیں تو وہ جتنا آزاد ہو چکا تھا اتنا ہی آزاد رہے گا۔\" اور انہی دونوں نے یہ جملہ کہا اور ان دونوں (ایوب اور یحییٰ) نے یہ بھی کہا: ہمیں معلوم نہیں ہے کہ یہ حدیث کا حصہ ہے یا نافع نے اپنی طرف سے کہا ہے۔ اور لیث بن سعد کی حدیث کے سوا ان میں سے کسی کی روایت میں سمعت رسول اللہ صلی اللہ علیہ وسلم (میں نے رسول اللہ صلی اللہ علیہ وسلم سےسنا) کے الفاظ نہیں ہیں۔"}],[4317,"عمرو نے سالم بن عبداللہ سے اور انہوں نے اپنے والد سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے اپنے اور کسی دوسرے کے درمیان مشترک غلام کو آزاد کیا تو کمی بیشی کے بغیر اس کے مال میں سے ( غلام کی ) منصفانہ قیمت لگائی جائے گی ، پھر اگر وہ خوش حال ہوا تو وہ اس کے مال سے اس کی طرف سے آزاد ہو جائے گا","",{"u2":"عمرو نے سالم بن عبداللہ سے اور انہوں نے اپنے والد سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اپنے اور کسی دوسرے کے درمیان مشترک غلام کو آزاد کیا تو کمی بیشی کے بغیر اس کے مال میں سے (غلام کی) منصفانہ قیمت لگائی جائے گی، پھر اگر وہ خوش حال ہوا تو وہ اس کے مال سے اس کی طرف سے آزاد ہو جائے گا"}],[4318,"زہری نے سالم سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا : جس نے کسی غلام ( کی ملکیت میں ) سے اپنا حصہ آزاد کیا تو اس کا باقی حصہ بھی اس کے مال سے آزاد ہو گا ، بشرطیکہ اس کے پاس اتنا مال ہو جو غلام کی قیمت کو پہنچ جائے","",{"u2":"زہری نے سالم سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا:جس نے کسی غلام (کی ملکیت میں) سے اپنا حصہ آزاد کیا تو اس کا باقی حصہ بھی اس کے مال سے آزاد ہو گا، بشرطیکہ اس کے پاس اتنا مال ہو جو غلام کی قیمت کو پہنچ جائے"}],[4319,"محمد بن جعفر نے کہا : ہمیں شعبہ نے قتادہ سے حدیث بیان کی ، انہوں نے نضر بن انس سے ، انہوں نے بشیر بن نہیک سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے دو آدمیوں کے مشترکہ غلام کے بارے میں جن میں سے ایک ( اپنا حصہ ) آزاد کر دیتا ہے ، فرمایا : \" وہ ( دوسرے کا ) ضامن ہے ۔ ( کہ اس کے حصے کی قیمت اسے مل جائے گی)","",{"u2":"محمد بن جعفر نے کہا: ہمیں شعبہ نے قتادہ سے حدیث بیان کی، انہوں نے نضر بن انس سے، انہوں نے بشیر بن نہیک سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے دو آدمیوں کے مشترکہ غلام کے بارے میں جن میں سے ایک (اپنا حصہ) آزاد کر دیتا ہے، فرمایا: \"وہ (دوسرے کا) ضامن ہے۔ (کہ اس کے حصے کی قیمت اسے مل جائے گی"}],[4320,"عبیداللہ کے والد معاذ عنبری نے کہا : ہمیں شعبہ نے اسی سند کے ساتھ حدیث بیان کی ، آپ نے فرمایا : \" جس نے غلام ( کی ملکیت ) میں سے اپنا حصہ آزاد کیا تو وہ اسی کے مال سے ( پورا ) آزاد ہو جائے گا","",{"u2":"عبیداللہ کے والد معاذ عنبری نے کہا: ہمیں شعبہ نے اسی سند کے ساتھ حدیث بیان کی، آپ نے فرمایا: \"جس نے غلام (کی ملکیت) میں سے اپنا حصہ آزاد کیا تو وہ اسی کے مال سے (پورا) آزاد ہو جائے گا"}],[4321,"اسماعیل بن ابراہیم نے ابن ابی عروبہ سے ، انہوں نے قتادہ سے ، انہوں نے نضر بن انس سے ، انہوں نے بشیر بن نہیک سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" جس نے غلام ( کی ملکیت ) میں سے اپنا حصہ آزاد کیا ، اگر اس کے پاس مال ہے تو اس کی ( پوری ) آزادی اسی کے مال کے ذریعے سے ہو گی اور اگر اس کے پاس مال نہیں ہے تو کسی جبری مشقت میں ڈالے بغیر اس غلام سے ( بقیہ قیمت کی ادائیگی کے لیے ) کام کروایا جائے گا","",{"u2":"اسماعیل بن ابراہیم نے ابن ابی عروبہ سے، انہوں نے قتادہ سے، انہوں نے نضر بن انس سے، انہوں نے بشیر بن نہیک سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"جس نے غلام (کی ملکیت) میں سے اپنا حصہ آزاد کیا، اگر اس کے پاس مال ہے تو اس کی (پوری) آزادی اسی کے مال کے ذریعے سے ہو گی اور اگر اس کے پاس مال نہیں ہے تو کسی جبری مشقت میں ڈالے بغیر اس غلام سے (بقیہ قیمت کی ادائیگی کے لیے) کام کروایا جائے گا"}],[4322,"علی بن مسہر ، محمد بن بشر اور عیسیٰ بن یونس سب نے ابن ابی عروبہ سے اسی سند کے ساتھ حدیث بیان کی اور عیسیٰ کی حدیث میں ہے : \" اسے کسی مشقت میں ڈالے بغیر ، اس شخص کے حصے ( کی ادائیگی ) کے لیے کام لیا جائے گا جس نے آزاد نہیں کیا","",{"u2":"علی بن مسہر، محمد بن بشر اور عیسیٰ بن یونس سب نے ابن ابی عروبہ سے اسی سند کے ساتھ حدیث بیان کی اور عیسیٰ کی حدیث میں ہے: \"اسے کسی مشقت میں ڈالے بغیر، اس شخص کے حصے (کی ادائیگی) کے لیے کام لیا جائے گا جس نے آزاد نہیں کیا"}],[4323,"اسماعیل بن علیہ نے ایوب سے ، انہوں نے ابوقلابہ سے ، انہوں نے ابومہلب سے اور انہوں نے سیدنا عمران بن حصین رضی اللہ عنہ سے روایت کی کہ ایک آدمی نے اپنی موت کے وقت اپنے چھ غلام آزاد کیے اور اس کے پاس ان کے سوا اور کوئی مال نہ تھا تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں بلوایا اور تین گروپوں میں تقسیم کیا ، پھر ان کے درمیان قرعہ ڈالا ، اس کے بعد دو کو آزاد کر دیا اور چار کو غلام ہی برقرار رکھا اور آپ نے اسے سرزنش کی","",{"u2":"اسماعیل بن علیہ نے ایوب سے، انہوں نے ابوقلابہ سے، انہوں نے ابومہلب سے اور انہوں نے سیدنا عمران بن حصین رضی اللہ عنہ سے روایت کی کہ ایک آدمی نے اپنی موت کے وقت اپنے چھ غلام آزاد کیے اور اس کے پاس ان کے سوا اور کوئی مال نہ تھا تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں بلوایا اور تین گروپوں میں تقسیم کیا، پھر ان کے درمیان قرعہ ڈالا، اس کے بعد دو کو آزاد کر دیا اور چار کو غلام ہی برقرار رکھا اور آپ نے اسے سرزنش کی"}],[4324,"حماد اور ( عبدالوہاب ) ثقفی دونوں نے ایوب سے اسی سند کے ساتھ حدیث بیان کی ، حماد کی حدیث ابن عُلیہ کی حدیث کی طرح ہے اور ثقفی کی حدیث میں ہے : انصار کے ایک آدمی نے اپنی موت کے وقت وصیت کی اور چھ غلام آزاد کر دیے","",{"u2":"حماد اور (عبدالوہاب) ثقفی دونوں نے ایوب سے اسی سند کے ساتھ حدیث بیان کی، حماد کی حدیث ابن عُلیہ کی حدیث کی طرح ہے اور ثقفی کی حدیث میں ہے: انصار کے ایک آدمی نے اپنی موت کے وقت وصیت کی اور چھ غلام آزاد کر دیے"}],[4325,"یزید بن زریع نے ہمیں حدیث بیان کی ، کہا : ہمیں ہشام بن حسان نے محمد بن سیرین سے حدیث بیان کی ، انہوں نے سیدنا عمران بن حصین رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ابن علیہ اور حماد کی حدیث کے مانند روایت کی","",{"u2":"یزید بن زریع نے ہمیں حدیث بیان کی، کہا: ہمیں ہشام بن حسان نے محمد بن سیرین سے حدیث بیان کی، انہوں نے سیدنا عمران بن حصین رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ابن علیہ اور حماد کی حدیث کے مانند روایت کی"}],[4326,"حماد بن زید نے عمرو بن دینار سے ، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ انصار میں سے ایک آدمی نے اپنی موت کے بعد اپنے غلام کو آزاد قرار دیا ، اس کے پاس اس کے سوا اور کوئی مال نہ تھا ۔ نبی صلی اللہ علیہ وسلم کو یہ بات پہنچی تو آپ نے فرمایا : \"\" اس ( غلام ) کو مجھ سے کون خریدے گا؟ \"\" اسے نعیم بن عبداللہ رضی اللہ عنہ نے آٹھ سو درہم میں خرید لیا تو آپ نے وہ ( رقم ) اس آدمی کے حوالے کر دی ۔ عمرو نے کہا : میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : وہ قبطی غلام تھا ( ابن زبیر رضی اللہ عنہ کی امارت کے ) پہلے سال فوت ہوا ۔ ( اپنی فوت کے بعد غلام کو آزاد کرنے والے کو ایک تہائی سے زیادہ ترکے میں وصیت کا اختیار ہی نہ تھا)","",{"u2":"حماد بن زید نے عمرو بن دینار سے، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ انصار میں سے ایک آدمی نے اپنی موت کے بعد اپنے غلام کو آزاد قرار دیا، اس کے پاس اس کے سوا اور کوئی مال نہ تھا۔ نبی صلی اللہ علیہ وسلم کو یہ بات پہنچی تو آپ نے فرمایا: \"اس (غلام) کو مجھ سے کون خریدے گا؟\" اسے نعیم بن عبداللہ رضی اللہ عنہ نے آٹھ سو درہم میں خرید لیا تو آپ نے وہ (رقم) اس آدمی کے حوالے کر دی۔\nعمرو نے کہا: میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: وہ قبطی غلام تھا (ابن زبیر رضی اللہ عنہ کی امارت کے) پہلے سال فوت ہوا۔ (اپنی فوت کے بعد غلام کو آزاد کرنے والے کو ایک تہائی سے زیادہ ترکے میں وصیت کا اختیار ہی نہ تھا"}],[4327,"سفیان بن عیینہ نے کہا : عمرو ( بن دینار ) نے سیدنا جابر رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : انصار کے ایک آدمی نے اپنی موت کے بعد اپنے غلام کے آزاد ہونے کی وصیت کی ، کہا : اس کے پاس اس کے علاوہ اور کوئی مال نہ تھا تو رسول اللہ صلی اللہ علیہ وسلم نے اسے فروخت کر دیا ‘ سیدنا جابر رضی اللہ عنہ نے کہا : اسے ابن نحام نے خریدا ، وہ قبطی غلام تھا ، سیدنا ابن زبیر رضی اللہ عنہ کی امارت کے پہلے سال فوت ہوا","",{"u2":"سفیان بن عیینہ نے کہا: عمرو (بن دینار) نے سیدنا جابر رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: انصار کے ایک آدمی نے اپنی موت کے بعد اپنے غلام کے آزاد ہونے کی وصیت کی، کہا: اس کے پاس اس کے علاوہ اور کوئی مال نہ تھا تو رسول اللہ صلی اللہ علیہ وسلم نے اسے فروخت کر دیا‘سیدنا جابر رضی اللہ عنہ نے کہا: اسے ابن نحام نے خریدا، وہ قبطی غلام تھا، سیدنا ابن زبیر رضی اللہ عنہ کی امارت کے پہلے سال فوت ہوا"}],[4328,"لیث بن سعد نے ابوزبیر سے ، انہوں نے سیدنا جابر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے مدبر ( مالک کی موت کے بعد آزاد ہونے والے غلام ) کے بارے میں عمرو بن دینار سے روایت کردہ حماد کی حدیث کے ہم معنی روایت کی","",{"u2":"لیث بن سعد نے ابوزبیر سے، انہوں نے سیدنا جابر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے مدبر (مالک کی موت کے بعد آزاد ہونے والے غلام) کے بارے میں عمرو بن دینار سے روایت کردہ حماد کی حدیث کے ہم معنی روایت کی"}],[4329,"عبدالمجید بن سہیل اور حسین بن ذکوان معلم نے عطاء سے ، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، اسی طرح مطر بن طہمان الوراق نے عطاء بن ابی رباح ، ابوزبیر اور عمرو بن دینار سے روایت کی کہ سیدنا جابر رضی اللہ عنہ نے انہیں مدبر کی بیع کے بارے میں حدیث بیان کی ، ان سب ( عطاء ، ابوزبیر اور عمرو ) نے کہا : انہوں ( جابر رضی اللہ عنہ ) نے نبی صلی اللہ علیہ وسلم سے اس حدیث کے ہم معنی روایت کی جو حماد اور ابن عیینہ نے عمرو سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے بیان کی"],[4330,"عبدالمجید بن سہیل اور حسین بن ذکوان معلم نے عطاء سے ، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، اسی طرح مطر بن طہمان الوراق نے عطاء بن ابی رباح ، ابوزبیر اور عمرو بن دینار سے روایت کی کہ سیدنا جابر رضی اللہ عنہ نے انہیں مدبر کی بیع کے بارے میں حدیث بیان کی ، ان سب ( عطاء ، ابوزبیر اور عمرو ) نے کہا : انہوں ( جابر رضی اللہ عنہ ) نے نبی صلی اللہ علیہ وسلم سے اس حدیث کے ہم معنی روایت کی جو حماد اور ابن عیینہ نے عمرو سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے بیان کی"],[4331,"عبدالمجید بن سہیل اور حسین بن ذکوان معلم نے عطاء سے ، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، اسی طرح مطر بن طہمان الوراق نے عطاء بن ابی رباح ، ابوزبیر اور عمرو بن دینار سے روایت کی کہ سیدنا جابر رضی اللہ عنہ نے انہیں مدبر کی بیع کے بارے میں حدیث بیان کی ، ان سب ( عطاء ، ابوزبیر اور عمرو ) نے کہا : انہوں ( جابر رضی اللہ عنہ ) نے نبی صلی اللہ علیہ وسلم سے اس حدیث کے ہم معنی روایت کی جو حماد اور ابن عیینہ نے عمرو سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے بیان کی",""],[4332,"لیث نے یحییٰ بن سعید سے ، انہوں نے بشیر بن یسار سے اور انہوں نے سیدنا سہل بن ابی حثمہ اور سیدنا رافع بن خدیج رضی اللہ عنہ سے روایت کی ، ان دونوں نے کہا : عبداللہ بن سہل بن زید اور محیصہ بن مسعود بن زید ( مدینہ سے ) نکلے یہاں تک کہ جب خیبر میں پہنچے تو وہاں کسی جگہ الگ الگ ہو گئے ، پھر ( یہ ہوتا ہے کہ ) اچانک محیصہ ، عبداللہ بن سہل کو مقتول پاتے ہیں ۔ انہوں نے اسے دفن کیا ، پھر وہ خود ، حویصہ بن مسعود اور ( مقتول کا حقیقی بھائی ) عبدالرحمان بن سہل رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے ، وہ ( عبدالرحمان ) سب سے کم عمر تھا ، چنانچہ عبدالرحمان اپنے دونوں ساتھیوں سے پہلے بات کرنے لگا تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا : \" بڑے کو اس کا مقام دو ، \" یعنی عمر میں بڑے کو ، تو وہ خاموش ہو گیا ، اس کے دونوں ساتھیوں نے بات کی اور ان کے ساتھ اس نے بھی بات کی ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو عبداللہ بن سہل کے قتل کی بات بتائی تو آپ صلی اللہ علیہ وسلم نے ان سے پوچھا : \" کیا تم پچاس قسمیں کھاؤ گے ، پھر اپنے ساتھی ( کے بدلے خون بہا ) ۔ ۔ یا ( فرمایا : ) بدلے میں اپنے قاتل ( سے دیت یا قصاص لینے ) ۔ ۔ کے حقدار بنو گے؟ \" انہوں نے جواب دیا : ہم قسمیں کیسے کھائیں جبکہ ہم نے دیکھا نہیں؟ آپ نے فرمایا : \" تو یہود پچاس قسمیں کھا کر تمہیں ( ان کے خلاف تمہارے مطالبے کے حق سے ) الگ کر دیں گے انہوں نے کہا : ہم کافر لوگوں کی قسمیں کیونکر قبول کریں؟ جب رسول اللہ صلی اللہ علیہ وسلم نے یہ صورت حال دیکھی آپ نے ( اپنی طرف سے ) اس کی دیت ادا کی","",{"u2":"لیث نے یحییٰ بن سعید سے، انہوں نے بشیر بن یسار سے اور انہوں نے حضرت سہل بن ابی حثمہ اور سیدنا رافع بن خدیج رضی اللہ عنہ سے روایت کی، ان دونوں نے کہا: عبداللہ بن سہل بن زید اور محیصہ بن مسعود بن زید (مدینہ سے) نکلے یہاں تک کہ جب خیبر میں پہنچے تو وہاں کسی جگہ الگ الگ ہو گئے، پھر (یہ ہوتا ہے کہ) اچانک محیصہ، عبداللہ بن سہل کو مقتول پاتے ہیں۔ انہوں نے اسے دفن کیا، پھر وہ خود، حویصہ بن مسعود اور (مقتول کا حقیقی بھائی) عبدالرحمان بن سہل رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے، وہ (عبدالرحمان) سب سے کم عمر تھا، چنانچہ عبدالرحمان اپنے دونوں ساتھیوں سے پہلے بات کرنے لگا تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"بڑے کو اس کا مقام دو،\" یعنی عمر میں بڑے کو، تو وہ خاموش ہو گیا، اس کے دونوں ساتھیوں نے بات کی اور ان کے ساتھ اس نے بھی بات کی، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو عبداللہ بن سہل کے قتل کی بات بتائی تو آپ صلی اللہ علیہ وسلم نے ان سے پوچھا: \"کیا تم پچاس قسمیں کھاؤ گے، پھر اپنے ساتھی (کے بدلے خون بہا)۔۔ یا (فرمایا:) بدلے میں اپنے قاتل (سے دیت یا قصاص لینے)۔۔ کے حقدار بنو گے؟\" انہوں نے جواب دیا: ہم قسمیں کیسے کھائیں جبکہ ہم نے دیکھا نہیں؟ آپ نے فرمایا: \"تو یہود پچاس قسمیں کھا کر تمہیں (ان کے خلاف تمہارے مطالبے کے حق سے) الگ کر دیں گے انہوں نے کہا: ہم کافر لوگوں کی قسمیں کیونکر قبول کریں؟ جب رسول اللہ صلی اللہ علیہ وسلم نے یہ صورت حال دیکھی آپ نے (اپنی طرف سے) اس کی دیت ادا کی"}],[4333,"حماد بن زید نے کہا : ہمیں یحییٰ بن سعید نے بشیر بن یسار سے ، انہوں نے سہل بن ابی حثمہ اور رافع بن خدیج سے روایت کی کہ محیصہ بن مسعود اور عبداللہ بن سہل خیبر کی طرف گئے اور ( وہاں ) کسی نخلستان میں الگ الگ ہو گئے ، عبداللہ بن سہل کو قتل کر دیا گیا تو ان لوگوں نے یہود پر الزام عائد کیا ، چنانچہ ان کے بھائی عبدالرحمان اور دو حویصہ اور محیصہ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے ۔ عبدالرحمان نے اپنے بھائی کے معاملے میں بات کی ، وہ ان سب میں کم عمر تھے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" بڑے کو بڑا بناؤ \"\" یا فرمایا : \"\" سب سے بڑا ( بات کا ) آغاز کرے ۔ \"\" ان دونوں نے اپنے ساتھی کے معاملے میں گفتگو کی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" تم میں سے پچاس آدمی ان میں سے ایک آدمی پر قسمیں کھائیں گے تو وہ اپنی رسی سمیت ( جس میں وہ بندھا ہو گا ) تمہارے حوالے کر دیا جائے گا؟ \"\" انہوں نے کہا : یہ ایسا معاملہ ہے جو ہم نے دیکھا نہیں ، ہم کیسے حلف اٹھائیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" تو یہود اپنے پچاس آدمیوں کی قسموں سے تم کو ( تمہارے دعوے کے استحقاق سے ) الگ کر دیں گے ۔ \"\" انہوں نے کہا : اے اللہ کے رسول! ( وہ تو ) کافر لوگ ہیں ۔ کہا : تو رسول اللہ صلی اللہ علیہ وسلم نے ان کی دیت اپنی طرف سے ادا کر دی ۔ سہل نے کہا : ایک دن میں ان کے باڑے میں گیا تو ان اونٹوں میں سے ایک اونٹنی نے مجھے لات ماری ۔ حماد نے کہا : یہ یا اس کی طرح ( بات کہی)","",{"u2":"حماد بن زید نے کہا: ہمیں یحییٰ بن سعید نے بشیر بن یسار سے، انہوں نے سہل بن ابی حثمہ اور رافع بن خدیج سے روایت کی کہ محیصہ بن مسعود اور عبداللہ بن سہل خیبر کی طرف گئے اور (وہاں) کسی نخلستان میں الگ الگ ہو گئے، عبداللہ بن سہل کو قتل کر دیا گیا تو ان لوگوں نے یہود پر الزام عائد کیا، چنانچہ ان کے بھائی عبدالرحمان اور دو حویصہ اور محیصہ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ عبدالرحمان نے اپنے بھائی کے معاملے میں بات کی، وہ ان سب میں کم عمر تھے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بڑے کو بڑا بناؤ\" یا فرمایا: \"سب سے بڑا (بات کا) آغاز کرے۔\" ان دونوں نے اپنے ساتھی کے معاملے میں گفتگو کی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے پچاس آدمی ان میں سے ایک آدمی پر قسمیں کھائیں گے تو وہ اپنی رسی سمیت (جس میں وہ بندھا ہو گا) تمہارے حوالے کر دیا جائے گا؟\" انہوں نے کہا: یہ ایسا معاملہ ہے جو ہم نے دیکھا نہیں، ہم کیسے حلف اٹھائیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو یہود اپنے پچاس آدمیوں کی قسموں سے تم کو (تمہارے دعوے کے استحقاق سے) الگ کر دیں گے۔\" انہوں نے کہا: اے اللہ کے رسول! (وہ تو) کافر لوگ ہیں۔ کہا: تو رسول اللہ صلی اللہ علیہ وسلم نے ان کی دیت اپنی طرف سے ادا کر دی۔\nسہل نے کہا: ایک دن میں ان کے باڑے میں گیا تو ان اونٹوں میں سے ایک اونٹنی نے مجھے لات ماری۔ حماد نے کہا: یہ یا اس کی طرح (بات کہی"}],[4334,"بشر بن مفضل نے کہا : ہمیں یحییٰ بن سعید نے بشیر بن یسار سے ، انہوں نے سہل بن ابی حثمہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی طرح روایت کی ، اور انہوں نے اپنی حدیث میں کہا : تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس سے اس کی دیت دے دی اور انہوں نے اپنی حدیث میں یہ نہیں کہا : مجھے ایک اونٹنی نے لات مار دی","",{"u2":"بشر بن مفضل نے کہا: ہمیں یحییٰ بن سعید نے بشیر بن یسار سے، انہوں نے سہل بن ابی حثمہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی طرح روایت کی، اور انہوں نے اپنی حدیث میں کہا: تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس سے اس کی دیت دے دی اور انہوں نے اپنی حدیث میں یہ نہیں کہا: مجھے ایک اونٹنی نے لات مار دی"}],[4335,"سفیان بن عیینہ اور عبدالوہاب ثقفی نے یحییٰ بن سعید سے ، انہوں نے بشیر بن یسار سے اور انہوں نے سہل بن ابی حثمہ سے انہی کی حدیث کی طرح حدیث بیان کی","",{"u2":"سفیان بن عیینہ اور عبدالوہاب ثقفی نے یحییٰ بن سعید سے، انہوں نے بشیر بن یسار سے اور انہوں نے سہل بن ابی حثمہ سے انہی کی حدیث کی طرح حدیث بیان کی"}],[4336,"سلیمان بن بلال نے یحییٰ بن سعید سے ، انہوں نے بشیر بن یسار سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں عبداللہ بن سہل بن زید انصاری اور محیصہ بن مسعود بن زید انصاری ، جن کا تعلق قبیلہ بنو حارثہ سے تھا ، خیبر کی طرف نکلے ، ان دنوں وہاں صلح تھی ، اور وہاں کے باشندے یہودی تھے ، تو وہ دونوں اپنی ضروریات کے پیش نظر الگ الگ ہو گئے ، بعد ازاں عبداللہ بن سہل قتل ہو گئے اور کھجور کے تنے کے ارد گرد بنائے گئے پانی کے ایک گڑھے میں مقتول حالت میں ملے ، ان کے ساتھی نے انہیں دفن کیا ، پھر مدینہ آئے اور مقتول کے بھائی عبدالرحمان بن سہل اور ( چچا زاد ) محیصہ اور حویصہ گئے اور رسول اللہ صلی اللہ علیہ وسلم سے عبداللہ اور ان کو قتل کیے جانے کی صورت حال اور جگہ بتائی ۔ بشیر کا خیال ہے اور وہ ان لوگوں سے حدیث بیان کرتے ہیں جنہوں نے رسول اللہ صلی اللہ علیہ وسلم کے اصحاب کو پایا کہ آپ نے ان سے فرمایا : \" کیا تم پچاس قسمیں کھا کر اپنے اتل ۔ ۔ یا اپنے ساتھی ۔ ۔ ( سے بدلہ/دیت ) کے حق دار بنو گے؟ \" انہوں نے کہا : اللہ کے رسول! نہ ہم نے دیکھا ، نہ وہاں موجود تھے ۔ ان ( بشیر ) کا خیال ہے کہ آپ نے فرمایا : \" تو یہود پچاس قسمیں کھا کر تمہیں ( اپنے دعوے کے استحقاق سے ) الگ کر دیں گے ۔ \" انہوں نے کہا : اے اللہ کے رسول! ہم کافر لوگوں کی قسمیں کیسے قبول کریں؟ بشیر کا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی طرف سے اس کی دیت ادا فرما دی","",{"u2":"سلیمان بن بلال نے یحییٰ بن سعید سے، انہوں نے بشیر بن یسار سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں عبداللہ بن سہل بن زید انصاری اور محیصہ بن مسعود بن زید انصاری، جن کا تعلق قبیلہ بنو حارثہ سے تھا، خیبر کی طرف نکلے، ان دنوں وہاں صلح تھی، اور وہاں کے باشندے یہودی تھے، تو وہ دونوں اپنی ضروریات کے پیش نظر الگ الگ ہو گئے، بعد ازاں عبداللہ بن سہل قتل ہو گئے اور کھجور کے تنے کے ارد گرد بنائے گئے پانی کے ایک گڑھے میں مقتول حالت میں ملے، ان کے ساتھی نے انہیں دفن کیا، پھر مدینہ آئے اور مقتول کے بھائی عبدالرحمان بن سہل اور (چچا زاد) محیصہ اور حویصہ گئے اور رسول اللہ صلی اللہ علیہ وسلم سے عبداللہ اور ان کو قتل کیے جانے کی صورت حال اور جگہ بتائی۔ بشیر کا خیال ہے اور وہ ان لوگوں سے حدیث بیان کرتے ہیں جنہوں نے رسول اللہ صلی اللہ علیہ وسلم کے اصحاب کو پایا کہ آپ نے ان سے فرمایا: \"کیا تم پچاس قسمیں کھا کر اپنے اتل۔۔ یا اپنے ساتھی۔۔ (سے بدلہ/دیت) کے حق دار بنو گے؟\" انہوں نے کہا: اللہ کے رسول! نہ ہم نے دیکھا، نہ وہاں موجود تھے۔ ان (بشیر) کا خیال ہے کہ آپ نے فرمایا: \"تو یہود پچاس قسمیں کھا کر تمہیں (اپنے دعوے کے استحقاق سے) الگ کر دیں گے۔\" انہوں نے کہا: اے اللہ کے رسول! ہم کافر لوگوں کی قسمیں کیسے قبول کریں؟ بشیر کا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی طرف سے اس کی دیت ادا فرما دی"}],[4337,"ہشیم نے یحییٰ بن سعید سے ، انہوں نے بشیر بن یسار سے روایت کی کہ انصار میں سے بنو حارثہ کا ایک آدمی جسے عبداللہ بن سہل بن زید کہا جاتا تھا اور اس کا چچا زاد بھائی جسے محیصہ بن مسعود بن زید کہا جاتا تھا ، سفر پر روانہ ہوئے ، اور انہوں نے اس قول تک ، لیث کی ( حدیث : 4342 ) کی طرح حدیث بیان کی : \"\" رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس سے اس کی دیت ادا فرما دی ۔ \"\" یحییٰ نے کہا : مجھے بشیر بن یسار نے حدیث بیان کی ، انہوں نے کہا : مجھے سہل بن ابی حثمہ نے خبر دی ، انہوں نے کہا : دیت کی ان اونٹنیوں میں سے ایک اونٹنی نے مجھے باڑے میں لات ماری تھی","",{"u2":"ہشیم نے یحییٰ بن سعید سے، انہوں نے بشیر بن یسار سے روایت کی کہ انصار میں سے بنو حارثہ کا ایک آدمی جسے عبداللہ بن سہل بن زید کہا جاتا تھا اور اس کا چچا زاد بھائی جسے محیصہ بن مسعود بن زید کہا جاتا تھا، سفر پر روانہ ہوئے، اور انہوں نے اس قول تک، لیث کی (حدیث: 4342) کی طرح حدیث بیان کی: \"رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس سے اس کی دیت ادا فرما دی۔\"\nیحییٰ نے کہا: مجھے بشیر بن یسار نے حدیث بیان کی، انہوں نے کہا: مجھے سہل بن ابی حثمہ نے خبر دی، انہوں نے کہا: دیت کی ان اونٹنیوں میں سے ایک اونٹنی نے مجھے باڑے میں لات ماری تھی"}],[4338,"سعید بن عبید نے ہمیں حدیث بیان کی ، ( کہا : ) ہمیں بشیر بن یسار انصاری نے سہل بن ابی حثمہ انصاری سے حدیث بیان کی ، انہوں نے ان کو بتایا کہ ان ( کے خاندان ) میں سے چند لوگ خیبر کی طرف نکلے اور وہاں الگ الگ ہو گئے ، بعد ازاں انہوں نے اپنے ایک آدمی کو قتل کیا ہوا پایا ۔ ۔ اور انہوں نے ( پوری ) حدیث بیان کی اور اس میں کہا : رسول اللہ صلی اللہ علیہ وسلم نے ناپسند کیا کہ اس کے خوب کو رائیگاں قرار دیں ، چنانچہ آپ نے صدقے کے اونٹوں سے سو اونٹ اس کی دیت ادا فرما دی ۔","",{"u2":"سعید بن عبید نے ہمیں حدیث بیان کی، (کہا:) ہمیں بشیر بن یسار انصاری نے سہل بن ابی حثمہ انصاری سے حدیث بیان کی، انہوں نے ان کو بتایا کہ ان (کے خاندان) میں سے چند لوگ خیبر کی طرف نکلے اور وہاں الگ الگ ہو گئے، بعد ازاں انہوں نے اپنے ایک آدمی کو قتل کیا ہوا پایا۔۔ اور انہوں نے (پوری) حدیث بیان کی اور اس میں کہا: رسول اللہ صلی اللہ علیہ وسلم نے ناپسند کیا کہ اس کے خوب کو رائیگاں قرار دیں، چنانچہ آپ نے صدقے کے اونٹوں سے سو اونٹ اس کی دیت ادا فرما دی۔"}],[4339,"ابولیلیٰ بن عبداللہ بن عبدالرحمان بن سہل ( بن زید انصاری ) نے سہل بن ابی حثمہ ( انصاری ) سے حدیث بیان کی ، انہوں نے انہیں ان کی قوم کے بڑی عمر کے لوگوں سے خبر دی کہ عبداللہ بن سہل اور محیصہ اپنی تنگدستی کی بنا پر جو انہیں لاحق ہو گئی تھی ، ( تجارت وغیرہ کے لیے ) خیبر کی طرف نکلے ، بعد ازاں محیصہ آئے اور بتایا کہ عبداللہ بن سہل قتل کر دیے گئے ہیں اور انہیں کسی چشمے یا پانی کے کچے کنویں ( فقیر ) میں پھینک دیا گیا ، چنانچہ وہ یہود کے پاس آئے اور کہا : اللہ کی قسم! تم لوگوں نے ہی انہیں قتل کیا ہے ۔ انہوں نے کہا : اللہ کی قسم! ہم نے انہیں قتل نہیں کیا ، پھر وہ آئے حتی کہ اپنی قوم کے پاس پہنچے اور ان کو یہ بات بتائی ، پھر وہ خود ، ان کے بھائی حویصہ ، اور وہ ان سے بڑے تھے ، اور عبدالرحمان بن سہل ( رسول اللہ صلی اللہ علیہ وسلم کے پاس ) آئے ، محیصہ نے گفتگو شروع کی اور وہی خیبر میں موجود تھے تو رسول اللہ صلی اللہ علیہ وسلم نے محیصہ سے فرمایا : \"\" بڑے کو بات کرنے دو ، بڑے کو موقع دو \"\" آپ کی مراد عمر ( میں بڑے ) سے تھی ، تو حویصہ نے بات کی ، اس کے بعد محیصہ نے بات کی ، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" یا وہ تمہارے ساتھی کی دیت دیں یا پھر جنگ کا اعلان کریں ۔ \"\" رسول اللہ صلی اللہ علیہ وسلم نے اس سلسلے میں ان کی طرف خط لکھا ، تو انہوں نے ( جوابا ) لکھا : اللہ کی قسم! ہم نے انہیں قتل نہیں کیا ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے حویصہ ، محیصہ اور عبدالرحمان سے فرمایا : \"\" کیا تم قسم کھا کر اپنے ساتھی کے خون ( کا بدلہ لینے ) کے حقدار بنو گے؟ \"\" انہوں نے کہا : نہیں ۔ آپ نے پوچھا : \"\" تو تمہارے سامنے یہود قسمیں کھائیں؟ \"\" انہوں نے جواب دیا : وہ مسلمان نہیں ہیں ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس سے اس کی دیت ادا کر دی ، رسول اللہ صلی اللہ علیہ وسلم نے ایک سو اونٹنیاں ان کی طرف روانہ کیں حتی کہ ان کے گھر ( باڑے ) پہنچا دی گئیں ۔ سہل نے کہا : ان میں سے ایک سرخ اونٹنی نے مجھے لات ماری تھی","",{"u2":"ابولیلیٰ بن عبداللہ بن عبدالرحمان بن سہل (بن زید انصاری) نے سہل بن ابی حثمہ (انصاری) سے حدیث بیان کی، انہوں نے انہیں ان کی قوم کے بڑی عمر کے لوگوں سے خبر دی کہ عبداللہ بن سہل اور محیصہ اپنی تنگدستی کی بنا پر جو انہیں لاحق ہو گئی تھی، (تجارت وغیرہ کے لیے) خیبر کی طرف نکلے، بعد ازاں محیصہ آئے اور بتایا کہ عبداللہ بن سہل قتل کر دیے گئے ہیں اور انہیں کسی چشمے یا پانی کے کچے کنویں (فقیر) میں پھینک دیا گیا، چنانچہ وہ یہود کے پاس آئے اور کہا: اللہ کی قسم! تم لوگوں نے ہی انہیں قتل کیا ہے۔ انہوں نے کہا: اللہ کی قسم! ہم نے انہیں قتل نہیں کیا، پھر وہ آئے حتی کہ اپنی قوم کے پاس پہنچے اور ان کو یہ بات بتائی، پھر وہ خود، ان کے بھائی حویصہ، اور وہ ان سے بڑے تھے، اور عبدالرحمان بن سہل (رسول اللہ صلی اللہ علیہ وسلم کے پاس) آئے، محیصہ نے گفتگو شروع کی اور وہی خیبر میں موجود تھے تو رسول اللہ صلی اللہ علیہ وسلم نے محیصہ سے فرمایا: \"بڑے کو بات کرنے دو، بڑے کو موقع دو\" آپ کی مراد عمر (میں بڑے) سے تھی، تو حویصہ نے بات کی، اس کے بعد محیصہ نے بات کی، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یا وہ تمہارے ساتھی کی دیت دیں یا پھر جنگ کا اعلان کریں۔\" رسول اللہ صلی اللہ علیہ وسلم نے اس سلسلے میں ان کی طرف خط لکھا، تو انہوں نے (جوابا) لکھا: اللہ کی قسم! ہم نے انہیں قتل نہیں کیا۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے حویصہ، محیصہ اور عبدالرحمان سے فرمایا: \"کیا تم قسم کھا کر اپنے ساتھی کے خون (کا بدلہ لینے) کے حقدار بنو گے؟\" انہوں نے کہا: نہیں۔ آپ نے پوچھا: \"تو تمہارے سامنے یہود قسمیں کھائیں؟\" انہوں نے جواب دیا: وہ مسلمان نہیں ہیں۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس سے اس کی دیت ادا کر دی، رسول اللہ صلی اللہ علیہ وسلم نے ایک سو اونٹنیاں ان کی طرف روانہ کیں حتی کہ ان کے گھر (باڑے) پہنچا دی گئیں۔\nسہل نے کہا: ان میں سے ایک سرخ اونٹنی نے مجھے لات ماری تھی"}],[4340,"یونس نے ابن شہاب سے خبر دی ، کہا : مجھے ابوسلمہ بن عبدالرحمان اور نبی صلی اللہ علیہ وسلم کی زوجہ محترمہ سیدہ میمونہ رضی اللہ عنہا کے آزاد کردہ غلام سلیمان بن یسار نے انصار میں سے رسول اللہ صلی اللہ علیہ وسلم کے ایک صحابی سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے قسامہ کو اسی صورت پر برقرار رکھا جس پر وہ جاہلیت میں تھی","",{"u2":"یونس نے ابن شہاب سے خبر دی، کہا: مجھے ابوسلمہ بن عبدالرحمان اور نبی صلی اللہ علیہ وسلم کی زوجہ محترمہ سیدہ میمونہ رضی اللہ عنہا کے آزاد کردہ غلام سلیمان بن یسار نے انصار میں سے رسول اللہ صلی اللہ علیہ وسلم کے ایک صحابی سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے قسامہ کو اسی صورت پر برقرار رکھا جس پر وہ جاہلیت میں تھی"}],[4341,"ابن جریج نے ابن شہاب سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی اور یہ اضافہ کیا : رسول اللہ صلی اللہ علیہ وسلم نے اس ( قسامہ ) کے ذریعے انصار کے لوگوں کے مابین ایک مقتول کا فیصلہ کیا جس کا دعویٰ انہوں نے یہود پر کیا تھا","",{"u2":"ابن جریج نے ابن شہاب سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی اور یہ اضافہ کیا: رسول اللہ صلی اللہ علیہ وسلم نے اس (قسامہ) کے ذریعے انصار کے لوگوں کے مابین ایک مقتول کا فیصلہ کیا جس کا دعویٰ انہوں نے یہود پر کیا تھا"}],[4342,"صالح نے ابن شہاب سے روایت کی کہ انہیں ابوسلمہ بن عبدالرحمان اور سلیمان بن یسار نے انصار کے کچھ لوگوں سے خبر دی اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی جس طرح ابن جریج کی حدیث ہے","",{"u2":"صالح نے ابن شہاب سے روایت کی کہ انہیں ابوسلمہ بن عبدالرحمان اور سلیمان بن یسار نے انصار کے کچھ لوگوں سے خبر دی اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی جس طرح ابن جریج کی حدیث ہے"}],[4343,"عبدالعزیز بن صہیب اور حمید نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ عرینہ کے کچھ لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس مدینہ آئے ، انہیں یہاں کی آب و ہوا نا موافق لگی ( اور انہیں استسقاء ہو گیا ) تو رسول اللہ صلی اللہ علیہ وسلم نے ان ( کے مطالبے پر ان سے ) فرمایا : \" اگر تم چاہتے ہو تو صدقے کے اونٹوں کے پاس چلے جاؤ اور ان کے دودھ اور پیشاب ( جسے وہ لوگ ، اس طرح کی کیفیت میں اپنی صحت کا ) ضامن سمجھتے تھے ) پیو ۔ انہوں نے ایسے ہی کیا اور صحت یاب ہو گئے ، پھر انہوں نے چرواہوں پر حملہ کر دیا ، ان کو قتل کر دیا ، اسلام سے مرتد ہو گئے اور رسول اللہ صلی اللہ علیہ وسلم کے ( بیت المال کے ) اونٹ ہانک کر لے گئے ۔ نبی صلی اللہ علیہ وسلم کو یہ بات پہنچی تو آپ نے ( کچھ لوگوں کو ) ان کے تعاقب میں روانہ کیا ، انہیں ( پکڑ کر ) لایا گیا تو آپ نے ان کے ہاتھ اور پاؤں کٹوا دیے ، ان کی آنکھیں پھوڑ دینے کا حکم دیا اور انہیں سیاہ پتھروں والی زمین میں چھوڑ دیا حتی کہ ( وہیں ) مر گئے","",{"u2":"عبدالعزیز بن صہیب اور حمید نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ عرینہ کے کچھ لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس مدینہ آئے، انہیں یہاں کی آب و ہوا نا موافق لگی (اور انہیں استسقاء ہو گیا) تو رسول اللہ صلی اللہ علیہ وسلم نے ان (کے مطالبے پر ان سے) فرمایا: \"اگر تم چاہتے ہو تو صدقے کے اونٹوں کے پاس چلے جاؤ اور ان کے دودھ اور پیشاب (جسے وہ لوگ، اس طرح کی کیفیت میں اپنی صحت کا) ضامن سمجھتے تھے) پیو۔ انہوں نے ایسے ہی کیا اور صحت یاب ہو گئے، پھر انہوں نے چرواہوں پر حملہ کر دیا، ان کو قتل کر دیا، اسلام سے مرتد ہو گئے اور رسول اللہ صلی اللہ علیہ وسلم کے (بیت المال کے) اونٹ ہانک کر لے گئے۔ نبی صلی اللہ علیہ وسلم کو یہ بات پہنچی تو آپ نے (کچھ لوگوں کو) ان کے تعاقب میں روانہ کیا، انہیں (پکڑ کر) لایا گیا تو آپ نے ان کے ہاتھ اور پاؤں کٹوا دیے، ان کی آنکھیں پھوڑ دینے کا حکم دیا اور انہیں سیاہ پتھروں والی زمین میں چھوڑ دیا حتی کہ (وہیں) مر گئے"}],[4344,"ابوجعفر محمد بن صباح اور ابوبکر بن ابی شیبہ نے ہمیں حدیث بیان کی ، الفاظ ابوبکر کے ہیں ، کہا : ہمیں ابن علیہ نے حجاج بن ابی عثمان سے حدیث بیان کی ، کہا : مجھے ابو رجاء مولیٰ ابی قلابہ نے ابو قلابہ سے حدیث بیان کی ، کہا : مجھے سیدنا انس رضی اللہ عنہ نے حدیث بیان کی کہ عُکل ( اور عرینہ ) کے آٹھ افراد رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے اسلام پر بیعت کی ، انہوں نے اس سرزمین کی آب و ہوا کو ناموافق پایا اور ان کے جسم کمزور ہو گئے ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اس بات کی شکایت کی تو آپ نے فرمایا : \"\" تم ہمارے چرواہے کے ساتھ ( جو رسول اللہ صلی اللہ علیہ وسلم کے اونٹ لے کر اسی مشترکہ چراگاہ کی طرف جا رہا تھا جہاں بیت المال کے اونٹ بھی چرتے تھے : فتح الباری : 1/338 ) اونٹوں میں کیوں نہیں چلے جاتے تاکہ ان کا پیشاب اور دودھ پیو؟ \"\" انہوں نے کہا : کیوں نہیں! چنانچہ وہ نکلے ، ان کا پیشاب اور دودھ پیا اور صحت یاب ہو گئے ، پھر انہوں نے ( رسول اللہ صلی اللہ علیہ وسلم کے ) چرواہے کو قتل کیا اور اونٹ بھی بھگا لے گئے ، رسول اللہ صلی اللہ علیہ وسلم کو یہ خبر پہنچی تو آپ نے ان کے پیچھے ( ایک دستہ ) روانہ کیا ، انہیں پکڑ لیا گیا اور ( مدینہ میں ) لایا گیا تو آپ نے ان کے بارے میں ( قرآن کی سزا پر عمل کرتے ہوئے ) حکم دیا ، اس پر ان کے ہاتھ پاؤں کاٹ دیے گئے ، ان کی آنکھیں گرم سلاخوں سے پھوڑ دی گئیں ، پھر انہیں دھوپ میں پھینک دیا گیا حتی کہ وہ مر گئے ۔ ابن صباح نے اپنی روایت میں ( کے بجائے ) اور ( کے بجائے ) کے الفاظ کہے ( معنی وہی ہے ۔)","",{"u2":"ابوجعفر محمد بن صباح اور ابوبکر بن ابی شیبہ نے ہمیں حدیث بیان کی، الفاظ ابوبکر کے ہیں، کہا: ہمیں ابن علیہ نے حجاج بن ابی عثمان سے حدیث بیان کی، کہا: مجھے ابو رجاء مولیٰ ابی قلابہ نے ابو قلابہ سے حدیث بیان کی، کہا: مجھے سیدنا انس رضی اللہ عنہ نے حدیث بیان کی کہ عُکل (اور عرینہ) کے آٹھ افراد رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے اسلام پر بیعت کی، انہوں نے اس سرزمین کی آب و ہوا کو ناموافق پایا اور ان کے جسم کمزور ہو گئے، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اس بات کی شکایت کی تو آپ نے فرمایا: \"تم ہمارے چرواہے کے ساتھ (جو رسول اللہ صلی اللہ علیہ وسلم کے اونٹ لے کر اسی مشترکہ چراگاہ کی طرف جا رہا تھا جہاں بیت المال کے اونٹ بھی چرتے تھے: فتح الباری: 1/338) اونٹوں میں کیوں نہیں چلے جاتے تاکہ ان کا پیشاب اور دودھ پیو؟\" انہوں نے کہا: کیوں نہیں! چنانچہ وہ نکلے، ان کا پیشاب اور دودھ پیا اور صحت یاب ہو گئے، پھر انہوں نے (رسول اللہ صلی اللہ علیہ وسلم کے) چرواہے کو قتل کیا اور اونٹ بھی بھگا لے گئے، رسول اللہ صلی اللہ علیہ وسلم کو یہ خبر پہنچی تو آپ نے ان کے پیچھے (ایک دستہ) روانہ کیا، انہیں پکڑ لیا گیا اور (مدینہ میں) لایا گیا تو آپ نے ان کے بارے میں (قرآن کی سزا پر عمل کرتے ہوئے) حکم دیا، اس پر ان کے ہاتھ پاؤں کاٹ دیے گئے، ان کی آنکھیں گرم سلاخوں سے پھوڑ دی گئیں، پھر انہیں دھوپ میں پھینک دیا گیا حتی کہ وہ مر گئے۔\nابن صباح نے اپنی روایت میں (کے بجائے) اور (کے بجائے) کے الفاظ کہے (معنی وہی ہے۔)"}],[4345,"ایوب نے ابوقلابہ کے آزاد کردہ غلام ابو رجاء سے روایت کی ، کہا : ابوقلابہ نے کہا : ہمیں سیدنا انس بن مالک رضی اللہ عنہ نے حدیث بیان کی ، انہوں نے کہا : عُکل یا عرینہ کے کچھ لوگ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور مدینہ میں انہیں استسقاء کی بیماری لاحق ہو گئی ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں دودھ والی اونٹنیوں کا حکم دیا ( کہ ان کے لیے خاص کر دی جائیں ) اور ان سے کہا کہ ان کے پیشاب اور دودھ پئیں ۔ ۔ ۔ آگے حجاج بن ابی عثمان کی حدیث کے ہم معنی ہے ۔ اور کہا : ان کی آنکھیں گرم سلاخوں سے پھوڑ دی گئیں اور انہیں سیاہ پتھروں والی زمین ( حرہ ) میں پھینک دیا گیا ، وہ پانی مانگتے تھے تو انہیں نہیں پلایا جاتا تھا","",{"u2":"ایوب نے ابوقلابہ کے آزاد کردہ غلام ابو رجاء سے روایت کی، کہا: ابوقلابہ نے کہا: ہمیں سیدنا انس بن مالک رضی اللہ عنہ نے حدیث بیان کی، انہوں نے کہا: عُکل یا عرینہ کے کچھ لوگ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور مدینہ میں انہیں استسقاء کی بیماری لاحق ہو گئی۔ تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں دودھ والی اونٹنیوں کا حکم دیا (کہ ان کے لیے خاص کر دی جائیں) اور ان سے کہا کہ ان کے پیشاب اور دودھ پئیں۔۔۔ آگے حجاج بن ابی عثمان کی حدیث کے ہم معنی ہے۔\nاور کہا: ان کی آنکھیں گرم سلاخوں سے پھوڑ دی گئیں اور انہیں سیاہ پتھروں والی زمین (حرہ) میں پھینک دیا گیا، وہ پانی مانگتے تھے تو انہیں نہیں پلایا جاتا تھا"}],[4346,"ابن عون نے کہا : ہمیں ابو رجاء مولیٰ ابی قلابہ نے ابوقلابہ سے حدیث بیان کی ، انہوں نے کہا : میں عمر بن عبدالعزیز کے پیچھے بیٹھا تھا تو انہوں نے لوگوں سے کہا : تم قسامہ کے بارے میں کیا کہتے ہو؟ عنبسہ نے کہا : ہمیں سیدنا انس بن مالک رضی اللہ عنہ نے اس اس طرح حدیث بیان کی ہے ۔ اس پر میں نے کہا : مجھے بھی سیدنا انس رضی اللہ عنہ نے حدیث بیان کی کہ کچھ لوگ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے ۔ ۔ اور انہوں نے ایوب اور حجاج کی حدیث کی طرح حدیث بیان کی ۔ ابوقلابہ نے کہا : جب میں فارغ ہوا تو عنبسہ نے سبحان اللہ کہا ( تعجب کا اظہار کیا ۔ ) ابوقلابہ نے کہا : اس پر میں نے کہا : اے عنبسہ! کیا تم مجھ پر ( جھوٹ بولنے کا ) الزام لگاتے ہو؟ انہوں نے کہا : نہیں ، ہمیں بھی سیدنا انس بن مالک رضی اللہ عنہ نے اسی طرح حدیث بیان کی ہے ۔ اے اہل شام! جب تم تم میں یہ یا ان جیسے لوگ موجود ہیں ، تم ہمیشہ بھلائی سے رہو گے ۔","",{"u2":"ابن عون نے کہا: ہمیں ابو رجاء مولیٰ ابی قلابہ نے ابوقلابہ سے حدیث بیان کی، انہوں نے کہا: میں عمر بن عبدالعزیز کے پیچھے بیٹھا تھا تو انہوں نے لوگوں سے کہا: تم قسامہ کے بارے میں کیا کہتے ہو؟ عنبسہ نے کہا: ہمیں سیدنا انس بن مالک رضی اللہ عنہ نے اس اس طرح حدیث بیان کی ہے۔ اس پر میں نے کہا: مجھے بھی سیدنا انس رضی اللہ عنہ نے حدیث بیان کی کہ کچھ لوگ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔۔ اور انہوں نے ایوب اور حجاج کی حدیث کی طرح حدیث بیان کی۔ ابوقلابہ نے کہا: جب میں فارغ ہوا تو عنبسہ نے سبحان اللہ کہا (تعجب کا اظہار کیا۔) ابوقلابہ نے کہا: اس پر میں نے کہا: اے عنبسہ! کیا تم مجھ پر (جھوٹ بولنے کا) الزام لگاتے ہو؟ انہوں نے کہا: نہیں، ہمیں بھی سیدنا انس بن مالک رضی اللہ عنہ نے اسی طرح حدیث بیان کی ہے۔ اے اہل شام! جب تم تم میں یہ یا ان جیسے لوگ موجود ہیں، تم ہمیشہ بھلائی سے رہو گے۔"}],[4347,"یحییٰ بن ابی کثیر نے ابو قلابہ سے اور انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ( قبیلہ ) عُکل کے آٹھ افراد رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے ۔ ۔ آگے انہی کی حدیث کی طرح ہے اور انہوں نے حدیث میں یہ الفاظ زائد بیان کیے : اور آپ نے ( خون روکنے کے لیے ) انہیں داغ نہیں دیا ۔ ( اس طرح وہ جلدی موت کے منہ میں چلے گئے)","",{"u2":"یحییٰ بن ابی کثیر نے ابو قلابہ سے اور انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی، انہوں نے کہا: (قبیلہ) عُکل کے آٹھ افراد رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔۔ آگے انہی کی حدیث کی طرح ہے اور انہوں نے حدیث میں یہ الفاظ زائد بیان کیے: اور آپ نے (خون روکنے کے لیے) انہیں داغ نہیں دیا۔ (اس طرح وہ جلدی موت کے منہ میں چلے گئے"}],[4348,"معاویہ بن قرہ نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : عرینہ کے کچھ افراد رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے ، وہ مسلمان ہوئے اور آپ کی بیعت کی اور مدینہ میں موم ۔ ۔ جو برسام ( پھیپڑوں کی جھلی کی سوزش کا دوسرا نام ) ہے ۔ ۔ کی وبا پھیلی ہوئی تھی ، پھر انہی کی حدیث کی طرح بیان کیا اور مزید کہا : آپ کے پاس انصار کے تقریبا بیس نوجوان حاضر تھے ، آپ نے انہیں ان کی طرف روانہ کیا اور آپ نے ان کے ساتھ ایک کھوجی بھی روانہ کیا جو ان کے پاؤں کے نقوش کی نشاندہی کرتا تھا","",{"u2":"معاویہ بن قرہ نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی، انہوں نے کہا: عرینہ کے کچھ افراد رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، وہ مسلمان ہوئے اور آپ کی بیعت کی اور مدینہ میں موم۔۔ جو برسام (پھیپڑوں کی جھلی کی سوزش کا دوسرا نام) ہے۔۔ کی وبا پھیلی ہوئی تھی، پھر انہی کی حدیث کی طرح بیان کیا اور مزید کہا: آپ کے پاس انصار کے تقریبا بیس نوجوان حاضر تھے، آپ نے انہیں ان کی طرف روانہ کیا اور آپ نے ان کے ساتھ ایک کھوجی بھی روانہ کیا جو ان کے پاؤں کے نقوش کی نشاندہی کرتا تھا"}],[4349,"ہمام اور سعید نے قتادہ کے حوالے سے سیدنا انس رضی اللہ عنہ سے روایت کی ، ہمام کی حدیث میں ہے : عُرینہ کا ایک گروہ نبی صلی اللہ علیہ وسلم کے پاس آیا اور سعید کی حدیث میں ہے : عُکل اور عرینہ کا ( گروہ آیا ) ۔ ۔ آگے انہی کی حدیث کی طرح ہے"],[4350,"ہمام اور سعید نے قتادہ کے حوالے سے سیدنا انس رضی اللہ عنہ سے روایت کی ، ہمام کی حدیث میں ہے : عُرینہ کا ایک گروہ نبی صلی اللہ علیہ وسلم کے پاس آیا اور سعید کی حدیث میں ہے : عُکل اور عرینہ کا ( گروہ آیا ) ۔ ۔ آگے انہی کی حدیث کی طرح ہے","",{"u2":"ہمام اور سعید نے قتادہ کے حوالے سے سیدنا انس رضی اللہ عنہ سے روایت کی، ہمام کی حدیث میں ہے: عُرینہ کا ایک گروہ نبی صلی اللہ علیہ وسلم کے پاس آیا اور سعید کی حدیث میں ہے: عُکل اور عرینہ کا (گروہ آیا)۔۔ آگے انہی کی حدیث کی طرح ہے"}]]);
